def _new_id12() -> str:
    return uuid.uuid4().hex[:12]


def _normalize_mode_profile(raw: dict | None, *, default: dict | None = None) -> dict:
    base = dict(default or _BUILTIN_MODE_PROFILES[0])
    if not isinstance(raw, dict):
        return _normalize_zone_entry(base, base)
    out = _normalize_zone_entry(raw, base)
    pid = str(raw.get("id") or base.get("id") or _new_id12()).strip() or _new_id12()
    name = str(raw.get("name") or base.get("name") or "Profile").strip() or "Profile"
    if len(name) > 64:
        name = name[:64]
    name_ru = str(raw.get("name_ru") or raw.get("name") or name).strip() or name
    if len(name_ru) > 64:
        name_ru = name_ru[:64]
    color = str(raw.get("color") or base.get("color") or "#64748b").strip()
    if not color.startswith("#") or len(color) not in (4, 7):
        color = "#64748b"
    builtin = bool(raw.get("builtin") if "builtin" in raw else base.get("builtin", False))
    return {
        "id": pid,
        "name": name,
        "name_ru": name_ru,
        "color": color,
        "builtin": builtin,
        "mode_en": bool(out.get("mode_en")),
        "mode": out.get("mode") or "low",
        "work_en": bool(out.get("work_en")),
        "work": out.get("work") or "resume",
        "lim_en": bool(out.get("lim_en")),
        "lim": float(out.get("lim") or 0),
        "pct_en": bool(out.get("pct_en")),
        "pct": float(out.get("pct") or 0),
        "updated_ts": raw.get("updated_ts")
        or base.get("updated_ts")
        or datetime.now().isoformat(timespec="seconds"),
    }


def _mode_profile_summary(p: dict) -> str:
    parts: list[str] = []
    if p.get("work_en"):
        parts.append(str(p.get("work") or "resume"))
    if p.get("mode_en"):
        parts.append(str(p.get("mode") or "low"))
    if p.get("lim_en"):
        try:
            parts.append(f"{int(float(p.get('lim') or 0))}W")
        except (TypeError, ValueError):
            parts.append("lim")
    if p.get("pct_en"):
        try:
            parts.append(f"{int(float(p.get('pct') or 0))}%")
        except (TypeError, ValueError):
            parts.append("pct")
    return " · ".join(parts) if parts else "—"


def _load_mode_profiles() -> None:
    global _mode_profiles
    with _mode_profiles_lock:
        raw = _load_json(MODE_PROFILES_FILE, {"profiles": []})
        if not isinstance(raw, dict):
            raw = {"profiles": []}
        items = raw.get("profiles") if isinstance(raw.get("profiles"), list) else []
        by_id: dict[str, dict] = {}
        for p in items:
            if not isinstance(p, dict):
                continue
            np = _normalize_mode_profile(p)
            by_id[np["id"]] = np
        # ensure builtins exist (user may override non-id fields if same id)
        for b in _BUILTIN_MODE_PROFILES:
            if b["id"] not in by_id:
                by_id[b["id"]] = _normalize_mode_profile(b)
            else:
                # keep user edits but force builtin flag for known ids
                cur = by_id[b["id"]]
                cur["builtin"] = True
                by_id[b["id"]] = cur
        # stable order: builtins first in template order, then custom
        ordered: list[dict] = []
        seen: set[str] = set()
        for b in _BUILTIN_MODE_PROFILES:
            if b["id"] in by_id:
                ordered.append(by_id[b["id"]])
                seen.add(b["id"])
        for pid, p in by_id.items():
            if pid not in seen:
                ordered.append(p)
        _mode_profiles = {"profiles": ordered}
        try:
            _save_json(MODE_PROFILES_FILE, _mode_profiles)
        except Exception:
            pass


def _save_mode_profiles() -> None:
    with _mode_profiles_lock:
        _save_json(MODE_PROFILES_FILE, _mode_profiles)


def list_mode_profiles() -> dict:
    with _mode_profiles_lock:
        items = []
        for p in _mode_profiles.get("profiles") or []:
            items.append(
                {
                    **p,
                    "summary": _mode_profile_summary(p),
                }
            )
        return {"ok": True, "profiles": items}


def get_mode_profile(profile_id: str) -> dict | None:
    pid = str(profile_id or "").strip()
    if not pid:
        return None
    with _mode_profiles_lock:
        for p in _mode_profiles.get("profiles") or []:
            if p.get("id") == pid:
                return json.loads(json.dumps(p))
    return None


def save_mode_profile(
    data: dict,
    *,
    profile_id: str | None = None,
) -> dict:
    if not isinstance(data, dict):
        raise ValueError("expected object")
    pid = str(profile_id or data.get("id") or "").strip()
    now = datetime.now().isoformat(timespec="seconds")
    with _mode_profiles_lock:
        profiles = list(_mode_profiles.get("profiles") or [])
        existing = None
        idx = -1
        if pid:
            for i, p in enumerate(profiles):
                if p.get("id") == pid:
                    existing = p
                    idx = i
                    break
        if existing:
            merged = dict(existing)
            merged.update(data)
            merged["id"] = pid
            merged["builtin"] = bool(existing.get("builtin"))
            merged["updated_ts"] = now
            np = _normalize_mode_profile(merged, default=existing)
            profiles[idx] = np
            out_id = pid
        else:
            if not pid:
                pid = _new_id12()
            data = dict(data)
            data["id"] = pid
            data["builtin"] = False
            data["updated_ts"] = now
            np = _normalize_mode_profile(data)
            np["builtin"] = False
            profiles.append(np)
            out_id = pid
        _mode_profiles["profiles"] = profiles
    _save_mode_profiles()
    return {"ok": True, "id": out_id, **list_mode_profiles()}


def delete_mode_profile(profile_id: str) -> dict:
    pid = str(profile_id or "").strip()
    if not pid:
        raise ValueError("id empty")
    with _mode_profiles_lock:
        profiles = list(_mode_profiles.get("profiles") or [])
        found = None
        for p in profiles:
            if p.get("id") == pid:
                found = p
                break
        if not found:
            raise ValueError(f"profile not found: {pid}")
        if found.get("builtin"):
            raise ValueError("cannot delete built-in profile")
        _mode_profiles["profiles"] = [p for p in profiles if p.get("id") != pid]
    _save_mode_profiles()
    return list_mode_profiles()


def apply_mode_profile(profile_id: str, *, password: str | None = None) -> dict:
    """Manual apply profile commands to ASIC (always real write; dry_run is policy-only)."""
    p = get_mode_profile(profile_id)
    if not p:
        raise ValueError(f"profile not found: {profile_id}")
    cmds = _zone_entry_commands(p)
    if not cmds:
        return {"ok": True, "id": p.get("id"), "applied": [], "skipped": True}
    pw = password if password is not None else DEFAULT_API_PASSWORD
    results = []
    for action, value in cmds:
        try:
            out = apply_set(action, value, pw)
            results.append({"action": action, "value": value, "ok": bool(out.get("ok")), "out": out})
        except Exception as e:
            results.append({"action": action, "value": value, "ok": False, "error": str(e)})
    ok = all(r.get("ok") for r in results) if results else True
    _policy_log(
        "ok" if ok else "warn",
        f"MODE_PROFILE apply {p.get('name') or p.get('id')}: "
        + ", ".join(f"{r['action']}={r['value']}" for r in results),
        source="mode_profile",
    )
    return {
        "ok": ok,
        "id": p.get("id"),
        "name": p.get("name"),
        "applied": results,
    }


# ── Schedule (time map: inactive | mode profile | map preset) ───────────────
_schedule_lock = threading.Lock()
_DEFAULT_SCHEDULE: dict = {
    "version": 1,
    "enabled": False,
    "timezone": "Europe/Moscow",
    "resolution_min": 60,
    "default_cell": {"t": "inactive"},
    "weekly": {d: [{"t": "inactive"}] * 24 for d in _DOW_KEYS},
    "exceptions": [],
}


def _normalize_schedule_cell(raw) -> dict:
    """Cell: {t: inactive|profile|preset|like, id?, like_dow?}."""
    if raw is None:
        return {"t": "inactive"}
    if isinstance(raw, str):
        s = raw.strip().lower()
        if s in ("inactive", "off", "block", "0"):
            return {"t": "inactive"}
        if s.startswith("profile:"):
            return {"t": "profile", "id": s.split(":", 1)[1].strip()}
        if s.startswith("preset:"):
            return {"t": "preset", "id": s.split(":", 1)[1].strip()}
        return {"t": "inactive"}
    if not isinstance(raw, dict):
        return {"t": "inactive"}
    t = str(raw.get("t") or raw.get("type") or "inactive").strip().lower()
    if t in ("off", "block", "none", "disabled"):
        t = "inactive"
    if t not in ("inactive", "profile", "preset", "like"):
        t = "inactive"
    out: dict = {"t": t}
    if t in ("profile", "preset"):
        cid = str(raw.get("id") or "").strip()
        if not cid:
            return {"t": "inactive"}
        out["id"] = cid
    if t == "like":
        ld = str(raw.get("like_dow") or raw.get("dow") or "sun").strip().lower()[:3]
        # accept mon/tue/... or monday
        for k in _DOW_KEYS:
            if ld.startswith(k[:3]) or k.startswith(ld):
                out["like_dow"] = k
                break
        else:
            out["like_dow"] = "sun"
    return out


def _normalize_day_hours(raw) -> list[dict]:
    """24 cells (hour 0..23)."""
    cells = [{"t": "inactive"}] * 24
    if isinstance(raw, list) and raw:
        for i in range(24):
            if i < len(raw):
                cells[i] = _normalize_schedule_cell(raw[i])
            else:
                cells[i] = _normalize_schedule_cell(raw[-1])
    elif isinstance(raw, dict):
        # allow {"0": {...}, "7": ...}
        for i in range(24):
            if str(i) in raw:
                cells[i] = _normalize_schedule_cell(raw[str(i)])
            elif i in raw:
                cells[i] = _normalize_schedule_cell(raw[i])
    return cells


def _normalize_schedule_cfg(raw: dict | None) -> dict:
    base = json.loads(json.dumps(_DEFAULT_SCHEDULE))
    if not isinstance(raw, dict):
        return base
    base["enabled"] = bool(raw.get("enabled", False))
    tz = str(raw.get("timezone") or base["timezone"]).strip() or "Europe/Moscow"
    base["timezone"] = tz
    try:
        res = int(raw.get("resolution_min") or 60)
    except (TypeError, ValueError):
        res = 60
    base["resolution_min"] = 60 if res >= 60 else max(15, res)
    base["default_cell"] = _normalize_schedule_cell(
        raw.get("default_cell") or raw.get("default") or {"t": "inactive"}
    )
    weekly_in = raw.get("weekly") if isinstance(raw.get("weekly"), dict) else {}
    weekly: dict = {}
    for d in _DOW_KEYS:
        weekly[d] = _normalize_day_hours(weekly_in.get(d))
    base["weekly"] = weekly
    ex_in = raw.get("exceptions") if isinstance(raw.get("exceptions"), list) else []
    exceptions: list[dict] = []
    for ex in ex_in:
        if not isinstance(ex, dict):
            continue
        date = str(ex.get("date") or "").strip()
        if not date or len(date) < 8:
            continue
        # YYYY-MM-DD
        if len(date) > 10:
            date = date[:10]
        mode = str(ex.get("mode") or ex.get("t") or "like").strip().lower()
        item: dict = {
            "id": str(ex.get("id") or _new_id12()).strip() or _new_id12(),
            "date": date,
            "note": str(ex.get("note") or "")[:80],
        }
        if mode in ("like", "as"):
            item["t"] = "like"
            ld = str(ex.get("like_dow") or "sun").strip().lower()[:3]
            item["like_dow"] = next(
                (k for k in _DOW_KEYS if k.startswith(ld) or ld.startswith(k[:3])),
                "sun",
            )
        elif mode in ("inactive", "off", "block"):
            item["t"] = "inactive"
        elif mode == "profile":
            item["t"] = "profile"
            item["id_ref"] = str(ex.get("id_ref") or ex.get("profile_id") or ex.get("ref") or "").strip()
            if not item["id_ref"]:
                continue
        elif mode == "preset":
            item["t"] = "preset"
            item["id_ref"] = str(ex.get("id_ref") or ex.get("preset_id") or ex.get("ref") or "").strip()
            if not item["id_ref"]:
                continue
        elif mode == "custom":
            item["t"] = "custom"
            item["hours"] = _normalize_day_hours(ex.get("hours") or ex.get("day"))
        else:
            # full cell in exception
            cell = _normalize_schedule_cell(ex)
            item["t"] = cell.get("t") or "inactive"
            if cell.get("id"):
                item["id_ref"] = cell["id"]
            if cell.get("like_dow"):
                item["like_dow"] = cell["like_dow"]
        exceptions.append(item)
    # sort by date
    exceptions.sort(key=lambda x: x.get("date") or "")
    base["exceptions"] = exceptions
    base["version"] = 1
    return base


_schedule_cfg: dict = {}


def _load_schedule_cfg() -> None:
    global _schedule_cfg
    with _schedule_lock:
        raw = _load_json(SCHEDULE_CFG_FILE, _DEFAULT_SCHEDULE)
        _schedule_cfg = _normalize_schedule_cfg(raw if isinstance(raw, dict) else None)
        try:
            _save_json(SCHEDULE_CFG_FILE, _schedule_cfg)
        except Exception:
            pass


def _save_schedule_cfg() -> None:
    with _schedule_lock:
        _save_json(SCHEDULE_CFG_FILE, _schedule_cfg)


def get_schedule_cfg() -> dict:
    with _schedule_lock:
        return json.loads(json.dumps(_schedule_cfg))


def set_schedule_cfg(raw: dict) -> dict:
    global _schedule_cfg
    cfg = _normalize_schedule_cfg(raw if isinstance(raw, dict) else None)
    with _schedule_lock:
        _schedule_cfg = cfg
    _save_schedule_cfg()
    return get_schedule_cfg()


def _schedule_now(tz_name: str | None = None):
    """Return timezone-aware datetime now for schedule resolution."""
    name = (tz_name or "Europe/Moscow").strip() or "Europe/Moscow"
    try:
        from zoneinfo import ZoneInfo  # py3.9+

        return datetime.now(ZoneInfo(name))
    except Exception:
        try:
            # fallback: local wall clock
            return datetime.now().astimezone()
        except Exception:
            return datetime.now()


def _cell_key(cell: dict | None) -> str:
    if not isinstance(cell, dict):
        return "inactive"
    t = str(cell.get("t") or "inactive")
    if t in ("profile", "preset") and cell.get("id"):
        return f"{t}:{cell.get('id')}"
    if t == "like":
        return f"like:{cell.get('like_dow') or 'sun'}"
    return t


def _cell_label(cell: dict | None) -> str:
    if not isinstance(cell, dict):
        return "inactive"
    t = str(cell.get("t") or "inactive")
    if t == "inactive":
        return "inactive"
    if t == "profile":
        p = get_mode_profile(str(cell.get("id") or ""))
        return f"profile · {(p or {}).get('name') or cell.get('id') or '?'}"
    if t == "preset":
        p = get_zone_preset(str(cell.get("id") or ""))
        return f"preset · {(p or {}).get('name') or cell.get('id') or '?'}"
    if t == "like":
        return f"like · {cell.get('like_dow') or 'sun'}"
    return t


def _hours_until_change(day_cells: list, hour: int) -> int:
    """Hours until cell key changes from current hour (1..24)."""
    if not day_cells or hour < 0 or hour > 23:
        return 1
    cur = _cell_key(day_cells[hour] if hour < len(day_cells) else None)
    n = 1
    h = hour + 1
    while h < 24:
        k = _cell_key(day_cells[h] if h < len(day_cells) else None)
        if k != cur:
            break
        n += 1
        h += 1
    return n


def resolve_schedule_at(dt: datetime | None = None) -> dict:
    """
    Resolve schedule cell for a wall-clock moment.
    Returns: enabled, active, cell, key, label, dow, hour, date, source,
             until_ts, exception
    """
    cfg = get_schedule_cfg()
    now = dt or _schedule_now(cfg.get("timezone"))
    dow = _DOW_FROM_PY.get(int(now.weekday()), "mon")
    hour = int(now.hour)
    date_s = now.strftime("%Y-%m-%d")
    out: dict = {
        "ok": True,
        "enabled": bool(cfg.get("enabled")),
        "timezone": cfg.get("timezone"),
        "date": date_s,
        "dow": dow,
        "hour": hour,
        "active": False,
        "cell": {"t": "inactive"},
        "key": "inactive",
        "label": "inactive",
        "source": "disabled",
        "until_ts": None,
        "exception": None,
    }
    if not cfg.get("enabled"):
        return out

    weekly = cfg.get("weekly") or {}
    day_cells = list(weekly.get(dow) or [{"t": "inactive"}] * 24)
    source = "weekly"
    ex_hit = None

    for ex in cfg.get("exceptions") or []:
        if not isinstance(ex, dict):
            continue
        if str(ex.get("date") or "") != date_s:
            continue
        ex_hit = ex
        et = str(ex.get("t") or "like")
        if et == "like":
            ld = str(ex.get("like_dow") or "sun")
            day_cells = list(weekly.get(ld) or day_cells)
            source = f"exception:like:{ld}"
        elif et == "inactive":
            day_cells = [{"t": "inactive"}] * 24
            source = "exception:inactive"
        elif et == "profile":
            day_cells = [{"t": "profile", "id": ex.get("id_ref")}] * 24
            source = "exception:profile"
        elif et == "preset":
            day_cells = [{"t": "preset", "id": ex.get("id_ref")}] * 24
            source = "exception:preset"
        elif et == "custom":
            day_cells = list(ex.get("hours") or day_cells)
            source = "exception:custom"
        break

    cell = _normalize_schedule_cell(
        day_cells[hour] if hour < len(day_cells) else cfg.get("default_cell")
    )
    # resolve nested like in cell (rare)
    if cell.get("t") == "like":
        ld = str(cell.get("like_dow") or "sun")
        alt = (weekly.get(ld) or day_cells)
        cell = _normalize_schedule_cell(alt[hour] if hour < len(alt) else cell)
        source = source + f"+like:{ld}"

    hours_left = _hours_until_change(day_cells, hour)
    # until next hour boundary * hours_left
    try:
        until = now.replace(minute=0, second=0, microsecond=0)
        from datetime import timedelta

        until = until + timedelta(hours=hours_left)
        until_ts = until.timestamp()
    except Exception:
        until_ts = None

    out.update(
        {
            "active": True,
            "cell": cell,
            "key": _cell_key(cell),
            "label": _cell_label(cell),
            "source": source,
            "until_ts": until_ts,
            "exception": ex_hit,
            "day_cells": day_cells,  # for UI preview of today
        }
    )
    return out


def get_schedule_status() -> dict:
    """Public status for UI / policy."""
    r = resolve_schedule_at()
    # drop heavy day_cells in light status unless needed
    light = {k: v for k, v in r.items() if k != "day_cells"}
    with _policy_lock:
        light["policy_key"] = _policy_ctrl.get("schedule_key")
        light["policy_label"] = _policy_ctrl.get("schedule_label")
    return light


# ── Mining pool presets (named url/user/pass snapshots) ─────────────────────
_pool_presets_lock = threading.Lock()
_pool_presets: dict = {"presets": [], "active_id": None}


def _normalize_pool_preset_pools(pools) -> list[dict]:
    """1–3 pool entries {url, user, pass} for write/update_pools."""
    out: list[dict] = []
    raw = pools if isinstance(pools, list) else []
    for p in raw[:3]:
        if not isinstance(p, dict):
            continue
        out.append(
            {
                "url": str(p.get("url") or p.get("URL") or "").strip(),
                "user": str(
                    p.get("user") or p.get("User") or p.get("worker") or ""
                ).strip(),
                "pass": str(
                    p.get("pass")
                    or p.get("password")
                    or p.get("Pass")
                    or "x"
                ),
            }
        )
    while len(out) < 3:
        out.append({"url": "", "user": "", "pass": "x"})
    # drop trailing empties but keep at least one slot for UI
    while len(out) > 1 and not out[-1].get("url") and not out[-1].get("user"):
        out.pop()
    if not any(x.get("url") for x in out):
        raise ValueError("at least one pool url required")
    return out


def _pool_preset_summary(pools: list, *, coin_type: str = "") -> str:
    parts = []
    ct = str(coin_type or "").strip()
    if ct:
        parts.append(ct)
    for p in pools or []:
        if not isinstance(p, dict):
            continue
        url = str(p.get("url") or "").strip()
        if not url:
            continue
        # short host-ish
        host = url.replace("stratum+tcp://", "").replace("stratum+ssl://", "")
        host = host.split("/")[0].split(":")[0]
        user = str(p.get("user") or "").strip()
        worker = user.split(".")[-1] if user else ""
        parts.append(host + (f"/{worker}" if worker else ""))
    return " · ".join(parts[:4]) if parts else "—"


def _normalize_coin_type(v) -> str:
    s = str(v or "").strip()
    if not s or s in ("—", "-", "none", "null"):
        return ""
    # keep short ticker-like codes
    return s[:32]


def _load_pool_presets() -> None:
    global _pool_presets
    with _pool_presets_lock:
        raw = _load_json(POOL_PRESETS_FILE, {"presets": [], "active_id": None})
        if not isinstance(raw, dict):
            raw = {"presets": [], "active_id": None}
        clean = []
        for p in raw.get("presets") or []:
            if not isinstance(p, dict):
                continue
            try:
                pools = _normalize_pool_preset_pools(p.get("pools") or p.get("config"))
            except Exception:
                continue
            coin = _normalize_coin_type(p.get("coin_type") or p.get("coin"))
            clean.append(
                {
                    "id": str(p.get("id") or "").strip() or _new_preset_id(),
                    "name": str(p.get("name") or "Preset")[:64],
                    "updated_ts": p.get("updated_ts")
                    or datetime.now().isoformat(timespec="seconds"),
                    "pools": pools,
                    "coin_type": coin,
                    "summary": _pool_preset_summary(pools, coin_type=coin),
                }
            )
        _pool_presets = {
            "presets": clean,
            "active_id": raw.get("active_id") if raw.get("active_id") else None,
        }
        try:
            _save_json(POOL_PRESETS_FILE, _pool_presets)
        except Exception:
            pass


def _save_pool_presets() -> None:
    with _pool_presets_lock:
        _save_json(POOL_PRESETS_FILE, _pool_presets)


def list_pool_presets(*, include_secrets: bool = True) -> dict:
    with _pool_presets_lock:
        items = []
        for p in _pool_presets.get("presets") or []:
            pools = p.get("pools") or []
            coin = _normalize_coin_type(p.get("coin_type") or p.get("coin"))
            if not include_secrets:
                pools = [
                    {
                        "url": x.get("url"),
                        "user": x.get("user"),
                        "pass": "••••" if x.get("pass") else "",
                        "pass_set": bool(x.get("pass")),
                    }
                    for x in pools
                    if isinstance(x, dict)
                ]
            items.append(
                {
                    "id": p.get("id"),
                    "name": p.get("name"),
                    "updated_ts": p.get("updated_ts"),
                    "coin_type": coin,
                    "summary": p.get("summary")
                    or _pool_preset_summary(p.get("pools") or [], coin_type=coin),
                    "pools": pools,
                }
            )
        return {
            "ok": True,
            "presets": items,
            "active_id": _pool_presets.get("active_id"),
        }


def get_pool_preset(preset_id: str) -> dict | None:
    pid = str(preset_id or "").strip()
    if not pid:
        return None
    with _pool_presets_lock:
        for p in _pool_presets.get("presets") or []:
            if p.get("id") == pid:
                return json.loads(json.dumps(p))
    return None


def snapshot_live_pools_for_preset() -> list[dict]:
    """Current ASIC pools → {url,user,pass}; password often unknown → 'x'."""
    body = fetch_mining_pools(force=True)
    if not body.get("ok"):
        raise RuntimeError(body.get("error") or "cannot read pools from miner")
    rows = body.get("pools") or []
    # order by pool number
    try:
        rows = sorted(rows, key=lambda r: int(r.get("pool") or 99))
    except Exception:
        pass
    out = []
    for r in rows[:3]:
        if not isinstance(r, dict):
            continue
        url = str(r.get("url") or "").strip()
        if url in ("", "—"):
            continue
        out.append(
            {
                "url": url,
                "user": str(r.get("user") or "").strip(),
                # Whatsminer status API does not return password
                "pass": "x",
            }
        )
    if not out:
        raise ValueError("miner has no pools configured")
    return _normalize_pool_preset_pools(out)


def save_pool_preset(
    name: str,
    pools: list | None = None,
    *,
    preset_id: str | None = None,
    from_live: bool = False,
    coin_type: str | None = None,
) -> dict:
    """Create/update pool preset. from_live → snapshot miner; pools=list → edit."""
    name = str(name or "").strip()
    if not name:
        raise ValueError("name empty")
    if len(name) > 64:
        name = name[:64]

    coin_in = None if coin_type is None else _normalize_coin_type(coin_type)

    if from_live:
        pools_norm = snapshot_live_pools_for_preset()
        # keep old passwords if same url+user when overwriting preset
        if preset_id:
            old = get_pool_preset(preset_id)
            if old:
                old_by_key = {
                    (
                        str(x.get("url") or "").strip(),
                        str(x.get("user") or "").strip(),
                    ): x
                    for x in (old.get("pools") or [])
                    if isinstance(x, dict)
                }
                for p in pools_norm:
                    key = (p.get("url") or "", p.get("user") or "")
                    prev = old_by_key.get(key)
                    if (
                        prev
                        and prev.get("pass")
                        and prev.get("pass") not in ("x", "••••", "")
                        and p.get("pass") in ("", "x")
                    ):
                        p["pass"] = prev["pass"]
        # coin from LuCI when snapshotting live
        if coin_in is None:
            try:
                live_body = fetch_mining_pools(force=False)
                coin_in = _normalize_coin_type(live_body.get("coin_type"))
            except Exception:
                coin_in = ""
            if not coin_in:
                coin_in = _normalize_coin_type(fetch_miner_coin_type())
    elif pools is not None:
        pools_norm = _normalize_pool_preset_pools(pools)
    elif preset_id:
        existing = get_pool_preset(preset_id)
        if not existing:
            raise ValueError(f"preset not found: {preset_id}")
        pools_norm = existing.get("pools") or []
        if coin_in is None:
            coin_in = _normalize_coin_type(existing.get("coin_type"))
    else:
        raise ValueError("pools list or from_live=true required")

    # preserve coin when not provided on update
    if coin_in is None and preset_id:
        old = get_pool_preset(preset_id)
        coin_in = _normalize_coin_type((old or {}).get("coin_type"))
    if coin_in is None:
        coin_in = ""

    now = datetime.now().isoformat(timespec="seconds")
    with _pool_presets_lock:
        presets = list(_pool_presets.get("presets") or [])
        if preset_id:
            pid = str(preset_id).strip()
            found = False
            for i, p in enumerate(presets):
                if p.get("id") == pid:
                    presets[i] = {
                        "id": pid,
                        "name": name,
                        "updated_ts": now,
                        "pools": pools_norm,
                        "coin_type": coin_in,
                        "summary": _pool_preset_summary(
                            pools_norm, coin_type=coin_in
                        ),
                    }
                    found = True
                    break
            if not found:
                raise ValueError(f"preset not found: {pid}")
            out_id = pid
        else:
            out_id = _new_preset_id()
            presets.append(
                {
                    "id": out_id,
                    "name": name,
                    "updated_ts": now,
                    "pools": pools_norm,
                    "coin_type": coin_in,
                    "summary": _pool_preset_summary(
                        pools_norm, coin_type=coin_in
                    ),
                }
            )
        _pool_presets["presets"] = presets
    _save_pool_presets()
    return {"ok": True, "id": out_id, **list_pool_presets()}


def delete_pool_preset(preset_id: str) -> dict:
    pid = str(preset_id or "").strip()
    if not pid:
        raise ValueError("id empty")
    with _pool_presets_lock:
        presets = [p for p in (_pool_presets.get("presets") or []) if p.get("id") != pid]
        if len(presets) == len(_pool_presets.get("presets") or []):
            raise ValueError(f"preset not found: {pid}")
        _pool_presets["presets"] = presets
        if _pool_presets.get("active_id") == pid:
            _pool_presets["active_id"] = None
    _save_pool_presets()
    return list_pool_presets()


def apply_pool_preset(
    preset_id: str,
    *,
    password: str | None = None,
    coin_type: str | None = None,
) -> dict:
    """Write preset pools to ASIC (update_pools) and mark active."""
    p = get_pool_preset(preset_id)
    if not p:
        raise ValueError(f"preset not found: {preset_id}")
    pools = _normalize_pool_preset_pools(p.get("pools") or [])
    pw = password or DEFAULT_API_PASSWORD
    # prefer explicit override (UI field), else preset value
    if coin_type is not None:
        coin = _normalize_coin_type(coin_type)
    else:
        coin = _normalize_coin_type(p.get("coin_type") or p.get("coin"))
    # persist coin on preset if provided from UI
    if coin_type is not None and coin != _normalize_coin_type(p.get("coin_type")):
        try:
            save_pool_preset(
                str(p.get("name") or p.get("id")),
                p.get("pools"),
                preset_id=str(p.get("id")),
                from_live=False,
                coin_type=coin,
            )
            p = get_pool_preset(preset_id) or p
        except Exception as e:
            print(f"[pools] coin persist: {e}")
    cmd: dict = {
        "cmd": "update_pools",
        "pools": pools,
        # Always restart so stratum picks up new pools (LuCI was deferred-only)
        "restart_mining": True,
    }
    if coin:
        cmd["coin_type"] = coin
    resp = miner_write_cmd(cmd, pw)
    out = _record_write(
        "pools",
        pools,
        resp,
        warning="pools preset applied · btminer restart may follow",
    )
    if isinstance(resp, dict) and resp.get("transport"):
        out["transport"] = resp.get("transport")
    with _pool_presets_lock:
        _pool_presets["active_id"] = p.get("id")
    _save_pool_presets()
    # invalidate live pools cache
    try:
        global _pools_cache, _pools_cache_ts
        with _pools_cache_lock:
            _pools_cache = None
            _pools_cache_ts = 0.0
    except Exception:
        pass
    out["ok"] = True
    out["id"] = p.get("id")
    out["name"] = p.get("name")
    out["pools"] = pools
    out["active_id"] = p.get("id")
    # include list for UI refresh
    try:
        out.update(list_pool_presets())
        out["ok"] = True
        out["id"] = p.get("id")
        out["name"] = p.get("name")
        out["active_id"] = p.get("id")
    except Exception:
        pass
    return out


def _coerce_zone_config_dict(req: dict) -> dict:
    """Normalize a zone-map payload (same rules as POST /api/zone/config)."""
    if not isinstance(req, dict):
        raise ValueError("expected object")
    cfg = dict(DEFAULT_ZONE_CFG)
    # start from current so partial updates still work when used that way
    with _zone_cfg_lock:
        base = dict(_zone_cfg) if _zone_cfg else dict(DEFAULT_ZONE_CFG)
    cfg.update({k: base.get(k) for k in DEFAULT_ZONE_CFG if k != "zones"})
    cfg["zones"] = json.loads(json.dumps(base.get("zones") or DEFAULT_ZONE_CFG["zones"]))
    for key in (
        "t0",
        "t1",
        "t2",
        "h",
        "t_crit",
        "t_crit_clear",
        "dwell_sec",
        "settle_sec",
        "streak",
        "min_write_interval_sec",
        "limit_tol_w",
        "max_warmup_wait_min",
    ):
        if key in req and req[key] is not None:
            try:
                if key in (
                    "dwell_sec",
                    "settle_sec",
                    "streak",
                    "min_write_interval_sec",
                    "limit_tol_w",
                    "max_warmup_wait_min",
                ):
                    cfg[key] = int(float(req[key]))
                else:
                    cfg[key] = float(req[key])
            except (TypeError, ValueError):
                pass
    if "t_ctrl_sensor" in req and req.get("t_ctrl_sensor") is not None:
        cfg["t_ctrl_sensor"] = _normalize_t_ctrl_sensor(req.get("t_ctrl_sensor"))
    for bkey in ("warmup_en", "warmup_downward_only"):
        if bkey in req:
            cfg[bkey] = bool(req[bkey])
    cfg["min_write_interval_sec"] = max(
        10, min(3600, int(cfg.get("min_write_interval_sec", 60) or 60))
    )
    cfg["limit_tol_w"] = max(10, min(2000, int(cfg.get("limit_tol_w", 100) or 100)))
    cfg["max_warmup_wait_min"] = max(
        1, min(240, int(cfg.get("max_warmup_wait_min", 30) or 30))
    )
    cfg["warmup_en"] = bool(cfg.get("warmup_en", True))
    cfg["warmup_downward_only"] = bool(cfg.get("warmup_downward_only", True))
    cfg["h"] = max(0.2, min(5.0, float(cfg.get("h", 0.5))))
    cfg["t_ctrl_sensor"] = _normalize_t_ctrl_sensor(
        cfg.get("t_ctrl_sensor", "liquid")
    )
    if "t2" not in cfg or cfg.get("t2") is None:
        cfg["t2"] = float(cfg.get("t1", 28)) + max(2.0, float(cfg["h"]))
    if float(cfg["t0"]) >= float(cfg["t1"]):
        raise ValueError("need t0 < t1")
    if float(cfg["t1"]) >= float(cfg["t2"]):
        raise ValueError("need t1 < t2")
    if float(cfg["t_crit_clear"]) >= float(cfg["t_crit"]):
        raise ValueError("need t_crit_clear < t_crit")
    zones_in = req.get("zones") if isinstance(req.get("zones"), dict) else {}
    zones_out = dict(cfg.get("zones") or {})
    for name, default in DEFAULT_ZONE_CFG["zones"].items():
        base_z = zones_out.get(name) or default
        zin = zones_in.get(name, base_z)
        if name == "critical":
            if not isinstance(base_z, dict):
                base_z = default
            if isinstance(zin, dict) and ("on_crit" in zin or "on_clear" in zin):
                zones_out[name] = {
                    "on_crit": _normalize_zone_entry(
                        zin.get("on_crit", base_z.get("on_crit")),
                        default["on_crit"],
                    ),
                    "on_clear": _normalize_zone_entry(
                        zin.get("on_clear", base_z.get("on_clear")),
                        default["on_clear"],
                    ),
                }
            else:
                zones_out[name] = {
                    "on_crit": _normalize_zone_entry(
                        zin if isinstance(zin, dict) else base_z.get("on_crit"),
                        default["on_crit"],
                    ),
                    "on_clear": _normalize_zone_entry(
                        base_z.get("on_clear") if isinstance(base_z, dict) else None,
                        default["on_clear"],
                    ),
                }
        else:
            zones_out[name] = _normalize_zone_entry(zin, default)
    cfg["zones"] = zones_out
    cfg["zone_map_version"] = 2
    return cfg


