        "last_on",
        "desired_on",
        "online",
        "last_error",
        "last_ok_ts",
        "last_action",
        "last_power",
        "last_power_ts",
        # API-only aliases (never stored)
        "reported_on",
        "desired",
        "reported",
        "auto_off_suspend_in_sec",
        "auto_off_suspend_pending",
        "password_set",
        "ha_token_set",
        "tuya_local_key_set",
        "xiaomi_token_set",
        "mining",
