def _device_runtime_defaults() -> dict:
    return {
        "last_on": None,
        "desired_on": None,
        "online": None,
        "last_error": None,
        "last_ok_ts": None,
        "last_action": None,
        "last_power": None,
        "last_power_ts": None,
        "last_brightness": None,
        "last_mode": None,
        "last_telemetry": None,
        "desired_brightness": None,
        "desired_mode": None,
    }


def _extract_device_runtime(raw: dict | None) -> dict:
    """Pull runtime fields from a mixed dict (legacy config or API body)."""
    out = _device_runtime_defaults()
    if not isinstance(raw, dict):
        return out
    for k in (
        "last_on",
        "desired_on",
        "online",
        "last_error",
        "last_ok_ts",
        "last_action",
        "last_power",
        "last_power_ts",
        "last_brightness",
        "last_mode",
        "last_telemetry",
        "desired_brightness",
        "desired_mode",
    ):
        if k not in raw:
            continue
        if k == "last_power":
            out[k] = (
                _normalize_power_metrics(raw.get("last_power"))
                if isinstance(raw.get("last_power"), dict)
                else None
            )
        elif k == "last_telemetry":
            out[k] = raw.get(k) if isinstance(raw.get(k), dict) else None
        elif k in ("last_brightness", "desired_brightness"):
            try:
                out[k] = max(0, min(100, int(raw.get(k))))
            except (TypeError, ValueError):
                out[k] = None
        elif k in ("last_mode", "desired_mode"):
            s = str(raw.get(k) or "").strip()
            out[k] = s or None
        elif k in ("last_on", "desired_on", "online"):
            v = raw.get(k)
            out[k] = None if v is None else _as_bool(v)
        else:
            out[k] = raw.get(k)
    return out


def _strip_device_runtime(d: dict) -> dict:
    """Config-only device dict (no shadow / diagnostics)."""
    if not isinstance(d, dict):
        return {}
    return {k: v for k, v in d.items() if k not in DEVICE_RUNTIME_KEYS}


def _merge_device_runtime(cfg: dict, st: dict | None) -> dict:
    """Config + runtime for API / policy (copy)."""
    out = dict(cfg)
    base = _device_runtime_defaults()
    if isinstance(st, dict):
        for k, v in st.items():
            if k in base or k in (
                "last_on",
                "desired_on",
                "online",
                "last_error",
                "last_ok_ts",
                "last_action",
                "last_power",
                "last_power_ts",
            ):
                base[k] = v
    out.update(base)
    return out


def _save_json_atomic(path: Path, data: dict) -> None:
    """Write JSON via temp + replace (safe for concurrent readers)."""
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        text = json.dumps(data, indent=2, ensure_ascii=False)
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_text(text, encoding="utf-8")
        tmp.replace(path)
    except Exception as e:
        print(f"[json] atomic save {path.name}: {e}", flush=True)


def _load_devices_state() -> None:
    """Load devices_state.json into _devices_state (call under _devices_cfg_lock)."""
    global _devices_state
    raw = _load_json(DEVICES_STATE_FILE, {"version": 1, "by_id": {}})
    by_id: dict = {}
    if isinstance(raw, dict):
        if isinstance(raw.get("by_id"), dict):
            by_id = raw["by_id"]
        elif isinstance(raw.get("devices"), dict):
            by_id = raw["devices"]
        elif isinstance(raw.get("devices"), list):
            for d in raw["devices"]:
                if isinstance(d, dict) and d.get("id"):
                    by_id[str(d["id"])] = d
    clean: dict[str, dict] = {}
    for did, st in by_id.items():
        if not did or not isinstance(st, dict):
            continue
        clean[str(did)] = _extract_device_runtime(st)
    _devices_state = clean


def _save_devices_state() -> None:
    """Persist runtime shadow only (poller-safe; does not touch config)."""
    with _devices_cfg_lock:
        payload = {
            "version": 1,
            "by_id": {
                did: _extract_device_runtime(st)
                for did, st in (_devices_state or {}).items()
                if did
            },
        }
        _save_json_atomic(DEVICES_STATE_FILE, payload)


def _device_state_get(did: str) -> dict:
    with _devices_cfg_lock:
        return dict(_devices_state.get(str(did) or "") or _device_runtime_defaults())


def _device_alias_ok(alias: str) -> bool:
    a = str(alias or "").strip().lower()
    return bool(re.fullmatch(r"[a-z][a-z0-9_]{0,31}", a))


def _device_alias_reserved(alias: str) -> bool:
    a = str(alias or "").strip().lower()
    return a in DEVICE_ALIAS_RESERVED


def _new_device_id() -> str:
    return "d_" + uuid.uuid4().hex[:12]


def _device_backend_fields_from_raw(raw: dict) -> dict:
    """Normalize connection fields shared with filtration backends."""
    be = str(raw.get("backend") or "tapo").strip().lower()
    if be in ("smartlife", "smart_life"):
        be = "tuya"
    if be in ("mi", "mihome", "mi_home", "miio", "mijia"):
        be = "xiaomi"
    if be not in _FILTRATION_BACKEND_IDS and be not in _DEVICE_BACKEND_EXTRA:
        be = "tapo"
    out: dict = {
        "backend": be,
        "ip": str(raw.get("ip") or "").strip()[:64],
        "email": str(raw.get("email") or "").strip()[:120],
        "password": str(raw.get("password") or ""),
        "device_id": str(raw.get("device_id") or "").strip()[:64],
        "ewelink_port": 8081,
        "ewelink_mode": "auto",  # auto | diy | lan
        "ewelink_devicekey": str(
            raw.get("ewelink_devicekey")
            or raw.get("devicekey")
            or ""
        ).strip()[:80],
        # CoolKit user apikey (selfApikey) — separate from per-device devicekey
        "ewelink_apikey": str(
            raw.get("ewelink_apikey")
            or raw.get("apikey")
            or raw.get("ewelink_user_apikey")
            or ""
        ).strip()[:80],
        "ewelink_country": str(raw.get("ewelink_country") or raw.get("country_code") or "+7").strip()[:8]
        or "+7",
        "ewelink_region": str(raw.get("ewelink_region") or "eu").strip().lower()[:8]
        or "eu",
        "ewelink_outlet": 0,
        "webhook_on_url": str(raw.get("webhook_on_url") or "").strip()[:500],
        "webhook_off_url": str(raw.get("webhook_off_url") or "").strip()[:500],
        "webhook_method": "POST"
        if str(raw.get("webhook_method") or "GET").upper() == "POST"
        else "GET",
        "webhook_body_on": str(raw.get("webhook_body_on") or "")[:2000],
        "webhook_body_off": str(raw.get("webhook_body_off") or "")[:2000],
        "webhook_headers": str(raw.get("webhook_headers") or "")[:2000],
        "shelly_channel": 0,
        "shelly_gen": "auto",
        "ha_url": str(raw.get("ha_url") or "").strip()[:300],
        "ha_token": str(raw.get("ha_token") or ""),
        "ha_entity_id": str(raw.get("ha_entity_id") or "").strip()[:120],
        # Tuya / Smart Life (LAN via tinytuya; key from mobile login)
        "tuya_ecosystem": "smartlife",
        "tuya_country": "7",
        "tuya_region": "eu",
        "tuya_local_key": str(raw.get("tuya_local_key") or raw.get("local_key") or ""),
        "tuya_version": 3.4,
        "tuya_switch_dps": 1,
        "tuya_bright_dps": 0,  # 0 = default 22 for lights
        "tuya_mode_dps": 0,  # 0 = default 21 for lights
        "device_kind": str(raw.get("device_kind") or raw.get("kind") or "").strip().lower()[
            :16
        ],
        # Xiaomi / Mi Home (LAN miIO; token once)
        "xiaomi_token": str(
            raw.get("xiaomi_token") or raw.get("miio_token") or raw.get("token") or ""
        ).strip(),
        "xiaomi_model": str(raw.get("xiaomi_model") or raw.get("model") or "").strip()[
            :64
        ],
    }
    eco = str(raw.get("tuya_ecosystem") or raw.get("ecosystem") or "smartlife").strip().lower()
    if eco in ("smart_life", "sl"):
        eco = "smartlife"
    if eco in ("tuya_smart", "tuyasmart", "793"):
        eco = "tuya"
    if eco in ("dns", "dns_houself", "dns-houself", "houseelf"):
        eco = "houself"
    if eco not in ("smartlife", "tuya", "classic", "houself"):
        eco = "smartlife"
    out["tuya_ecosystem"] = eco
    out["tuya_country"] = str(raw.get("tuya_country") or raw.get("country") or "7").strip()[:8] or "7"
    reg = str(raw.get("tuya_region") or raw.get("region") or "eu").strip().lower()
    out["tuya_region"] = reg if reg in ("eu", "us", "cn", "in") else "eu"
    try:
        out["tuya_version"] = float(raw.get("tuya_version") or raw.get("version") or 3.4)
    except (TypeError, ValueError):
        out["tuya_version"] = 3.4
    try:
        out["tuya_switch_dps"] = max(1, min(255, int(raw.get("tuya_switch_dps") or raw.get("switch_dps") or 1)))
    except (TypeError, ValueError):
        out["tuya_switch_dps"] = 1
    try:
        out["tuya_bright_dps"] = max(
            0, min(255, int(raw.get("tuya_bright_dps") or raw.get("bright_dps") or 0))
        )
    except (TypeError, ValueError):
        out["tuya_bright_dps"] = 0
    try:
        out["tuya_mode_dps"] = max(
            0, min(255, int(raw.get("tuya_mode_dps") or raw.get("mode_dps") or 0))
        )
    except (TypeError, ValueError):
        out["tuya_mode_dps"] = 0
    dk = str(out.get("device_kind") or "").strip().lower()
    if dk in ("lamp", "bulb", "led"):
        dk = "light"
    if dk not in ("", "switch", "light", "dimmer", "plug", "relay"):
        dk = ""
    # auto-kind for Tuya lights (switch on DPS 20)
    if not dk and out.get("backend") == "tuya" and int(out.get("tuya_switch_dps") or 0) == 20:
        dk = "dimmer"
    out["device_kind"] = dk
    try:
        out["ewelink_port"] = max(1, min(65535, int(raw.get("ewelink_port") or 8081)))
    except (TypeError, ValueError):
        out["ewelink_port"] = 8081
    em = str(raw.get("ewelink_mode") or out.get("ewelink_mode") or "auto").strip().lower()
    out["ewelink_mode"] = em if em in ("auto", "diy", "lan") else "auto"
    er = str(out.get("ewelink_region") or "eu").strip().lower()
    out["ewelink_region"] = er if er in ("eu", "us", "as", "cn") else "eu"
    ec = str(out.get("ewelink_country") or "+7").strip()
    if ec and not ec.startswith("+"):
        ec = "+" + ec
    out["ewelink_country"] = ec or "+7"
    try:
        out["ewelink_outlet"] = max(0, min(7, int(raw.get("ewelink_outlet") or 0)))
    except (TypeError, ValueError):
        out["ewelink_outlet"] = 0
    try:
        out["shelly_channel"] = max(0, min(3, int(raw.get("shelly_channel") or 0)))
    except (TypeError, ValueError):
        out["shelly_channel"] = 0
    sg = str(raw.get("shelly_gen") or "auto").strip().lower()
    out["shelly_gen"] = sg if sg in ("auto", "1", "2", "gen1", "gen2") else "auto"
    if out["shelly_gen"] == "gen1":
        out["shelly_gen"] = "1"
    if out["shelly_gen"] == "gen2":
        out["shelly_gen"] = "2"
    # Xiaomi token: keep 32 hex only
    xt = "".join(c for c in out["xiaomi_token"] if c.isalnum()).lower()
    if xt.startswith("0x"):
        xt = xt[2:]
    out["xiaomi_token"] = xt[:64]
    return out


def _device_off_delay_sec(v) -> int:
    """
    Seconds to wait after Suspend before Auto Off.
    Default 60. 0 = immediate. Clamped 0…3600.
    """
    if v is None or v == "":
        return 60
    try:
        n = int(float(v))
    except (TypeError, ValueError):
        return 60
    return max(0, min(3600, n))


def _normalize_device(raw: dict | None, *, keep_secrets: bool = True) -> dict | None:
    if not isinstance(raw, dict):
        return None
    alias = str(raw.get("alias") or "").strip().lower()
    if not _device_alias_ok(alias):
        return None
    if _device_alias_reserved(alias):
        return None
    did = str(raw.get("id") or "").strip() or _new_device_id()
    # bilingual name / description (legacy ``name`` / ``description`` supported)
    name_en = str(raw.get("name_en") or "").strip()
    name_ru = str(raw.get("name_ru") or "").strip()
    name_legacy = str(raw.get("name") or "").strip()
    if not name_en and not name_ru:
        name_en = name_ru = name_legacy or alias
    elif name_en and not name_ru:
        name_ru = name_en
    elif name_ru and not name_en:
        name_en = name_ru
    name_en = (name_en or alias)[:80]
    name_ru = (name_ru or name_en or alias)[:80]
    name = name_en or name_ru or alias

    desc_en = str(raw.get("description_en") or "").strip()
    desc_ru = str(raw.get("description_ru") or "").strip()
    desc_legacy = str(raw.get("description") or raw.get("desc") or "").strip()
    if not desc_en and not desc_ru:
        desc_en = desc_ru = desc_legacy
    elif desc_en and not desc_ru:
        desc_ru = desc_en
    elif desc_ru and not desc_en:
        desc_en = desc_ru
    desc_en = desc_en[:300]
    desc_ru = desc_ru[:300]
    description = desc_en or desc_ru

    icon = str(raw.get("icon") or "🔌").strip()[:8] or "🔌"
    # single-codepoint-ish: keep first grapheme-ish chunk
    if len(icon) > 4:
        icon = icon[:4]
    enabled = _as_bool(raw.get("enabled", True))
    inverted = _as_bool(raw.get("inverted", False))
    show_in_bot = _as_bool(raw.get("show_in_bot", False))
    fields = _device_backend_fields_from_raw(raw)
    if not keep_secrets:
        # used only when redacting for UI list
        pass
    last_on = raw.get("last_on")
    if last_on is not None:
        last_on = _as_bool(last_on)
    return {
        "id": did,
        "alias": alias,
        "name": name,
        "name_en": name_en,
        "name_ru": name_ru,
        "description": description,
        "description_en": desc_en,
        "description_ru": desc_ru,
        "icon": icon,
        "enabled": enabled,
        "inverted": inverted,
        "show_in_bot": show_in_bot,
        "auto_on_mining": _as_bool(raw.get("auto_on_mining", False)),
        "auto_off_suspend": _as_bool(raw.get("auto_off_suspend", False)),
        "auto_off_suspend_delay_sec": _device_off_delay_sec(
            raw.get("auto_off_suspend_delay_sec")
        ),
        "allow_off_while_mining": _as_bool(raw.get("allow_off_while_mining", False)),
        "allow_on_while_suspend": _as_bool(raw.get("allow_on_while_suspend", False)),
        "enforce_desired": _as_bool(raw.get("enforce_desired", False)),
        # Bound managed miner id; empty = mining policy ignored for this device
        "miner_id": str(raw.get("miner_id") or raw.get("bound_miner_id") or "").strip(),
        **fields,
        # reported (observed) logical state — also exposed as reported_on in API
        "last_on": last_on,
        "desired_on": (
            None
            if raw.get("desired_on") is None
            else _as_bool(raw.get("desired_on"))
        ),
        "online": (
            None
            if raw.get("online") is None
            else _as_bool(raw.get("online"))
        ),
        "last_error": raw.get("last_error"),
        "last_ok_ts": raw.get("last_ok_ts"),
        "last_action": raw.get("last_action"),
        # last power metrics (W/V/A/kWh) when backend reports them
        "last_power": _normalize_power_metrics(raw.get("last_power"))
        if isinstance(raw.get("last_power"), dict)
        else None,
        "last_power_ts": raw.get("last_power_ts"),
    }


def _device_from_filtration_cfg(filtr: dict | None) -> dict | None:
    """One-shot migration: legacy single filtration outlet → multi-device entry."""
    if not isinstance(filtr, dict):
        return None
    be = str(filtr.get("backend") or "tapo").strip().lower()
    ip = str(filtr.get("ip") or "").strip()
    # skip empty stub
    if not ip and not filtr.get("webhook_on_url") and not filtr.get("ha_entity_id"):
        return None
    if not filtr.get("password") and not filtr.get("password_set") and be == "tapo":
        # still allow if email+ip present (password may be redacted elsewhere)
        if not filtr.get("email"):
            return None
    raw = {
        "alias": "filtration",
        "name": "Filtration",
        "name_en": "Filtration",
        "name_ru": "Фильтрация",
        "icon": "🌀",
        "enabled": True,
        "backend": be if be else "tapo",
        "ip": ip,
        "email": filtr.get("email") or "",
        "password": filtr.get("password") or "",
        "device_id": filtr.get("device_id") or "",
        "ewelink_port": filtr.get("ewelink_port"),
        "webhook_on_url": filtr.get("webhook_on_url") or "",
        "webhook_off_url": filtr.get("webhook_off_url") or "",
        "webhook_method": filtr.get("webhook_method") or "GET",
        "webhook_body_on": filtr.get("webhook_body_on") or "",
        "webhook_body_off": filtr.get("webhook_body_off") or "",
        "webhook_headers": filtr.get("webhook_headers") or "",
        "shelly_channel": filtr.get("shelly_channel"),
        "shelly_gen": filtr.get("shelly_gen") or "auto",
        "ha_url": filtr.get("ha_url") or "",
        "ha_token": filtr.get("ha_token") or "",
        "ha_entity_id": filtr.get("ha_entity_id") or "",
        "auto_on_mining": filtr.get("auto_on_mining", True),
        "auto_off_suspend": filtr.get("auto_off_suspend", False),
        "allow_off_while_mining": filtr.get("allow_off_while_mining", False),
        "allow_on_while_suspend": filtr.get("allow_on_while_suspend", False),
        "enforce_desired": True,
        "show_in_bot": True,
        "last_on": filtr.get("last_on"),
        "desired_on": filtr.get("last_on"),
        "last_error": filtr.get("last_error"),
        "last_ok_ts": filtr.get("last_ok_ts"),
        "last_action": filtr.get("last_action"),
    }
    return _normalize_device(raw)


def _load_devices_cfg() -> None:
    global _devices_cfg, _devices_state
    with _devices_cfg_lock:
        raw = _load_json(DEVICES_CFG_FILE, DEFAULT_DEVICES_CFG)
        if not isinstance(raw, dict):
            raw = {}
        devices_in = raw.get("devices") if isinstance(raw.get("devices"), list) else []
        clean: list[dict] = []
        seen_alias: set[str] = set()
        # runtime lifted out of legacy config blobs
        lifted: dict[str, dict] = {}
        had_runtime_in_config = False
        for d in devices_in:
            if not isinstance(d, dict):
                continue
            rt = _extract_device_runtime(d)
            if any(
                rt.get(k) is not None
                for k in (
                    "last_on",
                    "desired_on",
                    "online",
                    "last_error",
                    "last_ok_ts",
                    "last_action",
                    "last_power",
                    "last_power_ts",
                )
            ):
                had_runtime_in_config = True
            nd = _normalize_device(d)
            if not nd:
                continue
            if nd["alias"] in seen_alias:
                continue
            seen_alias.add(nd["alias"])
            did = str(nd.get("id") or "")
            if did:
                lifted[did] = rt
            # config row: no shadow fields
            clean.append(_strip_device_runtime(nd))
        # auto-heal: empty multi-device list but legacy filtration outlet present
        # Only when config file is missing/empty — never after a corrupt wipe of multi-device
        migrated = False
        cfg_missing = not DEVICES_CFG_FILE.is_file()
        if not clean and cfg_missing:
            try:
                filtr = _load_json(FILTRATION_CFG_FILE, {})
            except Exception:
                filtr = {}
            mig = _device_from_filtration_cfg(
                filtr if isinstance(filtr, dict) else None
            )
            if mig and mig["alias"] not in seen_alias:
                rt = _extract_device_runtime(mig)
                mig_cfg = _strip_device_runtime(mig)
                clean.append(mig_cfg)
                if mig_cfg.get("id"):
                    lifted[str(mig_cfg["id"])] = rt
                migrated = True
                print(
                    f"[devices] migrated legacy filtration → device "
                    f"alias={mig.get('alias')} backend={mig.get('backend')}",
                    flush=True,
                )
        poller = _normalize_devices_poller(
            raw.get("poller") if isinstance(raw.get("poller"), dict) else None
        )
        # Soft-migrate: bind mining-flagged devices to active/sole miner
        clean, mig_bind = _migrate_device_miner_binds(clean)
        if mig_bind:
            migrated = True
        _devices_cfg = {"version": 1, "poller": poller, "devices": clean}
        # load state file, then overlay anything still stuck in old config
        _load_devices_state()
        for did, rt in lifted.items():
            prev = _devices_state.get(did) or _device_runtime_defaults()
            # prefer existing state file values when set; fill gaps from config lift
            merged = dict(prev)
            for k, v in rt.items():
                if v is not None and merged.get(k) is None:
                    merged[k] = v
            _devices_state[did] = _extract_device_runtime(merged)
        if migrated or had_runtime_in_config:
            try:
                # rewrite config without runtime; persist state
                payload = {
                    "version": 1,
                    "poller": poller,
                    "devices": [_strip_device_runtime(d) for d in clean],
                }
                _save_json_atomic(DEVICES_CFG_FILE, payload)
                _save_json_atomic(
                    DEVICES_STATE_FILE,
                    {
                        "version": 1,
                        "by_id": {
                            did: _extract_device_runtime(st)
                            for did, st in _devices_state.items()
                        },
                    },
                )
                if had_runtime_in_config:
                    print(
                        "[devices] migrated runtime fields → devices_state.json",
                        flush=True,
                    )
            except Exception as e:
                print(f"[devices] migrate save: {e}", flush=True)


def _save_devices_cfg() -> None:
    """
    Persist devices_config.json (settings only — no shadow/status).
    Guard: never overwrite a non-empty on-disk device list with an empty
    in-memory list (protects against race / partial load wipe).
    """
    with _devices_cfg_lock:
        mem = list(_devices_cfg.get("devices") or [])
        if not mem and DEVICES_CFG_FILE.is_file():
            try:
                disk = _load_json(DEVICES_CFG_FILE, {})
                disk_devs = (
                    disk.get("devices")
                    if isinstance(disk, dict) and isinstance(disk.get("devices"), list)
                    else []
                )
                if disk_devs:
                    print(
                        f"[devices] refuse save: memory has 0 devices but disk has "
                        f"{len(disk_devs)} — keeping disk (reload)",
                        flush=True,
                    )
                    # heal memory from disk so UI/API match
                    clean: list[dict] = []
                    seen: set[str] = set()
                    for d in disk_devs:
                        nd = _normalize_device(d)
                        if not nd or nd["alias"] in seen:
                            continue
                        seen.add(nd["alias"])
                        clean.append(_strip_device_runtime(nd))
                    if clean:
                        _devices_cfg["devices"] = clean
                        return
            except Exception as e:
                print(f"[devices] save guard: {e}", flush=True)
        # never write runtime into config
        payload = {
            "version": int(_devices_cfg.get("version") or 1),
            "poller": _normalize_devices_poller(
                _devices_cfg.get("poller")
                if isinstance(_devices_cfg.get("poller"), dict)
                else None
            ),
            "devices": [
                _strip_device_runtime(d)
                for d in (_devices_cfg.get("devices") or [])
                if isinstance(d, dict)
            ],
        }
        _devices_cfg["devices"] = payload["devices"]
        _devices_cfg["poller"] = payload["poller"]
        _save_json_atomic(DEVICES_CFG_FILE, payload)


# ── Cloud credentials vault (shared app logins per ecosystem / country) ─────
_cloud_creds_lock = threading.RLock()
_cloud_creds: dict = {"version": 1, "accounts": []}


def _load_cloud_credentials() -> None:
    global _cloud_creds
    with _cloud_creds_lock:
        try:
            if CLOUD_CREDENTIALS_FILE.is_file():
                raw = json.loads(
                    CLOUD_CREDENTIALS_FILE.read_text(encoding="utf-8")
                )
                if isinstance(raw, dict) and isinstance(raw.get("accounts"), list):
                    _cloud_creds = {
                        "version": int(raw.get("version") or 1),
                        "accounts": [
                            a for a in raw["accounts"] if isinstance(a, dict)
                        ],
                    }
                    return
        except Exception as e:
            print(f"[cloud-creds] load: {e}", flush=True)
        _cloud_creds = {"version": 1, "accounts": []}


def _save_cloud_credentials() -> None:
    with _cloud_creds_lock:
        try:
            CLOUD_CREDENTIALS_FILE.parent.mkdir(parents=True, exist_ok=True)
            payload = {
                "version": 1,
                "accounts": list(_cloud_creds.get("accounts") or []),
            }
            _save_json_atomic(CLOUD_CREDENTIALS_FILE, payload)
        except Exception as e:
            print(f"[cloud-creds] save: {e}", flush=True)


def _normalize_cloud_eco(eco: str) -> str:
    e = str(eco or "").strip().lower()
    if e in ("sonoff", "sonoff_diy"):
        return "ewelink"
    if e in ("smart_life", "sl"):
        return "smartlife"
    if e in ("tuya_smart", "tuyasmart"):
        return "tuya"
    if e in ("mi", "mihome", "mi_home", "miio"):
        return "xiaomi"
    return e or "ewelink"


def list_cloud_credentials(
    *, ecosystem: str | None = None, redact: bool = True
) -> list[dict]:
    """List saved cloud app accounts (optionally filter by ecosystem)."""
    with _cloud_creds_lock:
        if not (_cloud_creds.get("accounts") or []):
            _load_cloud_credentials()
        rows = []
        want = _normalize_cloud_eco(ecosystem) if ecosystem else None
        for a in _cloud_creds.get("accounts") or []:
            if not isinstance(a, dict):
                continue
            eco = _normalize_cloud_eco(a.get("ecosystem") or "")
            if want and eco != want:
                continue
            row = {
                "id": str(a.get("id") or ""),
                "ecosystem": eco,
                "email": str(a.get("email") or "").strip(),
                "country": str(a.get("country") or "").strip(),
                "region": str(a.get("region") or "").strip(),
                "label": str(a.get("label") or "").strip(),
                "updated_ts": a.get("updated_ts"),
            }
            if not redact:
                row["password"] = str(a.get("password") or "")
            else:
                row["password_set"] = bool(str(a.get("password") or "").strip())
            if row["id"] and row["email"]:
                rows.append(row)
        # newest first
        rows.sort(key=lambda r: str(r.get("updated_ts") or ""), reverse=True)
        return rows


def upsert_cloud_credential(
    *,
    ecosystem: str,
    email: str,
    password: str | None = None,
    country: str = "",
    region: str = "",
    label: str = "",
) -> dict:
    """
    Save / update cloud app credentials for ecosystem+email(+country).
    Empty password keeps existing password when updating.
    """
    eco = _normalize_cloud_eco(ecosystem)
    email = str(email or "").strip()
    if not email:
        raise ValueError("email required")
    country = str(country or "").strip()
    region = str(region or "").strip()
    label = str(label or "").strip()[:80]
    pw = str(password or "")
    if pw in ("••••", "****", "***"):
        pw = ""
    with _cloud_creds_lock:
        if not (_cloud_creds.get("accounts") or []):
            _load_cloud_credentials()
        accounts = list(_cloud_creds.get("accounts") or [])
        hit = None
        for i, a in enumerate(accounts):
            if not isinstance(a, dict):
                continue
            if _normalize_cloud_eco(a.get("ecosystem")) != eco:
                continue
            if str(a.get("email") or "").strip().lower() != email.lower():
                continue
            # same ecosystem+email; country match preferred, else first
            if country and str(a.get("country") or "").strip() == country:
                hit = i
                break
            if hit is None:
                hit = i
        now = datetime.now().isoformat(timespec="seconds")
        if hit is not None:
            cur = dict(accounts[hit])
            cur["email"] = email
            cur["ecosystem"] = eco
            if country:
                cur["country"] = country
            if region:
                cur["region"] = region
            if label:
                cur["label"] = label
            if pw:
                cur["password"] = pw
            cur["updated_ts"] = now
            if not cur.get("id"):
                cur["id"] = "acc_" + uuid.uuid4().hex[:12]
            accounts[hit] = cur
            out = cur
        else:
            out = {
                "id": "acc_" + uuid.uuid4().hex[:12],
                "ecosystem": eco,
                "email": email,
                "password": pw,
                "country": country,
                "region": region,
                "label": label,
                "updated_ts": now,
            }
            accounts.append(out)
        _cloud_creds["accounts"] = accounts
        _save_cloud_credentials()
        return {
            "id": out["id"],
            "ecosystem": eco,
            "email": email,
            "country": out.get("country") or country,
            "region": out.get("region") or region,
            "label": out.get("label") or label,
            "password_set": bool(str(out.get("password") or "").strip()),
            "updated_ts": out.get("updated_ts"),
        }


def get_cloud_credential_secret(acc_id: str) -> dict | None:
    acc_id = str(acc_id or "").strip()
    if not acc_id:
        return None
    with _cloud_creds_lock:
        if not (_cloud_creds.get("accounts") or []):
            _load_cloud_credentials()
        for a in _cloud_creds.get("accounts") or []:
            if isinstance(a, dict) and str(a.get("id") or "") == acc_id:
                return {
                    "id": acc_id,
                    "ecosystem": _normalize_cloud_eco(a.get("ecosystem")),
                    "email": str(a.get("email") or ""),
                    "password": str(a.get("password") or ""),
                    "country": str(a.get("country") or ""),
                    "region": str(a.get("region") or ""),
                    "label": str(a.get("label") or ""),
                }
    return None


def get_devices_cfg(*, redact: bool = True) -> dict:
    with _devices_cfg_lock:
        # pick up shadow updates written by devices-poller process
        try:
            _load_devices_state()
        except Exception:
            pass
        devices_cfg = json.loads(json.dumps(_devices_cfg.get("devices") or []))
        state_snap = {
            did: dict(st) for did, st in (_devices_state or {}).items()
        }
    devices: list[dict] = []
    for d in devices_cfg:
        did = str(d.get("id") or "")
        st = state_snap.get(did) or {}
        row = _merge_device_runtime(d, st)
        rem = _device_suspend_off_remaining(did) if did else None
        if rem is not None:
            row["auto_off_suspend_in_sec"] = rem
            row["auto_off_suspend_pending"] = True
        else:
            row["auto_off_suspend_in_sec"] = None
            row["auto_off_suspend_pending"] = False
        # Never expose dial tcp / EOF / etc. in API → UI
        if row.get("last_error"):
            row["last_error"] = _device_ui_error(
                row.get("last_error"),
                backend=str(row.get("backend") or ""),
                lang="ru",
            )
        # Device Shadow aliases for UI / API clarity
        row["reported_on"] = row.get("last_on")
        row["desired"] = row.get("desired_on")
        row["reported"] = row.get("last_on")
        devices.append(row)
    if redact:
        for d in devices:
            d["password_set"] = bool(d.get("password"))
            d["ha_token_set"] = bool(d.get("ha_token"))
            d["tuya_local_key_set"] = bool(d.get("tuya_local_key"))
            d["xiaomi_token_set"] = bool(d.get("xiaomi_token"))
            d["ewelink_devicekey_set"] = bool(d.get("ewelink_devicekey"))
            d["ewelink_apikey_set"] = bool(d.get("ewelink_apikey"))
            if d.get("password"):
                d["password"] = ""
            if d.get("ha_token"):
                d["ha_token"] = ""
            if d.get("tuya_local_key"):
                d["tuya_local_key"] = ""
            if d.get("xiaomi_token"):
                d["xiaomi_token"] = ""
            if d.get("ewelink_devicekey"):
                d["ewelink_devicekey"] = ""
            if d.get("ewelink_apikey"):
                d["ewelink_apikey"] = ""
    return {
        "version": 1,
        "poller": get_devices_poller_cfg(),
        "devices": devices,
        "backends": list_filtration_backends(),
        "reserved_aliases": sorted(DEVICE_ALIAS_RESERVED),
        "icons": list(DEVICE_ICON_DEFAULTS),
        "tuya_ecosystems": [
            {"id": "smartlife", "label": "Smart Life"},
            {"id": "tuya", "label": "Tuya Smart"},
            {"id": "classic", "label": "Tuya Smart (classic)"},
            {"id": "houself", "label": "DNS Houself"},
        ],
    }


def list_devices(*, redact: bool = True) -> list[dict]:
    return get_devices_cfg(redact=redact).get("devices") or []


def get_device_by_id(did: str, *, redact: bool = True) -> dict | None:
    did = str(did or "").strip()
    for d in list_devices(redact=redact):
        if d.get("id") == did:
            return d
    return None


def get_device_by_alias(alias: str, *, redact: bool = True) -> dict | None:
    a = str(alias or "").strip().lower()
    for d in list_devices(redact=redact):
        if d.get("alias") == a:
            return d
    return None


def _device_update_in_store(did: str, mutator) -> dict | None:
    """
    Apply mutator to **runtime state** only (devices_state.json).
    Never rewrites devices_config.json — poller-safe.

    Always reloads disk first so concurrent devices-poller writes
    (desired_on / last_on) are not wiped by a stale in-memory snapshot.
    """
    did = str(did or "").strip()
    if not did:
        return None
    with _devices_cfg_lock:
        # pick up poller shadow before we rewrite the whole by_id map
        try:
            _load_devices_state()
        except Exception:
            pass
        exists = any(
            str(d.get("id") or "") == did
            for d in (_devices_cfg.get("devices") or [])
            if isinstance(d, dict)
        )
        if not exists:
            return None
        st = dict(_devices_state.get(did) or _device_runtime_defaults())
        mutator(st)
        _devices_state[did] = _extract_device_runtime(st)
        payload = {
            "version": 1,
            "by_id": {
                k: _extract_device_runtime(v)
                for k, v in _devices_state.items()
                if k
            },
        }
        _save_json_atomic(DEVICES_STATE_FILE, payload)
    return get_device_by_id(did, redact=True)


def upsert_device(raw: dict) -> dict:
    """Create or update a device. Alias must be unique and not reserved."""
    if not isinstance(raw, dict):
        raise ValueError("invalid device")
    alias = str(raw.get("alias") or "").strip().lower()
    if not _device_alias_ok(alias):
        raise ValueError("invalid alias (a-z, a-z0-9_, max 32)")
    if _device_alias_reserved(alias):
        raise ValueError(f"alias reserved: {alias}")
    # merge secrets if UI sent empty password/token and device exists
    existing = None
    existing_st = None
    did = str(raw.get("id") or "").strip()
    with _devices_cfg_lock:
        for d in _devices_cfg.get("devices") or []:
            if did and d.get("id") == did:
                existing = dict(d)
                break
            if not did and d.get("alias") == alias:
                existing = dict(d)
                break
        if existing and existing.get("id"):
            existing_st = dict(
                _devices_state.get(str(existing["id"])) or _device_runtime_defaults()
            )
    merged = dict(raw)
    if existing:
        if not did:
            merged["id"] = existing.get("id")
        # keep secrets when blank / placeholder
        pw = merged.get("password")
        if pw is None or str(pw).strip() in ("", "••••", "****", "***"):
            merged["password"] = existing.get("password") or ""
        tok = merged.get("ha_token")
        if tok is None or str(tok).strip() in ("", "••••", "****", "***"):
            merged["ha_token"] = existing.get("ha_token") or ""
        tlk = merged.get("tuya_local_key") or merged.get("local_key")
        if tlk is None or str(tlk).strip() in ("", "••••", "****", "***"):
            merged["tuya_local_key"] = existing.get("tuya_local_key") or ""
        xtk = merged.get("xiaomi_token") or merged.get("miio_token") or merged.get("token")
        if xtk is None or str(xtk).strip() in ("", "••••", "****", "***"):
            merged["xiaomi_token"] = existing.get("xiaomi_token") or ""
        ewk = merged.get("ewelink_devicekey") or merged.get("devicekey")
        if ewk is None or str(ewk).strip() in ("", "••••", "****", "***"):
            merged["ewelink_devicekey"] = existing.get("ewelink_devicekey") or ""
        ewa = (
            merged.get("ewelink_apikey")
            or merged.get("apikey")
            or merged.get("ewelink_user_apikey")
        )
        if ewa is None or str(ewa).strip() in ("", "••••", "****", "***"):
            merged["ewelink_apikey"] = existing.get("ewelink_apikey") or ""
    # runtime from request or previous state
    rt_in = _extract_device_runtime(merged)
    if existing_st:
        for rk, v in existing_st.items():
            if rt_in.get(rk) is None and v is not None:
                rt_in[rk] = v
    nd = _normalize_device(merged)
    if not nd:
        raise ValueError("invalid device (alias / fields)")
    nd_cfg = _strip_device_runtime(nd)
    # seed desired_on when enabling hold without prior intent
    if nd_cfg.get("enforce_desired") and rt_in.get("desired_on") is None:
        if rt_in.get("last_on") is not None:
            rt_in["desired_on"] = bool(rt_in.get("last_on"))
    with _devices_cfg_lock:
        devices = list(_devices_cfg.get("devices") or [])
        idx = next(
            (i for i, d in enumerate(devices) if d.get("id") == nd_cfg["id"]), None
        )
        for d in devices:
            if d.get("alias") == nd_cfg["alias"] and d.get("id") != nd_cfg["id"]:
                raise ValueError(f"alias already used: {nd_cfg['alias']}")
        if idx is None:
            devices.append(nd_cfg)
        else:
            devices[idx] = nd_cfg
        _devices_cfg["devices"] = devices
        did_f = str(nd_cfg.get("id") or "")
        if did_f:
            _devices_state[did_f] = _extract_device_runtime(rt_in)
            _save_json_atomic(
                DEVICES_STATE_FILE,
                {
                    "version": 1,
                    "by_id": {
                        k: _extract_device_runtime(v)
                        for k, v in _devices_state.items()
                        if k
                    },
                },
            )
    _save_devices_cfg()
    # Persist cloud app login for this ecosystem (suggest later in UI)
    try:
        be = str(nd_cfg.get("backend") or "").lower()
        email = str(nd_cfg.get("email") or "").strip()
        pw = str(nd_cfg.get("password") or "").strip()
        if email and pw and be in (
            "ewelink",
            "sonoff",
            "sonoff_diy",
            "tuya",
            "smartlife",
            "tapo",
        ):
            eco = "ewelink" if be in ("ewelink", "sonoff", "sonoff_diy") else be
            if be == "smartlife":
                eco = "smartlife"
            country = ""
            region = ""
            if eco == "ewelink":
                country = str(nd_cfg.get("ewelink_country") or "+7")
                region = str(nd_cfg.get("ewelink_region") or "")
            elif eco in ("tuya", "smartlife"):
                country = str(nd_cfg.get("tuya_country") or "7")
                region = str(nd_cfg.get("tuya_region") or "")
                eco = str(nd_cfg.get("tuya_ecosystem") or eco)
            upsert_cloud_credential(
                ecosystem=eco,
                email=email,
                password=pw,
                country=country,
                region=region,
            )
    except Exception as ce:
        print(f"[cloud-creds] upsert on device save: {ce}", flush=True)
    out = get_device_by_id(nd_cfg["id"], redact=True)
    return out or _merge_device_runtime(nd_cfg, rt_in)


def delete_device(did: str) -> bool:
    did = str(did or "").strip()
    with _devices_cfg_lock:
        devices = list(_devices_cfg.get("devices") or [])
        new = [d for d in devices if d.get("id") != did]
        if len(new) == len(devices):
            return False
        _devices_cfg["devices"] = new
        _devices_state.pop(did, None)
        _save_json_atomic(
            DEVICES_STATE_FILE,
            {
                "version": 1,
                "by_id": {
                    k: _extract_device_runtime(v)
                    for k, v in _devices_state.items()
                    if k
                },
            },
        )
    _save_devices_cfg()
    _devices_sync_ts.pop(did, None)
    _devices_suspend_off_deadline.pop(did, None)
    return True


def replace_devices(devices_list: list) -> list[dict]:
    clean: list[dict] = []
    seen: set[str] = set()
    new_state: dict[str, dict] = {}
    for d in devices_list or []:
        if not isinstance(d, dict):
            continue
        rt = _extract_device_runtime(d)
        nd = _normalize_device(d)
        if not nd or nd["alias"] in seen:
            continue
        seen.add(nd["alias"])
        cfg_row = _strip_device_runtime(nd)
        clean.append(cfg_row)
        did = str(cfg_row.get("id") or "")
        if did:
            # keep prior state if restore had no runtime
            with _devices_cfg_lock:
                prev = _devices_state.get(did) or _device_runtime_defaults()
            merged_rt = dict(prev)
            for k, v in rt.items():
                if v is not None:
                    merged_rt[k] = v
            new_state[did] = _extract_device_runtime(merged_rt)
    with _devices_cfg_lock:
        _devices_cfg["devices"] = clean
        # drop state for removed ids; keep/update for present
        next_state: dict[str, dict] = {}
        for d in clean:
            did = str(d.get("id") or "")
            if not did:
                continue
            if did in new_state:
                next_state[did] = new_state[did]
            elif did in _devices_state:
                next_state[did] = _extract_device_runtime(_devices_state[did])
            else:
                next_state[did] = _device_runtime_defaults()
        _devices_state.clear()
        _devices_state.update(next_state)
        _save_json_atomic(
            DEVICES_STATE_FILE,
            {
                "version": 1,
                "by_id": {
                    k: _extract_device_runtime(v)
                    for k, v in _devices_state.items()
                    if k
                },
            },
        )
    _save_devices_cfg()
    return list_devices(redact=True)


def reorder_devices(ids: list) -> list[dict]:
    """Reorder devices by id list (unknown ignored; missing stay at end)."""
    want = [str(i).strip() for i in (ids or []) if str(i).strip()]
    with _devices_cfg_lock:
        devices = list(_devices_cfg.get("devices") or [])
        by_id = {str(d.get("id")): d for d in devices if d.get("id")}
        ordered: list[dict] = []
        seen: set[str] = set()
        for did in want:
            if did in by_id and did not in seen:
                ordered.append(_strip_device_runtime(by_id[did]))
                seen.add(did)
        for d in devices:
            did = str(d.get("id") or "")
            if did and did not in seen:
                ordered.append(_strip_device_runtime(d))
                seen.add(did)
        _devices_cfg["devices"] = ordered
    _save_devices_cfg()
    return list_devices(redact=True)


def _device_cfg_snapshot(did: str) -> dict | None:
    """Config + runtime for one device (policy / backends)."""
    did = str(did or "").strip()
    with _devices_cfg_lock:
        for d in _devices_cfg.get("devices") or []:
            if d.get("id") == did:
                st = _devices_state.get(did) or _device_runtime_defaults()
                return _merge_device_runtime(dict(d), st)
    return None


def _device_backend_dispatch(on: bool | None, cfg: dict) -> dict:
    """
    on=None read; else set physical state.

    **All** LAN device I/O goes through Go devices-poller (device_req IPC).
    serve must not import/call tinytuya, ewelink_lan, Tapo KLAP, etc. at runtime —
    those backends live only in poolheat-devices-poller.
    """
    be = str(cfg.get("backend") or "tapo").lower()
    if be in ("smartlife", "smart_life"):
        be = "tuya"
    if be in ("mi", "mihome", "mi_home", "miio", "mijia"):
        be = "xiaomi"
    if be in ("sonoff", "sonoff_diy"):
        be = "ewelink"
    if be in ("ha",):
        be = "homeassistant"
    # device_set passes logical via _logical_on; status has on=None.
    # Light extras: _set_brightness (0–100), _set_mode (white|colour|…).
    bright_i = None
    if cfg.get("_set_brightness") is not None:
        try:
            bright_i = max(0, min(100, int(cfg.get("_set_brightness"))))
        except (TypeError, ValueError):
            bright_i = None
    mode_s = str(cfg.get("_set_mode") or "").strip().lower() or None
    if mode_s == "color":
        mode_s = "colour"
    if mode_s and mode_s not in ("white", "colour", "scene", "music"):
        mode_s = None
    return _device_control_via_poller(
        on,
        cfg,
        backend_hint=be,
        brightness=bright_i,
        mode=mode_s,
    )


def _device_logical_to_physical(logical_on: bool, inverted: bool) -> bool:
    return (not logical_on) if inverted else bool(logical_on)


def _device_physical_to_logical(physical_on: bool, inverted: bool) -> bool:
    return (not physical_on) if inverted else bool(physical_on)


def _ha_attrs_to_power(attrs: dict) -> dict | None:
    """Extract power metrics from Home Assistant entity attributes when present."""
    if not isinstance(attrs, dict):
        return None
    out: dict = {}
    # current power in W
    for k in (
        "current_power_w",
        "power",
        "power_w",
        "current_consumption",
        "load_power",
    ):
        if attrs.get(k) is not None:
            try:
                out["power_w"] = round(float(attrs[k]), 2)
                break
            except (TypeError, ValueError):
                pass
    for k in ("voltage", "voltage_v"):
        if attrs.get(k) is not None:
            try:
                out["voltage_v"] = round(float(attrs[k]), 2)
                break
            except (TypeError, ValueError):
                pass
    for k in ("current", "current_a", "amperage"):
        if attrs.get(k) is not None:
            try:
                out["current_a"] = round(float(attrs[k]), 3)
                break
            except (TypeError, ValueError):
                pass
    for k in ("energy", "total_energy", "energy_kwh"):
        if attrs.get(k) is not None:
            try:
                out["energy_kwh"] = round(float(attrs[k]), 3)
                break
            except (TypeError, ValueError):
                pass
    return out or None


def _tuya_dps_to_power(dps: dict) -> dict | None:
    """
    Parse common Tuya metering DPS into SI units.
    FinePower PLG-1 / many plugs: 18=mA, 19=0.1W, 20=0.1V.
    Older maps: 4/5/6. Total energy often 17 or 23 (0.01 kWh or Wh).
    """
    if not isinstance(dps, dict) or not dps:
        return None
    # normalize keys to str
    d = {str(k): v for k, v in dps.items()}

    def _num(key: str):
        if key not in d or d[key] is None:
            return None
        try:
            return float(d[key])
        except (TypeError, ValueError):
            return None

    # Prefer modern 18/19/20 map when any present
    raw_i = _num("18")
    raw_p = _num("19")
    raw_v = _num("20")
    if raw_i is None and raw_p is None and raw_v is None:
        raw_i = _num("4")
        raw_p = _num("5")
        raw_v = _num("6")

    if raw_i is None and raw_p is None and raw_v is None:
        # only energy total?
        for ek in ("17", "23", "25", "9"):
            pass
        raw_e = _num("17")
        if raw_e is None:
            raw_e = _num("23")
        if raw_e is None:
            return None
        # heuristic: values often 0.01 kWh units
        out_e = {"energy_kwh": round(raw_e / 100.0, 3) if raw_e > 50 else round(raw_e, 3)}
        return out_e

    voltage_v = None
    current_a = None
    power_w = None

    if raw_v is not None:
        # 2300 → 230.0 V; raw 230 also ok
        voltage_v = raw_v / 10.0 if raw_v > 400 else raw_v
    if raw_i is not None:
        # mA → A (values like 350 for 0.35 A, or 3500)
        current_a = raw_i / 1000.0 if raw_i > 30 else raw_i
    if raw_p is not None:
        p_deci = raw_p / 10.0
        p_raw = raw_p
        # Choose scale by cross-check with V·I when possible
        if voltage_v is not None and current_a is not None and (voltage_v * current_a) > 0.5:
            vi = voltage_v * current_a
            if abs(p_deci - vi) <= abs(p_raw - vi):
                power_w = p_deci
            else:
                power_w = p_raw
        else:
            # typical monitoring plugs use deciwatts when voltage is deci-volts
            if raw_v is not None and raw_v > 400:
                power_w = p_deci
            else:
                power_w = p_raw

    out: dict = {}
    if power_w is not None:
        out["power_w"] = round(max(0.0, float(power_w)), 2)
    if voltage_v is not None:
        out["voltage_v"] = round(float(voltage_v), 2)
    if current_a is not None:
        out["current_a"] = round(max(0.0, float(current_a)), 3)

    raw_e = _num("17")
    if raw_e is None:
        raw_e = _num("23")
    if raw_e is not None and raw_e >= 0:
        # common: 0.01 kWh; if already small treat as kWh
        out["energy_kwh"] = (
            round(raw_e / 100.0, 3) if raw_e > 50 else round(raw_e, 3)
        )
    return out or None


def _normalize_power_metrics(power: dict | None) -> dict | None:
    if not isinstance(power, dict):
        return None
    out: dict = {}
    for k, digits in (
        ("power_w", 2),
        ("voltage_v", 2),
        ("current_a", 3),
        ("energy_kwh", 3),
        ("energy_today_kwh", 3),
    ):
        if power.get(k) is None:
            continue
        try:
            out[k] = round(float(power[k]), digits)
        except (TypeError, ValueError):
            continue
    return out or None


def _power_from_backend_out(out: dict | None) -> dict | None:
    if not isinstance(out, dict):
        return None
    if isinstance(out.get("power"), dict):
        return _normalize_power_metrics(out.get("power"))
    dps = out.get("dps")
    if isinstance(dps, dict):
        return _normalize_power_metrics(_tuya_dps_to_power(dps))
    return None


def _device_ready(cfg: dict) -> bool:
    be = str(cfg.get("backend") or "tapo").lower()
    if be in ("smartlife", "smart_life"):
        be = "tuya"
    if be in ("mi", "mihome", "mi_home", "miio", "mijia"):
        be = "xiaomi"
    if be == "tapo":
        return bool(str(cfg.get("ip") or "").strip())
    if be == "ewelink":
        ip_ok = bool(str(cfg.get("ip") or "").strip())
        id_ok = bool(str(cfg.get("device_id") or "").strip())
        mode = str(cfg.get("ewelink_mode") or "auto").lower()
        key_ok = bool(str(cfg.get("ewelink_devicekey") or "").strip())
        if mode == "lan":
            return ip_ok and id_ok and key_ok
        # auto/diy: IP+deviceid enough; key optional for encrypt
        return ip_ok and id_ok
    if be == "webhook":
        return bool(
            str(cfg.get("webhook_on_url") or "").strip()
            or str(cfg.get("webhook_off_url") or "").strip()
        )
    if be == "shelly":
        return bool(str(cfg.get("ip") or "").strip())
    if be in ("homeassistant", "ha"):
        return bool(
            str(cfg.get("ha_url") or "").strip()
            and str(cfg.get("ha_entity_id") or "").strip()
        )
    if be == "tuya":
        return bool(
            str(cfg.get("ip") or "").strip()
            and str(cfg.get("device_id") or "").strip()
            and (
                str(cfg.get("tuya_local_key") or "").strip()
                or (
                    str(cfg.get("email") or "").strip()
                    and str(cfg.get("password") or "").strip()
                )
            )
        )
    if be == "xiaomi":
        return bool(
            str(cfg.get("ip") or "").strip()
            and str(cfg.get("xiaomi_token") or "").strip()
        )
    return False


# ── Xiaomi / Mi Home LAN (miIO UDP 54321) ─────────────────────────────────────

def _device_backend_xiaomi(on: bool | None, cfg: dict) -> dict:
    """Deprecated: use _device_backend_dispatch → poller only."""
    return _device_control_via_poller(on, cfg, backend_hint="xiaomi")


def _device_backend_xiaomi_legacy_unused(on: bool | None, cfg: dict) -> dict:
    """
    LAN control via miIO (UDP 54321). Needs IP + 32-hex token.
    Token once (extractor / HA / cloud tools) — no ongoing cloud dependency.
    """
    ip = str(cfg.get("ip") or "").strip()
    if not ip:
        raise RuntimeError("Xiaomi IP не настроен")
    token = str(cfg.get("xiaomi_token") or "").strip()
    if not token:
        raise RuntimeError(
            "Xiaomi token пуст (32 hex) — token extractor / HA / cloud tools"
        )
    try:
        from xiaomi_miio import control as xiaomi_control  # type: ignore
    except ImportError as e:
        raise RuntimeError(
            "xiaomi_miio module missing — reinstall poolheat package"
        ) from e
    try:
        out = xiaomi_control(ip, token, on, timeout=6.0)
    except ValueError as e:
        raise RuntimeError(str(e)) from e
    except Exception as e:
        low = str(e).lower()
        if "token" in low or "decrypt" in low:
            raise RuntimeError(f"Xiaomi token/ключ: {e}") from e
        if "timeout" in low or "timed out" in low:
            raise RuntimeError(f"Xiaomi недоступен ({ip}:54321): {e}") from e
        raise RuntimeError(f"Xiaomi: {e}") from e
    # cache model if discovered
    model = out.get("model")
    if model and not cfg.get("xiaomi_model"):
        did = str(cfg.get("id") or "")
        if did:
            def _mut(d, m=model):
                d["xiaomi_model"] = m

            try:
                _device_update_in_store(did, _mut)
            except Exception:
                pass
        cfg["xiaomi_model"] = model
        out["xiaomi_model"] = model
    return out


# ── Tuya / Smart Life LAN (tinytuya + mobile login for local_key) ────────────

def _tuya_persist_key_to_config(
    store_id: str,
    *,
    local_key: str,
    device_id: str | None = None,
    ip: str | None = None,
) -> None:
    """Write local_key into devices_config.json (poller reads this, not runtime state)."""
    did = str(store_id or "").strip()
    key = str(local_key or "").strip()
    if not did or not key:
        return
    try:
        with _devices_cfg_lock:
            for d in _devices_cfg.get("devices") or []:
                if not isinstance(d, dict):
                    continue
                if str(d.get("id") or "") != did:
                    continue
                d["tuya_local_key"] = key
                if device_id:
                    d["device_id"] = str(device_id)
                if ip and not str(d.get("ip") or "").strip():
                    d["ip"] = str(ip)
                break
            _save_devices_cfg()
        print(f"[devices] tuya local_key saved to config for {did}", flush=True)
    except Exception as e:
        print(f"[devices] tuya local_key persist: {e}", flush=True)


def _tuya_ensure_local_key(cfg: dict, *, force: bool = False) -> str:
    """
    Return local_key for device. Refresh via mobile API if missing
    (or force=True) and email/password present. Persists into devices_config.
    """
    key = str(cfg.get("tuya_local_key") or "").strip()
    if key and not force:
        return key
    email = str(cfg.get("email") or "").strip()
    password = str(cfg.get("password") or "")
    if not email or not password:
        if key:
            return key
        raise RuntimeError(
            "Tuya: нужен local_key или email/password Smart Life / Tuya Smart"
        )
    try:
        from tuya_mobile import login_and_find_device  # type: ignore
    except ImportError as e:
        raise RuntimeError(
            "tuya_mobile module missing — reinstall poolheat package"
        ) from e
    dev_id = str(cfg.get("device_id") or "").strip()
    tip = str(cfg.get("ip") or "").strip()
    out = login_and_find_device(
        email,
        password,
        device_id=dev_id or None,
        ip=tip or None,
        country=str(cfg.get("tuya_country") or "7"),
        region=str(cfg.get("tuya_region") or "eu"),
        ecosystem=str(cfg.get("tuya_ecosystem") or "smartlife"),
    )
    found = out.get("match") if isinstance(out.get("match"), dict) else None
    n = int(out.get("device_count") or 0)
    if not found or not found.get("key"):
        raise RuntimeError(
            f"Tuya: local_key не найден для device_id={dev_id or '—'} "
            f"ip={tip or '—'} (аккаунт: {n} устр.)"
        )
    key = str(found["key"])
    cloud_id = str(found.get("id") or "").strip() or None
    cloud_ip = str(found.get("ip") or "").strip() or None
    store_id = str(cfg.get("id") or "").strip()
    if store_id:
        _tuya_persist_key_to_config(
            store_id, local_key=key, device_id=cloud_id, ip=cloud_ip
        )
    cfg["tuya_local_key"] = key
    if cloud_id:
        cfg["device_id"] = cloud_id
    return key


_device_cmd_ipc_lock = threading.Lock()


def _device_control_via_poller(
    on: bool | None,
    cfg: dict,
    *,
    backend_hint: str = "",
    timeout_sec: float = 22.0,
    brightness: int | None = None,
    mode: str | None = None,
) -> dict:
    """
    Enqueue device_req.json for Go devices-poller (all LAN backends).
    serve never imports tinytuya.

    brightness: 0–100 % for lights/dimmers (optional)
    mode: white|colour|scene|music (optional)
    """
    if not devices_poller_process_alive():
        raise RuntimeError(
            "devices-poller not running — device LAN control only via poller "
            "(no tinytuya in serve)"
        )
    did = str(cfg.get("id") or "").strip()
    if not did:
        raise RuntimeError("device id missing")
    req_id = uuid.uuid4().hex
    req: dict = {
        "id": req_id,
        "ts": time.time(),
        "device_id": did,
        "on": on,  # None = status; bool = set (logical when _logical_on)
        "source": "serve",
        "force": True,
    }
    # Caller passes physical for set paths that already applied inverted.
    # device_set uses logical; backends use physical. Align with poller SetLogical:
    # we pass logical via a flag when present on cfg.
    if on is not None and "_logical_on" in cfg:
        req["on"] = bool(cfg["_logical_on"])
    if brightness is not None:
        try:
            b = int(brightness)
            req["brightness"] = max(0, min(100, b))
        except (TypeError, ValueError):
            pass
    if mode is not None and str(mode).strip():
        req["mode"] = str(mode).strip().lower()
    # light-only set (brightness/mode) is still a set even if on is None
    with _device_cmd_ipc_lock:
        try:
            if DEVICE_RESULT_FILE.is_file():
                DEVICE_RESULT_FILE.unlink()
        except Exception:
            pass
        _write_json_atomic(DEVICE_REQ_FILE, req)
        deadline = time.time() + max(3.0, float(timeout_sec))
        last_err = "timeout waiting for devices-poller"
        while time.time() < deadline:
            time.sleep(0.12)
            try:
                if not DEVICE_RESULT_FILE.is_file():
                    if not devices_poller_process_alive():
                        raise RuntimeError("devices-poller died during command")
                    continue
                raw = json.loads(DEVICE_RESULT_FILE.read_text(encoding="utf-8"))
                if not isinstance(raw, dict) or str(raw.get("id") or "") != req_id:
                    continue
                if not raw.get("ok"):
                    raise RuntimeError(str(raw.get("error") or "device command failed"))
                out = {
                    "on": raw.get("on"),
                    "on_is_logical": True,
                    "backend": raw.get("backend") or backend_hint or cfg.get("backend"),
                    "ip": cfg.get("ip"),
                    "device_id": cfg.get("device_id") or did,
                    "transport": "devices-poller",
                }
                if raw.get("skipped"):
                    out["skipped"] = True
                    out["reason"] = raw.get("reason") or "already_in_state"
                if isinstance(raw.get("power"), dict):
                    out["power"] = raw["power"]
                if raw.get("brightness") is not None:
                    try:
                        out["brightness"] = int(raw["brightness"])
                    except (TypeError, ValueError):
                        pass
                if raw.get("mode"):
                    out["mode"] = str(raw["mode"])
                if isinstance(raw.get("extra"), dict):
                    out.update({k: v for k, v in raw["extra"].items() if k not in out})
                return out
            except RuntimeError:
                raise
            except Exception as e:
                last_err = str(e)
                continue
        raise RuntimeError(last_err)


def _device_backend_tuya(on: bool | None, cfg: dict) -> dict:
    """
    Tuya LAN — only via devices-poller (no tinytuya in serve).
    Status: on=None; set: on=True/False (physical already resolved by caller).
    Optional light fields on cfg: _set_brightness (0–100), _set_mode.

    Ensures local_key is present (cloud auto-fetch when email/password set).
    On sess/hmac failures, refreshes key once and retries.
    """
    bright = cfg.get("_set_brightness")
    mode = cfg.get("_set_mode")
    try:
        bright_i = int(bright) if bright is not None else None
    except (TypeError, ValueError):
        bright_i = None
    mode_s = str(mode).strip() if mode else None

    # Ensure key before poller (auto-fetch like eWeLink when missing)
    try:
        _tuya_ensure_local_key(cfg, force=False)
    except Exception as e:
        print(f"[devices] tuya ensure key: {e}", flush=True)

    def _call() -> dict:
        return _device_control_via_poller(
            on,
            cfg,
            backend_hint="tuya",
            brightness=bright_i,
            mode=mode_s or None,
        )

    try:
        return _call()
    except Exception as e:
        low = str(e).lower()
        # Stale local_key / wrong session → refresh from cloud once
        retryable = any(
            x in low
            for x in (
                "sess hmac",
                "sess resp decrypt",
                "wrong key",
                "local_key",
                "decrypt",
                "session key",
            )
        )
        email = str(cfg.get("email") or "").strip()
        password = str(cfg.get("password") or "")
        if not retryable or not email or not password:
            raise
        print(
            f"[devices] tuya control fail ({e}); refreshing local_key…",
            flush=True,
        )
        try:
            _tuya_ensure_local_key(cfg, force=True)
        except Exception as re:
            print(f"[devices] tuya key refresh fail: {re}", flush=True)
            raise e from re
        return _call()


def tuya_refresh_device_keys(
    *,
    email: str,
    password: str,
    country: str = "7",
    region: str = "eu",
    ecosystem: str = "smartlife",
    device_store_id: str | None = None,
    target_device_id: str | None = None,
    target_ip: str | None = None,
    slim: bool = True,
) -> dict:
    """
    Login to Smart Life / Tuya mobile API.

    Default slim=True (eWeLink-style): auto-match one device by
    device_id / IP / single-device account — no full inventory for UI.
    """
    from tuya_mobile import login_and_find_device, ecosystems  # type: ignore

    store_id = str(device_store_id or "").strip()
    want_id = str(target_device_id or "").strip()
    want_ip = str(target_ip or "").strip()
    # Prefer store snapshot when editing an existing device
    if store_id:
        cfg = _device_cfg_snapshot(store_id) or {}
        if not want_id:
            want_id = str(cfg.get("device_id") or "").strip()
        if not want_ip:
            want_ip = str(cfg.get("ip") or "").strip()
        if not email:
            email = str(cfg.get("email") or "").strip()
        if not password:
            password = str(cfg.get("password") or "")

    out = login_and_find_device(
        email,
        password,
        device_id=want_id or None,
        ip=want_ip or None,
        country=country,
        region=region,
        ecosystem=ecosystem,
    )
    match_raw = out.get("match") if isinstance(out.get("match"), dict) else None
    match = None
    if match_raw and match_raw.get("key"):
        match = {
            "id": match_raw.get("id"),
            "device_id": match_raw.get("id"),
            "key": match_raw.get("key"),
            "local_key": match_raw.get("key"),
            "name": match_raw.get("name"),
            "online": match_raw.get("online"),
            "product_id": match_raw.get("product_id"),
            "mac": match_raw.get("mac"),
            "ip": match_raw.get("ip"),
            "home": match_raw.get("home"),
            "key_set": True,
        }
        if store_id:
            _tuya_persist_key_to_config(
                store_id,
                local_key=str(match["key"]),
                device_id=str(match.get("id") or "") or None,
                ip=str(match.get("ip") or "") or None,
            )
            # also stamp runtime so UI sees key_set without reload race
            def _mut(x, key=match["key"], did=match.get("id")):
                x["tuya_local_key"] = key
                if did:
                    x["device_id"] = did

            try:
                _device_update_in_store(store_id, _mut)
            except Exception:
                pass

    n_dev = int(out.get("device_count") or 0)
    if slim:
        return {
            "ok": True,
            "slim": True,
            "device_count": n_dev,
            "match": match,
            "ecosystems": ecosystems(),
        }

    # Full list only when explicitly requested (debug / advanced)
    safe = []
    for d in out.get("devices") or []:
        if not isinstance(d, dict):
            continue
        safe.append(
            {
                "name": d.get("name"),
                "id": d.get("id"),
                "key_set": bool(d.get("key")),
                "key": d.get("key"),
                "product_id": d.get("product_id"),
                "home": d.get("home"),
                "online": d.get("online"),
                "mac": d.get("mac"),
                "ip": d.get("ip"),
            }
        )
    return {
        "ok": True,
        "slim": False,
        "devices": safe,
        "count": len(safe),
        "device_count": n_dev,
        "match": match,
        "ecosystems": ecosystems(),
    }


def _mining_work_state() -> str | None:
    """'resume' | 'suspend' | None from cache / policy (no miner I/O)."""
    try:
        with _cache_lock:
            if isinstance(_cache, dict) and _cache.get("ok"):
                w = _live_work(dict(_cache))
                if w:
                    return str(w).lower()
    except Exception:
        pass
    try:
        with _policy_lock:
            mw = str(_policy_ctrl.get("measured_work") or "").strip().lower()
        if mw in ("resume", "mining"):
            return "resume"
        if mw in ("suspend", "sleep"):
            return "suspend"
    except Exception:
        pass
    return None


# Throttle enforce_desired re-apply (per device).
# Keep short: poller interval is often 5s — 15s made "second restore" feel stuck.
_devices_enforce_ts: dict[str, float] = {}
_devices_enforce_last_reported: dict[str, bool] = {}
_DEVICES_ENFORCE_COOLDOWN_SEC = 3.0


def _device_enforce_cooldown_sec() -> float:
    """Min gap between restore attempts (Advanced → enforce_cooldown_sec)."""
    try:
        pol = get_devices_poller_cfg()
        if "enforce_cooldown_sec" in pol:
            return max(0.0, min(60.0, float(pol.get("enforce_cooldown_sec") or 0)))
        iv = float(pol.get("hold_interval_sec") or pol.get("interval_sec") or 5)
    except Exception:
        iv = 3.0
    return max(0.0, min(60.0, iv))


def _device_enforce_desired(
    did: str,
    reported: bool | None,
    *,
    use_timeout: bool = False,
) -> dict | None:
    """
    If enforce_desired is on and reported ≠ desired_on, re-apply desired (force).
    Returns device_set result or None if skipped.
    """
    if reported is None:
        return None
    cfg = _device_cfg_snapshot(did)
    if not cfg or not cfg.get("enabled"):
        return None
    if not bool(cfg.get("enforce_desired")):
        return None
    desired = cfg.get("desired_on")
    if desired is None:
        # seed from first successful probe so hold has a target
        def _seed(d):
            d["desired_on"] = bool(reported)

        _device_update_in_store(did, _seed)
        return None
    if bool(reported) is bool(desired):
        # matched — clear cooldown bookkeeping for next external flip
        _devices_enforce_last_reported.pop(did, None)
        return None
    now = time.time()
    last = float(_devices_enforce_ts.get(did) or 0)
    cool = _device_enforce_cooldown_sec()
    # If reported flipped again since last enforce attempt, allow immediately
    # (user toggled SmartLife twice) — only throttle same stuck mismatch.
    prev_rep = _devices_enforce_last_reported.get(did)
    same_mismatch = prev_rep is not None and bool(prev_rep) is bool(reported)
    if same_mismatch and (now - last) < cool:
        return None
    _devices_enforce_ts[did] = now
    _devices_enforce_last_reported[did] = bool(reported)
    alias = str(cfg.get("alias") or did)
    # Event log is English (same as policy log)
    name = (
        str(cfg.get("name_en") or cfg.get("name") or cfg.get("name_ru") or alias)
        .strip()
        or alias
    )
    driver = _device_driver_label(cfg.get("backend"))
    who = f"{name} ({driver})" if driver else name
    want_on = bool(desired)
    was_on = bool(reported)
    try:
        print(
            f"[devices] enforce desired {alias}"
            f"{f'/{driver}' if driver else ''}: "
            f"reported={'ON' if was_on else 'OFF'} → "
            f"desired={'ON' if want_on else 'OFF'}",
            flush=True,
        )
        if use_timeout:
            res = _device_set_with_timeout(
                did, want_on, source="enforce_desired"
            )
        else:
            res = device_set(
                did, want_on, source="enforce_desired", force=True
            )
        # event log (UI Events) when restore actually ran
        if isinstance(res, dict) and res.get("ok") and not res.get("skipped"):
            want_s = "ON" if want_on else "OFF"
            was_s = "ON" if was_on else "OFF"
            _devices_event_log(
                "device",
                f"{who}: restored {want_s} "
                f"(was {was_s}, external change)",
                source="enforce_desired",
                device_id=did,
                alias=alias,
                backend=str(cfg.get("backend") or "") or None,
                driver=driver or None,
                desired_on=want_on,
                reported_on=was_on,
            )
        return res
    except Exception as e:
        print(
            f"[devices] enforce desired {alias}"
            f"{f'/{driver}' if driver else ''}: {e}",
            flush=True,
        )
        _devices_event_log(
            "err",
            f"{who}: failed to restore "
            f"{'ON' if want_on else 'OFF'}: {e}",
            source="enforce_desired",
            device_id=did,
            alias=alias,
            backend=str(cfg.get("backend") or "") or None,
            driver=driver or None,
        )
        return None


def _devices_event_log(kind: str, msg: str, **extra) -> None:
    """
    Append to policy Events log. Safe for devices-poller process:
    merges with policy_events.json on disk so we don't wipe main-process events.
    """
    ev = {
        "ts": datetime.now().isoformat(timespec="seconds"),
        "kind": str(kind or "device"),
        "msg": str(msg or "")[:400],
        **{k: v for k, v in extra.items() if v is not None},
    }
    print(f"[devices] {ev['ts']} {ev['kind']}: {ev['msg']}", flush=True)
    try:
        mx = 200
        try:
            mx = int(get_event_log_max())
        except Exception:
            try:
                mx = int(POLICY_EVENTS_MAX_DEFAULT)
            except Exception:
                mx = 200
        mx = max(20, min(5000, mx))
        # merge disk + in-memory (main) so poller/main don't clobber each other
        disk_evs: list = []
        try:
            raw = _load_json(POLICY_EVENTS_FILE, {})
            if isinstance(raw, dict) and isinstance(raw.get("events"), list):
                disk_evs = [e for e in raw["events"] if isinstance(e, dict)]
        except Exception:
            disk_evs = []
        mem_evs: list = []
        try:
            with _policy_lock:
                mem_evs = [
                    e
                    for e in (_policy_ctrl.get("events") or [])
                    if isinstance(e, dict)
                ]
        except Exception:
            mem_evs = []
        # newest first; de-dupe by ts+kind+msg
        seen: set[str] = set()
        merged: list = []
        for e in [ev] + mem_evs + disk_evs:
            key = (
                f"{e.get('ts')}|{e.get('kind')}|{e.get('msg')}"
            )
            if key in seen:
                continue
            seen.add(key)
            merged.append(e)
            if len(merged) >= mx:
                break
        try:
            with _policy_lock:
                _policy_ctrl["events"] = list(merged)
                _policy_ctrl["last_event"] = merged[0] if merged else None
        except Exception:
            pass
        try:
            _save_json(POLICY_EVENTS_FILE, {"events": merged, "max": mx})
        except Exception as se:
            print(f"[devices] event log save: {se}", flush=True)
    except Exception as e:
        print(f"[devices] event log: {e}", flush=True)


def _device_adopt_reported(did: str, reported: bool | None) -> None:
    """When enforce is off: desired tracks reported (accept external changes)."""
    if reported is None:
        return
    cfg = _device_cfg_snapshot(did)
    if not cfg:
        return
    if bool(cfg.get("enforce_desired")):
        return
    cur = cfg.get("desired_on")
    if cur is not None and bool(cur) is bool(reported):
        return

    def _mut(d):
        d["desired_on"] = bool(reported)

    _device_update_in_store(did, _mut)


def device_poll_status(
    did: str,
    *,
    source: str = "poll",
    apply_policy: bool = True,
    use_timeout_for_enforce: bool = False,
) -> dict:
    """
    Poll live device status into store.

    Updates:
      - last_on / reported (observed logical ON/OFF)
      - online, last_ok_ts / last_error
      - last_power (W/V/A when backend provides it)

    Policy (apply_policy=True):
      - enforce_desired ON  → if reported ≠ desired, re-apply desired
      - enforce_desired OFF → desired follows reported
    """
    cfg = _device_cfg_snapshot(did)
    if not cfg:
        return {"ok": False, "error": "device not found"}
    be = str(cfg.get("backend") or "tapo")
    try:
        out = _device_backend_dispatch(None, cfg)
        reported = None
        phys = None
        inverted = bool(cfg.get("inverted"))
        if out.get("transport") == "devices-poller" or out.get("on_is_logical"):
            # poller returns logical on
            if out.get("on") is not None:
                reported = bool(out.get("on"))
                phys = _device_logical_to_physical(reported, inverted)
        else:
            phys = out.get("on")
            if phys is not None:
                reported = _device_physical_to_logical(bool(phys), inverted)
        power = _power_from_backend_out(out)

        def _mut(d):
            if reported is not None:
                d["last_on"] = bool(reported)
            d["online"] = True
            d["last_error"] = None
            d["last_ok_ts"] = datetime.now().isoformat(timespec="seconds")
            d["last_action"] = f"{source}:{be}"
            if power:
                d["last_power"] = power
                d["last_power_ts"] = datetime.now().isoformat(timespec="seconds")
            # lights / dimmers only — never store eWeLink protocol mode (lan/diy)
            # as last_mode (UI treats last_mode as light mode → false dimmer UI).
            br = out.get("brightness")
            if br is None and out.get("brightness_pct") is not None:
                br = out.get("brightness_pct")
            if br is not None:
                try:
                    d["last_brightness"] = max(0, min(100, int(br)))
                except (TypeError, ValueError):
                    pass
            mode_raw = str(out.get("mode") or "").strip().lower()
            if mode_raw in ("white", "colour", "color", "scene", "music"):
                d["last_mode"] = "colour" if mode_raw == "color" else mode_raw
            tel = {}
            for k in (
                "brightness_raw",
                "brightness_pct",
                "mode",
                "colour_data",
                "dps",
                "switch_dps_used",
            ):
                if k in out and out[k] is not None:
                    tel[k] = out[k]
            if tel:
                d["last_telemetry"] = tel

        _device_update_in_store(did, _mut)

        enforced = None
        if apply_policy and reported is not None:
            if bool(cfg.get("enforce_desired")):
                enforced = _device_enforce_desired(
                    did,
                    reported,
                    use_timeout=use_timeout_for_enforce,
                )
                if isinstance(enforced, dict) and enforced.get("ok"):
                    # after re-apply, reported should match desired
                    if enforced.get("on") is not None:
                        reported = bool(enforced.get("on"))
                        phys = _device_logical_to_physical(reported, inverted)
            else:
                _device_adopt_reported(did, reported)

        snap = _device_cfg_snapshot(did) or cfg
        ret = {
            "ok": True,
            "id": did,
            "backend": be,
            "on": reported,
            "reported_on": reported,
            "desired_on": snap.get("desired_on"),
            "online": True,
            "physical_on": phys,
            "enforce_desired": bool(snap.get("enforce_desired")),
            **{k: v for k, v in out.items() if k not in ("on",)},
        }
        if power:
            ret["power"] = power
        if isinstance(enforced, dict):
            ret["enforced"] = True
            ret["enforce_result"] = {
                "ok": enforced.get("ok"),
                "on": enforced.get("on"),
                "skipped": enforced.get("skipped"),
                "error": enforced.get("error"),
            }
        return ret
    except Exception as e:
        print(f"[devices] {did} {source} fail ({be}): {e}", flush=True)
        pretty = _device_ui_error(e, backend=be, lang="ru")
        pretty_api = _device_user_error(e, on=None, backend=be, lang="ru")

        def _mut_err(d):
            d["online"] = False
            d["last_error"] = pretty
            d["last_action"] = f"{source}_fail"

        _device_update_in_store(did, _mut_err)
        return {
            "ok": False,
            "id": did,
            "error": pretty_api,
            "backend": be,
            "online": False,
        }


def device_test(did: str) -> dict:
    """
    Probe live device state (status poll + enforce/adopt policy).
    For eWeLink also attaches DIY diagnosis (port open / DIY HTTP / hints).
    """
    out = device_poll_status(did, source="test", apply_policy=True)
    try:
        cfg = _device_cfg_snapshot(did) or {}
        be = str(cfg.get("backend") or "").lower()
        if be in ("ewelink", "sonoff", "sonoff_diy"):
            diag = probe_ewelink_diy(
                str(cfg.get("ip") or ""),
                str(cfg.get("device_id") or ""),
                int(cfg.get("ewelink_port") or 8081),
            )
            out["ewelink_diag"] = diag
            if not out.get("ok") and diag.get("hints"):
                # surface first 2 hints in error for UI
                tips = "; ".join(str(h) for h in (diag.get("hints") or [])[:2])
                if tips and tips not in str(out.get("error") or ""):
                    out["error"] = f"{out.get('error') or 'eWeLink fail'} · {tips}"
    except Exception as e:
        out["ewelink_diag_error"] = str(e)[:160]
    return out


def device_set(
    did: str,
    on: bool | None = None,
    *,
    source: str = "manual",
    force: bool = False,
    error_lang: str = "ru",
    brightness: int | None = None,
    mode: str | None = None,
) -> dict:
    """
    Set device logical ON/OFF and optional light params.

    Design:
      1) UI/API stamps desired_on immediately (hold target for devices-poller)
      2) poke poller via device_req to apply set now
      3) poller background loop keeps reported == desired when enforce_desired is on
    Gates: allow_off_while_mining / allow_on_while_suspend (unless force).
    Inverted devices flip physical polarity.

    brightness: 0–100 % (lights/dimmers)
    mode: white|colour|scene|music
    """
    bright_i: int | None = None
    if brightness is not None:
        try:
            bright_i = max(0, min(100, int(brightness)))
        except (TypeError, ValueError):
            bright_i = None
    mode_s = str(mode).strip().lower() if mode else None
    if mode_s in ("color",):
        mode_s = "colour"
    if mode_s and mode_s not in ("white", "colour", "scene", "music"):
        mode_s = None
    light_only = on is None and (bright_i is not None or mode_s)
    if on is None and not light_only:
        return {
            "ok": False,
            "error": "on or brightness/mode required"
            if str(error_lang or "ru").lower().startswith("en")
            else "нужен on или brightness/mode",
        }
    if on is not None:
        on = bool(on)
    elif bright_i is not None and bright_i > 0:
        on = True  # dimming implies turn on
    else:
        # mode-only or brightness 0: keep last_on if known
        cfg0 = _device_cfg_snapshot(did) or {}
        if cfg0.get("last_on") is not None:
            on = bool(cfg0.get("last_on"))
        else:
            on = True
    el = str(error_lang or "ru").lower().startswith("en")
    cfg = _device_cfg_snapshot(did)
    if not cfg:
        return {
            "ok": False,
            "error": "device not found" if el else "устройство не найдено",
        }
    if not cfg.get("enabled") and not force:
        return {
            "ok": False,
            "error": "device disabled" if el else "устройство отключено",
        }
    be = str(cfg.get("backend") or "tapo")
    inverted = bool(cfg.get("inverted"))
    # Mining gates only when device is bound to a miner with known work state
    work = device_mining_work(cfg)
    if not force and work:
        if not on and work == "resume" and not bool(
            cfg.get("allow_off_while_mining", False)
        ):
            return {
                "ok": False,
                "error": (
                    "cannot turn off while mining (allow OFF while mining)"
                    if el
                    else "нельзя выключить при майнинге (разрешите OFF при майнинге)"
                ),
                "id": did,
            }
        if on and work in ("suspend", "sleep") and not bool(
            cfg.get("allow_on_while_suspend", False)
        ):
            return {
                "ok": False,
                "error": (
                    "cannot turn on while Suspend (allow ON while suspend)"
                    if el
                    else "нельзя включить при Suspend (разрешите ON при suspend)"
                ),
                "id": did,
            }
    # Always write desired first — poller hold must not depend on set success.
    def _mut_desired(d):
        d["desired_on"] = bool(on)
        if bright_i is not None:
            d["desired_brightness"] = bright_i
        if mode_s:
            d["desired_mode"] = mode_s

    _device_update_in_store(did, _mut_desired)

    physical = _device_logical_to_physical(on, inverted)
    prev = cfg.get("last_on")
    prev_br = cfg.get("last_brightness")
    prev_mode = cfg.get("last_mode")
    # No-op if already in desired logical state (avoids Tuya toggle-on-repeat)
    # Still apply when brightness/mode requested.
    light_set = bright_i is not None or mode_s
    if (
        prev is not None
        and bool(prev) is on
        and not force
        and not light_set
    ):
        return {
            "ok": True,
            "id": did,
            "on": bool(prev),
            "physical_on": _device_logical_to_physical(bool(prev), inverted),
            "source": source,
            "backend": be,
            "alias": cfg.get("alias"),
            "name": cfg.get("name"),
            "icon": cfg.get("icon"),
            "prev_on": prev,
            "desired_on": bool(on),
            "skipped": True,
            "reason": "already_in_state",
            "power": cfg.get("last_power"),
            "brightness": prev_br,
            "mode": prev_mode,
        }
    try:
        cfg_call = dict(cfg)
        cfg_call["_logical_on"] = bool(on)  # poller SetLogical wants logical
        if bright_i is not None:
            cfg_call["_set_brightness"] = bright_i
        if mode_s:
            cfg_call["_set_mode"] = mode_s
        out = _device_backend_dispatch(physical, cfg_call)
        if out.get("transport") == "devices-poller" or out.get("on_is_logical"):
            # poller returns logical on
            got_logical = (
                bool(out["on"]) if out.get("on") is not None else bool(on)
            )
            got_phys = _device_logical_to_physical(got_logical, inverted)
        else:
            got_phys = out.get("on")
            if got_phys is None:
                got_phys = physical
            got_logical = _device_physical_to_logical(bool(got_phys), inverted)
        power = _power_from_backend_out(out)
        skipped = bool(out.get("skipped"))

        def _mut(d):
            d["last_on"] = bool(got_logical)  # reported
            d["desired_on"] = bool(on)  # commanded (keep hold target)
            d["online"] = True
            d["last_error"] = None
            d["last_ok_ts"] = datetime.now().isoformat(timespec="seconds")
            if skipped:
                d["last_action"] = f"{source}:{be}:skip:{'on' if on else 'off'}"
            else:
                d["last_action"] = f"{source}:{be}:{'on' if on else 'off'}"
            if power:
                d["last_power"] = power
                d["last_power_ts"] = datetime.now().isoformat(timespec="seconds")
            br = out.get("brightness")
            if br is None and out.get("brightness_pct") is not None:
                br = out.get("brightness_pct")
            if br is not None:
                try:
                    d["last_brightness"] = max(0, min(100, int(br)))
                except (TypeError, ValueError):
                    pass
            elif bright_i is not None:
                d["last_brightness"] = bright_i
            # Light modes only — ignore eWeLink diy/lan protocol "mode"
            mode_raw = str(out.get("mode") or mode_s or "").strip().lower()
            if mode_raw in ("white", "colour", "color", "scene", "music"):
                d["last_mode"] = "colour" if mode_raw == "color" else mode_raw
            elif be in ("ewelink", "sonoff", "sonoff_diy") and str(
                d.get("last_mode") or ""
            ).lower() in ("lan", "diy", "auto"):
                # clear stale protocol mode that triggered false dimmer UI
                d["last_mode"] = None

        _device_update_in_store(did, _mut)
        snap = _device_cfg_snapshot(did) or cfg
        ret = {
            "ok": True,
            "id": did,
            "on": bool(got_logical),
            "reported_on": bool(got_logical),
            "physical_on": bool(got_phys),
            "source": source,
            "backend": be,
            "brightness": snap.get("last_brightness"),
            "mode": snap.get("last_mode"),
            "alias": cfg.get("alias"),
            "name": cfg.get("name"),
            "icon": cfg.get("icon"),
            "prev_on": prev,
            "desired_on": bool(on),
            "online": True,
            **{k: v for k, v in out.items() if k not in ("on",)},
        }
        if power:
            ret["power"] = power
        return ret
    except Exception as e:
        # Log technical detail; UI/last_error get laconic category only
        print(
            f"[devices] {did} set fail ({be}) on={on} source={source}: {e}",
            flush=True,
        )
        pretty_store = _device_ui_error(e, backend=be, lang="ru")
        pretty = _device_user_error(e, on=on, backend=be, lang=error_lang)

        def _mut_err(d):
            # keep desired_on — background poller will retry hold
            d["desired_on"] = bool(on)
            d["online"] = False
            d["last_error"] = pretty_store
            d["last_action"] = f"{source}_fail"

        _device_update_in_store(did, _mut_err)
        return {
            "ok": False,
            "error": pretty,
            "id": did,
            "source": source,
            "backend": be,
            "desired_on": bool(on),
        }


def _device_suspend_off_remaining(did: str) -> int | None:
    """Seconds left until Auto Off after Suspend, or None if not pending."""
    did = str(did or "")
    if not did:
        return None
    dl = _devices_suspend_off_deadline.get(did)
    if dl is None:
        return None
    rem = int(dl - time.time() + 0.999)  # ceil-ish
    return max(0, rem)


def _norm_mining_work_token(work: str | None) -> str:
    w = str(work or "").strip().lower()
    if w == "mining":
        w = "resume"
    if w == "sleep":
        w = "suspend"
    if w in ("resume", "suspend"):
        return w
    return ""


def write_mining_work_snapshot(
    work: str | None,
    *,
    source: str = "",
    miner_id: str | None = None,
    host: str | None = None,
    by_miner: dict | None = None,
    merge: bool = True,
) -> None:
    """
    Publish mining work for devices poller (file IPC).

    Top-level ``work`` = active miner (legacy).
    ``by_miner[miner_id]`` = per-miner resume|suspend for device binding.
    When ``merge`` is True, existing by_miner entries are kept and updated.
    """
    w = _norm_mining_work_token(work)
    now = time.time()
    prev: dict = {}
    if merge:
        try:
            raw = _load_json(MINING_WORK_FILE, {})
            if isinstance(raw, dict):
                prev = raw
        except Exception:
            prev = {}
    by: dict = {}
    if merge and isinstance(prev.get("by_miner"), dict):
        for k, v in prev["by_miner"].items():
            if not isinstance(v, dict):
                continue
            mid = str(k or "").strip()
            if not mid:
                continue
            ww = _norm_mining_work_token(v.get("work"))
            if not ww:
                continue
            try:
                ts = float(v.get("ts") or 0)
            except (TypeError, ValueError):
                ts = 0.0
            by[mid] = {
                "work": ww,
                "ts": ts or now,
                "host": str(v.get("host") or "")[:80] or None,
            }
    if isinstance(by_miner, dict):
        for k, v in by_miner.items():
            mid = str(k or "").strip()
            if not mid or not isinstance(v, dict):
                continue
            ww = _norm_mining_work_token(v.get("work"))
            if not ww:
                continue
            try:
                ts = float(v.get("ts") or now)
            except (TypeError, ValueError):
                ts = now
            by[mid] = {
                "work": ww,
                "ts": ts,
                "host": str(v.get("host") or "")[:80] or None,
            }
    mid_one = str(miner_id or "").strip()
    if mid_one and w:
        by[mid_one] = {
            "work": w,
            "ts": now,
            "host": str(host or "")[:80] or None,
        }
    active_id = mid_one or str(prev.get("active_miner_id") or "").strip() or None
    # if only by_miner updates (no top-level work), keep previous top work when fresh
    top_w = w or None
    top_ts = now
    if not top_w and merge:
        pw = _norm_mining_work_token(prev.get("work"))
        try:
            pts = float(prev.get("ts") or 0)
        except (TypeError, ValueError):
            pts = 0.0
        if pw and pts > 0:
            top_w = pw
            top_ts = pts
    try:
        _save_json(
            MINING_WORK_FILE,
            {
                "work": top_w,
                "ts": top_ts,
                "source": str(source or prev.get("source") or "")[:40],
                "active_miner_id": active_id,
                "by_miner": by,
            },
        )
    except Exception as e:
        print(f"[devices-poller] write mining_work: {e}", flush=True)


def read_mining_work_snapshot(max_age_sec: float = 180.0) -> str | None:
    """Read global mining work (active miner). None if missing/stale."""
    try:
        raw = _load_json(MINING_WORK_FILE, {})
        if not isinstance(raw, dict):
            return None
        ts = float(raw.get("ts") or 0)
        if ts <= 0 or (time.time() - ts) > float(max_age_sec):
            return None
        w = _norm_mining_work_token(raw.get("work"))
        return w or None
    except Exception:
        pass
    return None


def read_mining_work_by_miner(
    miner_id: str | None, max_age_sec: float = 180.0
) -> str | None:
    """Per-miner resume|suspend from mining_work.json by_miner map."""
    mid = str(miner_id or "").strip()
    if not mid:
        return None
    try:
        raw = _load_json(MINING_WORK_FILE, {})
        if not isinstance(raw, dict):
            return None
        by = raw.get("by_miner") if isinstance(raw.get("by_miner"), dict) else {}
        ent = by.get(mid)
        if not isinstance(ent, dict):
            # fallback: if this is the active miner, use top-level work
            if str(raw.get("active_miner_id") or "").strip() == mid:
                return read_mining_work_snapshot(max_age_sec=max_age_sec)
            return None
        try:
            ts = float(ent.get("ts") or 0)
        except (TypeError, ValueError):
            ts = 0.0
        if ts <= 0 or (time.time() - ts) > float(max_age_sec):
            return None
        return _norm_mining_work_token(ent.get("work")) or None
    except Exception:
        return None


def _default_bind_miner_id() -> str:
    """
    Soft-migration target: active managed miner, else sole enabled miner.
    Empty if ambiguous / none.
    """
    try:
        managed = get_miners_managed()
    except Exception:
        return ""
    miners = [
        m
        for m in (managed.get("miners") or [])
        if isinstance(m, dict) and m.get("enabled", True)
    ]
    if not miners:
        return ""
    for m in miners:
        if str(m.get("role") or "").lower() == "active":
            mid = str(m.get("id") or "").strip()
            if mid:
                return mid
    if len(miners) == 1:
        return str(miners[0].get("id") or "").strip()
    return ""


def _device_needs_miner_bind_migration(d: dict) -> bool:
    """True if device has mining policy flags but no miner_id yet."""
    if str(d.get("miner_id") or "").strip():
        return False
    if bool(d.get("auto_on_mining")) or bool(d.get("auto_off_suspend")):
        return True
    # allow_off false + enabled device historically blocked OFF while mining
    if d.get("allow_off_while_mining") is False and (
        bool(d.get("auto_on_mining")) or bool(d.get("auto_off_suspend"))
    ):
        return True
    return False


def _migrate_device_miner_binds(devices: list[dict]) -> tuple[list[dict], bool]:
    """Bind mining-flagged devices to active/sole miner. Returns (devices, changed)."""
    target = _default_bind_miner_id()
    if not target:
        return devices, False
    changed = False
    out: list[dict] = []
    for d in devices:
        if not isinstance(d, dict):
            continue
        nd = dict(d)
        if _device_needs_miner_bind_migration(nd):
            nd["miner_id"] = target
            changed = True
            print(
                f"[devices] migrate miner_id={target} for "
                f"{nd.get('alias') or nd.get('id')}",
                flush=True,
            )
        out.append(nd)
    return out, changed


def _miner_label_for_id(miner_id: str | None) -> str | None:
    mid = str(miner_id or "").strip()
    if not mid:
        return None
    try:
        for m in get_miners_managed().get("miners") or []:
            if not isinstance(m, dict):
                continue
            if str(m.get("id") or "").strip() == mid:
                alias = str(m.get("alias") or m.get("name") or "").strip()
                host = str(m.get("host") or "").strip()
                if alias and host:
                    return f"{alias} · {host}"
                return alias or host or mid
    except Exception:
        pass
    return mid


def device_mining_work(
    device: dict | None, *, max_age_sec: float | None = None
) -> str | None:
    """
    Mining work for this device's bound miner: resume|suspend|None.

    None means mining policy must be ignored (unbound, unknown, or stale).
    """
    if not isinstance(device, dict):
        return None
    mid = str(device.get("miner_id") or "").strip()
    if not mid:
        return None
    if max_age_sec is None:
        try:
            max_age_sec = float(
                get_devices_poller_cfg().get("mining_work_max_age_sec") or 300
            )
        except Exception:
            max_age_sec = 300.0
    return read_mining_work_by_miner(mid, max_age_sec=float(max_age_sec))


def _load_devices_deadlines() -> None:
    """Restore suspend-off deadlines from disk (devices poller process)."""
    try:
        raw = _load_json(DEVICES_DEADLINES_FILE, {})
        if not isinstance(raw, dict):
            return
        dl = raw.get("deadlines") if isinstance(raw.get("deadlines"), dict) else {}
        st = raw.get("sync_ts") if isinstance(raw.get("sync_ts"), dict) else {}
        _devices_suspend_off_deadline.clear()
        for k, v in dl.items():
            try:
                _devices_suspend_off_deadline[str(k)] = float(v)
            except (TypeError, ValueError):
                continue
        _devices_sync_ts.clear()
        for k, v in st.items():
            try:
                _devices_sync_ts[str(k)] = float(v)
            except (TypeError, ValueError):
                continue
    except Exception as e:
        print(f"[devices-poller] load deadlines: {e}", flush=True)


def _save_devices_deadlines() -> None:
    try:
        _save_json(
            DEVICES_DEADLINES_FILE,
            {
                "deadlines": {
                    str(k): float(v)
                    for k, v in _devices_suspend_off_deadline.items()
                },
                "sync_ts": {
                    str(k): float(v) for k, v in _devices_sync_ts.items()
                },
                "ts": time.time(),
            },
        )
    except Exception as e:
        print(f"[devices-poller] save deadlines: {e}", flush=True)


def _device_set_with_timeout(
    did: str,
    on: bool,
    *,
    source: str,
    timeout: float | None = None,
) -> dict:
    """device_set in a worker thread; raise on hang past timeout."""
    if timeout is None:
        try:
            timeout = float(get_devices_poller_cfg().get("set_timeout_sec") or 15)
        except Exception:
            timeout = 15.0
    timeout = max(3.0, min(60.0, float(timeout)))
    with ThreadPoolExecutor(max_workers=1) as ex:
        fut = ex.submit(device_set, did, on, source=source, force=True)
        try:
            return fut.result(timeout=timeout)
        except FuturesTimeout as e:
            raise RuntimeError(
                f"device_set timeout after {timeout:.0f}s (device may be hung)"
            ) from e


def devices_sync_with_mining(measured_work: str | None = None) -> None:
    """
    Mining policy: Auto ON on Resume / Auto OFF on Suspend (per-device flags).

    Per-device: only if ``miner_id`` is set and that miner's work is known.
    Unbound devices ignore mining policy entirely.
    ``measured_work`` is ignored for bound devices (kept for call-site compat).
    """
    _ = measured_work  # legacy arg; resolve per device from by_miner
    now = time.time()
    try:
        max_age = float(
            get_devices_poller_cfg().get("mining_work_max_age_sec") or 300
        )
    except Exception:
        max_age = 300.0
    with _devices_cfg_lock:
        devices = [
            _merge_device_runtime(
                dict(d),
                _devices_state.get(str(d.get("id") or "")),
            )
            for d in (_devices_cfg.get("devices") or [])
            if isinstance(d, dict)
        ]
    for cfg in devices:
        if not cfg.get("enabled"):
            continue
        if not _device_ready(cfg):
            print(
                f"[devices] sync skip {cfg.get('alias') or cfg.get('id')}: "
                f"not ready (backend/credentials)",
                flush=True,
            )
            continue
        did = str(cfg.get("id") or "")
        if not did:
            continue
        # Unbound or unknown miner work → do not apply mining auto policy
        work = device_mining_work(cfg, max_age_sec=max_age)
        if not work:
            # clear stale suspend-off if unbound / miner offline
            if not str(cfg.get("miner_id") or "").strip():
                _devices_suspend_off_deadline.pop(did, None)
            continue
        auto_on = bool(cfg.get("auto_on_mining", False))
        auto_off = bool(cfg.get("auto_off_suspend", False))
        delay = _device_off_delay_sec(cfg.get("auto_off_suspend_delay_sec"))
        # physical truth for auto policy (not desired — that blocked auto_on)
        reported = cfg.get("last_on")
        desired = cfg.get("desired_on")
        last_err = cfg.get("last_error")
        last_act = str(cfg.get("last_action") or "")
        if last_err and last_act.endswith("_fail"):
            last_try = float(_devices_sync_ts.get(did) or 0)
            try:
                backoff = float(
                    get_devices_poller_cfg().get("error_backoff_sec") or 20
                )
            except Exception:
                backoff = 20.0
            if now - last_try < max(5.0, backoff):
                continue
        want: bool | None = None
        src = "auto"
        alias = str(cfg.get("alias") or did)

        if work == "resume":
            # mining back on → cancel any pending Auto Off
            if did in _devices_suspend_off_deadline:
                _devices_suspend_off_deadline.pop(did, None)
                print(
                    f"[devices] suspend-off cancelled {alias} (mining resume)",
                    flush=True,
                )
            if auto_on:
                # ensure ON while mining (reported unknown or OFF)
                if reported is not True:
                    want = True
                    src = "auto_mining"
                elif desired is not True:
                    # already ON, but shadow desired stale — fix state only
                    def _mut_des(d, _on=True):
                        d["desired_on"] = _on

                    _device_update_in_store(did, _mut_des)
        elif work in ("suspend", "sleep") and auto_off:
            # already off → nothing pending
            if reported is False:
                _devices_suspend_off_deadline.pop(did, None)
                if desired is not False:

                    def _mut_off(d):
                        d["desired_on"] = False

                    _device_update_in_store(did, _mut_off)
            else:
                # device on or unknown → schedule / fire delayed OFF
                deadline = _devices_suspend_off_deadline.get(did)
                if deadline is None:
                    if delay <= 0:
                        want = False
                        src = "auto_suspend"
                    else:
                        _devices_suspend_off_deadline[did] = now + float(delay)
                        print(
                            f"[devices] suspend-off in {delay}s {alias}",
                            flush=True,
                        )
                elif now >= float(deadline):
                    want = False
                    src = "auto_suspend"
                    _devices_suspend_off_deadline.pop(did, None)
                # else still waiting — leave device ON
        else:
            # auto_off disabled while suspend → clear stale deadline
            if work in ("suspend", "sleep") and not auto_off:
                _devices_suspend_off_deadline.pop(did, None)

        if want is None:
            continue
        _devices_sync_ts[did] = now
        try:
            print(
                f"[devices] sync {alias}: work={work} → "
                f"{'ON' if want else 'OFF'} ({src}) "
                f"reported={reported} desired={desired}",
                flush=True,
            )
            _device_set_with_timeout(did, want, source=src)
        except Exception as e:
            print(f"[devices] sync {alias}: {e}", flush=True)


def devices_poll_all_status() -> dict:
    """
    Poll status for every enabled/ready device (reported, online, power…).
    Applies enforce_desired / adopt-reported policy per device.
    """
    now = time.time()
    pol = get_devices_poller_cfg()
    try:
        backoff = float(pol.get("error_backoff_sec") or 20)
    except Exception:
        backoff = 20.0
    try:
        timeout = float(pol.get("set_timeout_sec") or 15)
    except Exception:
        timeout = 15.0
    timeout = max(3.0, min(60.0, timeout))
    backoff = max(5.0, backoff)

    with _devices_cfg_lock:
        ids = [
            str(d.get("id") or "")
            for d in (_devices_cfg.get("devices") or [])
            if d.get("enabled") is not False and str(d.get("id") or "")
        ]
    probed = 0
    errors = 0
    for did in ids:
        if not did:
            continue
        cfg = _device_cfg_snapshot(did)
        if not cfg or not _device_ready(cfg):
            continue
        # skip devices still in error backoff
        last_err = cfg.get("last_error")
        last_act = str(cfg.get("last_action") or "")
        if last_err and last_act.endswith("_fail"):
            last_try = float(_devices_sync_ts.get(did) or 0)
            if now - last_try < backoff:
                continue
        try:
            # status probe only (no enforce) under hard timeout
            with ThreadPoolExecutor(max_workers=1) as ex:
                fut = ex.submit(
                    device_poll_status,
                    did,
                    source="poll",
                    apply_policy=False,
                )
                try:
                    res = fut.result(timeout=timeout)
                except FuturesTimeout:
                    def _mut_to(d):
                        d["online"] = False
                        d["last_error"] = _device_ui_error(
                            f"status timeout after {timeout:.0f}s",
                            backend=str(cfg.get("backend") or ""),
                            lang="ru",
                        )
                        d["last_action"] = "poll_fail"

                    _device_update_in_store(did, _mut_to)
                    _devices_sync_ts[did] = now
                    errors += 1
                    print(
                        f"[devices-poller] status timeout "
                        f"{cfg.get('alias') or did} after {timeout:.0f}s",
                        flush=True,
                    )
                    continue
            if not res.get("ok"):
                errors += 1
                _devices_sync_ts[did] = now
                continue
            probed += 1
            reported = res.get("reported_on")
            if reported is None:
                reported = res.get("on")
            # desired policy after successful probe
            cfg2 = _device_cfg_snapshot(did) or cfg
            if bool(cfg2.get("enforce_desired")):
                try:
                    _device_enforce_desired(
                        did, reported, use_timeout=True
                    )
                except Exception as ee:
                    print(
                        f"[devices-poller] enforce "
                        f"{cfg2.get('alias') or did}: {ee}",
                        flush=True,
                    )
            else:
                _device_adopt_reported(did, reported)
        except Exception as e:
            errors += 1
            _devices_sync_ts[did] = now
            print(
                f"[devices-poller] status {cfg.get('alias') or did}: {e}",
                flush=True,
            )
    return {"probed": probed, "errors": errors}


def devices_poller_loop() -> None:
    """
    Dedicated loop (isolated process):
      1) poll each device → reported / online / power
      2) enforce desired OR adopt reported
      3) mining Auto ON/OFF policy
    """
    print("[devices-poller] loop start", flush=True)
    _load_devices_deadlines()
    while not _devices_poller_stop.is_set():
        t0 = time.time()
        pol = dict(DEFAULT_DEVICES_POLLER)
        try:
            # pick up UI/API config changes from main process (every tick)
            _load_devices_cfg()
            pol = get_devices_poller_cfg()
            n_dev = 0
            try:
                with _devices_cfg_lock:
                    n_dev = len(_devices_cfg.get("devices") or [])
            except Exception:
                n_dev = 0
            if not pol.get("enabled", True):
                print("[devices-poller] disabled in config — idle", flush=True)
            else:
                # 1–2) status poll + desired/reported policy
                summary = devices_poll_all_status()
                if summary.get("probed") or summary.get("errors"):
                    print(
                        f"[devices-poller] status "
                        f"ok={summary.get('probed', 0)} "
                        f"err={summary.get('errors', 0)} "
                        f"cfg={n_dev}",
                        flush=True,
                    )
                # 3) mining auto policy — per-device bound miner (by_miner map)
                try:
                    devices_sync_with_mining()
                except Exception as e:
                    print(f"[devices-poller] mining sync: {e}", flush=True)
            _save_devices_deadlines()
        except Exception as e:
            print(f"[devices-poller] tick: {e}", flush=True)
        try:
            interval = max(3, min(120, int(pol.get("interval_sec") or 5)))
        except (TypeError, ValueError):
            interval = 5
        # account for tick duration so delay stays ~interval
        spent = time.time() - t0
        wait = max(1.0, float(interval) - spent)
        _devices_poller_stop.wait(timeout=wait)
    print("[devices-poller] loop stop", flush=True)
    try:
        _save_devices_deadlines()
    except Exception:
        pass


def devices_poller_main() -> None:
    """
    DEPRECATED: ``python serve.py --devices-poller``.

    Production uses Go ``poolheat-devices-poller`` only. serve never spawns this.
    """
    print(
        "[devices-poller] WARNING: Python devices-poller is deprecated. "
        "Use /opt/bin/poolheat-devices-poller (Go). "
        "serve no longer spawns this process.",
        flush=True,
    )
    _devices_poller_stop.clear()

    def _sig(_signum=None, _frame=None) -> None:
        _devices_poller_stop.set()

    try:
        signal.signal(signal.SIGTERM, _sig)
        signal.signal(signal.SIGINT, _sig)
    except Exception:
        pass
    try:
        DEVICES_POLLER_PIDFILE.write_text(
            str(os.getpid()), encoding="utf-8"
        )
    except Exception:
        pass
    try:
        cl = cleanup_tmp_and_logs()
        print(
            f"[devices-poller] tmp cleanup: freed {cl.get('freed_mib')} MiB · "
            f"removed {cl.get('removed_n')}",
            flush=True,
        )
    except Exception as e:
        print(f"[devices-poller] tmp cleanup: {e}", flush=True)
    print(
        f"[devices-poller] pid={os.getpid()} data={DATA} (python/deprecated)",
        flush=True,
    )
    try:
        devices_poller_loop()
    finally:
        try:
            if DEVICES_POLLER_PIDFILE.is_file():
                DEVICES_POLLER_PIDFILE.unlink()
        except Exception:
            pass


def _resolve_devices_poller_bin() -> str | None:
    """
    Prefer Go poolheat-devices-poller (low RAM) over Python --devices-poller.
    Override: POOLHEAT_DEVICES_POLLER=/path/to/bin
    """
    candidates: list[Path] = []
    env = (os.environ.get("POOLHEAT_DEVICES_POLLER") or "").strip()
    if env:
        candidates.append(Path(env))
    here = Path(__file__).resolve().parent
    candidates.extend(
        [
            Path("/opt/bin/poolheat-devices-poller"),
            here / "poolheat-devices-poller",
            here.parent / "bin" / "poolheat-devices-poller",
        ]
    )
    # USB install: /opt/lib/poolheat may be symlink → sibling bin
    try:
        real_lib = here.resolve()
        candidates.append(real_lib.parent / "bin" / "poolheat-devices-poller")
        candidates.append(real_lib / "poolheat-devices-poller")
    except Exception:
        pass
    for p in candidates:
        try:
            if p.is_file() and os.access(p, os.X_OK):
                # resolve() so OTA-replaced path is the real inode we exec
                try:
                    return str(p.resolve())
                except Exception:
                    return str(p)
        except Exception:
            continue
    return None


def start_devices_poller_process() -> None:
    """Spawn isolated devices poller subprocess (non-blocking for serve)."""
    global _devices_poller_proc
    if not role_enabled("edge_device_poller"):
        print("devices-poller:    off (edge_device_poller role disabled)")
        return
    try:
        ki = _force_stop_named_poller(
            "devices",
            DEVICES_POLLER_PIDFILE,
            "poolheat-devices-poller",
            "serve.py --devices-poller",
        )
        if ki.get("term") or ki.get("kill"):
            print(f"devices-poller:    stopped old pids {ki}", flush=True)
    except Exception as e:
        print(f"devices-poller:    force-stop: {e}", flush=True)
    script = str(Path(__file__).resolve())
    logf = None
    try:
        logf = open(DEVICES_POLLER_LOG, "a", encoding="utf-8")
        logf.write(
            f"\n--- start {datetime.now().isoformat(timespec='seconds')} ---\n"
        )
        logf.flush()
    except Exception:
        logf = None
    go_bin = _resolve_devices_poller_bin()
    if not go_bin:
        # Device LAN I/O is Go-only — never spawn Python --devices-poller
        # (would load tinytuya / ewelink into a second heavy process).
        print(
            "devices-poller:    ERROR — poolheat-devices-poller binary missing "
            "(install dual-arch package). Device control disabled "
            "(no tinytuya/ewelink in serve).",
            flush=True,
        )
        if logf:
            try:
                logf.close()
            except Exception:
                pass
        return
    # Explicit --data so Go always uses same DATA as serve (USB path etc.)
    cmd = [go_bin, "-data", str(DATA)]
    kind = "go"
    try:
        env = os.environ.copy()
        env["POOLHEAT_DATA"] = str(DATA)
        _devices_poller_proc = subprocess.Popen(
            cmd,
            cwd=str(Path(__file__).resolve().parent),
            env=env,
            stdout=logf or subprocess.DEVNULL,
            stderr=subprocess.STDOUT if logf else subprocess.DEVNULL,
            start_new_session=True,
        )
        try:
            DEVICES_POLLER_PIDFILE.parent.mkdir(parents=True, exist_ok=True)
            DEVICES_POLLER_PIDFILE.write_text(
                str(_devices_poller_proc.pid) + "\n", encoding="utf-8"
            )
        except Exception as e:
            print(f"devices-poller:    pidfile seed: {e}", flush=True)
        print(
            f"devices-poller:    {kind} pid {_devices_poller_proc.pid} · "
            f"log {DEVICES_POLLER_LOG}"
            + (f" · bin {go_bin}" if go_bin else ""),
            flush=True,
        )
    except Exception as e:
        print(f"devices-poller:    failed to start: {e}", flush=True)
        _devices_poller_proc = None
        if logf:
            try:
                logf.close()
            except Exception:
                pass


def stop_devices_poller_process() -> None:
    global _devices_poller_proc
    proc = _devices_poller_proc
    _devices_poller_proc = None
    pids: list[int] = []
    if proc is not None:
        try:
            if proc.poll() is None:
                pids.append(int(proc.pid))
                proc.terminate()
        except Exception:
            pass
    try:
        if DEVICES_POLLER_PIDFILE.is_file():
            pid = int(DEVICES_POLLER_PIDFILE.read_text().strip() or "0")
            if pid > 1 and pid != os.getpid():
                pids.append(pid)
                try:
                    os.kill(pid, signal.SIGTERM)
                except Exception:
                    pass
    except Exception:
        pass
    if pids:
        _wait_pids_dead(pids, timeout_sec=2.0)
    if proc is not None:
        try:
            if proc.poll() is None:
                proc.kill()
                proc.wait(timeout=2)
        except Exception:
            pass


def miner_live_loop() -> None:
    """
    Fast ASIC live poll (control interval). Writes live_cache.json + mining_work
    so UI/policy/devices processes stay off :4028 for reads.

    When managed inventory has multiple enabled miners, polls each host and
    writes fleet_live.json so the fleet table can show per-row live data
    (Whatsminer / iPollo / Goldshell / …).
    """
    print("[miner-poller] live loop start", flush=True)
    while not _miner_poller_stop.is_set():
        t0 = time.time()
        try:
            # Multi-host fleet poll (managed inventory)
            try:
                _poll_managed_fleet_live()
            except Exception as e:
                print(f"[miner-poller] fleet: {e}", flush=True)
            live = fetch_live()
            publish_live_snapshot(live)
            try:
                mid = ""
                host = ""
                try:
                    mid = _default_bind_miner_id()  # active or sole
                    # prefer exact host match
                    live_host = _live_host_ip(live) if isinstance(live, dict) else ""
                    host = live_host or str((live or {}).get("host") or "").split(":")[0]
                    for m in get_miners_managed().get("miners") or []:
                        if not isinstance(m, dict):
                            continue
                        if str(m.get("host") or "").strip() == host and host:
                            mid = str(m.get("id") or mid).strip()
                            break
                except Exception:
                    pass
                write_mining_work_snapshot(
                    _live_work(live),
                    source="miner-poller",
                    miner_id=mid or None,
                    host=host or None,
                )
            except Exception:
                pass
            try:
                tg_note_live_poll_ok()
            except Exception:
                pass
        except Exception as e:
            print(
                f"[miner-poller] live: {datetime.now().isoformat(timespec='seconds')} {e}",
                flush=True,
            )
            try:
                tg_note_live_poll_fail(e)
            except Exception:
                pass
            # still stamp offline for history consumer via empty? leave last cache
        with _miner_cfg_lock:
            interval = max(2, int(POLL_INTERVAL_SEC))
        spent = time.time() - t0
        _miner_poller_stop.wait(timeout=max(1.0, float(interval) - spent))
    print("[miner-poller] live loop stop", flush=True)


def miner_poller_main() -> None:
    """
    Entry for ``python serve.py --miner-poller``.

    Isolated process: ASIC live poll + history collector + chipmap.
    UI process only serves HTTP and hydrates from live_cache.json.
    """
    _miner_poller_stop.clear()
    _collector_stop.clear()
    _chipmap_stop.clear()

    def _sig(_signum=None, _frame=None) -> None:
        _miner_poller_stop.set()
        _collector_stop.set()
        _chipmap_stop.set()

    try:
        signal.signal(signal.SIGTERM, _sig)
        signal.signal(signal.SIGINT, _sig)
    except Exception:
        pass
    try:
        MINER_POLLER_PIDFILE.write_text(str(os.getpid()), encoding="utf-8")
    except Exception:
        pass
    try:
        cl = cleanup_tmp_and_logs()
        print(
            f"[miner-poller] tmp cleanup: freed {cl.get('freed_mib')} MiB · "
            f"removed {cl.get('removed_n')}",
            flush=True,
        )
    except Exception as e:
        print(f"[miner-poller] tmp cleanup: {e}", flush=True)
    print(
        f"[miner-poller] pid={os.getpid()} data={DATA} miner={HOST_MINER}:{PORT_MINER}",
        flush=True,
    )
    try:
        init_db()
    except Exception as e:
        print(f"[miner-poller] init_db: {e}", flush=True)
    threads: list[threading.Thread] = []
    # Always keep a fast live loop (policy/UI cache)
    tl = threading.Thread(target=miner_live_loop, name="miner-live", daemon=True)
    tl.start()
    threads.append(tl)
    # History + energy samples (uses fetch_live; shares _miner_io_lock with live loop)
    if role_enabled("edge_history"):
        th = threading.Thread(
            target=collector_loop, name="history-collector", daemon=True
        )
        th.start()
        threads.append(th)
        print("[miner-poller] history collector on", flush=True)
    else:
        print("[miner-poller] history collector off", flush=True)
    if role_enabled("edge_miner_poller"):
        tc = threading.Thread(target=chipmap_loop, name="chipmap-poll", daemon=True)
        tc.start()
        threads.append(tc)
        print("[miner-poller] chipmap on", flush=True)
    else:
        print("[miner-poller] chipmap off", flush=True)
    # LAN discovery + manual Scan now (Python poller; Go binary has its own)
    td = threading.Thread(
        target=miner_discovery_loop, name="miner-discovery", daemon=True
    )
    td.start()
    threads.append(td)
    print("[miner-poller] discovery on", flush=True)
    try:
        while not _miner_poller_stop.is_set():
            _miner_poller_stop.wait(timeout=2.0)
    finally:
        _collector_stop.set()
        _chipmap_stop.set()
        try:
            if MINER_POLLER_PIDFILE.is_file():
                MINER_POLLER_PIDFILE.unlink()
        except Exception:
            pass
        print("[miner-poller] exit", flush=True)


def _resolve_miner_poller_bin() -> str | None:
    """Prefer Go poolheat-miner-poller (wm-lib) over Python --miner-poller."""
    candidates: list[Path] = []
    env = (os.environ.get("POOLHEAT_MINER_POLLER") or "").strip()
    if env:
        candidates.append(Path(env))
    here = Path(__file__).resolve().parent
    candidates.extend(
        [
            Path("/opt/bin/poolheat-miner-poller"),
            here / "poolheat-miner-poller",
            here.parent / "bin" / "poolheat-miner-poller",
        ]
    )
    try:
        real_lib = here.resolve()
        candidates.append(real_lib.parent / "bin" / "poolheat-miner-poller")
        candidates.append(real_lib / "poolheat-miner-poller")
    except Exception:
        pass
    for p in candidates:
        try:
            if p.is_file() and os.access(p, os.X_OK):
                # resolve() so OTA-replaced path is the real inode we exec
                try:
                    return str(p.resolve())
                except Exception:
                    return str(p)
        except Exception:
            continue
    return None



def _pid_exe_path(pid: int) -> str:
    """/proc/pid/exe target (may end with ' (deleted)' after OTA replace)."""
    try:
        return os.readlink(f"/proc/{int(pid)}/exe")
    except Exception:
        return ""


def _pid_alive(pid: int) -> bool:
    try:
        if pid <= 1:
            return False
        os.kill(int(pid), 0)
        return True
    except Exception:
        return False


def _find_pids_by_name(*name_substrings: str) -> list[int]:
    """
    Find PIDs whose cmdline or exe contains any substring.
    Prefer /proc (reliable on BusyBox/Entware); fall back to `ps w`.
    """
    me = os.getpid()
    needles = [s.lower() for s in name_substrings if s]
    if not needles:
        return []
    found: set[int] = set()

    # 1) /proc scan — works when `ps w` truncates or omits args
    try:
        for ent in Path("/proc").iterdir():
            if not ent.name.isdigit():
                continue
            pid = int(ent.name)
            if pid <= 1 or pid == me:
                continue
            try:
                cmd = _pid_cmdline(pid).lower()
            except Exception:
                cmd = ""
            try:
                exe = _pid_exe_path(pid).lower()
            except Exception:
                exe = ""
            blob = f"{cmd} {exe}"
            if any(n in blob for n in needles):
                found.add(pid)
    except Exception:
        pass

    # 2) BusyBox/Linux ps fallback
    if not found:
        out = ""
        for args in (["ps", "w"], ["ps", "ax"], ["ps"]):
            try:
                out = subprocess.check_output(
                    args, stderr=subprocess.DEVNULL, text=True, timeout=5
                )
                break
            except Exception:
                continue
        for line in (out or "").splitlines():
            low = line.lower()
            if not any(n in low for n in needles):
                continue
            parts = line.split()
            if not parts:
                continue
            pid = None
            for tok in parts[:3]:
                try:
                    pid = int(tok)
                    break
                except ValueError:
                    continue
            if pid is None or pid <= 1 or pid == me:
                continue
            found.add(pid)

    return sorted(found)


def _kill_named_processes(*name_substrings: str, sig: int = signal.SIGTERM) -> list[int]:
    """Best-effort kill of processes matching name substrings (cmdline/exe)."""
    killed: list[int] = []
    for pid in _find_pids_by_name(*name_substrings):
        try:
            os.kill(pid, sig)
            killed.append(pid)
        except Exception:
            pass
        # also try process group (start_new_session=True → pgid == pid)
        try:
            os.killpg(pid, sig)
        except Exception:
            pass
    return killed


def _wait_pids_dead(pids: list[int], timeout_sec: float = 5.0) -> list[int]:
    """Wait until pids exit. Returns still-alive leftovers."""
    deadline = time.time() + max(0.2, float(timeout_sec))
    left = {int(p) for p in pids if p and p > 1}
    while left and time.time() < deadline:
        left = {p for p in left if _pid_alive(p)}
        if not left:
            break
        time.sleep(0.1)
    return sorted(left)


def _force_stop_named_poller(kind: str, pidfile: Path, *name_substrings: str) -> dict:
    """
    Kill one poller family so a new binary is actually loaded after OTA.
    Linux keeps old inode mapped until process exit — replace alone is not enough.
    Uses /proc discovery + SIGTERM wait + SIGKILL; only then drops pidfile.
    """
    info: dict = {
        "kind": kind,
        "term": [],
        "kill": [],
        "waited_dead": [],
        "leftover": [],
        "pidfiles": [],
        "pids_seen": [],
    }
    pids: set[int] = set()
    me = os.getpid()

    # pidfile first
    try:
        if pidfile.is_file():
            pid = int((pidfile.read_text(encoding="utf-8") or "").strip() or "0")
            if pid > 1 and pid != me and _pid_alive(pid):
                pids.add(pid)
    except Exception:
        pass

    # /proc + ps
    for pid in _find_pids_by_name(*name_substrings):
        pids.add(pid)

    info["pids_seen"] = sorted(pids)

    # SIGTERM
    for pid in list(pids):
        try:
            os.kill(pid, signal.SIGTERM)
            info["term"].append(pid)
        except Exception:
            pass
        try:
            os.killpg(pid, signal.SIGTERM)
        except Exception:
            pass

    leftover = _wait_pids_dead(sorted(pids), timeout_sec=4.0)
    info["waited_dead"] = sorted(set(pids) - set(leftover))

    # SIGKILL leftovers + re-scan
    if leftover or _find_pids_by_name(*name_substrings):
        more = set(leftover) | set(_find_pids_by_name(*name_substrings))
        for pid in more:
            try:
                os.kill(pid, signal.SIGKILL)
                info["kill"].append(pid)
            except Exception:
                pass
            try:
                os.killpg(pid, signal.SIGKILL)
            except Exception:
                pass
        leftover = _wait_pids_dead(sorted(more), timeout_sec=3.0)

    # final scan
    leftover = sorted(set(leftover) | set(_find_pids_by_name(*name_substrings)))
    info["leftover"] = leftover

    # drop pidfile only after processes are gone (or we did our best)
    if not leftover:
        try:
            if pidfile.is_file():
                pidfile.unlink()
                info["pidfiles"].append(str(pidfile))
        except Exception:
            pass
    else:
        # stale pidfile pointing at dead pid still hurts alive() checks
        try:
            if pidfile.is_file():
                cur = int((pidfile.read_text(encoding="utf-8") or "").strip() or "0")
                if cur > 0 and not _pid_alive(cur):
                    pidfile.unlink()
                    info["pidfiles"].append(str(pidfile))
        except Exception:
            pass

    return info


def _force_stop_edge_pollers() -> dict:
    """Kill both Go/Python pollers (OTA full restart)."""
    a = _force_stop_named_poller(
        "miner",
        MINER_POLLER_PIDFILE,
        "poolheat-miner-poller",
        "serve.py --miner-poller",
        "serve.py --asic-poller",
    )
    b = _force_stop_named_poller(
        "devices",
        DEVICES_POLLER_PIDFILE,
        "poolheat-devices-poller",
        "serve.py --devices-poller",
    )
    return {"miner": a, "devices": b}



_poller_ver_cache: dict[str, tuple[float, str]] = {}
_POLLER_VER_TTL = 8.0  # short TTL — after OTA/restart UI must show fresh version


def _clear_poller_ver_cache(role: str | None = None) -> None:
    """Invalidate cached service versions (call after restart/OTA)."""
    global _poller_ver_cache
    if not role:
        _poller_ver_cache = {}
        return
    role = str(role).strip().lower()
    drop = [k for k in _poller_ver_cache if k == role or k.startswith(f"{role}:")]
    for k in drop:
        _poller_ver_cache.pop(k, None)


def _disk_bin_version(bin_path: str | None) -> str:
    if not bin_path:
        return ""
    try:
        bi = _poller_bin_info(bin_path)
        v = str(bi.get("version") or "").strip()
        if v.lower().startswith("version"):
            v = v.split(None, 1)[-1] if " " in v else v
        return v
    except Exception:
        return ""


def _role_service_version(role: str, cmd: str = "", pid: int | None = None) -> str | None:
    """
    Version string for Info → Processes.
    serve → app VERSION; Go pollers → disk `-version`, plus flag if running
    exe is a deleted (pre-OTA) inode that was not re-exec'd.
    """
    role = str(role or "").strip().lower()
    cmd = str(cmd or "")
    now = time.time()

    def _cached(key: str, producer) -> str | None:
        hit = _poller_ver_cache.get(key)
        if hit and (now - hit[0]) < _POLLER_VER_TTL:
            return hit[1] or None
        try:
            ver = producer() or ""
        except Exception:
            ver = ""
        _poller_ver_cache[key] = (now, ver)
        return ver or None

    if role == "serve":
        return _cached("serve", lambda: str(get_app_version() or "").strip())

    if role in ("miner-poller", "devices-poller"):
        bin_path = None
        # prefer path from cmdline if absolute
        for tok in cmd.split():
            if "poolheat-miner-poller" in tok or "poolheat-devices-poller" in tok:
                if tok.startswith("/") or tok.startswith("./"):
                    bin_path = tok.split(" (deleted)")[0].strip()
                    break
        if not bin_path:
            if role == "miner-poller":
                bin_path = _resolve_miner_poller_bin()
            else:
                try:
                    bin_path = _resolve_devices_poller_bin()
                except Exception:
                    bin_path = None
        if not bin_path:
            # python poller child
            if "serve.py" in cmd:
                return _cached(
                    f"{role}:py",
                    lambda: str(get_app_version() or "").strip() + " (py)",
                )
            return None

        exe = ""
        if pid and int(pid) > 0:
            exe = _pid_exe_path(int(pid))
        deleted = bool(exe) and ("(deleted)" in exe)

        def _prod():
            v = _disk_bin_version(bin_path)
            if deleted:
                # Running process still maps pre-OTA inode — disk -version is misleading.
                return (
                    (v + " · STALE(exe deleted — restart needed)")
                    if v
                    else "STALE(exe deleted)"
                )
            return v

        cache_key = f"{role}:{bin_path}:{pid or 0}:{1 if deleted else 0}"
        return _cached(cache_key, _prod)

    if role == "sniffer":
        return None
    return None


def _wait_poller_ready(pidfile: Path, *, timeout_sec: float = 6.0) -> dict:
    """After spawn: wait until pidfile points at a live process."""
    deadline = time.time() + max(1.0, float(timeout_sec))
    last: dict = {"alive": False, "pid": None, "exe": "", "deleted": False}
    while time.time() < deadline:
        try:
            if pidfile.is_file():
                pid = int((pidfile.read_text(encoding="utf-8") or "").strip() or "0")
                if pid > 1 and _pid_alive(pid):
                    exe = _pid_exe_path(pid)
                    last = {
                        "alive": True,
                        "pid": pid,
                        "exe": exe,
                        "deleted": bool(exe) and ("(deleted)" in exe),
                    }
                    if not last["deleted"]:
                        return last
        except Exception:
            pass
        time.sleep(0.15)
    return last


def restart_poolheat_role(role: str) -> dict:
    """
    Restart one Poolheat edge process from Info UI.
    roles: serve | miner-poller | devices-poller | all

    Critical: must fully kill old process so Linux unmaps the old ELF inode;
    then exec the on-disk binary (post-OTA).
    """
    role = str(role or "").strip().lower().replace("_", "-")
    if role in ("all", "edge", "*"):
        # full service restart (detached)
        try:
            _clear_poller_ver_cache()
            _restart_poolheat_later()
        except Exception as e:
            return {"ok": False, "role": "all", "error": str(e)}
        return {
            "ok": True,
            "role": "all",
            "message": "full service restart queued (1–2s)",
        }
    if role in ("miner-poller", "miner", "asic-poller"):
        try:
            stop_miner_poller_process()
        except Exception:
            pass
        try:
            ki = _force_stop_named_poller(
                "miner",
                MINER_POLLER_PIDFILE,
                "poolheat-miner-poller",
                "serve.py --miner-poller",
                "serve.py --asic-poller",
            )
            if ki.get("leftover"):
                for pid in list(ki["leftover"]):
                    try:
                        os.kill(int(pid), signal.SIGKILL)
                    except Exception:
                        pass
                time.sleep(0.5)
                ki["leftover"] = _find_pids_by_name(
                    "poolheat-miner-poller",
                    "serve.py --miner-poller",
                    "serve.py --asic-poller",
                )
            if ki.get("leftover"):
                return {
                    "ok": False,
                    "role": "miner-poller",
                    "error": f"could not kill old poller pids {ki['leftover']}",
                    "stopped": ki,
                }
            _clear_poller_ver_cache("miner-poller")
            start_miner_poller_process()
            ready = _wait_poller_ready(MINER_POLLER_PIDFILE, timeout_sec=6.0)
            bin_path = _resolve_miner_poller_bin()
            ver = _disk_bin_version(bin_path)
            ok = bool(ready.get("alive")) and not ready.get("deleted")
            return {
                "ok": ok,
                "role": "miner-poller",
                "stopped": ki,
                "alive": bool(ready.get("alive")),
                "pid": ready.get("pid"),
                "exe": ready.get("exe") or "",
                "exe_deleted": bool(ready.get("deleted")),
                "bin": bin_path,
                "version": ver,
                "message": (
                    "miner-poller restarted · new binary loaded"
                    if ok
                    else (
                        "miner-poller still maps deleted exe — kill manually"
                        if ready.get("deleted")
                        else "miner-poller failed to come up"
                    )
                ),
            }
        except Exception as e:
            return {"ok": False, "role": "miner-poller", "error": str(e)}
    if role in ("devices-poller", "devices", "device-poller"):
        try:
            stop_devices_poller_process()
        except Exception:
            pass
        try:
            ki = _force_stop_named_poller(
                "devices",
                DEVICES_POLLER_PIDFILE,
                "poolheat-devices-poller",
                "serve.py --devices-poller",
            )
            if ki.get("leftover"):
                for pid in list(ki["leftover"]):
                    try:
                        os.kill(int(pid), signal.SIGKILL)
                    except Exception:
                        pass
                time.sleep(0.5)
                ki["leftover"] = _find_pids_by_name(
                    "poolheat-devices-poller",
                    "serve.py --devices-poller",
                )
            if ki.get("leftover"):
                return {
                    "ok": False,
                    "role": "devices-poller",
                    "error": f"could not kill old poller pids {ki['leftover']}",
                    "stopped": ki,
                }
            _clear_poller_ver_cache("devices-poller")
            start_devices_poller_process()
            ready = _wait_poller_ready(DEVICES_POLLER_PIDFILE, timeout_sec=6.0)
            bin_path = _resolve_devices_poller_bin()
            ver = _disk_bin_version(bin_path)
            ok = bool(ready.get("alive")) and not ready.get("deleted")
            return {
                "ok": ok,
                "role": "devices-poller",
                "stopped": ki,
                "alive": bool(ready.get("alive")),
                "pid": ready.get("pid"),
                "exe": ready.get("exe") or "",
                "exe_deleted": bool(ready.get("deleted")),
                "bin": bin_path,
                "version": ver,
                "message": (
                    "devices-poller restarted · new binary loaded"
                    if ok
                    else (
                        "devices-poller still maps deleted exe — kill manually"
                        if ready.get("deleted")
                        else "devices-poller failed to come up"
                    )
                ),
            }
        except Exception as e:
            return {"ok": False, "role": "devices-poller", "error": str(e)}
    if role in ("serve", "ui", "http"):
        try:
            _clear_poller_ver_cache()
            _restart_poolheat_later()
        except Exception as e:
            return {"ok": False, "role": "serve", "error": str(e)}
        return {
            "ok": True,
            "role": "serve",
            "message": "serve restart queued (poolheatd / init.d)",
        }
    return {"ok": False, "error": f"unknown role: {role}"}


def _poller_bin_info(path: str | None) -> dict:
    """version / mtime / size of a Go poller binary (for OTA verification)."""
    out: dict = {"path": path, "ok": False}
    if not path:
        return out
    p = Path(path)
    try:
        st = p.stat()
        out["size"] = st.st_size
        out["mtime"] = datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds")
        out["ok"] = True
    except Exception as e:
        out["error"] = str(e)
        return out
    try:
        r = subprocess.run(
            [path, "-version"],
            capture_output=True,
            text=True,
            timeout=3,
        )
        ver = (r.stdout or r.stderr or "").strip().splitlines()
        out["version"] = ver[0] if ver else ""
    except Exception as e:
        out["version_error"] = str(e)
    return out


def start_miner_poller_process() -> None:
    """Spawn isolated ASIC poller (live + history + chipmap)."""
    global _miner_poller_proc
    if not (
        role_enabled("edge_miner_poller") or role_enabled("edge_history")
    ):
        print("miner-poller:      off (edge_miner/history roles disabled)")
        return
    # Kill only miner-poller leftovers (OTA: old binary stays mapped until exit)
    try:
        ki = _force_stop_named_poller(
            "miner",
            MINER_POLLER_PIDFILE,
            "poolheat-miner-poller",
            "serve.py --miner-poller",
            "serve.py --asic-poller",
        )
        if ki.get("term") or ki.get("kill"):
            print(f"miner-poller:      stopped old pids {ki}", flush=True)
    except Exception as e:
        print(f"miner-poller:      force-stop: {e}", flush=True)
    script = str(Path(__file__).resolve())
    logf = None
    try:
        logf = open(MINER_POLLER_LOG, "a", encoding="utf-8")
        logf.write(
            f"\n--- start {datetime.now().isoformat(timespec='seconds')} ---\n"
        )
        logf.flush()
    except Exception:
        logf = None
    go_bin = _resolve_miner_poller_bin()
    if go_bin:
        cmd = [go_bin]
        kind = "go"
    else:
        cmd = [sys.executable, script, "--miner-poller"]
        kind = "python"
    try:
        env = os.environ.copy()
        env.setdefault("POOLHEAT_DATA", str(DATA))
        env.setdefault("POOLHEAT_MINER_HOST", str(HOST_MINER))
        env.setdefault("POOLHEAT_MINER_PORT", str(PORT_MINER))
        env.setdefault("POOLHEAT_API_PASSWORD", str(DEFAULT_API_PASSWORD))
        env.setdefault("POOLHEAT_POLL_INTERVAL", str(int(POLL_INTERVAL_SEC)))
        if Path("/opt/etc/poolheat/config.json").is_file():
            env.setdefault("POOLHEAT_CONFIG", "/opt/etc/poolheat/config.json")
        _miner_poller_proc = subprocess.Popen(
            cmd,
            cwd=str(Path(__file__).resolve().parent),
            env=env,
            stdout=logf or subprocess.DEVNULL,
            stderr=subprocess.STDOUT if logf else subprocess.DEVNULL,
            start_new_session=True,
        )
        # Seed pidfile immediately so writes/alive work before Go Run() writes it.
        try:
            MINER_POLLER_PIDFILE.parent.mkdir(parents=True, exist_ok=True)
            MINER_POLLER_PIDFILE.write_text(
                str(_miner_poller_proc.pid) + "\n", encoding="utf-8"
            )
        except Exception as e:
            print(f"miner-poller:      pidfile seed: {e}", flush=True)
        print(
            f"miner-poller:      {kind} pid {_miner_poller_proc.pid} · "
            f"log {MINER_POLLER_LOG}"
            + (f" · bin {go_bin}" if go_bin else ""),
            flush=True,
        )
        if go_bin:
            try:
                bi = _poller_bin_info(go_bin)
                print(
                    f"miner-poller:      version={bi.get('version')!r} "
                    f"size={bi.get('size')} mtime={bi.get('mtime')}",
                    flush=True,
                )
            except Exception as e:
                print(f"miner-poller:      version probe: {e}", flush=True)
        # Go poller: live_cache + mining_work + chipmap_cache.json.
        # History samples may stay in serve (read live_cache only, no ASIC).
        if go_bin:
            if role_enabled("edge_history"):
                try:
                    th = threading.Thread(
                        target=collector_loop,
                        name="history-collector",
                        daemon=True,
                    )
                    th.start()
                    print(
                        "history:           in serve (from live_cache · go miner-poller)",
                        flush=True,
                    )
                except Exception as e:
                    print(f"history:           failed to start in serve: {e}", flush=True)
            print(
                "chipmap:           in miner-poller → chipmap_cache.json (serve read-only)",
                flush=True,
            )
    except Exception as e:
        print(f"miner-poller:      failed to start: {e}", flush=True)
        _miner_poller_proc = None
        if logf:
            try:
                logf.close()
            except Exception:
                pass


def stop_miner_poller_process() -> None:
    global _miner_poller_proc
    proc = _miner_poller_proc
    _miner_poller_proc = None
    pids: list[int] = []
    if proc is not None:
        try:
            if proc.poll() is None:
                pids.append(int(proc.pid))
                proc.terminate()
        except Exception:
            pass
    try:
        if MINER_POLLER_PIDFILE.is_file():
            pid = int(MINER_POLLER_PIDFILE.read_text().strip() or "0")
            if pid > 1 and pid != os.getpid():
                pids.append(pid)
                try:
                    os.kill(pid, signal.SIGTERM)
                except Exception:
                    pass
    except Exception:
        pass
    # wait briefly; force_stop will SIGKILL leftovers
    if pids:
        _wait_pids_dead(pids, timeout_sec=2.0)
    if proc is not None:
        try:
            if proc.poll() is None:
                proc.kill()
                proc.wait(timeout=2)
        except Exception:
            pass


def get_device_status(did: str, *, probe_live: bool = False) -> dict:
    d = get_device_by_id(did, redact=True)
    if not d:
        return {"ok": False, "error": "not found"}
    if probe_live and d.get("enabled") is not False and _device_ready(d):
        try:
            device_test(did)
            d = get_device_by_id(did, redact=True) or d
        except Exception:
            pass
    mid = str(d.get("miner_id") or "").strip()
    work = device_mining_work(d) if mid else None
    mining = work == "resume" if work else None
    on = d.get("last_on")
    # Unbound: no mining gates (can always toggle)
    if not mid or work is None:
        can_off = True
        can_on = True
    else:
        can_off = bool(d.get("allow_off_while_mining")) or not (
            bool(d.get("enabled")) and mining is True and on is True
        )
        can_on = bool(d.get("allow_on_while_suspend")) or not (
            bool(d.get("enabled")) and mining is False and on is False
        )
    return {
        "ok": True,
        **d,
        "miner_id": mid or None,
        "miner_label": _miner_label_for_id(mid),
        "mining": mining,
        "bound_mining_work": work,
        "can_turn_off": can_off,
        "can_turn_on": can_on,
    }


def devices_probe_live(*, max_devices: int = 24) -> dict:
    """
    Best-effort live status + power for ready devices (used by Refresh).
    Same path as poller status tick (reported / enforce / adopt).
    """
    probed = 0
    errors = 0
    with _devices_cfg_lock:
        ids = [
            str(d.get("id") or "")
            for d in (_devices_cfg.get("devices") or [])
            if d.get("enabled") is not False and str(d.get("id") or "")
        ]
    for did in ids[: max(1, int(max_devices))]:
        cfg = _device_cfg_snapshot(did)
        if not cfg or not _device_ready(cfg):
            continue
        try:
            res = device_poll_status(did, source="probe", apply_policy=True)
            if res.get("ok"):
                probed += 1
            else:
                errors += 1
        except Exception:
            errors += 1
    return {"probed": probed, "errors": errors}


# Background hold (enforce_desired) in serve process — same tinytuya path as UI
# Refresh. Go devices-poller may miss Tuya restore; this guarantees SmartLife
# toggles are reversed without opening the UI.
_devices_hold_stop = threading.Event()


def devices_hold_tick() -> dict:
    """No-op — hold is devices-poller only."""
    return {"checked": 0, "restored": 0, "errors": 0, "disabled": True}


def devices_hold_loop() -> None:
    """
    Removed: enforce_desired runs only in Go devices-poller.
    (tinytuya no longer loaded in serve.)
    """
    print("[devices-hold] disabled in serve — devices-poller owns hold", flush=True)
    _devices_hold_stop.wait()


def device_display_name(d: dict, lang: str = "ru") -> str:
    """Pick name_en / name_ru by chat/UI language."""
    if not isinstance(d, dict):
        return ""
    en = str(d.get("name_en") or d.get("name") or "").strip()
    ru = str(d.get("name_ru") or d.get("name") or "").strip()
    if str(lang or "ru").lower().startswith("en"):
        return en or ru or str(d.get("alias") or d.get("id") or "")
    return ru or en or str(d.get("alias") or d.get("id") or "")


def list_devices_bot_buttons(lang: str = "ru") -> list[dict]:
    """Enabled devices with show_in_bot for Telegram keyboard."""
    out = []
    for d in list_devices(redact=True):
        if not d.get("enabled"):
            continue
        if not d.get("show_in_bot"):
            continue
        out.append(
            {
                "id": d.get("id"),
                "alias": d.get("alias"),
                "name": device_display_name(d, lang),
                "name_en": d.get("name_en") or d.get("name"),
                "name_ru": d.get("name_ru") or d.get("name"),
                "icon": d.get("icon") or "🔌",
                "description": d.get("description") or "",
                "on": d.get("last_on"),
            }
        )
    return out


# ── Chip map (LuCI Miner API Log scrape) ─────────────────────────────────────
# Source: https://<miner>/cgi-bin/luci/admin/status/btminerapi
# Per-chip: C0..C263 × slot 0..3 · temp · freq · vol · nonce · pct · err
# Hash map metric = nonce (work found); pct is a separate API field, not hashrate.

DEFAULT_CHIPMAP_CFG: dict = {
    "enabled": True,
    "poll_interval_sec": 30,  # separate from miner live poll
    "web_user": "admin",
    "web_password": "",  # empty → DEFAULT_API_PASSWORD
    "web_scheme": "https",  # https | http
    "verify_tls": False,
    "persist_cache": True,  # write chipmap_cache.json under DATA
}

_chipmap_lock = threading.Lock()
_chipmap_cfg: dict = dict(DEFAULT_CHIPMAP_CFG)
_chipmap_cache: dict = {
    "ok": False,
    "ts": None,
    "fetch_ms": None,
    "error": None,
    "boards": [],
    "chip_count": 0,
    "temp_min": None,
    "temp_max": None,
    "temp_avg": None,
}
_chipmap_stop = threading.Event()

_CHIP_LINE_RE = re.compile(
    r"C(\d+)\s+freq:(\d+)\s+vol:(\d+)\s+temp:([\d.]+)\s+"
    r"nonce:(\d+)\s+err:(\d+)\s+crc:(\d+)\s+"
    r"x:(\d+)\s*/\s*(\d+)\s+repeat:(\d+)\s+"
    r"pct:\s*([\d.]+)\s*%\s*/\s*([\d.]+)\s*%",
    re.I,
)
_SLOT_HDR_RE = re.compile(
    r"slot:\s*(\d+)\s*,\s*freq:\s*([\d.]+)\s*,\s*temp:\s*([\d.]+)",
    re.I,
)


def _load_chipmap_cfg() -> None:
    global _chipmap_cfg
    with _chipmap_lock:
        raw = _load_json(CHIPMAP_CFG_FILE, DEFAULT_CHIPMAP_CFG)
        if not isinstance(raw, dict):
            raw = {}
        cfg = dict(DEFAULT_CHIPMAP_CFG)
        cfg["enabled"] = bool(raw.get("enabled", True))
        try:
            pi = int(raw.get("poll_interval_sec", 30) or 30)
        except (TypeError, ValueError):
            pi = 30
        cfg["poll_interval_sec"] = max(10, min(600, pi))
        cfg["web_user"] = str(raw.get("web_user") or "admin").strip() or "admin"
        cfg["web_password"] = str(raw.get("web_password") or "")
        sch = str(raw.get("web_scheme") or "https").strip().lower()
        cfg["web_scheme"] = "http" if sch == "http" else "https"
        cfg["verify_tls"] = bool(raw.get("verify_tls", False))
        cfg["persist_cache"] = bool(raw.get("persist_cache", True))
        _chipmap_cfg = cfg


def _save_chipmap_cfg() -> None:
    with _chipmap_lock:
        _save_json(CHIPMAP_CFG_FILE, _chipmap_cfg)


def _chipmap_persist_cache_enabled() -> bool:
    with _chipmap_lock:
        return bool(_chipmap_cfg.get("persist_cache", True))


def _chipmap_cache_is_persistable(data: dict | None) -> bool:
    """Only persist successful scrapes with board/chip data."""
    if not isinstance(data, dict):
        return False
    if data.get("reason") in ("suspend", "disabled", "error"):
        return False
    if data.get("ok") is False and not data.get("boards"):
        return False
    boards = data.get("boards")
    if not isinstance(boards, list) or not boards:
        return False
    try:
        n = int(data.get("chip_count") or 0)
    except (TypeError, ValueError):
        n = 0
    if n <= 0:
        n = sum(len(b.get("chips") or []) for b in boards if isinstance(b, dict))
    return n > 0


# Compact chip records for disk/RAM (drop nulls + rarely used UI fields)
_CHIPMAP_CHIP_KEEP: tuple[str, ...] = (
    "id",
    "freq",
    "vol",
    "temp",
    "nonce",
    "err",
    "crc",
    "x",
    "x2",
    "repeat",
    "pct",
    "pct2",
    "hash_share",
    "est_th",
    "nonce_rate",
)


def _chipmap_compact_chip(c: dict) -> dict:
    if not isinstance(c, dict):
        return {}
    out: dict = {}
    for k in _CHIPMAP_CHIP_KEEP:
        if k not in c:
            continue
        v = c.get(k)
        if v is None or v == "":
            continue
        out[k] = v
    return out


def _chipmap_compact_payload(data: dict) -> dict:
    """
    Smaller boards/chips for disk + RAM.
    Keeps UI-needed fields; drops nulls and model noise where possible.
    """
    if not isinstance(data, dict):
        return {}
    out = dict(data)
    boards_in = out.get("boards")
    if isinstance(boards_in, list):
        boards_out: list = []
        for b in boards_in:
            if not isinstance(b, dict):
                continue
            nb = {
                k: b.get(k)
                for k in (
                    "slot",
                    "board_freq",
                    "board_temp",
                    "chip_count",
                    "temp_min",
                    "temp_max",
                    "temp_avg",
                    "nonce_sum",
                )
                if b.get(k) is not None or k in ("slot", "chip_count")
            }
            chips = b.get("chips") if isinstance(b.get("chips"), list) else []
            nb["chips"] = [
                _chipmap_compact_chip(c) for c in chips if isinstance(c, dict)
            ]
            if "chip_count" not in nb:
                nb["chip_count"] = len(nb["chips"])
            boards_out.append(nb)
        out["boards"] = boards_out
    # drop huge nested model profiles from cache if present
    if isinstance(out.get("model"), dict):
        m = out["model"]
        out["model"] = {
            k: m.get(k)
            for k in (
                "id",
                "name",
                "family",
                "layout",
                "cooling",
                "algo",
                "algo_display",
                "coin",
                "boards",
                "chips_per_board",
                "cpd",
                "link",
            )
            if m.get(k) is not None
        }
    return out


def _chipmap_summary_only(data: dict) -> dict:
    """RAM-light status without per-chip arrays (disk holds full map)."""
    if not isinstance(data, dict):
        return {}
    keys = (
        "ok",
        "ts",
        "fetch_ms",
        "error",
        "reason",
        "message",
        "source",
        "host",
        "miner_type",
        "chip_count",
        "board_count",
        "temp_min",
        "temp_max",
        "temp_avg",
        "nonce_total",
        "hashrate_th",
        "mining_elapsed",
        "stale",
        "from_disk",
        "persisted",
        "persisted_at",
        "last_good_ts",
        "disk_cache",
    )
    out = {k: data.get(k) for k in keys if k in data or k in ("ok", "ts")}
    out["boards"] = []
    out["boards_in_ram"] = False
    out["disk_cache"] = True
    return out


def _clear_chipmap_cache_disk() -> None:
    """Remove on-disk chipmap cache (when persist is turned off)."""
    try:
        if CHIPMAP_CACHE_FILE.is_file():
            CHIPMAP_CACHE_FILE.unlink()
            print("[chipmap] disk cache removed (persist_cache off)")
    except Exception as e:
        print(f"[chipmap] cache unlink: {e}")


def _read_chipmap_cache_disk() -> dict | None:
    """Read full chipmap from disk (no RAM mutation)."""
    try:
        if not CHIPMAP_CACHE_FILE.is_file():
            return None
        raw = json.loads(CHIPMAP_CACHE_FILE.read_text(encoding="utf-8"))
        if not _chipmap_cache_is_persistable(raw):
            return None
        raw = _chipmap_compact_payload(dict(raw))
        raw["stale"] = True
        raw["source"] = raw.get("source") or "disk"
        raw["from_disk"] = True
        raw["disk_cache"] = True
        # full boards live on disk; caller decides whether to pin them in RAM
        raw["boards_in_ram"] = False
        return raw
    except Exception as e:
        print(f"[chipmap] cache read: {e}")
        return None


def _save_chipmap_cache_disk(data: dict | None = None) -> bool:
    """Write last good chipmap to disk (survives service restart). Compact form."""
    try:
        if not _chipmap_persist_cache_enabled():
            return False
        with _chipmap_lock:
            payload = dict(data) if isinstance(data, dict) else dict(_chipmap_cache)
        if not _chipmap_cache_is_persistable(payload):
            return False
        payload = _chipmap_compact_payload(payload)
        to_save = {
            k: payload.get(k)
            for k in (
                "ok",
                "ts",
                "fetch_ms",
                "error",
                "reason",
                "message",
                "source",
                "host",
                "miner_type",
                "model",
                "boards",
                "chip_count",
                "board_count",
                "temp_min",
                "temp_max",
                "temp_avg",
                "nonce_total",
                "hashrate_th",
                "mining_elapsed",
            )
            if k in payload or k in ("ok", "ts", "boards", "chip_count")
        }
        to_save["ok"] = True
        to_save["persisted"] = True
        to_save["persisted_at"] = datetime.now().isoformat(timespec="seconds")
        CHIPMAP_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
        # atomic write
        tmp = CHIPMAP_CACHE_FILE.with_suffix(".json.tmp")
        tmp.write_text(
            json.dumps(to_save, ensure_ascii=False, separators=(",", ":")) + "\n",
            encoding="utf-8",
        )
        tmp.replace(CHIPMAP_CACHE_FILE)
        return True
    except Exception as e:
        print(f"[chipmap] cache save: {e}")
        return False


def _load_chipmap_cache_disk(*, into_ram: bool = True) -> dict | None:
    """
    Restore last chipmap from disk.
    into_ram=True: full map in RAM (boot / explicit UI need).
    into_ram=False: only summary in RAM (memory-light).
    """
    global _chipmap_cache
    try:
        if not _chipmap_persist_cache_enabled():
            return None
        raw = _read_chipmap_cache_disk()
        if not raw:
            return None
        if into_ram:
            with _chipmap_lock:
                _chipmap_cache.clear()
                _chipmap_cache.update(raw)
                _chipmap_cache["boards_in_ram"] = True
        else:
            # summary only — full boards stay on disk until get_chipmap needs them
            summary = _chipmap_summary_only(raw)
            summary["stale"] = True
            summary["from_disk"] = True
            with _chipmap_lock:
                _chipmap_cache.clear()
                _chipmap_cache.update(summary)
        n = raw.get("chip_count") or 0
        mode = "full" if into_ram else "summary"
        print(
            f"[chipmap] restored disk cache ({mode}) · chips {n} · ts {raw.get('ts')}"
        )
        return raw if into_ram else _chipmap_cache
    except Exception as e:
        print(f"[chipmap] cache load: {e}")
        return None


def _chipmap_ensure_boards_in_ram() -> dict:
    """
    Return full map for one-shot use (disk preferred).
    Does not pin boards into long-lived RAM — summary stays in _chipmap_cache.
    """
    with _chipmap_lock:
        cur = dict(_chipmap_cache)
        if cur.get("boards"):
            return cur
    disk = _read_chipmap_cache_disk()
    if disk and disk.get("boards"):
        return dict(disk)
    return cur


def get_chipmap_cfg(*, redact: bool = True) -> dict:
    with _chipmap_lock:
        cfg = dict(_chipmap_cfg)
    if redact:
        if cfg.get("web_password"):
            p = str(cfg["web_password"])
            cfg["web_password_set"] = True
            cfg["web_password"] = (p[:2] + "…" + p[-2:]) if len(p) > 6 else "••••"
        else:
            # empty means fallback to miner API password
            cfg["web_password_set"] = bool(DEFAULT_API_PASSWORD)
            cfg["web_password"] = ""
            cfg["web_password_uses_miner"] = True
    else:
        cfg["web_password_set"] = bool(cfg.get("web_password") or DEFAULT_API_PASSWORD)
    return cfg


def apply_chipmap_cfg(req: dict) -> dict:
    if not isinstance(req, dict):
        raise ValueError("expected object")
    with _chipmap_lock:
        if "enabled" in req:
            _chipmap_cfg["enabled"] = bool(req["enabled"])
        if "poll_interval_sec" in req and req["poll_interval_sec"] is not None:
            try:
                _chipmap_cfg["poll_interval_sec"] = max(
                    10, min(600, int(req["poll_interval_sec"]))
                )
            except (TypeError, ValueError):
                pass
        if "web_user" in req and req["web_user"] is not None:
            _chipmap_cfg["web_user"] = str(req["web_user"]).strip() or "admin"
        if "web_password" in req and req["web_password"] is not None and str(req["web_password"]) != "":
            _chipmap_cfg["web_password"] = str(req["web_password"])
        if "web_scheme" in req and req["web_scheme"] is not None:
            sch = str(req["web_scheme"]).strip().lower()
            _chipmap_cfg["web_scheme"] = "http" if sch == "http" else "https"
        if "verify_tls" in req:
            _chipmap_cfg["verify_tls"] = bool(req["verify_tls"])
        if "persist_cache" in req:
            _chipmap_cfg["persist_cache"] = bool(req["persist_cache"])
    turned_off = (
        isinstance(req, dict)
        and "persist_cache" in req
        and not bool(req.get("persist_cache"))
    )
    _save_chipmap_cfg()
    if turned_off:
        _clear_chipmap_cache_disk()
    return get_chipmap_cfg(redact=True)


def _chipmap_web_password() -> str:
    with _chipmap_lock:
        pw = str(_chipmap_cfg.get("web_password") or "").strip()
    return pw if pw else str(DEFAULT_API_PASSWORD or "admin")


def _chipmap_base_url() -> str:
    with _chipmap_lock:
        scheme = _chipmap_cfg.get("web_scheme") or "https"
    with _miner_cfg_lock:
        host = HOST_MINER
    return f"{scheme}://{host}"


def parse_chipmap_log(text: str) -> dict:
    """Parse LuCI Miner API Log textarea into boards/chips structure."""
    boards_map: dict[int, dict] = {}
    current_slot: int | None = None
    temps: list[float] = []

    for line in (text or "").splitlines():
        line = line.strip()
        if not line:
            continue
        mh = _SLOT_HDR_RE.search(line)
        if mh:
            current_slot = int(mh.group(1))
            if current_slot not in boards_map:
                boards_map[current_slot] = {
                    "slot": current_slot,
                    "board_freq": _f(mh.group(2)),
                    "board_temp": _f(mh.group(3)),
                    "chips": [],
                }
            else:
                boards_map[current_slot]["board_freq"] = _f(mh.group(2))
                boards_map[current_slot]["board_temp"] = _f(mh.group(3))
            continue
        mc = _CHIP_LINE_RE.search(line)
        if mc and current_slot is not None:
            if current_slot not in boards_map:
                boards_map[current_slot] = {
                    "slot": current_slot,
                    "board_freq": None,
                    "board_temp": None,
                    "chips": [],
                }
            temp = _f(mc.group(4))
            pct = _f(mc.group(11))
            chip = {
                "id": int(mc.group(1)),
                "freq": int(mc.group(2)),
                "vol": int(mc.group(3)),
                "temp": temp,
                "nonce": int(mc.group(5)),
                "err": int(mc.group(6)),
                "crc": int(mc.group(7)),
                "x": int(mc.group(8)),
                "x2": int(mc.group(9)),
                "repeat": int(mc.group(10)),
                "pct": pct,
                "pct2": _f(mc.group(12)),
            }
            boards_map[current_slot]["chips"].append(chip)
            if temp is not None:
                temps.append(float(temp))

    boards = [boards_map[k] for k in sorted(boards_map.keys())]
    for b in boards:
        b["chips"].sort(key=lambda c: c["id"])
        b["chip_count"] = len(b["chips"])
        cts = [c["temp"] for c in b["chips"] if c.get("temp") is not None]
        b["temp_min"] = min(cts) if cts else None
        b["temp_max"] = max(cts) if cts else None
        b["temp_avg"] = (sum(cts) / len(cts)) if cts else None
        nsum = sum(int(c.get("nonce") or 0) for c in b["chips"])
        b["nonce_sum"] = nsum
        # relative share of board hash work (nonce / board total)
        for c in b["chips"]:
            try:
                n = int(c.get("nonce") or 0)
            except (TypeError, ValueError):
                n = 0
            c["hash_share"] = (
                round(100.0 * n / nsum, 3) if nsum > 0 else 0.0
            )

    chip_count = sum(b["chip_count"] for b in boards)
    total_nonce = sum(int(b.get("nonce_sum") or 0) for b in boards)
    return {
        "boards": boards,
        "chip_count": chip_count,
        "board_count": len(boards),
        "nonce_total": total_nonce,
        "temp_min": min(temps) if temps else None,
        "temp_max": max(temps) if temps else None,
        "temp_avg": (sum(temps) / len(temps)) if temps else None,
    }


def _chipmap_attach_hash_estimates(payload: dict) -> dict:
    """
    Per-chip hashrate estimate using mining Elapsed as time base.

    If nonce is cumulative since mining start:
      nonce_rate = nonce / elapsed          (nonce/s)
      est_th     = HR_total × nonce / Σnonce (TH/s)

    Share method is preferred for TH/s (elapsed cancels out when nonce
    is proportional to work over the same window). Elapsed is still used
    for nonce/s and status, and as a sanity check (elapsed > 0).
    """
    if not isinstance(payload, dict):
        return payload
    if payload.get("reason") == "suspend":
        return payload
    boards = payload.get("boards")
    if not isinstance(boards, list) or not boards:
        return payload

    elapsed = None
    hr = None
    try:
        live = live_snapshot(max_age_sec=LIVE_STALE_MAX_SEC)
        elapsed = _f(live.get("elapsed"))
        hr = _f(live.get("hashrate_th"))
    except Exception:
        pass

    total_nonce = int(payload.get("nonce_total") or 0)
    if total_nonce <= 0:
        total_nonce = 0
        for b in boards:
            for c in b.get("chips") or []:
                try:
                    total_nonce += int(c.get("nonce") or 0)
                except (TypeError, ValueError):
                    pass
        payload["nonce_total"] = total_nonce

    payload["mining_elapsed"] = elapsed
    payload["hashrate_th"] = hr
    el = float(elapsed) if elapsed is not None and float(elapsed) > 0 else None
    hr_ok = hr is not None and float(hr) > 0

    for b in boards:
        for c in b.get("chips") or []:
            try:
                n = int(c.get("nonce") or 0)
            except (TypeError, ValueError):
                n = 0
            if el is not None:
                c["nonce_rate"] = round(n / el, 6)  # nonce / s over mining elapsed
            else:
                c["nonce_rate"] = None
            if total_nonce > 0:
                share = n / float(total_nonce)
                c["hash_share_asic"] = round(100.0 * share, 4)
                if hr_ok:
                    # primary estimate: distribute measured ASIC HR by nonce share
                    c["est_th"] = round(float(hr) * share, 4)
                else:
                    c["est_th"] = None
            else:
                c["hash_share_asic"] = 0.0
                c["est_th"] = None
    return payload


def _chipmap_is_mining() -> tuple[bool | None, str]:
    """
    Whether boards are powered for chip log.
    Returns (is_mining, detail):
      True  — mining / boards expected live
      False — suspend / sleep (chip map N/A by design)
      None  — miner live API unreachable (real offline / auth issue possible)
    """
    try:
        live = live_snapshot(max_age_sec=LIVE_STALE_MAX_SEC)
    except Exception as e:
        return None, str(e)
    try:
        work = str(live.get("work_measured") or "").strip().lower()
        if not work:
            work = _measured_work_state(live)
        if work in ("suspend", "sleep"):
            return False, "suspend"
        if work in ("resume", "mining"):
            return True, "mining"
        # fallback measured
        mw = _measured_work_state(live)
        if mw in ("sleep", "suspend"):
            return False, "suspend"
        return True, mw or "mining"
    except Exception as e:
        return None, str(e)


def _chipmap_suspend_payload(*, fetch_ms: int | None = None) -> dict:
    """
    Friendly non-error status when ASIC is online but Suspend (no board power).
    Memory: do NOT keep 1k+ chips in RAM — full map stays on disk only.
    """
    msg = (
        "Mining Suspend · карты чипов доступны только при майнинге "
        "(когда есть питание на платах)."
    )
    out = {
        "ok": True,
        "reason": "suspend",
        "message": msg,
        "error": None,
        "ts": datetime.now().isoformat(timespec="seconds"),
        "fetch_ms": fetch_ms if fetch_ms is not None else 0,
        "source": "mining_state",
        "boards": [],
        "board_count": 0,
        "chip_count": 0,
        "temp_min": None,
        "temp_max": None,
        "temp_avg": None,
        "stale": False,
        "boards_in_ram": False,
    }
    # Prefer disk last-good summary (no full boards in RAM during suspend)
    disk = None
    if _chipmap_persist_cache_enabled():
        disk = _read_chipmap_cache_disk()
    with _chipmap_lock:
        prev = dict(_chipmap_cache)
        meta_src = disk if disk else prev
        if (
            meta_src
            and meta_src.get("chip_count")
            and meta_src.get("reason") != "suspend"
        ):
            out["board_count"] = meta_src.get("board_count") or 0
            out["chip_count"] = meta_src.get("chip_count")
            out["temp_min"] = meta_src.get("temp_min")
            out["temp_max"] = meta_src.get("temp_max")
            out["temp_avg"] = meta_src.get("temp_avg")
            out["miner_type"] = meta_src.get("miner_type")
            out["stale"] = True
            out["last_good_ts"] = meta_src.get("ts")
            out["disk_cache"] = bool(disk and disk.get("boards"))
            out["message"] = (
                msg
                + (
                    " · last map on disk (open Chips to load)"
                    if out["disk_cache"]
                    else " · last map cached"
                )
            )
        # Drop heavy boards from RAM — disk keeps them
        _chipmap_cache.clear()
        _chipmap_cache.update(_chipmap_summary_only(out))
        _chipmap_cache["reason"] = "suspend"
        _chipmap_cache["message"] = out["message"]
        _chipmap_cache["ok"] = True
    # never overwrite disk with empty suspend payload
    # If UI needs boards, get_chipmap hydrates from disk
    if disk and disk.get("boards"):
        out = dict(disk)
        out["reason"] = "suspend"
        out["message"] = msg + " · last map from disk"
        out["stale"] = True
        out["ok"] = True
        out["error"] = None
        out["fetch_ms"] = fetch_ms if fetch_ms is not None else 0
        out["from_disk"] = True
    return out


def fetch_chipmap_from_luci(*, force: bool = False) -> dict:
    """
    Removed from serve — Go miner-poller writes chipmap_cache.json.
    """
    raise RuntimeError(
        "chipmap scrape removed from serve — use miner-poller chipmap_cache.json"
    )


def request_chipmap_refresh(*, timeout_sec: float = 45.0) -> dict:
    """
    Ask Go miner-poller to refresh chipmap_cache.json (file IPC).
    """
    if not miner_poller_process_alive():
        return {"ok": False, "error": "miner-poller not running"}
    req_id = uuid.uuid4().hex
    req_path = DATA / "chipmap_req.json"
    res_path = DATA / "chipmap_result.json"
    try:
        if res_path.is_file():
            res_path.unlink()
    except Exception:
        pass
    _write_json_atomic(req_path, {"id": req_id, "ts": time.time(), "force": True})
    deadline = time.time() + max(5.0, float(timeout_sec))
    while time.time() < deadline:
        time.sleep(0.25)
        try:
            if not res_path.is_file():
                continue
            raw = json.loads(res_path.read_text(encoding="utf-8"))
            if not isinstance(raw, dict) or str(raw.get("id") or "") != req_id:
                continue
            return raw
        except Exception:
            continue
    # even without result file, cache may have been updated
    disk = _read_chipmap_cache_disk()
    if disk and disk.get("ok"):
        return {"ok": True, "id": req_id, "from_cache": True}
    return {"ok": False, "error": "timeout waiting for chipmap refresh", "id": req_id}


def get_chipmap(*, force: bool = False) -> dict:
    """
    Return chipmap for UI from chipmap_cache.json only.
    Poller writes the full ready JSON; serve never scrapes LuCI.
    force=True enqueues chipmap_req.json and waits briefly for refresh.
    """
    if force:
        request_chipmap_refresh(timeout_sec=45.0)
    disk = _read_chipmap_cache_disk()
    if disk and (disk.get("boards") is not None or disk.get("ok") is not None):
        out = dict(disk)
        out["from_disk"] = True
        out["boards_in_ram"] = False
        # light RAM summary only
        with _chipmap_lock:
            _chipmap_cache.clear()
            _chipmap_cache.update(_chipmap_summary_only(out) if out.get("boards") else out)
            _chipmap_cache["boards_in_ram"] = False
        return out
    with _chipmap_lock:
        ram = dict(_chipmap_cache)
    if ram:
        ram = dict(ram)
        ram.setdefault("ok", False)
        ram.setdefault("error", "no chipmap_cache.json yet — wait for miner-poller")
        ram["from_disk"] = False
        return ram
    return {
        "ok": False,
        "error": "no chipmap_cache.json — miner-poller chipmap not ready",
        "boards": [],
        "chip_count": 0,
        "from_disk": False,
    }


def chipmap_loop() -> None:
    """
    Deprecated in serve: chipmap is owned by Go miner-poller
    (writes chipmap_cache.json). Kept as no-op for --miner-poller python fallback.
    """
    print("[chipmap] loop disabled in serve — use poolheat-miner-poller", flush=True)
    while not _chipmap_stop.is_set():
        _chipmap_stop.wait(timeout=60.0)


# ── LuCI reverse proxy (:8788 → miner web UI) ────────────────────────────────

_luci_proxy_import_error: str | None = None


def _import_luci_proxy():
    """Load luci_proxy module from same dir as serve.py (Entware or local)."""
    global _luci_proxy_import_error
    import importlib
    import sys as _sys

    _lib = Path(__file__).resolve().parent
    if str(_lib) not in _sys.path:
        _sys.path.insert(0, str(_lib))

    # Prefer fresh load from file (handles OTA without full process restart edge cases)
    mod_path = _lib / "luci_proxy.py"
    try:
        if "luci_proxy" in _sys.modules:
            mod = importlib.reload(_sys.modules["luci_proxy"])
        elif mod_path.is_file():
            import importlib.util

            spec = importlib.util.spec_from_file_location("luci_proxy", mod_path)
            if spec is None or spec.loader is None:
                raise ImportError(f"no spec for {mod_path}")
            mod = importlib.util.module_from_spec(spec)
            _sys.modules["luci_proxy"] = mod
            spec.loader.exec_module(mod)
        else:
            import luci_proxy as mod  # type: ignore
        _luci_proxy_import_error = None
        return mod
    except Exception as e:
        _luci_proxy_import_error = str(e)
        print(f"[luci-proxy] module unavailable: {e}")
        # last chance: plain import
        try:
            import luci_proxy as mod  # type: ignore

            _luci_proxy_import_error = None
            return mod
        except Exception as e2:
            _luci_proxy_import_error = str(e2)
            raise


try:
    luci_proxy = _import_luci_proxy()
except Exception as _lp_err:
    luci_proxy = None  # type: ignore
    _luci_proxy_import_error = str(_lp_err)
    print(f"[luci-proxy] module unavailable: {_lp_err}")

DEFAULT_LUCI_PROXY_CFG: dict = {
    "enabled": False,
    "bind": "0.0.0.0",
    "listen_port": 8788,
    "target_scheme": "https",
    "target_port": 443,
    "verify_tls": False,
}

_luci_proxy_cfg: dict = dict(DEFAULT_LUCI_PROXY_CFG)
_luci_proxy_cfg_lock = threading.Lock()


def _load_luci_proxy_cfg() -> None:
    global _luci_proxy_cfg
    raw = _load_json(LUCI_PROXY_CFG_FILE, DEFAULT_LUCI_PROXY_CFG)
    if not isinstance(raw, dict):
        raw = {}
    cfg = dict(DEFAULT_LUCI_PROXY_CFG)
    cfg["enabled"] = bool(raw.get("enabled", False))
    bind = str(raw.get("bind") or HTTP_BIND or "0.0.0.0").strip() or "0.0.0.0"
    cfg["bind"] = bind
    try:
        lp = int(raw.get("listen_port", 8788) or 8788)
    except (TypeError, ValueError):
        lp = 8788
    cfg["listen_port"] = max(1, min(65535, lp))
    sch = str(raw.get("target_scheme") or "https").strip().lower()
    cfg["target_scheme"] = "http" if sch == "http" else "https"
    try:
        default_port = 80 if cfg["target_scheme"] == "http" else 443
        tp = int(raw.get("target_port", default_port) or default_port)
    except (TypeError, ValueError):
        tp = 80 if cfg["target_scheme"] == "http" else 443
    cfg["target_port"] = max(1, min(65535, tp))
    cfg["verify_tls"] = bool(raw.get("verify_tls", False))
    with _luci_proxy_cfg_lock:
        _luci_proxy_cfg = cfg


def _save_luci_proxy_cfg() -> None:
    with _luci_proxy_cfg_lock:
        _save_json(LUCI_PROXY_CFG_FILE, _luci_proxy_cfg)


def get_luci_proxy_cfg() -> dict:
    with _luci_proxy_cfg_lock:
        cfg = dict(_luci_proxy_cfg)
    st: dict = {}
    if luci_proxy is not None:
        try:
            st = luci_proxy.status()
        except Exception as e:
            st = {"error": str(e), "running": False}
    else:
        st = {
            "running": False,
            "enabled": bool(cfg.get("enabled")),
            "error": (
                "luci_proxy module not loaded"
                + (f": {_luci_proxy_import_error}" if _luci_proxy_import_error else "")
                + " — check /opt/lib/poolheat/luci_proxy.py and restart service"
            ),
        }
    # if config says on but process not listening — surface clearly
    if cfg.get("enabled") and not st.get("running") and not st.get("error"):
        st["error"] = st.get("error") or "enabled but not listening (start failed?)"
    cfg["target_host"] = HOST_MINER
    cfg["module_loaded"] = luci_proxy is not None
    return {
        "ok": True,
        "config": cfg,
        "status": st,
        "url_hint": f"http://<router-ip>:{cfg.get('listen_port') or 8788}/",
    }


def apply_luci_proxy_cfg(req: dict) -> dict:
    """Update config, persist, start/stop proxy module."""
    global luci_proxy
    if not isinstance(req, dict):
        raise ValueError("expected object")
    with _luci_proxy_cfg_lock:
        if "enabled" in req:
            _luci_proxy_cfg["enabled"] = bool(req["enabled"])
        if "bind" in req and req["bind"] is not None and str(req["bind"]).strip():
            _luci_proxy_cfg["bind"] = str(req["bind"]).strip()
        if "listen_port" in req and req["listen_port"] is not None:
            try:
                _luci_proxy_cfg["listen_port"] = max(
                    1, min(65535, int(req["listen_port"]))
                )
            except (TypeError, ValueError):
                pass
        if "target_scheme" in req and req["target_scheme"] is not None:
            sch = str(req["target_scheme"]).strip().lower()
            _luci_proxy_cfg["target_scheme"] = "http" if sch == "http" else "https"
        if "target_port" in req and req["target_port"] is not None:
            try:
                _luci_proxy_cfg["target_port"] = max(
                    1, min(65535, int(req["target_port"]))
                )
            except (TypeError, ValueError):
                pass
        if "verify_tls" in req:
            _luci_proxy_cfg["verify_tls"] = bool(req["verify_tls"])
        snap = dict(_luci_proxy_cfg)
    _save_luci_proxy_cfg()

    # (re)load module so OTA fixes apply without full process edge cases;
    # stop old listener first if we are replacing a live module instance
    try:
        if luci_proxy is not None:
            try:
                luci_proxy.stop()
            except Exception:
                pass
        luci_proxy = _import_luci_proxy()
    except Exception as e:
        body = get_luci_proxy_cfg()
        body["ok"] = False
        body["error"] = f"luci_proxy module missing: {e}"
        return body

    apply_res = _luci_proxy_sync_runtime(snap)
    body = get_luci_proxy_cfg()
    if snap.get("enabled") and not (body.get("status") or {}).get("running"):
        body["ok"] = False
        err = (body.get("status") or {}).get("error") or (
            (apply_res or {}).get("error") if isinstance(apply_res, dict) else None
        )
        body["error"] = err or "proxy failed to start"
    elif isinstance(apply_res, dict) and apply_res.get("ok") is False:
        body["ok"] = False
        body["error"] = apply_res.get("error") or "proxy apply failed"
    return body


def _luci_proxy_sync_runtime(cfg: dict | None = None) -> dict:
    """Push settings into luci_proxy module and start/stop. Returns apply() result."""
    if luci_proxy is None:
        return {
            "ok": False,
            "error": "luci_proxy module not loaded"
            + (f": {_luci_proxy_import_error}" if _luci_proxy_import_error else ""),
        }
    if cfg is None:
        with _luci_proxy_cfg_lock:
            cfg = dict(_luci_proxy_cfg)
    try:
        luci_proxy.set_host_resolver(lambda: HOST_MINER)
        luci_proxy.configure(
            enabled=bool(cfg.get("enabled")),
            bind=str(cfg.get("bind") or HTTP_BIND or "0.0.0.0"),
            listen_port=int(cfg.get("listen_port") or 8788),
            target_scheme=str(cfg.get("target_scheme") or "https"),
            target_port=int(
                cfg.get("target_port")
                or (80 if cfg.get("target_scheme") == "http" else 443)
            ),
            verify_tls=bool(cfg.get("verify_tls", False)),
            target_host=str(HOST_MINER or ""),
        )
        res = luci_proxy.apply()
        if not isinstance(res, dict):
            res = {"ok": True, "result": res}
        return res
    except Exception as e:
        print(f"[luci-proxy] apply: {e}")
        return {"ok": False, "error": str(e)}


# ─── Optional module: miner sniffer (download from GitHub on activate) ────────

DEFAULT_SNIFFER_CFG: dict = {
    "enabled": False,
    "iface": "br0",
    "filter": "",  # empty → host <miner>
    "pcap_dir": "/tmp/poolheat-sniffer",
    "snaplen": 0,
    "installed_version": None,
    "installed_at": None,
    "source_ref": None,
}

# Install dir lives under DATA so uninstall frees user space without touching /opt package
SNIFFER_MODULE_DIR = DATA / "modules" / "miner_sniffer"
SNIFFER_MODULE_FILE = SNIFFER_MODULE_DIR / "miner_sniffer.py"
# Also try repo checkout (dev) next to package root
_SNIFFER_REPO_CANDIDATES = (
    Path(__file__).resolve().parent.parent / "modules" / "miner_sniffer" / "miner_sniffer.py",
    Path(__file__).resolve().parent / "modules" / "miner_sniffer" / "miner_sniffer.py",
    Path("/opt/lib/poolheat/modules/miner_sniffer/miner_sniffer.py"),
)

_sniffer_cfg: dict = dict(DEFAULT_SNIFFER_CFG)
_sniffer_cfg_lock = threading.Lock()
_sniffer_mod = None  # type: ignore
_sniffer_import_error: str | None = None
_sniffer_op_lock = threading.Lock()


def _sniffer_module_present() -> bool:
    return SNIFFER_MODULE_FILE.is_file()


def _import_miner_sniffer(force_reload: bool = False):
    """Load installed (or local repo) miner_sniffer module."""
    global _sniffer_mod, _sniffer_import_error
    import importlib
    import importlib.util
    import sys as _sys

    candidates: list[Path] = []
    if SNIFFER_MODULE_FILE.is_file():
        candidates.append(SNIFFER_MODULE_FILE)
    for p in _SNIFFER_REPO_CANDIDATES:
        try:
            if p.is_file() and p not in candidates:
                candidates.append(p)
        except Exception:
            pass

    if not candidates:
        _sniffer_mod = None
        _sniffer_import_error = "module not installed (enable in Advanced to download from GitHub)"
        return None

    last_err: str | None = None
    for mod_path in candidates:
        try:
            key = "poolheat_miner_sniffer"
            if force_reload and key in _sys.modules:
                del _sys.modules[key]
            if key in _sys.modules and not force_reload:
                mod = _sys.modules[key]
            else:
                spec = importlib.util.spec_from_file_location(key, mod_path)
                if spec is None or spec.loader is None:
                    raise ImportError(f"cannot load {mod_path}")
                mod = importlib.util.module_from_spec(spec)
                _sys.modules[key] = mod
                spec.loader.exec_module(mod)
            _sniffer_mod = mod
            _sniffer_import_error = None
            try:
                mod.set_install_dir(str(mod_path.parent))
            except Exception:
                pass
            return mod
        except Exception as e:
            last_err = str(e)
            continue
    _sniffer_mod = None
    _sniffer_import_error = last_err or "import failed"
    return None


def _load_sniffer_cfg() -> None:
    global _sniffer_cfg
    raw = _load_json(SNIFFER_CFG_FILE, DEFAULT_SNIFFER_CFG)
    if not isinstance(raw, dict):
        raw = {}
    cfg = dict(DEFAULT_SNIFFER_CFG)
    cfg["enabled"] = bool(raw.get("enabled", False))
    iface = str(raw.get("iface") or "br0").strip() or "br0"
    cfg["iface"] = iface
    cfg["filter"] = str(raw.get("filter") or "").strip()
    pdir = str(raw.get("pcap_dir") or "/tmp/poolheat-sniffer").strip()
    cfg["pcap_dir"] = pdir or "/tmp/poolheat-sniffer"
    try:
        cfg["snaplen"] = max(0, min(65535, int(raw.get("snaplen", 0) or 0)))
    except (TypeError, ValueError):
        cfg["snaplen"] = 0
    cfg["installed_version"] = raw.get("installed_version")
    cfg["installed_at"] = raw.get("installed_at")
    cfg["source_ref"] = raw.get("source_ref")
    with _sniffer_cfg_lock:
        _sniffer_cfg = cfg


def _save_sniffer_cfg() -> None:
    with _sniffer_cfg_lock:
        _save_json(SNIFFER_CFG_FILE, _sniffer_cfg)


def install_sniffer_module(*, ref: str | None = None, force: bool = False) -> dict:
    """
    Download miner_sniffer.py from GitHub (andreybmc/poolheat modules/ path)
    into DATA/modules/miner_sniffer/. Local repo copy used as fallback.
    """
    global _sniffer_mod
    if not _sniffer_op_lock.acquire(blocking=False):
        return {"ok": False, "error": "sniffer install already in progress"}
    try:
        if _sniffer_module_present() and not force:
            mod = _import_miner_sniffer(force_reload=True)
            ver = getattr(mod, "MODULE_VERSION", None) if mod else None
            with _sniffer_cfg_lock:
                if ver:
                    _sniffer_cfg["installed_version"] = ver
            _save_sniffer_cfg()
            return {
                "ok": True,
                "already": True,
                "path": str(SNIFFER_MODULE_FILE),
                "version": ver,
            }

        target_ref = (ref or GITHUB_BRANCH or "main").strip() or "main"
        SNIFFER_MODULE_DIR.mkdir(parents=True, exist_ok=True)

        # 1) Prefer local checkout (dev / same repo tree)
        for src in _SNIFFER_REPO_CANDIDATES:
            try:
                if src.is_file() and src.resolve() != SNIFFER_MODULE_FILE.resolve():
                    shutil.copy2(src, SNIFFER_MODULE_FILE)
                    # optional README
                    readme_src = src.parent / "README.md"
                    if readme_src.is_file():
                        shutil.copy2(readme_src, SNIFFER_MODULE_DIR / "README.md")
                    mod = _import_miner_sniffer(force_reload=True)
                    ver = getattr(mod, "MODULE_VERSION", None) if mod else None
                    with _sniffer_cfg_lock:
                        _sniffer_cfg["installed_version"] = ver
                        _sniffer_cfg["installed_at"] = datetime.now().isoformat(
                            timespec="seconds"
                        )
                        _sniffer_cfg["source_ref"] = f"local:{src}"
                    _save_sniffer_cfg()
                    return {
                        "ok": True,
                        "path": str(SNIFFER_MODULE_FILE),
                        "version": ver,
                        "source": f"local:{src}",
                    }
            except Exception:
                continue

        # 2) GitHub raw single-file download (small, no full archive)
        rel = "modules/miner_sniffer/miner_sniffer.py"
        urls = [
            f"https://raw.githubusercontent.com/{GITHUB_REPO}/{target_ref}/{rel}",
            f"https://cdn.jsdelivr.net/gh/{GITHUB_REPO}@{target_ref}/{rel}",
        ]
        errors: list[str] = []
        blob: bytes | None = None
        used = None
        for u in urls:
            try:
                blob = _http_bytes(u, timeout=45)
                if blob and b"def start" in blob and b"tcpdump" in blob:
                    used = u
                    break
                errors.append(f"{u}: unexpected content")
                blob = None
            except Exception as e:
                errors.append(f"{u}: {e}")
                blob = None
        if not blob:
            # 3) fallback: full archive, extract module path only
            try:
                archive_url = (
                    f"https://github.com/{GITHUB_REPO}/archive/refs/heads/"
                    f"{target_ref}.tar.gz"
                )
                ablob = _http_bytes(archive_url, timeout=90)
                import tarfile
                import tempfile

                with tempfile.TemporaryDirectory(prefix="poolheat-sniff-") as td:
                    tgz = Path(td) / "src.tar.gz"
                    tgz.write_bytes(ablob)
                    with tarfile.open(tgz, "r:gz") as tar:
                        for m in tar.getmembers():
                            name = m.name.replace("\\", "/")
                            if name.startswith("/") or ".." in name.split("/"):
                                continue
                            parts = name.split("/", 1)
                            if len(parts) < 2:
                                continue
                            rel_path = parts[1]
                            if rel_path == rel and m.isfile():
                                f = tar.extractfile(m)
                                if f:
                                    blob = f.read()
                                    used = archive_url + "#" + rel
                                    break
            except Exception as e:
                errors.append(f"archive: {e}")

        if not blob:
            return {
                "ok": False,
                "error": "download failed: " + "; ".join(errors[:4]),
                "tried": urls,
            }

        SNIFFER_MODULE_FILE.write_bytes(blob)
        # try README
        try:
            readme_rel = "modules/miner_sniffer/README.md"
            rurl = (
                f"https://raw.githubusercontent.com/{GITHUB_REPO}/{target_ref}/{readme_rel}"
            )
            rblob = _http_bytes(rurl, timeout=20)
            if rblob and len(rblob) < 200_000:
                (SNIFFER_MODULE_DIR / "README.md").write_bytes(rblob)
        except Exception:
            pass

        mod = _import_miner_sniffer(force_reload=True)
        if mod is None:
            return {
                "ok": False,
                "error": f"downloaded but import failed: {_sniffer_import_error}",
                "path": str(SNIFFER_MODULE_FILE),
            }
        ver = getattr(mod, "MODULE_VERSION", None)
        with _sniffer_cfg_lock:
            _sniffer_cfg["installed_version"] = ver
            _sniffer_cfg["installed_at"] = datetime.now().isoformat(timespec="seconds")
            _sniffer_cfg["source_ref"] = used or target_ref
        _save_sniffer_cfg()
        return {
            "ok": True,
            "path": str(SNIFFER_MODULE_FILE),
            "version": ver,
            "source": used,
            "ref": target_ref,
        }
    finally:
        _sniffer_op_lock.release()


def uninstall_sniffer_module(*, remove_captures: bool = True) -> dict:
    """Stop capture, delete module files and config enable flag, free space."""
    global _sniffer_mod
    with _sniffer_cfg_lock:
        _sniffer_cfg["enabled"] = False
    _save_sniffer_cfg()

    stop_res: dict = {}
    mod = _sniffer_mod or _import_miner_sniffer()
    if mod is not None:
        try:
            stop_res = mod.uninstall_runtime(remove_captures=remove_captures)
        except Exception as e:
            stop_res = {"ok": False, "error": str(e)}
            try:
                mod.stop()
            except Exception:
                pass

    removed_files: list[str] = []
    # remove install tree under DATA
    if SNIFFER_MODULE_DIR.is_dir():
        for p in sorted(SNIFFER_MODULE_DIR.rglob("*"), reverse=True):
            try:
                if p.is_file() or p.is_symlink():
                    p.unlink()
                    removed_files.append(str(p))
                elif p.is_dir():
                    p.rmdir()
            except Exception:
                pass
        try:
            SNIFFER_MODULE_DIR.rmdir()
            removed_files.append(str(SNIFFER_MODULE_DIR))
        except Exception:
            pass
    # parent modules/ if empty
    try:
        parent = SNIFFER_MODULE_DIR.parent
        if parent.is_dir() and not any(parent.iterdir()):
            parent.rmdir()
    except Exception:
        pass

    # drop import
    import sys as _sys

    _sys.modules.pop("poolheat_miner_sniffer", None)
    _sniffer_mod = None

    with _sniffer_cfg_lock:
        _sniffer_cfg["installed_version"] = None
        _sniffer_cfg["installed_at"] = None
        _sniffer_cfg["source_ref"] = None
        _sniffer_cfg["enabled"] = False
    _save_sniffer_cfg()

    # optional: wipe pcap dir contents (usually /tmp/poolheat-sniffer)
    try:
        with _sniffer_cfg_lock:
            pdir = Path(str(_sniffer_cfg.get("pcap_dir") or "/tmp/poolheat-sniffer"))
        if remove_captures and pdir.is_dir():
            for p in pdir.iterdir():
                try:
                    if p.is_file():
                        p.unlink()
                        removed_files.append(str(p))
                except Exception:
                    pass
            try:
                pdir.rmdir()
            except Exception:
                pass
    except Exception:
        pass

    return {
        "ok": True,
        "stop": stop_res,
        "removed": removed_files[:50],
        "removed_count": len(removed_files),
        "installed": False,
        "enabled": False,
    }


def clear_sniffer_cache(*, keep_current: bool = False) -> dict:
    """
    Delete sniffer pcap / capture cache under pcap_dir (tmpfs).
    Does not uninstall the module. Stops nothing unless module clear requires it.
    """
    removed: list[str] = []
    errors: list[str] = []
    mod_res: dict | None = None
    # Prefer module helper if available
    mod = _sniffer_mod or (
        _import_miner_sniffer() if _sniffer_module_present() else None
    )
    if mod is not None and hasattr(mod, "clear_captures"):
        try:
            mod_res = mod.clear_captures(keep_current=bool(keep_current))
            if isinstance(mod_res, dict):
                for p in mod_res.get("removed") or []:
                    if p and str(p) not in removed:
                        removed.append(str(p))
        except Exception as e:
            errors.append(f"module: {e}")

    # Always wipe pcap_dir files (works even without module)
    try:
        with _sniffer_cfg_lock:
            pdir = Path(str(_sniffer_cfg.get("pcap_dir") or "/tmp/poolheat-sniffer"))
        current_name = None
        if keep_current and isinstance(mod_res, dict):
            cur = str(mod_res.get("current") or mod_res.get("pcap") or "")
            if cur:
                current_name = Path(cur).name
        if pdir.is_dir():
            for p in sorted(pdir.iterdir()):
                try:
                    if not p.is_file() and not p.is_symlink():
                        continue
                    if keep_current and current_name and p.name == current_name:
                        continue
                    # common capture artefacts only
                    suf = p.suffix.lower()
                    if (
                        suf in (".pcap", ".pcapng", ".cap", ".log", ".txt", ".gz")
                        or p.name.startswith("poolheat")
                        or p.name.startswith("wmt")
                        or p.name.startswith("capture")
                    ):
                        p.unlink()
                        removed.append(str(p))
                except Exception as e:
                    errors.append(f"{p}: {e}")
    except Exception as e:
        errors.append(str(e))

    return {
        "ok": len(errors) == 0 or bool(removed),
        "removed": removed[:80],
        "removed_count": len(removed),
        "keep_current": bool(keep_current),
        "error": "; ".join(errors[:5]) if errors else None,
        "module": mod_res,
    }


def get_sniffer_cfg() -> dict:
    with _sniffer_cfg_lock:
        cfg = dict(_sniffer_cfg)
    installed = _sniffer_module_present()
    # also count local repo as "available" for status
    local_available = any(p.is_file() for p in _SNIFFER_REPO_CANDIDATES)
    mod = _sniffer_mod
    if mod is None and (installed or local_available):
        mod = _import_miner_sniffer()
    st: dict = {}
    if mod is not None:
        try:
            st = mod.status()
        except Exception as e:
            st = {"running": False, "error": str(e)}
    else:
        st = {
            "running": False,
            "enabled": bool(cfg.get("enabled")),
            "error": _sniffer_import_error
            or ("not installed" if not installed else "module not loaded"),
            "tcpdump": None,
            "tcpdump_ok": False,
        }
        # still report tcpdump presence without module
        for c in (
            "/opt/bin/tcpdump",
            "/usr/sbin/tcpdump",
            "/usr/bin/tcpdump",
        ):
            if Path(c).is_file():
                st["tcpdump"] = c
                st["tcpdump_ok"] = True
                break

    cfg["installed"] = installed
    cfg["local_available"] = local_available
    cfg["module_loaded"] = mod is not None
    cfg["module_path"] = str(SNIFFER_MODULE_FILE) if installed else None
    cfg["miner_host"] = HOST_MINER
    if cfg.get("enabled") and not st.get("running") and not st.get("error"):
        st["error"] = st.get("error") or "enabled but capture not running"

    return {
        "ok": True,
        "config": cfg,
        "status": st,
        "github": {
            "repo": GITHUB_REPO,
            "branch": GITHUB_BRANCH,
            "path": "modules/miner_sniffer/",
        },
    }


def apply_sniffer_cfg(req: dict) -> dict:
    """Update config; on enable → install from GitHub if needed + start; on disable → stop."""
    global _sniffer_mod
    if not isinstance(req, dict):
        raise ValueError("expected object")

    with _sniffer_cfg_lock:
        if "enabled" in req:
            _sniffer_cfg["enabled"] = bool(req["enabled"])
        if "iface" in req and str(req.get("iface") or "").strip():
            _sniffer_cfg["iface"] = str(req["iface"]).strip()
        if "filter" in req:
            _sniffer_cfg["filter"] = str(req.get("filter") or "").strip()
        if "pcap_dir" in req and str(req.get("pcap_dir") or "").strip():
            _sniffer_cfg["pcap_dir"] = str(req["pcap_dir"]).strip()
        if "snaplen" in req:
            try:
                _sniffer_cfg["snaplen"] = max(
                    0, min(65535, int(req["snaplen"]))
                )
            except (TypeError, ValueError):
                pass
        snap = dict(_sniffer_cfg)
    _save_sniffer_cfg()

    # Enable only if module is already installed (Install button is separate)
    if snap.get("enabled") and not _sniffer_module_present():
        with _sniffer_cfg_lock:
            _sniffer_cfg["enabled"] = False
        _save_sniffer_cfg()
        body = get_sniffer_cfg()
        body["ok"] = False
        body["error"] = "sniffer not installed — use Install first"
        return body

    if snap.get("enabled"):
        _import_miner_sniffer(force_reload=False)
    # else: deactivate only — keep files

    apply_res = _sniffer_sync_runtime(snap)
    body = get_sniffer_cfg()
    body["apply"] = apply_res
    if snap.get("enabled"):
        st = body.get("status") or {}
        if not st.get("running"):
            body["ok"] = False
            body["error"] = (
                st.get("error")
                or (apply_res or {}).get("error")
                or "sniffer failed to start"
            )
    elif isinstance(apply_res, dict) and apply_res.get("ok") is False:
        body["ok"] = False
        body["error"] = apply_res.get("error") or "sniffer stop failed"
    return body


def _sniffer_sync_runtime(cfg: dict | None = None) -> dict:
    """Push settings into miner_sniffer and start/stop."""
    global _sniffer_mod
    if cfg is None:
        with _sniffer_cfg_lock:
            cfg = dict(_sniffer_cfg)

    want_on = bool(cfg.get("enabled"))
    if not want_on:
        mod = _sniffer_mod or (
            _import_miner_sniffer() if _sniffer_module_present() else None
        )
        if mod is None:
            return {"ok": True, "stopped": True, "note": "module not loaded"}
        try:
            mod.configure(enabled=False)
            return mod.stop()
        except Exception as e:
            return {"ok": False, "error": str(e)}

    mod = _import_miner_sniffer()
    if mod is None:
        return {
            "ok": False,
            "error": "sniffer module not loaded"
            + (f": {_sniffer_import_error}" if _sniffer_import_error else ""),
        }
    try:
        mod.set_host_resolver(lambda: HOST_MINER)
        mod.configure(
            enabled=True,
            iface=str(cfg.get("iface") or "br0"),
            filter=str(cfg.get("filter") or ""),
            pcap_dir=str(cfg.get("pcap_dir") or "/tmp/poolheat-sniffer"),
            snaplen=int(cfg.get("snaplen") or 0),
            miner_host=str(HOST_MINER or ""),
        )
        res = mod.apply()
        if not isinstance(res, dict):
            res = {"ok": True, "result": res}
        return res
    except Exception as e:
        print(f"[sniffer] apply: {e}")
        return {"ok": False, "error": str(e)}


def _miner_config_path() -> Path:
    """Where to persist miner host/port/password."""
    cfg = _APP.get("cfg_path") or ""
    if cfg:
        return Path(cfg)
    # Entware default
    if Path("/opt/etc/poolheat").is_dir():
        return Path("/opt/etc/poolheat/config.json")
    return DATA / "config.json"


def get_project_name() -> str:
    """Runtime name; re-sync from config.json if file has a value."""
    global PROJECT_NAME
    with _miner_cfg_lock:
        n = str(PROJECT_NAME or "").strip()
        path = _miner_config_path()
        if path.is_file():
            try:
                raw = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(raw, dict) and raw.get("project_name") is not None:
                    fn = str(raw.get("project_name") or "").strip()
                    if fn:
                        PROJECT_NAME = fn
                        n = fn
            except Exception:
                pass
        return n or "poolheat_WM"


def get_miner_settings() -> dict:
    # ensure project_name is fresh from disk
    pname = get_project_name()
    with _miner_cfg_lock:
        return {
            "miner_host": HOST_MINER,
            "miner_port": int(PORT_MINER),
            "api_password": DEFAULT_API_PASSWORD,
            "poll_interval_sec": int(POLL_INTERVAL_SEC),
            "dry_run": bool(DRY_RUN),
            "project_name": pname,
            "host": f"{HOST_MINER}:{PORT_MINER}",
            "config_path": str(_miner_config_path()),
        }


