def _normalize_hashboard_style(raw, vendor_id: str | None = None) -> dict:
    """Canonical per-vendor hashboard naming (CH1 / CPB0 / SM0 / HB1)."""
    base = {}
    vid = str(vendor_id or "").strip().lower()
    if vid in _HASHBOARD_STYLE_DEFAULTS:
        base = dict(_HASHBOARD_STYLE_DEFAULTS[vid])
    elif vid:
        base = {"prefix": "SM", "index_base": 0, "api_prefix": "SM", "api_index_base": 0}
    else:
        base = {"prefix": "SM", "index_base": 0, "api_prefix": "SM", "api_index_base": 0}
    if isinstance(raw, dict):
        for k in (
            "prefix",
            "index_base",
            "api_prefix",
            "api_index_base",
            "display",
            "note",
        ):
            if raw.get(k) is not None and raw.get(k) != "":
                base[k] = raw[k]
    try:
        base["index_base"] = int(base.get("index_base") or 0)
    except (TypeError, ValueError):
        base["index_base"] = 0
    try:
        base["api_index_base"] = int(
            base.get("api_index_base")
            if base.get("api_index_base") is not None
            else base["index_base"]
        )
    except (TypeError, ValueError):
        base["api_index_base"] = base["index_base"]
    prefix = str(base.get("prefix") or "SM")
    base["prefix"] = prefix
    base["api_prefix"] = str(base.get("api_prefix") or prefix)
    tmpl = str(base.get("display") or "{prefix}{n}")
    base["display"] = tmpl
    return base


def vendor_hashboard_style(vendor: str | None) -> dict:
    v = resolve_miner_vendor(vendor)
    st = v.get("hashboard") if isinstance(v, dict) else None
    return _normalize_hashboard_style(st, v.get("id") if isinstance(v, dict) else vendor)


def _vendor_id_for_hashboard(raw: str | None) -> str:
    """Vendor catalog id from vendor slug or miner_type (M63 → whatsminer)."""
    s = str(raw or "").strip()
    if not s:
        return "whatsminer"
    v = resolve_miner_vendor(s)
    if not v.get("unknown"):
        return str(v.get("id") or "whatsminer")
    sl = s.lower()
    if "goldshell" in sl or "ckbox" in sl or "ckb" in sl:
        return "goldshell"
    if "ipollo" in sl:
        return "ipollo"
    if "antminer" in sl or sl.startswith("s1") or sl.startswith("l9"):
        return "antminer"
    if resolve_miner_model is not None:
        try:
            mp = resolve_miner_model(s)
            mfr = mp.get("manufacturer") if isinstance(mp, dict) else None
            mid = mfr.get("id") if isinstance(mfr, dict) else None
            if mid:
                return str(resolve_miner_vendor(mid).get("id") or mid)
        except Exception:
            pass
    return str(v.get("id") or "whatsminer")


def format_hashboard_id(
    index: int,
    vendor: str | None = None,
    *,
    raw_name: str | None = None,
    style: dict | None = None,
) -> str:
    """Human board id: SM0 / CH1 / CPB0 / HB1. Prefer ASIC Name when it matches."""
    name = str(raw_name or "").strip()
    if name and re.search(r"[A-Za-z]+\s*\d+", name):
        return re.sub(r"\s+", "", name)
    st = style or vendor_hashboard_style(_vendor_id_for_hashboard(vendor))
    try:
        i = int(index)
    except (TypeError, ValueError):
        i = 0
    n = int(st.get("index_base") or 0) + i
    tmpl = str(st.get("display") or "{prefix}{n}")
    try:
        return tmpl.format(prefix=str(st.get("prefix") or "SM"), n=n, index=i)
    except Exception:
        return f"{st.get('prefix') or 'SM'}{n}"


def parse_hashboard_index(name: str | None, style: dict | None = None) -> int | None:
    """CPB0 / CH1 / chain2 / SM3 / HB1 → 0-based slot index."""
    s = str(name or "").strip()
    if not s:
        return None
    m = re.search(r"(\d+)\s*$", s)
    if not m:
        return None
    n = int(m.group(1))
    st = style or {}
    # CH/HB are 1-based in the name; chain0 / SM0 / CPB0 are 0-based
    prefix = re.sub(r"\d+$", "", s).strip().upper()
    base = int(st.get("index_base") or 0)
    api_base = int(st.get("api_index_base") if st.get("api_index_base") is not None else base)
    if prefix in ("CH", "HB"):
        return max(0, n - (1 if base == 1 else base))
    if prefix.lower() in ("chain", "asc"):
        return max(0, n - api_base)
    return max(0, n - base)


def _load_miner_vendors_raw() -> dict:
    global _miner_vendors_cache
    if isinstance(_miner_vendors_cache, dict):
        return _miner_vendors_cache
    for p in MINER_VENDORS_FILE_CANDIDATES:
        try:
            if p.is_file():
                raw = json.loads(p.read_text(encoding="utf-8"))
                if isinstance(raw, dict) and isinstance(raw.get("vendors"), list):
                    _miner_vendors_cache = raw
                    return raw
        except Exception:
            continue
    _miner_vendors_cache = {"version": 1, "vendors": list(_BUILTIN_MINER_VENDORS)}
    return _miner_vendors_cache


def get_miner_vendors() -> dict:
    """
    Vendor catalog for UI / inventory.
    Each entry: id, alias[], name (Title Case), logo path, default_port, color.
    """
    raw = _load_miner_vendors_raw()
    items: list[dict] = []
    for v in raw.get("vendors") or []:
        if not isinstance(v, dict):
            continue
        vid = str(v.get("id") or "").strip().lower()
        if not vid:
            continue
        aliases = v.get("alias") if isinstance(v.get("alias"), list) else []
        aliases = [str(a).strip().lower() for a in aliases if str(a).strip()]
        if vid not in aliases:
            aliases = [vid] + aliases
        name = str(v.get("name") or vid).strip()
        if name:
            # ensure leading capital (Whatsminer / Antminer …)
            name = name[0].upper() + name[1:]
        logo = str(v.get("logo") or f"/icons/vendors/{vid}.png").strip()
        # root-absolute so SPA nested routes (/ru/miners/…) don't break logos
        if logo and not logo.startswith(("/", "http://", "https://", "data:")):
            logo = "/" + logo.lstrip("./")
        try:
            port = int(v.get("default_port") or 4028)
        except (TypeError, ValueError):
            port = 4028
        try:
            order = int(v.get("order") or 100)
        except (TypeError, ValueError):
            order = 100
        items.append(
            {
                "id": vid,
                "alias": aliases,
                "name": name,
                "manufacturer": str(v.get("manufacturer") or "").strip() or None,
                "logo": logo,
                "default_port": port,
                "color": str(v.get("color") or "").strip() or None,
                "order": order,
                "hashboard": _normalize_hashboard_style(v.get("hashboard"), vid),
            }
        )
    items.sort(key=lambda x: (x.get("order") or 100, x.get("name") or ""))
    return {
        "ok": True,
        "version": int(raw.get("version") or 1),
        "vendors": items,
    }


def resolve_miner_vendor(raw: str | None) -> dict:
    """
    Map free-form vendor string → catalog entry.
    Returns {id, name, logo, default_port, …}; unknown → id lowercased, name Title.
    """
    cat = get_miner_vendors()
    key = str(raw or "").strip().lower().replace(" ", "").replace("-", "")
    if not key:
        # default Whatsminer
        for v in cat.get("vendors") or []:
            if v.get("id") == "whatsminer":
                return dict(v)
        return {
            "id": "whatsminer",
            "name": "Whatsminer",
            "logo": "/icons/vendors/whatsminer.png",
            "default_port": 4028,
            "alias": ["whatsminer"],
        }
    for v in cat.get("vendors") or []:
        aliases = [str(a).replace(" ", "").replace("-", "") for a in (v.get("alias") or [])]
        vid = str(v.get("id") or "").replace(" ", "").replace("-", "")
        if key == vid or key in aliases:
            return dict(v)
        # partial: "bitmain" in alias already; "antminer s19" → antminer
        if any(key.startswith(a) or a.startswith(key) for a in aliases if len(a) >= 3):
            return dict(v)
    # unknown vendor — Title Case display name, keep id slug
    slug = re.sub(r"[^a-z0-9_]+", "", key) or "unknown"
    title = str(raw or slug).strip()
    if title:
        title = title[0].upper() + title[1:]
    return {
        "id": slug,
        "name": title or slug,
        "logo": "/icons/vendors/unknown.svg",
        "default_port": 4028,
        "alias": [slug],
        "unknown": True,
    }

_DEFAULT_MINER_POLLER_CFG: dict = {
    "version": 1,
    "discovery": {
        "enabled": False,
        "ranges": [],
        "interval_sec": 600,
        "probe_timeout_ms": 400,
        # Keenetic ~256MB RAM: 48 parallel sockets OOMs during /24 scan
        "concurrency": 16,
        "ports": [4028, 80, 4433, 6060],
        "passwords": ["admin"],
        "ignore_ips": [],
    },
    "poll": {
        "max_parallel": 4,
        "interval_sec": 0,
        "per_miner_timeout_sec": 8,
    },
}


def _normalize_miner_poller_cfg(raw: dict | None) -> dict:
    out = json.loads(json.dumps(_DEFAULT_MINER_POLLER_CFG))
    if not isinstance(raw, dict):
        return out
    d = raw.get("discovery") if isinstance(raw.get("discovery"), dict) else {}
    p = raw.get("poll") if isinstance(raw.get("poll"), dict) else {}
    out["discovery"]["enabled"] = bool(d.get("enabled", False))
    ranges = d.get("ranges")
    if isinstance(ranges, list):
        out["discovery"]["ranges"] = [
            str(x).strip() for x in ranges if str(x).strip()
        ]
    elif isinstance(ranges, str) and ranges.strip():
        out["discovery"]["ranges"] = [
            ln.strip()
            for ln in ranges.replace(",", "\n").splitlines()
            if ln.strip()
        ]
    try:
        out["discovery"]["interval_sec"] = max(
            60, min(86400, int(d.get("interval_sec", 600) or 600))
        )
    except (TypeError, ValueError):
        pass
    try:
        out["discovery"]["probe_timeout_ms"] = max(
            100, min(5000, int(d.get("probe_timeout_ms", 500) or 500))
        )
    except (TypeError, ValueError):
        pass
    try:
        out["discovery"]["concurrency"] = max(
            1, min(128, int(d.get("concurrency", 48) or 48))
        )
    except (TypeError, ValueError):
        pass
    ports = d.get("ports")
    if isinstance(ports, list) and ports:
        out["discovery"]["ports"] = [
            int(x) for x in ports if str(x).strip().isdigit() and 1 <= int(x) <= 65535
        ] or [4028, 80, 4433]
    pws = d.get("passwords")
    if isinstance(pws, list):
        out["discovery"]["passwords"] = [
            str(x) for x in pws if str(x).strip() != ""
        ] or ["admin"]
    ign = d.get("ignore_ips")
    if isinstance(ign, list):
        out["discovery"]["ignore_ips"] = [
            str(x).strip() for x in ign if str(x).strip()
        ]
    try:
        out["poll"]["max_parallel"] = max(
            1, min(32, int(p.get("max_parallel", 4) or 4))
        )
    except (TypeError, ValueError):
        pass
    try:
        out["poll"]["per_miner_timeout_sec"] = max(
            3, min(60, int(p.get("per_miner_timeout_sec", 8) or 8))
        )
    except (TypeError, ValueError):
        pass
    try:
        iv = int(p.get("interval_sec", 0) or 0)
        out["poll"]["interval_sec"] = max(0, min(300, iv))
    except (TypeError, ValueError):
        pass
    return out


def get_miner_poller_cfg() -> dict:
    raw = _load_json(MINER_POLLER_CFG_FILE, {})
    return _normalize_miner_poller_cfg(raw if isinstance(raw, dict) else {})


def save_miner_poller_cfg(raw: dict | None) -> dict:
    cfg = _normalize_miner_poller_cfg(raw if isinstance(raw, dict) else {})
    _save_json_atomic(MINER_POLLER_CFG_FILE, cfg)
    return cfg


def get_miners_discovered() -> dict:
    raw = _load_json(
        MINERS_DISCOVERED_FILE,
        {"version": 1, "miners": [], "updated_ts": None},
    )
    if not isinstance(raw, dict):
        raw = {"version": 1, "miners": []}
    miners = raw.get("miners") if isinstance(raw.get("miners"), list) else []
    # hide ignored by default unless caller wants all
    return {
        "ok": True,
        "updated_ts": raw.get("updated_ts"),
        "probed": raw.get("probed"),
        "found": raw.get("found"),
        "scan_ms": raw.get("scan_ms"),
        "miners": [m for m in miners if isinstance(m, dict)],
    }


def _parse_managed_id(raw) -> int | None:
    """Positive integer inventory id, or None if missing / legacy string."""
    if raw is None or raw is False:
        return None
    s = str(raw).strip()
    if not s or not s.isdigit():
        return None
    try:
        n = int(s)
    except (TypeError, ValueError):
        return None
    return n if n > 0 else None


def _next_managed_id(miners: list) -> int:
    """Auto-increment: max(existing numeric ids) + 1 (or 1 if empty)."""
    mx = 0
    for m in miners or []:
        if not isinstance(m, dict):
            continue
        n = _parse_managed_id(m.get("id"))
        if n is not None and n > mx:
            mx = n
    return mx + 1


def _random_miner_name() -> str:
    """Random display name (same entropy style as the old m_<hex> ids)."""
    return "n_" + uuid.uuid4().hex[:10]


def _assign_managed_ids(miners: list) -> list:
    """
    Ensure every miner has a unique positive integer id (auto-increment).
    Legacy string ids (m_…) are replaced; numeric ids are kept stable.
    """
    out: list = []
    used: set[int] = set()
    pending: list = []
    for m in miners or []:
        if not isinstance(m, dict):
            continue
        row = dict(m)
        n = _parse_managed_id(row.get("id"))
        if n is not None and n not in used:
            row["id"] = n
            used.add(n)
            out.append(row)
        else:
            pending.append(row)
    nxt = (max(used) if used else 0) + 1
    for row in pending:
        while nxt in used:
            nxt += 1
        row["id"] = nxt
        used.add(nxt)
        nxt += 1
        out.append(row)
    # stable order by id
    out.sort(key=lambda x: int(x.get("id") or 0))
    return out


def _normalize_managed_miner(raw: dict | None) -> dict:
    """Ensure inventory fields exist on a managed miner row."""
    m = dict(raw) if isinstance(raw, dict) else {}
    mid = _parse_managed_id(m.get("id"))  # None → assigned in _save_miners_managed
    vinfo = resolve_miner_vendor(m.get("vendor") or "whatsminer")
    vendor = str(vinfo.get("id") or "whatsminer")
    vendor_name = str(vinfo.get("name") or vendor)
    vendor_logo = str(vinfo.get("logo") or m.get("vendor_logo") or "")
    if vendor_logo and not vendor_logo.startswith(
        ("/", "http://", "https://", "data:")
    ):
        vendor_logo = "/" + vendor_logo.lstrip("./")
    host = str(m.get("host") or m.get("ip") or "").strip()
    try:
        port = int(m.get("port") or vinfo.get("default_port") or 4028)
    except (TypeError, ValueError):
        port = int(vinfo.get("default_port") or 4028)
    role = str(m.get("role") or "standby").strip().lower()
    if role not in ("active", "standby"):
        role = "standby"
    miner_type = str(m.get("miner_type") or m.get("type") or "").strip()
    model_code = str(
        m.get("model_code") or m.get("modelCode") or miner_type or ""
    ).strip()
    model = str(m.get("model") or "").strip()
    if not model and model_code:
        model = model_code
    alias = str(m.get("alias") or "").strip()
    name = str(m.get("name") or "").strip()
    # display fallbacks (id is numeric — not used as a label)
    if not name:
        name = alias or host or (f"miner-{mid}" if mid else _random_miner_name())
    if not alias:
        alias = name or host or (f"miner-{mid}" if mid else _random_miner_name())
    serial = str(
        m.get("serial")
        or m.get("minersn")
        or m.get("customer_sn")
        or m.get("sn")
        or ""
    ).strip()
    cooling = _normalize_miner_cooling(
        m.get("cooling") or m.get("cooling_type") or m.get("cool")
    )
    algo = str(m.get("algo") or m.get("algorithm") or "").strip()
    algo_disp = str(m.get("algo_display") or "").strip()
    hr_unit = str(m.get("hashrate_unit") or "").strip()
    eff_unit = str(m.get("efficiency_unit") or "").strip()
    if resolve_miner_algo is not None:
        try:
            ainfo = resolve_miner_algo(
                vendor=vendor,
                miner_type=miner_type or model_code,
                model=model,
                model_code=model_code,
                explicit=algo,
            )
            if ainfo.get("id"):
                algo = str(ainfo["id"])
                algo_disp = str(ainfo.get("name") or algo)
                hr_unit = hr_unit or str(ainfo.get("hashrate_unit") or "")
                eff_unit = eff_unit or str(ainfo.get("efficiency_unit") or "")
        except Exception:
            pass
    if algo and not algo_disp:
        if miner_algo_display is not None:
            try:
                algo_disp = miner_algo_display(algo) or algo
            except Exception:
                algo_disp = algo
        else:
            algo_disp = algo
    pool_id = str(m.get("pool_id") or m.get("heat_pool_id") or "").strip()
    # reserved for future cloud / multi-site identity (not shown in UI yet)
    global_id = str(m.get("global_id") or "").strip()
    # Inventory hashrate targets (TH/s): factory = submodel nameplate;
    # configured = operating target (e.g. low-power mode 80 TH).
    factory_hr = _parse_optional_th(
        m.get("factory_hashrate_th")
        if m.get("factory_hashrate_th") is not None
        else m.get("factory_th")
        if m.get("factory_th") is not None
        else m.get("rated_hashrate_th")
    )
    configured_hr = _parse_optional_th(
        m.get("configured_hashrate_th")
        if m.get("configured_hashrate_th") is not None
        else m.get("target_hashrate_th")
        if m.get("target_hashrate_th") is not None
        else m.get("configured_th")
    )
    return {
        "id": mid if mid is not None else 0,  # 0 → allocate on save
        "global_id": global_id[:128],
        "vendor": vendor,
        "vendor_name": vendor_name,
        "vendor_logo": vendor_logo,
        "host": host,
        "port": port,
        "password": m.get("password") if m.get("password") is not None else "",
        "enabled": bool(m.get("enabled", True)),
        "role": role,
        "alias": alias[:64],
        "name": name[:64],
        "cell": str(m.get("cell") or m.get("location") or "")[:64],
        "model": model[:64],
        "model_code": model_code[:64],
        "serial": serial[:96],
        "inventory": str(
            m.get("inventory") or m.get("inventory_number") or m.get("inv") or ""
        )[:64],
        "cooling": cooling,
        "cooling_name": _miner_cooling_name(cooling),
        "algo": algo[:32],
        "algo_display": (algo_disp or algo)[:32],
        "hashrate_unit": hr_unit[:16],
        "efficiency_unit": eff_unit[:16],
        "factory_hashrate_th": factory_hr,
        "configured_hashrate_th": configured_hr,
        "pool_id": pool_id[:48] if pool_id else "",
        "miner_type": miner_type[:64] or model_code[:64],
        "mac": str(m.get("mac") or "").strip()[:32] or None,
        "fw_ver": str(m.get("fw_ver") or m.get("fw") or "").strip()[:64] or None,
        "source": str(m.get("source") or "").strip() or None,
        "imported_at": m.get("imported_at"),
        "last_ok_ts": m.get("last_ok_ts"),
        "last_error": m.get("last_error"),
    }


def _parse_optional_th(raw) -> float | None:
    """Parse optional hashrate in TH/s; empty / invalid → None."""
    if raw is None or raw == "":
        return None
    try:
        v = float(raw)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(v) or v < 0:
        return None
    if v == 0:
        return 0.0
    # keep modest precision for inventory fields
    if v >= 100:
        return round(v, 2)
    if v >= 1:
        return round(v, 3)
    return round(v, 6)


def _normalize_miner_cooling(raw) -> str:
    s = str(raw or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "air": "air",
        "aircool": "air",
        "air_cooled": "air",
        "fan": "air",
        "hydro": "hydro",
        "liquid": "hydro",
        "water": "hydro",
        "hyd": "hydro",
        "immersion": "immersion",
        "immerse": "immersion",
        "oil": "immersion",
    }
    s = aliases.get(s, s)
    if s in ("air", "hydro", "immersion"):
        return s
    return "air"


def _miner_cooling_name(cid: str, *, lang: str = "en") -> str:
    cid = _normalize_miner_cooling(cid)
    for t in MINER_COOLING_TYPES:
        if t["id"] == cid:
            if str(lang).startswith("ru"):
                return str(t.get("name_ru") or t.get("name") or cid)
            return str(t.get("name") or cid)
    return cid


def list_miner_cooling_types() -> list[dict]:
    return [dict(t) for t in MINER_COOLING_TYPES]


_miners_db_lock = threading.Lock()
_miners_db_ready = False


def _miners_db_connect() -> sqlite3.Connection:
    conn = sqlite3.connect(str(MINERS_DB_FILE), check_same_thread=False, timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA foreign_keys=ON")
    return conn


def _ensure_miners_db() -> None:
    """Create miners.db schema (managed inventory)."""
    global _miners_db_ready
    if _miners_db_ready and MINERS_DB_FILE.is_file():
        return
    do_migrate = False
    with _miners_db_lock:
        if _miners_db_ready and MINERS_DB_FILE.is_file():
            return
        MINERS_DB_FILE.parent.mkdir(parents=True, exist_ok=True)
        conn = _miners_db_connect()
        try:
            conn.executescript(
                """
                CREATE TABLE IF NOT EXISTS managed_miners (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    global_id TEXT NOT NULL DEFAULT '',
                    vendor TEXT NOT NULL DEFAULT 'whatsminer',
                    host TEXT NOT NULL DEFAULT '',
                    port INTEGER NOT NULL DEFAULT 4028,
                    password TEXT NOT NULL DEFAULT '',
                    enabled INTEGER NOT NULL DEFAULT 1,
                    role TEXT NOT NULL DEFAULT 'standby',
                    alias TEXT NOT NULL DEFAULT '',
                    name TEXT NOT NULL DEFAULT '',
                    cell TEXT NOT NULL DEFAULT '',
                    model TEXT NOT NULL DEFAULT '',
                    model_code TEXT NOT NULL DEFAULT '',
                    serial TEXT NOT NULL DEFAULT '',
                    inventory TEXT NOT NULL DEFAULT '',
                    cooling TEXT NOT NULL DEFAULT 'air',
                    algo TEXT NOT NULL DEFAULT '',
                    pool_id TEXT NOT NULL DEFAULT '',
                    miner_type TEXT NOT NULL DEFAULT '',
                    mac TEXT,
                    fw_ver TEXT,
                    source TEXT,
                    imported_at TEXT,
                    last_ok_ts TEXT,
                    last_error TEXT,
                    factory_hashrate_th REAL,
                    configured_hashrate_th REAL
                );
                CREATE INDEX IF NOT EXISTS idx_managed_host ON managed_miners(host);
                CREATE INDEX IF NOT EXISTS idx_managed_role ON managed_miners(role);
                CREATE INDEX IF NOT EXISTS idx_managed_mac ON managed_miners(mac);
                """
            )
            conn.commit()
            # existing DBs: soft-migrate missing columns
            cols = {
                str(r[1])
                for r in conn.execute("PRAGMA table_info(managed_miners)").fetchall()
            }
            if "algo" not in cols:
                conn.execute(
                    "ALTER TABLE managed_miners ADD COLUMN algo TEXT NOT NULL DEFAULT ''"
                )
                conn.commit()
                cols.add("algo")
            # Factory (submodel nameplate) + configured (operating target) TH/s
            for col in ("factory_hashrate_th", "configured_hashrate_th"):
                if col not in cols:
                    conn.execute(
                        f"ALTER TABLE managed_miners ADD COLUMN {col} REAL"
                    )
                    conn.commit()
                    cols.add(col)
            _miners_db_ready = True
            do_migrate = True
        finally:
            conn.close()
    # migrate outside lock (save takes the same lock)
    if do_migrate:
        try:
            _migrate_managed_json_to_sqlite()
        except Exception as e:
            print(f"[miners.db] migrate from JSON: {e}", flush=True)


def _managed_row_from_db(row: sqlite3.Row | dict) -> dict:
    """sqlite row → normalized managed miner dict (with vendor_name/logo)."""
    if row is None:
        return _normalize_managed_miner({})
    d = dict(row) if not isinstance(row, dict) else dict(row)
    # sqlite stores enabled as 0/1
    if "enabled" in d:
        d["enabled"] = bool(d.get("enabled"))
    return _normalize_managed_miner(d)


def _migrate_managed_json_to_sqlite() -> None:
    """Import miners_managed.json into miners.db if DB empty and JSON present."""
    _ensure_miners_db()
    with _miners_db_lock:
        conn = _miners_db_connect()
        try:
            n = conn.execute("SELECT COUNT(*) AS c FROM managed_miners").fetchone()
            if n and int(n["c"] or 0) > 0:
                return
        finally:
            conn.close()
    if not MINERS_MANAGED_FILE.is_file():
        return
    raw = _load_json(MINERS_MANAGED_FILE, {"version": 1, "miners": []})
    if not isinstance(raw, dict):
        return
    miners = raw.get("miners") if isinstance(raw.get("miners"), list) else []
    if not miners:
        return
    print(
        f"[miners.db] migrating {len(miners)} rows from {MINERS_MANAGED_FILE.name}",
        flush=True,
    )
    _save_miners_managed(miners, _from_migrate=True)
    # keep JSON as backup
    try:
        bak = MINERS_MANAGED_FILE.with_suffix(".json.bak")
        if not bak.is_file():
            MINERS_MANAGED_FILE.replace(bak)
            print(f"[miners.db] JSON archived → {bak.name}", flush=True)
    except Exception as e:
        print(f"[miners.db] archive JSON: {e}", flush=True)
    try:
        (DATA / "miners_inventory_initialized").write_text("1\n", encoding="utf-8")
    except Exception:
        pass


def get_miners_managed() -> dict:
    """Managed inventory from miners.db (auto-migrates legacy JSON once)."""
    _ensure_miners_db()
    with _miners_db_lock:
        conn = _miners_db_connect()
        try:
            rows = conn.execute(
                "SELECT * FROM managed_miners ORDER BY id ASC"
            ).fetchall()
        finally:
            conn.close()
    clean = [_managed_row_from_db(r) for r in rows]
    # fix non-positive / legacy ids if any slipped in
    if any(not isinstance(m.get("id"), int) or int(m.get("id") or 0) <= 0 for m in clean):
        return _save_miners_managed(clean)
    return {
        "ok": True,
        "miners": clean,
        "next_id": _next_managed_id(clean),
        "db": str(MINERS_DB_FILE),
    }


def _live_host_ip(live: dict | None) -> str:
    if not isinstance(live, dict):
        return ""
    h = str(live.get("host") or "").strip()
    if not h:
        return ""
    # host may be "192.168.1.10:4028"
    return h.split(":")[0].strip()


# Rolling per-host hashrate samples for fleet lowhash (30 min window).
_FLEET_HR_HIST_LOCK = threading.Lock()
_FLEET_HR_HIST: dict[str, list[tuple[float, float]]] = {}
_FLEET_HR_WINDOW_SEC = 30 * 60
# Need a few minutes of samples before lowhash is allowed to fire.
_FLEET_HR_MIN_SPAN_SEC = 5 * 60
_FLEET_HR_MIN_SAMPLES = 3


def _record_fleet_hr_sample(host: str, th: float | None) -> float | None:
    """
    Record live TH/s for host and return average over the last 30 minutes.
    Returns None when there is not enough history yet (span/samples).
    """
    h = str(host or "").strip()
    if not h:
        return None
    now = time.time()
    with _FLEET_HR_HIST_LOCK:
        hist = _FLEET_HR_HIST.setdefault(h, [])
        if th is not None:
            try:
                v = float(th)
            except (TypeError, ValueError):
                v = None
            if v is not None and math.isfinite(v) and v >= 0:
                hist.append((now, v))
        cutoff = now - _FLEET_HR_WINDOW_SEC
        # drop old samples in place
        i = 0
        while i < len(hist) and hist[i][0] < cutoff:
            i += 1
        if i:
            del hist[:i]
        if len(hist) < _FLEET_HR_MIN_SAMPLES:
            return None
        span = hist[-1][0] - hist[0][0]
        if span < _FLEET_HR_MIN_SPAN_SEC:
            return None
        avg = sum(v for _, v in hist) / len(hist)
        return round(avg, 6) if avg < 1 else round(avg, 3)


def _fleet_live_slice(live: dict | None, *, host: str | None = None) -> dict | None:
    """Compact live fields for fleet table rows."""
    if not isinstance(live, dict):
        return None
    # Ensure model profile (display name + estimated power) even if snapshot
    # was written before profiles existed / match keys were extended.
    try:
        if apply_model_profile_to_live is not None:
            live = apply_model_profile_to_live(
                dict(live), vendor=live.get("vendor") or live.get("api_vendor")
            )
    except Exception:
        pass
    power = live.get("power")
    th = live.get("hashrate_th")
    try:
        p = float(power) if power is not None else None
    except (TypeError, ValueError):
        p = None
    try:
        t = float(th) if th is not None else None
    except (TypeError, ValueError):
        t = None
    # Prefer explicit host arg, else live.host (may be host:port)
    host_key = str(host or "").strip()
    if not host_key:
        raw_h = str(live.get("host") or "").strip()
        if raw_h:
            host_key = raw_h.split(":")[0].strip()
    avg_30m = None
    if host_key and live.get("ok", True) and not live.get("error"):
        avg_30m = _record_fleet_hr_sample(host_key, t)
    elif host_key and t is not None:
        # still record offline samples as 0? no — only online polls
        pass
    eff = live.get("efficiency_jth")
    if eff is None and p is not None and t is not None and t > 0:
        eff = round(p / t, 2)
    if not live.get("efficiency_value") and p is not None and t is not None and t > 0:
        # last-resort J/T if profile apply didn't fill algo units
        live.setdefault("efficiency_value", eff)
        live.setdefault("efficiency_unit", "J/T")
    # temps: prefer liquid, else chip_avg / env
    temp = live.get("liquid")
    if temp is None:
        temp = live.get("chip_avg")
    if temp is None:
        temp = live.get("env")
    fans_raw = live.get("fans") or live.get("fan") or live.get("fan_speed") or live.get(
        "fan_speeds"
    )
    fan_s = None
    fans_list: list = []
    if isinstance(fans_raw, (list, tuple)) and fans_raw:
        for x in fans_raw:
            try:
                fans_list.append(int(float(x)))
            except (TypeError, ValueError):
                continue
        if fans_list:
            fan_s = fans_list[0]
    elif fans_raw is not None:
        try:
            fan_s = int(float(fans_raw))
            fans_list = [fan_s]
        except (TypeError, ValueError):
            fan_s = None
    # PSU fan as fallback when chassis fans missing
    psu_fan = live.get("psu_fan")
    try:
        psu_fan_i = int(float(psu_fan)) if psu_fan is not None else None
    except (TypeError, ValueError):
        psu_fan_i = None
    if not fans_list and psu_fan_i is not None:
        fans_list = [psu_fan_i]
        fan_s = psu_fan_i
    # Per-board hashrate (TH/s). live["boards"] is PCB temps — never treat as TH.
    board_ths: list = []
    raw_th = live.get("boards_th")
    if isinstance(raw_th, (list, tuple)) and raw_th:
        for x in raw_th:
            try:
                if x is None or x == "":
                    continue
                board_ths.append(float(x))
            except (TypeError, ValueError):
                continue
    if not board_ths and isinstance(live.get("boards_detail"), list):
        for b in live["boards_detail"]:
            if not isinstance(b, dict) or b.get("hashrate_th") is None:
                continue
            try:
                board_ths.append(float(b["hashrate_th"]))
            except (TypeError, ValueError):
                continue
    work = (
        live.get("work")
        or live.get("mining_work")
        or live.get("work_measured")
        or live.get("mode")
    )
    if work is None and live.get("mineroff"):
        work = "sleep"
    pools = live.get("pools") if isinstance(live.get("pools"), list) else None
    pool_ok = None
    pool_url = None
    if pools:
        # first active-looking pool
        for p0 in pools:
            if not isinstance(p0, dict):
                continue
            st = str(p0.get("status") or p0.get("stratum") or "").lower()
            if "dead" in st or "disc" in st:
                continue
            pool_url = str(p0.get("url") or p0.get("pool") or "")[:80] or None
            pool_ok = True
            break
        if pool_ok is None:
            pool_ok = False
            p0 = pools[0] if isinstance(pools[0], dict) else {}
            pool_url = str(p0.get("url") or p0.get("pool") or "")[:80] or None
    # Per-board PCB / chip temps (Antminer stats, Goldshell tstemp-*, …)
    boards_pcb = live.get("boards")
    if not isinstance(boards_pcb, list):
        boards_pcb = None
    bca = live.get("board_chip_avg")
    if not isinstance(bca, list):
        bca = None
    bcmx = live.get("board_chip_max")
    if not isinstance(bcmx, list):
        bcmx = None
    bcmn = live.get("board_chip_min")
    if not isinstance(bcmn, list):
        bcmn = None
    bdet = live.get("boards_detail")
    if not isinstance(bdet, list):
        bdet = None

    return {
        "ok": bool(live.get("ok", True)),
        "power": p,
        "hashrate_th": t,
        "efficiency_jth": eff,
        "temp": temp,
        "liquid": live.get("liquid"),
        "chip_avg": live.get("chip_avg"),
        "chip_max": live.get("chip_max"),
        "chip_min": live.get("chip_min"),
        "env": live.get("env"),
        "boards": boards_pcb[:8] if boards_pcb else None,
        "board_chip_avg": bca[:8] if bca else None,
        "board_chip_max": bcmx[:8] if bcmx else None,
        "board_chip_min": bcmn[:8] if bcmn else None,
        "boards_detail": bdet[:8] if bdet else None,
        "board_count": live.get("board_count"),
        "fan": fan_s,
        "fans": fans_list[:8],
        "psu_fan": psu_fan_i,
        "boards_th": board_ths[:8],
        "work": work,
        "elapsed": live.get("elapsed"),
        "rejected": live.get("rejected") or live.get("reject_rate") or live.get("hw_errors"),
        "freq_avg": live.get("freq_avg"),
        "pool_ok": pool_ok,
        "pool_url": pool_url,
        "miner_type": live.get("miner_type"),
        "vendor": live.get("vendor") or live.get("api_vendor"),
        "hashrate_hs": live.get("hashrate_hs"),
        "hashrate_unit": live.get("hashrate_unit"),
        "model_display": live.get("model_display"),
        "model_display_full": live.get("model_display_full"),
        "algo": live.get("algo"),
        "algo_display": live.get("algo_display"),
        "coin": live.get("coin"),
        "asic_cross": live.get("asic_cross"),
        "hashboard_voltage_mv": live.get("hashboard_voltage_mv"),
        "psu_feedback_v": live.get("psu_feedback_v"),
        "psu_status": live.get("psu_status"),
        "antminer_6060": live.get("antminer_6060"),
        "rate_th": live.get("rate_th"),
        "ideal_rate_th": live.get("ideal_rate_th"),
        "max_rate_th": live.get("max_rate_th"),
        "miner_status_6060": live.get("miner_status_6060"),
        "board_type": live.get("board_type"),
        "nonce_total": live.get("nonce_total"),
        "board_labels": live.get("board_labels"),
        "boards_detail": live.get("boards_detail"),
        "hashboard_style": live.get("hashboard_style"),
        "board_temps": [
            (round(float(x), 1) if isinstance(x, (int, float)) else None)
            for x in (live.get("boards") or [])[:8]
            if True
        ],
        "power_source": live.get("power_source"),
        "power_estimated": live.get("power_estimated"),
        "efficiency_value": live.get("efficiency_value"),
        "efficiency_unit": live.get("efficiency_unit"),
        "hashrate_th_avg_30m": avg_30m,
        "error": live.get("error"),
        "ts": live.get("ts"),
    }


def _load_fleet_live_map(*, max_age_sec: float = 120.0) -> dict[str, dict]:
    """host → live dict from fleet_live.json (multi-miner poller)."""
    out: dict[str, dict] = {}
    try:
        if not FLEET_LIVE_FILE.is_file():
            return out
        raw = json.loads(FLEET_LIVE_FILE.read_text(encoding="utf-8"))
        if not isinstance(raw, dict):
            return out
        miners = raw.get("miners") if isinstance(raw.get("miners"), dict) else raw
        if not isinstance(miners, dict):
            return out
        now = time.time()
        for host, entry in miners.items():
            if not isinstance(entry, dict):
                continue
            ts = float(entry.get("ts") or raw.get("ts") or 0)
            if ts > 0 and (now - ts) > float(max_age_sec):
                continue
            live = entry.get("live") if isinstance(entry.get("live"), dict) else entry
            # Keep ok:false stamps so UI can show offline (not "unknown")
            if isinstance(live, dict):
                out[str(host).strip()] = live
    except Exception:
        pass
    return out


def _publish_fleet_live_map(by_host: dict[str, dict]) -> None:
    """
    Write fleet_live.json. Merge with previous hosts so a partial poll
    (timeout / crash mid-cycle) does not wipe other miners' live rows.
    """
    try:
        now = time.time()
        merged: dict[str, dict] = {}
        # keep previous non-stale entries as base
        try:
            if FLEET_LIVE_FILE.is_file():
                prev = json.loads(FLEET_LIVE_FILE.read_text(encoding="utf-8"))
                old = prev.get("miners") if isinstance(prev, dict) else None
                if isinstance(old, dict):
                    for h, entry in old.items():
                        if not isinstance(entry, dict):
                            continue
                        ts = float(entry.get("ts") or prev.get("ts") or 0)
                        if ts > 0 and (now - ts) > 300.0:
                            continue
                        live = (
                            entry.get("live")
                            if isinstance(entry.get("live"), dict)
                            else entry
                        )
                        if isinstance(live, dict):
                            merged[str(h).strip()] = {
                                "ts": ts or now,
                                "live": live,
                                "host": str(h).strip(),
                            }
        except Exception:
            pass
        for h, live in (by_host or {}).items():
            if not isinstance(live, dict):
                continue
            hh = str(h).strip()
            if not hh:
                continue
            merged[hh] = {"ts": now, "live": live, "host": hh}
        payload = {"ts": now, "miners": merged}
        FLEET_LIVE_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = FLEET_LIVE_FILE.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
        tmp.replace(FLEET_LIVE_FILE)
    except Exception as e:
        print(f"[fleet-live] write: {e}", flush=True)


def _poll_one_managed_host(m: dict, *, timeout: float = 15.0) -> tuple[str, dict]:
    """
    Poll a single managed miner for fleet_live. Always returns (host, live)
    — never raises. Hard timeout so one dead/slow host cannot block the fleet.
    """
    host = str(m.get("host") or "").strip()
    if not host:
        return "", {}
    try:
        port = int(m.get("port") or 4028)
    except (TypeError, ValueError):
        port = 4028
    vendor_hint = str(m.get("vendor") or m.get("api_vendor") or "").lower()
    if vendor_hint in (
        "ipollo",
        "antminer",
        "bitmain",
        "goldshell",
        "avalon",
        "cgminer",
    ):
        with _ASIC_PROTO_LOCK:
            _ASIC_PROTO_CACHE[host] = "cgminer"
    elif vendor_hint in ("whatsminer", "microbt"):
        with _ASIC_PROTO_LOCK:
            _ASIC_PROTO_CACHE[host] = "whatsminer"

    def _do_fetch() -> dict:
        with _asic_target_override(host, port):
            live = _fetch_live_direct()
        if isinstance(live, dict):
            live.setdefault("host", f"{host}:{port}")
            return live
        raise RuntimeError("empty live")

    # Isolate hang: ThreadPool result timeout (remote VPN latency OK up to timeout)
    try:
        with ThreadPoolExecutor(max_workers=1) as ex:
            fut = ex.submit(_do_fetch)
            live = fut.result(timeout=max(5.0, float(timeout)))
        if isinstance(live, dict):
            return host, live
    except FuturesTimeout:
        err = f"poll timeout ({timeout:.0f}s)"
        print(f"[fleet-live] {host}:{port}: {err}", flush=True)
        return host, {
            "ok": False,
            "host": f"{host}:{port}",
            "error": err,
            "vendor": m.get("vendor"),
            "ts": datetime.now().isoformat(timespec="seconds"),
        }
    except Exception as e:
        # Goldshell cloud-box: HTTP /mcb/* when :4028 refused
        live_http = None
        try:
            live_http = _fetch_live_goldshell_http(host, port)
        except Exception:
            live_http = None
        if isinstance(live_http, dict) and live_http.get("ok"):
            print(
                f"[fleet-live] {host}: tcp failed ({e}); using goldshell HTTP",
                flush=True,
            )
            return host, live_http
        err = str(e)[:200]
        print(f"[fleet-live] {host}:{port}: {err}", flush=True)
        return host, {
            "ok": False,
            "host": f"{host}:{port}",
            "error": err,
            "vendor": m.get("vendor"),
            "ts": datetime.now().isoformat(timespec="seconds"),
        }
    return host, {
        "ok": False,
        "host": f"{host}:{port}",
        "error": "empty live",
        "vendor": m.get("vendor"),
        "ts": datetime.now().isoformat(timespec="seconds"),
    }


def _poll_managed_fleet_live() -> None:
    """
    Poll every enabled managed miner (Whatsminer / iPollo / Goldshell / …)
    and write fleet_live.json. Active host also refreshes via normal path.

    Parallel + per-host timeout so one unreachable ASIC (or high-latency
    remote like 192.168.1.10) cannot starve the rest of the fleet.

    Called from:
      • Python --miner-poller live loop
      • main serve fleet_live_loop (when Go poller owns :4028 — otherwise
        fleet_live goes stale and the UI marks every row offline)
    """
    try:
        managed = get_miners_managed()
    except Exception:
        return
    miners = [
        m
        for m in (managed.get("miners") or [])
        if isinstance(m, dict) and m.get("enabled", True)
    ]
    if not miners:
        return

    # poll config (optional)
    try:
        pcfg = get_miner_poller_cfg().get("poll") or {}
    except Exception:
        pcfg = {}
    try:
        max_par = int(pcfg.get("max_parallel") or 4)
    except (TypeError, ValueError):
        max_par = 4
    max_par = max(1, min(12, max_par))
    try:
        per_to = float(pcfg.get("per_miner_timeout_sec") or 12)
    except (TypeError, ValueError):
        per_to = 12.0
    # high-latency remote sites: at least 12s, cap 30s
    per_to = max(8.0, min(30.0, per_to))

    by_host: dict[str, dict] = {}
    workers = min(max_par, len(miners))
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futs = {
            pool.submit(_poll_one_managed_host, m, timeout=per_to): m
            for m in miners
        }
        try:
            for fut in as_completed(
                futs,
                timeout=per_to
                * max(2, (len(miners) + workers - 1) // workers),
            ):
                m = futs[fut]
                host = str((m or {}).get("host") or "").strip()
                try:
                    h, live = fut.result(timeout=0.1)
                    if h and isinstance(live, dict):
                        by_host[h] = live
                except FuturesTimeout:
                    print(f"[fleet-live] {host}: result timeout", flush=True)
                    if host:
                        by_host[host] = {
                            "ok": False,
                            "host": host,
                            "error": f"poll timeout ({per_to:.0f}s)",
                            "vendor": (m or {}).get("vendor"),
                            "ts": datetime.now().isoformat(timespec="seconds"),
                        }
                except Exception as e:
                    print(f"[fleet-live] {host}: {e}", flush=True)
                    if host:
                        by_host[host] = {
                            "ok": False,
                            "host": host,
                            "error": str(e)[:200],
                            "vendor": (m or {}).get("vendor"),
                            "ts": datetime.now().isoformat(timespec="seconds"),
                        }
        except FuturesTimeout:
            # overall barrier timed out — collect finished, stamp unfinished
            for fut, m in futs.items():
                host = str((m or {}).get("host") or "").strip()
                if not host or host in by_host:
                    continue
                if fut.done():
                    try:
                        h, live = fut.result(timeout=0)
                        if h and isinstance(live, dict):
                            by_host[h] = live
                            continue
                    except Exception:
                        pass
                by_host[host] = {
                    "ok": False,
                    "host": host,
                    "error": f"poll timeout ({per_to:.0f}s)",
                    "vendor": (m or {}).get("vendor"),
                    "ts": datetime.now().isoformat(timespec="seconds"),
                }
                print(f"[fleet-live] {host}: overall timeout", flush=True)

    if by_host:
        _publish_fleet_live_map(by_host)
        # Merge per-miner work for device binding (devices-poller reads by_miner)
        try:
            by_miner: dict = {}
            host_to_id: dict[str, str] = {}
            for m in miners:
                mid = str(m.get("id") or "").strip()
                host = str(m.get("host") or "").strip()
                if mid and host:
                    host_to_id[host] = mid
            now = time.time()
            for host, live in by_host.items():
                mid = host_to_id.get(host)
                if not mid or not isinstance(live, dict):
                    continue
                if live.get("ok") is False and not live.get("hashrate_th"):
                    continue
                try:
                    w = _live_work(live)
                except Exception:
                    continue
                ww = _norm_mining_work_token(w)
                if not ww:
                    continue
                by_miner[mid] = {
                    "work": ww,
                    "ts": now,
                    "host": host,
                }
            if by_miner:
                write_mining_work_snapshot(
                    None,
                    source="fleet-live",
                    by_miner=by_miner,
                    merge=True,
                )
        except Exception as e:
            print(f"[fleet-live] mining_work by_miner: {e}", flush=True)


def get_miners_fleet() -> dict:
    """
    Managed inventory + live overlay.
    Prefers multi-host fleet_live.json; falls back to single active live_cache.
    """
    _seed_managed_from_active()
    managed = get_miners_managed()
    miners_in = list(managed.get("miners") or [])
    fleet_map = _load_fleet_live_map(max_age_sec=120.0)
    live = hydrate_live_from_disk(max_age_sec=120.0)
    if not isinstance(live, dict):
        try:
            with _cache_lock:
                if isinstance(_cache, dict):
                    live = dict(_cache)
        except Exception:
            live = None
    live_ip = _live_host_ip(live)
    # One slice for active live_cache (records 30m HR under live_ip when known)
    live_slice = (
        _fleet_live_slice(live, host=live_ip) if isinstance(live, dict) else None
    )
    rows: list[dict] = []
    online_n = 0
    sum_th = 0.0
    sum_w = 0.0
    for m in miners_in:
        if not isinstance(m, dict):
            continue
        row = dict(m)
        host = str(m.get("host") or "").strip()
        role = str(m.get("role") or "standby")
        # Prefer per-host fleet live, then active live_cache match
        host_live = fleet_map.get(host) if host else None
        if isinstance(host_live, dict):
            sl = _fleet_live_slice(host_live, host=host)
            if sl and host_live.get("ok", True) and not host_live.get("error"):
                row["online"] = True
                row["live"] = sl
                online_n += 1
                if sl.get("hashrate_th") is not None:
                    try:
                        sum_th += float(sl["hashrate_th"])
                    except (TypeError, ValueError):
                        pass
                if sl.get("power") is not None:
                    try:
                        sum_w += float(sl["power"])
                    except (TypeError, ValueError):
                        pass
                # Trade name from model profile wins for UI (CK-BOX not CKBox)
                disp = (
                    (sl or {}).get("model_display")
                    or host_live.get("model_display")
                    or (sl or {}).get("model_display_full")
                    or host_live.get("model_display_full")
                )
                if disp:
                    row["model"] = disp
                    row["model_display"] = disp
                    row["model_display_full"] = (
                        (sl or {}).get("model_display_full")
                        or host_live.get("model_display_full")
                        or disp
                    )
                if not row.get("model_code") and (sl or {}).get("miner_type"):
                    row["model_code"] = (sl or {}).get("miner_type")
                if not row.get("model") and (
                    host_live.get("model_name")
                    or (sl or {}).get("miner_type")
                ):
                    row["model"] = host_live.get("model_name") or (sl or {}).get(
                        "miner_type"
                    )
                if not row.get("vendor") and host_live.get("vendor"):
                    row["vendor"] = host_live.get("vendor")
                live_algo = (
                    (sl or {}).get("algo")
                    or host_live.get("algo")
                    or (sl or {}).get("algo_display")
                )
                if live_algo and not row.get("algo"):
                    row["algo"] = (sl or {}).get("algo") or host_live.get("algo") or ""
                    row["algo_display"] = (
                        (sl or {}).get("algo_display")
                        or host_live.get("algo_display")
                        or live_algo
                    )
                elif (sl or {}).get("algo_display") and not row.get("algo_display"):
                    row["algo_display"] = sl.get("algo_display")
                if host_live.get("fw_ver") and not row.get("fw_ver"):
                    row["fw_ver"] = host_live.get("fw_ver")
                if host_live.get("serial") and not row.get("serial"):
                    row["serial"] = host_live.get("serial")
                if host_live.get("mac") and not row.get("mac"):
                    row["mac"] = host_live.get("mac")
            else:
                row["online"] = False
                row["live"] = sl
                row["last_error"] = (
                    (host_live or {}).get("error") or (sl or {}).get("error")
                )
            rows.append(row)
            continue
        match = bool(live_ip and host and host == live_ip)
        if match and live_slice and live_slice.get("ok"):
            row["online"] = True
            row["live"] = live_slice
            online_n += 1
            if live_slice.get("hashrate_th") is not None:
                sum_th += float(live_slice["hashrate_th"])
            if live_slice.get("power") is not None:
                sum_w += float(live_slice["power"])
            # fill model from live if inventory empty
            if not row.get("model_code") and live_slice.get("miner_type"):
                row["model_code"] = live_slice["miner_type"]
            if not row.get("model") and live_slice.get("miner_type"):
                row["model"] = live_slice["miner_type"]
        elif match and live_slice and not live_slice.get("ok"):
            row["online"] = False
            row["live"] = live_slice
            row["last_error"] = live_slice.get("error") or row.get("last_error")
        elif role == "active":
            # active but no fresh live
            row["online"] = False
            row["live"] = None
        else:
            row["online"] = None  # unknown / not polled
            row["live"] = None
        rows.append(row)
    return {
        "ok": True,
        "miners": rows,
        "live_host": live_ip or None,
        "fleet_hosts": list(fleet_map.keys()),
        "summary": {
            "total": len(rows),
            "online": online_n,
            "hashrate_th": round(sum_th, 6) if sum_th < 1 else round(sum_th, 2),
            "power_w": round(sum_w, 1),
        },
        "ts": datetime.now().isoformat(timespec="seconds"),
    }


def _save_miners_managed(miners: list, *, _from_migrate: bool = False) -> dict:
    """
    Replace managed inventory in miners.db.
    ids: positive integers kept; 0 / legacy strings reassigned (auto-increment).
    """
    _ensure_miners_db()
    clean = [
        _normalize_managed_miner(m) for m in (miners or []) if isinstance(m, dict)
    ]
    clean = _assign_managed_ids(clean)
    # exactly one active
    actives = [i for i, m in enumerate(clean) if m.get("role") == "active"]
    if not actives and clean:
        clean[0]["role"] = "active"
    elif len(actives) > 1:
        for i, m in enumerate(clean):
            if m.get("role") == "active" and i != actives[0]:
                m["role"] = "standby"

    cols = (
        "id",
        "global_id",
        "vendor",
        "host",
        "port",
        "password",
        "enabled",
        "role",
        "alias",
        "name",
        "cell",
        "model",
        "model_code",
        "serial",
        "inventory",
        "cooling",
        "algo",
        "pool_id",
        "miner_type",
        "mac",
        "fw_ver",
        "source",
        "imported_at",
        "last_ok_ts",
        "last_error",
        "factory_hashrate_th",
        "configured_hashrate_th",
    )
    with _miners_db_lock:
        conn = _miners_db_connect()
        try:
            conn.execute("DELETE FROM managed_miners")
            for m in clean:
                conn.execute(
                    f"""
                    INSERT INTO managed_miners ({", ".join(cols)})
                    VALUES ({", ".join("?" for _ in cols)})
                    """,
                    (
                        int(m["id"]),
                        str(m.get("global_id") or ""),
                        str(m.get("vendor") or "whatsminer"),
                        str(m.get("host") or ""),
                        int(m.get("port") or 4028),
                        str(m.get("password") if m.get("password") is not None else ""),
                        1 if m.get("enabled", True) else 0,
                        str(m.get("role") or "standby"),
                        str(m.get("alias") or "")[:64],
                        str(m.get("name") or "")[:64],
                        str(m.get("cell") or "")[:64],
                        str(m.get("model") or "")[:64],
                        str(m.get("model_code") or "")[:64],
                        str(m.get("serial") or "")[:96],
                        str(m.get("inventory") or "")[:64],
                        str(m.get("cooling") or "air"),
                        str(m.get("algo") or "")[:32],
                        str(m.get("pool_id") or "")[:48],
                        str(m.get("miner_type") or "")[:64],
                        m.get("mac"),
                        m.get("fw_ver"),
                        m.get("source"),
                        m.get("imported_at"),
                        m.get("last_ok_ts"),
                        m.get("last_error"),
                        m.get("factory_hashrate_th"),
                        m.get("configured_hashrate_th"),
                    ),
                )
            # keep AUTOINCREMENT sequence ahead of max id
            mx = max((int(m["id"]) for m in clean), default=0)
            try:
                conn.execute(
                    "DELETE FROM sqlite_sequence WHERE name='managed_miners'"
                )
                if mx > 0:
                    conn.execute(
                        "INSERT INTO sqlite_sequence(name, seq) VALUES ('managed_miners', ?)",
                        (mx,),
                    )
            except sqlite3.Error:
                # sqlite_sequence may be missing before first AUTOINCREMENT insert
                pass
            conn.commit()
        finally:
            conn.close()

    # mirror next_id into optional JSON backup only during migrate (debug)
    if _from_migrate:
        try:
            _save_json_atomic(
                MINERS_MANAGED_FILE.with_suffix(".json.migrated"),
                {"version": 1, "miners": clean, "next_id": _next_managed_id(clean)},
            )
        except Exception:
            pass

    # return without re-enter migration loops
    out_clean = [_normalize_managed_miner(m) for m in clean]
    return {
        "ok": True,
        "miners": out_clean,
        "next_id": _next_managed_id(out_clean),
        "db": str(MINERS_DB_FILE),
    }


def _seed_managed_from_active() -> None:
    """
    First-run only: if inventory empty (no DB rows, no legacy JSON), seed from miner_host.
    Never re-seed when inventory already exists (even empty after user Remove-all).
    """
    _ensure_miners_db()
    # legacy JSON still present → migrate path owns it
    try:
        if MINERS_MANAGED_FILE.is_file():
            return
    except Exception:
        pass
    # Marker: once inventory has been initialized, never auto-seed again
    marker = DATA / "miners_inventory_initialized"
    if marker.is_file():
        return
    cur = get_miners_managed()
    if cur.get("miners"):
        try:
            marker.write_text("1\n", encoding="utf-8")
        except Exception:
            pass
        return
    host = str(HOST_MINER or "").strip()
    if not host:
        return
    seed_name = _random_miner_name()
    _save_miners_managed(
        [
            {
                "id": 1,
                "global_id": "",
                "vendor": "whatsminer",
                "host": host,
                "port": int(PORT_MINER or 4028),
                "password": DEFAULT_API_PASSWORD or "admin",
                "enabled": True,
                "role": "active",
                "alias": seed_name,
                "name": seed_name,
                "cell": "",
                "model": "",
                "model_code": "",
                "serial": "",
                "inventory": "",
                "source": "manual",
                "imported_at": datetime.now().isoformat(timespec="seconds"),
            }
        ]
    )
    try:
        marker.write_text("1\n", encoding="utf-8")
    except Exception:
        pass


def import_discovered_miner(
    ip: str,
    *,
    make_active: bool = False,
    alias: str | None = None,
) -> dict:
    ip = str(ip or "").strip()
    if not ip:
        raise ValueError("ip required")
    disc = get_miners_discovered()
    found = None
    for m in disc.get("miners") or []:
        if str(m.get("ip") or "") == ip and not m.get("ignored"):
            found = m
            break
    if not found:
        raise ValueError(f"ip {ip} not in discovered list")
    managed = list(get_miners_managed().get("miners") or [])
    # match by MAC or IP
    mac = str(found.get("mac") or "").strip().lower()
    idx = None
    for i, m in enumerate(managed):
        if mac and str(m.get("mac") or "").strip().lower() == mac:
            idx = i
            break
        if str(m.get("host") or "") == ip:
            idx = i
            break
    vinfo = resolve_miner_vendor(found.get("vendor") or "whatsminer")
    vendor = str(vinfo.get("id") or "whatsminer")
    port = int(found.get("port") or vinfo.get("default_port") or 4028)
    mtype = str(found.get("miner_type") or "").strip()
    # Fresh import: auto-inc id (0→allocate) + random name (like old m_<hex>)
    rand_name = _random_miner_name()
    display = (str(alias).strip() if alias else "") or rand_name
    prev = managed[idx] if idx is not None else None
    row = {
        "id": prev.get("id") if prev else 0,
        "global_id": (prev.get("global_id") if prev else "") or "",
        "vendor": vendor,
        "host": ip,
        "port": port,
        "password": DEFAULT_API_PASSWORD or "admin",
        "enabled": True,
        "role": "standby",
        "alias": display[:64],
        "name": display[:64],
        "cell": "",
        "model": mtype,
        "model_code": mtype,
        "serial": str(found.get("serial") or found.get("minersn") or "").strip(),
        "inventory": "",
        "miner_type": mtype,
        "mac": found.get("mac"),
        "fw_ver": found.get("fw_ver"),
        "source": "discovery",
        "imported_at": datetime.now().isoformat(timespec="seconds"),
    }
    if prev is not None:
        # keep role/password/inventory labels if already managed
        row["role"] = prev.get("role") or "standby"
        if prev.get("password"):
            row["password"] = prev["password"]
        for k in (
            "alias",
            "name",
            "cell",
            "model",
            "model_code",
            "serial",
            "inventory",
            "global_id",
        ):
            if prev.get(k) not in (None, ""):
                row[k] = prev[k]
        managed[idx] = row
    else:
        managed.append(row)
    if make_active or not any(m.get("role") == "active" for m in managed):
        for m in managed:
            m["role"] = "standby"
        row["role"] = "active"
        # sync active connection
        apply_miner_settings(
            host=row["host"],
            port=int(row["port"]),
            password=row.get("password"),
            persist=True,
        )
    return _save_miners_managed(managed)


def add_managed_manual(
    host: str,
    *,
    port: int | None = None,
    vendor: str = "whatsminer",
    password: str | None = None,
    make_active: bool = True,
    alias: str | None = None,
) -> dict:
    host = str(host or "").strip()
    if not host:
        raise ValueError("host required")
    vinfo = resolve_miner_vendor(vendor or "whatsminer")
    vendor = str(vinfo.get("id") or "whatsminer")
    if port is None:
        port = int(vinfo.get("default_port") or 4028)
    port = int(port)
    managed = list(get_miners_managed().get("miners") or [])
    for m in managed:
        if str(m.get("host") or "") == host:
            raise ValueError(f"host {host} already managed")
    rand_name = _random_miner_name()
    display = (str(alias).strip() if alias else "") or rand_name
    row = {
        "id": 0,  # allocate on save
        "global_id": "",
        "vendor": vendor,
        "host": host,
        "port": port,
        "password": password or DEFAULT_API_PASSWORD or "admin",
        "enabled": True,
        "role": "standby",
        "alias": display[:64],
        "name": display[:64],
        "cell": "",
        "model": "",
        "model_code": "",
        "serial": "",
        "inventory": "",
        "source": "manual",
        "imported_at": datetime.now().isoformat(timespec="seconds"),
    }
    managed.append(row)
    if make_active or not any(m.get("role") == "active" for m in managed):
        for m in managed:
            m["role"] = "standby"
        row["role"] = "active"
        apply_miner_settings(
            host=row["host"],
            port=int(row["port"]),
            password=row.get("password"),
            persist=True,
        )
    return _save_miners_managed(managed)


def update_managed(mid: str, fields: dict | None) -> dict:
    """
    Patch inventory / identity fields of a managed miner.
    id is stable key; optional fields.alias/name/cell/model/model_code/serial/inventory
    plus host/port/vendor/password/enabled.
    """
    mid = str(mid or "").strip()
    if not mid:
        raise ValueError("id required")
    if not isinstance(fields, dict):
        fields = {}
    managed = list(get_miners_managed().get("miners") or [])
    found = None
    for m in managed:
        if str(m.get("id") or "") == mid:
            found = m
            break
    if not found:
        raise ValueError(f"miner not found: {mid}")
    # editable inventory / connection fields
    str_keys = (
        "alias",
        "name",
        "cell",
        "model",
        "model_code",
        "serial",
        "inventory",
        "vendor",
        "host",
        "password",
        "miner_type",
        "pool_id",
        "algo",
        "algorithm",
    )
    for k in str_keys:
        if k in fields and fields[k] is not None:
            found[k] = str(fields[k]).strip()
    if "algorithm" in fields and "algo" not in fields:
        found["algo"] = str(fields.get("algorithm") or "").strip()
    if "cooling" in fields or "cooling_type" in fields:
        found["cooling"] = _normalize_miner_cooling(
            fields.get("cooling", fields.get("cooling_type"))
        )
    if "port" in fields and fields["port"] is not None:
        try:
            found["port"] = int(fields["port"])
        except (TypeError, ValueError) as e:
            raise ValueError("port invalid") from e
    if "enabled" in fields:
        found["enabled"] = bool(fields["enabled"])
    # Inventory hashrate targets (TH/s)
    for thr_key, aliases in (
        (
            "factory_hashrate_th",
            ("factory_hashrate_th", "factory_th", "rated_hashrate_th"),
        ),
        (
            "configured_hashrate_th",
            ("configured_hashrate_th", "target_hashrate_th", "configured_th"),
        ),
    ):
        raw_v = None
        hit = False
        for ak in aliases:
            if ak in fields:
                raw_v = fields.get(ak)
                hit = True
                break
        if hit:
            # empty string clears the field
            if raw_v is None or raw_v == "":
                found[thr_key] = None
            else:
                found[thr_key] = _parse_optional_th(raw_v)
    # resolve vendor id via catalog (Whatsminer / Antminer / Avalon / Goldshell)
    if "vendor" in fields and fields.get("vendor") is not None:
        vinfo = resolve_miner_vendor(str(fields.get("vendor")))
        found["vendor"] = vinfo.get("id") or found.get("vendor")
        if not found.get("port") and vinfo.get("default_port"):
            found["port"] = int(vinfo["default_port"])
    # keep model_code ↔ miner_type in sync when only one set
    if found.get("model_code") and not found.get("miner_type"):
        found["miner_type"] = found["model_code"]
    if found.get("miner_type") and not found.get("model_code"):
        found["model_code"] = found["miner_type"]
    if found.get("model_code") and not found.get("model"):
        found["model"] = found["model_code"]
    # model/vendor change without explicit algo → resolve from catalog
    if "algo" not in fields and "algorithm" not in fields:
        if any(k in fields for k in ("model", "model_code", "miner_type", "vendor")):
            found["algo"] = ""
    was_active = found.get("role") == "active"
    out = _save_miners_managed(managed)
    # if active connection fields changed — re-apply
    if was_active and any(k in fields for k in ("host", "port", "password")):
        try:
            apply_miner_settings(
                host=found.get("host"),
                port=int(found.get("port") or 4028),
                password=found.get("password"),
                persist=True,
            )
        except Exception as e:
            print(f"[managed] re-apply after edit: {e}", flush=True)
    out["updated"] = mid
    out["ok"] = True
    return out


def set_managed_active(mid: str) -> dict:
    mid = str(mid or "").strip()
    managed = list(get_miners_managed().get("miners") or [])
    found = None
    for m in managed:
        if str(m.get("id") or "") == mid:
            found = m
            m["role"] = "active"
            m["enabled"] = True
        else:
            if m.get("role") == "active":
                m["role"] = "standby"
    if not found:
        raise ValueError("miner not found")
    apply_miner_settings(
        host=found["host"],
        port=int(found.get("port") or 4028),
        password=found.get("password"),
        persist=True,
    )
    return _save_miners_managed(managed)


def remove_managed(mid: str) -> dict:
    mid = str(mid or "").strip()
    if not mid:
        raise ValueError("id required")
    before = list(get_miners_managed().get("miners") or [])
    managed = [m for m in before if str(m.get("id") or "") != mid]
    if len(managed) == len(before):
        raise ValueError(f"miner not found: {mid}")
    if managed and not any(m.get("role") == "active" for m in managed):
        managed[0]["role"] = "active"
        try:
            apply_miner_settings(
                host=managed[0]["host"],
                port=int(managed[0].get("port") or 4028),
                password=managed[0].get("password"),
                persist=True,
            )
        except Exception as e:
            print(f"[managed] promote after remove: {e}", flush=True)
    out = _save_miners_managed(managed)
    out["removed"] = mid
    out["ok"] = True
    return out


def ignore_discovered(ip: str, ignored: bool = True) -> dict:
    ip = str(ip or "").strip()
    raw = _load_json(MINERS_DISCOVERED_FILE, {"version": 1, "miners": []})
    if not isinstance(raw, dict):
        raw = {"version": 1, "miners": []}
    miners = raw.get("miners") if isinstance(raw.get("miners"), list) else []
    for m in miners:
        if isinstance(m, dict) and str(m.get("ip") or "") == ip:
            m["ignored"] = bool(ignored)
    raw["miners"] = miners
    _save_json_atomic(MINERS_DISCOVERED_FILE, raw)
    return get_miners_discovered()


def _host_to_slash24(host: str) -> str | None:
    host = str(host or "").strip()
    if not host:
        return None
    if host.startswith("["):
        host = host.split("]", 1)[0].lstrip("[")
    if ":" in host and host.count(":") == 1:
        host = host.split(":", 1)[0]
    parts = host.split(".")
    if len(parts) == 4 and all(p.isdigit() and 0 <= int(p) <= 255 for p in parts):
        return f"{parts[0]}.{parts[1]}.{parts[2]}.0/24"
    return None


def _default_discovery_ranges() -> list[str]:
    """
    When UI/config has no ranges: /24 of every managed miner + active host.
    Covers multi-subnet fleets (e.g. 172.16.100 + 192.168.13).

    Does NOT scan every router interface (VPN / WAN / guest) — that balloons
    to thousands of hosts and stalls the poller on Keenetic.
    """
    seen: set[str] = set()
    out: list[str] = []

    def _add(host: str) -> None:
        cidr = _host_to_slash24(host)
        if cidr and cidr not in seen:
            seen.add(cidr)
            out.append(cidr)

    try:
        managed = get_miners_managed()
        for m in managed.get("miners") or []:
            if isinstance(m, dict):
                _add(str(m.get("host") or ""))
    except Exception:
        pass
    _add(str(HOST_MINER or ""))
    return out


def _expand_one_scan_range(s: str) -> list[str]:
    """
    Expand one range token to host IPs.

    Supported:
      • CIDR:              192.168.1.0/24
      • full IP–IP:        192.168.1.1-192.168.2.240
      • last-octet:        192.168.1.1-40
      • multi-octet:       192.168.1-2.1-250   (3rd 1..2, 4th 1..250)
      • single IP:         192.168.1.10
    """
    import ipaddress

    s = str(s or "").strip()
    if not s:
        return []
    if "/" in s:
        net = ipaddress.ip_network(s, strict=False)
        hosts = list(net.hosts()) if net.num_addresses > 2 else list(net)
        return [str(ip) for ip in hosts]

    if "-" in s:
        # 1) full IP–IP (dash between two dotted quads)
        m = re.fullmatch(
            r"(\d{1,3}(?:\.\d{1,3}){3})\s*-\s*(\d{1,3}(?:\.\d{1,3}){3})", s
        )
        if m:
            ia = int(ipaddress.IPv4Address(m.group(1)))
            ib = int(ipaddress.IPv4Address(m.group(2)))
            if ib < ia:
                ia, ib = ib, ia
            if ib - ia > 4096:
                raise ValueError(f"range too large: {s}")
            return [str(ipaddress.IPv4Address(n)) for n in range(ia, ib + 1)]

        # 2) compact multi-octet / last-octet: exactly 4 dotted segments,
        #    each "N" or "N-M"
        segs = s.split(".")
        if len(segs) == 4 and all(
            re.fullmatch(r"\d{1,3}(?:-\d{1,3})?", seg.strip()) for seg in segs
        ):
            bounds: list[tuple[int, int]] = []
            for seg in segs:
                seg = seg.strip()
                if "-" in seg:
                    a, b = seg.split("-", 1)
                    lo, hi = int(a), int(b)
                    if lo > hi:
                        lo, hi = hi, lo
                else:
                    lo = hi = int(seg)
                if lo < 0 or hi > 255:
                    raise ValueError(f"invalid octet range: {s}")
                bounds.append((lo, hi))
            n = 1
            for lo, hi in bounds:
                n *= hi - lo + 1
                if n > 4096:
                    raise ValueError(f"range too large ({n} hosts): {s}")
            out: list[str] = []
            for o0 in range(bounds[0][0], bounds[0][1] + 1):
                for o1 in range(bounds[1][0], bounds[1][1] + 1):
                    for o2 in range(bounds[2][0], bounds[2][1] + 1):
                        for o3 in range(bounds[3][0], bounds[3][1] + 1):
                            out.append(f"{o0}.{o1}.{o2}.{o3}")
            return out

        raise ValueError(f"invalid IP range: {s}")

    return [str(ipaddress.IPv4Address(s))]


def _expand_scan_ranges(ranges: list[str]) -> list[str]:
    """CIDR / start-end / multi-octet / single IP → host list (cap 4096).

    Invalid entries are skipped (log) so one bad range cannot abort the scan.
    """
    seen: set[str] = set()
    out: list[str] = []
    errors: list[str] = []
    for r in ranges or []:
        s = str(r or "").strip()
        if not s:
            continue
        try:
            for ip_s in _expand_one_scan_range(s):
                if ip_s not in seen:
                    seen.add(ip_s)
                    out.append(ip_s)
        except Exception as e:
            errors.append(f"{s!r}: {e}")
            print(f"[miner-poller] discovery skip range {s!r}: {e}", flush=True)
        if len(out) > 4096:
            raise ValueError(f"too many hosts ({len(out)} > 4096) — shrink ranges")
    if not out and errors:
        raise ValueError("; ".join(errors[:3]))
    return out


def _tcp_open_fast(ip: str, port: int, timeout: float) -> bool:
    try:
        with socket.create_connection((ip, int(port)), timeout=timeout):
            return True
    except Exception:
        return False


def _recv_until_json(sock: socket.socket, timeout: float = 1.5) -> dict | None:
    sock.settimeout(timeout)
    chunks: list[bytes] = []
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            b = sock.recv(4096)
        except socket.timeout:
            break
        except Exception:
            break
        if not b:
            break
        chunks.append(b)
        raw = b"".join(chunks)
        # null-terminated or complete JSON
        if b"\x00" in raw:
            raw = raw.split(b"\x00", 1)[0]
        text = raw.decode("utf-8", errors="replace").strip()
        if not text:
            continue
        try:
            obj = json.loads(text)
            return obj if isinstance(obj, dict) else None
        except Exception:
            # keep reading
            if len(raw) > 65536:
                break
    text = b"".join(chunks).split(b"\x00", 1)[0].decode("utf-8", errors="replace").strip()
    if not text:
        return None
    try:
        obj = json.loads(text)
        return obj if isinstance(obj, dict) else None
    except Exception:
        return None


def _probe_tcp_json(ip: str, port: int, payload: dict, timeout: float) -> dict | None:
    try:
        with socket.create_connection((ip, int(port)), timeout=timeout) as sock:
            data = (json.dumps(payload, separators=(",", ":")) + "\n").encode()
            sock.sendall(data)
            return _recv_until_json(sock, timeout=timeout)
    except Exception:
        return None


def _probe_http_text(
    ip: str, port: int, path: str = "/", timeout: float = 1.0
) -> tuple[int | None, str]:
    try:
        url = f"http://{ip}:{int(port)}{path}" if int(port) != 80 else f"http://{ip}{path}"
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "poolheat-discovery/1.0", "Accept": "*/*"},
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            code = int(getattr(resp, "status", 200) or 200)
            body = resp.read(65536).decode("utf-8", errors="replace")
            return code, body
    except urllib.error.HTTPError as e:
        try:
            body = e.read(65536).decode("utf-8", errors="replace")
        except Exception:
            body = ""
        return int(e.code), body
    except Exception:
        return None, ""


def _probe_host_discovery(
    ip: str,
    *,
    timeout: float,
    ports: list[int],
    passwords: list[str],
) -> dict | None:
    """
    Fingerprint one host. Returns discovered miner dict or None.
    Covers Whatsminer :4028/:4433, CGMiner/BMMiner/iPollo/Goldshell :4028,
    Antminer web :80, Antminer SearchFreq :6060.
    """
    t0 = time.time()
    ports = [int(p) for p in (ports or [4028, 80, 4433, 6060]) if 1 <= int(p) <= 65535]
    # always try classic ASIC ports
    for must in (4028, 80, 6060):
        if must not in ports:
            ports.append(must)

    def _hit(
        vendor: str,
        port: int,
        *,
        miner_type: str | None = None,
        fw: str | None = None,
        mac: str | None = None,
        platform: str | None = None,
    ) -> dict:
        return {
            "ip": ip,
            "host": ip,
            "vendor": vendor,
            "port": int(port),
            "miner_type": miner_type or "",
            "fw": fw or "",
            "fw_ver": fw or "",
            "mac": mac or "",
            "platform": platform or "",
            "status": "online",
            "rtt_ms": int((time.time() - t0) * 1000),
        }

    # ── TCP :4028 (Whatsminer cmd / CGMiner command) ─────────────────────
    if 4028 in ports and _tcp_open_fast(ip, 4028, timeout):
        # Whatsminer get_version
        for pw in passwords or ["admin"]:
            raw = _probe_tcp_json(
                ip, 4028, {"cmd": "get_version", "token": str(pw)}, timeout
            )
            if not raw:
                raw = _probe_tcp_json(ip, 4028, {"cmd": "get_version"}, timeout)
            if isinstance(raw, dict) and (
                raw.get("STATUS") is not None
                or isinstance(raw.get("Msg"), dict)
                or raw.get("Code") is not None
            ):
                msg = raw.get("Msg") if isinstance(raw.get("Msg"), dict) else {}
                # CGMiner error "Missing JSON" → not Whatsminer
                st = raw.get("STATUS")
                err_msg = ""
                if isinstance(st, list) and st and isinstance(st[0], dict):
                    err_msg = str(st[0].get("Msg") or "")
                if "Missing JSON" in err_msg or "command" in err_msg.lower():
                    break
                mt = str(msg.get("miner_type") or msg.get("Type") or "").strip()
                fw = str(msg.get("fw_ver") or msg.get("api_ver") or "").strip()
                plat = str(msg.get("platform") or "").strip()
                if mt or fw or plat or msg:
                    return _hit(
                        "whatsminer",
                        4028,
                        miner_type=mt or "Whatsminer",
                        fw=fw,
                        platform=plat,
                    )
            break  # one attempt enough for plaintext version

        # CGMiner / BMMiner / iPollo / Goldshell
        raw = _probe_tcp_json(ip, 4028, {"command": "version"}, timeout)
        if not isinstance(raw, dict):
            raw = _probe_tcp_json(ip, 4028, {"command": "summary"}, timeout)
        if isinstance(raw, dict):
            ver = None
            for key in ("VERSION", "version", "SUMMARY", "summary"):
                sec = raw.get(key)
                if isinstance(sec, list) and sec and isinstance(sec[0], dict):
                    ver = sec[0]
                    break
                if isinstance(sec, dict):
                    ver = sec
                    break
            desc = ""
            st = raw.get("STATUS")
            if isinstance(st, list) and st and isinstance(st[0], dict):
                desc = str(st[0].get("Description") or "")
            mtype = ""
            fw = ""
            vendor = "cgminer"
            if isinstance(ver, dict):
                mtype = str(
                    ver.get("Type") or ver.get("type") or ver.get("Model") or ""
                ).strip()
                fw = str(
                    ver.get("Miner")
                    or ver.get("BMMiner")
                    or ver.get("CompileTime")
                    or ""
                ).strip()
                if ver.get("BMMiner") or "antminer" in mtype.lower():
                    vendor = "antminer"
            desc_l = desc.lower()
            mt_l = mtype.lower()
            if "ipollo" in desc_l or "ipollo" in mt_l:
                vendor = "ipollo"
            elif "goldshell" in desc_l or "ckb" in desc_l or "ckbox" in mt_l:
                vendor = "goldshell"
            elif "antminer" in mt_l or "bitmain" in desc_l or "jansson" in desc_l:
                vendor = "antminer"
            if mtype or fw or desc or raw.get("STATUS") is not None:
                return _hit(
                    vendor,
                    4028,
                    miner_type=mtype or (desc[:40] if desc else vendor.title()),
                    fw=fw,
                )

    # ── Antminer SearchFreqServer :6060 ─────────────────────────────────
    if 6060 in ports and _tcp_open_fast(ip, 6060, min(timeout, 0.8)):
        code, body = _probe_http_text(ip, 6060, "/productName", timeout=timeout)
        name = (body or "").strip()
        if code == 200 and name and (
            "antminer" in name.lower() or name.lower().startswith("ant")
        ):
            return _hit("antminer", 6060, miner_type=name)
        code2, body2 = _probe_http_text(ip, 6060, "/miner_power", timeout=timeout)
        if code2 == 200 and "power" in (body2 or "").lower():
            return _hit("antminer", 6060, miner_type="Antminer")

    # ── HTTP :80 / :8080 ────────────────────────────────────────────────
    for http_port in (80, 8080, 443):
        if http_port not in ports:
            continue
        if not _tcp_open_fast(ip, http_port, min(timeout, 0.6)):
            continue
        code, body = _probe_http_text(ip, http_port, "/", timeout=timeout)
        low = (body or "").lower()
        title = ""
        m_title = re.search(
            r"<title[^>]*>(.*?)</title>", body or "", flags=re.I | re.S
        )
        if m_title:
            title = re.sub(r"\s+", " ", m_title.group(1)).strip()
        if (
            "antminer" in low
            or "bitmain" in low
            or "antminer" in title.lower()
        ):
            return _hit(
                "antminer",
                http_port,
                miner_type=title or "Antminer",
            )
        # Goldshell cloud box
        if "goldshell" in low or "/mcb/" in low:
            return _hit("goldshell", http_port, miner_type=title or "Goldshell")
        # iPollo LuCI
        if "ipollo" in low or ("luci" in low and "miner" in low):
            return _hit("ipollo", http_port, miner_type=title or "iPollo")

    # ── Whatsminer V3 port open (no full binary probe without wm-lib) ───
    if 4433 in ports and _tcp_open_fast(ip, 4433, min(timeout, 0.5)):
        # weak signal — only if nothing else matched
        return _hit("whatsminer", 4433, miner_type="Whatsminer (v3 port)")

    return None


def run_miner_discovery(
    ranges: list[str] | None = None,
    *,
    cfg: dict | None = None,
) -> dict:
    """
    Scan LAN ranges, write miners_discovered.json + scan result.
    Used by Python miner-poller (Go binary has its own implementation).
    """
    t0 = time.time()
    cfg = cfg or get_miner_poller_cfg()
    disc = (cfg or {}).get("discovery") if isinstance(cfg, dict) else {}
    disc = disc if isinstance(disc, dict) else {}
    rng = [str(x).strip() for x in (ranges or []) if str(x).strip()]
    if not rng:
        rng = [str(x).strip() for x in (disc.get("ranges") or []) if str(x).strip()]
    if not rng:
        rng = _default_discovery_ranges()
    if not rng:
        return {
            "ok": False,
            "error": "no scan ranges configured",
            "probed": 0,
            "found": 0,
            "scan_ms": int((time.time() - t0) * 1000),
            "updated_ts": datetime.now().isoformat(timespec="seconds"),
        }
    try:
        hosts = _expand_scan_ranges(rng)
    except Exception as e:
        return {
            "ok": False,
            "error": str(e),
            "probed": 0,
            "found": 0,
            "scan_ms": int((time.time() - t0) * 1000),
            "updated_ts": datetime.now().isoformat(timespec="seconds"),
        }
    ignore = {
        str(x).strip()
        for x in (disc.get("ignore_ips") or [])
        if str(x).strip()
    }
    hosts = [h for h in hosts if h not in ignore]
    timeout_ms = int(disc.get("probe_timeout_ms") or 500)
    timeout = max(0.15, min(5.0, timeout_ms / 1000.0))
    # Cap hard: ThreadPool of 48 × open sockets blows ~256MB Keenetic
    conc = max(4, min(24, int(disc.get("concurrency") or 16)))
    ports = disc.get("ports") if isinstance(disc.get("ports"), list) else []
    ports = [int(p) for p in ports if str(p).isdigit()] or [4028, 80, 4433, 6060]
    passwords = disc.get("passwords") if isinstance(disc.get("passwords"), list) else []
    passwords = [str(p) for p in passwords if str(p).strip()] or ["admin"]
    if DEFAULT_API_PASSWORD and str(DEFAULT_API_PASSWORD) not in passwords:
        passwords = [str(DEFAULT_API_PASSWORD)] + passwords

    print(
        f"[miner-poller] discovery hosts={len(hosts)} conc={conc} "
        f"timeout={timeout}s ports={ports} ranges={rng}",
        flush=True,
    )

    hits: list[dict] = []
    lock = threading.Lock()

    def _one(ip: str) -> None:
        try:
            m = _probe_host_discovery(
                ip, timeout=timeout, ports=ports, passwords=passwords
            )
        except Exception:
            m = None
        if m:
            with lock:
                hits.append(m)

    # Thread pool (stdlib concurrent.futures already imported)
    with ThreadPoolExecutor(max_workers=conc) as ex:
        list(ex.map(_one, hosts))

    # merge with previous discovered (preserve first_seen / ignored)
    prev_raw = _load_json(
        MINERS_DISCOVERED_FILE, {"version": 1, "miners": [], "updated_ts": None}
    )
    prev_list = (
        prev_raw.get("miners") if isinstance(prev_raw.get("miners"), list) else []
    )
    prev_by: dict[str, dict] = {}
    for p in prev_list:
        if isinstance(p, dict) and p.get("ip"):
            prev_by[str(p["ip"])] = p
    now = datetime.now().isoformat(timespec="seconds")
    out: list[dict] = []
    seen: set[str] = set()
    for h in hits:
        ip = str(h.get("ip") or "")
        if not ip:
            continue
        old = prev_by.get(ip) or {}
        if old.get("ignored"):
            h["ignored"] = True
        h["first_seen"] = old.get("first_seen") or now
        h["last_seen"] = now
        out.append(h)
        seen.add(ip)
    for p in prev_list:
        if not isinstance(p, dict):
            continue
        ip = str(p.get("ip") or "")
        if ip and ip not in seen and p.get("ignored"):
            out.append(p)
    # sort by IP
    def _ip_key(m: dict) -> tuple:
        parts = str(m.get("ip") or "").split(".")
        try:
            return tuple(int(x) for x in parts)
        except Exception:
            return (999, 999, 999, 999)

    out.sort(key=_ip_key)
    scan_ms = int((time.time() - t0) * 1000)
    payload = {
        "version": 1,
        "updated_ts": now,
        "probed": len(hosts),
        "found": len(hits),
        "scan_ms": scan_ms,
        "ranges": rng,
        "miners": out,
    }
    try:
        _save_json_atomic(MINERS_DISCOVERED_FILE, payload)
    except Exception as e:
        return {
            "ok": False,
            "error": f"save discovered: {e}",
            "probed": len(hosts),
            "found": len(hits),
            "scan_ms": scan_ms,
            "updated_ts": now,
        }
    return {
        "ok": True,
        "probed": len(hosts),
        "found": len(hits),
        "scan_ms": scan_ms,
        "updated_ts": now,
        "ranges": rng,
    }


def process_pending_miner_scan() -> bool:
    """
    If miner_scan_req.json exists, run discovery (Python poller path).
    Mirrors Go ProcessPendingScan.
    """
    if not MINER_SCAN_REQ_FILE.is_file():
        return False
    try:
        req = _load_json(MINER_SCAN_REQ_FILE, {})
    except Exception as e:
        print(f"[miner-poller] scan-req read: {e}", flush=True)
        try:
            MINER_SCAN_REQ_FILE.unlink()
        except Exception:
            pass
        return True
    try:
        MINER_SCAN_REQ_FILE.unlink()
    except Exception:
        pass
    if not isinstance(req, dict):
        return True
    req_id = str(req.get("id") or uuid.uuid4().hex)
    ranges = req.get("ranges") if isinstance(req.get("ranges"), list) else []
    ranges = [str(x).strip() for x in ranges if str(x).strip()]
    cfg = get_miner_poller_cfg()
    if not ranges:
        ranges = [
            str(x).strip()
            for x in ((cfg.get("discovery") or {}).get("ranges") or [])
            if str(x).strip()
        ]
    if not ranges:
        ranges = _default_discovery_ranges()
    try:
        _save_json_atomic(
            MINER_SCAN_STATUS_FILE,
            {
                "running": True,
                "id": req_id,
                "phase": "scanning",
                "ranges": ranges,
                "ts": datetime.now().isoformat(timespec="seconds"),
            },
        )
    except Exception:
        pass
    print(f"[miner-poller] scan start id={req_id} ranges={ranges}", flush=True)
    res = run_miner_discovery(ranges, cfg=cfg)
    res["id"] = req_id
    res["ts"] = time.time()
    try:
        _save_json_atomic(MINER_SCAN_RESULT_FILE, res)
    except Exception as e:
        print(f"[miner-poller] scan result write: {e}", flush=True)
    try:
        _save_json_atomic(
            MINER_SCAN_STATUS_FILE,
            {
                "running": False,
                "id": req_id,
                "phase": "idle",
                "last_ok": bool(res.get("ok")),
                "found": res.get("found"),
                "probed": res.get("probed"),
                "error": res.get("error"),
                "ts": datetime.now().isoformat(timespec="seconds"),
            },
        )
    except Exception:
        pass
    print(
        f"[miner-poller] scan done id={req_id} ok={res.get('ok')} "
        f"probed={res.get('probed')} found={res.get('found')} "
        f"ms={res.get('scan_ms')} err={res.get('error')}",
        flush=True,
    )
    return True


def miner_discovery_loop() -> None:
    """Manual scan requests + optional periodic auto-discovery."""
    print("[miner-poller] discovery loop start", flush=True)
    last_auto = 0.0
    while not _miner_poller_stop.is_set():
        try:
            process_pending_miner_scan()
        except Exception as e:
            print(f"[miner-poller] scan: {e}", flush=True)
        try:
            cfg = get_miner_poller_cfg()
            disc = (cfg or {}).get("discovery") or {}
            if disc.get("enabled"):
                iv = max(60, int(disc.get("interval_sec") or 600))
                if time.time() - last_auto >= iv:
                    ranges = [
                        str(x).strip()
                        for x in (disc.get("ranges") or [])
                        if str(x).strip()
                    ] or _default_discovery_ranges()
                    if ranges:
                        print(
                            f"[miner-poller] auto-discovery ranges={ranges}",
                            flush=True,
                        )
                        run_miner_discovery(ranges, cfg=cfg)
                    last_auto = time.time()
        except Exception as e:
            print(f"[miner-poller] auto-discovery: {e}", flush=True)
        _miner_poller_stop.wait(timeout=1.0)
    print("[miner-poller] discovery loop stop", flush=True)


def start_miner_scan(ranges: list[str] | None = None) -> dict:
    if not miner_poller_process_alive():
        raise RuntimeError("miner-poller not running — scan only via poller")
    rng = [str(x).strip() for x in (ranges or []) if str(x).strip()]
    if not rng:
        # fall back to saved discovery ranges, then managed/active /24s
        try:
            cfg = get_miner_poller_cfg()
            d = (cfg or {}).get("discovery") or {}
            saved = d.get("ranges") if isinstance(d.get("ranges"), list) else []
            rng = [str(x).strip() for x in saved if str(x).strip()]
        except Exception:
            rng = []
    if not rng:
        rng = _default_discovery_ranges()
    if not rng:
        raise ValueError(
            "no scan ranges — set CIDR/range in Settings → Miner-poller "
            "(e.g. 192.168.1.0/24) or add managed miners / miner_host"
        )
    req_id = uuid.uuid4().hex
    req = {
        "id": req_id,
        "ts": time.time(),
        "ranges": rng,
    }
    try:
        if MINER_SCAN_RESULT_FILE.is_file():
            MINER_SCAN_RESULT_FILE.unlink()
    except Exception:
        pass
    # Mark queued immediately so UI does not treat stale idle status as "done"
    try:
        _save_json_atomic(
            MINER_SCAN_STATUS_FILE,
            {
                "running": True,
                "id": req_id,
                "phase": "queued",
                "ranges": rng,
                "ts": datetime.now().isoformat(timespec="seconds"),
            },
        )
    except Exception:
        pass
    _save_json_atomic(MINER_SCAN_REQ_FILE, req)
    return {"ok": True, "id": req_id, "queued": True, "ranges": rng}


def miner_scan_status() -> dict:
    st = _load_json(MINER_SCAN_STATUS_FILE, {})
    res = _load_json(MINER_SCAN_RESULT_FILE, {})
    return {
        "ok": True,
        "status": st if isinstance(st, dict) else {},
        "last_result": res if isinstance(res, dict) else {},
        "discovered": get_miners_discovered(),
    }


def apply_miner_settings(
    host: str | None = None,
    port: int | None = None,
    password: str | None = None,
    poll_interval_sec: int | None = None,
    dry_run: bool | None = None,
    project_name: str | None = None,
    *,
    persist: bool = True,
) -> dict:
    """Update runtime miner target; optionally write config.json."""
    global HOST_MINER, PORT_MINER, DEFAULT_API_PASSWORD, POLL_INTERVAL_SEC, DRY_RUN
    global PROJECT_NAME, _cache, _cache_ts

    with _miner_cfg_lock:
        if host is not None:
            h = str(host).strip()
            if not h:
                raise ValueError("miner_host empty")
            # basic sanity: no spaces
            if any(c.isspace() for c in h):
                raise ValueError("miner_host invalid")
            HOST_MINER = h
        if port is not None:
            p = int(port)
            if p < 1 or p > 65535:
                raise ValueError("miner_port out of range")
            PORT_MINER = p
        if password is not None and str(password) != "":
            DEFAULT_API_PASSWORD = str(password)
        if poll_interval_sec is not None:
            pi = int(poll_interval_sec)
            if pi < 2 or pi > 300:
                raise ValueError("poll_interval_sec must be 2–300")
            POLL_INTERVAL_SEC = pi
        if dry_run is not None:
            DRY_RUN = bool(dry_run)
        if project_name is not None:
            pn = str(project_name).strip() or "poolheat_WM"
            if len(pn) > 64:
                pn = pn[:64]
            PROJECT_NAME = pn

        settings = {
            "miner_host": HOST_MINER,
            "miner_port": int(PORT_MINER),
            "api_password": DEFAULT_API_PASSWORD,
            "poll_interval_sec": int(POLL_INTERVAL_SEC),
            "dry_run": bool(DRY_RUN),
            "project_name": str(PROJECT_NAME or "poolheat_WM"),
            "host": f"{HOST_MINER}:{PORT_MINER}",
        }
        # keep LuCI proxy target in sync with miner host
        if host is not None and luci_proxy is not None:
            try:
                luci_proxy.configure(target_host=HOST_MINER)
            except Exception:
                pass

        if persist:
            path = _miner_config_path()
            path.parent.mkdir(parents=True, exist_ok=True)
            existing: dict = {}
            if path.is_file():
                try:
                    existing = json.loads(path.read_text(encoding="utf-8"))
                    if not isinstance(existing, dict):
                        existing = {}
                except Exception:
                    existing = {}
            existing["miner_host"] = HOST_MINER
            existing["miner_port"] = int(PORT_MINER)
            existing["api_password"] = DEFAULT_API_PASSWORD
            existing["poll_interval_sec"] = int(POLL_INTERVAL_SEC)
            existing["dry_run"] = bool(DRY_RUN)
            # project_name: only overwrite when explicitly provided in this call;
            # otherwise keep file value (don't clobber via dry_run-only saves)
            if project_name is not None:
                existing["project_name"] = str(PROJECT_NAME or "poolheat_WM")
            elif existing.get("project_name"):
                PROJECT_NAME = str(existing["project_name"]).strip() or PROJECT_NAME
                existing["project_name"] = str(PROJECT_NAME or "poolheat_WM")
            else:
                existing["project_name"] = str(PROJECT_NAME or "poolheat_WM")
            settings["project_name"] = str(existing.get("project_name") or "poolheat_WM")
            # keep other keys (bind, http_port, comment…)
            if "bind" not in existing:
                existing["bind"] = HTTP_BIND
            if "http_port" not in existing:
                existing["http_port"] = HTTP_PORT
            path.write_text(
                json.dumps(existing, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
            settings["config_path"] = str(path)
            settings["saved"] = True
            settings["saved"] = True
        else:
            settings["saved"] = False

    # drop live cache so next poll hits new host
    with _cache_lock:
        _cache = None
        _cache_ts = 0.0
    # invalidate identity / error caches when target host changes
    if host is not None:
        try:
            global _IDENT_CACHE
            _IDENT_CACHE = {"ts": 0.0, "data": None}
        except Exception:
            pass
        try:
            with _state_lock:
                _state["miner_error_cache"] = {}
                _save_state()
        except Exception:
            pass
    return settings


# ── Config backup / restore (settings JSON bundle) ───────────────────────────
CONFIG_BACKUP_FORMAT = "poolheat_config_backup"
CONFIG_BACKUP_VERSION = 1
# Keys in config.json that are host/runtime facts — rewritten on every boot
_CONFIG_META_KEY = "meta"


def _read_json_file(path: Path) -> dict | None:
    try:
        if not path.is_file():
            return None
        raw = json.loads(path.read_text(encoding="utf-8"))
        return raw if isinstance(raw, dict) else None
    except Exception:
        return None


def build_runtime_meta() -> dict:
    """
    Host + software facts for config.json meta (and backups).
    Safe to call often; does not touch miner network unless identity already cached.
    """
    router_brief: dict = {}
    try:
        r = _collect_router_info()
        router_brief = {
            "vendor": r.get("vendor"),
            "model": r.get("model"),
            "model_code": r.get("model_code"),
            "hostname": r.get("hostname"),
            "os_title": r.get("os_title"),
            "os_release": r.get("os_release"),
            "arch": r.get("arch"),
            "hw_version": r.get("hw_version"),
            "source": r.get("source"),
        }
    except Exception as e:
        router_brief = {"error": str(e)}

    miner_type = None
    miner_sn = None
    try:
        # disk / RAM identity cache only — no live fetch
        mem = None
        try:
            mem = _IDENT_CACHE.get("data") if isinstance(_IDENT_CACHE, dict) else None
        except NameError:
            mem = None
        disk = None
        try:
            disk = _load_miner_id_disk()
        except Exception:
            disk = None
        src = mem if isinstance(mem, dict) and (mem.get("miner_type") or mem.get("minersn")) else disk
        if isinstance(src, dict):
            miner_type = src.get("miner_type") or src.get("model")
            miner_sn = src.get("minersn") or src.get("miner_sn")
    except Exception:
        pass

    try:
        uname = os.uname()
        host_os = {
            "sysname": uname.sysname,
            "release": uname.release,
            "machine": uname.machine,
            "nodename": uname.nodename,
        }
    except Exception:
        host_os = {}

    return {
        "app_version": get_app_version(),
        "github_repo": GITHUB_REPO,
        "github_branch": GITHUB_BRANCH,
        "project_name": get_project_name(),
        "updated_at": datetime.now().isoformat(timespec="seconds"),
        "router": router_brief,
        "miner": {
            "host": HOST_MINER,
            "port": int(PORT_MINER),
            "type": miner_type,
            "sn": miner_sn,
        },
        "paths": {
            "config": str(_miner_config_path()),
            "data": str(DATA),
            "www": str(ROOT),
            "db": str(DB_FILE),
        },
        "bind": f"{HTTP_BIND}:{HTTP_PORT}",
        "dry_run": bool(DRY_RUN),
        "host_os": host_os,
    }


def refresh_config_meta(*, include_router: bool = True) -> dict:
    """
    Overwrite config.json → meta with current host/software facts.
    Called on service start and before backup download. User settings untouched.
    """
    meta = build_runtime_meta() if include_router else {
        "app_version": get_app_version(),
        "updated_at": datetime.now().isoformat(timespec="seconds"),
        "project_name": get_project_name(),
        "miner": {"host": HOST_MINER, "port": int(PORT_MINER)},
        "paths": {
            "config": str(_miner_config_path()),
            "data": str(DATA),
            "www": str(ROOT),
        },
        "bind": f"{HTTP_BIND}:{HTTP_PORT}",
        "dry_run": bool(DRY_RUN),
    }
    path = _miner_config_path()
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        existing = _read_json_file(path) or {}
        existing[_CONFIG_META_KEY] = meta
        # also mirror version at top-level for quick glance
        existing["app_version"] = meta.get("app_version")
        path.write_text(
            json.dumps(existing, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
    except Exception as e:
        print(f"[config] meta refresh: {e}")
        meta["_write_error"] = str(e)
    return meta


def build_config_backup() -> dict:
    """
    Full settings snapshot for download.
    Includes secrets (API password, TG token, filtration passwords) so restore works.
    Does not include history.db / runtime caches / policy events.
    Refreshes host meta into config.json first.
    """
    meta = refresh_config_meta(include_router=True)

    app_path = _miner_config_path()
    app_file = _read_json_file(app_path) or {}
    # ensure runtime miner keys present even if file is sparse
    ms = get_miner_settings()
    app_merged = dict(app_file)
    for k in (
        "miner_host",
        "miner_port",
        "api_password",
        "poll_interval_sec",
        "dry_run",
        "project_name",
        "bind",
        "http_port",
    ):
        if k not in app_merged and k in ms:
            app_merged[k] = ms[k]
        if k in ("miner_host", "miner_port", "api_password", "poll_interval_sec", "dry_run", "project_name"):
            app_merged[k] = ms.get(k, app_merged.get(k))
    app_merged[_CONFIG_META_KEY] = meta
    app_merged["app_version"] = meta.get("app_version")

    with _hist_cfg_lock:
        history = dict(_hist_cfg)
    logs = get_logs_cfg()
    sensors = get_sensors_cfg()
    devices = get_devices_cfg(redact=False)
    devices.pop("backends", None)
    devices.pop("reserved_aliases", None)
    devices.pop("icons", None)
    devices.pop("tuya_ecosystems", None)
    # backup = settings only (runtime lives in devices_state.json, not portable)
    if isinstance(devices.get("devices"), list):
        devices["devices"] = [
            _strip_device_runtime(d) for d in devices["devices"] if isinstance(d, dict)
        ]
    with _weather_cfg_lock:
        weather = dict(_weather_cfg)
    with _energy_cfg_lock:
        energy = dict(_energy_cfg)
    with _pool_cfg_lock:
        pool = dict(_pool_cfg)

    zone = get_zone_cfg()
    with _zone_presets_lock:
        zone_presets = json.loads(json.dumps(_zone_presets))

    filtration = get_filtration_cfg(redact=False)
    filtration.pop("backends", None)
    chipmap = get_chipmap_cfg(redact=False)
    with _luci_proxy_cfg_lock:
        luci_proxy_cfg = dict(_luci_proxy_cfg)
    with _sniffer_cfg_lock:
        sniffer_cfg = dict(_sniffer_cfg)
    telegram = get_telegram_cfg(redact=False)
    telegram.pop("status", None)
    with _pool_presets_lock:
        pool_presets = json.loads(json.dumps(_pool_presets))

    return {
        "format": CONFIG_BACKUP_FORMAT,
        "version": CONFIG_BACKUP_VERSION,
        "app_version": meta.get("app_version") or get_app_version(),
        "exported_at": datetime.now().isoformat(timespec="seconds"),
        "project_name": get_project_name(),
        "meta": meta,
        "configs": {
            "app": app_merged,
            "history": history,
            "logs": logs,
            "sensors": sensors,
            "devices": devices,
            "weather": weather,
            "energy": energy,
            "pool": pool,
            "zone_map": zone,
            "zone_presets": zone_presets,
            "pool_presets": pool_presets,
            "filtration": filtration,
            "chipmap": chipmap,
            "luci_proxy": luci_proxy_cfg,
            "sniffer": sniffer_cfg,
            "telegram": telegram,
        },
        "notes": (
            "Restore via UI Settings → Backup or POST /api/config/restore. "
            "Contains secrets (API password, Telegram token, filtration passwords). "
            "meta / app_version are host facts — rewritten on each service start. "
            "sniffer module files are not in the backup — re-download on enable."
        ),
    }


def restore_config_backup(payload: dict, *, sections: list[str] | None = None) -> dict:
    """
    Apply backup bundle. `sections` optional filter of configs keys;
    default = all present sections.
    """
    if not isinstance(payload, dict):
        raise ValueError("expected JSON object")
    # accept raw {configs:{…}} or full backup wrapper or single legacy flat
    if payload.get("format") == CONFIG_BACKUP_FORMAT or "configs" in payload:
        cfgs = payload.get("configs")
        if not isinstance(cfgs, dict):
            raise ValueError("missing configs object")
    else:
        # allow paste of single config.json as app only
        if any(k in payload for k in ("miner_host", "api_password", "project_name")):
            cfgs = {"app": payload}
        else:
            raise ValueError(
                "unknown backup format (need format=poolheat_config_backup or configs{})"
            )

    want = set(sections) if sections else set(cfgs.keys())
    applied: list[str] = []
    errors: dict[str, str] = {}

    # 1) app / miner config
    if "app" in want and isinstance(cfgs.get("app"), dict):
        try:
            app = dict(cfgs["app"])
            # never restore stale host meta from another machine
            app.pop(_CONFIG_META_KEY, None)
            app.pop("app_version", None)
            apply_miner_settings(
                host=app.get("miner_host"),
                port=app.get("miner_port"),
                password=app.get("api_password"),
                poll_interval_sec=app.get("poll_interval_sec"),
                dry_run=app.get("dry_run") if "dry_run" in app else None,
                project_name=app.get("project_name"),
                persist=True,
            )
            # preserve extra keys (bind, http_port, force_stop, …)
            path = _miner_config_path()
            path.parent.mkdir(parents=True, exist_ok=True)
            existing = _read_json_file(path) or {}
            for k, v in app.items():
                if k in (
                    "miner_host",
                    "miner_port",
                    "api_password",
                    "poll_interval_sec",
                    "dry_run",
                    "project_name",
                    _CONFIG_META_KEY,
                    "app_version",
                ):
                    continue  # already applied / host facts
                existing[k] = v
            # re-apply runtime keys on top
            ms = get_miner_settings()
            for k in (
                "miner_host",
                "miner_port",
                "api_password",
                "poll_interval_sec",
                "dry_run",
                "project_name",
            ):
                existing[k] = ms.get(k)
            path.write_text(
                json.dumps(existing, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
            applied.append("app")
        except Exception as e:
            errors["app"] = str(e)

    # 2) history
    if "history" in want and isinstance(cfgs.get("history"), dict):
        try:
            req = cfgs["history"]
            with _hist_cfg_lock:
                if "enabled" in req:
                    _hist_cfg["enabled"] = bool(req["enabled"])
                if "retention_days" in req:
                    _hist_cfg["retention_days"] = max(
                        1, min(90, int(req["retention_days"]))
                    )
                if "sample_interval_sec" in req:
                    _hist_cfg["sample_interval_sec"] = max(
                        5, min(3600, int(req["sample_interval_sec"]))
                    )
            _save_hist_cfg()
            applied.append("history")
        except Exception as e:
            errors["history"] = str(e)

    # 2b) logs depth (error log + event/action log)
    if "logs" in want and isinstance(cfgs.get("logs"), dict):
        try:
            apply_logs_cfg(cfgs["logs"])
            applied.append("logs")
        except Exception as e:
            errors["logs"] = str(e)

    # 2c) virtual / alias sensors
    if "sensors" in want and isinstance(cfgs.get("sensors"), dict):
        try:
            sl = cfgs["sensors"].get("sensors")
            if isinstance(sl, list):
                replace_sensors(sl)
            applied.append("sensors")
        except Exception as e:
            errors["sensors"] = str(e)

    # 2d) peripherals devices (actuators)
    if "devices" in want and isinstance(cfgs.get("devices"), dict):
        try:
            dl = cfgs["devices"].get("devices")
            if isinstance(dl, list):
                replace_devices(dl)
            applied.append("devices")
        except Exception as e:
            errors["devices"] = str(e)

    # 3) weather
    if "weather" in want and isinstance(cfgs.get("weather"), dict):
        try:
            req = cfgs["weather"]
            with _weather_cfg_lock:
                for k, v in req.items():
                    if k in (
                        "enabled",
                        "city",
                        "country",
                        "admin1",
                        "timezone",
                        "latitude",
                        "longitude",
                        "refresh_interval_sec",
                    ):
                        _weather_cfg[k] = v
                if "enabled" in req:
                    _weather_cfg["enabled"] = bool(req["enabled"])
                if "latitude" in req and req["latitude"] is not None:
                    _weather_cfg["latitude"] = float(req["latitude"])
                if "longitude" in req and req["longitude"] is not None:
                    _weather_cfg["longitude"] = float(req["longitude"])
            _save_weather_cfg()
            applied.append("weather")
        except Exception as e:
            errors["weather"] = str(e)

    # 3b) energy tariff
    if "energy" in want and isinstance(cfgs.get("energy"), dict):
        try:
            set_energy_cfg(cfgs["energy"])
            applied.append("energy")
        except Exception as e:
            errors["energy"] = str(e)

    # 4) pool
    if "pool" in want and isinstance(cfgs.get("pool"), dict):
        try:
            req = cfgs["pool"]
            with _pool_cfg_lock:
                for key in (
                    "length_m",
                    "width_m",
                    "depth_m",
                    "flow_m3h",
                    "shape",
                    "water_sensor",
                ):
                    if key in req and req[key] is not None:
                        if key == "water_sensor":
                            _pool_cfg[key] = _normalize_pool_water_sensor(req[key])
                        elif key == "shape":
                            _pool_cfg[key] = str(req[key])
                        else:
                            _pool_cfg[key] = float(req[key])
                # legacy keys no longer used
                _pool_cfg.pop("hex_delta_c", None)
                _pool_cfg.pop("comment", None)
            _save_pool_cfg()
            applied.append("pool")
        except Exception as e:
            errors["pool"] = str(e)

    # 5) zone map
    if "zone_map" in want and isinstance(cfgs.get("zone_map"), dict):
        try:
            cfg = _coerce_zone_config_dict(cfgs["zone_map"])
            with _zone_cfg_lock:
                _zone_cfg.clear()
                _zone_cfg.update(cfg)
            _save_zone_cfg()
            applied.append("zone_map")
        except Exception as e:
            errors["zone_map"] = str(e)

    # 6) zone presets
    if "zone_presets" in want and isinstance(cfgs.get("zone_presets"), dict):
        try:
            global _zone_presets
            raw = cfgs["zone_presets"]
            with _zone_presets_lock:
                _zone_presets = {
                    "presets": list(raw.get("presets") or []),
                    "active_id": raw.get("active_id"),
                }
            _save_zone_presets()
            # re-normalize via loader
            _load_zone_presets()
            applied.append("zone_presets")
        except Exception as e:
            errors["zone_presets"] = str(e)

    # 6b) mining pool presets
    if "pool_presets" in want and isinstance(cfgs.get("pool_presets"), dict):
        try:
            global _pool_presets
            raw = cfgs["pool_presets"]
            with _pool_presets_lock:
                _pool_presets = {
                    "presets": list(raw.get("presets") or []),
                    "active_id": raw.get("active_id"),
                }
            _save_pool_presets()
            _load_pool_presets()
            applied.append("pool_presets")
        except Exception as e:
            errors["pool_presets"] = str(e)

    # 7) filtration
    if "filtration" in want and isinstance(cfgs.get("filtration"), dict):
        try:
            apply_filtration_cfg(cfgs["filtration"])
            applied.append("filtration")
        except Exception as e:
            errors["filtration"] = str(e)

    # 8) chipmap
    if "chipmap" in want and isinstance(cfgs.get("chipmap"), dict):
        try:
            apply_chipmap_cfg(cfgs["chipmap"])
            applied.append("chipmap")
        except Exception as e:
            errors["chipmap"] = str(e)

    # 8b) luci proxy
    if "luci_proxy" in want and isinstance(cfgs.get("luci_proxy"), dict):
        try:
            apply_luci_proxy_cfg(cfgs["luci_proxy"])
            applied.append("luci_proxy")
        except Exception as e:
            errors["luci_proxy"] = str(e)

    # 8b) sniffer (settings only; module re-downloaded on enable if missing)
    if "sniffer" in want and isinstance(cfgs.get("sniffer"), dict):
        try:
            apply_sniffer_cfg(cfgs["sniffer"])
            applied.append("sniffer")
        except Exception as e:
            errors["sniffer"] = str(e)

    # 9) telegram
    if "telegram" in want and isinstance(cfgs.get("telegram"), dict):
        try:
            req = cfgs["telegram"]
            with _tg_cfg_lock:
                for k, v in req.items():
                    if k in ("status", "bot_token_set"):
                        continue
                    if k == "bot_token" and isinstance(v, str) and (
                        "…" in v or v.startswith("••••")
                    ):
                        continue  # skip redacted
                    _tg_cfg[k] = v
                if "enabled" in req:
                    _tg_cfg["enabled"] = bool(req["enabled"])
            _save_telegram_cfg(force=True)
            applied.append("telegram")
        except Exception as e:
            errors["telegram"] = str(e)

    if not applied and errors:
        raise RuntimeError("restore failed: " + "; ".join(f"{k}: {v}" for k, v in errors.items()))
    if not applied:
        raise ValueError("nothing to restore (empty sections)")

    # always rewrite host meta after restore (this machine, current version)
    try:
        meta = refresh_config_meta(include_router=True)
    except Exception as e:
        meta = {"error": str(e)}

    return {
        "ok": True,
        "applied": applied,
        "errors": errors or None,
        "app_version": get_app_version(),
        "meta": meta,
    }


