def publish_live_snapshot(live: dict | None) -> None:
    """
    Update in-process RAM cache and write live_cache.json for other processes
    (UI/API, devices poller mining_work consumers).
    """
    global _cache, _cache_ts
    if not isinstance(live, dict):
        return
    now = time.time()
    with _cache_lock:
        _cache = live
        _cache_ts = now
    try:
        payload = {
            "ts": now,
            "live": live,
            "host": f"{HOST_MINER}:{PORT_MINER}",
            "pid": os.getpid(),
        }
        LIVE_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = LIVE_CACHE_FILE.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
        tmp.replace(LIVE_CACHE_FILE)
    except Exception as e:
        print(f"[live-cache] write: {e}", flush=True)


def hydrate_live_from_disk(*, max_age_sec: float | None = None) -> dict | None:
    """
    Load live_cache.json into RAM if fresh enough. Returns live dict or None.
    Used by UI process when ASIC poller runs out-of-process.
    """
    global _cache, _cache_ts
    max_age = (
        float(LIVE_DISK_MAX_AGE_SEC)
        if max_age_sec is None
        else float(max_age_sec)
    )
    try:
        if not LIVE_CACHE_FILE.is_file():
            return None
        raw = json.loads(LIVE_CACHE_FILE.read_text(encoding="utf-8"))
        if not isinstance(raw, dict):
            return None
        ts = float(raw.get("ts") or 0)
        if ts <= 0 or (time.time() - ts) > max_age:
            return None
        live = raw.get("live")
        if not isinstance(live, dict) or not live.get("ok"):
            return None
        with _cache_lock:
            # only replace if disk is newer than RAM
            if ts >= float(_cache_ts or 0):
                _cache = live
                _cache_ts = ts
        return dict(live)
    except Exception:
        return None



def live_snapshot(*, max_age_sec: float | None = None, allow_direct: bool = False) -> dict:
    """
    Live data for serve logic: only live_cache.json from miner-poller.
    ``allow_direct`` is ignored (ASIC TCP is poller-only).
    """
    _ = allow_direct  # deprecated — never open ASIC from serve
    age = float(LIVE_DISK_MAX_AGE_SEC if max_age_sec is None else max_age_sec)
    live = hydrate_live_from_disk(max_age_sec=age)
    if isinstance(live, dict) and live.get("ok"):
        return live
    with _cache_lock:
        if isinstance(_cache, dict) and _cache.get("ok"):
            return dict(_cache)
    raise RuntimeError("no live snapshot (miner-poller / live_cache)")


def miner_poller_process_alive() -> bool:
    """True if miner-poller is live (pidfile, /proc scan, or fresh live_cache)."""
    me = os.getpid()
    try:
        if MINER_POLLER_PIDFILE.is_file():
            raw = MINER_POLLER_PIDFILE.read_text(encoding="utf-8").strip()
            # tolerate "12345\n" or "12345 extra"
            pid_s = (raw.split() or ["0"])[0]
            pid = int(pid_s or "0")
            if pid > 0 and pid != me and _pid_alive(pid):
                return True
    except Exception:
        pass
    try:
        if _find_pids_by_name(
            "poolheat-miner-poller",
            "serve.py --miner-poller",
            "serve.py --asic-poller",
            "miner-poller",
        ):
            return True
    except Exception:
        pass
    # Soft signal: poller writes live_cache.json every few seconds.
    # Helps when pidfile is stale/missing but Go poller is still working
    # (manual start, crash-loop respawn, dual poolheatd).
    try:
        if LIVE_CACHE_FILE.is_file():
            age = time.time() - float(LIVE_CACHE_FILE.stat().st_mtime)
            if age <= 45.0:
                return True
    except Exception:
        pass
    return False

