def devices_poller_process_alive() -> bool:
    """True if devices-poller is live (pidfile or /proc scan)."""
    me = os.getpid()
    try:
        if DEVICES_POLLER_PIDFILE.is_file():
            pid = int((DEVICES_POLLER_PIDFILE.read_text(encoding="utf-8") or "").strip() or "0")
            if pid > 0 and pid != me and _pid_alive(pid):
                return True
    except Exception:
        pass
    try:
        return bool(
            _find_pids_by_name(
                "poolheat-devices-poller",
                "serve.py --devices-poller",
            )
        )
    except Exception:
        return False


def _load_json(path: Path, default: dict | None = None) -> dict:
    """Load JSON object from path; missing/invalid → copy of default (or {})."""
    base = dict(default) if isinstance(default, dict) else {}
    if path.exists():
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return {**base, **data}
        except Exception:
            pass
    return base


def _save_json(path: Path, data: dict) -> None:
    try:
        path.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass


def _load_state() -> None:
    global _state
    _state.update(_load_json(STATE_FILE, _state))


def _save_state() -> None:
    _save_json(STATE_FILE, _state)


def _load_hist_cfg() -> None:
    global _hist_cfg
    with _hist_cfg_lock:
        _hist_cfg = _load_json(CONFIG_FILE, DEFAULT_HISTORY_CFG)
        # clamp
        _hist_cfg["retention_days"] = max(1, min(90, int(_hist_cfg["retention_days"])))
        _hist_cfg["sample_interval_sec"] = max(5, min(3600, int(_hist_cfg["sample_interval_sec"])))
        _hist_cfg["enabled"] = bool(_hist_cfg["enabled"])


def _clamp_error_log_max(v) -> int:
    try:
        n = int(v)
    except (TypeError, ValueError):
        n = MINER_ERROR_LOG_MAX_DEFAULT
    return max(ERROR_LOG_MAX_MIN, min(ERROR_LOG_MAX_CEIL, n))


def _clamp_event_log_max(v) -> int:
    try:
        n = int(v)
    except (TypeError, ValueError):
        n = POLICY_EVENTS_MAX_DEFAULT
    return max(EVENT_LOG_MAX_MIN, min(EVENT_LOG_MAX_CEIL, n))


def _load_logs_cfg() -> None:
    """Load error/event log depth limits from DATA/logs_config.json."""
    global _logs_cfg, MINER_ERROR_LOG_MAX, POLICY_EVENTS_MAX
    with _logs_cfg_lock:
        raw = _load_json(LOGS_CFG_FILE, DEFAULT_LOGS_CFG)
        if not isinstance(raw, dict):
            raw = {}
        cfg = dict(DEFAULT_LOGS_CFG)
        cfg["error_log_max"] = _clamp_error_log_max(
            raw.get("error_log_max", DEFAULT_LOGS_CFG["error_log_max"])
        )
        cfg["event_log_max"] = _clamp_event_log_max(
            raw.get("event_log_max", DEFAULT_LOGS_CFG["event_log_max"])
        )
        _logs_cfg = cfg
        MINER_ERROR_LOG_MAX = cfg["error_log_max"]
        POLICY_EVENTS_MAX = cfg["event_log_max"]


def _save_logs_cfg() -> None:
    with _logs_cfg_lock:
        _save_json(LOGS_CFG_FILE, dict(_logs_cfg))


def get_logs_cfg() -> dict:
    with _logs_cfg_lock:
        return dict(_logs_cfg)


def get_error_log_max() -> int:
    with _logs_cfg_lock:
        return int(_logs_cfg.get("error_log_max") or MINER_ERROR_LOG_MAX_DEFAULT)


def get_event_log_max() -> int:
    with _logs_cfg_lock:
        return int(_logs_cfg.get("event_log_max") or POLICY_EVENTS_MAX_DEFAULT)


def prune_miner_error_log(max_rows: int | None = None) -> int:
    """Keep only last max_rows in miner_error_log. Returns deleted count."""
    mx = get_error_log_max() if max_rows is None else _clamp_error_log_max(max_rows)
    with _db_lock:
        conn = _db_connect()
        try:
            before = conn.execute("SELECT COUNT(*) FROM miner_error_log").fetchone()[0]
            conn.execute(
                """
                DELETE FROM miner_error_log
                WHERE id NOT IN (
                    SELECT id FROM miner_error_log
                    ORDER BY seen_ts DESC, id DESC
                    LIMIT ?
                )
                """,
                (mx,),
            )
            conn.commit()
            after = conn.execute("SELECT COUNT(*) FROM miner_error_log").fetchone()[0]
            return max(0, int(before) - int(after))
        finally:
            conn.close()


def apply_logs_cfg(req: dict | None = None) -> dict:
    """
    Update log depth settings, persist, prune both logs to new limits.
    Returns {config, pruned_errors, pruned_events}.
    """
    global MINER_ERROR_LOG_MAX, POLICY_EVENTS_MAX
    req = req if isinstance(req, dict) else {}
    with _logs_cfg_lock:
        if "error_log_max" in req and req["error_log_max"] is not None:
            _logs_cfg["error_log_max"] = _clamp_error_log_max(req["error_log_max"])
        if "event_log_max" in req and req["event_log_max"] is not None:
            _logs_cfg["event_log_max"] = _clamp_event_log_max(req["event_log_max"])
        cfg = dict(_logs_cfg)
        MINER_ERROR_LOG_MAX = cfg["error_log_max"]
        POLICY_EVENTS_MAX = cfg["event_log_max"]
    _save_logs_cfg()

    pruned_errors = 0
    try:
        pruned_errors = prune_miner_error_log(cfg["error_log_max"])
    except Exception as e:
        print(f"[logs] prune error log: {e}")

    pruned_events = 0
    try:
        mx = int(cfg["event_log_max"])
        with _policy_lock:
            evs = list(_policy_ctrl.get("events") or [])
            if len(evs) > mx:
                pruned_events = len(evs) - mx
                _policy_ctrl["events"] = evs[:mx]
                if _policy_ctrl["events"]:
                    _policy_ctrl["last_event"] = _policy_ctrl["events"][0]
                else:
                    _policy_ctrl["last_event"] = None
        if pruned_events:
            _save_policy_events()
        else:
            # still rewrite max field on disk
            _save_policy_events()
    except Exception as e:
        print(f"[logs] prune event log: {e}")

    return {
        "config": cfg,
        "pruned_errors": pruned_errors,
        "pruned_events": pruned_events,
    }


# ─── Virtual / alias sensors (Peripherals) ────────────────────────────────────
#
# A sensor has a system ``alias`` (e.g. outdoor, pool_water) and optional
# priority sources; each source may carry its own transform:
#   sources: [ {type:live|weather|sensor|const, …, transform?: …}, … ]
#     first valid source wins; its transform is applied
#   transform (legacy, sensor-level): migrated onto first source on load/save
#     none | offset | power_delta_table
#     offset: value + offset  (Δ can be negative)
#     power_delta_table: value + delta(power) from a W→Δ°C table
#       positive Δ adds, negative Δ subtracts
#
DEFAULT_SENSORS_CFG: dict = {"version": 1, "sensors": []}

# Live fields that can be bound as sources
SENSOR_LIVE_FIELDS: tuple[str, ...] = (
    "liquid",
    "env",
    "chip_min",
    "chip_avg",
    "chip_max",
    "board_max",
    "power",  # W — also used by power_delta_table
    "freq_avg",
    "hashrate_th",
)
SENSOR_WEATHER_FIELDS: tuple[str, ...] = (
    "temp_c",
    "feels_like_c",
    "humidity",
    "wind_ms",
    "pressure_hpa",
)

_sensors_cfg_lock = threading.Lock()
_sensors_cfg: dict = dict(DEFAULT_SENSORS_CFG)


def _sensor_alias_ok(alias: str) -> bool:
    a = str(alias or "").strip().lower()
    return bool(re.fullmatch(r"[a-z][a-z0-9_]{0,47}", a))


def _new_sensor_id() -> str:
    return "s_" + uuid.uuid4().hex[:12]


def _normalize_sensor_source(raw: dict | None) -> dict | None:
    if not isinstance(raw, dict):
        return None
    typ = str(raw.get("type") or "").strip().lower()
    out: dict | None = None
    if typ in ("live", "miner", "asic"):
        field = str(raw.get("field") or "liquid").strip().lower()
        if field not in SENSOR_LIVE_FIELDS:
            field = "liquid"
        out = {"type": "live", "field": field}
    elif typ in ("weather", "wx", "outdoor_api"):
        field = str(raw.get("field") or "temp_c").strip().lower()
        if field not in SENSOR_WEATHER_FIELDS:
            field = "temp_c"
        out = {"type": "weather", "field": field}
    elif typ in ("sensor", "alias", "ref"):
        ref = str(raw.get("alias") or raw.get("ref") or "").strip().lower()
        if not _sensor_alias_ok(ref):
            return None
        out = {"type": "sensor", "alias": ref}
    elif typ in ("const", "constant", "fixed"):
        try:
            v = float(raw.get("value"))
        except (TypeError, ValueError):
            return None
        out = {"type": "const", "value": v}
    if out is None:
        return None
    # Per-source transform (optional). Legacy sensors may only have top-level transform.
    xf = raw.get("transform")
    if isinstance(xf, dict) and xf:
        out["transform"] = _normalize_sensor_transform(xf)
    else:
        out["transform"] = {"type": "none"}
    return out


def _normalize_sensor_transform(raw: dict | None) -> dict:
    if not isinstance(raw, dict):
        return {"type": "none"}
    typ = str(raw.get("type") or "none").strip().lower()
    if typ in ("", "none", "identity", "passthrough"):
        return {"type": "none"}
    if typ in ("offset", "fixed_offset", "delta_fixed"):
        try:
            off = float(raw.get("offset", 0) or 0)
        except (TypeError, ValueError):
            off = 0.0
        return {"type": "offset", "offset": off}
    if typ in ("power_delta_table", "power_table", "kw_delta", "power_delta"):
        table_in = raw.get("table") or raw.get("points") or []
        table: list[dict] = []
        if isinstance(table_in, list):
            for p in table_in:
                if not isinstance(p, dict):
                    continue
                try:
                    # accept power_w or power_kw
                    if p.get("power_w") is not None:
                        pw = float(p.get("power_w"))
                    elif p.get("power_kw") is not None:
                        pw = float(p.get("power_kw")) * 1000.0
                    elif p.get("power") is not None:
                        pw = float(p.get("power"))
                        if pw < 50:  # likely kW
                            pw *= 1000.0
                    else:
                        continue
                    delta = float(p.get("delta") if p.get("delta") is not None else p.get("offset"))
                except (TypeError, ValueError):
                    continue
                table.append({"power_w": max(0.0, pw), "delta": delta})
        table.sort(key=lambda x: x["power_w"])
        return {
            "type": "power_delta_table",
            "table": table,
            "interpolate": bool(raw.get("interpolate", True)),
            "power_field": "power",
        }
    return {"type": "none"}


def _normalize_sensor_names(raw: dict, alias: str) -> tuple[str, str, str]:
    """
    Bilingual display names.

    Accepts ``name_en`` / ``name_ru`` and legacy ``name``.
    If only one language is set, the other is auto-filled from it.
    Returns (name_en, name_ru, name) where ``name`` is a default fallback
    (EN preferred, then RU, then alias).
    """
    en = str(raw.get("name_en") or "").strip()
    ru = str(raw.get("name_ru") or "").strip()
    legacy = str(raw.get("name") or "").strip()
    if not en and not ru:
        if legacy:
            en = ru = legacy
        else:
            en = ru = alias
    elif en and not ru:
        ru = en
    elif ru and not en:
        en = ru
    # keep lengths sane
    en = (en or alias)[:80]
    ru = (ru or en or alias)[:80]
    name = en or ru or alias
    return en, ru, name


def _normalize_sensor(raw: dict | None) -> dict | None:
    if not isinstance(raw, dict):
        return None
    alias = str(raw.get("alias") or "").strip().lower()
    if not _sensor_alias_ok(alias):
        return None
    sid = str(raw.get("id") or "").strip() or _new_sensor_id()
    name_en, name_ru, name = _normalize_sensor_names(raw, alias)
    unit = str(raw.get("unit") or "°C").strip() or "°C"
    enabled = bool(raw.get("enabled", True))
    # Telegram /status card — show this sensor under temperatures
    show_in_status = _as_bool(
        raw.get("show_in_status", raw.get("status_in_bot", False))
    )
    # Persist samples to history.db (sensor_samples) for charts / export
    history = _as_bool(
        raw.get(
            "history",
            raw.get(
                "save_history",
                raw.get("collect_history", raw.get("record_history", False)),
            ),
        )
    )
    sources_raw = raw.get("sources")
    if not isinstance(sources_raw, list):
        sources_raw = []
    sources: list[dict] = []
    for s in sources_raw:
        ns = _normalize_sensor_source(s)
        if ns:
            sources.append(ns)
    # legacy single source
    if not sources and raw.get("source"):
        ns = _normalize_sensor_source(raw.get("source"))
        if ns:
            sources.append(ns)
    if not sources:
        # default: live liquid (harmless placeholder)
        sources = [{"type": "live", "field": "liquid", "transform": {"type": "none"}}]
    # Migrate legacy sensor-level transform onto first source if no source has one
    legacy_xf = _normalize_sensor_transform(raw.get("transform"))
    if legacy_xf.get("type") and legacy_xf.get("type") != "none":
        has_src_xf = any(
            isinstance(s.get("transform"), dict)
            and (s.get("transform") or {}).get("type") not in (None, "", "none")
            for s in sources
        )
        if not has_src_xf and sources:
            sources[0] = dict(sources[0])
            sources[0]["transform"] = legacy_xf
    return {
        "id": sid,
        "alias": alias,
        "name": name,
        "name_en": name_en,
        "name_ru": name_ru,
        "unit": unit,
        "enabled": enabled,
        "show_in_status": show_in_status,
        "history": history,
        "sources": sources,
        "note": str(raw.get("note") or "")[:500],
    }


def _load_sensors_cfg() -> None:
    global _sensors_cfg
    with _sensors_cfg_lock:
        raw = _load_json(SENSORS_CFG_FILE, DEFAULT_SENSORS_CFG)
        if not isinstance(raw, dict):
            raw = {}
        sensors_in = raw.get("sensors") if isinstance(raw.get("sensors"), list) else []
        clean: list[dict] = []
        seen_alias: set[str] = set()
        for s in sensors_in:
            ns = _normalize_sensor(s)
            if not ns:
                continue
            if ns["alias"] in seen_alias:
                continue
            seen_alias.add(ns["alias"])
            clean.append(ns)
        _sensors_cfg = {"version": 1, "sensors": clean}


def _save_sensors_cfg() -> None:
    with _sensors_cfg_lock:
        _save_json(SENSORS_CFG_FILE, dict(_sensors_cfg))


def get_sensors_cfg() -> dict:
    with _sensors_cfg_lock:
        return json.loads(json.dumps(_sensors_cfg))


def list_sensors() -> list[dict]:
    with _sensors_cfg_lock:
        return json.loads(json.dumps(_sensors_cfg.get("sensors") or []))


def get_sensor_by_id(sid: str) -> dict | None:
    sid = str(sid or "").strip()
    for s in list_sensors():
        if s.get("id") == sid:
            return s
    return None


def get_sensor_by_alias(alias: str) -> dict | None:
    a = str(alias or "").strip().lower()
    for s in list_sensors():
        if s.get("alias") == a:
            return s
    return None


def upsert_sensor(raw: dict) -> dict:
    """Create or update a sensor. Requires unique alias."""
    ns = _normalize_sensor(raw)
    if not ns:
        raise ValueError("invalid sensor (alias: a-z, a-z0-9_, max 48)")
    with _sensors_cfg_lock:
        sensors = list(_sensors_cfg.get("sensors") or [])
        idx = next((i for i, s in enumerate(sensors) if s.get("id") == ns["id"]), None)
        # alias uniqueness
        for s in sensors:
            if s.get("alias") == ns["alias"] and s.get("id") != ns["id"]:
                raise ValueError(f"alias already used: {ns['alias']}")
        if idx is None:
            sensors.append(ns)
        else:
            sensors[idx] = ns
        _sensors_cfg["sensors"] = sensors
    _save_sensors_cfg()
    return ns


def delete_sensor(sid: str) -> bool:
    sid = str(sid or "").strip()
    with _sensors_cfg_lock:
        sensors = list(_sensors_cfg.get("sensors") or [])
        new = [s for s in sensors if s.get("id") != sid]
        if len(new) == len(sensors):
            return False
        _sensors_cfg["sensors"] = new
    _save_sensors_cfg()
    return True


def replace_sensors(sensors_list: list) -> list[dict]:
    clean: list[dict] = []
    seen: set[str] = set()
    for s in sensors_list or []:
        ns = _normalize_sensor(s)
        if not ns or ns["alias"] in seen:
            continue
        seen.add(ns["alias"])
        clean.append(ns)
    with _sensors_cfg_lock:
        _sensors_cfg["sensors"] = clean
    _save_sensors_cfg()
    return clean


def reorder_sensors(ids: list) -> list[dict]:
    """
    Reorder sensors by id list. Unknown ids ignored; any missing sensors
    stay at the end in previous relative order.
    """
    want = [str(i).strip() for i in (ids or []) if str(i).strip()]
    with _sensors_cfg_lock:
        sensors = list(_sensors_cfg.get("sensors") or [])
        by_id = {str(s.get("id")): s for s in sensors if s.get("id")}
        ordered: list[dict] = []
        seen: set[str] = set()
        for sid in want:
            if sid in by_id and sid not in seen:
                ordered.append(by_id[sid])
                seen.add(sid)
        for s in sensors:
            sid = str(s.get("id") or "")
            if sid and sid not in seen:
                ordered.append(s)
                seen.add(sid)
        _sensors_cfg["sensors"] = ordered
    _save_sensors_cfg()
    return list_sensors()


def _live_snapshot_for_sensors() -> dict:
    """Best-effort last live miner snapshot (no new TCP if cached)."""
    with _cache_lock:
        live = dict(_cache) if isinstance(_cache, dict) else {}
    return live


def _weather_snapshot_for_sensors() -> dict:
    try:
        # use cache / non-force path
        w = fetch_weather_current(force=False)
        return w if isinstance(w, dict) else {}
    except Exception:
        return {}


def _read_live_field(live: dict, field: str) -> float | None:
    field = str(field or "").strip().lower()
    if field == "board_max":
        boards = live.get("boards") or []
        vals: list[float] = []
        for b in boards:
            fb = _f(b)
            if fb is not None:
                vals.append(fb)
        return max(vals) if vals else None
    if field == "freq_avg":
        return _f(live.get("freq_avg") if live.get("freq_avg") is not None else live.get("freq"))
    return _f(live.get(field))


def _interpolate_power_delta(table: list[dict], power_w: float, interpolate: bool) -> float | None:
    if not table:
        return None
    if power_w <= table[0]["power_w"]:
        return float(table[0]["delta"])
    if power_w >= table[-1]["power_w"]:
        return float(table[-1]["delta"])
    for i in range(1, len(table)):
        a, b = table[i - 1], table[i]
        if power_w <= b["power_w"]:
            if not interpolate:
                # nearest lower
                return float(a["delta"])
            span = b["power_w"] - a["power_w"]
            if span <= 0:
                return float(b["delta"])
            t = (power_w - a["power_w"]) / span
            return float(a["delta"]) + t * (float(b["delta"]) - float(a["delta"]))
    return float(table[-1]["delta"])


def _apply_sensor_transform(
    value: float, transform: dict, live: dict
) -> tuple[float | None, str | None]:
    """Return (transformed value, note)."""
    typ = (transform or {}).get("type") or "none"
    if typ == "none":
        return value, None
    if typ == "offset":
        try:
            off = float(transform.get("offset") or 0)
        except (TypeError, ValueError):
            off = 0.0
        return value + off, f"offset {off:+g}"
    if typ == "power_delta_table":
        pw = _read_live_field(live, "power")
        if pw is None:
            return None, "no power for table"
        table = transform.get("table") or []
        delta = _interpolate_power_delta(
            table, float(pw), bool(transform.get("interpolate", True))
        )
        if delta is None:
            return None, "empty power table"
        # positive Δ adds, negative Δ subtracts
        return value + float(delta), f"Δ={float(delta):+g} @ {pw:.0f}W"
    return value, None


def evaluate_sensor(
    sensor: dict,
    *,
    live: dict | None = None,
    weather: dict | None = None,
    _stack: set[str] | None = None,
) -> dict:
    """
    Resolve sensor value via priority sources + transform.
    Returns {ok, value, unit, alias, source_used, note, error?}.
    """
    alias = str(sensor.get("alias") or "")
    unit = str(sensor.get("unit") or "°C")
    out: dict = {
        "ok": False,
        "value": None,
        "unit": unit,
        "alias": alias,
        "id": sensor.get("id"),
        "name": sensor.get("name") or alias,
        "name_en": sensor.get("name_en") or sensor.get("name") or alias,
        "name_ru": sensor.get("name_ru") or sensor.get("name") or alias,
        "enabled": bool(sensor.get("enabled", True)),
        "source_used": None,
        "note": None,
        "error": None,
    }
    if not sensor.get("enabled", True):
        out["error"] = "disabled"
        return out

    stack = set(_stack or set())
    if alias in stack:
        out["error"] = "cycle"
        return out
    stack.add(alias)

    live = live if isinstance(live, dict) else _live_snapshot_for_sensors()
    weather = weather if isinstance(weather, dict) else None

    raw_val: float | None = None
    source_used: dict | None = None

    for src in sensor.get("sources") or []:
        if not isinstance(src, dict):
            continue
        typ = src.get("type")
        v: float | None = None
        if typ == "live":
            v = _read_live_field(live, str(src.get("field") or "liquid"))
        elif typ == "weather":
            if weather is None:
                weather = _weather_snapshot_for_sensors()
            field = str(src.get("field") or "temp_c")
            if weather.get("enabled") is False:
                v = None
            elif weather.get("ok") or weather.get("stale"):
                v = _f(weather.get(field))
        elif typ == "const":
            v = _f(src.get("value"))
        elif typ == "sensor":
            ref = str(src.get("alias") or "")
            other = get_sensor_by_alias(ref)
            if other:
                ev = evaluate_sensor(
                    other, live=live, weather=weather, _stack=stack
                )
                if ev.get("ok"):
                    v = _f(ev.get("value"))
        if v is not None and math.isfinite(float(v)):
            raw_val = float(v)
            source_used = src
            break

    if raw_val is None:
        out["error"] = "no source"
        return out

    # Transform belongs to the winning source; fall back to legacy sensor-level
    transform = {"type": "none"}
    if isinstance(source_used, dict) and isinstance(source_used.get("transform"), dict):
        transform = source_used.get("transform") or {"type": "none"}
    elif isinstance(sensor.get("transform"), dict):
        transform = sensor.get("transform") or {"type": "none"}
    final, note = _apply_sensor_transform(raw_val, transform, live)
    if final is None or not math.isfinite(float(final)):
        out["error"] = note or "transform failed"
        out["source_used"] = source_used
        return out

    out["ok"] = True
    out["value"] = round(float(final), 3)
    out["raw"] = round(float(raw_val), 3)
    out["source_used"] = source_used
    out["note"] = note
    return out


def evaluate_all_sensors() -> dict[str, dict]:
    live = _live_snapshot_for_sensors()
    weather = _weather_snapshot_for_sensors()
    values: dict[str, dict] = {}
    for s in list_sensors():
        alias = s.get("alias") or s.get("id")
        values[str(alias)] = evaluate_sensor(s, live=live, weather=weather)
    return values


def sensors_catalog() -> dict:
    return {
        "live_fields": list(SENSOR_LIVE_FIELDS),
        "weather_fields": list(SENSOR_WEATHER_FIELDS),
        "transforms": ["none", "offset", "power_delta_table"],
        "source_types": ["live", "weather", "sensor", "const"],
    }


def _save_hist_cfg() -> None:
    with _hist_cfg_lock:
        _save_json(CONFIG_FILE, _hist_cfg)


def _weather_refresh_sec(cfg: dict | None = None) -> int:
    """Clamp weather refresh interval (seconds)."""
    c = cfg if isinstance(cfg, dict) else _weather_cfg
    try:
        sec = int(c.get("refresh_interval_sec") or WEATHER_CACHE_TTL_DEFAULT)
    except (TypeError, ValueError):
        sec = int(WEATHER_CACHE_TTL_DEFAULT)
    return max(60, min(86400, sec))


def _load_weather_cfg() -> None:
    global _weather_cfg
    with _weather_cfg_lock:
        _weather_cfg = _load_json(WEATHER_CFG_FILE, DEFAULT_WEATHER_CFG)
        _weather_cfg["enabled"] = bool(_weather_cfg.get("enabled", True))
        try:
            _weather_cfg["latitude"] = float(_weather_cfg.get("latitude", DEFAULT_WEATHER_CFG["latitude"]))
            _weather_cfg["longitude"] = float(_weather_cfg.get("longitude", DEFAULT_WEATHER_CFG["longitude"]))
        except (TypeError, ValueError):
            _weather_cfg["latitude"] = DEFAULT_WEATHER_CFG["latitude"]
            _weather_cfg["longitude"] = DEFAULT_WEATHER_CFG["longitude"]
        if not _weather_cfg.get("city"):
            _weather_cfg["city"] = DEFAULT_WEATHER_CFG["city"]
        _weather_cfg["refresh_interval_sec"] = _weather_refresh_sec(_weather_cfg)


def _save_weather_cfg() -> None:
    with _weather_cfg_lock:
        _save_json(WEATHER_CFG_FILE, _weather_cfg)


def _load_pool_cfg() -> None:
    global _pool_cfg
    with _pool_cfg_lock:
        _pool_cfg = _load_json(POOL_CFG_FILE, DEFAULT_POOL_CFG)
        for key, default in (
            ("length_m", 8.0),
            ("width_m", 4.0),
            ("depth_m", 1.5),
            ("flow_m3h", 12.0),
        ):
            try:
                v = float(_pool_cfg.get(key, default))
            except (TypeError, ValueError):
                v = default
            # sane clamps
            if key == "flow_m3h":
                v = max(0.0, min(500.0, v))
            else:
                v = max(0.1, min(200.0, v))
            _pool_cfg[key] = v
        shape = str(_pool_cfg.get("shape") or "rect").lower()
        if shape in ("round", "circular", "circle"):
            shape = "circle"
        elif shape in ("ellipse", "elliptic", "oval"):
            shape = "oval"
        else:
            shape = "rect"
        _pool_cfg["shape"] = shape
        # drop legacy HX / comment fields if present in old configs
        _pool_cfg.pop("hex_delta_c", None)
        _pool_cfg.pop("comment", None)
        _pool_cfg["water_sensor"] = _normalize_pool_water_sensor(
            _pool_cfg.get("water_sensor", "liquid")
        )


def _normalize_pool_water_sensor(v) -> str:
    """
    Pool water °C source:
      - built-in miner fields: liquid | env | chip_avg | chip_max | board_max
      - peripheral virtual sensors: sensor:<alias>  (Peripherals → Sensors)
    """
    raw = str(v or "liquid").strip()
    s = raw.lower().replace("-", "_").replace(" ", "_")
    # explicit virtual sensor reference
    for pref in ("sensor:", "sensors:", "alias:", "virt:", "virtual:"):
        if s.startswith(pref):
            alias = s.split(":", 1)[1].strip().lower()
            if _sensor_alias_ok(alias):
                return f"sensor:{alias}"
            return "liquid"
    # built-in map (same aliases as T_ctrl)
    aliases = {
        "liquid_temp": "liquid",
        "coolant": "liquid",
        "water": "liquid",
        "env_temp": "env",
        "ambient": "env",
        "environment": "env",
        "chip": "chip_max",
        "chipmax": "chip_max",
        "pcb": "board_max",
        "board": "board_max",
        "boards": "board_max",
        "pcb_max": "board_max",
    }
    s = aliases.get(s, s)
    if s in POOL_WATER_SENSORS:
        return s
    # bare alias of a configured peripheral sensor
    if _sensor_alias_ok(s):
        try:
            if get_sensor_by_alias(s) is not None:
                return f"sensor:{s}"
        except Exception:
            pass
        # allow storing alias even if not loaded yet (backup restore)
        return f"sensor:{s}"
    return "liquid"


def list_pool_water_sensor_options() -> list[dict]:
    """Options for Pool UI select: miner live fields + virtual sensors."""
    out: list[dict] = []
    labels = {
        "liquid": "liquid — ASIC liquid_temp (coolant)",
        "env": "env — Env Temp (ambient)",
        "chip_avg": "chip avg",
        "chip_max": "chip max",
        "board_max": "board max (PCB)",
    }
    for sid in POOL_WATER_SENSORS:
        out.append(
            {
                "id": sid,
                "group": "miner",
                "label": labels.get(sid, sid),
            }
        )
    try:
        for s in list_sensors():
            if not isinstance(s, dict):
                continue
            if s.get("enabled") is False:
                continue
            alias = str(s.get("alias") or "").strip().lower()
            if not _sensor_alias_ok(alias):
                continue
            out.append(
                {
                    "id": f"sensor:{alias}",
                    "group": "sensors",
                    "alias": alias,
                    "name": s.get("name") or alias,
                    "name_en": s.get("name_en") or s.get("name") or alias,
                    "name_ru": s.get("name_ru") or s.get("name") or alias,
                    "unit": s.get("unit") or "°C",
                    "label": f"{s.get('name') or alias} · {alias}",
                }
            )
    except Exception:
        pass
    return out


def resolve_pool_water(
    live: dict | None, sensor: str | None = None
) -> tuple[float | None, str]:
    """
    Pool water temperature from live snapshot and/or peripheral sensors.
    sensor id: built-in or ``sensor:<alias>``.
    """
    if sensor is None:
        with _pool_cfg_lock:
            sensor = _pool_cfg.get("water_sensor") or "liquid"
    sens = _normalize_pool_water_sensor(sensor)
    if sens.startswith("sensor:"):
        alias = sens.split(":", 1)[1]
        try:
            sdef = get_sensor_by_alias(alias)
        except Exception:
            sdef = None
        if not sdef or sdef.get("enabled") is False:
            return None, sens
        try:
            live_d = live if isinstance(live, dict) else None
            ev = evaluate_sensor(sdef, live=live_d)
            if ev.get("ok"):
                return _f(ev.get("value")), sens
        except Exception:
            pass
        return None, sens
    return resolve_t_ctrl(live, sens)


def _save_pool_cfg() -> None:
    with _pool_cfg_lock:
        _save_json(POOL_CFG_FILE, _pool_cfg)
    # keep active heat-pool config in sync
    try:
        _sync_active_heat_pool_from_legacy()
    except Exception as e:
        print(f"[heat-pools] sync active from legacy: {e}", flush=True)


# ── Multi heat-pools (geometry catalog + miner binding) ─────────────────────

_heat_pools_lock = threading.Lock()
_heat_pools: dict = {"version": 1, "active_id": None, "pools": []}


def _new_heat_pool_id() -> str:
    return "pool_" + uuid.uuid4().hex[:10]


def _coerce_pool_geometry(cfg: dict | None) -> dict:
    """Normalize geometry fields (same rules as single pool_config)."""
    base = dict(DEFAULT_POOL_CFG)
    if isinstance(cfg, dict):
        base.update(cfg)
    out = dict(DEFAULT_POOL_CFG)
    for key, default in (
        ("length_m", 8.0),
        ("width_m", 4.0),
        ("depth_m", 1.5),
        ("flow_m3h", 12.0),
    ):
        try:
            v = float(base.get(key, default))
        except (TypeError, ValueError):
            v = default
        if key == "flow_m3h":
            v = max(0.0, min(500.0, v))
        else:
            v = max(0.1, min(200.0, v))
        out[key] = v
    shape = str(base.get("shape") or "rect").lower()
    if shape in ("round", "circular", "circle"):
        shape = "circle"
    elif shape in ("ellipse", "elliptic", "oval"):
        shape = "oval"
    else:
        shape = "rect"
    out["shape"] = shape
    out["water_sensor"] = _normalize_pool_water_sensor(
        base.get("water_sensor", "liquid")
    )
    return out


def _load_heat_pools() -> None:
    global _heat_pools
    with _heat_pools_lock:
        raw = _load_json(HEAT_POOLS_FILE, {})
        if not isinstance(raw, dict) or not isinstance(raw.get("pools"), list):
            # migrate from single pool_config.json
            with _pool_cfg_lock:
                legacy = dict(_pool_cfg)
            pid = "pool_default"
            _heat_pools = {
                "version": 1,
                "active_id": pid,
                "pools": [
                    {
                        "id": pid,
                        "name": "Main pool",
                        "enabled": True,
                        "config": _coerce_pool_geometry(legacy),
                        "updated_ts": datetime.now().isoformat(timespec="seconds"),
                    }
                ],
            }
            try:
                _save_json(HEAT_POOLS_FILE, _heat_pools)
            except Exception:
                pass
            return
        pools: list[dict] = []
        for p in raw.get("pools") or []:
            if not isinstance(p, dict):
                continue
            pid = str(p.get("id") or "").strip() or _new_heat_pool_id()
            name = str(p.get("name") or "Pool").strip()[:64] or "Pool"
            pools.append(
                {
                    "id": pid,
                    "name": name,
                    "enabled": bool(p.get("enabled", True)),
                    "config": _coerce_pool_geometry(
                        p.get("config") if isinstance(p.get("config"), dict) else p
                    ),
                    "updated_ts": p.get("updated_ts")
                    or datetime.now().isoformat(timespec="seconds"),
                }
            )
        if not pools:
            pid = "pool_default"
            with _pool_cfg_lock:
                legacy = dict(_pool_cfg)
            pools = [
                {
                    "id": pid,
                    "name": "Main pool",
                    "enabled": True,
                    "config": _coerce_pool_geometry(legacy),
                    "updated_ts": datetime.now().isoformat(timespec="seconds"),
                }
            ]
        active = str(raw.get("active_id") or "").strip()
        if not any(p["id"] == active for p in pools):
            active = pools[0]["id"]
        _heat_pools = {"version": 1, "active_id": active, "pools": pools}


def _save_heat_pools() -> None:
    with _heat_pools_lock:
        _save_json(HEAT_POOLS_FILE, _heat_pools)


def _sync_active_heat_pool_from_legacy() -> None:
    """When /api/pool/config is saved, mirror into active heat-pool entry."""
    with _heat_pools_lock:
        if not _heat_pools.get("pools"):
            return
        active = str(_heat_pools.get("active_id") or "")
        with _pool_cfg_lock:
            cfg = _coerce_pool_geometry(_pool_cfg)
        for p in _heat_pools.get("pools") or []:
            if p.get("id") == active:
                p["config"] = cfg
                p["updated_ts"] = datetime.now().isoformat(timespec="seconds")
                break
        _save_json(HEAT_POOLS_FILE, _heat_pools)


def _apply_heat_pool_to_legacy(pool: dict) -> None:
    """Push selected pool geometry into legacy _pool_cfg (live heat model)."""
    cfg = _coerce_pool_geometry(
        pool.get("config") if isinstance(pool, dict) else None
    )
    with _pool_cfg_lock:
        _pool_cfg.clear()
        _pool_cfg.update(cfg)
    # avoid recursive sync loop: write file only
    with _pool_cfg_lock:
        _save_json(POOL_CFG_FILE, _pool_cfg)


def list_heat_pools() -> dict:
    with _heat_pools_lock:
        pools = list(_heat_pools.get("pools") or [])
        active = _heat_pools.get("active_id")
    # attach bound miners
    managed = get_miners_managed().get("miners") or []
    by_pool: dict[str, list] = {}
    for m in managed:
        pid = str(m.get("pool_id") or "").strip()
        if not pid:
            continue
        by_pool.setdefault(pid, []).append(
            {
                "id": m.get("id"),
                "alias": m.get("alias"),
                "name": m.get("name"),
                "host": m.get("host"),
                "role": m.get("role"),
                "cooling": m.get("cooling"),
            }
        )
    items = []
    for p in pools:
        pid = p.get("id")
        cfg = p.get("config") or {}
        items.append(
            {
                "id": pid,
                "name": p.get("name"),
                "enabled": p.get("enabled", True),
                "config": cfg,
                "derived": pool_derived(cfg),
                "updated_ts": p.get("updated_ts"),
                "miners": by_pool.get(pid, []),
                "miner_count": len(by_pool.get(pid, [])),
                "active": pid == active,
            }
        )
    return {
        "ok": True,
        "active_id": active,
        "pools": items,
        "cooling_types": list_miner_cooling_types(),
    }


def get_heat_pool(pool_id: str) -> dict | None:
    pid = str(pool_id or "").strip()
    with _heat_pools_lock:
        for p in _heat_pools.get("pools") or []:
            if p.get("id") == pid:
                return json.loads(json.dumps(p))
    return None


def save_heat_pool(
    name: str,
    config: dict | None = None,
    *,
    pool_id: str | None = None,
    enabled: bool | None = None,
    make_active: bool = False,
) -> dict:
    name = str(name or "").strip()
    if not name:
        raise ValueError("name empty")
    if len(name) > 64:
        name = name[:64]
    cfg = _coerce_pool_geometry(config)
    now = datetime.now().isoformat(timespec="seconds")
    with _heat_pools_lock:
        pools = list(_heat_pools.get("pools") or [])
        if pool_id:
            pid = str(pool_id).strip()
            found = False
            for i, p in enumerate(pools):
                if p.get("id") == pid:
                    row = dict(p)
                    row["name"] = name
                    row["config"] = cfg
                    row["updated_ts"] = now
                    if enabled is not None:
                        row["enabled"] = bool(enabled)
                    pools[i] = row
                    found = True
                    out_id = pid
                    break
            if not found:
                raise ValueError(f"pool not found: {pid}")
        else:
            out_id = _new_heat_pool_id()
            pools.append(
                {
                    "id": out_id,
                    "name": name,
                    "enabled": True if enabled is None else bool(enabled),
                    "config": cfg,
                    "updated_ts": now,
                }
            )
        _heat_pools["pools"] = pools
        if make_active or not _heat_pools.get("active_id"):
            _heat_pools["active_id"] = out_id
        active_id = _heat_pools.get("active_id")
    _save_heat_pools()
    # if this is the active pool — push to legacy live config
    if active_id == out_id:
        p = get_heat_pool(out_id)
        if p:
            _apply_heat_pool_to_legacy(p)
    return {"ok": True, "id": out_id, **list_heat_pools()}


def delete_heat_pool(pool_id: str) -> dict:
    pid = str(pool_id or "").strip()
    if not pid:
        raise ValueError("id empty")
    with _heat_pools_lock:
        pools = [p for p in (_heat_pools.get("pools") or []) if p.get("id") != pid]
        if len(pools) == len(_heat_pools.get("pools") or []):
            raise ValueError(f"pool not found: {pid}")
        if not pools:
            raise ValueError("cannot delete the last pool")
        _heat_pools["pools"] = pools
        if _heat_pools.get("active_id") == pid:
            _heat_pools["active_id"] = pools[0]["id"]
            active = pools[0]
        else:
            active = None
            for p in pools:
                if p.get("id") == _heat_pools.get("active_id"):
                    active = p
                    break
    _save_heat_pools()
    # unbind miners from deleted pool
    managed = list(get_miners_managed().get("miners") or [])
    dirty = False
    for m in managed:
        if str(m.get("pool_id") or "") == pid:
            m["pool_id"] = ""
            dirty = True
    if dirty:
        _save_miners_managed(managed)
    if active:
        _apply_heat_pool_to_legacy(active)
    return list_heat_pools()


def set_active_heat_pool(pool_id: str) -> dict:
    p = get_heat_pool(pool_id)
    if not p:
        raise ValueError(f"pool not found: {pool_id}")
    with _heat_pools_lock:
        _heat_pools["active_id"] = p["id"]
    _save_heat_pools()
    _apply_heat_pool_to_legacy(p)
    return {"ok": True, "active_id": p["id"], **list_heat_pools()}


def bind_miners_to_heat_pool(pool_id: str, miner_ids: list | None) -> dict:
    """
    Set which managed miners heat this pool.
    miner_ids — full list for this pool (others unbind if they pointed here).
    """
    pid = str(pool_id or "").strip()
    if not pid:
        raise ValueError("pool_id required")
    if not get_heat_pool(pid):
        raise ValueError(f"pool not found: {pid}")
    want = set()
    for x in miner_ids or []:
        s = str(x or "").strip()
        if s:
            want.add(s)
    managed = list(get_miners_managed().get("miners") or [])
    for m in managed:
        mid = str(m.get("id") or "")
        cur = str(m.get("pool_id") or "")
        if mid in want:
            m["pool_id"] = pid
        elif cur == pid:
            m["pool_id"] = ""
    _save_miners_managed(managed)
    return list_heat_pools()


def pool_derived(cfg: dict | None = None) -> dict:
    """
    Volume (m³) and surface area (m²).
    shapes:
      rect  — L×W×D prism, S = L×W
      circle — diameter = L, S = π(L/2)², V = S×D
      oval  — ellipse axes L×W, S = π(L/2)(W/2), V = S×D
    """
    with _pool_cfg_lock:
        c = dict(cfg or _pool_cfg)
    L = float(c.get("length_m") or 0)
    W = float(c.get("width_m") or 0)
    D = float(c.get("depth_m") or 0)
    flow = float(c.get("flow_m3h") or 0)
    shape = str(c.get("shape") or "rect").lower()
    if shape in ("round", "circular", "circle"):
        shape = "circle"
    elif shape in ("ellipse", "elliptic", "oval"):
        shape = "oval"
    else:
        shape = "rect"

    if shape == "circle":
        r = L / 2.0
        surface_m2 = math.pi * r * r
        volume_m3 = surface_m2 * D
        formula_v = "V = π·(Ø/2)²·D"
        formula_s = "S = π·(Ø/2)²"
    elif shape == "oval":
        surface_m2 = math.pi * (L / 2.0) * (W / 2.0)
        volume_m3 = surface_m2 * D
        formula_v = "V = π·(L/2)·(W/2)·D"
        formula_s = "S = π·(L/2)·(W/2)"
    else:
        volume_m3 = L * W * D
        surface_m2 = L * W
        formula_v = "V = L × W × D"
        formula_s = "S = L × W"

    turnover_h = (volume_m3 / flow) if flow > 0 else None
    mass_kg = volume_m3 * 1000.0
    return {
        "length_m": L,
        "width_m": W,
        "depth_m": D,
        "flow_m3h": flow,
        "volume_m3": round(volume_m3, 3),
        "surface_m2": round(surface_m2, 3),
        "turnover_h": round(turnover_h, 3) if turnover_h is not None else None,
        "mass_kg": round(mass_kg, 1),
        "shape": shape,
        "formula_v": formula_v,
        "formula_s": formula_s,
        "water_sensor": _normalize_pool_water_sensor(c.get("water_sensor")),
        "water_sensors": list(POOL_WATER_SENSORS),
        "water_sensor_options": list_pool_water_sensor_options(),
    }


def _http_get_json(url: str, timeout: float = 12.0) -> dict:
    req = urllib.request.Request(
        url,
        headers={"User-Agent": "poolheat/0.1 (weather; Open-Meteo)"},
        method="GET",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
    data = json.loads(raw)
    if not isinstance(data, dict):
        raise RuntimeError("unexpected weather response")
    return data


