def _wmo_text(code: int | None, lang: str = "ru") -> str:
    if code is None:
        return "—"
    table = _WMO_EN if str(lang or "").lower().startswith("en") else _WMO_RU
    return table.get(int(code), "—")


def weather_search_cities(
    query: str, count: int = 12, *, language: str | None = None
) -> list[dict]:
    """
    Open-Meteo geocoding. Tries preferred language, then fallbacks (en/ru)
    so Latin and Cyrillic queries both return hits.
    """
    q = (query or "").strip()
    if len(q) < 2:
        return []
    count = max(1, min(25, int(count)))
    lang0 = (language or "ru").strip().lower()[:5] or "ru"
    # try preferred + common fallbacks (dedupe)
    langs: list[str] = []
    for L in (lang0, "en", "ru"):
        if L and L not in langs:
            langs.append(L)

    def _parse(data: dict) -> list[dict]:
        results = data.get("results") or []
        out: list[dict] = []
        for r in results:
            if not isinstance(r, dict):
                continue
            try:
                lat = float(r["latitude"])
                lon = float(r["longitude"])
            except (KeyError, TypeError, ValueError):
                continue
            out.append(
                {
                    "city": r.get("name") or q,
                    "country": r.get("country_code") or r.get("country") or "",
                    "admin1": r.get("admin1") or "",
                    "latitude": lat,
                    "longitude": lon,
                    "timezone": r.get("timezone") or "auto",
                    "label": ", ".join(
                        x
                        for x in [
                            r.get("name"),
                            r.get("admin1"),
                            r.get("country_code") or r.get("country"),
                        ]
                        if x
                    ),
                }
            )
        return out

    last_err: Exception | None = None
    for lang in langs:
        url = (
            "https://geocoding-api.open-meteo.com/v1/search?"
            + urllib.parse.urlencode(
                {"name": q, "count": count, "language": lang, "format": "json"}
            )
        )
        try:
            data = _http_get_json(url)
            out = _parse(data if isinstance(data, dict) else {})
            if out:
                return out
        except Exception as e:
            last_err = e
            continue
    if last_err is not None:
        raise last_err
    return []


def fetch_weather_current(cfg: dict | None = None, *, force: bool = False) -> dict:
    """Current outdoor weather for configured city (Open-Meteo)."""
    global _weather_cache, _weather_cache_ts
    with _weather_cfg_lock:
        c = dict(cfg or _weather_cfg)

    if not c.get("enabled", True):
        return {"ok": True, "enabled": False, "city": c.get("city"), "temp_c": None}

    now = time.time()
    ttl = float(_weather_refresh_sec(c))
    with _weather_cache_lock:
        if (
            not force
            and _weather_cache is not None
            and (now - _weather_cache_ts) < ttl
            and _weather_cache.get("ok")
        ):
            out = dict(_weather_cache)
            out["refresh_interval_sec"] = int(ttl)
            return out

    lat = float(c["latitude"])
    lon = float(c["longitude"])
    tz = c.get("timezone") or "auto"
    url = (
        "https://api.open-meteo.com/v1/forecast?"
        + urllib.parse.urlencode(
            {
                "latitude": lat,
                "longitude": lon,
                "current": (
                    "temperature_2m,relative_humidity_2m,weather_code,"
                    "wind_speed_10m,is_day,apparent_temperature,surface_pressure"
                ),
                "timezone": tz,
                "wind_speed_unit": "ms",
            }
        )
    )
    try:
        data = _http_get_json(url)
        cur = data.get("current") or {}
        code = cur.get("weather_code")
        try:
            code_i = int(code) if code is not None else None
        except (TypeError, ValueError):
            code_i = None
        is_day_raw = cur.get("is_day")
        try:
            is_day = bool(int(is_day_raw)) if is_day_raw is not None else True
        except (TypeError, ValueError):
            is_day = True
        # surface_pressure is already hPa on Open-Meteo
        p_hpa = _f(cur.get("surface_pressure"))
        if p_hpa is not None:
            p_hpa = round(p_hpa, 1)
        body = {
            "ok": True,
            "enabled": True,
            "city": c.get("city"),
            "country": c.get("country"),
            "admin1": c.get("admin1"),
            "latitude": lat,
            "longitude": lon,
            "timezone": data.get("timezone") or tz,
            "temp_c": cur.get("temperature_2m"),
            "feels_like_c": cur.get("apparent_temperature"),
            "humidity": cur.get("relative_humidity_2m"),
            "wind_ms": cur.get("wind_speed_10m"),
            "pressure_hpa": p_hpa,
            "weather_code": code_i,
            "weather_text": _wmo_text(code_i, "ru"),
            "weather_text_en": _wmo_text(code_i, "en"),
            "is_day": is_day,
            "observed_at": cur.get("time"),
            "refresh_interval_sec": int(ttl),
            "source": "open-meteo",
            "cached": False,
        }
        with _weather_cache_lock:
            _weather_cache = dict(body)
            _weather_cache["cached"] = True
            _weather_cache_ts = now
        body["cached"] = False
        return body
    except Exception as e:
        with _weather_cache_lock:
            stale = dict(_weather_cache) if _weather_cache else None
        if stale and stale.get("ok"):
            stale = dict(stale)
            stale["stale"] = True
            stale["error"] = str(e)
            return stale
        return {
            "ok": False,
            "enabled": True,
            "city": c.get("city"),
            "error": str(e),
            "temp_c": None,
        }


