def _db_connect() -> sqlite3.Connection:
    conn = sqlite3.connect(str(DB_FILE), check_same_thread=False, timeout=10)
    conn.row_factory = sqlite3.Row
    return conn


# Temperatures persisted for dashboard chart (settings gear list).
# Keep in sync with ui TEMP_CHART_SERIES / live temps catalog.
HISTORY_TEMP_COLUMNS: tuple[str, ...] = (
    "liquid",
    "env",
    "outdoor_c",
    "chip_min",
    "chip_avg",
    "chip_max",
    "board0",
    "board1",
    "board2",
    "board3",
    "board_max",
    "psu_temp",
    "inlet",
    "outlet",
    # per-slot chip temps (SM0–SM3) when ASIC exposes them
    "sm0_chip_min",
    "sm0_chip_avg",
    "sm0_chip_max",
    "sm1_chip_min",
    "sm1_chip_avg",
    "sm1_chip_max",
    "sm2_chip_min",
    "sm2_chip_avg",
    "sm2_chip_max",
    "sm3_chip_min",
    "sm3_chip_avg",
    "sm3_chip_max",
)


def init_db() -> None:
    with _db_lock:
        conn = _db_connect()
        try:
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS samples (
                    ts REAL NOT NULL PRIMARY KEY,
                    ts_iso TEXT NOT NULL,
                    liquid REAL,
                    env REAL,
                    chip_min REAL,
                    chip_avg REAL,
                    chip_max REAL,
                    board0 REAL,
                    board1 REAL,
                    board2 REAL,
                    board3 REAL,
                    power REAL,
                    power_limit REAL,
                    power_limit_set REAL,
                    power_pct_cmd REAL,
                    freq REAL,
                    hashrate_th REAL,
                    mode TEXT,
                    hash_stable INTEGER,
                    online INTEGER DEFAULT 1,
                    work_state TEXT,
                    upfreq_ok INTEGER
                )
                """
            )
            conn.execute("CREATE INDEX IF NOT EXISTS idx_samples_ts ON samples(ts)")
            # migrate older DBs
            cols = {r[1] for r in conn.execute("PRAGMA table_info(samples)").fetchall()}
            if "hashrate_th" not in cols:
                conn.execute("ALTER TABLE samples ADD COLUMN hashrate_th REAL")
            if "online" not in cols:
                conn.execute("ALTER TABLE samples ADD COLUMN online INTEGER DEFAULT 1")
            if "work_state" not in cols:
                conn.execute("ALTER TABLE samples ADD COLUMN work_state TEXT")
            if "upfreq_ok" not in cols:
                conn.execute("ALTER TABLE samples ADD COLUMN upfreq_ok INTEGER")
            if "outdoor_c" not in cols:
                conn.execute("ALTER TABLE samples ADD COLUMN outdoor_c REAL")
            if "eff_jt" not in cols:
                conn.execute("ALTER TABLE samples ADD COLUMN eff_jt REAL")
            # all chart-displayable temperatures
            for col in HISTORY_TEMP_COLUMNS:
                if col not in cols:
                    try:
                        conn.execute(
                            f"ALTER TABLE samples ADD COLUMN {col} REAL"
                        )
                    except Exception:
                        pass
            # User sensors with history=true (Peripherals → Sensors)
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS sensor_samples (
                    ts REAL NOT NULL,
                    alias TEXT NOT NULL,
                    value REAL,
                    PRIMARY KEY (ts, alias)
                )
                """
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_sensor_samples_alias_ts "
                "ON sensor_samples(alias, ts)"
            )
            # Miner error journal (last 100 kept by app logic)
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS miner_error_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    seen_ts REAL NOT NULL,
                    seen_iso TEXT NOT NULL,
                    code TEXT NOT NULL,
                    cause TEXT,
                    miner_ts TEXT,
                    miner_sn TEXT,
                    miner_type TEXT,
                    miner_mac TEXT,
                    miner_label TEXT,
                    component_sn TEXT,
                    component_tag TEXT,
                    UNIQUE(code, miner_ts)
                )
                """
            )
            # migrate older journals
            err_cols = {
                r[1] for r in conn.execute("PRAGMA table_info(miner_error_log)").fetchall()
            }
            for col, decl in (
                ("miner_sn", "TEXT"),
                ("miner_type", "TEXT"),
                ("miner_mac", "TEXT"),
                ("miner_label", "TEXT"),
                ("component_sn", "TEXT"),
                ("component_tag", "TEXT"),
            ):
                if col not in err_cols:
                    try:
                        conn.execute(
                            f"ALTER TABLE miner_error_log ADD COLUMN {col} {decl}"
                        )
                    except Exception:
                        pass
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_miner_err_seen ON miner_error_log(seen_ts DESC)"
            )
            conn.commit()
        finally:
            conn.close()


# MINER_ERROR_LOG_MAX / POLICY_EVENTS_MAX live in logs_config (see get_error_log_max)
_IDENT_CACHE: dict = {"ts": 0.0, "data": None}
_IDENT_CACHE_TTL = 45.0
_BACKFILL_DONE = False
INFO_CACHE_FILE = DATA / "info_cache.json"
MINER_ID_CACHE_FILE = DATA / "miner_identity_cache.json"


def _normalize_sn(v) -> str | None:
    """Non-empty serial string, or None."""
    if v is None:
        return None
    s = str(v).strip()
    if not s or s.lower() in ("none", "null", "n/a", "na", "—", "-"):
        return None
    return s


def _effective_miner_sn(ident: dict | None) -> tuple[str | None, str | None]:
    """
    Display SN: minersn if set, else CustomerSn (custom_data).
    Returns (sn, source) where source is 'minersn' | 'customer_sn' | None.
    """
    if not isinstance(ident, dict):
        return None, None
    msn = _normalize_sn(ident.get("minersn") or ident.get("miner_sn"))
    if msn:
        return msn, "minersn"
    csn = _normalize_sn(
        ident.get("customer_sn")
        or ident.get("CustomerSn")
        or ident.get("customerSn")
    )
    if csn:
        return csn, "customer_sn"
    return None, None


def _miner_display_label(ident: dict | None) -> str:
    """Prefer ASIC SN (minersn → CustomerSn); else model · MAC."""
    if not isinstance(ident, dict):
        return "—"
    sn, _src = _effective_miner_sn(ident)
    if sn:
        return sn
    parts: list[str] = []
    mt = (ident.get("miner_type") or "").strip()
    mac = (ident.get("mac") or "").strip()
    if mt:
        parts.append(mt)
    if mac:
        parts.append(mac)
    return " · ".join(parts) if parts else "—"


def _sm_slot_from_error(code: str | None, cause: str | None) -> int | None:
    """SM0..SM3 → slot 0..3 from cause text or known board error codes."""
    text = f"{cause or ''} {code or ''}"
    m = re.search(r"\bSM\s*([0-3])\b", text, re.I)
    if m:
        return int(m.group(1))
    # WMOC reason: "Slot2 chips been reset, U1-U2-…"
    m = re.search(r"\bSlot\s*([0-3])\b", text, re.I)
    if m:
        return int(m.group(1))
    c = str(code or "").strip().lstrip("0") or str(code or "").strip()
    if not c.isdigit():
        return None
    # known exact FW codes with fixed slot (catalog titles, not pattern math)
    _exact_slot = {
        "550999": 0, "551999": 1, "552999": 2, "553999": 3,
        "580999": 0, "581999": 1, "582999": 2, "583999": 3,
        "5130": 0, "5131": 1, "5132": 2, "5133": 3,
    }
    if c in _exact_slot:
        return _exact_slot[c]
    # last digit = board index for SM* families
    families = (
        "300", "301", "302", "303",
        "320", "321", "322", "323",
        "350", "351", "352", "353",
        "410", "411", "412", "413",
        "420", "421", "422", "423",
        "430", "431", "432", "433",
        "440", "441", "442", "443",
        "510", "511", "512", "513",
        "530", "531", "532", "533",
        "540", "541", "542", "543",
        "550", "551", "552", "553",
        "560", "561", "562", "563",
        "580", "581", "582", "583",
        "5110", "5111", "5112", "5113",
    )
    if c in families or any(c.startswith(p) and len(c) == len(p) for p in ("30", "32", "35", "41", "42", "43", "44", "51", "53", "54", "55", "56", "58")):
        d = int(c[-1])
        if 0 <= d <= 3:
            return d
    # 5110-5113 frequency up
    if c.startswith("511") and len(c) == 4:
        d = int(c[-1])
        if 0 <= d <= 3:
            return d
    return None


def _is_psu_error_code(code: str | None) -> bool:
    c = str(code or "").strip().lstrip("0") or ""
    if not c.isdigit():
        return False
    n = int(c)
    return 200 <= n < 300


def _component_for_error(
    code: str | None,
    cause: str | None,
    ident: dict | None,
) -> tuple[str | None, str | None]:
    """
    Component SN for the failing part.
    SM2 reading chip id error → PCB SN of slot 2.
    PSU family → powersn.
    """
    ident = ident if isinstance(ident, dict) else {}
    slot = _sm_slot_from_error(code, cause)
    if slot is not None:
        boards = ident.get("boards") or []
        pcb = None
        for b in boards:
            if not isinstance(b, dict):
                continue
            try:
                if int(b.get("slot")) == slot:
                    pcb = b.get("pcb_sn")
                    break
            except (TypeError, ValueError):
                continue
        if not pcb and 0 <= slot < len(boards) and isinstance(boards[slot], dict):
            pcb = boards[slot].get("pcb_sn")
        return (str(pcb) if pcb else None), f"SM{slot}"
    if _is_psu_error_code(code):
        psn = ident.get("powersn")
        return (str(psn) if psn else None), "PSU"
    return None, None


def _load_miner_id_disk() -> dict | None:
    try:
        if not MINER_ID_CACHE_FILE.is_file():
            return None
        d = json.loads(MINER_ID_CACHE_FILE.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else None
    except Exception:
        return None


def _save_miner_id_disk(data: dict) -> None:
    try:
        MINER_ID_CACHE_FILE.write_text(
            json.dumps(data, ensure_ascii=False), encoding="utf-8"
        )
    except Exception:
        pass


def _identity_usable(data: dict | None) -> bool:
    if not isinstance(data, dict):
        return False
    return bool(
        data.get("ok")
        or data.get("mac")
        or data.get("miner_type")
        or data.get("minersn")
        or (data.get("boards") or [])
    )


def get_miner_identity_cached(force: bool = False) -> dict:
    """Cached miner identity (type, mac, sn, boards PCB SN). Falls back to last good."""
    global _BACKFILL_DONE
    now = time.time()
    if (
        not force
        and _IDENT_CACHE.get("data")
        and (now - float(_IDENT_CACHE.get("ts") or 0)) < _IDENT_CACHE_TTL
        and _identity_usable(_IDENT_CACHE.get("data"))
    ):
        return dict(_IDENT_CACHE["data"])
    data: dict
    try:
        data = _collect_miner_identity()
    except Exception as e:
        data = {"ok": False, "error": str(e), "boards": []}
    if _identity_usable(data):
        _IDENT_CACHE["ts"] = now
        _IDENT_CACHE["data"] = data
        _save_miner_id_disk(data)
        if not _BACKFILL_DONE:
            try:
                n = backfill_miner_error_log_identity(ident=data)
                if n:
                    print(f"error log backfill: {n} rows")
                _BACKFILL_DONE = True
            except Exception as e:
                print(f"error log backfill: {e}")
        return dict(data)
    # live failed — use memory / disk last-good
    if _identity_usable(_IDENT_CACHE.get("data")):
        return dict(_IDENT_CACHE["data"])
    disk = _load_miner_id_disk()
    if _identity_usable(disk):
        _IDENT_CACHE["ts"] = now
        _IDENT_CACHE["data"] = disk
        return dict(disk)
    _IDENT_CACHE["ts"] = now
    _IDENT_CACHE["data"] = data
    return dict(data)


def log_miner_errors(
    entries: list[dict],
    *,
    miner_ctx: dict | None = None,
) -> int:
    """
    Append new miner errors to journal (dedupe by code+miner_ts).
    Stores miner identity + component SN for the miner active at log time.
    Keep only last get_error_log_max() rows. Returns number inserted.
    """
    if not entries:
        return 0
    ident = miner_ctx if isinstance(miner_ctx, dict) else get_miner_identity_cached()
    label = _miner_display_label(ident)
    miner_sn = (ident.get("minersn") or None) if isinstance(ident, dict) else None
    miner_type = (ident.get("miner_type") or None) if isinstance(ident, dict) else None
    miner_mac = (ident.get("mac") or None) if isinstance(ident, dict) else None
    if miner_sn == "":
        miner_sn = None

    now = time.time()
    iso = datetime.now().isoformat(timespec="seconds")
    max_rows = get_error_log_max()
    inserted = 0
    with _db_lock:
        conn = _db_connect()
        try:
            for e in entries:
                code = str(e.get("code") or "").strip()
                if not code:
                    continue
                miner_ts = e.get("ts")
                miner_ts_s = str(miner_ts) if miner_ts not in (None, "") else ""
                cause = e.get("cause") or e.get("message") or ""
                # allow per-entry override of component
                comp_sn = e.get("component_sn")
                comp_tag = e.get("component_tag")
                if not comp_sn and not comp_tag:
                    comp_sn, comp_tag = _component_for_error(code, cause, ident)
                try:
                    cur = conn.execute(
                        """
                        INSERT OR IGNORE INTO miner_error_log
                            (seen_ts, seen_iso, code, cause, miner_ts,
                             miner_sn, miner_type, miner_mac, miner_label,
                             component_sn, component_tag)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?)
                        """,
                        (
                            now,
                            iso,
                            code,
                            str(cause),
                            miner_ts_s,
                            miner_sn,
                            miner_type,
                            miner_mac,
                            label,
                            comp_sn,
                            comp_tag,
                        ),
                    )
                    inserted += int(cur.rowcount or 0)
                except Exception:
                    continue
            # prune oldest beyond limit
            conn.execute(
                """
                DELETE FROM miner_error_log
                WHERE id NOT IN (
                    SELECT id FROM miner_error_log
                    ORDER BY seen_ts DESC, id DESC
                    LIMIT ?
                )
                """,
                (max_rows,),
            )
            conn.commit()
        finally:
            conn.close()
    return inserted


def backfill_miner_error_log_identity(ident: dict | None = None) -> int:
    """
    Fill miner/component columns for old journal rows using Info identity
    (current live or last-good cache). Returns number of rows updated.
    """
    if ident is None:
        try:
            ident = get_miner_identity_cached(force=False)
        except Exception:
            ident = _load_miner_id_disk() or {}
    if not _identity_usable(ident):
        return 0
    label = _miner_display_label(ident)
    miner_sn = ident.get("minersn") or None
    if miner_sn == "":
        miner_sn = None
    miner_type = ident.get("miner_type") or None
    miner_mac = ident.get("mac") or None
    updated = 0
    with _db_lock:
        conn = _db_connect()
        try:
            cur = conn.execute(
                """
                SELECT id, code, cause, miner_label, component_sn, component_tag
                FROM miner_error_log
                """
            )
            rows = cur.fetchall()
            for r in rows:
                fields: dict = {}
                if not (r["miner_label"] or "").strip():
                    fields["miner_sn"] = miner_sn
                    fields["miner_type"] = miner_type
                    fields["miner_mac"] = miner_mac
                    fields["miner_label"] = label
                if not (r["component_sn"] or "").strip():
                    csn, ctag = _component_for_error(r["code"], r["cause"], ident)
                    if csn:
                        fields["component_sn"] = csn
                    if ctag and not (r["component_tag"] or "").strip():
                        fields["component_tag"] = ctag
                elif not (r["component_tag"] or "").strip():
                    _, ctag = _component_for_error(r["code"], r["cause"], ident)
                    if ctag:
                        fields["component_tag"] = ctag
                if not fields:
                    continue
                sets = ", ".join(f"{k}=?" for k in fields)
                conn.execute(
                    f"UPDATE miner_error_log SET {sets} WHERE id=?",
                    (*fields.values(), r["id"]),
                )
                updated += 1
            conn.commit()
        finally:
            conn.close()
    return updated


def _display_cause(code: str | None, cause: str | None) -> str:
    """Prefer official Whatsminer web Cause when stored text is a placeholder."""
    c = str(code or "").strip()
    msg = (cause or "").strip()
    if msg and msg.lower() not in (f"error code {c}".lower(), f"error {c}".lower()):
        return msg
    return _official_cause(c) or msg or (f"Error code {c}" if c else "—")


def query_miner_error_log(limit: int | None = None) -> list[dict]:
    mx = get_error_log_max()
    if limit is None:
        limit = mx
    try:
        limit = int(limit)
    except (TypeError, ValueError):
        limit = mx
    limit = max(1, min(mx, limit))
    with _db_lock:
        conn = _db_connect()
        try:
            cur = conn.execute(
                """
                SELECT id, seen_ts, seen_iso, code, cause, miner_ts,
                       miner_sn, miner_type, miner_mac, miner_label,
                       component_sn, component_tag
                FROM miner_error_log
                ORDER BY seen_ts DESC, id DESC
                LIMIT ?
                """,
                (limit,),
            )
            rows = []
            for r in cur.fetchall():
                code = r["code"]
                cause = _display_cause(code, r["cause"])
                # display miner: stored label, or rebuild
                mlabel = (r["miner_label"] or "").strip()
                if not mlabel:
                    mlabel = _miner_display_label(
                        {
                            "minersn": r["miner_sn"],
                            "miner_type": r["miner_type"],
                            "mac": r["miner_mac"],
                        }
                    )
                ctag = (r["component_tag"] or "").strip()
                csn = (r["component_sn"] or "").strip()
                if not csn and not ctag:
                    csn2, ctag2 = _component_for_error(code, cause, None)
                    csn, ctag = (csn2 or ""), (ctag2 or "")
                comp_disp = csn or "—"
                if ctag and csn:
                    comp_disp = f"{ctag} · {csn}"
                elif ctag and not csn:
                    comp_disp = ctag
                rows.append(
                    {
                        "id": r["id"],
                        "seen_ts": r["seen_ts"],
                        "seen_iso": r["seen_iso"],
                        "code": code,
                        "cause": cause,
                        "miner_ts": r["miner_ts"] or None,
                        "miner_sn": r["miner_sn"] or None,
                        "miner_type": r["miner_type"] or None,
                        "miner_mac": r["miner_mac"] or None,
                        "miner": mlabel if mlabel != "—" else "—",
                        "component_sn": csn or None,
                        "component_tag": ctag or None,
                        "component": comp_disp,
                    }
                )
            return rows
        finally:
            conn.close()


def insert_sample(row: dict) -> None:
    with _db_lock:
        conn = _db_connect()
        try:
            uf = row.get("upfreq_ok")
            if uf is None:
                uf_db = None
            else:
                uf_db = 0 if uf in (0, False, "0") else 1
            # Core non-temp + all HISTORY_TEMP_COLUMNS (chart-displayable)
            cols = [
                "ts",
                "ts_iso",
                *HISTORY_TEMP_COLUMNS,
                "power",
                "power_limit",
                "power_limit_set",
                "power_pct_cmd",
                "freq",
                "hashrate_th",
                "mode",
                "hash_stable",
                "online",
                "work_state",
                "upfreq_ok",
                "eff_jt",
            ]
            # de-dupe while preserving order (outdoor_c is in HISTORY_TEMP)
            seen: set[str] = set()
            cols_u: list[str] = []
            for c in cols:
                if c not in seen:
                    seen.add(c)
                    cols_u.append(c)
            vals = []
            for c in cols_u:
                if c == "online":
                    vals.append(
                        0 if row.get("online") in (0, False, "0") else 1
                    )
                elif c == "upfreq_ok":
                    vals.append(uf_db)
                elif c in ("ts", "ts_iso"):
                    vals.append(row.get(c))
                else:
                    vals.append(row.get(c))
            placeholders = ",".join("?" * len(cols_u))
            col_sql = ",".join(cols_u)
            conn.execute(
                f"INSERT OR REPLACE INTO samples ({col_sql}) VALUES ({placeholders})",
                tuple(vals),
            )
            conn.commit()
        finally:
            conn.close()
    # Do not invalidate query cache on every sample — P1 TTL (10s) is enough.
    # Stats are lightly stale until TTL; full invalidate on prune/clear only.


def prune_old(retention_days: int) -> int:
    cutoff = time.time() - retention_days * 86400
    with _db_lock:
        conn = _db_connect()
        try:
            cur = conn.execute("DELETE FROM samples WHERE ts < ?", (cutoff,))
            n = cur.rowcount
            try:
                cur2 = conn.execute(
                    "DELETE FROM sensor_samples WHERE ts < ?", (cutoff,)
                )
                n += cur2.rowcount
            except Exception:
                pass
            conn.commit()
            n_out = n
        finally:
            conn.close()
    try:
        _invalidate_history_query_cache()
    except Exception:
        pass
    return n_out


def clear_history_samples() -> int:
    """Delete all history samples (charts DB)."""
    with _db_lock:
        conn = _db_connect()
        try:
            cur = conn.execute("DELETE FROM samples")
            n = cur.rowcount
            try:
                cur2 = conn.execute("DELETE FROM sensor_samples")
                n += cur2.rowcount
            except Exception:
                pass
            conn.commit()
            try:
                conn.execute("VACUUM")
            except Exception:
                pass
            n_out = n
        finally:
            conn.close()
    try:
        _invalidate_history_query_cache()
    except Exception:
        pass
    return n_out


def _history_sensor_values(live: dict | None) -> dict[str, float]:
    """Evaluate user sensors with history=true → {alias: value}."""
    out: dict[str, float] = {}
    try:
        sensors = list_sensors()
    except Exception:
        return out
    for s in sensors:
        if not s or not s.get("history"):
            continue
        if s.get("enabled", True) is False:
            continue
        alias = str(s.get("alias") or "").strip().lower()
        if not alias or not _sensor_alias_ok(alias):
            continue
        try:
            ev = evaluate_sensor(s, live=live if isinstance(live, dict) else None)
            if not ev or not ev.get("ok"):
                continue
            v = ev.get("value")
            if v is None or v == "":
                continue
            fv = float(v)
            if not math.isfinite(fv):
                continue
            out[alias] = fv
        except Exception:
            continue
    return out


def insert_sensor_samples(ts: float, values: dict[str, float]) -> int:
    """Write user-sensor history samples (same ts as miner sample)."""
    if not values:
        return 0
    try:
        ts_f = float(ts)
    except (TypeError, ValueError):
        ts_f = time.time()
    n = 0
    with _db_lock:
        conn = _db_connect()
        try:
            for alias, val in values.items():
                a = str(alias or "").strip().lower()
                if not a or not _sensor_alias_ok(a):
                    continue
                try:
                    v = float(val)
                except (TypeError, ValueError):
                    continue
                if not math.isfinite(v):
                    continue
                conn.execute(
                    """
                    INSERT OR REPLACE INTO sensor_samples (ts, alias, value)
                    VALUES (?, ?, ?)
                    """,
                    (ts_f, a, v),
                )
                n += 1
            if n:
                conn.commit()
        finally:
            conn.close()
    return n


def record_sensor_history(live: dict | None, ts: float | None = None) -> int:
    """Evaluate history-enabled sensors and store values."""
    vals = _history_sensor_values(live)
    if not vals:
        return 0
    if ts is None:
        try:
            ts = float((live or {}).get("ts") or time.time())
        except (TypeError, ValueError):
            ts = time.time()
    return insert_sensor_samples(float(ts), vals)


def clear_miner_error_log() -> int:
    """Delete all miner error journal rows + freeze cache."""
    global _state
    with _db_lock:
        conn = _db_connect()
        try:
            cur = conn.execute("DELETE FROM miner_error_log")
            conn.commit()
            n = cur.rowcount
        finally:
            conn.close()
    with _state_lock:
        _state["miner_error_cache"] = {}
        _save_state()
    return n


def history_sensor_series_meta(*, use_cache: bool = True) -> list[dict]:
    """Sensors with history=true — appear on Temperatures °C chart."""
    now = time.time()
    if use_cache:
        data = _history_sensor_meta_cache.get("data")
        ts0 = float(_history_sensor_meta_cache.get("ts") or 0)
        if data is not None and (now - ts0) < _HISTORY_SENSOR_META_TTL_SEC:
            return list(data)
    out: list[dict] = []
    try:
        sensors = list_sensors()
    except Exception:
        return out
    for s in sensors:
        if not s or not s.get("history"):
            continue
        if s.get("enabled", True) is False:
            continue
        alias = str(s.get("alias") or "").strip().lower()
        if not alias or not _sensor_alias_ok(alias):
            continue
        unit = str(s.get("unit") or "°C").strip() or "°C"
        # Temperatures °C chart: skip known non-temp units (rpm, V, W, …)
        ul = unit.lower().replace(" ", "")
        _non_temp = (
            "rpm",
            "volt",
            "volts",
            "watt",
            "watts",
            "kw",
            "kwh",
            "%",
            "amp",
            "amps",
            "ma",
            "th/s",
            "ths",
            "mhs",
            "mh/s",
        )
        if ul in _non_temp or ul in ("v", "w", "a"):
            continue
        name = str(s.get("name") or alias)
        name_en = str(s.get("name_en") or name or alias)
        name_ru = str(s.get("name_ru") or name or alias)
        # field key on history points (prefix avoids collision with liquid/env/…)
        fid = f"s_{alias}"
        out.append(
            {
                "id": fid,
                "alias": alias,
                "field": fid,
                "label": name,
                "label_en": name_en,
                "label_ru": name_ru,
                "unit": unit,
                "group": "sensor",
            }
        )
    _history_sensor_meta_cache["ts"] = time.time()
    _history_sensor_meta_cache["data"] = list(out)
    return out


def _merge_sensor_samples_into_points(
    points: list[dict], since: float, until: float
) -> list[dict]:
    """Attach sensor_samples as s_<alias> on each history point (bisect nearest)."""
    if not points:
        return points
    meta = history_sensor_series_meta()
    aliases = [m["alias"] for m in meta if m.get("alias")]
    if not aliases:
        return points
    # Load sensor samples in range for these aliases
    by_alias: dict[str, list[tuple[float, float]]] = {a: [] for a in aliases}
    with _db_lock:
        conn = _db_connect()
        try:
            try:
                ph = ",".join("?" * len(aliases))
                cur = conn.execute(
                    f"""
                    SELECT ts, alias, value FROM sensor_samples
                    WHERE ts >= ? AND ts <= ? AND alias IN ({ph})
                    ORDER BY ts ASC
                    """,
                    (since, until, *aliases),
                )
                for row in cur.fetchall():
                    a = str(row["alias"] or "").strip().lower()
                    if a not in by_alias:
                        continue
                    try:
                        ts = float(row["ts"])
                        v = float(row["value"])
                    except (TypeError, ValueError):
                        continue
                    if not math.isfinite(ts) or not math.isfinite(v):
                        continue
                    by_alias[a].append((ts, v))
            except Exception:
                return points
        finally:
            conn.close()

    # bisect-ready: parallel ts[] / val[] per alias
    series_tv: dict[str, tuple[list[float], list[float]]] = {}
    for a, series in by_alias.items():
        if not series:
            continue
        series_tv[a] = ([t for t, _ in series], [v for _, v in series])

    def _lookup(alias: str, ts: float) -> float | None:
        pair = series_tv.get(alias)
        if not pair:
            return None
        tss, vals = pair
        i = bisect.bisect_right(tss, ts + 0.05) - 1
        if i < 0:
            return None
        dt = ts - tss[i]
        if dt <= 90.0:
            return vals[i]
        return None

    for p in points:
        try:
            pts = float(p.get("ts"))
        except (TypeError, ValueError):
            continue
        for a in aliases:
            v = _lookup(a, pts)
            if v is not None:
                p[f"s_{a}"] = v
    return points


# Chart-facing columns only (no SELECT *) — order stable for SELECT list
HISTORY_STATUS_COLUMNS: tuple[str, ...] = (
    "ts",
    "online",
    "work_state",
    "upfreq_ok",
)
HISTORY_POWER_COLUMNS: tuple[str, ...] = HISTORY_STATUS_COLUMNS + (
    "power",
    "power_limit",
    "power_limit_set",
    "power_pct_cmd",
    "freq",
    "hashrate_th",
    "mode",
    "hash_stable",
    "eff_jt",
)
HISTORY_TEMPS_COLUMNS: tuple[str, ...] = HISTORY_STATUS_COLUMNS + HISTORY_TEMP_COLUMNS
# Overview dash: power + temps (no ts_iso / unused export fields)
HISTORY_DASH_COLUMNS: tuple[str, ...] = tuple(
    dict.fromkeys([*HISTORY_POWER_COLUMNS, *HISTORY_TEMPS_COLUMNS])
)
HISTORY_CHART_COLUMNS: tuple[str, ...] = (
    "ts",
    "ts_iso",
    *HISTORY_TEMP_COLUMNS,
    "power",
    "power_limit",
    "power_limit_set",
    "power_pct_cmd",
    "freq",
    "hashrate_th",
    "mode",
    "hash_stable",
    "online",
    "work_state",
    "upfreq_ok",
    "eff_jt",
)


def _history_columns_for_chart(chart: str | None) -> tuple[str, ...]:
    """P2: column set by chart kind."""
    c = str(chart or "all").strip().lower()
    if c in ("power", "pw", "hash"):
        return HISTORY_POWER_COLUMNS
    if c in ("temps", "temp", "temperature", "t"):
        return HISTORY_TEMPS_COLUMNS
    if c in ("dash", "dashboard", "overview", "ui"):
        return HISTORY_DASH_COLUMNS
    return HISTORY_CHART_COLUMNS


def _history_want_sensors(chart: str | None) -> bool:
    c = str(chart or "all").strip().lower()
    return c not in ("power", "pw", "hash")


def _points_to_columnar(points: list[dict]) -> tuple[list[str], dict]:
    """Dense columnar payload — much smaller JSON than list-of-objects."""
    if not points:
        return [], {}
    keys: list[str] = []
    seen: set[str] = set()
    for p in points:
        if not isinstance(p, dict):
            continue
        for k in p.keys():
            if k not in seen:
                seen.add(k)
                keys.append(str(k))
    cols: dict[str, list] = {k: [] for k in keys}
    for p in points:
        if not isinstance(p, dict):
            for k in keys:
                cols[k].append(None)
            continue
        for k in keys:
            cols[k].append(p.get(k))
    # drop all-null columns
    keys_out: list[str] = []
    cols_out: dict[str, list] = {}
    for k in keys:
        arr = cols[k]
        if any(v is not None and v != "" for v in arr):
            keys_out.append(k)
            cols_out[k] = arr
    return keys_out, cols_out

# P1 caches — avoid full-table stats + re-query on every chart paint
_HISTORY_STATS_TTL_SEC = 15.0
_history_stats_cache: dict = {"ts": 0.0, "data": None}
_HISTORY_QUERY_TTL_SEC = 10.0
_history_query_cache: dict = {}  # key -> {"ts": float, "points": list}
_history_query_cache_lock = threading.Lock()
_HISTORY_SENSOR_META_TTL_SEC = 30.0
_history_sensor_meta_cache: dict = {"ts": 0.0, "data": None}
# Pre-serialized JSON for GET /api/history (skip dumps on warm hits)
_HISTORY_HTTP_TTL_SEC = 45.0  # long enough for chart paint + user zoom
_history_http_cache: dict = {}  # key -> {"ts": float, "data": bytes}
_history_http_cache_lock = threading.Lock()


def _history_query_cache_key(
    since: float,
    until: float,
    max_points: int,
    chart: str = "all",
) -> tuple:
    # quantize window so nearby refreshes hit cache (30s — matches sample cadence)
    return (
        int(float(since) // 30) * 30,
        int(float(until) // 30) * 30,
        int(max_points),
        str(chart or "all"),
    )


def _invalidate_history_query_cache() -> None:
    with _history_query_cache_lock:
        _history_query_cache.clear()
    with _history_http_cache_lock:
        _history_http_cache.clear()
    _history_stats_cache["ts"] = 0.0
    _history_stats_cache["data"] = None


def _samples_existing_columns(conn) -> set[str]:
    try:
        return {str(r[1]) for r in conn.execute("PRAGMA table_info(samples)")}
    except Exception:
        return set()


def _history_select_column_list(
    conn, chart: str | None = "all"
) -> list[str]:
    """Intersect chart columns with real table (migrations / older DBs)."""
    existing = _samples_existing_columns(conn)
    if not existing:
        return ["ts"]
    want = _history_columns_for_chart(chart)
    cols: list[str] = []
    seen: set[str] = set()
    for c in want:
        if c in existing and c not in seen:
            seen.add(c)
            cols.append(c)
    if "ts" not in seen:
        cols.insert(0, "ts")
    return cols


def query_history(
    hours: float | None = None,
    since: float | None = None,
    until: float | None = None,
    max_points: int = 2000,
    *,
    chart: str | None = "all",
    use_cache: bool = True,
    merge_sensors: bool | None = None,
) -> list[dict]:
    """
    History for charts.
    P0: SQL time-bucket downsample · explicit columns.
    P1: short RAM cache.
    P2: chart=power|temps|dash|all column sets.
    """
    now = time.time()
    if since is None:
        if hours is None:
            hours = 24.0
        since = now - float(hours) * 3600
    if until is None:
        until = now
    since = float(since)
    until = float(until)
    if until < since:
        since, until = until, since
    max_points = max(10, min(20000, int(max_points)))
    chart_k = str(chart or "all").strip().lower() or "all"
    if merge_sensors is None:
        merge_sensors = _history_want_sensors(chart_k)

    cache_key = _history_query_cache_key(since, until, max_points, chart_k)
    if use_cache:
        with _history_query_cache_lock:
            hit = _history_query_cache.get(cache_key)
            if (
                hit
                and (now - float(hit.get("ts") or 0)) < _HISTORY_QUERY_TTL_SEC
                and isinstance(hit.get("points"), list)
            ):
                return list(hit["points"])

    span = max(1.0, until - since)
    # ~max_points buckets over the window (latest sample per bucket)
    bucket = max(1.0, span / float(max_points))

    points: list[dict] = []
    with _db_lock:
        conn = _db_connect()
        try:
            cols = _history_select_column_list(conn, chart_k)
            col_sql = ", ".join(f"s.{c}" for c in cols)
            # Fast empty check without COUNT(*) over full range
            cur = conn.execute(
                "SELECT 1 FROM samples WHERE ts >= ? AND ts <= ? LIMIT 1",
                (since, until),
            )
            if cur.fetchone() is None:
                points = []
            else:
                # One row per time bucket = MAX(ts) in bucket (keeps work_state/mode intact)
                try:
                    cur = conn.execute(
                        f"""
                        SELECT {col_sql}
                        FROM samples s
                        INNER JOIN (
                            SELECT MAX(ts) AS mts
                            FROM samples
                            WHERE ts >= ? AND ts <= ?
                            GROUP BY CAST((ts - ?) / ? AS INTEGER)
                        ) b ON s.ts = b.mts
                        ORDER BY s.ts ASC
                        LIMIT ?
                        """,
                        (since, until, since, bucket, max_points),
                    )
                    rows = cur.fetchall()
                    # drop nulls — cuts JSON size a lot (unused sm*/boards)
                    points = [
                        {k: r[k] for k in r.keys() if r[k] is not None}
                        for r in rows
                    ]
                except Exception as e:
                    # Fallback: strided fetch without loading every column twice
                    print(f"[history] bucket query fallback: {e}", flush=True)
                    cur = conn.execute(
                        f"""
                        SELECT {col_sql}
                        FROM samples s
                        WHERE s.ts >= ? AND s.ts <= ?
                        ORDER BY s.ts ASC
                        """,
                        (since, until),
                    )
                    all_rows = cur.fetchall()
                    if all_rows:
                        stride = max(
                            1, (len(all_rows) + max_points - 1) // max_points
                        )
                        points = [
                            {k: r[k] for k in r.keys() if r[k] is not None}
                            for r in all_rows[::stride][:max_points]
                        ]
        finally:
            conn.close()

    if points and merge_sensors:
        try:
            points = _merge_sensor_samples_into_points(
                points, float(since), float(until)
            )
        except Exception as e:
            print(f"[history] merge sensor samples: {e}", flush=True)

    if use_cache:
        with _history_query_cache_lock:
            # cap cache entries (simple LRU-ish: drop oldest half if large)
            if len(_history_query_cache) > 24:
                items = sorted(
                    _history_query_cache.items(),
                    key=lambda kv: float(kv[1].get("ts") or 0),
                )
                for k, _ in items[:12]:
                    _history_query_cache.pop(k, None)
            _history_query_cache[cache_key] = {
                "ts": time.time(),
                "points": list(points),
            }
    return points


def history_stats(*, use_cache: bool = True) -> dict:
    """DB totals for history. Cached ~15s (P1) — not a full scan every chart paint."""
    now = time.time()
    if use_cache:
        data = _history_stats_cache.get("data")
        ts0 = float(_history_stats_cache.get("ts") or 0)
        if data is not None and (now - ts0) < _HISTORY_STATS_TTL_SEC:
            return dict(data)

    with _db_lock:
        conn = _db_connect()
        try:
            cur = conn.execute(
                "SELECT COUNT(*) AS c, MIN(ts) AS tmin, MAX(ts) AS tmax FROM samples"
            )
            row = cur.fetchone()
            out = {
                "count": int(row["c"] or 0),
                "oldest_ts": row["tmin"],
                "newest_ts": row["tmax"],
                "oldest_iso": datetime.fromtimestamp(row["tmin"]).isoformat(
                    timespec="seconds"
                )
                if row["tmin"]
                else None,
                "newest_iso": datetime.fromtimestamp(row["tmax"]).isoformat(
                    timespec="seconds"
                )
                if row["tmax"]
                else None,
                "db_path": str(DB_FILE),
                "db_size_bytes": DB_FILE.stat().st_size if DB_FILE.exists() else 0,
            }
        finally:
            conn.close()
    _history_stats_cache["ts"] = time.time()
    _history_stats_cache["data"] = dict(out)
    return out


# ── Energy accounting (energy.db meters + hold integration) ──────────────────
# Virtual meter: hold current miner power W until next sample → kWh.
# Physical meters: schema reserved for future external counters.

DEFAULT_ENERGY_CFG: dict = {
    # ── metering process (Advanced settings) ──
    "metering_enabled": True,
    # hold = power constant until next sample; trap = trapezoid (legacy/optional)
    "integration": "hold",
    # if True — tick from history collector when a live sample is taken
    "attach_to_history": True,
    # used when attach_to_history is false (own loop interval)
    "metering_interval_sec": 30,
    # gaps larger than this do not accumulate (no fake kWh)
    "max_gap_sec": 900,
    # energy_samples retention
    "retention_days": 365,
    # default virtual meter source
    "virtual_source": "miner_power",
    # one-shot: import history.db → energy.db on first init only (never after reset)
    "history_backfill_done": False,
    "history_backfill_at": None,
    "history_backfill_samples": 0,
    # ── tariff (Miner → Energy) ──
    "currency": "RUB",
    "currency_symbol": "₽",
    # 1zone | 2zone | 3zone  (legacy: flat / day_night)
    "tariff_mode": "1zone",
    # 1-zone
    "price_kwh": 5.0,
    # 2-zone (day = non-night)
    "price_day_kwh": 6.0,
    "price_night_kwh": 3.0,
    "night_start": "23:00",
    "night_end": "07:00",
    # 3-zone: peak / mid (semi-peak) / night; priority night > peak > mid
    "price_peak_kwh": 8.0,
    "price_mid_kwh": 6.0,
    "peak1_start": "07:00",
    "peak1_end": "10:00",
    "peak2_start": "17:00",
    "peak2_end": "21:00",
}

_energy_cfg_lock = threading.Lock()
_energy_cfg: dict = dict(DEFAULT_ENERGY_CFG)

_ENERGY_TIME_KEYS = (
    "night_start",
    "night_end",
    "peak1_start",
    "peak1_end",
    "peak2_start",
    "peak2_end",
)
_ENERGY_PRICE_KEYS = (
    "price_kwh",
    "price_day_kwh",
    "price_night_kwh",
    "price_peak_kwh",
    "price_mid_kwh",
)


def _parse_hhmm(s: str, default_h: int = 0, default_m: int = 0) -> int:
    """Return minutes from midnight."""
    try:
        parts = str(s or "").strip().split(":")
        h = int(parts[0])
        m = int(parts[1]) if len(parts) > 1 else 0
        return max(0, min(23, h)) * 60 + max(0, min(59, m))
    except Exception:
        return default_h * 60 + default_m


def _fmt_hhmm(mins: int) -> str:
    mins = int(mins) % (24 * 60)
    return f"{mins // 60:02d}:{mins % 60:02d}"


def _energy_normalize_mode(mode: str | None) -> str:
    m = str(mode or "1zone").strip().lower().replace("-", "_").replace(" ", "")
    if m in (
        "1zone",
        "1",
        "one",
        "single",
        "flat",
        "однозонный",
        "однозонн",
        "1зон",
        "zone1",
    ):
        return "1zone"
    if m in (
        "2zone",
        "2",
        "two",
        "day_night",
        "daynight",
        "tou",
        "двухзонный",
        "двухзонн",
        "2зон",
        "zone2",
    ):
        return "2zone"
    if m in (
        "3zone",
        "3",
        "three",
        "triple",
        "трёхзонный",
        "трехзонный",
        "трёхзонн",
        "трехзонн",
        "3зон",
        "zone3",
    ):
        return "3zone"
    return "1zone"


def _energy_normalize_cfg(raw: dict | None) -> dict:
    c = dict(DEFAULT_ENERGY_CFG)
    if isinstance(raw, dict):
        c.update({k: raw[k] for k in DEFAULT_ENERGY_CFG if k in raw})
    c["tariff_mode"] = _energy_normalize_mode(c.get("tariff_mode"))
    c["currency"] = (str(c.get("currency") or "RUB").strip() or "RUB")[:8].upper()
    sym = str(c.get("currency_symbol") or "").strip()
    if not sym:
        sym = {"RUB": "₽", "USD": "$", "EUR": "€", "UAH": "₴", "KZT": "₸"}.get(
            c["currency"], c["currency"]
        )
    c["currency_symbol"] = sym[:4]
    for k in _ENERGY_PRICE_KEYS:
        try:
            c[k] = max(0.0, float(c.get(k) if c.get(k) is not None else DEFAULT_ENERGY_CFG[k]))
        except (TypeError, ValueError):
            c[k] = float(DEFAULT_ENERGY_CFG[k])
    for k in _ENERGY_TIME_KEYS:
        default = str(DEFAULT_ENERGY_CFG[k])
        val = str(c.get(k) or default).strip() or default
        # normalize to HH:MM
        c[k] = _fmt_hhmm(_parse_hhmm(val, *_parse_hhmm_defaults(default)))
    c["metering_enabled"] = bool(c.get("metering_enabled", True))
    c["attach_to_history"] = bool(c.get("attach_to_history", True))
    c["history_backfill_done"] = bool(c.get("history_backfill_done", False))
    if c.get("history_backfill_at") is not None:
        c["history_backfill_at"] = str(c.get("history_backfill_at") or "") or None
    try:
        c["history_backfill_samples"] = max(0, int(c.get("history_backfill_samples") or 0))
    except (TypeError, ValueError):
        c["history_backfill_samples"] = 0
    integ = str(c.get("integration") or "hold").strip().lower()
    c["integration"] = "trap" if integ in ("trap", "trapezoid", "trapezoidal") else "hold"
    try:
        c["max_gap_sec"] = max(60, min(7200, int(c.get("max_gap_sec") or 900)))
    except (TypeError, ValueError):
        c["max_gap_sec"] = 900
    try:
        c["metering_interval_sec"] = max(5, min(3600, int(c.get("metering_interval_sec") or 30)))
    except (TypeError, ValueError):
        c["metering_interval_sec"] = 30
    try:
        c["retention_days"] = max(1, min(3650, int(c.get("retention_days") or 365)))
    except (TypeError, ValueError):
        c["retention_days"] = 365
    c["virtual_source"] = str(c.get("virtual_source") or "miner_power").strip() or "miner_power"
    return c


def _parse_hhmm_defaults(s: str) -> tuple[int, int]:
    try:
        parts = str(s).split(":")
        return int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
    except Exception:
        return 0, 0


def _load_energy_cfg() -> None:
    global _energy_cfg
    with _energy_cfg_lock:
        _energy_cfg = _energy_normalize_cfg(_load_json(ENERGY_CFG_FILE, DEFAULT_ENERGY_CFG))


def _save_energy_cfg() -> None:
    with _energy_cfg_lock:
        _save_json(ENERGY_CFG_FILE, _energy_cfg)


def get_energy_cfg() -> dict:
    with _energy_cfg_lock:
        return dict(_energy_cfg)


def set_energy_cfg(patch: dict) -> dict:
    global _energy_cfg
    if not isinstance(patch, dict):
        raise ValueError("body must be object")
    with _energy_cfg_lock:
        merged = dict(_energy_cfg)
        for k in DEFAULT_ENERGY_CFG:
            if k in patch and patch[k] is not None:
                merged[k] = patch[k]
        # allow nested "config" from UI
        if isinstance(patch.get("config"), dict):
            for k in DEFAULT_ENERGY_CFG:
                if k in patch["config"] and patch["config"][k] is not None:
                    merged[k] = patch["config"][k]
        _energy_cfg = _energy_normalize_cfg(merged)
        cfg = dict(_energy_cfg)
    _save_energy_cfg()
    return cfg


# ── energy.db (virtual + physical meters) ────────────────────────────────────

_energy_db_lock = threading.Lock()
_energy_db_ready = False


def _energy_db_connect() -> sqlite3.Connection:
    conn = sqlite3.connect(str(ENERGY_DB_FILE), check_same_thread=False, timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    return conn


def _ensure_energy_db() -> None:
    """Create energy.db schema and default virtual meter."""
    global _energy_db_ready
    if _energy_db_ready and ENERGY_DB_FILE.is_file():
        return
    with _energy_db_lock:
        if _energy_db_ready and ENERGY_DB_FILE.is_file():
            return
        conn = _energy_db_connect()
        try:
            conn.executescript(
                """
                CREATE TABLE IF NOT EXISTS meters (
                    id TEXT PRIMARY KEY,
                    type TEXT NOT NULL,          -- virtual | physical
                    name TEXT NOT NULL,
                    enabled INTEGER NOT NULL DEFAULT 1,
                    source TEXT,                 -- miner_power | modbus | shelly | …
                    source_config TEXT,          -- JSON for physical drivers (future)
                    unit TEXT NOT NULL DEFAULT 'kWh',
                    created_ts REAL NOT NULL
                );
                CREATE TABLE IF NOT EXISTS meter_state (
                    meter_id TEXT PRIMARY KEY,
                    last_ts REAL,
                    last_power_w REAL,
                    total_kwh REAL NOT NULL DEFAULT 0,
                    updated_ts REAL,
                    FOREIGN KEY (meter_id) REFERENCES meters(id)
                );
                CREATE TABLE IF NOT EXISTS energy_samples (
                    meter_id TEXT NOT NULL,
                    ts REAL NOT NULL,
                    power_w REAL,               -- power held for interval ending at ts
                    delta_kwh REAL NOT NULL DEFAULT 0,
                    total_kwh REAL NOT NULL DEFAULT 0,
                    online INTEGER,
                    PRIMARY KEY (meter_id, ts)
                );
                CREATE INDEX IF NOT EXISTS idx_energy_samples_ts
                    ON energy_samples(meter_id, ts);
                """
            )
            # default virtual meter (calculated from miner power)
            now = time.time()
            conn.execute(
                """
                INSERT OR IGNORE INTO meters
                    (id, type, name, enabled, source, source_config, unit, created_ts)
                VALUES (?, 'virtual', ?, 1, 'miner_power', NULL, 'kWh', ?)
                """,
                (VIRTUAL_METER_ID, "Virtual · miner power", now),
            )
            conn.execute(
                """
                INSERT OR IGNORE INTO meter_state
                    (meter_id, last_ts, last_power_w, total_kwh, updated_ts)
                VALUES (?, NULL, NULL, 0, ?)
                """,
                (VIRTUAL_METER_ID, now),
            )
            conn.commit()
        finally:
            conn.close()
        _energy_db_ready = True


def list_energy_meters() -> list[dict]:
    _ensure_energy_db()
    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            rows = conn.execute(
                """
                SELECT m.*, s.last_ts, s.last_power_w, s.total_kwh, s.updated_ts
                FROM meters m
                LEFT JOIN meter_state s ON s.meter_id = m.id
                ORDER BY m.type, m.name
                """
            ).fetchall()
            out = []
            for r in rows:
                d = dict(r)
                d["enabled"] = bool(d.get("enabled"))
                if d.get("total_kwh") is not None:
                    d["total_kwh"] = round(float(d["total_kwh"]), 4)
                if d.get("last_power_w") is not None:
                    try:
                        d["last_power_w"] = round(float(d["last_power_w"]), 1)
                    except (TypeError, ValueError):
                        pass
                out.append(d)
            return out
        finally:
            conn.close()


def energy_meter_tick(
    power_w: float | None,
    *,
    ts: float | None = None,
    online: bool = True,
    meter_id: str = VIRTUAL_METER_ID,
) -> dict | None:
    """
    Hold-scheme sample for a meter.

    Previous power is held constant until this sample:
        delta_kWh = last_power_W × (ts − last_ts) / 3_600_000
    Then store last_power = current power for the next interval.
    """
    cfg = get_energy_cfg()
    if not cfg.get("metering_enabled", True):
        return None
    if meter_id != VIRTUAL_METER_ID:
        # physical drivers not implemented yet
        return None
    _ensure_energy_db()
    now = float(ts if ts is not None else time.time())
    try:
        pw = float(power_w) if power_w is not None and online else 0.0
    except (TypeError, ValueError):
        pw = 0.0
    if not math.isfinite(pw) or pw < 0:
        pw = 0.0
    max_gap = float(cfg.get("max_gap_sec") or 900)
    integ = str(cfg.get("integration") or "hold")

    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            st = conn.execute(
                "SELECT last_ts, last_power_w, total_kwh FROM meter_state WHERE meter_id = ?",
                (meter_id,),
            ).fetchone()
            if not st:
                conn.execute(
                    """
                    INSERT OR IGNORE INTO meters
                        (id, type, name, enabled, source, unit, created_ts)
                    VALUES (?, 'virtual', ?, 1, 'miner_power', 'kWh', ?)
                    """,
                    (meter_id, "Virtual · miner power", now),
                )
                conn.execute(
                    """
                    INSERT INTO meter_state (meter_id, last_ts, last_power_w, total_kwh, updated_ts)
                    VALUES (?, ?, ?, 0, ?)
                    """,
                    (meter_id, now, pw, now),
                )
                conn.commit()
                return {
                    "meter_id": meter_id,
                    "delta_kwh": 0.0,
                    "total_kwh": 0.0,
                    "power_w": pw,
                    "ts": now,
                }

            last_ts = st["last_ts"]
            last_pw = st["last_power_w"]
            total = float(st["total_kwh"] or 0)
            delta = 0.0
            if last_ts is not None and last_pw is not None:
                dt = now - float(last_ts)
                if 0 < dt <= max_gap:
                    try:
                        lp = float(last_pw)
                    except (TypeError, ValueError):
                        lp = 0.0
                    if not math.isfinite(lp) or lp < 0:
                        lp = 0.0
                    if integ == "trap":
                        # optional: average with new power
                        mid = (lp + pw) / 2.0
                        delta = mid * dt / 3600.0 / 1000.0
                    else:
                        # hold: previous power constant until this sample
                        delta = lp * dt / 3600.0 / 1000.0
                    total += delta
            conn.execute(
                """
                INSERT OR REPLACE INTO energy_samples
                    (meter_id, ts, power_w, delta_kwh, total_kwh, online)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    meter_id,
                    now,
                    float(last_pw) if last_pw is not None and delta > 0 else pw,
                    delta,
                    total,
                    1 if online else 0,
                ),
            )
            conn.execute(
                """
                UPDATE meter_state
                SET last_ts = ?, last_power_w = ?, total_kwh = ?, updated_ts = ?
                WHERE meter_id = ?
                """,
                (now, pw, total, now, meter_id),
            )
            conn.commit()
            return {
                "meter_id": meter_id,
                "delta_kwh": round(delta, 6),
                "total_kwh": round(total, 4),
                "power_w": pw,
                "ts": now,
            }
        finally:
            conn.close()


def energy_meter_tick_from_live(live: dict | None) -> dict | None:
    """Extract power from live payload and tick virtual meter."""
    if not isinstance(live, dict):
        return None
    cfg = get_energy_cfg()
    if not cfg.get("metering_enabled", True):
        return None
    online = True
    if live.get("ok") is False:
        online = False
    if live.get("online") in (0, "0", False):
        online = False
    pw = None
    for k in ("power_w", "power", "Power", "avg_power"):
        if live.get(k) is not None:
            try:
                pw = float(live[k])
                break
            except (TypeError, ValueError):
                pass
    # nested summary
    if pw is None and isinstance(live.get("summary"), dict):
        for k in ("power_w", "power", "Power"):
            if live["summary"].get(k) is not None:
                try:
                    pw = float(live["summary"][k])
                    break
                except (TypeError, ValueError):
                    pass
    ts = live.get("ts") or live.get("timestamp") or time.time()
    try:
        ts = float(ts)
    except (TypeError, ValueError):
        ts = time.time()
    return energy_meter_tick(pw, ts=ts, online=online)


def prune_energy_samples(retention_days: int | None = None) -> int:
    cfg = get_energy_cfg()
    days = int(retention_days if retention_days is not None else cfg.get("retention_days") or 365)
    cutoff = time.time() - max(1, days) * 86400
    _ensure_energy_db()
    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            cur = conn.execute("DELETE FROM energy_samples WHERE ts < ?", (cutoff,))
            conn.commit()
            return int(cur.rowcount or 0)
        finally:
            conn.close()


def _mark_history_backfill_done(*, samples: int = 0) -> None:
    """Persist one-shot flag so history.db is never re-imported after first init/reset."""
    set_energy_cfg(
        {
            "history_backfill_done": True,
            "history_backfill_at": datetime.now().isoformat(timespec="seconds"),
            "history_backfill_samples": int(samples),
        }
    )


def backfill_energy_from_history(*, force: bool = False) -> dict:
    """
    One-shot: build virtual meter samples from history.db power (hold scheme).

    Runs only once after the energy feature is introduced (or force=True for admin).
    After reset of energy.db the flag stays set — history is NOT imported again.
    If live energy samples already exist, only older history (ts < first energy sample)
    is prepended.
    """
    cfg = get_energy_cfg()
    if not force and cfg.get("history_backfill_done"):
        return {
            "ok": True,
            "skipped": True,
            "reason": "already_done",
            "at": cfg.get("history_backfill_at"),
            "samples": cfg.get("history_backfill_samples"),
        }

    _ensure_energy_db()
    max_gap = float(cfg.get("max_gap_sec") or 900)
    hold = str(cfg.get("integration") or "hold") != "trap"
    meter_id = VIRTUAL_METER_ID

    # oldest energy sample (if any) — only import history before it
    oldest_energy_ts = None
    energy_count = 0
    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            row = conn.execute(
                "SELECT COUNT(*) AS c, MIN(ts) AS tmin FROM energy_samples WHERE meter_id = ?",
                (meter_id,),
            ).fetchone()
            energy_count = int(row["c"] or 0)
            if row["tmin"] is not None:
                oldest_energy_ts = float(row["tmin"])
        finally:
            conn.close()

    # load history power series
    hist_points: list[tuple[float, float, int]] = []
    try:
        with _db_lock:
            conn = _db_connect()
            try:
                cols = {r[1] for r in conn.execute("PRAGMA table_info(samples)").fetchall()}
                if "power" not in cols:
                    _mark_history_backfill_done(samples=0)
                    return {"ok": True, "skipped": True, "reason": "no_power_column"}
                if "online" in cols:
                    cur = conn.execute(
                        """
                        SELECT ts, power, online FROM samples
                        WHERE power IS NOT NULL
                        ORDER BY ts ASC
                        """
                    )
                else:
                    cur = conn.execute(
                        """
                        SELECT ts, power, 1 AS online FROM samples
                        WHERE power IS NOT NULL
                        ORDER BY ts ASC
                        """
                    )
                for r in cur.fetchall():
                    try:
                        ts = float(r["ts"])
                        pw = float(r["power"])
                    except (TypeError, ValueError):
                        continue
                    if not math.isfinite(ts) or not math.isfinite(pw) or pw < 0:
                        continue
                    online = 1
                    try:
                        if r["online"] is not None and int(r["online"]) == 0:
                            online = 0
                            pw = 0.0
                    except (TypeError, ValueError, KeyError):
                        pass
                    if oldest_energy_ts is not None and ts >= oldest_energy_ts - 1e-6:
                        break
                    hist_points.append((ts, pw, online))
            finally:
                conn.close()
    except Exception as e:
        return {"ok": False, "error": f"history read: {e}"}

    if not hist_points:
        _mark_history_backfill_done(samples=0)
        return {
            "ok": True,
            "skipped": True,
            "reason": "no_history" if energy_count == 0 else "nothing_older",
            "energy_samples_before": energy_count,
        }

    # hold integration over history points
    rows_out: list[tuple] = []
    total = 0.0
    last_ts: float | None = None
    last_pw: float | None = None
    for ts, pw, online in hist_points:
        delta = 0.0
        if last_ts is not None and last_pw is not None:
            dt = ts - last_ts
            if 0 < dt <= max_gap:
                if hold:
                    delta = float(last_pw) * dt / 3600.0 / 1000.0
                else:
                    delta = (float(last_pw) + float(pw)) / 2.0 * dt / 3600.0 / 1000.0
                total += delta
        held_pw = float(last_pw) if (last_pw is not None and delta > 0) else float(pw)
        rows_out.append((meter_id, ts, held_pw, delta, total, int(online)))
        last_ts = ts
        last_pw = float(pw)

    # Write into energy.db. If live samples already exist, prepend older history
    # and shift existing total_kwh by the imported prefix (keep live deltas).
    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            if energy_count == 0:
                conn.execute("DELETE FROM energy_samples WHERE meter_id = ?", (meter_id,))
                if rows_out:
                    conn.executemany(
                        """
                        INSERT OR REPLACE INTO energy_samples
                            (meter_id, ts, power_w, delta_kwh, total_kwh, online)
                        VALUES (?, ?, ?, ?, ?, ?)
                        """,
                        rows_out,
                    )
                conn.execute(
                    """
                    UPDATE meter_state
                    SET last_ts = ?, last_power_w = ?, total_kwh = ?, updated_ts = ?
                    WHERE meter_id = ?
                    """,
                    (last_ts, last_pw, total, time.time(), meter_id),
                )
            else:
                if rows_out:
                    conn.executemany(
                        """
                        INSERT OR IGNORE INTO energy_samples
                            (meter_id, ts, power_w, delta_kwh, total_kwh, online)
                        VALUES (?, ?, ?, ?, ?, ?)
                        """,
                        rows_out,
                    )
                    # shift totals of samples that already existed (ts >= first live)
                    conn.execute(
                        """
                        UPDATE energy_samples
                        SET total_kwh = total_kwh + ?
                        WHERE meter_id = ? AND ts >= ?
                        """,
                        (total, meter_id, oldest_energy_ts),
                    )
                    conn.execute(
                        """
                        UPDATE meter_state
                        SET total_kwh = total_kwh + ?, updated_ts = ?
                        WHERE meter_id = ?
                        """,
                        (total, time.time(), meter_id),
                    )
            conn.commit()
        finally:
            conn.close()

    imported = len(rows_out)
    _mark_history_backfill_done(samples=imported)
    print(
        f"[energy] history backfill: imported={imported} "
        f"energy_before={energy_count} prefix_kwh≈{total:.3f}"
    )
    return {
        "ok": True,
        "skipped": False,
        "imported": imported,
        "energy_samples_before": energy_count,
        "history_points": len(hist_points),
        "total_kwh_prefix": round(total, 4),
    }


def maybe_backfill_energy_from_history() -> dict:
    """Called once at service start (safe if already done)."""
    try:
        return backfill_energy_from_history(force=False)
    except Exception as e:
        print(f"[energy] history backfill failed: {e}")
        # do not set done flag on hard failure — retry next boot
        return {"ok": False, "error": str(e)}


def reset_energy_meter(meter_id: str = VIRTUAL_METER_ID, *, clear_samples: bool = False) -> dict:
    """Reset cumulative total (optional wipe samples). Does NOT re-import history.db."""
    _ensure_energy_db()
    now = time.time()
    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            if clear_samples:
                conn.execute("DELETE FROM energy_samples WHERE meter_id = ?", (meter_id,))
            conn.execute(
                """
                UPDATE meter_state
                SET total_kwh = 0, last_ts = NULL, last_power_w = NULL, updated_ts = ?
                WHERE meter_id = ?
                """,
                (now, meter_id),
            )
            conn.commit()
            out = {"ok": True, "meter_id": meter_id, "total_kwh": 0.0}
        finally:
            conn.close()
    # Never auto-import history again after an explicit reset
    try:
        _mark_history_backfill_done(samples=0)
        out["history_backfill_done"] = True
        out["note"] = "history.db will not be re-imported"
    except Exception as e:
        out["history_backfill_warn"] = str(e)
    return out


def _query_energy_deltas(
    since: float, until: float, meter_id: str = VIRTUAL_METER_ID
) -> list[tuple[float, float, float]]:
    """Return [(ts, delta_kwh, power_w), ...] from energy.db."""
    _ensure_energy_db()
    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            rows = conn.execute(
                """
                SELECT ts, delta_kwh, power_w FROM energy_samples
                WHERE meter_id = ? AND ts > ? AND ts <= ? AND delta_kwh IS NOT NULL
                ORDER BY ts ASC
                """,
                (meter_id, since, until),
            ).fetchall()
            out = []
            for r in rows:
                try:
                    ts = float(r["ts"])
                    d = float(r["delta_kwh"] or 0)
                    pw = float(r["power_w"]) if r["power_w"] is not None else 0.0
                except (TypeError, ValueError):
                    continue
                out.append((ts, d, pw))
            return out
        finally:
            conn.close()


def _energy_bucket_key(ts: float, bucket: str) -> tuple:
    """
    Return (sort_key, label, bucket_start_ts, bucket_end_ts) for local time.
    bucket: hour | day | week | month
    """
    lt = time.localtime(ts)
    b = (bucket or "hour").strip().lower()
    if b in ("h", "hr", "hours"):
        b = "hour"
    elif b in ("d", "days"):
        b = "day"
    elif b in ("w", "weeks"):
        b = "week"
    elif b in ("m", "mo", "months"):
        b = "month"
    else:
        b = b if b in ("hour", "day", "week", "month") else "hour"

    if b == "hour":
        start = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday, lt.tm_hour, 0, 0, 0, 0, -1))
        end = start + 3600
        label = time.strftime("%d.%m %H:00", time.localtime(start))
        key = (lt.tm_year, lt.tm_mon, lt.tm_mday, lt.tm_hour)
    elif b == "day":
        start = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday, 0, 0, 0, 0, 0, -1))
        end = start + 86400
        label = time.strftime("%d.%m", time.localtime(start))
        key = (lt.tm_year, lt.tm_mon, lt.tm_mday)
    elif b == "week":
        # ISO week: Monday start
        day_start = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday, 0, 0, 0, 0, 0, -1))
        # tm_wday: Mon=0 .. Sun=6
        start = day_start - lt.tm_wday * 86400
        end = start + 7 * 86400
        iso = time.strftime("%G-W%V", time.localtime(start))
        label = iso
        y, w, _ = time.strftime("%G %V %u", time.localtime(start)).split()
        key = (int(y), int(w))
    else:  # month
        start = time.mktime((lt.tm_year, lt.tm_mon, 1, 0, 0, 0, 0, 0, -1))
        if lt.tm_mon == 12:
            end = time.mktime((lt.tm_year + 1, 1, 1, 0, 0, 0, 0, 0, -1))
        else:
            end = time.mktime((lt.tm_year, lt.tm_mon + 1, 1, 0, 0, 0, 0, 0, -1))
        label = time.strftime("%Y-%m", time.localtime(start))
        key = (lt.tm_year, lt.tm_mon)
    return key, label, float(start), float(end)


# energy_series response cache (query key → {ts, body})
_energy_series_cache_lock = threading.Lock()
_energy_series_cache: dict[tuple, dict] = {}
_ENERGY_SERIES_CACHE_TTL_SEC = 30.0
_ENERGY_SERIES_CACHE_MAX = 24


def _energy_series_bucket_sql_expr(bucket: str) -> str:
    """
    SQLite expression for local-time bucket key (string).
    hour → 'YYYY-MM-DD HH'; day → 'YYYY-MM-DD'; week → 'YYYY-Www'; month → 'YYYY-MM'
    """
    b = bucket if bucket in ("hour", "day", "week", "month") else "hour"
    base = "ts, 'unixepoch', 'localtime'"
    if b == "hour":
        return f"strftime('%Y-%m-%d %H', {base})"
    if b == "day":
        return f"strftime('%Y-%m-%d', {base})"
    if b == "week":
        # ISO year-week (matches Python %G-W%V style key loosely)
        return f"strftime('%G-W%V', {base})"
    return f"strftime('%Y-%m', {base})"


def energy_series(
    *,
    hours: float | None = None,
    bucket: str = "hour",
    max_points: int = 500,
    meter_id: str = VIRTUAL_METER_ID,
) -> dict:
    """
    Aggregated energy chart series from energy.db.

    bucket: hour | day | week | month
    Each point: bar kWh (sum of hold deltas) + avg_power_w (continuous mean)
    + max_power_w (peak hold power in bucket — "full power" line on chart).

    Optimizations:
      1) SQL GROUP BY bucket (not full raw fetch + Python loop)
      2) 30s response cache
      3) tariff/cost once per bucket (not per sample)
    """
    cfg = get_energy_cfg()
    now = time.time()
    b = (bucket or "hour").strip().lower()
    if b in ("h", "hr", "hours"):
        b = "hour"
    elif b in ("d", "days"):
        b = "day"
    elif b in ("w", "weeks"):
        b = "week"
    elif b in ("m", "mo", "months"):
        b = "month"
    if b not in ("hour", "day", "week", "month"):
        b = "hour"

    # default lookback by bucket if hours omitted
    default_hours = {
        "hour": 48.0,
        "day": 30 * 24.0,
        "week": 16 * 7 * 24.0,
        "month": 24 * 30.0,
    }
    try:
        if hours is None:
            hours = default_hours.get(b, 48.0)
        else:
            hours = max(1.0, min(24 * 400, float(hours)))
    except (TypeError, ValueError):
        hours = default_hours.get(b, 48.0)
    try:
        max_points = max(12, min(2000, int(max_points)))
    except (TypeError, ValueError):
        max_points = 500

    # stabilize cache window (30s slots) so concurrent UI polls hit the same key
    cache_slot = int(now // _ENERGY_SERIES_CACHE_TTL_SEC)
    until = float(cache_slot * _ENERGY_SERIES_CACHE_TTL_SEC) + (
        _ENERGY_SERIES_CACHE_TTL_SEC - 0.001
    )
    # don't go past real now
    until = min(until, now + 1.0)
    since = until - hours * 3600.0
    cache_key = (
        str(meter_id),
        b,
        round(float(hours), 3),
        int(max_points),
        int(cache_slot),
    )
    with _energy_series_cache_lock:
        hit = _energy_series_cache.get(cache_key)
        if (
            isinstance(hit, dict)
            and (now - float(hit.get("ts") or 0)) < _ENERGY_SERIES_CACHE_TTL_SEC
            and isinstance(hit.get("body"), dict)
        ):
            body = dict(hit["body"])
            body["cache"] = "HIT"
            return body

    _ensure_energy_db()
    b_expr = _energy_series_bucket_sql_expr(b)
    sample_count = 0
    agg_rows: list[dict] = []
    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            # total raw samples in window (for UI meta) — cheap COUNT
            try:
                sample_count = int(
                    conn.execute(
                        """
                        SELECT COUNT(*) FROM energy_samples
                        WHERE meter_id = ? AND ts >= ? AND ts <= ?
                        """,
                        (meter_id, since, until),
                    ).fetchone()[0]
                    or 0
                )
            except Exception:
                sample_count = 0
            # SQL aggregate: one row per local-time bucket
            sql = f"""
                SELECT
                    {b_expr} AS bkey,
                    MIN(ts) AS first_ts,
                    MAX(ts) AS last_ts,
                    SUM(CASE
                        WHEN delta_kwh IS NOT NULL AND delta_kwh > 0
                        THEN delta_kwh ELSE 0 END) AS kwh,
                    SUM(CASE
                        WHEN power_w IS NOT NULL AND power_w >= 0
                        THEN power_w ELSE 0 END) AS pw_sum,
                    SUM(CASE
                        WHEN power_w IS NOT NULL AND power_w >= 0
                             AND delta_kwh IS NOT NULL AND delta_kwh > 0
                        THEN power_w * delta_kwh ELSE 0 END) AS pw_wsum,
                    SUM(CASE
                        WHEN power_w IS NOT NULL AND power_w >= 0
                             AND delta_kwh IS NOT NULL AND delta_kwh > 0
                        THEN delta_kwh ELSE 0 END) AS pw_w,
                    MAX(power_w) AS pw_max,
                    COUNT(*) AS n
                FROM energy_samples
                WHERE meter_id = ? AND ts >= ? AND ts <= ?
                GROUP BY bkey
                ORDER BY bkey ASC
            """
            rows = conn.execute(sql, (meter_id, since, until)).fetchall()
            for r in rows:
                try:
                    first_ts = float(r["first_ts"])
                    last_ts = float(r["last_ts"])
                    kwh = float(r["kwh"] or 0)
                    n = int(r["n"] or 0)
                except (TypeError, ValueError):
                    continue
                if not math.isfinite(kwh):
                    kwh = 0.0
                try:
                    pw_sum = float(r["pw_sum"] or 0)
                except (TypeError, ValueError):
                    pw_sum = 0.0
                try:
                    pw_wsum = float(r["pw_wsum"] or 0)
                except (TypeError, ValueError):
                    pw_wsum = 0.0
                try:
                    pw_w = float(r["pw_w"] or 0)
                except (TypeError, ValueError):
                    pw_w = 0.0
                try:
                    pw_max = (
                        float(r["pw_max"])
                        if r["pw_max"] is not None
                        else None
                    )
                except (TypeError, ValueError):
                    pw_max = None
                if pw_max is not None and not math.isfinite(pw_max):
                    pw_max = None
                agg_rows.append(
                    {
                        "first_ts": first_ts,
                        "last_ts": last_ts,
                        "kwh": max(0.0, kwh),
                        "n": n,
                        "pw_sum": pw_sum,
                        "pw_wsum": pw_wsum,
                        "pw_w": pw_w,
                        "pw_max": pw_max,
                    }
                )
        finally:
            conn.close()

    if not agg_rows:
        body = {
            "ok": True,
            "points": [],
            "bucket": b,
            "hours": hours,
            "count": 0,
            "returned": 0,
            "meter_id": meter_id,
            "from_ts": since,
            "to_ts": now,
            "from_iso": datetime.fromtimestamp(since).isoformat(timespec="seconds"),
            "to_iso": datetime.fromtimestamp(now).isoformat(timespec="seconds"),
            "integration": cfg.get("integration") or "hold",
            "cache": "MISS",
        }
        with _energy_series_cache_lock:
            _energy_series_cache[cache_key] = {"ts": now, "body": dict(body)}
        return body

    points: list[dict] = []
    for row in agg_rows:
        first_ts = row["first_ts"]
        last_ts = row["last_ts"]
        # calendar bucket bounds from first sample (local time) — once per bucket
        _key, label, b_start, b_end = _energy_bucket_key(first_ts, b)
        b_end_use = min(float(b_end), now)
        kwh = float(row["kwh"])
        n = int(row["n"])
        # cost: one tariff lookup at bucket mid (not per sample)
        mid_ts = (float(b_start) + float(b_end_use)) / 2.0
        try:
            price = _energy_price_at(mid_ts, cfg)
            cost = kwh * float(price)
        except Exception:
            cost = 0.0
        span_h = max((last_ts - first_ts) / 3600.0, 1.0 / 60.0)
        nom_h = max((b_end_use - float(b_start)) / 3600.0, 1e-6)
        avg_from_energy = (kwh / span_h) * 1000.0 if kwh > 0 else None
        pw_w = float(row["pw_w"] or 0)
        pw_wsum = float(row["pw_wsum"] or 0)
        pw_sum = float(row["pw_sum"] or 0)
        if pw_w > 0:
            avg_w = pw_wsum / pw_w
        elif avg_from_energy is not None:
            avg_w = avg_from_energy
        elif n > 0 and pw_sum > 0:
            avg_w = pw_sum / n
        else:
            avg_w = None
        if kwh > 0 and nom_h >= 0.25 and span_h >= nom_h * 0.5:
            avg_w = (kwh / nom_h) * 1000.0
        max_w = row["pw_max"]
        if max_w is None and avg_w is not None:
            max_w = avg_w
        points.append(
            {
                "ts": float(b_start),
                "ts_end": b_end_use,
                "label": label,
                "kwh": round(kwh, 4),
                "cost": round(cost, 2),
                "avg_power_w": (
                    round(avg_w, 1)
                    if avg_w is not None and math.isfinite(avg_w)
                    else None
                ),
                "max_power_w": (
                    round(max_w, 1)
                    if max_w is not None and math.isfinite(max_w)
                    else None
                ),
                "samples": n,
            }
        )

    # cap points (keep most recent)
    if len(points) > max_points:
        points = points[-max_points:]

    body = {
        "ok": True,
        "points": points,
        "bucket": b,
        "hours": hours,
        "count": sample_count,
        "returned": len(points),
        "meter_id": meter_id,
        "from_ts": since,
        "to_ts": now,
        "from_iso": datetime.fromtimestamp(since).isoformat(timespec="seconds"),
        "to_iso": datetime.fromtimestamp(now).isoformat(timespec="seconds"),
        "integration": cfg.get("integration") or "hold",
        "cache": "MISS",
    }
    with _energy_series_cache_lock:
        _energy_series_cache[cache_key] = {"ts": now, "body": dict(body)}
        # bound memory
        if len(_energy_series_cache) > _ENERGY_SERIES_CACHE_MAX:
            # drop oldest entries
            items = sorted(
                _energy_series_cache.items(),
                key=lambda kv: float((kv[1] or {}).get("ts") or 0),
            )
            for k, _ in items[: max(0, len(items) - _ENERGY_SERIES_CACHE_MAX)]:
                _energy_series_cache.pop(k, None)
    return body


def _sum_energy_period(
    since: float, until: float, cfg: dict, meter_id: str = VIRTUAL_METER_ID
) -> dict:
    """Sum stored hold deltas and price with current tariff at each sample ts."""
    rows = _query_energy_deltas(since, until, meter_id)
    by_zone: dict[str, dict[str, float]] = {
        "flat": {"kwh": 0.0, "cost": 0.0},
        "day": {"kwh": 0.0, "cost": 0.0},
        "night": {"kwh": 0.0, "cost": 0.0},
        "peak": {"kwh": 0.0, "cost": 0.0},
        "mid": {"kwh": 0.0, "cost": 0.0},
    }
    kwh = 0.0
    cost = 0.0
    span_sec = 0.0
    for ts, delta, pw in rows:
        if delta <= 0:
            continue
        zone = _energy_zone_at(ts, cfg)
        price = _energy_price_at(ts, cfg)
        seg_cost = delta * price
        kwh += delta
        cost += seg_cost
        if zone not in by_zone:
            zone = "flat"
        by_zone[zone]["kwh"] += delta
        by_zone[zone]["cost"] += seg_cost
        # reconstruct span from hold: delta = P * dt / 3.6e6 → dt = delta * 3.6e6 / P
        if pw and pw > 0:
            span_sec += delta * 3600.0 * 1000.0 / pw
    avg_w = (kwh * 1000.0 * 3600.0 / span_sec) if span_sec > 0 else None
    return {
        "kwh": round(kwh, 4),
        "cost": round(cost, 2),
        "kwh_day": round(by_zone["day"]["kwh"] + by_zone["flat"]["kwh"], 4),
        "kwh_night": round(by_zone["night"]["kwh"], 4),
        "kwh_peak": round(by_zone["peak"]["kwh"], 4),
        "kwh_mid": round(by_zone["mid"]["kwh"], 4),
        "cost_day": round(by_zone["day"]["cost"] + by_zone["flat"]["cost"], 2),
        "cost_night": round(by_zone["night"]["cost"], 2),
        "cost_peak": round(by_zone["peak"]["cost"], 2),
        "cost_mid": round(by_zone["mid"]["cost"], 2),
        "avg_w": round(avg_w, 1) if avg_w is not None else None,
        "span_sec": round(span_sec, 1),
        "samples": len(rows),
        "zone": _energy_normalize_mode(cfg.get("tariff_mode")),
    }


def _energy_in_range(mins: int, start_m: int, end_m: int) -> bool:
    """True if mins is in [start, end) on a 24h clock (end may wrap midnight)."""
    if start_m == end_m:
        return False
    if start_m < end_m:
        return start_m <= mins < end_m
    return mins >= start_m or mins < end_m


def _energy_zone_at(ts: float, cfg: dict) -> str:
    """
    Return zone key for timestamp:
      1zone → 'flat'
      2zone → 'day' | 'night'
      3zone → 'peak' | 'mid' | 'night'  (priority: night > peak > mid)
    """
    mode = _energy_normalize_mode(cfg.get("tariff_mode"))
    if mode == "1zone":
        return "flat"
    lt = time.localtime(ts)
    mins = lt.tm_hour * 60 + lt.tm_min
    ns = _parse_hhmm(cfg.get("night_start"), 23, 0)
    ne = _parse_hhmm(cfg.get("night_end"), 7, 0)
    if mode == "2zone":
        return "night" if _energy_in_range(mins, ns, ne) else "day"
    # 3zone
    if _energy_in_range(mins, ns, ne):
        return "night"
    p1s = _parse_hhmm(cfg.get("peak1_start"), 7, 0)
    p1e = _parse_hhmm(cfg.get("peak1_end"), 10, 0)
    p2s = _parse_hhmm(cfg.get("peak2_start"), 17, 0)
    p2e = _parse_hhmm(cfg.get("peak2_end"), 21, 0)
    if _energy_in_range(mins, p1s, p1e) or _energy_in_range(mins, p2s, p2e):
        return "peak"
    return "mid"


def _energy_price_at(ts: float, cfg: dict) -> float:
    zone = _energy_zone_at(ts, cfg)
    if zone == "flat":
        return float(cfg.get("price_kwh") or 0)
    if zone == "day":
        return float(cfg.get("price_day_kwh") or 0)
    if zone == "night":
        return float(cfg.get("price_night_kwh") or 0)
    if zone == "peak":
        return float(cfg.get("price_peak_kwh") or 0)
    if zone == "mid":
        return float(cfg.get("price_mid_kwh") or 0)
    return float(cfg.get("price_kwh") or 0)


def _query_power_samples(since: float, until: float) -> list[tuple[float, float]]:
    """Return [(ts, power_w), ...] for integration (no downsampling)."""
    with _db_lock:
        conn = _db_connect()
        try:
            cols = {r[1] for r in conn.execute("PRAGMA table_info(samples)").fetchall()}
            if "power" not in cols:
                return []
            # prefer only online==1 when column exists; still keep rows with power
            if "online" in cols:
                cur = conn.execute(
                    """
                    SELECT ts, power FROM samples
                    WHERE ts >= ? AND ts <= ? AND power IS NOT NULL
                      AND (online IS NULL OR online != 0)
                    ORDER BY ts ASC
                    """,
                    (since, until),
                )
            else:
                cur = conn.execute(
                    """
                    SELECT ts, power FROM samples
                    WHERE ts >= ? AND ts <= ? AND power IS NOT NULL
                    ORDER BY ts ASC
                    """,
                    (since, until),
                )
            out: list[tuple[float, float]] = []
            for r in cur.fetchall():
                try:
                    ts = float(r["ts"])
                    pw = float(r["power"])
                except (TypeError, ValueError):
                    continue
                if not math.isfinite(ts) or not math.isfinite(pw) or pw < 0:
                    continue
                out.append((ts, pw))
            return out
        finally:
            conn.close()


def _integrate_energy(
    points: list[tuple[float, float]],
    cfg: dict,
    *,
    since: float | None = None,
    until: float | None = None,
) -> dict:
    """
    Integrate power series → kWh/cost.
    Default integration=hold: power at sample i held until sample i+1.
    """
    max_gap = float(cfg.get("max_gap_sec") or 900)
    hold = str(cfg.get("integration") or "hold") != "trap"
    kwh = 0.0
    cost = 0.0
    by_zone: dict[str, dict[str, float]] = {
        "flat": {"kwh": 0.0, "cost": 0.0},
        "day": {"kwh": 0.0, "cost": 0.0},
        "night": {"kwh": 0.0, "cost": 0.0},
        "peak": {"kwh": 0.0, "cost": 0.0},
        "mid": {"kwh": 0.0, "cost": 0.0},
    }
    span_sec = 0.0
    samples = 0
    empty = {
        "kwh": 0.0,
        "cost": 0.0,
        "kwh_day": 0.0,
        "kwh_night": 0.0,
        "kwh_peak": 0.0,
        "kwh_mid": 0.0,
        "cost_day": 0.0,
        "cost_night": 0.0,
        "cost_peak": 0.0,
        "cost_mid": 0.0,
        "avg_w": None,
        "span_sec": 0.0,
        "samples": len(points),
        "zone": _energy_normalize_mode(cfg.get("tariff_mode")),
    }
    if len(points) < 2:
        empty["samples"] = len(points)
        return empty
    for i in range(1, len(points)):
        t0, p0 = points[i - 1]
        t1, p1 = points[i]
        if since is not None and t1 < since:
            continue
        if until is not None and t0 > until:
            break
        dt = t1 - t0
        if dt <= 0 or dt > max_gap:
            continue
        a, b = t0, t1
        if since is not None and a < since:
            a = since
            dt = b - a
        if until is not None and b > until:
            b = until
            dt = b - a
        if dt <= 0 or dt > max_gap:
            continue
        # hold: p0 constant; trap: average
        mid_p = p0 if hold else (p0 + p1) / 2.0
        seg_kwh = mid_p * dt / 3600.0 / 1000.0
        mid_t = (a + b) / 2.0
        zone = _energy_zone_at(mid_t, cfg)
        price = _energy_price_at(mid_t, cfg)
        seg_cost = seg_kwh * price
        kwh += seg_kwh
        cost += seg_cost
        span_sec += dt
        samples += 1
        if zone not in by_zone:
            zone = "flat"
        by_zone[zone]["kwh"] += seg_kwh
        by_zone[zone]["cost"] += seg_cost
    avg_w = (kwh * 1000.0 * 3600.0 / span_sec) if span_sec > 0 else None
    return {
        "kwh": round(kwh, 4),
        "cost": round(cost, 2),
        "kwh_day": round(by_zone["day"]["kwh"] + by_zone["flat"]["kwh"], 4),
        "kwh_night": round(by_zone["night"]["kwh"], 4),
        "kwh_peak": round(by_zone["peak"]["kwh"], 4),
        "kwh_mid": round(by_zone["mid"]["kwh"], 4),
        "cost_day": round(by_zone["day"]["cost"] + by_zone["flat"]["cost"], 2),
        "cost_night": round(by_zone["night"]["cost"], 2),
        "cost_peak": round(by_zone["peak"]["cost"], 2),
        "cost_mid": round(by_zone["mid"]["cost"], 2),
        "avg_w": round(avg_w, 1) if avg_w is not None else None,
        "span_sec": round(span_sec, 1),
        "samples": samples,
        "zone": _energy_normalize_mode(cfg.get("tariff_mode")),
    }


def _local_day_start(ts: float | None = None) -> float:
    t = time.localtime(ts if ts is not None else time.time())
    return time.mktime((t.tm_year, t.tm_mon, t.tm_mday, 0, 0, 0, 0, 0, -1))


def energy_summary() -> dict:
    """kWh / cost periods from energy.db hold samples + virtual meter state."""
    cfg = get_energy_cfg()
    _ensure_energy_db()
    now = time.time()
    day0 = _local_day_start(now)
    windows = {
        "today": (day0, now),
        "yesterday": (day0 - 86400, day0),
        "d7": (now - 7 * 86400, now),
        "d30": (now - 30 * 86400, now),
    }
    periods = {}
    for key, (a, b) in windows.items():
        periods[key] = {
            "from_ts": a,
            "to_ts": b,
            "from_iso": datetime.fromtimestamp(a).isoformat(timespec="seconds"),
            "to_iso": datetime.fromtimestamp(b).isoformat(timespec="seconds"),
            **_sum_energy_period(a, b, cfg),
        }
    meters = list_energy_meters()
    virtual = next((m for m in meters if m.get("id") == VIRTUAL_METER_ID), None)
    live_w = virtual.get("last_power_w") if virtual else None
    live_est = False
    try:
        snap = hydrate_live_from_disk(max_age_sec=180.0)
        if isinstance(snap, dict):
            src = str(snap.get("power_source") or "").lower()
            live_est = bool(snap.get("power_estimated")) or src in (
                "model",
                "estimate",
                "estimated",
                "profile",
            )
            if live_w is None and snap.get("power") not in (None, ""):
                live_w = snap.get("power")
    except Exception:
        live_est = False
    sample_count = 0
    with _energy_db_lock:
        conn = _energy_db_connect()
        try:
            row = conn.execute(
                "SELECT COUNT(*) AS c, MIN(ts) AS tmin, MAX(ts) AS tmax FROM energy_samples WHERE meter_id = ?",
                (VIRTUAL_METER_ID,),
            ).fetchone()
            sample_count = int(row["c"] or 0)
            oldest = row["tmin"]
            newest = row["tmax"]
        finally:
            conn.close()
    return {
        "ok": True,
        "config": cfg,
        "live_power_w": live_w,
        "live_power_estimated": live_est,
        "periods": periods,
        "meters": meters,
        "virtual_meter": virtual,
        "energy_db": {
            "path": str(ENERGY_DB_FILE),
            "size_bytes": ENERGY_DB_FILE.stat().st_size if ENERGY_DB_FILE.exists() else 0,
            "samples": sample_count,
            "oldest_ts": oldest,
            "newest_ts": newest,
            "integration": cfg.get("integration") or "hold",
            "metering_enabled": bool(cfg.get("metering_enabled", True)),
            "history_backfill_done": bool(cfg.get("history_backfill_done")),
            "history_backfill_at": cfg.get("history_backfill_at"),
            "history_backfill_samples": cfg.get("history_backfill_samples"),
        },
        "generated_at": datetime.now().isoformat(timespec="seconds"),
    }


try:
    _load_energy_cfg()
    _ensure_energy_db()
    maybe_backfill_energy_from_history()
except Exception:
    pass


# ─── miner I/O ────────────────────────────────────────────────────────────────

# Last successful live read — used to skip write when ASIC is offline.
_last_live_ok_ts: float = 0.0
_last_live_ok_lock = threading.Lock()
_MINER_ONLINE_MAX_AGE_SEC = 45.0


def _mark_miner_live_ok() -> None:
    global _last_live_ok_ts
    with _last_live_ok_lock:
        _last_live_ok_ts = time.time()


def miner_is_online(*, max_age_sec: float | None = None, probe: bool = False) -> bool:
    """
    True if we recently have live_cache from miner-poller.
    probe no longer opens ASIC TCP from serve (ignored; disk hydrate only).
    """
    age = float(max_age_sec if max_age_sec is not None else _MINER_ONLINE_MAX_AGE_SEC)
    with _last_live_ok_lock:
        last = float(_last_live_ok_ts or 0)
    if last > 0 and (time.time() - last) <= age:
        return True
    live = hydrate_live_from_disk(max_age_sec=age)
    if isinstance(live, dict) and live.get("ok"):
        _mark_miner_live_ok()
        return True
    return False


def _parse_miner_json(text: str) -> dict:
    """
    Parse Whatsminer TCP JSON robustly.
    Handles: trailing junk, multiple objects, partial reads already completed,
    and common firmware quirks — never surface raw JSONDecodeError as «offline».
    """
    s = (text or "").replace("\x00", "").strip()
    if not s:
        raise TimeoutError("empty response from miner")
    dec = json.JSONDecoder()
    # Prefer first complete object starting at first '{'
    i = s.find("{")
    if i < 0:
        raise RuntimeError(f"miner response not JSON: {s[:80]!r}")
    try:
        obj, _end = dec.raw_decode(s, i)
        if isinstance(obj, dict):
            return obj
        raise RuntimeError(f"miner JSON root not object: {type(obj).__name__}")
    except json.JSONDecodeError:
        pass
    # Sanitize common garbage then retry
    cleaned = s[i:]
    cleaned = re.sub(r",\s*}", "}", cleaned)
    cleaned = re.sub(r",\s*]", "]", cleaned)
    cleaned = cleaned.replace("NaN", "null").replace("Infinity", "null")
    try:
        obj, _end = dec.raw_decode(cleaned)
        if isinstance(obj, dict):
            return obj
    except json.JSONDecodeError as e:
        # Brace-match first object if truncated tail after valid body
        depth = 0
        in_str = False
        esc = False
        end_idx = -1
        for idx, ch in enumerate(cleaned):
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
                continue
            if ch == '"':
                in_str = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    end_idx = idx + 1
                    break
        if end_idx > 0:
            try:
                obj = json.loads(cleaned[:end_idx])
                if isinstance(obj, dict):
                    return obj
            except json.JSONDecodeError:
                pass
        raise RuntimeError(
            f"bad JSON from miner (len={len(s)}, col={getattr(e, 'colno', '?')})"
        ) from e
    raise RuntimeError(f"miner JSON root not object after sanitize")


def _recv_json(sock: socket.socket, timeout: float = 5.0) -> dict:
    """Read one JSON object from miner TCP socket (may span multiple recv)."""
    deadline = time.time() + max(0.5, float(timeout))
    chunks: list[bytes] = []
    while time.time() < deadline:
        remain = max(0.05, deadline - time.time())
        sock.settimeout(remain)
        try:
            chunk = sock.recv(16384)
            if not chunk:
                break
            chunks.append(chunk)
            text = b"".join(chunks).replace(b"\x00", b"").decode("utf-8", errors="replace")
            # Need at least one complete object
            if "{" not in text:
                continue
            try:
                return _parse_miner_json(text)
            except RuntimeError as e:
                # incomplete — keep reading until timeout
                if "bad JSON" in str(e) or "not JSON" in str(e):
                    # if looks incomplete (unbalanced braces), continue
                    if text.count("{") > text.count("}"):
                        continue
                    raise
                raise
        except socket.timeout:
            break
    raw = b"".join(chunks).replace(b"\x00", b"").decode("utf-8", errors="replace")
    if not raw.strip():
        raise TimeoutError("empty response from miner")
    try:
        return _parse_miner_json(raw)
    except RuntimeError:
        # incomplete buffer after timeout
        if raw.count("{") > raw.count("}"):
            raise TimeoutError(
                f"incomplete JSON from miner (len={len(raw)})"
            ) from None
        raise


# Per-host ASIC protocol cache: "whatsminer" | "cgminer" | "unknown"
_ASIC_PROTO_CACHE: dict[str, str] = {}
_ASIC_PROTO_LOCK = threading.Lock()
# Optional host/port override for multi-miner fleet poll (thread-local)
_tls_asic = threading.local()
# fleet_live.json — map host → live slice for multi-vendor inventory
FLEET_LIVE_FILE = DATA / "fleet_live.json"


def _is_this_python_miner_poller() -> bool:
    """True when this process is the Python ASIC poller (owns direct :4028)."""
    try:
        argv = " ".join(sys.argv)
        if "--miner-poller" in argv or "--asic-poller" in argv:
            return True
    except Exception:
        pass
    return False


def _parse_hashrate_to_hs(value) -> float | None:
    """
    Normalize hashrate field to H/s.

    Whatsminer: large numeric MHS (e.g. 148500000.0 ≈ 148.5 TH/s).
    CGMiner/iPollo: string with unit suffix ("240.2572M", "4.67G") or plain float.
    """
    if value is None or value == "":
        return None
    if isinstance(value, (int, float)):
        try:
            v = float(value)
        except (TypeError, ValueError):
            return None
        if not (v > 0) or v != v:  # NaN
            return None
        return v
    s = str(value).strip().replace(",", "")
    if not s:
        return None
    # "18.58 GH/s", "240.2572M", "15.86G" — allow optional space before unit
    m = re.match(
        r"^([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*([kKmMgGtTpP]?)(?:\s*H(?:/s)?)?$",
        s,
        re.I,
    )
    if not m:
        # bare number
        try:
            v = float(s)
            return v if v > 0 else None
        except (TypeError, ValueError):
            return None
    try:
        num = float(m.group(1))
    except (TypeError, ValueError):
        return None
    if not (num > 0):
        return None
    suf = (m.group(2) or "").upper()
    mult = {
        "": 1.0,
        "K": 1e3,
        "M": 1e6,
        "G": 1e9,
        "T": 1e12,
        "P": 1e15,
    }.get(suf, 1.0)
    # If suffix present → value is already in that unit (240.2572M → MH/s).
    # If no suffix and huge number → Whatsminer-style raw MHS count (H/s-ish).
    return num * mult


def _hs_to_th(hs: float | None) -> float | None:
    if hs is None or hs <= 0:
        return None
    return hs / 1e12


def _asic_status_is_error(raw: dict | None) -> bool:
    if not isinstance(raw, dict):
        return True
    st = raw.get("STATUS")
    if isinstance(st, list) and st:
        row = st[0] if isinstance(st[0], dict) else {}
        code = str(row.get("STATUS") or row.get("Status") or "").upper()
        if code in ("E", "F"):
            return True
        msg = str(row.get("Msg") or "")
        if "Missing JSON" in msg or "Invalid command" in msg or "Access denied" in msg:
            return True
    elif isinstance(st, str) and st.upper() in ("E", "F"):
        return True
    return False


def _cgminer_payload(cmd: dict) -> dict:
    """Map Whatsminer-style {cmd, …} → classic CGMiner {command, parameter}."""
    name = str(cmd.get("command") or cmd.get("cmd") or "").strip()
    out: dict = {"command": name}
    param = cmd.get("parameter")
    if param is None:
        param = cmd.get("param")
    if param is None and cmd.get("token") is not None:
        # not used by cgminer; skip
        param = None
    if param is not None and str(param) != "":
        out["parameter"] = param
    return out


def _detect_asic_protocol(host: str, port: int, timeout: float = 2.5) -> str:
    """
    Probe host:port — Whatsminer answers {"cmd":"get_version"} with Msg dict;
    CGMiner/iPollo needs {"command":"version|summary"} and returns STATUS list.
    """
    host = str(host or "").strip()
    if not host:
        return "unknown"
    with _ASIC_PROTO_LOCK:
        cached = _ASIC_PROTO_CACHE.get(host)
    if cached in ("whatsminer", "cgminer"):
        return cached

    def _try(payload: dict) -> dict | None:
        try:
            data = (json.dumps(payload, separators=(",", ":")) + "\n").encode()
            with socket.create_connection((host, int(port)), timeout=timeout) as sock:
                sock.sendall(data)
                return _recv_json(sock, timeout=timeout)
        except Exception:
            return None

    # Whatsminer first (Peak fleet default)
    wm = _try({"cmd": "get_version"})
    if isinstance(wm, dict) and not _asic_status_is_error(wm):
        msg = wm.get("Msg")
        if isinstance(msg, dict) and (
            msg.get("api_ver") or msg.get("fw_ver") or msg.get("miner_type")
        ):
            with _ASIC_PROTO_LOCK:
                _ASIC_PROTO_CACHE[host] = "whatsminer"
            return "whatsminer"

    # Classic CGMiner / iPollo / Avalon-style
    for payload in (
        {"command": "version"},
        {"command": "summary"},
        {"command": "config"},
    ):
        cg = _try(payload)
        if not isinstance(cg, dict) or _asic_status_is_error(cg):
            continue
        # Description: "cgminer 4.11.1" / Device Code IPL / SUMMARY section
        desc = ""
        st = cg.get("STATUS")
        if isinstance(st, list) and st and isinstance(st[0], dict):
            desc = str(st[0].get("Description") or "")
        desc_l = desc.lower()
        if (
            "SUMMARY" in cg
            or "VERSION" in cg
            or "CONFIG" in cg
            or "STATS" in cg
            or "DEVS" in cg
            or "cgminer" in desc_l
            or "bmminer" in desc_l
            or "bfgminer" in desc_l
            or "ckbminer" in desc_l  # Goldshell CKBox
            or "goldshell" in desc_l
        ):
            with _ASIC_PROTO_LOCK:
                _ASIC_PROTO_CACHE[host] = "cgminer"
            return "cgminer"
        # Device Code IPL (iPollo) / INCS (Goldshell CK) in config
        cfg = cg.get("CONFIG")
        if isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            dc = str(cfg[0].get("Device Code") or "").upper()
            if any(x in dc for x in ("IPL", "VX", "INCS", "SGW", "SSM")):
                with _ASIC_PROTO_LOCK:
                    _ASIC_PROTO_CACHE[host] = "cgminer"
                return "cgminer"

    with _ASIC_PROTO_LOCK:
        _ASIC_PROTO_CACHE[host] = "unknown"
    return "unknown"


def _asic_target() -> tuple[str, int]:
    """Active ASIC host:port (thread-local override or global config)."""
    h = getattr(_tls_asic, "host", None)
    p = getattr(_tls_asic, "port", None)
    host = str(h if h else HOST_MINER or "").strip()
    try:
        port = int(p if p is not None else PORT_MINER or 4028)
    except (TypeError, ValueError):
        port = 4028
    return host, port


@contextlib.contextmanager
def _asic_target_override(host: str, port: int = 4028):
    """Temporarily point direct ASIC I/O at another miner (fleet multi-poll)."""
    prev_h = getattr(_tls_asic, "host", None)
    prev_p = getattr(_tls_asic, "port", None)
    _tls_asic.host = str(host or "").strip()
    try:
        _tls_asic.port = int(port or 4028)
    except (TypeError, ValueError):
        _tls_asic.port = 4028
    try:
        yield
    finally:
        _tls_asic.host = prev_h
        _tls_asic.port = prev_p


def _miner_cmd_unlocked(
    cmd: dict,
    timeout: float = 5.0,
    *,
    host: str | None = None,
    port: int | None = None,
) -> dict:
    """
    Direct TCP :4028 — ONLY for legacy `python serve.py --miner-poller`
    (this process IS the poller). HTTP serve must never call this.

    Auto-adapts Whatsminer ``cmd`` vs CGMiner ``command`` (iPollo, Goldshell, …).
    Optional host/port override for multi-miner fleet poll.
    """
    if host is None and port is None:
        host, port = _asic_target()
    else:
        host = str(host if host is not None else HOST_MINER or "").strip()
        port = int(port if port is not None else PORT_MINER or 4028)
    proto = _detect_asic_protocol(host, port, timeout=min(2.5, float(timeout)))
    if proto == "cgminer":
        payload_obj = _cgminer_payload(cmd)
    else:
        # Whatsminer / unknown: keep original (cmd key)
        payload_obj = dict(cmd or {})
        if "cmd" not in payload_obj and "command" in payload_obj:
            payload_obj["cmd"] = payload_obj.pop("command")
    payload = (json.dumps(payload_obj, separators=(",", ":")) + "\n").encode()
    with socket.create_connection((host, port), timeout=timeout) as sock:
        sock.sendall(payload)
        raw = _recv_json(sock, timeout=timeout)
    # If Whatsminer-style failed with missing command, retry as CGMiner once
    if (
        proto != "cgminer"
        and isinstance(raw, dict)
        and _asic_status_is_error(raw)
    ):
        st = raw.get("STATUS")
        msg = ""
        if isinstance(st, list) and st and isinstance(st[0], dict):
            msg = str(st[0].get("Msg") or "")
        if "Missing JSON" in msg or "command" in msg.lower():
            payload_obj = _cgminer_payload(cmd)
            payload = (json.dumps(payload_obj, separators=(",", ":")) + "\n").encode()
            with socket.create_connection((host, port), timeout=timeout) as sock:
                sock.sendall(payload)
                raw = _recv_json(sock, timeout=timeout)
            if isinstance(raw, dict) and not _asic_status_is_error(raw):
                with _ASIC_PROTO_LOCK:
                    _ASIC_PROTO_CACHE[host] = "cgminer"
    return raw


def miner_cmd(cmd: dict, timeout: float = 5.0) -> dict:
    """
    On-demand miner JSON read (pools, summary, …).

    - Python miner-poller process: direct TCP (owns :4028).
    - Fleet multi-host override (_asic_target_override): direct TCP — Go
      miner-poller is single-target and cannot reach standby hosts.
    - HTTP serve / other roles: file IPC → miner-poller only.
    """
    if _is_this_python_miner_poller():
        return _miner_cmd_unlocked(cmd, timeout=timeout)
    # Multi-host fleet live: TLS host override → this host is not the Go
    # poller's active target. Without direct TCP every standby shows offline.
    if getattr(_tls_asic, "host", None):
        return _miner_cmd_unlocked(cmd, timeout=timeout)
    if not miner_poller_process_alive():
        raise RuntimeError(
            "miner-poller not running — ASIC I/O only via poller "
            f"(cmd={cmd.get('cmd')!r}). Start poolheat-miner-poller."
        )
    return miner_read_via_poller(cmd, timeout_sec=max(float(timeout), 8.0))


def _extract_miner_payload(
    raw: Any,
    *section_keys: str,
) -> dict:
    """
    Normalize miner TCP reply to a flat dict of fields.

    Whatsminer secure/API style::
        {"STATUS": "S", "Msg": { ...fields... }}

    Classic cgminer multi-section (seen after factory_reset / some FW)::
        {"STATUS": [{"STATUS":"S","Msg":"Summary"}], "SUMMARY": [{ ...fields... }]}

    Never raises KeyError on missing ``Msg`` — returns {}.
    """
    if not isinstance(raw, dict):
        return {}
    msg = raw.get("Msg")
    if isinstance(msg, dict):
        return msg
    # prefer explicit sections (SUMMARY, DEVS already handled elsewhere)
    keys = section_keys or (
        "SUMMARY",
        "summary",
        "STATUS",
        "status",
        "INFO",
        "info",
    )
    for key in keys:
        sec = raw.get(key)
        if isinstance(sec, list) and sec:
            first = sec[0]
            if isinstance(first, dict):
                # skip pure status-only rows like {"STATUS":"S","Msg":"Summary"}
                if set(first.keys()) <= {
                    "STATUS",
                    "Status",
                    "Msg",
                    "msg",
                    "Code",
                    "When",
                    "Description",
                    "id",
                    "ID",
                }:
                    continue
                return first
        if isinstance(sec, dict) and sec:
            return sec
    # last resort: if Msg is a non-empty string only, no fields
    return {}


def _read_text_file(path: str, max_len: int = 4096) -> str | None:
    try:
        p = Path(path)
        if not p.is_file():
            return None
        raw = p.read_bytes()[:max_len]
        # device-tree model is often null-terminated
        return raw.split(b"\x00", 1)[0].decode("utf-8", errors="replace").strip() or None
    except Exception:
        return None


def _parse_ndmc_kv(text: str) -> dict[str, str]:
    """Parse simple `key: value` lines from `ndmc -c 'show …'` output."""
    out: dict[str, str] = {}
    for line in (text or "").splitlines():
        m = re.match(r"^\s*([A-Za-z0-9_.-]+)\s*:\s*(.*?)\s*$", line)
        if not m:
            continue
        k, v = m.group(1), m.group(2)
        if v:
            out[k] = v
    return out


def _disk_usage_entry(path: str | Path, label: str | None = None) -> dict | None:
    try:
        p = Path(path)
        if not p.exists():
            return None
        # resolve symlinks so USB-backed /opt/var/poolheat reports the stick, not UBI
        try:
            real = p.resolve()
        except Exception:
            real = p
        u = shutil.disk_usage(str(real if real.exists() else p))
        return {
            "path": str(p),
            "real_path": str(real),
            "label": label or str(p),
            "total_b": int(u.total),
            "used_b": int(u.used),
            "free_b": int(u.free),
            "used_pct": round(100.0 * u.used / u.total, 1) if u.total else None,
        }
    except Exception:
        return None


def _is_usb_path(path: str | Path | None) -> bool:
    """True if path lives on Keenetic USB mount (/tmp/mnt/…)."""
    if not path:
        return False
    s = str(path).replace("\\", "/")
    return "/tmp/mnt/" in s or s.startswith("/mnt/")


# ── Firmware repository (optional, prefers USB stick) ───────────────────────

_FW_LOCK = threading.Lock()
_FW_MAX_UPLOAD_B = 256 * 1024 * 1024  # 256 MiB
_FW_DEFAULT_MODELS = [
    "M30S",
    "M30S+",
    "M31S",
    "M33S",
    "M36S",
    "M50",
    "M50S",
    "M53",
    "M56",
    "M60",
    "M60S",
    "M63",
    "M63S",
    "M63S+",
    "M66",
    "M66S",
]


def _fw_cfg_load() -> dict:
    cfg = {"enabled": False}
    try:
        if FIRMWARE_CFG_FILE.is_file():
            raw = json.loads(FIRMWARE_CFG_FILE.read_text(encoding="utf-8"))
            if isinstance(raw, dict):
                cfg["enabled"] = bool(raw.get("enabled"))
    except Exception:
        pass
    return cfg


def _fw_cfg_save(cfg: dict) -> dict:
    out = {"enabled": bool(cfg.get("enabled"))}
    try:
        FIRMWARE_CFG_FILE.parent.mkdir(parents=True, exist_ok=True)
        FIRMWARE_CFG_FILE.write_text(
            json.dumps(out, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
    except Exception as e:
        raise RuntimeError(f"cannot save firmware config: {e}") from e
    return out


def _fw_usb_root() -> Path | None:
    """USB poolheat root if migrated, else None."""
    info = _poolheat_usb_info()
    if not info:
        return None
    root = info.get("usb_root") or info.get("real_path") or info.get("path")
    if not root:
        return None
    p = Path(str(root))
    return p if p.exists() else None


def _fw_storage_root() -> Path:
    """
    Firmware files live on USB when available (…/poolheat/firmware),
    else under DATA/firmware (internal flash — not recommended).
    """
    usb = _fw_usb_root()
    if usb is not None:
        return usb / "firmware"
    return DATA / "firmware"


def _fw_files_dir() -> Path:
    return _fw_storage_root() / "files"


def _fw_catalog_path() -> Path:
    return _fw_storage_root() / "catalog.json"


def _fw_ensure_dirs() -> None:
    _fw_files_dir().mkdir(parents=True, exist_ok=True)


def _fw_safe_name(name: str) -> str:
    base = Path(str(name or "firmware.bin")).name
    base = re.sub(r"[^\w.\-+()\[\] ]+", "_", base, flags=re.UNICODE).strip(" ._")
    if not base:
        base = "firmware.bin"
    if len(base) > 180:
        stem = Path(base).stem[:160]
        suf = Path(base).suffix[:20] or ".bin"
        base = stem + suf
    return base


def _fw_load_catalog() -> dict:
    path = _fw_catalog_path()
    empty = {"version": 1, "items": []}
    try:
        if path.is_file():
            raw = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(raw, dict) and isinstance(raw.get("items"), list):
                return raw
    except Exception:
        pass
    return empty


def _fw_save_catalog(cat: dict) -> None:
    _fw_ensure_dirs()
    path = _fw_catalog_path()
    path.write_text(
        json.dumps(cat, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )


def _fw_normalize_models(models) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    if models is None:
        return out
    if isinstance(models, str):
        parts = re.split(r"[,;\n|/]+", models)
    elif isinstance(models, (list, tuple)):
        parts = [str(x) for x in models]
    else:
        parts = [str(models)]
    for p in parts:
        m = str(p).strip()
        if not m:
            continue
        key = m.upper()
        if key in seen:
            continue
        seen.add(key)
        out.append(m)
    return out


def _fw_item_public(it: dict, *, files_dir: Path) -> dict:
    stored = str(it.get("stored_as") or "")
    fpath = files_dir / Path(stored).name if stored else None
    size = it.get("size")
    exists = bool(fpath and fpath.is_file())
    if exists and fpath is not None:
        try:
            size = fpath.stat().st_size
        except Exception:
            pass
    return {
        "id": it.get("id"),
        "filename": it.get("filename") or (fpath.name if fpath else ""),
        "stored_as": stored,
        "size": size,
        "sha256": it.get("sha256"),
        "models": list(it.get("models") or []),
        "note": it.get("note") or "",
        "uploaded_at": it.get("uploaded_at"),
        "updated_at": it.get("updated_at"),
        "exists": exists,
    }


def get_firmware_status() -> dict:
    """Config + storage path + free space + catalog summary."""
    cfg = _fw_cfg_load()
    root = _fw_storage_root()
    on_usb = _is_usb_path(root)
    usage = _disk_usage_entry(root if root.exists() else root.parent, "firmware storage")
    cat = _fw_load_catalog()
    items = cat.get("items") or []
    return {
        "ok": True,
        "enabled": bool(cfg.get("enabled")),
        "on_usb": on_usb,
        "storage_path": str(root),
        "catalog_path": str(_fw_catalog_path()),
        "files_dir": str(_fw_files_dir()),
        "disk": usage,
        "count": len(items),
        "suggested_models": list(_FW_DEFAULT_MODELS),
        "max_upload_b": _FW_MAX_UPLOAD_B,
        "warning": (
            None
            if on_usb
            else "Firmware repo is not on USB — large files will use internal flash/data path"
        ),
    }


def list_firmware() -> dict:
    st = get_firmware_status()
    if not st.get("enabled"):
        return {**st, "items": [], "disabled": True}
    cat = _fw_load_catalog()
    files_dir = _fw_files_dir()
    items = [
        _fw_item_public(it, files_dir=files_dir)
        for it in (cat.get("items") or [])
        if isinstance(it, dict)
    ]
    # newest first
    items.sort(key=lambda x: str(x.get("uploaded_at") or ""), reverse=True)
    return {**st, "items": items, "disabled": False}


def apply_firmware_config(req: dict) -> dict:
    cfg = _fw_cfg_load()
    if "enabled" in req:
        cfg["enabled"] = bool(req.get("enabled"))
    saved = _fw_cfg_save(cfg)
    if saved.get("enabled"):
        try:
            _fw_ensure_dirs()
            if not _fw_catalog_path().is_file():
                _fw_save_catalog({"version": 1, "items": []})
        except Exception as e:
            raise RuntimeError(f"cannot init firmware storage: {e}") from e
    return get_firmware_status()


def firmware_add_file(
    *,
    filename: str,
    data: bytes,
    models: list[str] | str | None = None,
    note: str = "",
) -> dict:
    if not _fw_cfg_load().get("enabled"):
        raise RuntimeError("firmware repository is disabled — enable in Settings → Firmware")
    if not data:
        raise ValueError("empty file")
    if len(data) > _FW_MAX_UPLOAD_B:
        raise ValueError(f"file too large (max {_FW_MAX_UPLOAD_B // (1024*1024)} MiB)")
    safe = _fw_safe_name(filename)
    fid = uuid.uuid4().hex[:12]
    stored_name = f"{fid}_{safe}"
    with _FW_LOCK:
        _fw_ensure_dirs()
        fpath = _fw_files_dir() / stored_name
        fpath.write_bytes(data)
        sha = hashlib.sha256(data).hexdigest()
        now = datetime.now().isoformat(timespec="seconds")
        cat = _fw_load_catalog()
        item = {
            "id": fid,
            "filename": safe,
            "stored_as": stored_name,
            "size": len(data),
            "sha256": sha,
            "models": _fw_normalize_models(models),
            "note": str(note or "")[:500],
            "uploaded_at": now,
            "updated_at": now,
        }
        items = [it for it in (cat.get("items") or []) if isinstance(it, dict)]
        items.append(item)
        cat["items"] = items
        cat["version"] = 1
        _fw_save_catalog(cat)
    return {
        "ok": True,
        "item": _fw_item_public(item, files_dir=_fw_files_dir()),
        **get_firmware_status(),
    }


def firmware_update_item(req: dict) -> dict:
    if not _fw_cfg_load().get("enabled"):
        raise RuntimeError("firmware repository is disabled")
    fid = str(req.get("id") or "").strip()
    if not fid:
        raise ValueError("id required")
    with _FW_LOCK:
        cat = _fw_load_catalog()
        items = cat.get("items") or []
        found = None
        for it in items:
            if isinstance(it, dict) and str(it.get("id")) == fid:
                found = it
                break
        if not found:
            raise ValueError(f"firmware id not found: {fid}")
        if "models" in req:
            found["models"] = _fw_normalize_models(req.get("models"))
        if "note" in req:
            found["note"] = str(req.get("note") or "")[:500]
        if "filename" in req and str(req.get("filename") or "").strip():
            found["filename"] = _fw_safe_name(str(req.get("filename")))
        found["updated_at"] = datetime.now().isoformat(timespec="seconds")
        _fw_save_catalog(cat)
        item = found
    return {
        "ok": True,
        "item": _fw_item_public(item, files_dir=_fw_files_dir()),
    }


def firmware_delete_item(fid: str) -> dict:
    if not _fw_cfg_load().get("enabled"):
        raise RuntimeError("firmware repository is disabled")
    fid = str(fid or "").strip()
    if not fid:
        raise ValueError("id required")
    with _FW_LOCK:
        cat = _fw_load_catalog()
        items = [it for it in (cat.get("items") or []) if isinstance(it, dict)]
        found = None
        rest = []
        for it in items:
            if str(it.get("id")) == fid:
                found = it
            else:
                rest.append(it)
        if not found:
            raise ValueError(f"firmware id not found: {fid}")
        stored = str(found.get("stored_as") or "")
        if stored:
            try:
                p = _fw_files_dir() / Path(stored).name
                if p.is_file():
                    p.unlink()
            except Exception as e:
                print(f"[firmware] unlink {stored}: {e}")
        cat["items"] = rest
        _fw_save_catalog(cat)
    return {"ok": True, "deleted": fid, **get_firmware_status()}


def firmware_file_path(fid: str) -> Path | None:
    cat = _fw_load_catalog()
    for it in cat.get("items") or []:
        if isinstance(it, dict) and str(it.get("id")) == fid:
            stored = str(it.get("stored_as") or "")
            if not stored:
                return None
            p = _fw_files_dir() / Path(stored).name
            return p if p.is_file() else None
    return None


def firmware_item_by_id(fid: str) -> dict | None:
    cat = _fw_load_catalog()
    for it in cat.get("items") or []:
        if isinstance(it, dict) and str(it.get("id")) == str(fid).strip():
            return it
    return None


def _miner_model_keys(miner_type: str | None) -> set[str]:
    """Normalize model tags: M63_VK2A → {M63_VK2A, M63VK2A, M63}."""
    t = str(miner_type or "").upper().strip()
    if not t:
        return set()
    keys = {t, re.sub(r"[^A-Z0-9+]", "", t)}
    base = t.split("_")[0].split("-")[0]
    keys.add(base)
    keys.add(base.replace("+", ""))
    return {k for k in keys if k}


def firmware_model_matches(miner_type: str | None, models: list | None) -> bool:
    """True if catalog models list is empty (any) or intersects miner type keys."""
    ml = list(models or [])
    if not ml:
        return True
    mk = _miner_model_keys(miner_type)
    if not mk:
        return True
    for m in ml:
        if mk & _miner_model_keys(str(m)):
            return True
    return False


def list_firmware_compatible(miner_type: str | None = None) -> dict:
    """Library items filtered for miner model (empty models list = show)."""
    st = list_firmware()
    if st.get("disabled") or not st.get("enabled"):
        return {**st, "compatible": [], "miner_type": miner_type}
    mt = miner_type
    if not mt:
        try:
            ident = get_miner_identity_cached(force=False)
            if isinstance(ident, dict):
                mt = str(ident.get("miner_type") or "").strip() or None
        except Exception:
            mt = None
    items = st.get("items") or []
    compatible = [
        it
        for it in items
        if isinstance(it, dict)
        and it.get("exists") is not False
        and firmware_model_matches(mt, it.get("models"))
    ]
    other = [
        it
        for it in items
        if isinstance(it, dict)
        and it.get("exists") is not False
        and it not in compatible
    ]
    return {
        **st,
        "miner_type": mt,
        "compatible": compatible,
        "other": other,
        "count_compatible": len(compatible),
    }


_FW_FLASH_LOCK = threading.Lock()
_FW_FLASH_STATE: dict[str, Any] = {
    "busy": False,
    "pct": 0,
    "stage": "idle",
    "error": None,
    "result": None,
    "firmware_id": None,
    "filename": None,
    "started_at": None,
    "finished_at": None,
}


def get_firmware_flash_status() -> dict:
    """Flash progress from miner-poller (firmware_flash_status.json)."""
    try:
        if FIRMWARE_FLASH_STATUS_FILE.is_file():
            raw = json.loads(FIRMWARE_FLASH_STATUS_FILE.read_text(encoding="utf-8"))
            if isinstance(raw, dict):
                out = dict(raw)
                out.setdefault("busy", False)
                return out
    except Exception:
        pass
    with _FW_FLASH_LOCK:
        return dict(_FW_FLASH_STATE)


def _fw_flash_set(**kwargs: Any) -> None:
    with _FW_FLASH_LOCK:
        _FW_FLASH_STATE.update(kwargs)


def _prepare_firmware_image(data: bytes, miner_type: str | None = None) -> tuple[bytes, dict]:
    """Deprecated — extraction is done in miner-poller (wm-lib)."""
    return data, {"source": "raw_passthrough", "size": len(data or b"")}


def _netpacket_client(password: str | None = None, *, timeout: float = 20.0):
    raise RuntimeError(
        "NetPacket removed from serve — use miner-poller "
        "(firmware flash / export-log IPC)"
    )


def _flash_status_is_stale(st: dict, *, max_age_sec: float = 180.0) -> bool:
    """True if busy flag is stuck (poller died / never picked up queued job)."""
    if not isinstance(st, dict) or not st.get("busy"):
        return False
    # finished_at set but busy left true
    if st.get("finished_at") and st.get("stage") in ("success", "done", "error"):
        return True
    started = str(st.get("started_at") or "")
    if not started:
        return True
    try:
        # ISO local without tz
        t0 = datetime.fromisoformat(started.replace("Z", ""))
        age = (datetime.now() - t0).total_seconds()
        stage = str(st.get("stage") or "")
        # queued forever without poller pickup
        if stage in ("queued", "prepare", "") and age > 90:
            return True
        # any busy longer than max (flash can be long — only for queued/auth stuck)
        if stage in ("queued", "prepare", "auth", "extract") and age > max_age_sec:
            return True
        # absolute cap 25 min
        if age > 25 * 60:
            return True
    except Exception:
        return True
    return False


def _clear_flash_status_file() -> None:
    try:
        if FIRMWARE_FLASH_STATUS_FILE.is_file():
            FIRMWARE_FLASH_STATUS_FILE.unlink()
    except Exception:
        pass
    with _FW_FLASH_LOCK:
        _FW_FLASH_STATE.update(
            {
                "busy": False,
                "pct": 0,
                "stage": "idle",
                "error": None,
                "result": None,
                "finished_at": datetime.now().isoformat(timespec="seconds"),
            }
        )


def flash_firmware_to_miner(
    firmware_id: str,
    *,
    password: str | None = None,
    confirm: str = "",
    allow_incompatible: bool = False,
) -> dict:
    """
    Queue firmware flash for Go miner-poller (NetPacket :8889).
    Returns immediately with queued=True; UI polls /api/firmware/flash/status.
    serve never opens :8889 / never loads whatsminer.
    """
    conf = str(confirm or "").strip().lower()
    if conf not in ("yes", "confirm", "flash", "1", "go"):
        raise ValueError("confirm required (yes) — double-check in UI")
    if not _fw_cfg_load().get("enabled"):
        raise RuntimeError("firmware repository is disabled")
    if not miner_poller_process_alive():
        raise RuntimeError(
            "miner-poller not running — firmware flash only via poller "
            "(OTA poolheat-miner-poller)"
        )
    st0 = get_firmware_flash_status()
    if st0.get("busy"):
        if _flash_status_is_stale(st0):
            print(f"[firmware] clearing stale busy status: {st0.get('stage')}", flush=True)
            _clear_flash_status_file()
        else:
            raise RuntimeError(
                f"firmware flash already in progress "
                f"(stage={st0.get('stage')!r} · started {st0.get('started_at')})"
            )

    item = firmware_item_by_id(firmware_id)
    if not item:
        raise ValueError(f"firmware id not found: {firmware_id}")
    fpath = firmware_file_path(str(item.get("id")))
    if not fpath or not fpath.is_file():
        raise ValueError("firmware file missing on disk")

    miner_type = None
    platform = "h616"
    try:
        ident = get_miner_identity_cached(force=False)
        if isinstance(ident, dict):
            miner_type = str(ident.get("miner_type") or "").strip() or None
            plat = str(ident.get("platform") or ident.get("chip") or "").lower()
            if "h3" in plat:
                platform = "h3"
            elif "h6" in plat and "h616" not in plat:
                platform = "h6os"
    except Exception:
        pass
    models = list(item.get("models") or [])
    if (
        models
        and miner_type
        and not firmware_model_matches(miner_type, models)
        and not allow_incompatible
    ):
        raise ValueError(
            f"firmware models {models} not compatible with miner {miner_type} "
            f"(pass allow_incompatible=true to force)"
        )

    req_id = uuid.uuid4().hex
    pw = password if password not in (None, "") else DEFAULT_API_PASSWORD
    # Stage into DATA/miner_fw_cache so poller always has a local path
    # (works when UI is remote — never pass USB/host-only library paths).
    try:
        staged = _stage_firmware_for_poller(fpath, req_id)
    except Exception as e:
        raise RuntimeError(f"cannot stage firmware for poller: {e}") from e
    abs_path = str(staged.resolve())
    req = {
        "id": req_id,
        "ts": time.time(),
        "path": abs_path,
        "cache_dir": str(staged.parent),
        "filename": str(item.get("filename") or fpath.name),
        "firmware_id": str(item.get("id")),
        "platform": platform,
        "password": str(pw or ""),
        "miner_type": miner_type,
        "cleanup_cache": True,
    }
    seed = {
        "busy": True,
        "pct": 0,
        "stage": "queued",
        "error": None,
        "ok": None,
        "id": req_id,
        "filename": req["filename"],
        "path": abs_path,
        "started_at": datetime.now().isoformat(timespec="seconds"),
        "finished_at": None,
        "status_log": [],
    }
    try:
        _write_json_atomic(FIRMWARE_FLASH_STATUS_FILE, seed)
    except Exception as e:
        raise RuntimeError(f"cannot write flash status: {e}") from e
    with _FW_FLASH_LOCK:
        _FW_FLASH_STATE.update(seed)
    # req last so poller never sees req without status
    _write_json_atomic(FIRMWARE_FLASH_REQ_FILE, req)
    print(
        f"[firmware] staged+queued id={req_id} cache={abs_path} "
        f"platform={platform} → miner-poller",
        flush=True,
    )
    return {
        "ok": True,
        "queued": True,
        "id": req_id,
        "transport": "go-miner-poller",
        "firmware_id": str(item.get("id")),
        "filename": item.get("filename"),
        "miner_type": miner_type,
        "models": models,
        "path": abs_path,
        "staged": True,
        "platform": platform,
        "host": f"{HOST_MINER}:8889",
        "message": "flash staged to poller cache — poll /api/firmware/flash/status",
        "warning": (
            "Firmware via miner-poller NetPacket · ASIC may reboot · "
            "verify Firmware Version after reconnect"
        ),
    }


def _stage_firmware_for_poller(src: Path, req_id: str) -> Path:
    """
    Copy firmware image into DATA/miner_fw_cache/<req_id>/image.bin.

    Poller only reads this cache (same DATA volume as live_cache). When UI
    runs on an external host it still uploads/selects via edge HTTP; edge
    stages here so no USB/library path is required on the client.
    """
    src = Path(src)
    if not src.is_file():
        raise FileNotFoundError(str(src))
    dest_dir = DATA / "miner_fw_cache" / str(req_id)
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / "image.bin"
    # copy in chunks to avoid huge RAM spike
    with open(src, "rb") as inf, open(dest, "wb") as outf:
        while True:
            chunk = inf.read(1024 * 1024)
            if not chunk:
                break
            outf.write(chunk)
    meta = {
        "source": str(src),
        "bytes": dest.stat().st_size,
        "staged_at": datetime.now().isoformat(timespec="seconds"),
        "req_id": req_id,
    }
    try:
        (dest_dir / "meta.json").write_text(
            json.dumps(meta, ensure_ascii=False), encoding="utf-8"
        )
    except Exception:
        pass
    return dest


def _ensure_miner_poller_for_export() -> None:
    """
    Make sure miner-poller can accept export_log_req.json.
    If process looks dead, try start once; still raise with diagnostics if no IPC.
    """
    if miner_poller_process_alive():
        return
    # best-effort respawn (serve may own edge_miner_poller role)
    try:
        start_miner_poller_process()
    except Exception as e:
        print(f"[export-log] start poller: {e}", flush=True)
    # wait briefly for pidfile / process
    deadline = time.time() + 8.0
    while time.time() < deadline:
        if miner_poller_process_alive():
            return
        time.sleep(0.25)
    # diagnostics for UI
    pid_txt = ""
    try:
        if MINER_POLLER_PIDFILE.is_file():
            pid_txt = MINER_POLLER_PIDFILE.read_text(encoding="utf-8").strip()[:40]
    except Exception:
        pass
    live_age = None
    try:
        if LIVE_CACHE_FILE.is_file():
            live_age = round(time.time() - float(LIVE_CACHE_FILE.stat().st_mtime), 1)
    except Exception:
        pass
    raise RuntimeError(
        "miner-poller not running — export log only via poller"
        + (f" · pidfile={pid_txt or 'missing'}")
        + (f" · live_cache_age={live_age}s" if live_age is not None else " · no live_cache")
        + " · restart miner-poller from Info → Processes"
    )


def export_miner_log(*, password: str | None = None, timeout_sec: float = 90.0) -> dict:
    """
    Ask miner-poller to pull ASIC export-log (NetPacket cmd 20).
    Result file under DATA/export_logs/.
    """
    _ensure_miner_poller_for_export()
    req_id = uuid.uuid4().hex
    pw = password if password not in (None, "") else DEFAULT_API_PASSWORD
    req = {"id": req_id, "ts": time.time(), "password": str(pw or "")}
    try:
        if EXPORT_LOG_RESULT_FILE.is_file():
            EXPORT_LOG_RESULT_FILE.unlink()
    except Exception:
        pass
    _write_json_atomic(EXPORT_LOG_REQ_FILE, req)
    deadline = time.time() + max(15.0, float(timeout_sec))
    last_err = "timeout waiting for export-log"
    while time.time() < deadline:
        time.sleep(0.25)
        try:
            if not EXPORT_LOG_RESULT_FILE.is_file():
                # do not abort immediately — poller may be mid-restart; re-check soft
                if not miner_poller_process_alive():
                    # allow brief gap; only fail if still dead near end of wait
                    if time.time() + 3.0 >= deadline:
                        raise RuntimeError("miner-poller died during export-log")
                continue
            raw = json.loads(EXPORT_LOG_RESULT_FILE.read_text(encoding="utf-8"))
            if not isinstance(raw, dict) or str(raw.get("id") or "") != req_id:
                continue
            if not raw.get("ok"):
                raise RuntimeError(str(raw.get("error") or "export-log failed"))
            fn = str(raw.get("filename") or "")
            return {
                "ok": True,
                "path": raw.get("path"),
                "filename": fn,
                "bytes": raw.get("bytes"),
                "transport": raw.get("transport") or "go-miner-poller",
                "download": f"/api/miner/export-log/download?name={fn}",
            }
        except RuntimeError:
            raise
        except Exception as e:
            last_err = str(e)
            continue
    raise RuntimeError(last_err)


def list_export_logs() -> dict:
    """List ASIC export-log files under DATA/export_logs."""
    d = DATA / "export_logs"
    items: list[dict] = []
    try:
        if d.is_dir():
            for p in sorted(d.iterdir(), key=lambda x: x.stat().st_mtime, reverse=True):
                if not p.is_file():
                    continue
                try:
                    st = p.stat()
                    items.append({
                        "name": p.name,
                        "bytes": st.st_size,
                        "mtime": datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds"),
                        "download": f"/api/miner/export-log/download?name={p.name}",
                    })
                except Exception:
                    continue
    except Exception as e:
        return {"ok": False, "error": str(e), "items": []}
    return {"ok": True, "items": items, "dir": str(d)}


def _poolheat_usb_info() -> dict | None:
    """
    If poolheat data/lib is on USB (symlink migration), return usage + paths.
    Marker file: DATA/USB_ROOT or /opt/etc/poolheat/USB_ROOT (may itself be on USB).
    """
    candidates: list[Path] = []
    try:
        candidates.append(Path(DATA))
    except Exception:
        pass
    for p in (
        Path("/opt/var/poolheat"),
        Path("/opt/lib/poolheat"),
        Path("/opt/etc/poolheat"),
        Path("/opt/share/poolheat"),
    ):
        candidates.append(p)

    usb_root: str | None = None
    for base in candidates:
        try:
            marker = base / "USB_ROOT" if base.is_dir() else None
            if marker and marker.is_file():
                txt = marker.read_text(encoding="utf-8", errors="replace").strip()
                if txt:
                    usb_root = txt
                    break
        except Exception:
            pass
        try:
            if base.is_symlink() and _is_usb_path(os.path.realpath(str(base))):
                # parent of lib/var on stick is …/poolheat
                rp = Path(os.path.realpath(str(base)))
                usb_root = str(rp.parent if rp.name in ("lib", "var", "etc", "share") else rp)
                break
        except Exception:
            pass

    measure_path: Path | None = None
    if usb_root:
        measure_path = Path(usb_root)
    else:
        try:
            data_real = Path(os.path.realpath(str(DATA)))
            if _is_usb_path(data_real):
                measure_path = data_real
        except Exception:
            measure_path = None

    if not measure_path or not measure_path.exists():
        return None
    if not _is_usb_path(measure_path) and not (usb_root and _is_usb_path(usb_root)):
        # only report as USB install when on stick
        if not _is_usb_path(measure_path):
            return None

    ent = _disk_usage_entry(measure_path, "USB · poolheat")
    if not ent:
        return None
    ent["on_usb"] = True
    ent["usb_root"] = usb_root or str(measure_path)
    try:
        ent["data_real"] = os.path.realpath(str(DATA))
    except Exception:
        ent["data_real"] = str(DATA)
    return ent


def _host_swap_devices() -> list[dict]:
    """
    Parse /proc/swaps → per-device usage (zram, USB partition, file).
    Size/Used columns are in kB (Linux).
    """
    out: list[dict] = []
    try:
        with open("/proc/swaps", encoding="utf-8") as f:
            lines = f.read().splitlines()
    except Exception:
        return out
    for line in lines[1:]:  # skip header
        parts = line.split()
        if len(parts) < 5:
            continue
        fname, typ, size_kb, used_kb, prio = (
            parts[0],
            parts[1],
            parts[2],
            parts[3],
            parts[4],
        )
        try:
            size_b = int(size_kb) * 1024
            used_b = int(used_kb) * 1024
            priority = int(prio)
        except (TypeError, ValueError):
            continue
        kind = "other"
        label = fname
        low = fname.lower()
        if "zram" in low:
            kind = "zram"
            label = "zram (compressed RAM)"
        elif typ == "partition" and (
            "/dev/sd" in low
            or "/dev/mmc" in low
            or "/dev/usb" in low
            or "/dev/nvme" in low
        ):
            kind = "usb" if "/dev/sd" in low or "usb" in low else "disk"
            # resolve USB mount label when possible
            label = f"USB swap · {fname}" if kind == "usb" else f"disk · {fname}"
        elif typ == "file":
            kind = "file"
            if "/opt" in low or "/tmp/mnt" in low or "/mnt" in low:
                kind = "usb"
                label = f"USB swapfile · {fname}"
            else:
                label = f"swapfile · {fname}"
        out.append(
            {
                "path": fname,
                "type": typ,
                "kind": kind,
                "label": label,
                "size_b": size_b,
                "used_b": used_b,
                "free_b": max(0, size_b - used_b),
                "used_pct": round(100.0 * used_b / size_b, 1) if size_b else 0.0,
                "priority": priority,
            }
        )
    # highest priority first
    out.sort(key=lambda x: (-int(x.get("priority") or 0), str(x.get("path") or "")))
    return out


def ensure_usb_swap_priority(*, prefer_usb: bool = True) -> dict:
    """
    Keenetic often activates zram (prio 0) and USB swap partition (prio -1).
    Kernel then almost never pages to USB. Raise USB swap priority so the
    stick is actually used under RAM pressure (poolheat on 256MB routers).
    """
    result: dict = {"ok": False, "changed": False, "devices": [], "actions": []}
    devices = _host_swap_devices()
    result["devices"] = devices
    if not prefer_usb or not devices:
        result["ok"] = True
        result["note"] = "no swap devices" if not devices else "prefer_usb=false"
        return result
    usb = [d for d in devices if d.get("kind") == "usb"]
    zram = [d for d in devices if d.get("kind") == "zram"]
    if not usb:
        result["ok"] = True
        result["note"] = "no USB swap active"
        return result
    try:
        max_other = max(
            (int(d.get("priority") or 0) for d in devices if d.get("kind") != "usb"),
            default=-1,
        )
    except Exception:
        max_other = 0
    target_prio = max(5, max_other + 5)
    for d in usb:
        path = str(d.get("path") or "")
        cur = int(d.get("priority") or 0)
        if not path or cur >= target_prio:
            continue
        # swapoff + swapon -p N (Keenetic: busybox applets, not /sbin/swapon)
        def _run_swap(args: list[str]) -> subprocess.CompletedProcess:
            last: subprocess.CompletedProcess | None = None
            for prefix in (
                [],
                ["busybox"],
                ["/bin/busybox"],
                ["/sbin/busybox"],
            ):
                cmd = prefix + args
                try:
                    last = subprocess.run(
                        cmd,
                        capture_output=True,
                        text=True,
                        timeout=20,
                        check=False,
                    )
                    if last.returncode == 0 or "busybox" in cmd[0]:
                        # busybox returns 0/1; accept first successful path
                        if last.returncode == 0:
                            return last
                except FileNotFoundError:
                    continue
                except Exception as e:
                    last = subprocess.CompletedProcess(
                        cmd, 1, "", str(e)
                    )
            return last or subprocess.CompletedProcess(args, 1, "", "swap tools missing")

        try:
            _run_swap(["swapoff", path])
            proc = _run_swap(["swapon", "-p", str(target_prio), path])
            ok = proc.returncode == 0
            if not ok:
                # some builds ignore -p; try plain swapon
                proc = _run_swap(["swapon", path])
                ok = proc.returncode == 0
            result["actions"].append(
                {
                    "path": path,
                    "from_priority": cur,
                    "to_priority": target_prio if ok else cur,
                    "ok": ok,
                    "stderr": (proc.stderr or "")[:160],
                }
            )
            if ok:
                result["changed"] = True
        except Exception as e:
            result["actions"].append(
                {"path": path, "ok": False, "error": str(e)[:160]}
            )
    result["devices"] = _host_swap_devices()
    result["ok"] = True
    if result["changed"]:
        print(
            f"[swap] USB priority raised → {target_prio}: "
            + ", ".join(
                f"{a.get('path')} prio {a.get('from_priority')}→{a.get('to_priority')}"
                for a in result["actions"]
                if a.get("ok")
            ),
            flush=True,
        )
    return result


def _host_memory() -> dict | None:
    try:
        info: dict[str, int] = {}
        with open("/proc/meminfo", encoding="utf-8") as f:
            for line in f:
                parts = line.split()
                if len(parts) < 2:
                    continue
                key = parts[0].rstrip(":")
                try:
                    # values in kB
                    info[key] = int(parts[1]) * 1024
                except ValueError:
                    pass
        total = info.get("MemTotal")
        available = info.get("MemAvailable")
        free = info.get("MemFree")
        if total is None:
            return None
        used = total - (available if available is not None else (free or 0))
        swap_total = info.get("SwapTotal") or 0
        swap_free = info.get("SwapFree") or 0
        swap_used = max(0, swap_total - swap_free) if swap_total else 0
        devices = _host_swap_devices()
        usb_swap = next((d for d in devices if d.get("kind") == "usb"), None)
        return {
            "total_b": total,
            "available_b": available,
            "free_b": free,
            "used_b": used,
            "used_pct": round(100.0 * used / total, 1) if total else None,
            "swap_total_b": swap_total or None,
            "swap_free_b": swap_free if swap_total else None,
            "swap_used_b": swap_used if swap_total else None,
            "swap_used_pct": (
                round(100.0 * swap_used / swap_total, 1) if swap_total else None
            ),
            "swap_devices": devices,
            "swap_usb": bool(usb_swap),
            "swap_usb_path": (usb_swap or {}).get("path"),
            "swap_usb_priority": (usb_swap or {}).get("priority"),
            "swap_usb_used_b": (usb_swap or {}).get("used_b"),
            "swap_usb_size_b": (usb_swap or {}).get("size_b"),
        }
    except Exception:
        return None


def _pid_rss_b(pid: int) -> int | None:
    """VmRSS for pid in bytes."""
    try:
        with open(f"/proc/{int(pid)}/status", encoding="utf-8") as f:
            for line in f:
                if line.startswith("VmRSS:"):
                    # kB
                    return int(line.split()[1]) * 1024
    except Exception:
        return None
    return None


def _pid_cmdline(pid: int) -> str:
    try:
        raw = Path(f"/proc/{int(pid)}/cmdline").read_bytes()
        return raw.replace(b"\x00", b" ").decode("utf-8", errors="replace").strip()
    except Exception:
        return ""



def _pid_uptime_sec(pid: int) -> float | None:
    """Process uptime in seconds (Linux /proc; None on other OS)."""
    try:
        # /proc/uptime: seconds since boot
        up = float(Path("/proc/uptime").read_text(encoding="utf-8").split()[0])
        # /proc/pid/stat field 22 (1-based) = starttime in clock ticks
        stat = Path(f"/proc/{int(pid)}/stat").read_text(encoding="utf-8")
        # comm may contain spaces in () — split after last )
        rpar = stat.rfind(")")
        fields = stat[rpar + 2 :].split()
        # after comm: state is fields[0], starttime is fields[19] (stat field 22)
        start_ticks = float(fields[19])
        clk = float(os.sysconf("SC_CLK_TCK") or 100)
        start_sec = start_ticks / clk
        ut = up - start_sec
        if ut < 0:
            ut = 0.0
        return round(ut, 1)
    except Exception:
        return None


def _fmt_uptime_short(sec: float | None, *, lang: str = "en") -> str:
    if sec is None:
        return "—"
    try:
        s = int(max(0, float(sec)))
    except (TypeError, ValueError):
        return "—"
    d, s = divmod(s, 86400)
    h, s = divmod(s, 3600)
    m, s = divmod(s, 60)
    if lang.startswith("ru"):
        if d:
            return f"{d}д {h}ч {m}м"
        if h:
            return f"{h}ч {m}м"
        return f"{m}м {s}с"
    if d:
        return f"{d}d {h}h {m}m"
    if h:
        return f"{h}h {m}m"
    return f"{m}m {s}s"


def _poolheat_process_roles() -> dict:
    """
    RSS for poolheat processes: serve, miner-poller, devices-poller,
    and sniffer (tcpdump / miner_sniffer) when capture is running.

    Returns dict:
      processes: [{role, pid, rss_b, rss_mib, cmd}, ...]
      total_rss_b / total_rss_mib / count
    """
    found: dict[str, dict] = {}

    def _add(role: str, pid: int, cmd: str = "") -> None:
        if pid <= 0:
            return
        try:
            os.kill(pid, 0)
        except Exception:
            return
        rss = _pid_rss_b(pid)
        if not cmd:
            cmd = _pid_cmdline(pid)
        prev = found.get(role)
        # sniffer may be multi-process (python + tcpdump) — keep largest RSS
        if prev and prev.get("pid") == pid:
            return
        if prev and role == "sniffer" and (prev.get("rss_b") or 0) >= (rss or 0):
            return
        # allow multiple sniffer rows via unique role keys later; merge as one role
        # with max rss + note child pids in cmd if replacing
        if prev and role == "sniffer" and prev.get("pid") != pid:
            # sum RSS of sniffer family under one role
            prev_rss = int(prev.get("rss_b") or 0)
            new_rss = int(rss or 0)
            total = prev_rss + new_rss
            found[role] = {
                "role": role,
                "pid": prev.get("pid"),
                "pids": sorted(
                    {
                        int(prev.get("pid") or 0),
                        int(pid),
                        *[int(x) for x in (prev.get("pids") or []) if x],
                    }
                    - {0}
                ),
                "rss_b": total,
                "rss_mib": round(total / (1024 * 1024), 1),
                "cmd": (prev.get("cmd") or "")[:80]
                + " · +"
                + (cmd or str(pid))[:60],
            }
            return
        up = _pid_uptime_sec(pid)
        if role == "serve" and up is None:
            try:
                up = round(max(0.0, time.time() - float(_SERVE_BOOT_TS)), 1)
            except Exception:
                up = None
        ver = _role_service_version(role, cmd or "", pid=pid)
        exe = _pid_exe_path(pid) if role in ("miner-poller", "devices-poller") else ""
        found[role] = {
            "role": role,
            "pid": pid,
            "rss_b": rss,
            "rss_mib": round(rss / (1024 * 1024), 1) if rss is not None else None,
            "uptime_sec": up,
            "uptime": _fmt_uptime_short(up),
            "version": ver,
            "exe": (exe or "")[:200] or None,
            "exe_deleted": bool(exe) and ("(deleted)" in exe),
            "cmd": (cmd or "")[:160],
            "restartable": role in ("serve", "miner-poller", "devices-poller"),
        }

    # Self = main HTTP serve (unless we are a poller child)
    self_cmd = " ".join(sys.argv)
    self_pid = os.getpid()
    if "--miner-poller" in self_cmd or "miner-poller" in self_cmd:
        _add("miner-poller", self_pid, self_cmd)
    elif "--devices-poller" in self_cmd or "devices-poller" in self_cmd:
        _add("devices-poller", self_pid, self_cmd)
    else:
        _add("serve", self_pid, self_cmd)

    for role, pfile in (
        ("miner-poller", MINER_POLLER_PIDFILE),
        ("devices-poller", DEVICES_POLLER_PIDFILE),
    ):
        try:
            if pfile.is_file():
                pid = int(pfile.read_text().strip() or "0")
                if pid > 0 and pid != self_pid:
                    _add(role, pid)
        except Exception:
            pass

    # Sniffer when capture is running (module status + /proc)
    try:
        sn_pid = None
        st: dict = {}
        if _sniffer_mod is not None or _sniffer_module_present():
            try:
                cfg_body = get_sniffer_cfg()
                st = (
                    cfg_body.get("status")
                    if isinstance(cfg_body, dict)
                    else {}
                ) or {}
            except Exception:
                st = {}
        if isinstance(st, dict) and st.get("running"):
            try:
                sn_pid = int(st.get("pid") or 0) or None
            except (TypeError, ValueError):
                sn_pid = None
            if sn_pid:
                _add("sniffer", sn_pid, _pid_cmdline(sn_pid) or "miner_sniffer")
    except Exception:
        pass

    # Scan /proc for pollers + sniffer (tcpdump / miner_sniffer)
    try:
        for ent in Path("/proc").iterdir():
            if not ent.name.isdigit():
                continue
            pid = int(ent.name)
            if pid == self_pid:
                continue
            cmd = _pid_cmdline(pid)
            low = cmd.lower()
            if (
                "--miner-poller" in cmd
                or "miner-poller" in cmd
                or "poolheat-miner-poller" in cmd
            ):
                _add("miner-poller", pid, cmd)
            elif (
                "--devices-poller" in cmd
                or "devices-poller" in cmd
                or "poolheat-devices-poller" in cmd
            ):
                _add("devices-poller", pid, cmd)
            elif (
                "miner_sniffer" in low
                or "poolheat-sniffer" in low
                or (
                    "tcpdump" in low
                    and (
                        "poolheat" in low
                        or "sniffer" in low
                        or "/tmp/poolheat" in low
                    )
                )
            ):
                _add("sniffer", pid, cmd)
            elif "serve.py" in cmd and "--miner-poller" not in cmd and "--devices-poller" not in cmd:
                if "serve" not in found:
                    _add("serve", pid, cmd)
    except Exception:
        pass

    # stable order
    order = {
        "serve": 0,
        "miner-poller": 1,
        "devices-poller": 2,
        "sniffer": 3,
    }
    procs = sorted(found.values(), key=lambda p: order.get(p["role"], 9))
    for p in procs:
        if not p.get("version"):
            try:
                p["version"] = _role_service_version(
                    str(p.get("role") or ""),
                    str(p.get("cmd") or ""),
                    pid=int(p.get("pid") or 0) or None,
                )
            except Exception:
                pass
    total_rss = sum(int(p["rss_b"] or 0) for p in procs)
    return {
        "processes": procs,
        "total_rss_b": total_rss or None,
        "total_rss_mib": round(total_rss / (1024 * 1024), 1) if total_rss else None,
        "count": len(procs),
    }


def cleanup_tmp_and_logs(
    *,
    max_log_bytes: int = 2 * 1024 * 1024,
    max_pcap_age_sec: float = 24 * 3600,
    max_tmp_age_sec: float = 2 * 24 * 3600,
) -> dict:
    """
    Free RAM-backed /tmp and trim large log files under DATA.
    Safe to run at boot and via API.
    """
    now = time.time()
    removed: list[dict] = []
    freed = 0
    errors: list[str] = []

    def _unlink(path: Path, reason: str) -> None:
        nonlocal freed
        try:
            if not path.is_file() and not path.is_symlink():
                return
            sz = 0
            try:
                sz = int(path.stat().st_size)
            except Exception:
                pass
            path.unlink(missing_ok=True)
            freed += max(0, sz)
            removed.append(
                {"path": str(path), "bytes": sz, "reason": reason}
            )
        except Exception as e:
            errors.append(f"{path}: {e}")

    def _trim_log(path: Path) -> None:
        """Keep last ~max_log_bytes/2 of a growing log."""
        nonlocal freed
        try:
            if not path.is_file():
                return
            sz = path.stat().st_size
            if sz <= max_log_bytes:
                return
            keep = max(64 * 1024, max_log_bytes // 2)
            with open(path, "rb") as f:
                f.seek(max(0, sz - keep))
                tail = f.read()
            # drop partial first line
            nl = tail.find(b"\n")
            if nl >= 0 and nl + 1 < len(tail):
                tail = tail[nl + 1 :]
            path.write_bytes(tail)
            freed += max(0, sz - len(tail))
            removed.append(
                {
                    "path": str(path),
                    "bytes": sz - len(tail),
                    "reason": f"trim_log>{max_log_bytes}",
                }
            )
        except Exception as e:
            errors.append(f"trim {path}: {e}")

    # 1) sniffer pcap dir (default /tmp/poolheat-sniffer)
    pcap_dirs: list[Path] = []
    try:
        with _sniffer_cfg_lock:
            pdir = str(_sniffer_cfg.get("pcap_dir") or "/tmp/poolheat-sniffer")
        pcap_dirs.append(Path(pdir))
    except Exception:
        pcap_dirs.append(Path("/tmp/poolheat-sniffer"))
    pcap_dirs.append(Path("/tmp/poolheat-sniffer"))
    for pdir in {p.resolve() if p.exists() else p for p in pcap_dirs}:
        try:
            if not pdir.is_dir():
                continue
            for f in pdir.rglob("*"):
                if not f.is_file():
                    continue
                try:
                    age = now - f.stat().st_mtime
                except Exception:
                    age = 0
                # always drop old captures; also drop huge files
                try:
                    sz = f.stat().st_size
                except Exception:
                    sz = 0
                if age >= max_pcap_age_sec or sz > 8 * 1024 * 1024:
                    _unlink(f, "pcap_old_or_large")
        except Exception as e:
            errors.append(f"pcap {pdir}: {e}")

    # 2) other /tmp poolheat* leftovers
    try:
        tmp = Path("/tmp")
        if tmp.is_dir():
            for f in tmp.iterdir():
                name = f.name
                if not (
                    name.startswith("poolheat")
                    or name.startswith("poolheat-")
                    or "poolheat" in name
                ):
                    continue
                if f.is_dir():
                    # only known ephemeral dirs
                    if name == "poolheat-sniffer" or name.startswith("poolheat-upd"):
                        try:
                            for sub in f.rglob("*"):
                                if not sub.is_file():
                                    continue
                                try:
                                    age = now - sub.stat().st_mtime
                                    sz = sub.stat().st_size
                                except Exception:
                                    age, sz = max_tmp_age_sec, 0
                                # sniffer: age/size; upd temp: wipe all leftovers
                                if name.startswith("poolheat-upd") or age >= max_pcap_age_sec or sz > 8 * 1024 * 1024:
                                    _unlink(sub, "tmp_poolheat_dir")
                        except Exception as e:
                            errors.append(f"tmpdir {f}: {e}")
                    continue
                if f.is_file():
                    try:
                        age = now - f.stat().st_mtime
                        sz = f.stat().st_size
                    except Exception:
                        age, sz = 0, 0
                    if (
                        age >= max_tmp_age_sec
                        or sz > max_log_bytes
                        or name.endswith(".boot.log")
                    ):
                        _unlink(f, "tmp_poolheat_file")
    except Exception as e:
        errors.append(f"/tmp scan: {e}")

    # 3) DATA logs (USB usually — still free page cache / avoid growth)
    for logn in (
        "poolheat.log",
        "serve.boot.log",
        "devices_poller.log",
        "miner_poller.log",
    ):
        _trim_log(DATA / logn)
    for p in (
        Path("/tmp/poolheat-serve.boot.log"),
        Path("/opt/var/poolheat/poolheat.log"),
        Path("/opt/var/poolheat/serve.boot.log"),
    ):
        _trim_log(p)

    # optional sniffer module clear (best-effort)
    try:
        sn = clear_sniffer_cache(keep_current=False)
        if isinstance(sn, dict) and sn.get("deleted"):
            removed.append(
                {
                    "path": "sniffer_cache",
                    "bytes": int(sn.get("freed_bytes") or 0),
                    "reason": "sniffer_clear",
                }
            )
            freed += int(sn.get("freed_bytes") or 0)
    except Exception:
        pass

    return {
        "ok": True,
        "freed_b": freed,
        "freed_mib": round(freed / (1024 * 1024), 2),
        "removed": removed[:80],
        "removed_n": len(removed),
        "errors": errors[:20],
    }


def _host_uptime_sec() -> float | None:
    try:
        with open("/proc/uptime", encoding="utf-8") as f:
            return float(f.read().split()[0])
    except Exception:
        return None


def _collect_router_info() -> dict:
    router: dict = {
        "ok": False,
        "vendor": None,
        "model": None,
        "model_code": None,
        "title": None,
        "description": None,
        "device": None,
        "hw_version": None,
        "hw_id": None,
        "os_title": None,
        "os_release": None,
        "arch": None,
        "hostname": None,
        "device_tree_model": None,
        "kernel": None,
        "source": None,
    }
    dt = _read_text_file("/proc/device-tree/model")
    if dt:
        router["device_tree_model"] = dt
        # e.g. "Keenetic KN-2710"
        m = re.search(r"(KN-\d+)", dt, re.I)
        if m:
            router["model_code"] = m.group(1).upper()
        if "keenetic" in dt.lower():
            router["vendor"] = "Keenetic"
        router["model"] = dt
        router["ok"] = True
        router["source"] = "device-tree"

    # Prefer absolute path: Entware PATH is /opt/bin first; ndmc is Keenetic /bin
    ndmc_bin = None
    for cand in ("/bin/ndmc", "/usr/bin/ndmc", "ndmc"):
        if cand == "ndmc":
            # only if found on PATH
            try:
                which = subprocess.run(
                    ["which", "ndmc"],
                    capture_output=True,
                    text=True,
                    timeout=2,
                    check=False,
                )
                w = (which.stdout or "").strip().splitlines()
                if w and Path(w[0]).is_file():
                    ndmc_bin = w[0]
            except Exception:
                ndmc_bin = "ndmc"
            break
        if Path(cand).is_file():
            ndmc_bin = cand
            break
    if ndmc_bin:
        try:
            proc = subprocess.run(
                [ndmc_bin, "-c", "show version"],
                capture_output=True,
                text=True,
                timeout=6,
                check=False,
                env={
                    **os.environ,
                    "PATH": "/bin:/usr/bin:/sbin:/usr/sbin:"
                    + str(os.environ.get("PATH") or ""),
                },
            )
            text = (proc.stdout or "") + "\n" + (proc.stderr or "")
            kv = _parse_ndmc_kv(text)
            if kv:
                router["ok"] = True
                router["source"] = "ndmc"
                router["vendor"] = (
                    kv.get("vendor")
                    or kv.get("manufacturer")
                    or router.get("vendor")
                )
                # "Giant (KN-2610)" or bare device name
                router["model"] = (
                    kv.get("model")
                    or kv.get("description")
                    or kv.get("device")
                    or router.get("model")
                )
                router["device"] = kv.get("device") or router.get("device")
                router["description"] = kv.get("description") or router.get(
                    "description"
                )
                router["hw_version"] = kv.get("hw_version") or router.get("hw_version")
                router["hw_id"] = kv.get("hw_id") or router.get("hw_id")
                # KeeneticOS marketing title (e.g. 5.1.3) + full release
                router["os_title"] = (
                    kv.get("title") or kv.get("os") or router.get("os_title")
                )
                router["os_release"] = kv.get("release") or router.get("os_release")
                router["arch"] = kv.get("arch") or router.get("arch")
                # model often "Peak (KN-2710)" / hw_id KN-2610
                code_src = (
                    str(router.get("model") or "")
                    + " "
                    + str(kv.get("hw_id") or "")
                    + " "
                    + str(kv.get("description") or "")
                )
                m = re.search(r"(KN-\d+)", code_src, re.I)
                if m:
                    router["model_code"] = m.group(1).upper()
            elif proc.returncode != 0:
                router["ndmc_error"] = (
                    f"ndmc exit {proc.returncode}: {(proc.stderr or proc.stdout or '')[:120]}"
                )
            # hostname from show system (optional)
            try:
                proc2 = subprocess.run(
                    [ndmc_bin, "-c", "show system"],
                    capture_output=True,
                    text=True,
                    timeout=4,
                    check=False,
                    env={
                        **os.environ,
                        "PATH": "/bin:/usr/bin:/sbin:/usr/sbin:"
                        + str(os.environ.get("PATH") or ""),
                    },
                )
                kv2 = _parse_ndmc_kv((proc2.stdout or "") + "\n" + (proc2.stderr or ""))
                if kv2.get("hostname"):
                    router["hostname"] = kv2["hostname"]
                if kv2.get("model") and not router.get("model"):
                    router["model"] = kv2["model"]
                if kv2.get("hw_version") and not router.get("hw_version"):
                    router["hw_version"] = kv2["hw_version"]
            except Exception:
                pass
        except Exception as e:
            router["ndmc_error"] = str(e)

    # Fallbacks when ndmc missing / failed (still show something useful)
    try:
        u = os.uname()
        router["kernel"] = f"{u.sysname} {u.release}".strip()
        if not router.get("arch"):
            router["arch"] = u.machine
        # Keenetic kernel string: "4.9-ndm-5" + version comment has keenetic.com
        ver = _read_text_file("/proc/version") or ""
        if not router.get("vendor") and (
            "keenetic" in ver.lower() or "ndm" in (u.release or "").lower()
        ):
            router["vendor"] = "Keenetic"
            router["ok"] = True
            router["source"] = router.get("source") or "uname"
        if not router.get("os_title") and "ndm" in (u.release or "").lower():
            # no marketing title without ndmc — show kernel as OS hint
            router["os_title"] = router.get("os_title") or f"KeeneticOS · {u.release}"
            router["os_release"] = router.get("os_release") or u.version[:60]
    except Exception:
        pass

    if not router.get("hostname"):
        try:
            router["hostname"] = socket.gethostname()
        except Exception:
            pass
    if not router.get("arch"):
        try:
            router["arch"] = os.uname().machine
        except Exception:
            pass
    # Prefer friendly description when model is short device name only
    if router.get("description") and (
        not router.get("model")
        or str(router.get("model")).strip() == str(router.get("device") or "").strip()
    ):
        router["model"] = router["description"]
    return router


def _parse_detect_hash_rate(raw) -> list[float | None]:
    """
    API v3 miner.detect-hash-rate — EEPROM Tagged Hashrate per slot (GHS).
    Format: \"91153:91153:94080:94080\" (works in Suspend; no board power needed).
    """
    if raw is None:
        return []
    if isinstance(raw, (list, tuple)):
        out: list[float | None] = []
        for x in raw:
            v = _f(x)
            out.append(v if v is not None and v > 0 else None)
        return out
    s = str(raw).strip()
    if not s:
        return []
    out = []
    for part in s.replace(",", ":").split(":"):
        part = part.strip()
        if not part:
            out.append(None)
            continue
        v = _f(part)
        out.append(v if v is not None and v > 0 else None)
    return out


def _ghs_to_th(ghs: float | None) -> float | None:
    if ghs is None:
        return None
    try:
        g = float(ghs)
    except (TypeError, ValueError):
        return None
    if g <= 0:
        return None
    return g / 1000.0


def resolve_hashboard_layout(
    miner_type: str | None = None,
    *,
    n_devs: int | None = None,
    board_num: int | None = None,
) -> dict:
    """
    How many PCB/hashboard slots to show and which indices for charts.

    Delegates to miner_models.resolve_hashboard_layout (manufacturer + family
    catalog). Fallback keeps previous defaults if the module is missing.
    """
    if _mm_resolve_hashboard_layout is not None:
        return _mm_resolve_hashboard_layout(
            miner_type, n_devs=n_devs, board_num=board_num
        )
    # Fallback without miner_models
    n_guess = 4
    if n_devs and int(n_devs) > 0:
        n_guess = int(n_devs)
    elif board_num and int(board_num) > 0:
        n_guess = int(board_num)
    n_guess = max(1, min(8, n_guess))
    if n_guess >= 4:
        chart = [0, 2]
    elif n_guess >= 3:
        chart = [0, 1, 2]
    elif n_guess >= 2:
        chart = [0, 1]
    else:
        chart = [0]
    return {
        "boards": n_guess,
        "chart": chart,
        "model_key": "auto",
        "note": "auto (miner_models unavailable)",
    }


def _chart_slots_for_boards(n: int, preferred: list | None = None) -> list[int]:
    """Pick board indices for temp chart. 3-board ASICs → all three sensors."""
    n = max(1, min(8, int(n)))
    pref = [int(x) for x in (preferred or []) if isinstance(x, (int, float))]
    pref = [x for x in pref if 0 <= x < n]
    if n >= 4:
        if pref == [0, 2] or (len(pref) == 2 and pref[0] == 0 and pref[-1] == 2):
            return [0, 2]
        if len(pref) >= 2:
            return pref[:3]
        return [0, 2]
    if n >= 3:
        return [0, 1, 2]
    if n >= 2:
        return [0, 1]
    return [0]


def _boards_from_v3_device_msg(msg: dict | None) -> list[dict]:
    """
    PCB SN + Tagged Hashrate (detect-hash-rate) + chipdata from API v3 get.device.info.
    Available in Suspend — data lives in hashboard EEPROM.
    """
    if not isinstance(msg, dict):
        return []
    miner = msg.get("miner") if isinstance(msg.get("miner"), dict) else {}
    if not miner:
        return []
    rates = _parse_detect_hash_rate(miner.get("detect-hash-rate"))
    try:
        n = int(miner.get("board-num") or 0)
    except (TypeError, ValueError):
        n = 0
    if n <= 0:
        # infer from highest present pcbsn / rate
        n = max(len(rates), 4)
        for i in range(8):
            if miner.get(f"pcbsn{i}") or miner.get(f"chipdata{i}"):
                n = max(n, i + 1)
    n = max(1, min(8, n))
    boards: list[dict] = []
    for i in range(n):
        pcb = miner.get(f"pcbsn{i}") or miner.get(f"pcb_sn{i}") or miner.get(f"PCB SN{i}")
        if isinstance(pcb, str):
            pcb = pcb.strip() or None
        chip = miner.get(f"chipdata{i}") or miner.get(f"chip_data{i}")
        if isinstance(chip, str):
            chip = chip.strip() or None
        ghs = rates[i] if i < len(rates) else None
        boards.append(
            {
                "slot": i,
                "pcb_sn": pcb,
                "chip_data": chip,
                "tagged_ghs": ghs,
                "tagged_th": _ghs_to_th(ghs),
                "temp_c": None,
                "effective_chips": None,
                "source": "v3",
            }
        )
    return boards


def _merge_board_rows(primary: list[dict], secondary: list[dict]) -> list[dict]:
    """Merge board identity rows by slot — fill empty fields from secondary."""
    by_slot: dict[int, dict] = {}
    order: list[int] = []

    def _slot_of(b: dict, fallback: int) -> int:
        try:
            s = b.get("slot")
            if s is None:
                return fallback
            return int(s)
        except (TypeError, ValueError):
            return fallback

    # primary first (prefer EEPROM/v3 for SN + tagged)
    for i, b in enumerate(primary or []):
        if not isinstance(b, dict):
            continue
        sl = _slot_of(b, i)
        row = dict(b)
        row["slot"] = sl
        by_slot[sl] = row
        if sl not in order:
            order.append(sl)
    for i, b in enumerate(secondary or []):
        if not isinstance(b, dict):
            continue
        sl = _slot_of(b, i)
        if sl not in by_slot:
            row = dict(b)
            row["slot"] = sl
            by_slot[sl] = row
            order.append(sl)
            continue
        cur = by_slot[sl]
        for k, v in b.items():
            if k == "slot":
                continue
            if v in (None, "", []):
                continue
            if cur.get(k) in (None, "", []):
                cur[k] = v
    # stable slot order
    order_sorted = sorted(order)
    return [by_slot[s] for s in order_sorted if s in by_slot]


def _collect_miner_identity() -> dict:
    """
    ASIC identity for Info tab (PCB SN · Tagged · model · PSU).

    All ASIC I/O via miner_cmd → miner-poller IPC (no direct :4028/:4433).
    Disk cache seeds last-good boards so UI is not empty mid-refresh.
    """
    out: dict = {
        "ok": False,
        "host": f"{HOST_MINER}:{PORT_MINER}",
        "miner_type": None,
        "fw_ver": None,
        "api_ver": None,
        "platform": None,
        "chip": None,
        "mac": None,
        "minersn": None,
        # CustomerSn from get.device.custom_data — used when minersn empty
        "customer_sn": None,
        "sn_source": None,  # minersn | customer_sn | None
        "powersn": None,
        "psu_model": None,
        "psu_hw_version": None,
        "psu_sw_version": None,
        "hostname": None,
        "boards": [],
        # EEPROM factory / tagged hashrate (GHS + TH) — not live mining rate
        "factory_ghs": None,
        "factory_th": None,
        "tagged_ghs": None,  # sum of board tagged (alias factory when present)
        "tagged_th": None,
        "board_num": None,
        "hash_board": None,
        "error": None,
    }
    # Seed last-good identity so boards don't flash empty while we re-read
    try:
        disk = _load_miner_id_disk() or {}
        if isinstance(disk, dict):
            for k, v in disk.items():
                if k in out and v not in (None, "", []):
                    out[k] = v
    except Exception:
        pass
    try:
        live = hydrate_live_from_disk(max_age_sec=LIVE_STALE_MAX_SEC) or {}
        if isinstance(live, dict):
            if live.get("psu_model") and not out.get("psu_model"):
                out["psu_model"] = live.get("psu_model")
            if live.get("board_count") is not None and not out.get("board_num"):
                out["board_num"] = live.get("board_count")
            out["host"] = live.get("host") or out["host"]
    except Exception:
        pass

    if not miner_poller_process_alive():
        out["ok"] = bool(
            out.get("miner_type")
            or out.get("minersn")
            or out.get("mac")
            or (out.get("boards") or [])
        )
        if not out["ok"]:
            out["error"] = "miner-poller not running — cannot refresh identity"
        else:
            out["error"] = None
            out["source"] = "disk+live (poller down)"
        return out

    try:
        ver = miner_cmd({"cmd": "get_version"}, timeout=8).get("Msg") or {}
        if isinstance(ver, dict):
            out["miner_type"] = ver.get("miner_type") or out.get("miner_type")
            out["fw_ver"] = ver.get("fw_ver") or out.get("fw_ver")
            out["api_ver"] = ver.get("api_ver") or out.get("api_ver")
            out["platform"] = ver.get("platform") or out.get("platform")
            out["chip"] = ver.get("chip") or out.get("chip")
        info = miner_cmd({"cmd": "get_miner_info"}, timeout=8).get("Msg") or {}
        if isinstance(info, dict):
            out["mac"] = info.get("mac") or out.get("mac")
            msn = _normalize_sn(info.get("minersn"))
            if msn:
                out["minersn"] = msn
            psn = info.get("powersn")
            if psn not in (None, ""):
                out["powersn"] = psn
            if info.get("hostname"):
                out["hostname"] = info.get("hostname")
        try:
            psu = miner_cmd({"cmd": "get_psu"}, timeout=8).get("Msg") or {}
            if isinstance(psu, dict):
                out["psu_model"] = psu.get("model") or psu.get("name") or out.get("psu_model")
                out["psu_hw_version"] = psu.get("hw_version") or out.get("psu_hw_version")
                out["psu_sw_version"] = psu.get("sw_version") or out.get("psu_sw_version")
                if not out.get("powersn"):
                    sn = psu.get("serial_no")
                    out["powersn"] = sn if sn not in (None, "") else None
        except Exception:
            pass

        # summary.Factory GHS — EEPROM total; works in Suspend
        try:
            sm = miner_cmd({"cmd": "summary"}, timeout=8).get("Msg") or {}
            if isinstance(sm, dict):
                fg = _f(sm.get("Factory GHS") or sm.get("factory_ghs"))
                if fg is not None and fg > 0:
                    out["factory_ghs"] = fg
                    out["factory_th"] = _ghs_to_th(fg)
        except Exception:
            pass

        boards_devs: list[dict] = []
        try:
            devs_raw = miner_cmd({"cmd": "devs"}, timeout=10)
            devs = (
                (devs_raw.get("DEVS") if isinstance(devs_raw, dict) else None) or []
            )
            for d in devs if isinstance(devs, list) else []:
                if not isinstance(d, dict):
                    continue
                # per-board Factory GHS = Tagged Hashrate (EEPROM)
                ghs = _f(d.get("Factory GHS") or d.get("factory_ghs"))
                if ghs is not None and ghs <= 0:
                    ghs = None
                boards_devs.append(
                    {
                        "slot": d.get("Slot"),
                        "pcb_sn": d.get("PCB SN") or d.get("pcb_sn"),
                        "chip_data": d.get("Chip Data") or d.get("chip_data"),
                        "temp_c": _f(d.get("Temperature")),
                        "effective_chips": d.get("Effective Chips"),
                        "tagged_ghs": ghs,
                        "tagged_th": _ghs_to_th(ghs),
                        "source": "devs",
                    }
                )
        except Exception:
            pass

        # API v3: PCB SN + detect-hash-rate even when Suspend (devs fails)
        boards_v3: list[dict] = []
        try:
            v3_msg = _fetch_v3_device_msg()
            if isinstance(v3_msg, dict):
                boards_v3 = _boards_from_v3_device_msg(v3_msg)
                miner = (
                    v3_msg.get("miner")
                    if isinstance(v3_msg.get("miner"), dict)
                    else {}
                )
                if miner:
                    if not out.get("miner_type") and miner.get("type"):
                        out["miner_type"] = miner.get("type")
                    if not out.get("minersn"):
                        msn = miner.get("miner-sn") or miner.get("minersn")
                        out["minersn"] = _normalize_sn(msn)
                    # CustomerSn may also appear under miner custom fields
                    if not out.get("customer_sn"):
                        out["customer_sn"] = _normalize_sn(
                            miner.get("CustomerSn")
                            or miner.get("customer_sn")
                            or miner.get("customerSn")
                        )
                    try:
                        bn = int(miner.get("board-num") or 0)
                        if bn > 0:
                            out["board_num"] = bn
                    except (TypeError, ValueError):
                        pass
                    hb = miner.get("hash-board") or miner.get("hash_board")
                    if hb:
                        out["hash_board"] = hb
                    if not out.get("chip"):
                        cd0 = miner.get("chipdata0")
                        if cd0:
                            out["chip"] = cd0
                net = (
                    v3_msg.get("network")
                    if isinstance(v3_msg.get("network"), dict)
                    else {}
                )
                if net and not out.get("mac") and net.get("mac"):
                    out["mac"] = net.get("mac")
                pwr = (
                    v3_msg.get("power")
                    if isinstance(v3_msg.get("power"), dict)
                    else {}
                )
                if isinstance(pwr, dict):
                    if not out.get("powersn") and pwr.get("sn"):
                        out["powersn"] = pwr.get("sn")
                    if not out.get("psu_model"):
                        out["psu_model"] = pwr.get("model") or pwr.get("type")
                sys_ = (
                    v3_msg.get("system")
                    if isinstance(v3_msg.get("system"), dict)
                    else {}
                )
                if isinstance(sys_, dict):
                    if not out.get("fw_ver") and sys_.get("fwversion"):
                        out["fw_ver"] = sys_.get("fwversion")
                    if not out.get("platform") and sys_.get("platform"):
                        out["platform"] = sys_.get("platform")
                    if not out.get("api_ver") and sys_.get("api"):
                        out["api_ver"] = str(sys_.get("api"))
        except Exception as e:
            print(f"[ident] v3 device: {e}")

        # CustomerSn (API v3 get.device.custom_data) — fallback when minersn empty
        if not out.get("customer_sn"):
            try:
                csn = _fetch_customer_sn()
                if csn:
                    out["customer_sn"] = csn
            except Exception as e:
                print(f"[ident] customer_sn: {e}")

        # Prefer v3 for EEPROM fields (works in Suspend); merge live temp/chips from devs
        if boards_v3:
            out["boards"] = _merge_board_rows(boards_v3, boards_devs)
        else:
            out["boards"] = boards_devs

        # Sum tagged from boards if factory total missing
        sum_ghs = 0.0
        any_tagged = False
        for b in out["boards"]:
            g = _f(b.get("tagged_ghs"))
            if g is not None and g > 0:
                sum_ghs += g
                any_tagged = True
        if any_tagged:
            out["tagged_ghs"] = sum_ghs
            out["tagged_th"] = _ghs_to_th(sum_ghs)
            if out.get("factory_ghs") is None:
                out["factory_ghs"] = sum_ghs
                out["factory_th"] = out["tagged_th"]
        elif out.get("factory_ghs") is not None:
            out["tagged_ghs"] = out["factory_ghs"]
            out["tagged_th"] = out.get("factory_th")

        if out.get("board_num") is None and out["boards"]:
            out["board_num"] = len(out["boards"])

        # Display SN: minersn if set, else CustomerSn
        out["minersn"] = _normalize_sn(out.get("minersn"))
        out["customer_sn"] = _normalize_sn(out.get("customer_sn"))
        eff, src = _effective_miner_sn(out)
        out["sn_source"] = src
        # convenience field for UI / TG (never invent fake SN)
        out["display_sn"] = eff

        out["ok"] = bool(
            out.get("miner_type")
            or out.get("mac")
            or out.get("boards")
            or out.get("factory_ghs")
            or out.get("customer_sn")
        )
        out["error"] = None
        out["source"] = "poller-ipc"
    except Exception as e:
        out["error"] = str(e)
        # keep seeded boards / type from disk if live refresh failed
        if not out.get("ok"):
            out["ok"] = bool(
                out.get("miner_type")
                or out.get("mac")
                or out.get("boards")
                or out.get("factory_ghs")
            )
    return out


def collect_system_info(*, force_miner: bool = False) -> dict:
    """Router + miner identity + host resources for Info tab.

    force_miner=True refreshes ASIC identity (slow); router/ndmc always live.
    """
    disks: list[dict] = []
    seen: set[str] = set()

    def _add_disk(ent: dict | None) -> None:
        if not ent:
            return
        key = f"{ent['total_b']}:{ent['free_b']}:{ent.get('used_b')}"
        if key in seen:
            return
        seen.add(key)
        disks.append(ent)

    # USB first when poolheat lives on the stick (symlinks under /opt → /tmp/mnt/…)
    usb_info = _poolheat_usb_info()
    if usb_info:
        _add_disk(usb_info)

    # resolved DATA FS (may be same as USB — de-duped)
    try:
        data_real = Path(os.path.realpath(str(DATA)))
        if data_real.exists():
            lab = "poolheat data"
            if _is_usb_path(data_real):
                lab = "USB · poolheat data"
            _add_disk(_disk_usage_entry(data_real, lab))
    except Exception:
        pass

    # skip rootfs (always full)
    for path, label in (
        ("/opt", "/opt (Entware)"),
        ("/storage", "/storage"),
        ("/tmp", "/tmp"),
    ):
        _add_disk(_disk_usage_entry(path, label))

    db_size = None
    try:
        if DB_FILE.is_file():
            db_size = DB_FILE.stat().st_size
    except Exception:
        pass

    data_real_s = None
    try:
        data_real_s = os.path.realpath(str(DATA))
    except Exception:
        data_real_s = str(DATA)

    # Router first (fast ndmc) so Info tab never waits on ASIC for model/OS
    router = _collect_router_info()
    try:
        miner = get_miner_identity_cached(force=bool(force_miner))
    except Exception as e:
        miner = {"ok": False, "error": str(e)[:160]}
    result = {
        "ok": True,
        "ts": datetime.now().isoformat(timespec="seconds"),
        "router": router,
        "miner": miner,
        "resources": {
            "disks": disks,
            "memory": _host_memory(),
            "processes": _poolheat_process_roles(),
            "uptime_sec": _host_uptime_sec(),
            "history_db_b": db_size,
            "history_db_path": str(DB_FILE),
            "data_path": str(DATA),
            "data_real_path": data_real_s,
            "www_path": str(ROOT),
            "on_usb": bool(usb_info),
            "usb": usb_info,
        },
        "poolheat": {
            **get_version_info(),
            "http_port": HTTP_PORT,
            "poll_interval_sec": int(POLL_INTERVAL_SEC),
            "dry_run": bool(DRY_RUN),
            "miner_host": f"{HOST_MINER}:{PORT_MINER}",
            "on_usb": bool(usb_info),
            "usb_root": (usb_info or {}).get("usb_root") if usb_info else None,
            "roles": get_roles(),
            "architecture": {
                "planes": {
                    "edge": "miner poller · devices poller · luci proxy · edge API",
                    "app": "web UI · telegram bot (later: external server)",
                },
                "deployment": get_roles().get("deployment"),
                "doc": "ARCHITECTURE.md",
            },
        },
    }
    # full Info snapshot for instant UI (models/versions/boards/resources)
    try:
        cache_blob = dict(result)
        cache_blob["cached_at"] = result["ts"]
        INFO_CACHE_FILE.write_text(
            json.dumps(cache_blob, ensure_ascii=False), encoding="utf-8"
        )
    except Exception:
        pass
    return result


def load_info_cache() -> dict | None:
    """Last successful Info snapshot (router/miner) for fast UI paint."""
    try:
        if not INFO_CACHE_FILE.is_file():
            return None
        data = json.loads(INFO_CACHE_FILE.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def _read_version_file(path: Path) -> str | None:
    try:
        if path.is_file():
            v = path.read_text(encoding="utf-8").strip().splitlines()[0].strip()
            return v or None
    except Exception:
        pass
    return None


def get_app_version() -> str:
    """Installed software version (semver-ish)."""
    env = (os.environ.get("POOLHEAT_VERSION") or "").strip()
    if env:
        return env
    here = Path(__file__).resolve().parent
    for p in (
        here / "VERSION",
        ROOT / "VERSION",
        Path("/opt/lib/poolheat/VERSION"),
        Path("/opt/share/poolheat/VERSION"),
        here.parent / "VERSION",  # repo root when running from ui/
    ):
        v = _read_version_file(p)
        if v:
            return v
    return _DEFAULT_APP_VERSION


def parse_version_tuple(s: str) -> tuple:
    """Parse 'v0.2.0-1' → (0, 2, 0). Non-numeric → (0,)."""
    if not s:
        return (0,)
    core = str(s).strip().lstrip("vV").split("+")[0].split("-")[0]
    parts: list[int] = []
    for p in core.split("."):
        try:
            parts.append(int(re.sub(r"[^0-9].*", "", p) or "0"))
        except ValueError:
            parts.append(0)
    return tuple(parts) if parts else (0,)


def version_cmp(a: str, b: str) -> int:
    """-1 if a<b, 0 if equal, 1 if a>b (numeric semver core)."""
    ta, tb = parse_version_tuple(a), parse_version_tuple(b)
    n = max(len(ta), len(tb))
    ta = ta + (0,) * (n - len(ta))
    tb = tb + (0,) * (n - len(tb))
    if ta < tb:
        return -1
    if ta > tb:
        return 1
    return 0


def get_version_info() -> dict:
    host = detect_host_package_arch()
    return {
        "version": get_app_version(),
        "github_repo": GITHUB_REPO,
        "github_branch": GITHUB_BRANCH,
        "github_url": f"https://github.com/{GITHUB_REPO}",
        "host_machine": host.get("machine"),
        "host_pkg_arch": host.get("pkg_arch"),
        "host_arch_source": host.get("source"),
    }


def _http_json(url: str, timeout: float = 12.0) -> dict | list:
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": f"poolheat/{get_app_version()}",
            "Accept": "application/vnd.github+json",
        },
        method="GET",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read()
    return json.loads(raw.decode("utf-8", errors="replace"))


def _http_text(url: str, timeout: float = 12.0) -> str:
    req = urllib.request.Request(
        url,
        headers={"User-Agent": f"poolheat/{get_app_version()}"},
        method="GET",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read().decode("utf-8", errors="replace")


def _http_bytes(url: str, timeout: float = 60.0) -> bytes:
    req = urllib.request.Request(
        url,
        headers={"User-Agent": f"poolheat/{get_app_version()}"},
        method="GET",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read()


def _http_download_to_file(
    url: str,
    dest: Path,
    *,
    timeout: float = 300.0,
    chunk_size: int = 256 * 1024,
) -> int:
    """
    Stream HTTP body to disk (avoids holding full OTA package in RAM).
    Critical on Giant (256 MiB): 8–15 MiB package + extract used to OOM/thrash.
    Returns bytes written.
    """
    req = urllib.request.Request(
        url,
        headers={"User-Agent": f"poolheat/{get_app_version()}"},
        method="GET",
    )
    dest.parent.mkdir(parents=True, exist_ok=True)
    written = 0
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        with dest.open("wb") as fh:
            while True:
                chunk = resp.read(chunk_size)
                if not chunk:
                    break
                fh.write(chunk)
                written += len(chunk)
                if written and written % (2 * 1024 * 1024) < chunk_size:
                    _set_update_phase(
                        "downloading",
                        f"{written // (1024 * 1024)} MiB",
                    )
    return written


def _set_update_phase(phase: str | None, detail: str | None = None) -> None:
    try:
        _update_state["phase"] = phase
        _update_state["phase_detail"] = detail
    except Exception:
        pass


def _stop_pollers_for_ota() -> None:
    """
    Stop Go pollers before replacing their ELF binaries.
    Linux allows rename-over-running-exec, but on USB/Entware Keenetic
    we still hit ETXTBSY / thrash when two 7–8 MiB pollers stay mapped.
    """
    needles = (
        "poolheat-devices-poller",
        "poolheat-miner-poller",
    )
    killed: list[str] = []
    try:
        for ent in Path("/proc").iterdir():
            if not ent.name.isdigit():
                continue
            try:
                raw = (ent / "cmdline").read_bytes()
            except Exception:
                continue
            cmd = raw.replace(b"\x00", b" ").decode("utf-8", errors="replace")
            for n in needles:
                if n in cmd:
                    try:
                        os.kill(int(ent.name), 15)
                        killed.append(f"{n}:{ent.name}")
                    except Exception:
                        pass
                    break
        if killed:
            time.sleep(0.8)
            # SIGKILL leftovers
            for ent in Path("/proc").iterdir():
                if not ent.name.isdigit():
                    continue
                try:
                    raw = (ent / "cmdline").read_bytes()
                except Exception:
                    continue
                cmd = raw.replace(b"\x00", b" ").decode("utf-8", errors="replace")
                for n in needles:
                    if n in cmd:
                        try:
                            os.kill(int(ent.name), 9)
                        except Exception:
                            pass
                        break
            print(f"[update] stopped pollers for OTA: {', '.join(killed)}", flush=True)
    except Exception as e:
        print(f"[update] stop pollers: {e}", flush=True)
    for pidf in (
        Path("/opt/var/poolheat/devices_poller.pid"),
        Path("/opt/var/poolheat/miner_poller.pid"),
    ):
        try:
            pidf.unlink(missing_ok=True)
        except Exception:
            pass


def _normalize_notes_lang(lang: str | None) -> str:
    s = str(lang or "en").strip().lower()
    if s.startswith("ru") or s in ("рус", "russian", "русск"):
        return "ru"
    return "en"


def _strip_md_fenced_code(text: str) -> str:
    """
    Blank out fenced code blocks (``` … ``` / ~~~ … ~~~) so language
    markers inside documentation examples are not treated as real sections.
    Replaces non-newline chars with spaces to keep offsets aligned with
    the original text.
    """
    if not text:
        return text

    def _blank(m: re.Match) -> str:
        return re.sub(r"[^\n]", " ", m.group(0))

    return re.sub(
        r"(?ms)^[ \t]*(```|~~~)[^\n]*\n.*?^[ \t]*\1[ \t]*$",
        _blank,
        text,
    )


def _looks_like_notes_placeholder(chunk: str) -> bool:
    """True for example/placeholder RU/EN snippets, not real release notes."""
    s = (chunk or "").strip()
    if not s:
        return True
    # very short example lines from docs ("Русский текст…", "English text…")
    if len(s) < 48 and re.search(
        r"(текст|text|feature|фича|fix|исправлен)\s*[.…]*$", s, re.I
    ):
        return True
    # leftover fence / behaviour docs leaked after a bogus split
    if "### Behaviour" in s or "### Behavior" in s:
        return True
    if re.search(r"UI\s+\*\*RU\*\*", s):
        return True
    return False


def _split_bilingual_release_notes(body: str) -> dict[str, str]:
    """
    Split a GitHub release body into language sections.

    Supported layouts (any one is enough):

    1) HTML comment markers:
         <!--en-->  ...english...
         <!--ru-->  ...russian...
       (also: <!--lang:en-->, <!--english-->, <!--русский-->)

    2) Markdown headings:
         ## English
         ...
         ## Русский
         ...
       (also: ## EN / ## RU / ## Russian)

    Markers inside fenced code blocks (``` … ```) are ignored so that
    documentation-style release bodies (with authoring examples) are not
    mis-parsed as bilingual notes.

    If no markers found, the whole body is treated as English (default).
    """
    text = (body or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not text:
        return {}

    def _canon(tok: str) -> str | None:
        t = (tok or "").strip().lower()
        if t in ("en", "eng", "english", "англ", "английский"):
            return "en"
        if t in ("ru", "rus", "russian", "рус", "русский", "русская", "русск"):
            return "ru"
        if t.startswith("ru") or "русск" in t:
            return "ru"
        if t.startswith("en") or "англ" in t:
            return "en"
        return None

    # Find markers only outside code fences; slice chunks from original text
    # (fence blanking preserves character offsets).
    search_text = _strip_md_fenced_code(text)
    sections: dict[str, str] = {}

    # 1) <!--en--> / <!--lang:ru--> markers (outside fences only)
    marker_re = re.compile(
        r"<!--\s*(?:lang\s*[:=]\s*)?"
        r"(en|eng|english|ru|rus|russian|русск\w*|англ\w*)"
        r"\s*-->",
        re.I,
    )
    matches = list(marker_re.finditer(search_text))
    if matches:
        for idx, m in enumerate(matches):
            lang = _canon(m.group(1))
            if not lang:
                continue
            start = m.end()
            end = matches[idx + 1].start() if idx + 1 < len(matches) else len(text)
            chunk = text[start:end].strip()
            if chunk and not _looks_like_notes_placeholder(chunk):
                sections[lang] = chunk
        pre = text[: matches[0].start()].strip()
        if pre and "en" not in sections and not _looks_like_notes_placeholder(pre):
            sections["en"] = pre
        if sections:
            return sections

    # 2) ## English / ## Русский headings (at line start, outside fences)
    head_re = re.compile(
        r"(?m)^(#{1,3}\s*)"
        r"(English|EN|Eng|Английский|Russian|RU|Rus|Русский|Русская)\s*$",
        re.I,
    )
    matches = list(head_re.finditer(search_text))
    if matches:
        for idx, m in enumerate(matches):
            lang = _canon(m.group(2))
            if not lang:
                continue
            start = m.end()
            end = matches[idx + 1].start() if idx + 1 < len(matches) else len(text)
            chunk = text[start:end].strip()
            # drop a horizontal rule right after heading
            chunk = re.sub(r"^(?:---|\*\*\*|___)\s*\n+", "", chunk)
            if chunk and not _looks_like_notes_placeholder(chunk):
                sections[lang] = chunk
        pre = text[: matches[0].start()].strip()
        if pre and "en" not in sections and not _looks_like_notes_placeholder(pre):
            sections["en"] = pre
        if sections:
            return sections

    # 3) no structure → entire body is default English
    return {"en": text}


def _select_release_notes(
    body: str | None, *, lang: str = "en"
) -> dict:
    """
    Pick notes for UI language. Prefer requested lang; else English; else any.
    """
    want = _normalize_notes_lang(lang)
    raw = (body or "").replace("\r\n", "\n").strip()
    split = _split_bilingual_release_notes(raw) if raw else {}
    notes_en = (split.get("en") or "").strip() or None
    notes_ru = (split.get("ru") or "").strip() or None
    # if only one blob stored as en and request ru — fallback
    chosen = None
    used = "en"
    fallback = False
    if want == "ru" and notes_ru:
        chosen, used = notes_ru, "ru"
    elif want == "en" and notes_en:
        chosen, used = notes_en, "en"
    elif notes_en:
        chosen, used, fallback = notes_en, "en", want != "en"
    elif notes_ru:
        chosen, used, fallback = notes_ru, "ru", want != "ru"
    elif raw:
        chosen, used, fallback = raw, "en", want != "en"

    # soft cap for UI
    def _cap(s: str | None) -> str | None:
        if not s:
            return None
        s = s.strip()
        return s[:4000] if s else None

    available = [k for k in ("en", "ru") if split.get(k)]
    if not available and chosen:
        available = [used]

    return {
        "notes": _cap(chosen),
        "notes_lang": used if chosen else None,
        "notes_fallback": bool(fallback and chosen),
        "notes_en": _cap(notes_en) if notes_en else (_cap(raw) if raw and not notes_ru else None),
        "notes_ru": _cap(notes_ru),
        "notes_available": available,
    }


# ── Host architecture → GitHub release package ─────────────────────────────
# Release assets (see packaging/entware/build-ipk.sh):
#   poolheat_${ver}_${pkg_arch}.ipk
#   poolheat-${ver}-opt-${pkg_arch}.tar.gz   (optional; preferred when present)
#   poolheat-${ver}-opt.tar.gz              (legacy single-arch; last resort)

# ELF e_machine (little-endian)
_ELF_EM_MIPS = 8
_ELF_EM_ARM = 40
_ELF_EM_X86_64 = 62
_ELF_EM_AARCH64 = 183

# Entware package architecture tags used in asset filenames
_PKG_ARCH_AARCH64 = "aarch64-3.10"
_PKG_ARCH_MIPSELSF = "mipselsf-3.4"

# Prefer higher score when matching release assets
_PKG_ARCH_ALIASES: dict[str, tuple[str, ...]] = {
    _PKG_ARCH_AARCH64: (
        "aarch64-3.10",
        "aarch64_3.10",
        "aarch64",
        "arm64",
    ),
    _PKG_ARCH_MIPSELSF: (
        "mipselsf-3.4",
        "mipselsf_3.4",
        "mipselsf",
        "mipsel",
        "mips",
    ),
}


def _elf_machine(path: Path | str | bytes | None) -> int | None:
    """Return ELF e_machine or None if not a valid ELF."""
    try:
        if isinstance(path, (bytes, bytearray)):
            b = bytes(path[:20])
        else:
            p = Path(path) if not isinstance(path, Path) else path
            if not p.is_file():
                return None
            with p.open("rb") as f:
                b = f.read(20)
        if len(b) < 20 or b[:4] != b"\x7fELF":
            return None
        # e_machine at offset 18 (little-endian for our targets)
        return int.from_bytes(b[18:20], "little")
    except Exception:
        return None


def _expected_elf_for_pkg_arch(pkg_arch: str) -> set[int]:
    a = str(pkg_arch or "").lower()
    if "mips" in a:
        return {_ELF_EM_MIPS}
    if "aarch64" in a or a in ("arm64",):
        return {_ELF_EM_AARCH64}
    if a.startswith("arm") or "armv7" in a:
        return {_ELF_EM_ARM, _ELF_EM_AARCH64}
    return set()


def detect_host_package_arch() -> dict:
    """
    Detect router CPU / Entware package architecture for OTA asset selection.

    Returns:
      machine: uname -m (aarch64, mips, …)
      pkg_arch: Entware tag used in release filenames (aarch64-3.10 / mipselsf-3.4)
      elf_ok: set of acceptable ELF e_machine values for Go pollers
      source: how pkg_arch was decided
    """
    machine = ""
    try:
        machine = (os.uname().machine or "").strip().lower()
    except Exception:
        try:
            machine = (os.environ.get("HOSTTYPE") or "").strip().lower()
        except Exception:
            machine = ""

    # Entware: /opt/etc/opkg.conf → arch aarch64-3.10 1
    opkg_archs: list[str] = []
    try:
        conf = Path("/opt/etc/opkg.conf")
        if conf.is_file():
            for line in conf.read_text(encoding="utf-8", errors="replace").splitlines():
                line = line.strip()
                if line.startswith("arch "):
                    parts = line.split()
                    if len(parts) >= 2:
                        opkg_archs.append(parts[1].strip().lower())
    except Exception:
        pass

    source = "uname"
    pkg_arch = ""
    # Prefer explicit Entware arch from opkg.conf
    for a in opkg_archs:
        if "mipsel" in a or a.startswith("mips"):
            pkg_arch = _PKG_ARCH_MIPSELSF
            source = "opkg.conf"
            break
        if "aarch64" in a or a in ("arm64",):
            pkg_arch = _PKG_ARCH_AARCH64
            source = "opkg.conf"
            break

    if not pkg_arch:
        if machine in ("aarch64", "arm64"):
            pkg_arch = _PKG_ARCH_AARCH64
        elif machine in ("mips", "mipsel", "mips64", "mips64el"):
            pkg_arch = _PKG_ARCH_MIPSELSF
        elif machine.startswith("arm"):
            # rare 32-bit Keenetic — no dedicated package yet; try aarch64 only if 64
            pkg_arch = _PKG_ARCH_AARCH64 if "64" in machine else _PKG_ARCH_AARCH64
            source = "uname-arm-fallback"
        else:
            # last resort: inspect currently installed poller ELF
            em = _elf_machine("/opt/bin/poolheat-devices-poller") or _elf_machine(
                "/opt/bin/poolheat-miner-poller"
            )
            if em == _ELF_EM_MIPS:
                pkg_arch = _PKG_ARCH_MIPSELSF
                source = "installed-poller-elf"
            elif em == _ELF_EM_AARCH64:
                pkg_arch = _PKG_ARCH_AARCH64
                source = "installed-poller-elf"
            else:
                pkg_arch = _PKG_ARCH_AARCH64
                source = "default-aarch64"

    return {
        "machine": machine or None,
        "pkg_arch": pkg_arch,
        "opkg_archs": opkg_archs,
        "elf_machines": sorted(_expected_elf_for_pkg_arch(pkg_arch)),
        "source": source,
    }


def _release_asset_score(name: str, pkg_arch: str) -> int:
    """
    Higher = better match for this host.
    Prefer arch-specific opt tarball, then arch ipk, then legacy opt.tar.gz.
    """
    n = str(name or "").lower()
    if not n.startswith("poolheat"):
        return -1
    aliases = _PKG_ARCH_ALIASES.get(pkg_arch, (pkg_arch,))
    arch_hit = any(a.lower() in n for a in aliases)
    other_arches = []
    for k, als in _PKG_ARCH_ALIASES.items():
        if k == pkg_arch:
            continue
        other_arches.extend(als)
    other_hit = any(a.lower() in n for a in other_arches)

    if n.endswith(".ipk"):
        if arch_hit and not other_hit:
            return 80
        if arch_hit:
            return 70
        return -1  # never pick foreign-arch ipk
    if n.endswith(".tar.gz") or n.endswith(".tgz"):
        if "opt" in n and arch_hit and not other_hit:
            return 100  # poolheat-X-opt-mipselsf-3.4.tar.gz
        if "opt" in n and arch_hit:
            return 90
        # legacy single-arch tarball — usable only as last resort
        if re.match(r"poolheat-[\d.]+-opt\.tar\.gz$", n) and not other_hit:
            return 20
        if "opt" in n and not arch_hit and not other_hit:
            return 15
        return -1
    return -1


def _pick_release_asset(
    assets: list | None, pkg_arch: str
) -> dict | None:
    """Pick best GitHub release asset for host pkg_arch."""
    if not isinstance(assets, list):
        return None
    best: dict | None = None
    best_score = -1
    for a in assets:
        if not isinstance(a, dict):
            continue
        name = str(a.get("name") or "")
        url = str(a.get("browser_download_url") or a.get("url") or "").strip()
        if not name or not url:
            continue
        sc = _release_asset_score(name, pkg_arch)
        if sc > best_score:
            best_score = sc
            best = {
                "name": name,
                "url": url,
                "size": a.get("size"),
                "content_type": a.get("content_type"),
                "score": sc,
            }
    return best if best_score >= 0 else None


def _github_release_for_ref(ref: str | None) -> dict | None:
    """Fetch release JSON by tag, or latest if ref empty / branch-like."""
    ref = (ref or "").strip()
    try:
        if ref and re.match(r"^v?\d+(\.\d+)*", ref):
            tag = ref if ref.startswith("v") else ref
            # try exact, then with/without v
            for t in (tag, tag.lstrip("v"), f"v{tag.lstrip('v')}"):
                try:
                    rel = _http_json(
                        f"https://api.github.com/repos/{GITHUB_REPO}/releases/tags/{t}"
                    )
                    if isinstance(rel, dict) and rel.get("tag_name") and not rel.get("message"):
                        return rel
                except Exception:
                    continue
        rel = _http_json(
            f"https://api.github.com/repos/{GITHUB_REPO}/releases/latest"
        )
        if isinstance(rel, dict) and rel.get("tag_name") and not rel.get("message"):
            return rel
    except Exception:
        return None
    return None


def _parse_ar_members(blob: bytes) -> dict[str, bytes]:
    """Minimal System V ar parser (for .ipk)."""
    if not blob.startswith(b"!<arch>\n"):
        raise ValueError("not an ar archive")
    out: dict[str, bytes] = {}
    off = 8
    n = len(blob)
    while off + 60 <= n:
        hdr = blob[off : off + 60]
        off += 60
        name = hdr[0:16].decode("ascii", errors="replace").strip()
        try:
            size = int(hdr[48:58].decode("ascii", errors="replace").strip())
        except ValueError as e:
            raise ValueError(f"bad ar size for {name!r}") from e
        if size < 0 or off + size > n:
            raise ValueError(f"ar member truncated: {name}")
        data = blob[off : off + size]
        off += size
        if size % 2:
            off += 1
        # GNU long names not needed for our ipks
        out[name] = data
    return out


def _extract_ipk_data_root(ipk_blob: bytes, dest: Path) -> Path:
    """
    Extract ipk data.tar.gz into dest; return path to extracted root
    (directory that contains opt/ or is opt itself).
    """
    import io
    import tarfile

    members = _parse_ar_members(ipk_blob)
    data_blob = None
    for key in ("data.tar.gz", "data.tar.xz", "data.tar.zst", "data.tar"):
        if key in members:
            data_blob = members[key]
            mode = "r:gz" if key.endswith(".gz") else "r:"
            if key.endswith(".xz"):
                mode = "r:xz"
            break
    if data_blob is None:
        raise ValueError("ipk missing data.tar.*")
    dest.mkdir(parents=True, exist_ok=True)
    with tarfile.open(fileobj=io.BytesIO(data_blob), mode=mode) as tar:
        # safe extract
        for m in tar.getmembers():
            name = m.name.replace("\\", "/")
            if name.startswith("/") or ".." in name.split("/"):
                continue
            tar.extract(m, path=dest)
    # find opt/
    opt = dest / "opt"
    if opt.is_dir():
        return dest
    for p in dest.rglob("opt"):
        if p.is_dir() and ((p / "bin").is_dir() or (p / "lib").is_dir()):
            return p.parent
    return dest


def _install_tree_from_opt(
    opt_root: Path,
    *,
    lib_dir: Path,
    www_dir: Path,
    entware: bool,
    pkg_arch: str,
    installed: list[str],
    skip_wrong_arch_binaries: bool = True,
) -> list[str]:
    """
    Copy poolheat files from an extracted opt/ tree (ipk data or opt.tar.gz).
    Refuse Go pollers whose ELF machine does not match pkg_arch.
    """
    warnings: list[str] = []
    # opt_root may be .../opt or parent containing opt/
    if (opt_root / "opt").is_dir():
        base = opt_root / "opt"
    else:
        base = opt_root

    mapping: list[tuple[Path, Path]] = []
    # Python + UI
    lib_src = base / "lib" / "poolheat"
    if lib_src.is_dir():
        for rel in (
            "serve.py",
            "luci_proxy.py",
            "miner_models.py",
            "tuya_mobile.py",
            "xiaomi_miio.py",
            "ewelink_lan.py",
            "tuya_lan_ctl.py",
            "chipmap_skus.json",
            "miner_vendors.json",
            "miner_model_profiles.json",
            "migrate-layout.sh",
            "VERSION",
        ):
            s = lib_src / rel
            if s.is_file():
                mapping.append((s, lib_dir / rel))
        # whatsminer package
        wm_src = lib_src / "whatsminer"
        wm_dst = lib_dir / "whatsminer"
        if wm_src.is_dir():
            try:
                if wm_dst.exists():
                    shutil.rmtree(wm_dst)
                shutil.copytree(
                    wm_src,
                    wm_dst,
                    ignore=shutil.ignore_patterns(
                        "__pycache__", "*.pyc", ".DS_Store"
                    ),
                )
                installed.append(str(wm_dst))
            except Exception as e:
                warnings.append(f"whatsminer: {e}")

    www_src = base / "share" / "poolheat" / "www"
    if www_src.is_dir():
        for rel in ("index.html", "miner_vendors.json"):
            s = www_src / rel
            if s.is_file():
                mapping.append((s, www_dir / rel))
        icons_src = www_src / "icons"
        icons_dst = www_dir / "icons"
        if icons_src.is_dir():
            try:
                icons_dst.mkdir(parents=True, exist_ok=True)
                for p in sorted(icons_src.rglob("*")):
                    if not p.is_file():
                        continue
                    if p.name == ".DS_Store" or "__pycache__" in p.parts:
                        continue
                    rel = p.relative_to(icons_src)
                    mapping.append((p, icons_dst / rel))
                installed.append(str(icons_dst))
            except Exception as e:
                warnings.append(f"icons: {e}")

    ver_src = base / "share" / "poolheat" / "VERSION"
    if not ver_src.is_file():
        ver_src = lib_src / "VERSION" if lib_src.is_dir() else Path()
    if ver_src.is_file():
        mapping.append((ver_src, lib_dir / "VERSION"))
        if entware:
            mapping.append((ver_src, Path("/opt/share/poolheat/VERSION")))

    if entware:
        bin_src = base / "bin"
        for name in (
            "poolheatd",
            "poolheat-devices-poller",
            "poolheat-miner-poller",
        ):
            s = bin_src / name
            if s.is_file():
                mapping.append((s, Path("/opt/bin") / name))
        for name in ("S99poolheat", "S99poolheat-standalone"):
            s = base / "etc" / "init.d" / name
            if s.is_file():
                mapping.append((s, Path("/opt/etc/init.d") / name))

    expect_elf = _expected_elf_for_pkg_arch(pkg_arch)
    for src, dst in mapping:
        if not src.is_file():
            continue
        # Guard: never install wrong-arch pollers (root cause of Giant outage)
        if dst.name in ("poolheat-devices-poller", "poolheat-miner-poller"):
            em = _elf_machine(src)
            if skip_wrong_arch_binaries and expect_elf and em not in expect_elf:
                msg = (
                    f"skip {dst.name}: ELF machine={em} "
                    f"not in {sorted(expect_elf)} for pkg_arch={pkg_arch}"
                )
                print(f"[update] {msg}", flush=True)
                warnings.append(msg)
                continue
            if em is None:
                msg = f"skip {dst.name}: not a valid ELF"
                print(f"[update] {msg}", flush=True)
                warnings.append(msg)
                continue
        try:
            dst.parent.mkdir(parents=True, exist_ok=True)
            data = src.read_bytes()
            tmp = dst.with_suffix(dst.suffix + ".new")
            tmp.write_bytes(data)
            tmp.replace(dst)
            if dst.name in (
                "poolheatd",
                "poolheat-devices-poller",
                "poolheat-miner-poller",
                "S99poolheat",
                "S99poolheat-standalone",
                "serve.py",
                "migrate-layout.sh",
                "tuya_lan_ctl.py",
            ):
                try:
                    os.chmod(dst, 0o755)
                except Exception:
                    pass
            installed.append(str(dst))
        except Exception as e:
            warnings.append(f"{dst}: {e}")
    return warnings


def check_github_update(*, lang: str = "en") -> dict:
    """
    Compare installed VERSION with GitHub:
      1) latest release tag (if any)
      2) latest git tag
      3) VERSION file on default branch
    Also returns latest commit on branch for reference.

    Release notes support bilingual bodies (see _split_bilingual_release_notes).
    ``lang`` selects preferred notes language; missing RU → English default.

    Includes host package architecture + matching release asset for OTA.
    """
    ui_lang = _normalize_notes_lang(lang)
    current = get_app_version()
    host = detect_host_package_arch()
    out: dict = {
        "ok": True,
        "current_version": current,
        "latest_version": None,
        "update_available": False,
        "status": "unknown",  # up_to_date | update_available | local_ahead | unknown
        "source": None,
        "release_name": None,
        "release_url": None,
        "tag": None,
        "commit_sha": None,
        "commit_url": None,
        "published_at": None,
        "github_repo": GITHUB_REPO,
        "github_branch": GITHUB_BRANCH,
        "checked_at": datetime.now().isoformat(timespec="seconds"),
        "error": None,
        "notes": None,
        "notes_lang": None,
        "notes_fallback": False,
        "notes_en": None,
        "notes_ru": None,
        "notes_available": [],
        "ui_lang": ui_lang,
        # architecture-aware OTA
        "host_machine": host.get("machine"),
        "host_pkg_arch": host.get("pkg_arch"),
        "host_arch_source": host.get("source"),
        "package_asset": None,
        "package_url": None,
        "package_score": None,
    }
    latest: str | None = None
    rel_obj: dict | None = None
    try:
        # 1) releases
        try:
            rel = _http_json(
                f"https://api.github.com/repos/{GITHUB_REPO}/releases/latest"
            )
            if isinstance(rel, dict) and rel.get("tag_name") and not rel.get("message"):
                rel_obj = rel
                latest = str(rel["tag_name"]).lstrip("vV")
                out["source"] = "release"
                out["tag"] = rel.get("tag_name")
                out["release_name"] = rel.get("name") or rel.get("tag_name")
                out["release_url"] = rel.get("html_url")
                out["published_at"] = rel.get("published_at")
                body_notes = (rel.get("body") or "").replace("\r\n", "\n").strip()
                note_pack = _select_release_notes(body_notes, lang=ui_lang)
                out.update(note_pack)
                asset = _pick_release_asset(
                    rel.get("assets") if isinstance(rel.get("assets"), list) else [],
                    str(host.get("pkg_arch") or _PKG_ARCH_AARCH64),
                )
                if asset:
                    out["package_asset"] = asset.get("name")
                    out["package_url"] = asset.get("url")
                    out["package_score"] = asset.get("score")
        except urllib.error.HTTPError as e:
            if e.code != 404:
                raise
        except Exception:
            pass

        # 2) tags
        if not latest:
            try:
                tags = _http_json(
                    f"https://api.github.com/repos/{GITHUB_REPO}/tags?per_page=5"
                )
                if isinstance(tags, list) and tags:
                    t0 = tags[0]
                    if isinstance(t0, dict) and t0.get("name"):
                        latest = str(t0["name"]).lstrip("vV")
                        out["source"] = "tag"
                        out["tag"] = t0.get("name")
                        out["release_url"] = (
                            f"https://github.com/{GITHUB_REPO}/releases/tag/{t0['name']}"
                        )
                        if isinstance(t0.get("commit"), dict):
                            out["commit_sha"] = (t0["commit"].get("sha") or "")[:12] or None
            except Exception:
                pass

        # 3) VERSION on branch (GitHub Contents API — no CDN cache lag)
        if not latest:
            try:
                req = urllib.request.Request(
                    f"https://api.github.com/repos/{GITHUB_REPO}/contents/VERSION"
                    f"?ref={urllib.parse.quote(GITHUB_BRANCH)}",
                    headers={
                        "User-Agent": f"poolheat/{get_app_version()}",
                        "Accept": "application/vnd.github.raw",
                    },
                    method="GET",
                )
                with urllib.request.urlopen(req, timeout=12) as resp:
                    raw = resp.read().decode("utf-8", errors="replace")
                line = raw.strip().splitlines()[0].strip() if raw.strip() else ""
                if line and "404" not in line.lower() and len(line) < 40:
                    # accept "0.2.0" or "v0.2.0"
                    if re.match(r"^v?\d+(\.\d+)*", line, re.I):
                        latest = line.lstrip("vV")
                        out["source"] = f"VERSION@{GITHUB_BRANCH}"
                        out["release_url"] = (
                            f"https://github.com/{GITHUB_REPO}/blob/"
                            f"{GITHUB_BRANCH}/VERSION"
                        )
            except urllib.error.HTTPError as e:
                if e.code not in (404, 403):
                    # 403 rate-limit etc. — surface later if nothing else works
                    out["_version_http"] = e.code
            except Exception as e:
                out["_version_err"] = str(e)

        # always try commit tip for branch (metadata)
        try:
            commit = _http_json(
                f"https://api.github.com/repos/{GITHUB_REPO}/commits/{GITHUB_BRANCH}"
            )
            if isinstance(commit, dict) and commit.get("sha"):
                out["commit_sha"] = commit["sha"][:12]
                out["commit_url"] = commit.get("html_url")
                if not out.get("published_at"):
                    try:
                        out["published_at"] = (
                            (commit.get("commit") or {})
                            .get("committer", {})
                            .get("date")
                        )
                    except Exception:
                        pass
        except Exception:
            pass

        out["latest_version"] = latest
        if latest:
            cmp = version_cmp(current, latest)
            if cmp < 0:
                out["update_available"] = True
                out["status"] = "update_available"
            elif cmp == 0:
                out["update_available"] = False
                out["status"] = "up_to_date"
            else:
                out["update_available"] = False
                out["status"] = "local_ahead"
        else:
            # No published version channel yet — still allow install from branch
            out["status"] = "branch_only"
            out["update_available"] = False
            out["latest_version"] = None
            out["error"] = None
            sha = f" ({out['commit_sha']})" if out.get("commit_sha") else ""
            if ui_lang == "ru":
                out["notes"] = (
                    f"На GitHub нет release/tag/VERSION. "
                    f"Можно поставить код с ветки {GITHUB_BRANCH}{sha}. "
                    f"После push VERSION или Release vX.Y.Z проверка станет точной."
                )
                out["notes_lang"] = "ru"
                out["notes_fallback"] = False
            else:
                out["notes"] = (
                    f"No release/tag/VERSION on GitHub yet. "
                    f"You can install from branch {GITHUB_BRANCH}{sha}. "
                    f"After pushing VERSION or Release vX.Y.Z, checks become exact."
                )
                out["notes_lang"] = "en"
                out["notes_fallback"] = False
            out["notes_available"] = [out["notes_lang"]]
        # drop internal diagnostics from public payload
        out.pop("_version_http", None)
        out.pop("_version_err", None)
    except Exception as e:
        out["ok"] = False
        out["error"] = str(e)
        out["status"] = "error"

    _update_state["last_check"] = out
    return out


def _is_entware_layout() -> bool:
    return Path("/opt/lib/poolheat").is_dir() and Path("/opt/share/poolheat/www").is_dir()


def _restart_poolheat_later() -> None:
    """
    Restart after GitHub apply. Must outlive this process: killing serve.py
    would otherwise abort an in-process restart (or a timed-out foreground
    poolheatd) and leave the service dead.

    Critical (0.6.35): script is written to a file and run as `sh path`, NOT
    `sh -c '…serve.py…'`. Inline -c puts the whole script in argv, so a
    /proc kill matching ``serve.py`` suicides the restart shell and leaves
    poolheat dead after OTA (seen 2026-08-11 06:32 on Keenetic).
    """
    def _run() -> None:
        time.sleep(1.2)
        log = "/opt/var/poolheat/poolheat.log"
        script_path = "/opt/var/poolheat/ota-restart.sh"
        # Detached shell in a new session — survives kill of current serve.py
        # Keep needles SPECIFIC (full binary names / paths) — never match self.
        script = f"""#!/bin/sh
exec >>{log} 2>&1
echo "[$(date '+%Y-%m-%d %H:%M:%S')] poolheat update: restart begin"
SELF=$$
sleep 1
# stop service + children (serve, Go pollers, python pollers)
if [ -x /opt/etc/init.d/S99poolheat-standalone ]; then
  /opt/etc/init.d/S99poolheat-standalone stop || true
elif [ -x /opt/etc/init.d/S99poolheat ]; then
  /opt/etc/init.d/S99poolheat stop || true
fi
# Prefer /proc cmdline/exe scan — BusyBox `ps w` often misses on Keenetic.
# Linux keeps old ELF mapped until process exit; must kill before re-exec.
# NEVER kill SELF / PPID (this restart script).
_ph_kill_match() {{
  _sig="${{1:-15}}"; shift
  for _d in /proc/[0-9]*; do
    [ -d "$_d" ] || continue
    _pid="${{_d##*/}}"
    case "$_pid" in *[!0-9]*|"") continue ;; esac
    [ "$_pid" = "$SELF" ] && continue
    [ "$_pid" = "$PPID" ] && continue
    _cmd=$(tr '\\0' ' ' < "$_d/cmdline" 2>/dev/null || true)
    # Skip our own ota-restart.sh if it ever appears
    case "$_cmd" in *ota-restart.sh*) continue ;; esac
    _exe=$(readlink "$_d/exe" 2>/dev/null || true)
    _blob="$_cmd $_exe"
    for _n in "$@"; do
      case "$_blob" in
        *"$_n"*) kill -"$_sig" "$_pid" 2>/dev/null || true; break ;;
      esac
    done
  done
}}
# Specific names only (avoid bare "serve.py" matching huge argv of sh -c).
_ph_kill_match 15 /opt/lib/poolheat/serve.py poolheat-devices-poller poolheat-miner-poller /opt/bin/poolheatd
sleep 1
_ph_kill_match 9 /opt/lib/poolheat/serve.py poolheat-devices-poller poolheat-miner-poller /opt/bin/poolheatd
rm -f /opt/var/poolheat/devices_poller.pid /opt/var/poolheat/miner_poller.pid 2>/dev/null || true
# ensure new binaries are executable (OTA may land them)
chmod +x /opt/bin/poolheat-devices-poller /opt/bin/poolheat-miner-poller /opt/bin/poolheatd 2>/dev/null || true
sync 2>/dev/null || true
ls -la /opt/bin/poolheat-*-poller /opt/bin/poolheatd 2>/dev/null || true
/opt/bin/poolheat-miner-poller -version 2>/dev/null || true
/opt/bin/poolheat-devices-poller -version 2>/dev/null || true
sleep 1
# start (prefer standalone — no rc.func / PROCS=poolheatd mismatch)
ok=0
if [ -x /opt/etc/init.d/S99poolheat-standalone ]; then
  if /opt/etc/init.d/S99poolheat-standalone start; then ok=1; fi
fi
if [ "$ok" -eq 0 ] && [ -x /opt/etc/init.d/S99poolheat ]; then
  if /opt/etc/init.d/S99poolheat start; then ok=1; fi
fi
if [ "$ok" -eq 0 ]; then
  mkdir -p /opt/var/poolheat /opt/var/run
  if [ -x /opt/bin/poolheatd ]; then
    /opt/bin/poolheatd >>{log} 2>&1 &
    echo $! > /opt/var/run/poolheatd.pid
  else
    /opt/bin/python3 /opt/lib/poolheat/serve.py >>{log} 2>&1 &
    echo $! > /opt/var/run/poolheatd.pid
  fi
  sleep 1
fi
# detect live serve by /proc (not only ps)
alive=0
for _d in /proc/[0-9]*; do
  _cmd=$(tr '\\0' ' ' < "$_d/cmdline" 2>/dev/null || true)
  case "$_cmd" in
    */opt/lib/poolheat/serve.py*|*/opt/bin/python3*serve.py*) alive=1; break ;;
  esac
done
if [ "$alive" -eq 1 ] || ps w 2>/dev/null | grep -q '[s]erve.py'; then
  echo "[$(date '+%Y-%m-%d %H:%M:%S')] poolheat update: restart OK"
  sleep 3
  ps w 2>/dev/null | grep -E 'poolheat-(devices|miner)-poller|serve.py' | head -20 || true
else
  echo "[$(date '+%Y-%m-%d %H:%M:%S')] poolheat update: restart FAILED — no serve.py"
  # last-ditch start
  /opt/etc/init.d/S99poolheat-standalone start 2>/dev/null || true
fi
"""
        try:
            sp = Path(script_path)
            sp.parent.mkdir(parents=True, exist_ok=True)
            sp.write_text(script, encoding="utf-8")
            try:
                sp.chmod(0o755)
            except Exception:
                pass
            subprocess.Popen(
                ["sh", str(sp)],
                start_new_session=True,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                close_fds=True,
            )
        except Exception as e:
            try:
                with open(log, "a", encoding="utf-8") as fh:
                    fh.write(f"poolheat update: spawn restart failed: {e}\n")
            except Exception:
                pass

    threading.Thread(target=_run, name="poolheat-restart", daemon=True).start()


def _queue_update_restart_notify(
    chat_id,
    lang: str = "ru",
    *,
    from_version: str | None = None,
    to_version: str | None = None,
    source: str = "telegram",
) -> None:
    """
    Persist a one-shot TG message for after service restart.
    Written to DATA so it survives kill of serve.py.
    """
    try:
        DATA.mkdir(parents=True, exist_ok=True)
        payload = {
            "chat_id": chat_id,
            "lang": "en" if str(lang or "").lower().startswith("en") else "ru",
            "from_version": from_version,
            "to_version": to_version or get_app_version(),
            "source": source,
            "queued_at": datetime.now().isoformat(timespec="seconds"),
        }
        UPDATE_NOTIFY_FILE.write_text(
            json.dumps(payload, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        print(f"[update] restart notify queued → chat {chat_id}")
    except Exception as e:
        print(f"[update] restart notify queue fail: {e}")


def _flush_update_restart_notify() -> None:
    """
    After boot: if an OTA left a pending notify, send success to that chat.
    Safe to call multiple times; file is removed first to avoid loops.
    """
    path = UPDATE_NOTIFY_FILE
    if not path.is_file():
        return
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except Exception as e:
        print(f"[update] restart notify read fail: {e}")
        try:
            path.unlink(missing_ok=True)
        except Exception:
            pass
        return
    try:
        path.unlink(missing_ok=True)
    except Exception:
        pass
    if not isinstance(raw, dict):
        return
    chat_id = raw.get("chat_id")
    if chat_id is None:
        return
    en = str(raw.get("lang") or "ru").lower().startswith("en")
    ver = str(raw.get("to_version") or get_app_version() or "?")
    from_v = raw.get("from_version")
    try:
        # ensure TG config loaded
        if not _tg_cfg.get("bot_token") or not _tg_cfg.get("enabled"):
            print("[update] restart notify skipped: telegram disabled")
            return
        if en:
            if from_v:
                msg = (
                    f"✅ Restart OK after update\n"
                    f"{from_v} → {ver}\n"
                    f"Service is online again."
                )
            else:
                msg = f"✅ Restart OK · {ver}\nService is online again."
        else:
            if from_v:
                msg = (
                    f"✅ Перезапуск после обновления OK\n"
                    f"{from_v} → {ver}\n"
                    f"Сервис снова онлайн."
                )
            else:
                msg = f"✅ Перезапуск OK · {ver}\nСервис снова онлайн."
        tg_send_message(
            chat_id,
            msg,
            reply_markup=_tg_main_keyboard(
                "en" if en else "ru", chat_id
            ),
        )
        print(f"[update] restart notify sent → chat {chat_id}")
    except Exception as e:
        print(f"[update] restart notify send fail: {e}")
        # re-queue once if send failed (network blip right after start)
        try:
            raw["retry"] = int(raw.get("retry") or 0) + 1
            if int(raw["retry"]) <= 2:
                path.write_text(
                    json.dumps(raw, ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8",
                )
        except Exception:
            pass


def start_github_update_async(
    ref: str | None = None, *, source: str = "manual"
) -> dict:
    """
    Start OTA in a background thread and return immediately.

    Giant reinstall of the mipselsf package takes ~2–4 minutes (USB + low RAM).
    Synchronous POST /api/update/apply was dying in browsers/proxies before the
    install finished — UI showed failure while files were still being written.
    """
    if _update_state.get("busy"):
        return {
            "ok": False,
            "error": "update already in progress",
            "busy": True,
            "phase": _update_state.get("phase"),
            "phase_detail": _update_state.get("phase_detail"),
        }
    # Try to reserve the lock without blocking the HTTP worker for minutes
    if not _update_lock.acquire(blocking=False):
        return {
            "ok": False,
            "error": "update already in progress",
            "busy": True,
        }
    # Mark busy before spawning so concurrent POSTs see it
    _update_state["busy"] = True
    _update_state["started_at"] = datetime.now().isoformat(timespec="seconds")
    _set_update_phase("queued", ref or "latest")
    apply_source = (source or "manual").strip() or "manual"
    target_ref = (ref or "").strip() or None

    def _runner() -> None:
        try:
            # lock already held — use internal body
            apply_github_update(
                target_ref, source=apply_source, _lock_held=True
            )
        except Exception as e:
            print(f"[update] async apply crashed: {e}", flush=True)
            try:
                err = {
                    "ok": False,
                    "error": str(e),
                    "source": apply_source,
                    "applied_at": datetime.now().isoformat(timespec="seconds"),
                }
                _update_state["last_apply"] = err
                _set_update_phase("error", str(e)[:200])
                _log_update_apply(err, source=apply_source)
            except Exception:
                pass
            finally:
                _update_state["busy"] = False
                try:
                    _update_lock.release()
                except Exception:
                    pass

    threading.Thread(
        target=_runner, name="poolheat-ota-apply", daemon=True
    ).start()
    return {
        "ok": True,
        "started": True,
        "async": True,
        "busy": True,
        "from_version": get_app_version(),
        "ref": target_ref,
        "source": apply_source,
        "phase": _update_state.get("phase"),
        "message": (
            "Установка запущена в фоне (обычно 1–4 мин). "
            "Не закрывайте страницу — статус обновится сам."
        ),
        "poll_url": "/api/update/status",
        "poll_interval_sec": 2,
    }


def apply_github_update(
    ref: str | None = None,
    *,
    source: str = "manual",
    _lock_held: bool = False,
) -> dict:
    """
    Install poolheat update from GitHub, architecture-aware:

      1) Detect host Entware arch (aarch64-3.10 / mipselsf-3.4)
      2) Prefer matching release asset (.ipk or opt-<arch>.tar.gz)
      3) Fallback: source tree archive for Python/UI only; pollers only if
         ELF machine matches host (never install Peak aarch64 binaries on Giant)

    Does not overwrite /opt/etc/poolheat/config.json.
    ``source`` is written to the action log (manual | auto | telegram).

    ``_lock_held``: caller already holds ``_update_lock`` and set busy
    (used by async starter).
    """
    if not _lock_held:
        if not _update_lock.acquire(blocking=False):
            return {"ok": False, "error": "update already in progress"}
        _update_state["busy"] = True
        _update_state["started_at"] = datetime.now().isoformat(timespec="seconds")
    from_ver = get_app_version()
    apply_source = (source or "manual").strip() or "manual"
    try:
        if not _is_entware_layout():
            # allow local demo install into ROOT / next to serve.py
            lib_dir = Path(__file__).resolve().parent
            www_dir = ROOT if ROOT.is_dir() else lib_dir
            version_targets = [lib_dir / "VERSION"]
            if ROOT != lib_dir:
                version_targets.append(ROOT / "VERSION")
            entware = False
        else:
            lib_dir = Path("/opt/lib/poolheat")
            www_dir = Path("/opt/share/poolheat/www")
            version_targets = [
                Path("/opt/lib/poolheat/VERSION"),
                Path("/opt/share/poolheat/VERSION"),
            ]
            entware = True

        host = detect_host_package_arch()
        pkg_arch = str(host.get("pkg_arch") or _PKG_ARCH_AARCH64)

        target_ref = (ref or "").strip()
        # Prefer latest known from check, else branch
        if not target_ref:
            last = _update_state.get("last_check") or {}
            if isinstance(last, dict):
                target_ref = last.get("tag") or ""
                # if only VERSION@branch, install from branch
                if not target_ref and last.get("source", "").startswith("VERSION@"):
                    target_ref = GITHUB_BRANCH
            target_ref = target_ref or GITHUB_BRANCH
        target_ref = str(target_ref).strip() or GITHUB_BRANCH

        import tempfile
        import tarfile

        errors: list[str] = []
        warnings: list[str] = []
        installed: list[str] = []
        used_url = ""
        install_mode = ""  # release-ipk | release-opt | source-archive
        package_asset = None

        # ── 1) Arch-specific release package (preferred on Entware) ─────────
        if entware:
            rel = _github_release_for_ref(target_ref)
            asset = None
            if isinstance(rel, dict):
                asset = _pick_release_asset(
                    rel.get("assets") if isinstance(rel.get("assets"), list) else [],
                    pkg_arch,
                )
                # if check already resolved an asset for this host, prefer it
                last = _update_state.get("last_check") or {}
                if (
                    isinstance(last, dict)
                    and last.get("package_url")
                    and last.get("host_pkg_arch") == pkg_arch
                    and (not asset or last.get("package_score", 0) >= (asset or {}).get("score", 0))
                ):
                    asset = {
                        "name": last.get("package_asset"),
                        "url": last.get("package_url"),
                        "score": last.get("package_score"),
                    }
            if asset and asset.get("url"):
                package_asset = asset.get("name")
                try:
                    print(
                        f"[update] host={host.get('machine')} pkg_arch={pkg_arch} "
                        f"asset={asset.get('name')} score={asset.get('score')}",
                        flush=True,
                    )
                    used_url = str(asset["url"])
                    _set_update_phase("downloading", package_asset)
                    with tempfile.TemporaryDirectory(prefix="poolheat-pkg-") as td:
                        tdir = Path(td)
                        name = str(asset.get("name") or "pkg.bin").lower()
                        # Stream to disk — never hold full package in RAM
                        if name.endswith(".ipk"):
                            ipk_path = tdir / "pkg.ipk"
                            n = _http_download_to_file(
                                used_url, ipk_path, timeout=300
                            )
                            print(
                                f"[update] downloaded {n} bytes → {ipk_path.name}",
                                flush=True,
                            )
                            install_mode = "release-ipk"
                            _set_update_phase("extracting", package_asset)
                            blob = ipk_path.read_bytes()
                            root = _extract_ipk_data_root(blob, tdir / "ipk")
                            del blob
                            if entware:
                                _stop_pollers_for_ota()
                            _set_update_phase("installing", package_asset)
                            w = _install_tree_from_opt(
                                root,
                                lib_dir=lib_dir,
                                www_dir=www_dir,
                                entware=entware,
                                pkg_arch=pkg_arch,
                                installed=installed,
                            )
                            warnings.extend(w)
                        elif name.endswith(".tar.gz") or name.endswith(".tgz"):
                            tgz_path = tdir / "opt.tar.gz"
                            n = _http_download_to_file(
                                used_url, tgz_path, timeout=300
                            )
                            print(
                                f"[update] downloaded {n} bytes → {tgz_path.name}",
                                flush=True,
                            )
                            install_mode = "release-opt"
                            _set_update_phase("extracting", package_asset)
                            with tarfile.open(tgz_path, "r:gz") as tar:
                                for m in tar.getmembers():
                                    nm = m.name.replace("\\", "/")
                                    if nm.startswith("/") or ".." in nm.split("/"):
                                        continue
                                    tar.extract(m, path=tdir / "optroot")
                            if entware:
                                _stop_pollers_for_ota()
                            _set_update_phase("installing", package_asset)
                            w = _install_tree_from_opt(
                                tdir / "optroot",
                                lib_dir=lib_dir,
                                www_dir=www_dir,
                                entware=entware,
                                pkg_arch=pkg_arch,
                                installed=installed,
                            )
                            warnings.extend(w)
                        else:
                            errors.append(f"unsupported asset type: {name}")
                            installed = []
                except Exception as e:
                    errors.append(f"package {asset.get('name')}: {e}")
                    installed = []
                    print(f"[update] package install failed: {e}", flush=True)
                    _set_update_phase("error", str(e)[:200])

        # ── 2) Fallback: source archive (Python/UI; pollers only if ELF OK) ─
        if not installed:
            if re.match(r"^[0-9a-f]{7,40}$", target_ref):
                archive_url = (
                    f"https://codeload.github.com/{GITHUB_REPO}/tar.gz/{target_ref}"
                )
            elif target_ref == GITHUB_BRANCH or not target_ref.startswith("v"):
                if re.match(r"^v?\d+\.\d+", target_ref):
                    tag = target_ref if target_ref.startswith("v") else f"v{target_ref}"
                    archive_url = (
                        f"https://github.com/{GITHUB_REPO}/archive/refs/tags/{tag}.tar.gz"
                    )
                else:
                    archive_url = (
                        f"https://github.com/{GITHUB_REPO}/archive/refs/heads/"
                        f"{target_ref}.tar.gz"
                    )
            else:
                archive_url = (
                    f"https://github.com/{GITHUB_REPO}/archive/refs/tags/{target_ref}.tar.gz"
                )

            blob = None
            urls_try = [archive_url]
            if "refs/tags/" in archive_url:
                bare = target_ref.lstrip("v")
                urls_try.append(
                    f"https://github.com/{GITHUB_REPO}/archive/refs/heads/{GITHUB_BRANCH}.tar.gz"
                )
                urls_try.append(
                    f"https://github.com/{GITHUB_REPO}/archive/refs/tags/v{bare}.tar.gz"
                )
                urls_try.append(
                    f"https://github.com/{GITHUB_REPO}/archive/refs/tags/{bare}.tar.gz"
                )
            for u in urls_try:
                try:
                    blob = _http_bytes(u, timeout=120)
                    used_url = u
                    break
                except Exception as e:
                    errors.append(f"{u}: {e}")
                    blob = None
            if not blob:
                return {
                    "ok": False,
                    "error": "download failed: " + "; ".join(errors[:4]),
                    "tried": urls_try,
                    "host_pkg_arch": pkg_arch,
                    "host_machine": host.get("machine"),
                }

            install_mode = "source-archive"
            with tempfile.TemporaryDirectory(prefix="poolheat-upd-") as td:
                tdir = Path(td)
                tgz_path = tdir / "src.tar.gz"
                tgz_path.write_bytes(blob)
                with tarfile.open(tgz_path, "r:gz") as tar:
                    def _safe_members(members):
                        for m in members:
                            name = m.name.replace("\\", "/")
                            if name.startswith("/") or ".." in name.split("/"):
                                continue
                            parts = name.split("/", 1)
                            if len(parts) < 2:
                                continue
                            rel = parts[1]
                            if rel in (
                                "ui/serve.py",
                                "ui/index.html",
                                "ui/miner_vendors.json",
                                "ui/chipmap_skus.json",
                                "VERSION",
                                "packaging/entware/opt/bin/poolheatd",
                                "packaging/entware/opt/bin/poolheat-devices-poller",
                                "packaging/entware/opt/bin/poolheat-miner-poller",
                                "packaging/entware/opt/etc/init.d/S99poolheat",
                                "packaging/entware/opt/etc/init.d/S99poolheat-standalone",
                                "packaging/entware/migrate-layout.sh",
                            ):
                                yield m
                            elif rel.startswith("ui/") and rel.endswith(
                                (".py", ".html", ".json")
                            ):
                                yield m
                            elif rel.startswith("ui/whatsminer/") and (
                                rel.endswith(".py")
                                or rel.endswith(".json")
                                or rel.endswith(".md")
                                or rel.endswith("LICENSE")
                                or rel.endswith(".txt")
                            ):
                                yield m
                            elif rel.startswith("ui/icons/") and (
                                rel.endswith(
                                    (
                                        ".svg",
                                        ".png",
                                        ".ico",
                                        ".webp",
                                        ".jpg",
                                        ".jpeg",
                                    )
                                )
                                or rel.endswith("LICENSE")
                                or rel.endswith("README.md")
                            ):
                                yield m

                    tar.extractall(path=tdir, members=_safe_members(tar))

                roots = [p for p in tdir.iterdir() if p.is_dir()]
                src_root = roots[0] if roots else tdir

                # Build a synthetic opt/ tree from source layout for shared installer
                synth = tdir / "synth_opt" / "opt"
                (synth / "lib" / "poolheat").mkdir(parents=True, exist_ok=True)
                (synth / "share" / "poolheat" / "www").mkdir(parents=True, exist_ok=True)
                (synth / "bin").mkdir(parents=True, exist_ok=True)
                (synth / "etc" / "init.d").mkdir(parents=True, exist_ok=True)

                def _cp(src: Path, dst: Path) -> None:
                    if src.is_file():
                        dst.parent.mkdir(parents=True, exist_ok=True)
                        shutil.copy2(src, dst)

                for name in (
                    "serve.py",
                    "luci_proxy.py",
                    "miner_models.py",
                    "tuya_mobile.py",
                    "xiaomi_miio.py",
                    "ewelink_lan.py",
                    "tuya_lan_ctl.py",
                    "chipmap_skus.json",
                    "miner_vendors.json",
                    "miner_model_profiles.json",
                ):
                    _cp(src_root / "ui" / name, synth / "lib" / "poolheat" / name)
                _cp(
                    src_root / "packaging/entware/migrate-layout.sh",
                    synth / "lib" / "poolheat" / "migrate-layout.sh",
                )
                _cp(src_root / "VERSION", synth / "lib" / "poolheat" / "VERSION")
                _cp(src_root / "VERSION", synth / "share" / "poolheat" / "VERSION")
                _cp(
                    src_root / "ui" / "index.html",
                    synth / "share" / "poolheat" / "www" / "index.html",
                )
                _cp(
                    src_root / "ui" / "miner_vendors.json",
                    synth / "share" / "poolheat" / "www" / "miner_vendors.json",
                )
                wm = src_root / "ui" / "whatsminer"
                if wm.is_dir():
                    shutil.copytree(
                        wm,
                        synth / "lib" / "poolheat" / "whatsminer",
                        ignore=shutil.ignore_patterns(
                            "__pycache__", "*.pyc", ".DS_Store"
                        ),
                    )
                icons = src_root / "ui" / "icons"
                if icons.is_dir():
                    shutil.copytree(
                        icons,
                        synth / "share" / "poolheat" / "www" / "icons",
                        ignore=shutil.ignore_patterns(".DS_Store", "__pycache__"),
                    )
                for name in (
                    "poolheatd",
                    "poolheat-devices-poller",
                    "poolheat-miner-poller",
                ):
                    _cp(
                        src_root / "packaging/entware/opt/bin" / name,
                        synth / "bin" / name,
                    )
                for name in ("S99poolheat", "S99poolheat-standalone"):
                    _cp(
                        src_root / "packaging/entware/opt/etc/init.d" / name,
                        synth / "etc" / "init.d" / name,
                    )

                w = _install_tree_from_opt(
                    synth,
                    lib_dir=lib_dir,
                    www_dir=www_dir,
                    entware=entware,
                    pkg_arch=pkg_arch,
                    installed=installed,
                    skip_wrong_arch_binaries=True,
                )
                warnings.extend(w)
                if any("skip poolheat-" in x for x in w):
                    warnings.append(
                        "source archive pollers skipped (wrong arch) — "
                        "use arch-specific .ipk from GitHub release"
                    )

        # On-router layout migration
        if entware and installed:
            mig = lib_dir / "migrate-layout.sh"
            if mig.is_file():
                try:
                    import subprocess

                    _set_update_phase("migrate", "migrate-layout.sh")
                    r = subprocess.run(
                        ["sh", str(mig)],
                        capture_output=True,
                        text=True,
                        timeout=60,
                    )
                    if r.stdout:
                        print(r.stdout, flush=True)
                    if r.returncode != 0 and r.stderr:
                        print(f"[update] migrate-layout: {r.stderr}", flush=True)
                    installed.append("migrate-layout")
                except Exception as e:
                    print(f"[update] migrate-layout: {e}", flush=True)

        if not installed:
            _set_update_phase("error", "no files installed")
            err = {
                "ok": False,
                "error": "install failed: " + ("; ".join(errors[:4]) or "no files"),
                "url": used_url or None,
                "host_pkg_arch": pkg_arch,
                "host_machine": host.get("machine"),
                "package_asset": package_asset,
                "warnings": warnings[:8],
                "applied_at": datetime.now().isoformat(timespec="seconds"),
            }
            _update_state["last_apply"] = err
            return err

        # Verify pollers after install
        poller_status = {}
        for name in ("poolheat-devices-poller", "poolheat-miner-poller"):
            p = Path("/opt/bin") / name if entware else lib_dir / name
            em = _elf_machine(p) if p.is_file() else None
            expect = set(host.get("elf_machines") or [])
            ok = bool(em is not None and (not expect or em in expect))
            poller_status[name] = {
                "path": str(p) if p.is_file() else None,
                "elf_machine": em,
                "ok": ok,
            }
            if entware and p.is_file() and not ok:
                warnings.append(
                    f"{name} ELF machine={em} incompatible with {pkg_arch}"
                )

        result = {
            "ok": True,
            "installed": installed,
            "from_version": from_ver,
            "to_version": get_app_version(),
            "ref": target_ref,
            "url": used_url,
            "restart": entware,
            "source": apply_source,
            "install_mode": install_mode,
            "host_machine": host.get("machine"),
            "host_pkg_arch": pkg_arch,
            "package_asset": package_asset,
            "pollers": poller_status,
            "warnings": warnings[:12],
            "message": (
                f"Обновление установлено ({install_mode or 'package'}, arch={pkg_arch})"
                + ("; сервис перезапускается…" if entware else "")
            ),
            "applied_at": datetime.now().isoformat(timespec="seconds"),
        }
        _update_state["last_apply"] = result
        _set_update_phase("done", result.get("to_version"))
        try:
            _log_update_apply(result, source=apply_source)
        except Exception as e:
            print(f"[update] log apply: {e}")
        if entware:
            _set_update_phase("restarting", result.get("to_version"))
            _restart_poolheat_later()
        return result
    except Exception as e:
        err = {
            "ok": False,
            "error": str(e),
            "source": apply_source,
            "applied_at": datetime.now().isoformat(timespec="seconds"),
        }
        _update_state["last_apply"] = err
        _set_update_phase("error", str(e)[:200])
        try:
            _log_update_apply(err, source=apply_source)
        except Exception:
            pass
        return err
    finally:
        _update_state["busy"] = False
        try:
            _update_lock.release()
        except Exception:
            pass


def _normalize_update_cfg(raw: dict | None) -> dict:
    cfg = dict(DEFAULT_UPDATE_CFG)
    if isinstance(raw, dict):
        cfg.update({k: raw[k] for k in raw if k in DEFAULT_UPDATE_CFG or k in (
            "auto_update", "schedule", "check_interval_min",
            "last_check_ts", "last_apply_ts", "last_result",
        )})
    cfg["auto_update"] = bool(cfg.get("auto_update"))
    sch = str(cfg.get("schedule") or "always").strip().lower()
    if sch not in UPDATE_SCHEDULES:
        sch = "always"
    cfg["schedule"] = sch
    try:
        iv = int(cfg.get("check_interval_min") or 360)
    except (TypeError, ValueError):
        iv = 360
    cfg["check_interval_min"] = max(30, min(24 * 60, iv))
    return cfg


def _load_update_cfg() -> None:
    global _update_cfg
    with _update_cfg_lock:
        raw = _load_json(UPDATE_CFG_FILE, DEFAULT_UPDATE_CFG)
        _update_cfg = _normalize_update_cfg(raw if isinstance(raw, dict) else None)


def _save_update_cfg() -> None:
    with _update_cfg_lock:
        _save_json(UPDATE_CFG_FILE, dict(_update_cfg))


def get_update_cfg() -> dict:
    with _update_cfg_lock:
        return dict(_update_cfg)


def set_update_cfg(patch: dict | None) -> dict:
    """Merge patch into update_config.json (auto_update / schedule / interval)."""
    global _update_cfg
    if not isinstance(patch, dict):
        patch = {}
    with _update_cfg_lock:
        cur = dict(_update_cfg)
        if "auto_update" in patch:
            cur["auto_update"] = bool(patch.get("auto_update"))
        if "schedule" in patch:
            cur["schedule"] = str(patch.get("schedule") or "always")
        if "check_interval_min" in patch:
            try:
                cur["check_interval_min"] = int(patch.get("check_interval_min"))
            except (TypeError, ValueError):
                pass
        _update_cfg = _normalize_update_cfg(cur)
        _save_json(UPDATE_CFG_FILE, dict(_update_cfg))
        return dict(_update_cfg)


def _update_schedule_active(cfg: dict | None = None, now: datetime | None = None) -> bool:
    """True if auto-update may run under the selected schedule (router local time)."""
    cfg = cfg if isinstance(cfg, dict) else get_update_cfg()
    sch = str(cfg.get("schedule") or "always").strip().lower()
    if sch == "always" or sch not in UPDATE_SCHEDULES:
        return True
    now = now or datetime.now()
    # Night window 02:00 ≤ t < 06:00 (same spirit as Keenetic quiet hours)
    night = 2 <= int(now.hour) < 6
    wd = int(now.weekday())  # Mon=0 … Sun=6
    if sch == "night":
        return night
    if sch == "weekdays_night":
        return night and wd < 5
    if sch == "weekends_night":
        return night and wd >= 5
    return True


def _log_update_apply(result: dict, *, source: str = "manual") -> None:
    """Write successful (or failed) OTA into action / policy event log."""
    if not isinstance(result, dict):
        return
    src = (source or "manual").strip() or "manual"
    if result.get("ok"):
        fr = result.get("from_version") or "?"
        to = result.get("to_version") or get_app_version() or "?"
        ref = result.get("ref") or ""
        msg = f"UPDATE {src}: {fr} → {to}"
        if ref:
            msg += f" ({ref})"
        _policy_log(
            "ok",
            msg,
            source=src,
            from_version=fr,
            to_version=to,
            ref=ref or None,
        )
        # persist last success on disk (auto-update status UI)
        try:
            with _update_cfg_lock:
                _update_cfg["last_apply_ts"] = time.time()
                _update_cfg["last_result"] = {
                    "ok": True,
                    "source": src,
                    "from_version": fr,
                    "to_version": to,
                    "ref": ref or None,
                    "at": result.get("applied_at")
                    or datetime.now().isoformat(timespec="seconds"),
                }
                _save_json(UPDATE_CFG_FILE, dict(_update_cfg))
        except Exception:
            pass
    else:
        err = str(result.get("error") or "failed")
        _policy_log("err", f"UPDATE {src}: {err}", source=src, error=err)


def auto_update_tick(*, force: bool = False) -> dict:
    """
    One auto-update cycle: if enabled + schedule window + interval → check GitHub;
    install when update_available. Logs success to action log.
    """
    cfg = get_update_cfg()
    out: dict = {
        "ok": True,
        "ran": False,
        "skipped": None,
        "auto_update": bool(cfg.get("auto_update")),
        "schedule": cfg.get("schedule"),
        "schedule_active": _update_schedule_active(cfg),
    }
    if not cfg.get("auto_update") and not force:
        out["skipped"] = "disabled"
        return out
    if not _update_schedule_active(cfg) and not force:
        out["skipped"] = "schedule"
        return out
    if _update_state.get("busy"):
        out["skipped"] = "busy"
        return out

    now = time.time()
    interval = max(30, int(cfg.get("check_interval_min") or 360)) * 60
    last_ts = cfg.get("last_check_ts")
    try:
        last_f = float(last_ts) if last_ts is not None else 0.0
    except (TypeError, ValueError):
        last_f = 0.0
    if not force and last_f > 0 and (now - last_f) < interval:
        out["skipped"] = "interval"
        out["next_check_in_sec"] = int(interval - (now - last_f))
        return out

    out["ran"] = True
    try:
        chk = check_github_update(lang="en")
    except Exception as e:
        out["ok"] = False
        out["error"] = str(e)
        try:
            with _update_cfg_lock:
                _update_cfg["last_check_ts"] = time.time()
                _update_cfg["last_result"] = {
                    "ok": False,
                    "error": str(e),
                    "at": datetime.now().isoformat(timespec="seconds"),
                }
                _save_json(UPDATE_CFG_FILE, dict(_update_cfg))
        except Exception:
            pass
        return out

    try:
        with _update_cfg_lock:
            _update_cfg["last_check_ts"] = time.time()
            _update_cfg["last_result"] = {
                "ok": bool(chk.get("ok")),
                "status": chk.get("status"),
                "current_version": chk.get("current_version"),
                "latest_version": chk.get("latest_version"),
                "update_available": bool(chk.get("update_available")),
                "at": chk.get("checked_at")
                or datetime.now().isoformat(timespec="seconds"),
            }
            _save_json(UPDATE_CFG_FILE, dict(_update_cfg))
    except Exception:
        pass

    out["check"] = {
        "status": chk.get("status"),
        "update_available": bool(chk.get("update_available")),
        "current_version": chk.get("current_version"),
        "latest_version": chk.get("latest_version"),
    }

    if not chk.get("update_available"):
        out["skipped"] = "up_to_date"
        return out

    # Install latest release / tag from last_check (logs once with source=auto)
    result = apply_github_update(None, source="auto")
    out["apply"] = {
        "ok": bool(result.get("ok")) if isinstance(result, dict) else False,
        "from_version": (result or {}).get("from_version") if isinstance(result, dict) else None,
        "to_version": (result or {}).get("to_version") if isinstance(result, dict) else None,
        "error": (result or {}).get("error") if isinstance(result, dict) else None,
    }
    out["ok"] = bool(out["apply"]["ok"])
    return out


def auto_update_loop() -> None:
    """Background: check/install GitHub updates on schedule (Keenetic-style)."""
    print("[update] auto-update loop start", flush=True)
    # first pass after boot delay so network/DNS settle
    time.sleep(45)
    while not _auto_update_stop.is_set():
        try:
            cfg = get_update_cfg()
            if cfg.get("auto_update"):
                r = auto_update_tick(force=False)
                if r.get("ran"):
                    print(
                        f"[update] auto tick: avail={ (r.get('check') or {}).get('update_available') } "
                        f"skip={r.get('skipped')} apply={ (r.get('apply') or {}).get('ok') }",
                        flush=True,
                    )
        except Exception as e:
            print(f"[update] auto loop: {e}", flush=True)
        # wake often enough for night windows; real throttle is check_interval_min
        _auto_update_stop.wait(120)
    print("[update] auto-update loop stop", flush=True)


def _add_to_16(s: str) -> bytes:
    b = s.encode("utf-8")
    if len(b) % 16:
        b += b"\x00" * (16 - len(b) % 16)
    return b


# Whatsminer: max ~100 tokens, default lifetime ~30 min (API manual Code 136).
# Each successful get_token burns a slot — cache & reuse; do not spam get_token.
_OVER_MAX_CONNECT_RU = (
    "лимит токенов API майнера (over max connect, до 100 / ~30 мин). "
    "Не жмите повторно: подождите до 30 мин или перезагрузите ASIC (питание / web). "
    "Read-команды (summary) не при чём — только get_token."
)

_token_cache_lock = threading.Lock()
# {host, port, pwd_fp, host_sign, host_passwd_md5, expires_at}
_token_cache: dict | None = None

# After over-max: freeze TCP privileged writes so policy cannot burn more slots.
# LuCI-first ops (mode/pools/reboot/restart) stay available.
_tcp_write_backoff_lock = threading.Lock()
_tcp_write_backoff_until: float = 0.0
_TCP_WRITE_BACKOFF_SEC = 1200.0  # 20 min


def _msg_is_over_max_connect(msg) -> bool:
    if not isinstance(msg, str):
        return False
    low = msg.strip().lower()
    return (
        low == "over max connect"
        or "over max connect" in low
        or "лимит токенов api" in low
    )


def _note_tcp_write_exhausted(sec: float | None = None) -> None:
    global _tcp_write_backoff_until
    wait = float(sec if sec is not None else _TCP_WRITE_BACKOFF_SEC)
    with _tcp_write_backoff_lock:
        _tcp_write_backoff_until = max(
            _tcp_write_backoff_until, time.time() + max(60.0, wait)
        )


def _tcp_write_blocked() -> bool:
    with _tcp_write_backoff_lock:
        return time.time() < _tcp_write_backoff_until


def _tcp_write_blocked_msg() -> str:
    with _tcp_write_backoff_lock:
        rem = max(0, int(_tcp_write_backoff_until - time.time()))
    return f"{_OVER_MAX_CONNECT_RU} · backoff {rem}s (LuCI mode/reboot всё ещё работают)"


def _password_fingerprint(password: str) -> str:
    return hashlib.sha256((password or "").encode("utf-8")).hexdigest()[:16]


def _token_cache_get(password: str) -> dict | None:
    global _token_cache
    with _token_cache_lock:
        c = _token_cache
        if not c:
            return None
        if c.get("host") != HOST_MINER or int(c.get("port") or 0) != int(PORT_MINER):
            return None
        if c.get("pwd_fp") != _password_fingerprint(password):
            return None
        if float(c.get("expires_at") or 0) <= time.time():
            _token_cache = None
            return None
        return {
            "host_sign": c["host_sign"],
            "host_passwd_md5": c["host_passwd_md5"],
        }


def _token_cache_put(password: str, token: dict, *, ttl_sec: float) -> None:
    global _token_cache
    with _token_cache_lock:
        _token_cache = {
            "host": HOST_MINER,
            "port": int(PORT_MINER),
            "pwd_fp": _password_fingerprint(password),
            "host_sign": token["host_sign"],
            "host_passwd_md5": token["host_passwd_md5"],
            "expires_at": time.time() + max(30.0, float(ttl_sec)),
        }


def _token_cache_clear() -> None:
    global _token_cache
    with _token_cache_lock:
        _token_cache = None


def _decrypt_privileged_response(cipher, raw: dict) -> dict:
    """Miner may return ciphertext in «data» or «enc» (base64 string)."""
    if not isinstance(raw, dict):
        return raw  # type: ignore[return-value]
    blob = None
    for k in ("data", "enc"):
        v = raw.get(k)
        # request uses enc:1 (int); response uses enc:"<base64>"
        if isinstance(v, str) and len(v) > 16:
            blob = v
            break
    if not blob:
        return raw
    try:
        pt = cipher.decrypt(base64.b64decode(blob)).split(b"\x00")[0].decode()
        return json.loads(pt)
    except Exception:
        return raw


def get_token_data(
    password: str,
    *,
    max_attempts: int = 3,
    unlocked: bool = False,
) -> dict:
    """Removed from serve — token crypto is in Go miner-poller / wm-lib."""
    raise RuntimeError(
        "get_token disabled in serve (no passlib) — use miner-poller writes"
    )


def _miner_write_ports() -> list[int]:
    """
    TCP write ports to try (order matters).
    4028 = classic BTMiner API (get_version api_ver 2.x).
    4029 = temporary «API-v2 / IP access mode» seen during restarts on some FW.
    """
    ports: list[int] = []
    for p in (int(PORT_MINER), 4029, 4028):
        if p not in ports:
            ports.append(p)
    return ports


def privileged_cmd(
    cmd: dict,
    password: str,
    *,
    token_attempts: int = 3,
    ports: list[int] | None = None,
) -> dict:
    """Route privileged writes through miner-poller only."""
    return miner_write_cmd(cmd, password)


