def get_write_api_status(password: str | None = None) -> dict:
    """Probe write path via miner-poller only (no direct ASIC from serve)."""
    password = password or DEFAULT_API_PASSWORD
    out: dict = {
        "ok": True,
        "write_ok": False,
        "v2_write_ok": False,
        "v3_write_ok": None,
        "luci_ok": None,
        "poller": miner_poller_process_alive(),
        "hint": "",
    }
    if not miner_poller_process_alive():
        out["hint"] = "miner-poller not running"
        out["error"] = out["hint"]
        return out
    try:
        r = miner_write_cmd({"cmd": "set_led", "param": "auto"}, password)
        try:
            ok, msg = _miner_cmd_result(r)
        except Exception:
            ok, msg = True, "ok"
        out["v2_write_ok"] = bool(ok)
        out["write_ok"] = bool(ok)
        if not ok:
            out["v2_write_error"] = msg
            out["hint"] = str(msg)
        else:
            out["hint"] = "Write via miner-poller OK"
    except Exception as e:
        out["v2_write_ok"] = False
        out["v2_write_error"] = str(e)
        out["hint"] = str(e)
    return out


def enable_write_api(
    password: str | None = None,
    *,
    new_password: str | None = None,
) -> dict:
    """Enable Miner API Switch via miner-poller NetPacket only."""
    password = (password or DEFAULT_API_PASSWORD or "admin").strip() or "admin"
    steps: list[dict] = []
    try:
        r = luci_enable_api_switch(password, enable=True)
        steps.append({"step": "netpacket_api_switch", "ok": True, "detail": r})
    except Exception as e:
        steps.append({"step": "netpacket_api_switch", "ok": False, "detail": str(e)})
        return {
            "ok": False,
            "enabled": False,
            "message": str(e),
            "steps": steps,
        }
    status = get_write_api_status(password)
    enabled = bool(status.get("write_ok"))
    return {
        "ok": True,
        "enabled": enabled,
        "message": (
            "Write API via poller" if enabled else
            "api_switch sent · verify Suspend/mode"
        ),
        "status": status,
        "steps": steps,
    }


def _write_json_atomic(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
    tmp.replace(path)


_miner_write_ipc_lock = threading.Lock()
_miner_read_ipc_lock = threading.Lock()


def miner_read_via_poller(
    cmd: dict,
    *,
    timeout_sec: float | None = None,
    password: str | None = None,
) -> dict:
    """
    Enqueue on-demand ASIC read for Go miner-poller (file IPC).

    serve/UI never opens miner TCP. Job:
    miner_read_req.json → poller → miner_read_result.json.
    """
    if not miner_poller_process_alive():
        raise RuntimeError(
            "miner-poller not running — ASIC read only via poller "
            f"(cmd={cmd.get('cmd')!r})"
        )
    req_id = uuid.uuid4().hex
    timeout = float(
        timeout_sec if timeout_sec is not None else MINER_READ_TIMEOUT_SEC
    )
    req = {
        "id": req_id,
        "ts": time.time(),
        "cmd": dict(cmd or {}),
        "password": password or DEFAULT_API_PASSWORD,
    }
    with _miner_read_ipc_lock:
        try:
            if MINER_READ_RESULT_FILE.is_file():
                MINER_READ_RESULT_FILE.unlink()
        except Exception:
            pass
        _write_json_atomic(MINER_READ_REQ_FILE, req)
        deadline = time.time() + max(3.0, timeout)
        last_err = "timeout waiting for miner-poller read result"
        while time.time() < deadline:
            time.sleep(0.12)
            try:
                if not MINER_READ_RESULT_FILE.is_file():
                    if not miner_poller_process_alive():
                        raise RuntimeError("miner-poller died during read")
                    continue
                raw = json.loads(MINER_READ_RESULT_FILE.read_text(encoding="utf-8"))
                if not isinstance(raw, dict) or str(raw.get("id") or "") != req_id:
                    continue
                if not raw.get("ok"):
                    err = str(raw.get("error") or "miner read failed")
                    raise RuntimeError(err)
                resp = raw.get("response")
                if not isinstance(resp, dict):
                    resp = {"STATUS": "S", "Msg": resp, "transport": "go-miner-poller"}
                else:
                    resp = dict(resp)
                resp.setdefault("transport", raw.get("transport") or "go-miner-poller")
                return resp
            except RuntimeError:
                raise
            except Exception as e:
                last_err = str(e)
                continue
        raise RuntimeError(last_err)


def miner_write_via_poller(
    cmd: dict,
    password: str,
    *,
    action: str | None = None,
    value=None,
    timeout_sec: float | None = None,
) -> dict:
    """
    Enqueue privileged write for Go miner-poller (file IPC).
    serve never opens ASIC TCP (:4028 / :4433 / :8889).
    """
    if not miner_poller_process_alive():
        raise RuntimeError(
            "miner-poller not running — ASIC write only via poller"
        )
    req_id = uuid.uuid4().hex
    timeout = float(timeout_sec if timeout_sec is not None else MINER_WRITE_TIMEOUT_SEC)
    req = {
        "id": req_id,
        "ts": time.time(),
        "cmd": dict(cmd or {}),
        "password": password or DEFAULT_API_PASSWORD,
        "action": action,
        "value": value,
    }
    with _miner_write_ipc_lock:
        # Drop stale result so we don't match an old id
        try:
            if MINER_WRITE_RESULT_FILE.is_file():
                MINER_WRITE_RESULT_FILE.unlink()
        except Exception:
            pass
        _write_json_atomic(MINER_WRITE_REQ_FILE, req)
        deadline = time.time() + max(3.0, timeout)
        last_err = "timeout waiting for miner-poller write result"
        while time.time() < deadline:
            time.sleep(0.15)
            try:
                if not MINER_WRITE_RESULT_FILE.is_file():
                    if not miner_poller_process_alive():
                        raise RuntimeError("miner-poller died during write")
                    continue
                raw = json.loads(MINER_WRITE_RESULT_FILE.read_text(encoding="utf-8"))
                if not isinstance(raw, dict) or str(raw.get("id") or "") != req_id:
                    continue
                if not raw.get("ok"):
                    err = str(raw.get("error") or "miner rejected command")
                    raise RuntimeError(err)
                resp = raw.get("response")
                if not isinstance(resp, dict):
                    resp = {"STATUS": "S", "Msg": "ok", "transport": "go-miner-poller"}
                else:
                    resp = dict(resp)
                resp.setdefault("transport", raw.get("transport") or "go-miner-poller")
                return resp
            except RuntimeError:
                raise
            except Exception as e:
                last_err = str(e)
                continue
        raise RuntimeError(last_err)


def miner_write_cmd(cmd: dict, password: str) -> dict:
    """
    Unified write path — Go miner-poller only (file IPC).
    serve never opens ASIC TCP / never loads whatsminer.
    """
    password = password or DEFAULT_API_PASSWORD
    cname = str(cmd.get("cmd") or "").strip()

    if not miner_is_online(max_age_sec=_MINER_ONLINE_MAX_AGE_SEC, probe=False):
        if not miner_poller_process_alive():
            raise RuntimeError(
                "ASIC offline · write skipped (нет live_cache — команда не отправлялась)"
            )

    if not miner_poller_process_alive():
        raise RuntimeError(
            "miner-poller not running — ASIC writes (factory_reset/reboot/pools/…) "
            "go only via poller NetPacket/V2. Restart miner-poller from Info → Processes "
            "or: /opt/bin/poolheat-miner-poller"
        )
    try:
        to = None
        if cname in (
            "update_pools",
            "set_pools",
            "reboot",
            "reboot_asic",
            "system_reboot",
            "restart_btminer",
            "restart",
            "restart_miner",
            "restart_cgminer",
            "btminer_restart",
            "factory_reset",
            "factory",
            "restore_factory",
            "reset_factory",
            "set_customer_sn",
            "customer_sn",
            "set_customer_msg",
        ):
            to = max(float(MINER_WRITE_TIMEOUT_SEC), 60.0)
        return miner_write_via_poller(cmd, password, timeout_sec=to)
    except Exception as e:
        err = str(e)
        if "over max" in err.lower() and "лимит" not in err.lower():
            raise RuntimeError(_OVER_MAX_CONNECT_RU) from e
        raise


