# Typical J/TH when Factory GHS unavailable (~2990 W / ~172.7 TH on this M63)
_DEFAULT_J_PER_TH = 17.31


def _official_cause(code: str, *, native_cause: str | None = None) -> str | None:
    """Cause text for error code.

    Prefer native WMOC/firmware reason (may include chip list U1-U2-…).
    Else short catalog title (exact code only — no invented patterns).
    Else local web-UI map.
    """
    c = str(code).strip()
    c2 = c.lstrip("0") or "0"
    if native_cause and str(native_cause).strip():
        nc = str(native_cause).strip()
        if nc.lower() not in (f"error code {c}".lower(), f"error {c}".lower()):
            return nc
    # whatsminer catalog removed from serve — use local web-UI map only
    if c in _MINER_ERROR_CAUSES:
        return _MINER_ERROR_CAUSES[c]
    if c2 in _MINER_ERROR_CAUSES:
        return _MINER_ERROR_CAUSES[c2]
    return None


def _parse_error_code_item(item) -> list[dict]:
    """
    Normalize one entry from get_error_code Msg.error_code.
    Supports:
      {"2320": "2026-08-03 01:26:57"}
      {"error_code":"2320","time":"...","cause":"...","error_message":"..."}
      {"Code":2320,"Cause":"Hashrate too low, ...","Time":"..."}
    """
    if not isinstance(item, dict):
        return []
    # structured form with explicit cause
    code = (
        item.get("error_code")
        or item.get("ErrorCode")
        or item.get("code")
        or item.get("Code")
    )
    cause = (
        item.get("cause")
        or item.get("Cause")
        or item.get("error_message")
        or item.get("ErrorMessage")
        or item.get("msg")
        or item.get("Msg")
        or item.get("message")
        or item.get("Description")
    )
    ts = (
        item.get("time")
        or item.get("Time")
        or item.get("timestamp")
        or item.get("When")
        or item.get("ts")
    )
    out: list[dict] = []
    if code is not None and str(code).strip().isdigit():
        out.append(
            {
                "code": str(code).strip(),
                "ts": str(ts) if ts is not None else None,
                "cause": str(cause).strip() if cause not in (None, "") else None,
            }
        )
        return out
    # classic map form: { "2320": "2026-08-03 01:26:57" }
    for k, v in item.items():
        ks = str(k).strip()
        if not ks or not ks.replace(".", "").isdigit():
            continue
        # value may be time string or nested dict
        if isinstance(v, dict):
            c2 = (
                v.get("cause")
                or v.get("Cause")
                or v.get("error_message")
                or v.get("msg")
            )
            t2 = v.get("time") or v.get("Time") or v.get("timestamp")
            out.append(
                {
                    "code": ks,
                    "ts": str(t2) if t2 is not None else None,
                    "cause": str(c2).strip() if c2 not in (None, "") else None,
                }
            )
        else:
            out.append(
                {
                    "code": ks,
                    "ts": str(v) if v is not None else None,
                    "cause": None,
                }
            )
    return out


def _fetch_miner_errors_tcp() -> list[dict]:
    """
    TCP get_error_code → list of {code, ts, cause?}.
    Note: firmware often returns a *recent buffer* (history), not only the
    active Errors table on the miner web UI. Prefer LuCI scrape when available.
    """
    out: list[dict] = []
    try:
        raw = miner_cmd({"cmd": "get_error_code"}, timeout=4)
    except Exception:
        return out
    msg = raw.get("Msg") if isinstance(raw, dict) else None
    codes = None
    if isinstance(msg, dict):
        codes = msg.get("error_code")
    elif isinstance(msg, list):
        codes = msg
    if not isinstance(codes, list):
        return out
    for item in codes:
        out.extend(_parse_error_code_item(item))
    return out


def _fetch_miner_errors_raw() -> list[dict]:
    """
    Active firmware errors for the live UI table.
    Prefer LuCI Miner Status → Errors (same list as WhatsMiner web).
    Fall back to TCP get_error_code if LuCI unavailable.
    """
    luci, ok = _fetch_miner_errors_luci_state(force=False)
    if ok:
        return luci
    return _fetch_miner_errors_tcp()


def _snapshot_cause_2320(
    *,
    hashrate_th: float | None,
    power_limit: float | None,
    factory_ghs: float | None,
) -> str:
    """
    Whatsminer web Cause for 2320 (snapshot at first detection).
    API usually only gives code+time; stock UI builds this string once.
    """
    cur = hashrate_th
    exp: float | None = None
    if factory_ghs is not None and factory_ghs > 0:
        exp = float(factory_ghs) / 1000.0
    elif power_limit is not None and power_limit > 0:
        exp = float(power_limit) / _DEFAULT_J_PER_TH
    if cur is not None and exp is not None and exp > 0:
        pct = 100.0 * float(cur) / exp
        return (
            f"Hashrate too low, current: {float(cur):.2f}T, "
            f"expected: {exp:.2f}T, percent: {pct:.2f}%"
        )
    if cur is not None:
        return f"Hashrate too low, current: {float(cur):.2f}T"
    return "Hashrate too low"


def _resolve_miner_errors(
    raw_errors: list[dict],
    *,
    hashrate_th: float | None,
    power_limit: float | None,
    factory_ghs: float | None,
) -> list[dict]:
    """
    Active firmware errors for UI table: ErrorCode | Cause | Time.
    Cause is frozen on first sight (cache) so live hashrate does not rewrite it.
    """
    with _state_lock:
        cache = dict(_state.get("miner_error_cache") or {})

    active: list[dict] = []
    active_keys: set[str] = set()

    for e in raw_errors:
        code = str(e.get("code") or "").strip()
        if not code:
            continue
        ts = e.get("ts")
        key = f"{code}@{ts or ''}"
        active_keys.add(key)

        # prefer native Cause from miner API if present
        cause = e.get("cause")
        # ignore placeholder "Error code NNN" (our old fallback / empty FW)
        if cause and str(cause).strip().lower() in (
            f"error code {code}".lower(),
            f"error {code}".lower(),
        ):
            cause = None

        hint = (
            _MINER_ERROR_HINTS.get(code)
            or _MINER_ERROR_HINTS.get(code[:3] + "0")
            or f"Error {code}"
        )

        if key in cache and cache[key].get("cause"):
            cached = cache[key]["cause"]
            c_ok = cached and str(cached).strip().lower() not in (
                f"error code {code}".lower(),
                f"error {code}".lower(),
            )
            n_ok = cause and str(cause).strip().lower() not in (
                f"error code {code}".lower(),
                f"error {code}".lower(),
            )
            # Prefer richer live Cause (LuCI often has vin:/U1- details)
            # over a shorter frozen map string from first sight.
            if n_ok and c_ok:
                if len(str(cause).strip()) >= len(str(cached).strip()):
                    pass  # keep native
                else:
                    cause = cached
            elif c_ok and not n_ok:
                cause = cached
            elif not n_ok:
                cause = None

        if not cause:
            if code == "2320" or code.startswith("232"):
                cause = _snapshot_cause_2320(
                    hashrate_th=hashrate_th,
                    power_limit=power_limit,
                    factory_ghs=factory_ghs,
                )
            else:
                # catalog short title if known; else "Error code N"
                # Full WMOC text with U1-U2-… only when firmware sent it as cause
                cause = _official_cause(code, native_cause=e.get("cause")) or f"Error code {code}"

        cache[key] = {"code": code, "ts": ts, "cause": cause, "hint": hint}
        active.append(
            {
                "code": code,
                "cause": cause,
                "ts": ts,
                "hint": hint,
                # aliases for older UI
                "message": cause,
            }
        )

    # journal: log active errors (dedupe by code+miner_ts in DB)
    try:
        log_miner_errors(active, miner_ctx=get_miner_identity_cached())
    except Exception as e:
        print(f"[errors] log failed: {e}")

    # drop cleared errors from cache
    cache = {k: v for k, v in cache.items() if k in active_keys}

    with _state_lock:
        _state["miner_error_cache"] = cache
        _save_state()

    return active


# ── ASIC Errors + Events (LuCI Miner Status page) ────────────────────────────
# Errors table = active faults (same as web «Errors» — not TCP history buffer).
# Events table = EventCode / EventCause / … (web-only).
# One LuCI scrape fills both caches.

_MINER_EVENTS_TTL_S = 45.0
_MINER_ERRORS_LUCI_TTL_S = 45.0
_miner_events_lock = threading.Lock()
_miner_events_cache: dict = {
    "ts": 0.0,
    "events": [],
    "error": None,
    "source": None,
}
_miner_events_refreshing = False

_miner_errors_luci_lock = threading.Lock()
_miner_errors_luci_cache: dict = {
    "ts": 0.0,
    "errors": [],
    "error": None,
    "source": None,
    "ok": False,  # True once we successfully scraped LuCI (even if 0 rows)
}


def _strip_html_text(s: str) -> str:
    t = re.sub(r"<[^>]+>", " ", s or "")
    t = (
        t.replace("&nbsp;", " ")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
        .replace("&quot;", '"')
        .replace("&#39;", "'")
    )
    return re.sub(r"\s+", " ", t).strip()


def _parse_miner_errors_html(html: str) -> list[dict]:
    """
    Parse active Errors table from LuCI /admin/status/btminerstatus.
    Columns: ErrorCode · Cause · Time — same as stock web UI.
    Returns list of {code, ts, cause}.
    """
    if not html:
        return []
    out: list[dict] = []
    for tm in re.finditer(r"<table\b[^>]*>(.*?)</table>", html, re.I | re.S):
        table = tm.group(1)
        ths = re.findall(r"<th\b[^>]*>(.*?)</th>", table, re.I | re.S)
        headers = [_strip_html_text(h).lower().replace(" ", "") for h in ths]
        # Active errors table has ErrorCode (not EventCode)
        if not any(h in ("errorcode", "error_code") for h in headers):
            continue
        if any(h in ("eventcode", "event_code") for h in headers):
            continue
        # Map column indices
        def _col(*names: str) -> int | None:
            for n in names:
                if n in headers:
                    return headers.index(n)
            return None

        i_code = _col("errorcode", "error_code", "code")
        i_cause = _col("cause", "errorcause", "message")
        i_time = _col("time", "timestamp", "when")
        if i_code is None:
            continue
        for tr in re.finditer(r"<tr\b[^>]*>(.*?)</tr>", table, re.I | re.S):
            row_html = tr.group(1)
            # skip title / descr rows
            if re.search(r"<th\b", row_html, re.I) and not re.search(
                r"<td\b", row_html, re.I
            ):
                continue
            tds = re.findall(r"<td\b[^>]*>(.*?)</td>", row_html, re.I | re.S)
            if not tds:
                continue
            # Prefer hidden input values (stable)
            def _cell(i: int | None) -> str:
                if i is None or i >= len(tds):
                    return ""
                cell = tds[i]
                hm = re.search(
                    r'<input[^>]+value="([^"]*)"', cell, re.I
                )
                if hm:
                    return _strip_html_text(hm.group(1))
                return _strip_html_text(cell)

            code = _cell(i_code)
            if not code or not re.fullmatch(r"\d{2,6}", code):
                continue
            cause = _cell(i_cause) or None
            ts = _cell(i_time) or None
            out.append({"code": code, "ts": ts, "cause": cause})
        if out:
            break
    return out


def _parse_miner_events_html(html: str) -> list[dict]:
    """
    Parse Events table from LuCI /admin/status/btminerstatus HTML.
    Returns list of {code, cause, action, count, ts, source, detail}.
    """
    if not html:
        return []
    out: list[dict] = []
    # Prefer tables that include an EventCode header (not ErrorCode).
    for tm in re.finditer(r"<table\b[^>]*>(.*?)</table>", html, re.I | re.S):
        table = tm.group(1)
        ths = re.findall(r"<th\b[^>]*>(.*?)</th>", table, re.I | re.S)
        headers = [_strip_html_text(h).lower().replace(" ", "") for h in ths]
        if not headers:
            # some FW use first row of <td> as titles
            first_tr = re.search(r"<tr\b[^>]*>(.*?)</tr>", table, re.I | re.S)
            if first_tr:
                tds0 = re.findall(r"<t[dh]\b[^>]*>(.*?)</t[dh]>", first_tr.group(1), re.I | re.S)
                headers = [_strip_html_text(h).lower().replace(" ", "") for h in tds0]
        if not any(h in ("eventcode", "event_code") for h in headers):
            continue
        # skip pure Error table (ErrorCode without EventCode)
        if any(h in ("errorcode", "error_code") for h in headers) and not any(
            h in ("eventcode", "event_code") for h in headers
        ):
            continue

        def _col(*names: str) -> int | None:
            for n in names:
                if n in headers:
                    return headers.index(n)
            return None

        i_code = _col("eventcode", "event_code", "code")
        i_cause = _col("eventcause", "event_cause", "cause")
        i_action = _col("eventaction", "event_action", "action")
        i_count = _col("eventcount", "event_count", "count")
        i_time = _col("lasttime", "last_time", "time")
        i_src = _col("eventsource", "event_source", "source")
        i_detail = _col("detail")
        if i_code is None:
            continue

        for rm in re.finditer(r"<tr\b[^>]*>(.*?)</tr>", table, re.I | re.S):
            row = rm.group(1)
            if re.search(r"<th\b", row, re.I):
                continue
            cells = re.findall(r"<td\b[^>]*>(.*?)</td>", row, re.I | re.S)
            if not cells:
                continue
            texts = [_strip_html_text(c) for c in cells]
            # skip header-like rows
            joined = " ".join(texts).lower()
            if "eventcode" in joined or joined.startswith("event code"):
                continue

            def _at(idx: int | None) -> str:
                if idx is None or idx < 0 or idx >= len(texts):
                    return ""
                return texts[idx]

            code = _at(i_code)
            if not code or code in ("—", "-", "–"):
                continue
            # ignore placeholder / empty-section rows (LuCI empty table message)
            code_l = code.lower().strip()
            if code_l in ("no data", "none", "n/a", "—", "-", "–"):
                continue
            if (
                "no values" in code_l
                or "no events" in code_l
                or "no data" in code_l
                or "contains no" in code_l
                or "section contains" in code_l
                or code_l.startswith("this section")
            ):
                continue
            # multi-word prose is never a real EventCode (codes are short tokens)
            if len(code) > 40 or (" " in code and not re.match(r"^[\w.-]+$", code)):
                # allow short codes with dots; reject long free-text cells
                if " " in code and not re.match(r"^E?\d{1,6}$", code, re.I):
                    continue
            cause = _at(i_cause)
            action = _at(i_action)
            count_s = _at(i_count)
            ts = _at(i_time)
            source = _at(i_src)
            detail = _at(i_detail)
            # Detail buttons often render as "Detail" only — drop that noise
            if detail.lower() in ("detail", "details", "…", "..."):
                detail = ""
            count: int | None = None
            try:
                if count_s:
                    count = int(re.sub(r"[^\d-]", "", count_s) or 0)
            except (TypeError, ValueError):
                count = None
            out.append(
                {
                    "code": code,
                    "cause": cause or None,
                    "action": action or None,
                    "count": count,
                    "ts": ts or None,
                    "source": source or None,
                    "detail": detail or None,
                }
            )
        if out:
            break
    return out


def _scrape_miner_status_luci_once() -> tuple[list[dict], list[dict], str | None]:
    """
    One LuCI scrape of Miner Status → active Errors + Events tables.
    Returns (errors, events, error_or_None). Uses chipmap web credentials.
    """
    password = _chipmap_web_password()
    base = _chipmap_base_url()
    user = "admin"
    verify = False
    try:
        with _chipmap_lock:
            user = str(_chipmap_cfg.get("web_user") or "admin")
            verify = bool(_chipmap_cfg.get("verify_tls", False))
    except Exception:
        pass

    errors: list[dict] = []
    events: list[dict] = []
    err: str | None = None
    try:
        import ssl as _ssl
        import http.cookiejar

        ctx = _ssl.create_default_context()
        if not verify:
            ctx.check_hostname = False
            ctx.verify_mode = _ssl.CERT_NONE
        cj = http.cookiejar.CookieJar()
        opener = urllib.request.build_opener(
            urllib.request.HTTPSHandler(context=ctx),
            urllib.request.HTTPHandler(),
            urllib.request.HTTPCookieProcessor(cj),
        )
        opener.addheaders = [("User-Agent", "poolheat-status/1.0")]

        login_body = urllib.parse.urlencode(
            {"luci_username": user, "luci_password": password}
        ).encode("utf-8")
        login_req = urllib.request.Request(
            f"{base}/cgi-bin/luci",
            data=login_body,
            method="POST",
            headers={"Content-Type": "application/x-www-form-urlencoded"},
        )
        with opener.open(login_req, timeout=6) as resp:
            _ = resp.read(8192)

        page_req = urllib.request.Request(
            f"{base}/cgi-bin/luci/admin/status/btminerstatus",
            method="GET",
        )
        with opener.open(page_req, timeout=8) as resp:
            html = resp.read().decode("utf-8", errors="replace")

        errors = _parse_miner_errors_html(html)
        events = _parse_miner_events_html(html)
        if (
            not errors
            and not events
            and "luci_username" in html
            and "ErrorCode" not in html
            and "EventCode" not in html
        ):
            err = "luci login failed (check web password)"
    except Exception as e:
        err = str(e)
        errors = []
        events = []
    return errors, events, err


def _scrape_miner_events_luci_once() -> tuple[list[dict], str | None]:
    """Back-compat: Events only."""
    _errs, events, err = _scrape_miner_status_luci_once()
    return events, err


def _apply_luci_status_caches(
    errors: list[dict],
    events: list[dict],
    err: str | None,
) -> None:
    """Write both LuCI caches from one scrape."""
    now = time.time()
    with _miner_events_lock:
        if err and not events and _miner_events_cache.get("events"):
            _miner_events_cache["error"] = err
            _miner_events_cache["ts"] = now
        else:
            _miner_events_cache["ts"] = now
            _miner_events_cache["events"] = list(events)
            _miner_events_cache["error"] = err
            _miner_events_cache["source"] = "luci:btminerstatus"
    with _miner_errors_luci_lock:
        if err and not errors and _miner_errors_luci_cache.get("ok"):
            # keep last good active list on transient failure
            _miner_errors_luci_cache["error"] = err
            _miner_errors_luci_cache["ts"] = now
        else:
            _miner_errors_luci_cache["ts"] = now
            _miner_errors_luci_cache["errors"] = list(errors)
            _miner_errors_luci_cache["error"] = err
            _miner_errors_luci_cache["source"] = "luci:btminerstatus"
            # success even when 0 active errors (empty table)
            _miner_errors_luci_cache["ok"] = err is None or bool(errors)


def _miner_events_bg_refresh() -> None:
    global _miner_events_refreshing
    try:
        errors, events, err = _scrape_miner_status_luci_once()
        _apply_luci_status_caches(errors, events, err)
    except Exception as e:
        print(f"[events] bg refresh: {e}")
    finally:
        with _miner_events_lock:
            _miner_events_refreshing = False


def _fetch_miner_errors_luci_state(
    *, force: bool = False
) -> tuple[list[dict], bool]:
    """
    Active Errors from LuCI cache.
    Returns (errors, ok) — ok=True means LuCI source is trusted (use even if empty).
    Cold start (never scraped): one short sync scrape so we do not fall back to
    the TCP history buffer and show stale codes.
    """
    global _miner_events_refreshing
    now = time.time()
    with _miner_errors_luci_lock:
        age = now - float(_miner_errors_luci_cache.get("ts") or 0)
        cached = list(_miner_errors_luci_cache.get("errors") or [])
        ok = bool(_miner_errors_luci_cache.get("ok"))
        has_ts = float(_miner_errors_luci_cache.get("ts") or 0) > 0
        fresh = (not force) and ok and has_ts and age < _MINER_ERRORS_LUCI_TTL_S
        if fresh:
            return cached, True
        # stale but previously successful — serve cache, refresh in background
        if ok and has_ts and not force:
            with _miner_events_lock:
                if not _miner_events_refreshing:
                    _miner_events_refreshing = True
                    threading.Thread(
                        target=_miner_events_bg_refresh,
                        name="miner-status-luci",
                        daemon=True,
                    ).start()
            return cached, True

    # cold start or force: sync scrape once (must not use TCP buffer as “active”)
    errors, events, err = _scrape_miner_status_luci_once()
    _apply_luci_status_caches(errors, events, err)
    with _miner_errors_luci_lock:
        return (
            list(_miner_errors_luci_cache.get("errors") or []),
            bool(_miner_errors_luci_cache.get("ok")),
        )


def _fetch_miner_events_luci(*, force: bool = False) -> list[dict]:
    """
    Cached Events for live UI. Stale cache is served immediately; refresh runs
    in a background thread so /api/live is not blocked by LuCI.
    Cold start (empty cache) does one short sync scrape.
    """
    global _miner_events_refreshing
    now = time.time()
    with _miner_events_lock:
        age = now - float(_miner_events_cache.get("ts") or 0)
        cached = list(_miner_events_cache.get("events") or [])
        fresh = (not force) and age < _MINER_EVENTS_TTL_S and (
            _miner_events_cache.get("ts") or 0
        ) > 0
        if fresh:
            return cached
        # have something → return it, refresh in background
        if cached and not force:
            if not _miner_events_refreshing:
                _miner_events_refreshing = True
                threading.Thread(
                    target=_miner_events_bg_refresh,
                    name="miner-status-luci",
                    daemon=True,
                ).start()
            return cached
        if _miner_events_refreshing and not force:
            return cached

    # cold / force: sync once (bounded timeouts inside scrape)
    if not force:
        with _miner_events_lock:
            if not _miner_events_refreshing:
                _miner_events_refreshing = True
                threading.Thread(
                    target=_miner_events_bg_refresh,
                    name="miner-status-luci",
                    daemon=True,
                ).start()
        return []

    errors, events, err = _scrape_miner_status_luci_once()
    _apply_luci_status_caches(errors, events, err)
    return list(events)


def _extract_liquid_temp(
    status: dict | None,
    summary: dict | None,
    psu: dict | None = None,
    *,
    v3_msg: dict | None = None,
) -> float | None:
    """
    Liquid / coolant temperature across firmware families.
    Classic air API: often missing. Liquid M63+: API v3 power.liquid-temperature
    (same field WhatsMinerTool shows as Liquid Temp). Also try status/summary/psu.
    """
    status = status if isinstance(status, dict) else {}
    summary = summary if isinstance(summary, dict) else {}
    psu = psu if isinstance(psu, dict) else {}
    candidates = [
        status.get("liquid_temp"),
        status.get("Liquid Temp"),
        status.get("liquid_temperature"),
        status.get("coolant_temp"),
        summary.get("Liquid Temp"),
        summary.get("liquid_temp"),
        summary.get("Coolant Temp"),
        psu.get("liquid_temp"),
        psu.get("liquid-temperature"),
        psu.get("temp_liquid"),
    ]
    if isinstance(v3_msg, dict):
        power = v3_msg.get("power") if isinstance(v3_msg.get("power"), dict) else {}
        candidates.extend(
            [
                power.get("liquid-temperature"),
                power.get("liquid_temperature"),
                power.get("liquid_temp"),
                power.get("coolant"),
                v3_msg.get("liquid_temp"),
                v3_msg.get("liquid-temperature"),
            ]
        )
    for c in candidates:
        v = _f(c)
        if v is not None:
            return v
    return None


_v3_device_msg_cache: dict | None = None
_v3_device_msg_ts = 0.0
_V3_DEVICE_MSG_TTL_SEC = 30.0

_customer_sn_cache: str | None = None
_customer_sn_ts = 0.0
_CUSTOMER_SN_TTL_SEC = 120.0


def _set_customer_sn_cache(sn: str | None) -> None:
    """Update in-memory CustomerSn cache (after write or successful read)."""
    global _customer_sn_cache, _customer_sn_ts
    sn_n = _normalize_sn(sn) if sn not in (None, "") else None
    _customer_sn_cache = sn_n
    _customer_sn_ts = time.time()


def _fetch_customer_sn(*, force: bool = False) -> str | None:
    """
    CustomerSn via miner-poller IPC (get.device.custom_data / get_customer_msg).
    Cached briefly; force=True re-reads ASIC after set/clear.
    """
    global _customer_sn_cache, _customer_sn_ts
    now = time.time()
    if (
        not force
        and (now - float(_customer_sn_ts or 0)) < _CUSTOMER_SN_TTL_SEC
        and _customer_sn_cache is not None
    ):
        return _customer_sn_cache
    if not miner_poller_process_alive():
        return _customer_sn_cache
    try:
        raw = miner_cmd({"cmd": "get.device.custom_data"}, timeout=12)
        sn = None
        if isinstance(raw, dict):
            sn = _normalize_sn(
                raw.get("customer_sn")
                or raw.get("CustomerSn")
            )
            if not sn:
                msg = raw.get("Msg") or raw.get("msg")
                if isinstance(msg, dict):
                    sn = _normalize_sn(
                        msg.get("CustomerSn")
                        or msg.get("customer_sn")
                        or msg.get("customersn")
                    )
                elif isinstance(msg, str) and msg.strip():
                    # some FW return plain string
                    sn = _normalize_sn(msg)
        if sn:
            _set_customer_sn_cache(sn)
            return sn
        # empty but successful read → cache empty (cleared)
        if isinstance(raw, dict) and (
            raw.get("STATUS") in ("S", "s", None)
            or raw.get("ok") is True
            or "Msg" in raw
            or "msg" in raw
        ):
            # distinguish missing key vs empty SN: if transport answered, store ""
            if raw.get("customer_sn") is not None or raw.get("CustomerSn") is not None:
                _set_customer_sn_cache("")
                return None
            msg = raw.get("Msg") if isinstance(raw.get("Msg"), dict) else raw.get("msg")
            if isinstance(msg, dict) and (
                "CustomerSn" in msg or "customer_sn" in msg or "customersn" in msg
            ):
                _set_customer_sn_cache("")
                return None
    except Exception as e:
        print(f"[ident] get.device.custom_data: {e}", flush=True)
    return _customer_sn_cache


def _fetch_v3_device_msg(*, force: bool = False) -> dict | None:
    """
    get.device.info msg via miner-poller IPC (TCP :4433 stays in poller).
    Cached briefly — used for PCB SN / detect-hash-rate when Suspend.
    """
    global _v3_device_msg_cache, _v3_device_msg_ts
    now = time.time()
    if (
        not force
        and isinstance(_v3_device_msg_cache, dict)
        and (now - float(_v3_device_msg_ts or 0)) < _V3_DEVICE_MSG_TTL_SEC
    ):
        return _v3_device_msg_cache
    if not miner_poller_process_alive():
        return _v3_device_msg_cache if isinstance(_v3_device_msg_cache, dict) else None
    try:
        # poller returns {STATUS, Msg: <device.info msg>} for get.device.info
        raw = miner_cmd({"cmd": "get.device.info"}, timeout=12)
        msg = None
        if isinstance(raw, dict):
            msg = raw.get("Msg")
            if msg is None and isinstance(raw.get("msg"), dict):
                msg = raw.get("msg")
            # some poller shapes nest under response already unwrapped
            if msg is None and (
                "miner" in raw or "power" in raw or "system" in raw
            ):
                msg = raw
        if isinstance(msg, dict) and msg:
            _v3_device_msg_cache = msg
            _v3_device_msg_ts = now
            return msg
    except Exception as e:
        print(f"[ident] v3 get.device.info: {e}", flush=True)
    return _v3_device_msg_cache if isinstance(_v3_device_msg_cache, dict) else None


def _normalize_psu_vin(raw) -> float | None:
    """
    PowerVin (input voltage, V).
    get_psu: often ×100 (e.g. 39200 → 392.0 V); API v3: already volts (392).
    """
    v = _f(raw)
    if v is None or v < 0:
        return None
    if v > 1000:
        # centivolts / 0.01 V units
        return round(v / 100.0, 2)
    return round(v, 2)


def _normalize_psu_iin(raw) -> float | None:
    """
    PowerIin (input current, A).
    get_psu: milliamps as integer string (\"96\", \"12515\") → A.
    API v3: already amps as float (0.09, 12.48) — keep as-is.
    """
    i = _f(raw)
    if i is None or i < 0:
        return None
    s = str(raw).strip().replace(",", ".")
    # integer / no decimal point → get_psu mA
    if s and "." not in s and i >= 1:
        return round(i / 1000.0, 3)
    return round(i, 3)


def _build_temp_sensors_catalog(
    *,
    summary: dict,
    status: dict,
    liquid: float | None,
    liquid_source: str | None,
    boards: list,
    board_chip_min: list,
    board_chip_max: list,
    board_chip_avg: list,
    psu_temp: float | None,
    miner_type: str | None,
    n_boards: int,
) -> list[dict]:
    """
    All temperature points available from this miner poll, for UI catalog.

    Each item: {id, group, label, label_ru, value, unit, source, available}.
    ``available`` is False when the field is not present for this model/FW
    (still listed when the model family typically has it — e.g. liquid on M63).
    """
    out: list[dict] = []
    mt = str(miner_type or "").upper()
    # Prefer model catalog cooling/sensors; fallback to legacy family names
    liquid_family = False
    model_sens: dict = {}
    if resolve_miner_model is not None:
        try:
            mp = resolve_miner_model(miner_type)
            model_sens = mp.get("sensors") if isinstance(mp.get("sensors"), dict) else {}
            liquid_family = bool(
                model_sens.get("liquid_temp")
                or str(mp.get("cooling") or "").lower() == "liquid"
            )
        except Exception:
            liquid_family = False
            model_sens = {}
    if not liquid_family:
        liquid_family = any(
            x in mt for x in ("M53", "M56", "M63", "M66", "M50S", "M30S++", "LIQUID")
        )

    def _add(
        sid: str,
        group: str,
        label: str,
        label_ru: str,
        value,
        source: str,
        *,
        expect: bool = True,
        reject_zero: bool = True,
    ) -> None:
        v = _f(value)
        # FW often reports 0 / null for missing sensors
        if v is not None and reject_zero and (v <= 0.05 or v > 150):
            v = None
        available = v is not None
        # keep expected-but-missing for model (e.g. liquid on hydro) as listed null
        if not available and not expect:
            return
        out.append(
            {
                "id": sid,
                "group": group,
                "label": label,
                "label_ru": label_ru,
                "value": round(v, 2) if v is not None else None,
                "unit": "°C",
                "source": source,
                "available": available,
            }
        )

    _add(
        "env",
        "ambient",
        "Env Temp",
        "Окружающая (Env)",
        summary.get("Env Temp"),
        "summary",
        expect=True,
    )
    _add(
        "liquid",
        "coolant",
        "Liquid / coolant",
        "Жидкость / теплоноситель",
        liquid,
        liquid_source or "—",
        expect=liquid_family or liquid is not None,
    )
    # inlet/outlet if ever present
    for key, sid, lab, lab_ru in (
        ("Inlet Temp", "inlet", "Inlet Temp", "Вход (Inlet)"),
        ("Outlet Temp", "outlet", "Outlet Temp", "Выход (Outlet)"),
        ("inlet_temp", "inlet", "Inlet Temp", "Вход (Inlet)"),
        ("outlet_temp", "outlet", "Outlet Temp", "Выход (Outlet)"),
    ):
        raw = summary.get(key)
        if raw is None and isinstance(status, dict):
            raw = status.get(key)
        if raw is not None:
            _add(sid, "coolant", lab, lab_ru, raw, "summary/status", expect=True)

    _add(
        "chip_min",
        "chip",
        "Chip Temp Min",
        "Чипы min",
        summary.get("Chip Temp Min"),
        "summary",
    )
    _add(
        "chip_avg",
        "chip",
        "Chip Temp Avg",
        "Чипы avg",
        summary.get("Chip Temp Avg"),
        "summary",
    )
    _add(
        "chip_max",
        "chip",
        "Chip Temp Max",
        "Чипы max",
        summary.get("Chip Temp Max"),
        "summary",
    )
    # legacy single "Temperature" on some FW (often PCB/case)
    if summary.get("Temperature") not in (None, ""):
        _add(
            "summary_temp",
            "board",
            "Temperature (summary)",
            "Temperature (summary)",
            summary.get("Temperature"),
            "summary",
            expect=True,
        )

    # Per-slot PCB always expected for model board count (structural).
    # Per-slot chip min/avg/max only when DEVS actually provides values —
    # many models/FW never expose them (would show as n/a forever).
    def _slot_chip_ok(v) -> bool:
        fv = _f(v)
        if fv is None:
            return False
        if fv <= 0.05 or fv > 150:
            return False
        return True

    # Model profile: board_chip_temp=False → never list SM chip min/avg/max
    # (M63 typically has no per-slot chip fields — only PCB). If True/None, list
    # only slots that actually have data (no permanent n/a rows).
    model_wants_board_chip = model_sens.get("board_chip_temp")
    any_board_chip = any(
        _slot_chip_ok(v)
        for lst in (board_chip_min, board_chip_max, board_chip_avg)
        for v in (lst or [])
    )
    show_board_chip = (
        False
        if model_wants_board_chip is False
        else any_board_chip
    )

    for i in range(max(0, int(n_boards or 0))):
        pcb = boards[i] if i < len(boards) else None
        cmin = board_chip_min[i] if i < len(board_chip_min) else None
        cmax = board_chip_max[i] if i < len(board_chip_max) else None
        cavg = board_chip_avg[i] if i < len(board_chip_avg) else None
        bid = format_hashboard_id(i, miner_type)
        if model_sens.get("pcb_temp", True) is not False:
            _add(
                f"sm{i}_pcb",
                "board",
                f"{bid} PCB",
                f"{bid} PCB",
                pcb,
                "devs",
                expect=True,
            )
        if show_board_chip and (
            _slot_chip_ok(cmin) or _slot_chip_ok(cavg) or _slot_chip_ok(cmax)
        ):
            _add(
                f"sm{i}_chip_min",
                "board_chip",
                f"{bid} Chip Min",
                f"{bid} чип min",
                cmin,
                "devs",
                expect=False,
            )
            _add(
                f"sm{i}_chip_avg",
                "board_chip",
                f"{bid} Chip Avg",
                f"{bid} чип avg",
                cavg,
                "devs",
                expect=False,
            )
            _add(
                f"sm{i}_chip_max",
                "board_chip",
                f"{bid} Chip Max",
                f"{bid} чип max",
                cmax,
                "devs",
                expect=False,
            )

    _add(
        "psu",
        "psu",
        "PSU temp0",
        "БП temp0",
        psu_temp,
        "get_psu",
        expect=True,
    )

    # board max/min/avg derived
    pcb_vals = [v for v in boards if isinstance(v, (int, float)) and v is not None]
    if pcb_vals:
        _add("board_max", "board", "Boards max (PCB)", "Платы max (PCB)", max(pcb_vals), "derived")
        _add("board_min", "board", "Boards min (PCB)", "Платы min (PCB)", min(pcb_vals), "derived")
        _add(
            "board_avg",
            "board",
            "Boards avg (PCB)",
            "Платы avg (PCB)",
            sum(pcb_vals) / len(pcb_vals),
            "derived",
        )

    return out


def _ipollo_luci_login(
    host: str,
    password: str = "root",
    user: str = "root",
    timeout: float = 4.0,
) -> str | None:
    """
    iPollo LuCI session cookie (sysauth). Default credentials root/root.
    Returns cookie header value or None.
    """
    try:
        import urllib.error
        import urllib.parse
        import urllib.request

        base = f"http://{host}"
        # login form
        data = urllib.parse.urlencode(
            {"luci_username": user, "luci_password": password}
        ).encode()
        req = urllib.request.Request(
            f"{base}/cgi-bin/luci/",
            data=data,
            method="POST",
            headers={"Content-Type": "application/x-www-form-urlencoded"},
        )
        # Don't follow redirects fully — capture Set-Cookie
        class _NoRedir(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *a, **k):
                return None

        opener = urllib.request.build_opener(_NoRedir)
        try:
            resp = opener.open(req, timeout=timeout)
            headers = resp.headers
        except urllib.error.HTTPError as e:
            headers = e.headers
        except Exception:
            return None
        # urllib may store cookies differently — parse Set-Cookie
        sc = headers.get("Set-Cookie") or headers.get("set-cookie") or ""
        m = re.search(r"(sysauth=[^;]+)", sc)
        if m:
            return m.group(1)
        # fallback: CookieJar style
        return None
    except Exception:
        return None


def _ipollo_luci_get_json(
    host: str,
    path: str,
    cookie: str,
    timeout: float = 4.0,
) -> dict | None:
    try:
        import urllib.request

        url = f"http://{host}{path}"
        req = urllib.request.Request(
            url,
            headers={"Cookie": cookie, "Accept": "application/json,text/plain,*/*"},
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read(65536).decode("utf-8", errors="replace").strip()
        if not raw:
            return None
        obj = json.loads(raw)
        return obj if isinstance(obj, dict) else None
    except Exception:
        return None


# SearchFreq :6060 — READ paths we poll. Write/diag paths are never called.
_ANTMINER_6060_POLL_EVERY = (
    "/miner_power",
    "/rate",
    "/readvol",
    "/warning",
    "/miner_status",
)
_ANTMINER_6060_POLL_SLOW = (
    "/ideal_rate",
    "/max_rate",
    "/board_type",
    "/summary",
    "/ee_info",
    "/chip_stat",
    "/asic_stat",
    "/adc",
    "/power-0",
    "/power-1",
    "/power-2",
    "/power-3",
    "/productName",
    "/get_sn",
    "/nonce",
)
_ANTMINER_6060_NEVER = (
    "/fan-<1-99>",
    "/uart-<0-5>",
    "/readreg-<chain>-<asic>-<reg>",
    "/readcorereg-<chain>-<asic>-<reg>",
    "/resetcore-<chain>-<asic>",
    "/clear_find_asic_fail_record",
    "/min_boot_reset",
    "/flush",
    "/set_sn",
)
_ANTMINER_6060_DOWN: dict[str, float] = {}
_ANTMINER_6060_DOWN_TTL = 45.0


def _antminer_6060_get(host: str, path: str, timeout: float = 2.5) -> str | None:
    """
    GET plain text from Bitmain SearchFreqServer (:6060).

    Returns body text on HTTP 200 *and* on HTTP 404/500 (so callers can
    skip an unsupported path). Returns None only when the port is closed
    or the request times out — never follow write/diag paths from here.
    """
    host = str(host or "").strip().split(":")[0]
    if not host:
        return None
    path = path if str(path).startswith("/") else ("/" + str(path))
    url = f"http://{host}:6060{path}"
    try:
        req = urllib.request.Request(
            url,
            headers={
                "User-Agent": "poolheat/1.0",
                "Accept": "text/plain,*/*",
                "Connection": "close",
            },
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.read(262144).decode("utf-8", errors="replace")
    except urllib.error.HTTPError as e:
        try:
            raw = e.read(8192).decode("utf-8", errors="replace")
        except Exception:
            raw = ""
        return raw if raw else f"{e.code} {e.reason}"
    except Exception:
        return None


def _parse_antminer_miner_power(text: str | None) -> float | None:
    """
    Parse SearchFreq `/miner_power` body.
    Examples: ``miner power:3605`` · ``3605`` · ``power=3605W``
    """
    if not text:
        return None
    s = str(text).strip()
    # primary: "miner power:3605"
    m = re.search(r"miner\s*power\s*[:=]\s*([0-9]+(?:\.[0-9]+)?)", s, re.I)
    if m:
        try:
            v = float(m.group(1))
            return v if v > 0 else None
        except (TypeError, ValueError):
            return None
    m = re.search(r"([0-9]+(?:\.[0-9]+)?)\s*W\b", s, re.I)
    if m:
        try:
            v = float(m.group(1))
            return v if v > 0 else None
        except (TypeError, ValueError):
            return None
    # bare integer as only content
    m = re.fullmatch(r"\s*([0-9]{2,5}(?:\.[0-9]+)?)\s*", s)
    if m:
        try:
            v = float(m.group(1))
            # wall watts for ASIC usually 200–15000
            return v if 50 <= v <= 20000 else None
        except (TypeError, ValueError):
            return None
    return None


def _parse_antminer_rate_text(
    text: str | None, unit_hint: str | None = None
) -> float | None:
    """
    /rate · /ideal_rate · /max_rate → always TH/s.

    Accepts ``141.2`` (TH), ``17.2G``, ``rate:150.2 TH/s``.
    Bare numbers follow *unit_hint*: GH/s (L9/Scrypt) → divide by 1000,
    MH/s → /1e6, otherwise TH (S19/S21). Values ≥ 800 without a suffix
    are treated as GH even on SHA miners.
    """
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    obj = _try_parse_json_blob(raw)
    if isinstance(obj, (int, float)):
        raw = str(obj)
    elif isinstance(obj, dict):
        for k in ("rate", "hashrate", "value", "ideal", "max", "ghs", "ths"):
            if obj.get(k) not in (None, ""):
                raw = str(obj.get(k))
                break
    m = re.search(
        r"([0-9]+(?:\.[0-9]+)?)\s*([tTgGmM])(?:\s*H(?:/s)?)?", raw
    )
    if m:
        v = float(m.group(1))
        u = m.group(2).upper()
        if u == "T":
            return v if v > 0 else None
        if u == "G":
            return v / 1000.0 if v > 0 else None
        if u == "M":
            return v / 1e6 if v > 0 else None
    m = re.search(r"([0-9]+(?:\.[0-9]+)?)", raw)
    if not m:
        return None
    v = float(m.group(1))
    if v <= 0:
        return None
    hint = str(unit_hint or "").upper()
    if "MH" in hint or hint in ("M", "J/M", "J/MH"):
        return v / 1e6
    if "GH" in hint or hint in ("G", "J/G", "J/GH"):
        return v / 1000.0
    # Heuristic: 800–80000 without unit → GH/s (mis-scaled SHA or raw L9)
    if v >= 800:
        return v / 1000.0
    return v


def _parse_antminer_miner_status(text: str | None) -> str | None:
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    obj = _try_parse_json_blob(raw)
    if isinstance(obj, dict):
        for k in ("status", "state", "miner_status", "msg"):
            if obj.get(k) not in (None, ""):
                return str(obj.get(k)).strip()[:80]
    line = raw.splitlines()[0].strip()
    line = re.sub(r"^(miner[_\s-]*status|status)\s*[:=]\s*", "", line, flags=re.I)
    return line[:80] if line else None


def _parse_antminer_board_type(text: str | None) -> str | None:
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    obj = _try_parse_json_blob(raw)
    if isinstance(obj, dict):
        for k in ("board_type", "type", "hb", "hash_board"):
            if obj.get(k):
                return str(obj.get(k)).strip()[:64]
    line = raw.splitlines()[0].strip()
    line = re.sub(r"^(board[_\s-]*type|type)\s*[:=]\s*", "", line, flags=re.I)
    if line and len(line) < 80:
        return line
    return None


def _parse_antminer_adc(text: str | None) -> dict | None:
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    obj = _try_parse_json_blob(raw)
    chains: list[dict] = []
    if isinstance(obj, dict):
        rows = obj.get("chain") or obj.get("chains") or obj.get("adc") or obj.get("data")
        if isinstance(rows, list):
            for i, row in enumerate(rows):
                if isinstance(row, dict):
                    chains.append({"chain": row.get("chain", i), **{
                        k: row[k] for k in list(row)[:8] if k != "chain"
                    }})
                elif isinstance(row, (int, float)):
                    chains.append({"chain": i, "adc": float(row)})
    if not chains:
        for m in re.finditer(
            r"(?:chain|ch|adc)\s*(\d+)\s*[:=]\s*([0-9]+(?:\.[0-9]+)?)", raw, re.I
        ):
            chains.append({"chain": int(m.group(1)), "adc": float(m.group(2))})
    if not chains and not obj:
        return {"raw": raw[:1500], "source": "6060/adc"}
    return {"source": "6060/adc", "chains": chains[:8], "raw": raw[:1500]}


def _try_parse_json_blob(text: str | None):
    """Parse JSON object/array, including trailing-junk SearchFreq bodies."""
    if not text:
        return None
    s = str(text).strip()
    if not s or s[0] not in "{[":
        return None
    try:
        return json.loads(s)
    except Exception:
        pass
    try:
        obj, _ = json.JSONDecoder().raw_decode(s)
        return obj
    except Exception:
        return None


def _parse_antminer_warning(text: str | None) -> list[dict]:
    """
    /warning — JSON log of critical alerts (overtemp, fan, voltage, hashrate).
    Accepts list / {warning|error|data|msg: [...] } / plain lines.
    """
    if not text or not str(text).strip():
        return []
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return []
    obj = _try_parse_json_blob(raw)
    items: list = []
    if isinstance(obj, list):
        items = obj
    elif isinstance(obj, dict):
        for k in (
            "warning",
            "warnings",
            "error",
            "errors",
            "data",
            "msg",
            "message",
            "log",
            "logs",
            "list",
        ):
            v = obj.get(k)
            if isinstance(v, list):
                items = v
                break
            if isinstance(v, str) and v.strip():
                items = [v]
                break
        if not items and any(
            obj.get(k) for k in ("code", "msg", "message", "cause", "desc")
        ):
            items = [obj]
    else:
        items = [ln.strip() for ln in raw.splitlines() if ln.strip()]

    out: list[dict] = []
    for it in items[:40]:
        if it in (None, "", [], {}):
            continue
        if isinstance(it, str):
            msg = it.strip()
            if not msg or msg.lower() in ("ok", "none", "null", "[]"):
                continue
            out.append(
                {
                    "code": "6060",
                    "cause": msg[:240],
                    "message": msg[:240],
                    "source": "6060/warning",
                    "hint": "SearchFreq /warning",
                }
            )
            continue
        if not isinstance(it, dict):
            continue
        msg = str(
            it.get("cause")
            or it.get("msg")
            or it.get("message")
            or it.get("desc")
            or it.get("info")
            or it.get("warning")
            or ""
        ).strip()
        code = str(
            it.get("code") or it.get("id") or it.get("type") or it.get("err") or "6060"
        ).strip() or "6060"
        if not msg:
            msg = json.dumps(it, ensure_ascii=False)[:240]
        level = str(it.get("level") or it.get("severity") or "").strip()
        rec = {
            "code": code[:32],
            "cause": msg[:240],
            "message": msg[:240],
            "source": "6060/warning",
            "hint": level or "SearchFreq /warning",
        }
        if it.get("time") or it.get("ts") or it.get("date"):
            rec["ts"] = it.get("time") or it.get("ts") or it.get("date")
        out.append(rec)
    return out


def _parse_antminer_readvol(text: str | None) -> dict | None:
    """
    /readvol — hashboard voltage, PSU feedback, power status.
    Example: ``read current voltage:1300 feedback:12.907188 power status:0``
    """
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    obj = _try_parse_json_blob(raw)
    out: dict = {"raw": raw[:500], "source": "6060/readvol"}
    if isinstance(obj, dict):
        for k, dest in (
            ("voltage", "voltage_mv"),
            ("vol", "voltage_mv"),
            ("feedback", "feedback_v"),
            ("fb", "feedback_v"),
            ("power_status", "power_status"),
            ("powerstatus", "power_status"),
            ("status", "power_status"),
        ):
            if obj.get(k) not in (None, ""):
                out[dest] = obj.get(k)
    m = re.search(r"voltage\s*[:=]\s*([0-9]+(?:\.[0-9]+)?)", raw, re.I)
    if m:
        try:
            out["voltage_mv"] = float(m.group(1))
        except (TypeError, ValueError):
            pass
    m = re.search(r"feedback\s*[:=]\s*([0-9]+(?:\.[0-9]+)?)", raw, re.I)
    if m:
        try:
            out["feedback_v"] = float(m.group(1))
        except (TypeError, ValueError):
            pass
    m = re.search(r"power\s*status\s*[:=]\s*([-+]?\d+)", raw, re.I)
    if m:
        try:
            out["power_status"] = int(m.group(1))
        except (TypeError, ValueError):
            pass
    # chainN:1300 snippets
    chains: list[dict] = []
    for m in re.finditer(
        r"(?:chain|ch|pic)\s*(\d+)\s*[:=]\s*([0-9]+(?:\.[0-9]+)?)", raw, re.I
    ):
        try:
            chains.append({"chain": int(m.group(1)), "voltage_mv": float(m.group(2))})
        except (TypeError, ValueError):
            continue
    if chains:
        out["chains"] = chains
    if (
        out.get("voltage_mv") is None
        and out.get("feedback_v") is None
        and out.get("power_status") is None
        and not chains
    ):
        return None
    return out


def _parse_kv_blob(text: str) -> dict:
    """Loose key:value / key=value extractor for 6060 text summaries."""
    kv: dict = {}
    for m in re.finditer(
        r"([A-Za-z][A-Za-z0-9_ \-]{1,32})\s*[:=]\s*([^\n,;]+)", str(text)
    ):
        k = re.sub(r"\s+", "_", m.group(1).strip().lower())
        v = m.group(2).strip()
        if k and v:
            kv[k[:40]] = v[:80]
    return kv


def _parse_antminer_summary_6060(text: str | None) -> dict | None:
    """/summary — control-board physical sensors (not CGMiner summary)."""
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    obj = _try_parse_json_blob(raw)
    out: dict = {"raw": raw[:2000], "source": "6060/summary"}
    if isinstance(obj, dict):
        out["data"] = {
            str(k)[:40]: obj[k]
            for k in list(obj)[:40]
            if not isinstance(obj[k], (dict, list))
        }
    kv = _parse_kv_blob(raw)
    if kv:
        out["fields"] = kv
    return out if (out.get("data") or out.get("fields")) else out


def _parse_antminer_ee_info(text: str | None) -> dict | None:
    """
    /ee_info — hashboard EEPROM: serials, factory freq/voltage tables.
    """
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    obj = _try_parse_json_blob(raw)
    boards: list[dict] = []
    if isinstance(obj, dict):
        rows = (
            obj.get("boards")
            or obj.get("chain")
            or obj.get("chains")
            or obj.get("data")
            or obj.get("ee")
        )
        if isinstance(rows, list):
            for i, row in enumerate(rows):
                if not isinstance(row, dict):
                    continue
                boards.append(
                    {
                        "slot": row.get("chain", row.get("slot", i)),
                        "pcb_sn": row.get("sn")
                        or row.get("pcb_sn")
                        or row.get("serial"),
                        "freq": row.get("freq") or row.get("frequency"),
                        "voltage": row.get("vol")
                        or row.get("voltage")
                        or row.get("volt"),
                    }
                )
        elif isinstance(rows, dict):
            for k, row in rows.items():
                if not isinstance(row, dict):
                    continue
                boards.append(
                    {
                        "slot": row.get("chain", k),
                        "pcb_sn": row.get("sn") or row.get("pcb_sn"),
                        "freq": row.get("freq"),
                        "voltage": row.get("vol") or row.get("voltage"),
                    }
                )
    # text: "chain0 sn:xxx freq:525 vol:1300"
    if not boards:
        for m in re.finditer(
            r"(?:chain|ch|board|pcb)\s*(\d+)[^\n]{0,160}", raw, re.I
        ):
            chunk = m.group(0)
            rec: dict = {"slot": int(m.group(1))}
            sn = re.search(r"(?:sn|serial)\s*[:=]\s*([A-Za-z0-9._-]{4,})", chunk, re.I)
            if sn:
                rec["pcb_sn"] = sn.group(1)
            fq = re.search(r"freq(?:uency)?\s*[:=]\s*([0-9]+)", chunk, re.I)
            if fq:
                rec["freq"] = int(fq.group(1))
            vl = re.search(r"vol(?:t(?:age)?)?\s*[:=]\s*([0-9]+(?:\.[0-9]+)?)", chunk, re.I)
            if vl:
                rec["voltage"] = float(vl.group(1))
            if len(rec) > 1:
                boards.append(rec)
    out: dict = {"raw": raw[:4000], "source": "6060/ee_info"}
    if boards:
        out["boards"] = boards[:8]
    return out


def _parse_antminer_chip_stat(text: str | None) -> dict | None:
    """
    /chip_stat or /asic_stat — per-ASIC matrix; ``x`` = bad chip («крест»).
    """
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    obj = _try_parse_json_blob(raw)
    chains: list[dict] = []
    if isinstance(obj, dict):
        rows = obj.get("chain") or obj.get("chains") or obj.get("data") or obj.get("asic")
        if isinstance(rows, list):
            for i, row in enumerate(rows):
                if isinstance(row, str):
                    pat = row
                    chains.append(
                        {
                            "chain": i,
                            "pattern": pat[:256],
                            "ok": pat.lower().count("o"),
                            "cross": len(re.findall(r"[xX×]", pat)),
                        }
                    )
                elif isinstance(row, dict):
                    pat = str(row.get("acs") or row.get("stat") or row.get("pattern") or "")
                    chains.append(
                        {
                            "chain": row.get("chain", i),
                            "pattern": pat[:256],
                            "ok": row.get("ok", pat.lower().count("o")),
                            "cross": row.get("x", row.get("cross", len(re.findall(r"[xX×]", pat)))),
                        }
                    )
    if not chains:
        for m in re.finditer(
            r"(?:chain|ch|board)\s*(\d+)\s*[:=]\s*([oxX×\.]+)", raw, re.I
        ):
            pat = m.group(2)
            chains.append(
                {
                    "chain": int(m.group(1)),
                    "pattern": pat[:256],
                    "ok": pat.lower().count("o"),
                    "cross": len(re.findall(r"[xX×]", pat)),
                }
            )
    if not chains:
        # standalone o/x runs (one per line)
        for i, ln in enumerate(raw.splitlines()):
            pat = ln.strip()
            if re.fullmatch(r"[oxX×\.\s]{8,}", pat):
                compact = re.sub(r"\s+", "", pat)
                chains.append(
                    {
                        "chain": i,
                        "pattern": compact[:256],
                        "ok": compact.lower().count("o"),
                        "cross": len(re.findall(r"[xX×]", compact)),
                    }
                )
    if not chains:
        return {"raw": raw[:4000], "source": "6060/chip_stat"}
    total_x = sum(int(c.get("cross") or 0) for c in chains)
    total_ok = sum(int(c.get("ok") or 0) for c in chains)
    return {
        "source": "6060/chip_stat",
        "chains": chains[:8],
        "cross_total": total_x,
        "ok_total": total_ok,
        "chip_count": total_ok + total_x,
        "raw": raw[:4000],
    }


_ANTMINER_6060_SLOW: dict[str, dict] = {}
_ANTMINER_6060_SLOW_TTL = 90.0


def _antminer_6060_slow_get(host: str, path: str, cache_key: str) -> str | None:
    """Cached GET for EEPROM / chip matrix (changes rarely)."""
    now = time.time()
    slot = _ANTMINER_6060_SLOW.get(host) or {}
    ts = float(slot.get(cache_key + "_ts") or 0)
    if cache_key in slot and (now - ts) < _ANTMINER_6060_SLOW_TTL:
        return slot.get(cache_key)
    txt = _antminer_6060_get(host, path, timeout=2.0)
    if txt is None and cache_key == "chip_stat":
        txt = _antminer_6060_get(host, "/asic_stat", timeout=1.5)
    slot[cache_key] = txt
    slot[cache_key + "_ts"] = now
    _ANTMINER_6060_SLOW[host] = slot
    return txt


def _parse_antminer_nonce_text(text: str | None) -> dict | None:
    """
    Best-effort parse of `/nonce` chip table.
    Formats vary by FW — keep raw + extract numeric nonce counts when possible.
    """
    if not text or not str(text).strip():
        return None
    raw = str(text).strip()
    if re.search(r"404 not found|500 server error", raw, re.I):
        return None
    chips: list[dict] = []
    # patterns: "chain0 asic12 nonce:12345" / "0-12:12345" / "nonce[0][12]=123"
    for m in re.finditer(
        r"(?:chain|board|ch)[^\d]*(\d+).*?(?:asic|chip|ic)[^\d]*(\d+).*?"
        r"(?:nonce|n)[^\d]*([0-9]+)",
        raw,
        flags=re.I | re.S,
    ):
        chips.append(
            {
                "chain": int(m.group(1)),
                "asic": int(m.group(2)),
                "nonce": int(m.group(3)),
            }
        )
    if not chips:
        # looser: pairs "12:3456" lines
        for m in re.finditer(
            r"(?:^|[\s,;])(\d{1,3})[:\-](\d{1,3})[=:\s]+(\d{2,})", raw
        ):
            chips.append(
                {
                    "chain": int(m.group(1)),
                    "asic": int(m.group(2)),
                    "nonce": int(m.group(3)),
                }
            )
    out: dict = {"raw": raw[:8000], "source": "6060/nonce"}
    if chips:
        out["chips"] = chips[:2048]
        out["nonce_total"] = sum(int(c.get("nonce") or 0) for c in chips)
        out["chip_count"] = len(chips)
    return out


def _enrich_live_antminer_6060(host: str, body: dict) -> dict:
    """
    Bitmain SearchFreqServer on :6060 (stock / L9 / S19 FW):

      GET /miner_power  → wall watts
      GET /warning      → JSON critical alerts
      GET /readvol      → chain voltage, PSU feedback, power status
      GET /summary      → control-board physical sensors
      GET /ee_info      → hashboard EEPROM (SN, factory freq/volt)
      GET /chip_stat|/asic_stat → per-ASIC o/x matrix («кресты»)
      GET /rate · /ideal_rate · /max_rate · /miner_status · /board_type
      GET /power-0..3 · /adc   (read-only voltage / ADC)
      GET /nonce · /productName · /get_sn

    Write paths (/fan-N, /uart-N, /resetcore-…, /set_sn, /flush, …) are
    never called from the poller.

    Non-fatal — leaves body unchanged when port closed or path unsupported.
    """
    if not host or not isinstance(body, dict):
        return body
    host = str(host).split(":")[0].strip()
    now = time.time()
    down_ts = float(_ANTMINER_6060_DOWN.get(host) or 0)
    if down_ts and (now - down_ts) < _ANTMINER_6060_DOWN_TTL:
        return body
    hw: dict = dict(body.get("antminer_hw") or {}) if isinstance(body.get("antminer_hw"), dict) else {}
    got = False
    unit_hint = str(
        body.get("hashrate_unit") or body.get("efficiency_unit") or ""
    )

    # Probe :6060 via /miner_power. None = port closed / timeout — skip rest.
    ptxt = _antminer_6060_get(host, "/miner_power", timeout=1.5)
    if ptxt is None:
        _ANTMINER_6060_DOWN[host] = now
        return body
    _ANTMINER_6060_DOWN.pop(host, None)
    pw = _parse_antminer_miner_power(ptxt)
    if pw is not None:
        got = True
        body["power"] = round(pw, 1)
        body["power_w"] = round(pw, 1)
        body["power_source"] = "antminer_6060"
        body["power_estimated"] = False
        try:
            th = float(body.get("hashrate_th") or 0)
            if th > 0:
                unit = str(body.get("efficiency_unit") or "J/T").upper()
                if unit in ("J/G", "J/GH"):
                    ev, eu = round(pw / (th * 1000.0), 3), "J/G"
                elif unit in ("J/M", "J/MH"):
                    ev, eu = round(pw / (th * 1e6), 3), "J/M"
                else:
                    ev, eu = round(pw / th, 1), "J/T"
                body["efficiency_value"] = ev
                body["efficiency_unit"] = eu
                body["efficiency_jth"] = round(pw / th, 2)
        except (TypeError, ValueError):
            pass

    # /rate — live hashrate from SearchFreq (fills gaps / L9)
    rtxt = _antminer_6060_get(host, "/rate", timeout=1.2)
    rate_th = _parse_antminer_rate_text(rtxt, unit_hint=unit_hint)
    if rate_th is not None and rate_th > 0:
        got = True
        hw["rate_th"] = rate_th
        body["rate_th"] = rate_th
        if body.get("hashrate_th") in (None, "", 0, 0.0) or (
            isinstance(body.get("hashrate_th"), (int, float))
            and float(body.get("hashrate_th") or 0) <= 0
        ):
            body["hashrate_th"] = rate_th
            body["hashrate_hs"] = rate_th * 1e12

    # /readvol — every poll
    vtxt = _antminer_6060_get(host, "/readvol", timeout=1.5)
    svol = _parse_antminer_readvol(vtxt)
    if svol:
        got = True
        hw["readvol"] = svol
        mv = svol.get("voltage_mv")
        fb = svol.get("feedback_v")
        try:
            if mv is not None:
                mvf = float(mv)
                body["hashboard_voltage_mv"] = mvf
                # 1000–2000 typically mV on PIC
                if 200 <= mvf <= 2500 and body.get("board_voltage") in (None, ""):
                    body["board_voltage"] = round(mvf / 1000.0, 3) if mvf > 80 else mvf
        except (TypeError, ValueError):
            pass
        try:
            if fb is not None:
                fbf = float(fb)
                body["psu_feedback_v"] = fbf
                if body.get("psu_vin") in (None, "") and 8 <= fbf <= 16:
                    body["psu_vin"] = round(fbf, 3)
        except (TypeError, ValueError):
            pass
        if svol.get("power_status") is not None:
            body["psu_status"] = svol.get("power_status")

    # /warning — every poll
    wtxt = _antminer_6060_get(host, "/warning", timeout=1.5)
    warns = _parse_antminer_warning(wtxt)
    if warns:
        got = True
        hw["warnings"] = warns
        body["antminer_warnings"] = warns
        errs = list(body.get("miner_errors") or [])
        seen = {(str(e.get("code")), str(e.get("cause") or e.get("message") or "")) for e in errs}
        for w in warns:
            key = (str(w.get("code") or "6060"), str(w.get("cause") or ""))
            if key in seen:
                continue
            errs.append(w)
            seen.add(key)
        body["miner_errors"] = errs

    # slower / less chatty paths (cached ~90s)
    stxt = _antminer_6060_slow_get(host, "/summary", "summary")
    ssum = _parse_antminer_summary_6060(stxt)
    if ssum:
        hw["summary"] = ssum
        body["antminer_summary"] = ssum.get("fields") or ssum.get("data") or ssum

    etxt = _antminer_6060_slow_get(host, "/ee_info", "ee_info")
    ee = _parse_antminer_ee_info(etxt)
    if ee:
        hw["ee_info"] = ee
        body["antminer_ee"] = ee
        # fill missing PCB SN from EEPROM
        ee_boards = ee.get("boards") if isinstance(ee.get("boards"), list) else []
        if ee_boards and isinstance(body.get("boards_detail"), list):
            by_slot = {}
            for b in ee_boards:
                if isinstance(b, dict) and b.get("slot") is not None:
                    by_slot[int(b["slot"])] = b
            for rec in body["boards_detail"]:
                if not isinstance(rec, dict):
                    continue
                try:
                    sl = int(rec.get("slot"))
                except (TypeError, ValueError):
                    continue
                src = by_slot.get(sl)
                if src and src.get("pcb_sn") and not rec.get("pcb_sn"):
                    rec["pcb_sn"] = src["pcb_sn"]
                if src and src.get("freq") and not rec.get("freq"):
                    rec["freq"] = src["freq"]

    ctxt = _antminer_6060_slow_get(host, "/chip_stat", "chip_stat")
    cstat = _parse_antminer_chip_stat(ctxt)
    if cstat and (cstat.get("chains") or cstat.get("chip_count")):
        hw["chip_stat"] = cstat
        body["antminer_chip_stat"] = cstat
        if cstat.get("cross_total") is not None:
            body["asic_cross"] = cstat.get("cross_total")
        if cstat.get("chip_count") and not body.get("chipmap_hint"):
            body["chipmap_hint"] = {
                "source": "6060/chip_stat",
                "chip_count": cstat.get("chip_count"),
                "cross": cstat.get("cross_total"),
            }

    itxt = _antminer_6060_slow_get(host, "/ideal_rate", "ideal_rate")
    ideal_th = _parse_antminer_rate_text(itxt, unit_hint=unit_hint)
    if ideal_th:
        got = True
        hw["ideal_rate_th"] = ideal_th
        body["ideal_rate_th"] = ideal_th
        if body.get("factory_th") in (None, "", 0):
            body["factory_th"] = ideal_th
        if body.get("tagged_th") in (None, "", 0):
            body["tagged_th"] = ideal_th

    mtxt = _antminer_6060_slow_get(host, "/max_rate", "max_rate")
    max_th = _parse_antminer_rate_text(mtxt, unit_hint=unit_hint)
    if max_th:
        got = True
        hw["max_rate_th"] = max_th
        body["max_rate_th"] = max_th

    mst = _antminer_6060_get(host, "/miner_status", timeout=1.2)
    st = _parse_antminer_miner_status(mst)
    if st:
        got = True
        hw["miner_status"] = st
        body["miner_status_6060"] = st

    btyp = _antminer_6060_slow_get(host, "/board_type", "board_type")
    bt = _parse_antminer_board_type(btyp)
    if bt:
        got = True
        hw["board_type"] = bt
        body["board_type"] = body.get("board_type") or bt
        if not body.get("hash_board"):
            body["hash_board"] = bt

    # /power-0..3 — per-chain voltage (read-only)
    chain_volts: list[dict] = []
    for i in range(4):
        ptxt_i = _antminer_6060_slow_get(host, f"/power-{i}", f"power_{i}")
        if not ptxt_i or re.search(r"404 not found|500 server error", ptxt_i, re.I):
            continue
        parsed = _parse_antminer_readvol(ptxt_i) or {}
        rec = {"chain": i, "raw": str(ptxt_i).strip()[:200]}
        if parsed.get("voltage_mv") is not None:
            rec["voltage_mv"] = parsed["voltage_mv"]
        elif parsed.get("feedback_v") is not None:
            rec["voltage_v"] = parsed["feedback_v"]
        else:
            m = re.search(r"([0-9]+(?:\.[0-9]+)?)", str(ptxt_i))
            if m:
                rec["voltage_mv"] = float(m.group(1))
        chain_volts.append(rec)
    if chain_volts:
        got = True
        hw["chain_voltage"] = chain_volts
        body["chain_voltage"] = chain_volts

    atxt = _antminer_6060_slow_get(host, "/adc", "adc")
    adc = _parse_antminer_adc(atxt)
    if adc:
        got = True
        hw["adc"] = adc
        body["antminer_adc"] = adc

    # product / serial (fill gaps)
    if not body.get("miner_type") or not str(body.get("miner_type")).strip():
        name = _antminer_6060_slow_get(host, "/productName", "productName")
        if name and name.strip() and "not found" not in name.lower():
            body["miner_type"] = name.strip()
            body.setdefault("model_name", name.strip())
    if not body.get("serial"):
        sn = _antminer_6060_slow_get(host, "/get_sn", "get_sn")
        if sn and sn.strip() and "not found" not in sn.lower() and len(sn.strip()) < 64:
            body["serial"] = sn.strip()
    # /nonce — optional chip table (some FW close the socket; cache 90s)
    ntxt = _antminer_6060_slow_get(host, "/nonce", "nonce")
    nparsed = _parse_antminer_nonce_text(ntxt)
    if nparsed:
        got = True
        body["antminer_nonce"] = nparsed
        hw["nonce"] = {
            "nonce_total": nparsed.get("nonce_total"),
            "chip_count": nparsed.get("chip_count"),
            "source": "6060/nonce",
        }
        if nparsed.get("nonce_total") is not None:
            body["nonce_total"] = nparsed.get("nonce_total")
        if nparsed.get("chips") and not body.get("chipmap_hint"):
            body["chipmap_hint"] = {
                "source": "6060/nonce",
                "chip_count": nparsed.get("chip_count"),
            }
    if hw:
        body["antminer_hw"] = hw
    if got:
        body["antminer_6060"] = True
    return body


def _antminer_6060_snapshot_from_live(live: dict | None, *, host: str | None = None) -> dict:
    """Sanitized SearchFreq snapshot for GET /api/miner/antminer6060 (cache only)."""
    live = live if isinstance(live, dict) else {}
    hw = live.get("antminer_hw") if isinstance(live.get("antminer_hw"), dict) else {}
    nonce = live.get("antminer_nonce") if isinstance(live.get("antminer_nonce"), dict) else {}
    power_src = str(live.get("power_source") or "")
    power_w = live.get("power_w") if live.get("power_w") is not None else live.get("power")
    if power_src != "antminer_6060":
        power_w = None
    return {
        "ok": True,
        "available": bool(live.get("antminer_6060")),
        "host": host or live.get("host"),
        "power_w": power_w,
        "power_source": power_src or None,
        "rate_th": live.get("rate_th"),
        "ideal_rate_th": live.get("ideal_rate_th"),
        "max_rate_th": live.get("max_rate_th"),
        "miner_status": live.get("miner_status_6060") or hw.get("miner_status"),
        "board_type": live.get("board_type") or hw.get("board_type"),
        "hashboard_voltage_mv": live.get("hashboard_voltage_mv"),
        "psu_feedback_v": live.get("psu_feedback_v"),
        "psu_status": live.get("psu_status"),
        "asic_cross": live.get("asic_cross"),
        "nonce_total": live.get("nonce_total") or nonce.get("nonce_total"),
        "nonce_chips": nonce.get("chip_count") or (hw.get("nonce") or {}).get("chip_count"),
        "warnings": live.get("antminer_warnings") or hw.get("warnings") or [],
        "chain_voltage": live.get("chain_voltage") or hw.get("chain_voltage"),
        "adc": live.get("antminer_adc") or hw.get("adc"),
        "product": live.get("miner_type") or live.get("model_name"),
        "serial": live.get("serial"),
        "catalog": {
            "polled_every": list(_ANTMINER_6060_POLL_EVERY),
            "polled_slow": list(_ANTMINER_6060_POLL_SLOW),
            "never": list(_ANTMINER_6060_NEVER),
        },
    }


def get_antminer_6060_snapshot(host: str | None = None) -> dict:
    """Read-only 6060 view from live_cache / fleet_live — never hits the miner."""
    want = str(host or "").strip().split(":")[0]
    live = None
    if want:
        try:
            fmap = _load_fleet_live_map(max_age_sec=180.0)
            for key, entry in (fmap or {}).items():
                if not isinstance(entry, dict):
                    continue
                kh = str(key).split(":")[0]
                eh = str(entry.get("host") or "").split(":")[0]
                if kh == want or eh == want:
                    live = entry
                    break
        except Exception:
            live = None
    if not isinstance(live, dict):
        try:
            live = hydrate_live_from_disk(max_age_sec=LIVE_STALE_MAX_SEC) or {}
        except Exception:
            live = {}
        if want and isinstance(live, dict):
            lh = str(live.get("host") or "").split(":")[0]
            if lh and lh != want:
                return {
                    "ok": False,
                    "available": False,
                    "host": want,
                    "error": "no live snapshot for host",
                    "catalog": {
                        "polled_every": list(_ANTMINER_6060_POLL_EVERY),
                        "polled_slow": list(_ANTMINER_6060_POLL_SLOW),
                        "never": list(_ANTMINER_6060_NEVER),
                    },
                }
    return _antminer_6060_snapshot_from_live(live, host=want or None)


def _enrich_live_ipollo(host: str, body: dict, password: str | None = None) -> dict:
    """
    Fill model / fans / temps / serial from iPollo LuCI JSON endpoints.

    Sensor channels are model-aware via miner_model_profiles.json:
    V1 mini = 1 hashboard, 2 chip temps (temp0/temp1), 2 fans (fanspeed0/fanspeed3).
    Non-fatal — returns body unchanged on failure.
    """
    if not host:
        return body
    pw = str(password if password is not None else DEFAULT_API_PASSWORD or "root")
    # try configured password then root/root
    cookie = None
    for user, p in (("root", pw), ("root", "root"), ("admin", pw), ("admin", "admin")):
        cookie = _ipollo_luci_login(host, password=p, user=user)
        if cookie:
            break
    if not cookie:
        return body
    sysinfo = _ipollo_luci_get_json(
        host, "/cgi-bin/luci/admin/ipollo_main/ipollo_sysinfo", cookie
    )
    realtime = _ipollo_luci_get_json(
        host, "/cgi-bin/luci/admin/ipollo_main/ipollo_realtime", cookie
    )
    if isinstance(sysinfo, dict):
        model = str(sysinfo.get("model") or "").strip()
        if model:
            body["miner_type"] = body.get("miner_type") or model
            body["model_name"] = model
        sn = str(sysinfo.get("sn") or sysinfo.get("sn0") or "").strip()
        if sn and sn.upper() != "NULL":
            body["serial"] = sn
        # Per-HB serials when present (V1: sn0 only)
        for i, key in enumerate(("sn0", "sn1", "sn2")):
            v = str(sysinfo.get(key) or "").strip()
            if v and v.upper() != "NULL":
                body.setdefault("board_serials", {})[key] = v
                if i == 0 and not body.get("board_serial"):
                    body["board_serial"] = v
        fw = str(sysinfo.get("fw") or "").strip()
        if fw:
            body["fw_ver"] = fw
        try:
            el = int(float(sysinfo.get("elapsed") or 0))
            if el > 0:
                body["elapsed"] = el
        except (TypeError, ValueError):
            pass
        body["vendor"] = "ipollo"
        body["api_vendor"] = "ipollo"

    # Resolve model profile early so temp/fan keys match hardware map
    prof = None
    try:
        if lookup_model_profile is not None:
            prof = lookup_model_profile(
                vendor="ipollo",
                miner_type=body.get("miner_type"),
                model=body.get("model") if isinstance(body.get("model"), str) else None,
                model_name=body.get("model_name"),
            )
    except Exception:
        prof = None

    # Defaults for V1 mini when profile missing
    temp_keys = ["temp0", "temp1"]
    fan_keys = ["fanspeed0", "fanspeed3"]
    ignore_temps = {"temp2", "temp3"}
    ignore_fans = {"fanspeed1", "fanspeed2"}
    placeholder = -273.2
    expected_boards = 1
    try:
        from miner_models import (  # type: ignore
            profile_fan_keys,
            profile_hashboard_count,
            profile_temp_keys,
            normalize_hardware_map,
        )

        if prof:
            tk = profile_temp_keys(prof)
            fk = profile_fan_keys(prof)
            if tk:
                temp_keys = tk
            if fk:
                fan_keys = fk
            hw = normalize_hardware_map(prof)
            ph = ((hw.get("temps") or {}).get("chip") or {}).get("placeholder")
            if ph is not None:
                try:
                    placeholder = float(ph)
                except (TypeError, ValueError):
                    pass
            ign = (hw.get("poll") or {}).get("ignore_keys") or {}
            if isinstance(ign.get("temps"), list):
                ignore_temps = {str(x) for x in ign["temps"]}
            if isinstance(ign.get("fans"), list):
                ignore_fans = {str(x) for x in ign["fans"]}
            body["model_hardware"] = hw
            try:
                expected_boards = int(profile_hashboard_count(prof) or 1)
            except Exception:
                expected_boards = 1
    except Exception:
        pass

    if isinstance(realtime, dict):
        # hashrate string e.g. 240.2572M
        hr = _parse_hashrate_to_hs(
            realtime.get("hashratecur") or realtime.get("hashrate")
        )
        if hr is not None and hr > 0:
            body["hashrate_hs"] = hr
            body["hashrate_th"] = _hs_to_th(hr)
            body["hashrate_unit"] = (
                "MH/s" if hr < 1e12 else ("GH/s" if hr < 1e15 else "TH/s")
            )
            if hr >= 1e6 and hr < 1e9:
                body["hashrate_unit"] = "MH/s"
            elif hr >= 1e9 and hr < 1e12:
                body["hashrate_unit"] = "GH/s"
            elif hr >= 1e12:
                body["hashrate_unit"] = "TH/s"

        # Temps: only real sensors from model map (not temp2/temp3 placeholders)
        temps: list[float] = []
        temp_readings: list[dict] = []
        for k in temp_keys:
            if k in ignore_temps:
                continue
            try:
                t = float(realtime.get(k))
            except (TypeError, ValueError):
                continue
            # drop absolute-zero / missing placeholders
            if t <= placeholder + 1 or t <= -100:
                continue
            temps.append(t)
            temp_readings.append({"id": k, "c": round(t, 1), "source": "luci_realtime"})
        # Optional aggregate ASC (do not inflate sensor count / boards)
        try:
            t_asc = float(realtime.get("tempasc"))
            if t_asc > -100 and t_asc > placeholder + 1:
                body["temp_asc"] = round(t_asc, 1)
        except (TypeError, ValueError):
            pass
        if temps:
            body["chip_temps"] = [round(t, 1) for t in temps]
            body["chip_avg"] = round(sum(temps) / len(temps), 1)
            body["chip_max"] = round(max(temps), 1)
            body["chip_min"] = round(min(temps), 1)
            body["temp_sensors"] = temp_readings
            # Single hashboard: one boards[] entry with both sensors (not N boards)
            if expected_boards <= 1:
                body["boards"] = [
                    {
                        "id": "HB1",
                        "index": 1,
                        "name": "HB1",
                        "temp": body["chip_avg"],
                        "temp_max": body["chip_max"],
                        "temp_min": body["chip_min"],
                        "temps": [round(t, 1) for t in temps],
                        "hashrate_hs": body.get("hashrate_hs"),
                    }
                ]
                body["board_count"] = 1
                body["board_chip_avg"] = [body["chip_avg"]]
                body["board_chip_max"] = [body["chip_max"]]

        # Fans: only physical channels (V1: fanspeed0 + fanspeed3)
        fans: list[int] = []
        fan_readings: list[dict] = []
        for k in fan_keys:
            if k in ignore_fans:
                continue
            try:
                f = int(float(realtime.get(k) or 0))
            except (TypeError, ValueError):
                continue
            if f > 0:
                fans.append(f)
                fan_readings.append(
                    {"id": k, "rpm": f, "source": "luci_realtime"}
                )
        if fans:
            body["fans"] = fans
            body["fan"] = fans[0]
            # Not PSU fan on iPollo — keep psu_fan unset / alias first chassis fan only
            body["fan_sensors"] = fan_readings
            if len(fans) >= 2:
                body["fan_in"] = fans[0]
                body["fan_out"] = fans[-1]
        try:
            rej = float(realtime.get("rejected") or 0)
            body["rejected"] = rej
        except (TypeError, ValueError):
            pass
    return body


def _cgminer_identity(summary_raw: dict | None, summary: dict | None) -> dict:
    """Extract vendor/model hints from classic CGMiner / BFGMiner / BMMiner / ckbminer."""
    out: dict = {"api_vendor": "cgminer", "vendor": None, "miner_type": None}
    desc = ""
    if isinstance(summary_raw, dict):
        st = summary_raw.get("STATUS")
        if isinstance(st, list) and st and isinstance(st[0], dict):
            desc = str(st[0].get("Description") or "")
    desc_l = desc.lower()
    # Bitmain BMMiner: version.Type = "Antminer L9"
    try:
        ver_raw = miner_cmd({"cmd": "version"}, timeout=3)
        ver = _extract_miner_payload(ver_raw, "VERSION", "version")
        if isinstance(ver, dict):
            mtype = str(ver.get("Type") or ver.get("type") or "").strip()
            if mtype:
                out["miner_type"] = mtype
                out["model_name"] = mtype
            if "antminer" in mtype.lower() or ver.get("BMMiner"):
                out["vendor"] = "antminer"
                out["api_vendor"] = "antminer"
                out["fw_ver"] = str(ver.get("Miner") or ver.get("BMMiner") or "") or None
            if ver.get("BMMiner"):
                out["bmminer"] = str(ver.get("BMMiner"))
    except Exception:
        pass
    # Device name from DEVS later; Device Code from config
    try:
        cfg_raw = miner_cmd({"cmd": "config"}, timeout=3)
        cfg = _extract_miner_payload(cfg_raw, "CONFIG", "config")
        if isinstance(cfg, dict):
            dc = str(cfg.get("Device Code") or "").strip().upper()
            if "IPL" in dc:
                out["vendor"] = "ipollo"
                out["api_vendor"] = "ipollo"
            elif any(x in dc for x in ("INCS", "SGW", "SSM")):
                out["vendor"] = "goldshell"
                out["api_vendor"] = "goldshell"
            out["device_code"] = dc or None
            out["os"] = cfg.get("OS")
    except Exception:
        pass
    if "ipollo" in desc_l:
        out["vendor"] = "ipollo"
        out["api_vendor"] = "ipollo"
    elif "ckbminer" in desc_l or "goldshell" in desc_l:
        out["vendor"] = "goldshell"
        out["api_vendor"] = "goldshell"
    elif "jansson" in desc_l and not out.get("vendor"):
        # Bitmain stock often uses Description "jansson x.y"
        out["vendor"] = out.get("vendor") or "antminer"
        out["api_vendor"] = out.get("api_vendor") or "antminer"
    elif ("cgminer" in desc_l or "bfgminer" in desc_l) and not out.get("vendor"):
        out["vendor"] = "cgminer"
    return out


def _http_json_get(url: str, timeout: float = 4.0) -> dict | list | None:
    try:
        import urllib.request

        req = urllib.request.Request(
            url, headers={"Accept": "application/json,text/plain,*/*"}
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read(262144).decode("utf-8", errors="replace").strip()
        if not raw:
            return None
        obj = json.loads(raw)
        return obj if isinstance(obj, (dict, list)) else None
    except Exception:
        return None


def _fetch_live_goldshell_http(host: str, port: int = 80) -> dict | None:
    """
    Build a live snapshot purely from Goldshell cloud-box HTTP API
    when CGMiner :4028 is down / refused.
    """
    if not host:
        return None
    base = f"http://{host}"
    status = _http_json_get(f"{base}/mcb/status", timeout=5.0)
    if not isinstance(status, dict) or not status.get("model"):
        # not a goldshell cloud-box
        return None
    body: dict = {
        "ok": True,
        "ts": datetime.now().isoformat(timespec="seconds"),
        "host": f"{host}:{port or 4028}",
        "vendor": "goldshell",
        "api_vendor": "goldshell",
        "miner_type": str(status.get("model") or "Goldshell"),
        "model_name": str(status.get("model") or ""),
        "fw_ver": str(status.get("firmware") or "") or None,
        "hardware": str(status.get("hardware") or status.get("mcbversion") or "")
        or None,
        "hashrate_th": 0.0,
        "hashrate_hs": 0.0,
        "hashrate_unit": "MH/s",
        "work_measured": "resume",
        "source": "goldshell-http",
    }
    short = body["model_name"].replace("Goldshell-", "").replace("Goldshell", "").strip()
    if short:
        body["model"] = short
    body = _enrich_live_goldshell(host, body)
    # If pools present and any Alive/active — keep resume; else still online device
    pools = body.get("pools") if isinstance(body.get("pools"), list) else []
    if pools:
        any_up = any(
            str(p.get("status") or "").lower() in ("alive", "true", "1")
            or p.get("active")
            for p in pools
            if isinstance(p, dict)
        )
        # Device online even if pool dead (initialising)
        body["pool_ok"] = bool(any_up)
    try:
        body = _stamp_hashboard_meta(body, None)
    except Exception:
        pass
    try:
        if apply_model_profile_to_live is not None:
            body = apply_model_profile_to_live(body, vendor="goldshell")
    except Exception:
        pass
    try:
        body["work_measured"] = (
            "suspend" if _measured_work_state(body) == "sleep" else "resume"
        )
    except Exception:
        pass
    return body


def _enrich_live_goldshell(host: str, body: dict) -> dict:
    """
    Goldshell cloud-box HTTP API (CKBox / Mini-DOGE / …):
      GET /mcb/status  → model, firmware, hardware
      GET /mcb/setting → MAC name, power plan, temp targets
      GET /mcb/pools   → pool list
    Plus CGMiner stats fans already in body when available.
    """
    if not host:
        return body
    base = f"http://{host}"
    status = _http_json_get(f"{base}/mcb/status", timeout=4.0)
    setting = _http_json_get(f"{base}/mcb/setting", timeout=4.0)
    pools_http = _http_json_get(f"{base}/mcb/pools", timeout=4.0)
    if isinstance(status, dict):
        model = str(status.get("model") or "").strip()
        if model:
            body["miner_type"] = body.get("miner_type") or model
            body["model_name"] = model
            # Goldshell-CKBox → CKBox (raw); profile renames to CK-BOX for UI
            short = model.replace("Goldshell-", "").replace("Goldshell", "").strip()
            if short and not body.get("model"):
                body["model"] = short
        fw = str(status.get("firmware") or "").strip()
        if fw:
            body["fw_ver"] = fw
        hw = str(status.get("hardware") or status.get("mcbversion") or "").strip()
        if hw:
            body["hardware"] = hw
        body["vendor"] = "goldshell"
        body["api_vendor"] = "goldshell"
    if isinstance(setting, dict):
        mac = str(setting.get("name") or "").strip()
        if mac and ":" in mac:
            body["mac"] = mac.lower()
        # power plan string e.g. "800 MHz 0.42 V 50 RPM 50 RPM"
        plan = str(setting.get("manualPowerplan") or "").strip()
        if not plan:
            pps = setting.get("powerplans")
            if isinstance(pps, list) and pps and isinstance(pps[0], dict):
                plan = str(pps[0].get("info") or "").strip()
        if plan:
            body["power_plan"] = plan
            # try extract frequency
            m = re.search(r"(\d+(?:\.\d+)?)\s*MHz", plan, re.I)
            if m and body.get("freq_avg") in (None, "", 0):
                try:
                    body["freq_avg"] = float(m.group(1))
                except (TypeError, ValueError):
                    pass
        tt = setting.get("temp_target") or (
            (setting.get("temp_targets") or [None])[0]
            if isinstance(setting.get("temp_targets"), list)
            else None
        )
        try:
            if tt is not None:
                body["temp_target"] = float(tt)
        except (TypeError, ValueError):
            pass
    if isinstance(pools_http, list) and pools_http:
        pools_out = []
        for p0 in pools_http:
            if not isinstance(p0, dict):
                continue
            pools_out.append(
                {
                    "url": p0.get("url") or p0.get("URL"),
                    "user": p0.get("user") or p0.get("User"),
                    "status": (
                        "Alive"
                        if p0.get("active") or p0.get("legal")
                        else str(p0.get("status") or "Dead")
                    ),
                    "priority": p0.get("pool-priority") or p0.get("priority") or 0,
                    "pass": p0.get("pass"),
                }
            )
        if pools_out and not body.get("pools"):
            body["pools"] = pools_out
        elif pools_out:
            # fill missing urls
            body["pools"] = pools_out
    return body


def _devs_row_hashrate_th(d: dict, vendor: str | None = None) -> float | None:
    """Normalize one CGMiner DEVS row hashrate to TH/s."""
    if not isinstance(d, dict):
        return None
    for key in ("GHS 5s", "GHS av", "GHS 30m", "RT HASHRATE", "HS RT"):
        if d.get(key) not in (None, ""):
            try:
                raw = d[key]
                if isinstance(raw, str):
                    m = re.search(r"([\d.]+)\s*([TGM]?H)", raw, re.I)
                    if m:
                        v = float(m.group(1))
                        u = m.group(2).upper()
                        if u.startswith("T"):
                            return v
                        if u.startswith("G"):
                            return v / 1000.0
                        if u.startswith("M"):
                            return v / 1e6
                v = float(raw)
                if v <= 0:
                    continue
                # bare GHS field is GH/s
                if str(key).upper().startswith("GHS") or v < 50_000:
                    return v / 1000.0
                return v / 1e6
            except (TypeError, ValueError):
                continue
    for key in ("MHS 5s", "MHS av", "MHS 1m", "MHS 5m"):
        if d.get(key) not in (None, ""):
            try:
                v = float(d[key])
            except (TypeError, ValueError):
                continue
            if v <= 0:
                continue
            # Whatsminer-scale raw megahashes
            if v >= 1e5:
                return v / 1e6
            # Goldshell UI shows GH/s but DEVS often puts 1124.45 in MHS
            vend = str(vendor or "").lower()
            if vend in ("goldshell", "cgminer") and v >= 20:
                return v / 1000.0
            return v / 1e6
    return None


def _temp_plausible(tv: float | None) -> bool:
    """Reject absolute-zero placeholders and empty 0.0 board slots."""
    if tv is None:
        return False
    try:
        v = float(tv)
    except (TypeError, ValueError):
        return False
    # 0.0 is almost always "no sensor" on CGMiner/Goldshell/Antminer
    if v <= 0.05 or v >= 200 or v <= -50:
        return False
    return True


def _parse_temp_number(val) -> float | None:
    if val in (None, ""):
        return None
    try:
        if isinstance(val, str):
            s = val.strip()
            # "84.0 °C / 69.6 °C" → first number only here
            m = re.match(r"^[+-]?(\d+(?:\.\d+)?)", s.replace(",", "."))
            if not m:
                return None
            tv = float(m.group(1) if m.lastindex else m.group(0))
        else:
            tv = float(val)
    except (TypeError, ValueError):
        return None
    return tv if _temp_plausible(tv) else None


def _devs_row_temps(d: dict) -> tuple[float | None, float | None]:
    """
    Primary / secondary board temps from one CGMiner DEVS row.

    pyasic Goldshell: ``tstemp-2`` = PCB (primary), often also tstemp-0/1.
    Whatsminer/iPollo: ``Temperature`` + ``Chip Temp Avg``.
    """
    if not isinstance(d, dict):
        return None, None
    # Goldshell (pyasic): hashboards[b_id].temp = board["tstemp-2"]
    tstemps: list[tuple[int, float]] = []
    for key, val in d.items():
        kl = str(key).lower().replace("_", "-")
        m = re.match(r"^tstemp-?(\d+)$", kl)
        if not m:
            continue
        tv = _parse_temp_number(val)
        if tv is not None:
            tstemps.append((int(m.group(1)), tv))
    if tstemps:
        tstemps.sort(key=lambda x: x[0])
        by_i = {i: v for i, v in tstemps}
        # prefer index 2 (pyasic), else highest index, else first
        primary = by_i.get(2) or by_i.get(max(by_i)) or tstemps[0][1]
        secondary = None
        for i in (1, 0, 3, 4):
            if i in by_i and abs(by_i[i] - primary) > 0.15:
                secondary = by_i[i]
                break
        if secondary is None:
            for i, v in tstemps:
                if abs(v - primary) > 0.15:
                    secondary = v
                    break
        return primary, secondary

    # "84.0 °C / 69.6 °C" in one string field
    for key, val in d.items():
        if not isinstance(val, str) or "/" not in val:
            continue
        if "temp" not in str(key).lower() and "°" not in val and "C" not in val:
            continue
        found = re.findall(r"(\d+(?:\.\d+)?)\s*°?\s*C?", val)
        nums = []
        for x in found:
            tv = _parse_temp_number(x)
            if tv is not None:
                nums.append(tv)
        if len(nums) >= 2:
            return nums[0], nums[1]
        if len(nums) == 1:
            return nums[0], None

    primary = None
    extras: list[float] = []
    for key in (
        "Temperature",
        "temp",
        "Temp",
        "temp1",
        "temp2",
        "Temperature2",
        "Chip Temperature",
        "Chip Temp",
        "Chip Temp Avg",
        "Chip Temp Max",
        "temp_pcb",
        "temp_chip",
        "Inlet Temperature",
        "Outlet Temperature",
    ):
        tv = _parse_temp_number(d.get(key))
        if tv is None:
            continue
        if primary is None and key in ("Temperature", "temp", "Temp", "temp1"):
            primary = tv
        else:
            extras.append(tv)
    if primary is None and extras:
        primary = extras.pop(0)
    secondary = None
    for x in extras:
        if primary is None or abs(x - primary) > 0.15:
            secondary = x
            break
    return primary, secondary


def _stamp_hashboard_meta(body: dict, devs: list | None = None) -> dict:
    """Attach vendor board names + per-board hashrate/temps from CGMiner DEVS."""
    if not isinstance(body, dict):
        return body
    vendor = str(body.get("vendor") or body.get("api_vendor") or "").strip()
    style = vendor_hashboard_style(vendor)
    body["hashboard_style"] = {
        "prefix": style.get("prefix"),
        "index_base": style.get("index_base"),
        "api_prefix": style.get("api_prefix"),
        "display": style.get("display"),
    }
    n = 0
    try:
        n = int(body.get("board_count") or 0)
    except (TypeError, ValueError):
        n = 0
    if isinstance(devs, list) and len(devs) > n:
        n = len(devs)
    if n <= 0:
        boards = body.get("boards")
        if isinstance(boards, list):
            n = len(boards)
    n = max(0, min(8, n))
    labels: list[str] = []
    details: list[dict] = []
    board_ths: list[float] = []
    temps: list[float] = []
    temps2: list[float | None] = []
    for i in range(n or 0):
        raw_name = None
        d = None
        if isinstance(devs, list):
            for cand in devs:
                if not isinstance(cand, dict):
                    continue
                nm = str(cand.get("Name") or cand.get("name") or "").strip()
                idx = parse_hashboard_index(nm, style)
                slot = cand.get("Slot")
                asc = cand.get("ASC")
                if idx == i or slot == i or asc == i:
                    d = cand
                    raw_name = nm or None
                    break
            if d is None and i < len(devs) and isinstance(devs[i], dict):
                d = devs[i]
                raw_name = str(d.get("Name") or d.get("name") or "").strip() or None
        label = format_hashboard_id(i, vendor, raw_name=raw_name, style=style)
        labels.append(label)
        th = _devs_row_hashrate_th(d, vendor) if d else None
        t1, t2 = _devs_row_temps(d) if d else (None, None)
        if t1 is None and isinstance(body.get("boards"), list) and i < len(body["boards"]):
            try:
                t1 = float(body["boards"][i])  # type: ignore[index]
            except (TypeError, ValueError):
                t1 = None
        if th is not None:
            board_ths.append(round(th, 4))
        if t1 is not None:
            temps.append(t1)
        temps2.append(t2)
        rec = {
            "slot": i,
            "id": label,
            "name": raw_name or label,
        }
        if th is not None:
            rec["hashrate_th"] = round(th, 4)
        if t1 is not None:
            rec["temp_c"] = round(t1, 1)
        if t2 is not None:
            rec["temp2_c"] = round(t2, 1)
        if isinstance(d, dict):
            for src, dst in (
                ("Accepted", "accepted"),
                ("Rejected", "rejected"),
                ("Hardware Errors", "hw_errors"),
                ("Diff1 Work", "nonces"),
                ("Nonce", "nonces"),
            ):
                if d.get(src) not in (None, ""):
                    try:
                        rec[dst] = int(float(d[src]))
                    except (TypeError, ValueError):
                        pass
        details.append(rec)
    if labels:
        body["board_labels"] = labels
    if details:
        body["boards_detail"] = details
    if board_ths and not body.get("boards_th"):
        body["boards_th"] = board_ths
    # Goldshell (and similar): two temps per board → PCB / chip
    if any(t is not None for t in temps2):
        if not body.get("board_chip_avg") or not any(
            x not in (None, 0, 0.0) for x in (body.get("board_chip_avg") or [])
        ):
            body["board_chip_avg"] = [
                (round(t, 1) if t is not None else None) for t in temps2
            ]
        if not body.get("board_chip_max"):
            body["board_chip_max"] = list(body["board_chip_avg"])
        if not body.get("board_chip_min"):
            body["board_chip_min"] = list(body["board_chip_avg"])
    # Prefer DEVS temps when chip_avg missing or bogus 0.0 (Goldshell)
    need_avg = body.get("chip_avg") in (None, "")
    try:
        if not need_avg and not _temp_plausible(float(body.get("chip_avg"))):
            need_avg = True
    except (TypeError, ValueError):
        need_avg = True
    if temps and need_avg:
        body["chip_avg"] = round(sum(temps) / len(temps), 1)
        body["chip_max"] = round(max(temps), 1)
        body["chip_min"] = round(min(temps), 1)
    # boards[] from DEVS PCB when still empty
    if details and (
        not body.get("boards")
        or not any(
            _temp_plausible(x) if x is not None else False
            for x in (body.get("boards") or [])
        )
    ):
        body["boards"] = [
            (d.get("temp_c") if isinstance(d, dict) else None) for d in details
        ]
        if any(x is not None for x in body["boards"]):
            body["board_count"] = len(body["boards"])
    if n and not body.get("board_count"):
        body["board_count"] = n
    return body


def _antminer_stats_temps(row: dict) -> dict:
    """
    Parse Bitmain BMMiner STATS row temps (pyasic bmminer._get_hashboards).

    L9 / S19 style keys (1-based chain index)::
      temp{i}           — often PCB or sensor 1
      temp2_{i}         — PCB (pyasic → hashboard.temp)
      temp{i}           — chip (pyasic → hashboard.chip_temp) when paired with temp2_
      temp_out_chip_{i} / temp_in_chip_{i}
      temp_out_pcb_{i}  / temp_in_pcb_{i}
      temp_max
    """
    pcb_by: dict[int, float] = {}
    chip_by: dict[int, float] = {}
    loose: list[float] = []
    temp_max = _parse_temp_number(row.get("temp_max"))

    # Pass 1: pyasic-primary keys (temp2_{i} PCB, temp{i} chip)
    for key, val in row.items():
        kl = str(key).lower().strip()
        if kl in ("temp_num", "temp_target", "tempcontrol"):
            continue
        tv = _parse_temp_number(val)
        if tv is None:
            continue
        # temp2_1 → PCB chain 1 (pyasic hashboard.temp)
        m = re.match(r"^temp2_(\d+)$", kl)
        if m:
            idx = int(m.group(1)) - 1
            if idx >= 0:
                pcb_by[idx] = tv
            continue
        # temp1 / temp2 / temp3 → chip when temp2_* present (pyasic chip_temp)
        m = re.match(r"^temp(\d+)$", kl)
        if m:
            idx = int(m.group(1)) - 1
            if idx >= 0 and idx not in chip_by:
                chip_by[idx] = tv
            continue
        loose.append(tv)

    # Pass 2: L9-style temp_out_chip_* / temp_out_pcb_* — fill gaps only
    # (do not overwrite pyasic temp2_* / temp{i})
    for key, val in row.items():
        kl = str(key).lower().strip()
        tv = _parse_temp_number(val)
        if tv is None:
            continue
        m = re.match(r"^temp_(out|in)_(chip|pcb)_(\d+)$", kl)
        if not m:
            continue
        idx = int(m.group(3)) - 1
        if idx < 0:
            continue
        if m.group(2) == "chip":
            if idx not in chip_by:
                chip_by[idx] = tv
        else:
            if idx not in pcb_by:
                pcb_by[idx] = tv

    # If we have both temp{i} and temp2_{i}, pyasic: temp=PCB (temp2_), chip=temp{i}
    # Our chip_by already has temp{i}; pcb_by has temp2_{i}. Good.

    # If only temp{i} without temp2_, treat as PCB (common on some FW)
    if pcb_by and chip_by:
        pass
    elif chip_by and not pcb_by:
        pcb_by = dict(chip_by)
        chip_by = {}

    return {
        "pcb_by": pcb_by,
        "chip_by": chip_by,
        "temp_max": temp_max,
        "loose": loose,
    }


def _cgminer_apply_stats(body: dict) -> dict:
    """
    Pull fans / frequency / temps / chain rates from CGMiner/BMMiner ``stats``.

    Temp mapping follows pyasic:
      Antminer BMMiner — STATS[1] temp2_{i} (PCB), temp{i} (chip)
      Avalon — handled via estats separately when present
    """
    try:
        stats_raw = miner_cmd({"cmd": "stats"}, timeout=6)
    except Exception as e:
        print(f"[live] stats: {e}")
        # Avalon often needs estats instead
        try:
            stats_raw = miner_cmd({"cmd": "estats"}, timeout=6)
            print("[live] stats failed; using estats", flush=True)
        except Exception as e2:
            print(f"[live] estats: {e2}")
            return body
    if not isinstance(stats_raw, dict) or _asic_status_is_error(stats_raw):
        return body
    rows = stats_raw.get("STATS") or stats_raw.get("stats") or []
    if not isinstance(rows, list):
        return body
    fans: list[int] = []
    board_ths: list[float] = []
    freq = None
    ant_type = None
    pcb_temps: list[float | None] = []
    chip_temps: list[float | None] = []
    all_chip: list[float] = []
    all_pcb: list[float] = []
    temp_max_global: float | None = None

    for row in rows:
        if not isinstance(row, dict):
            continue
        # Bitmain identity row (no STATS id)
        t = str(row.get("Type") or "").strip()
        if t and "antminer" in t.lower():
            ant_type = t
            body["vendor"] = "antminer"
            body["api_vendor"] = "antminer"
            body["miner_type"] = body.get("miner_type") or t
            body["model_name"] = body.get("model_name") or t
            if row.get("Miner"):
                body["fw_ver"] = str(row.get("Miner"))
        # Avalon MM ID blob sometimes nested as string
        mm = row.get("MM ID0") or row.get("MMID0")
        if isinstance(mm, str) and mm.strip().startswith("{"):
            try:
                mm = json.loads(mm)
            except Exception:
                mm = None
        if isinstance(mm, dict):
            # Avalon env
            env_t = _parse_temp_number(mm.get("Temp") or mm.get("temp"))
            if env_t is not None and body.get("env") in (None, "", 0, 0.0):
                body["env"] = env_t
            # MTmax / Tmax arrays → chip
            for key in ("MTmax", "Tmax", "TMax", "MTavg", "Tavg", "TAvg"):
                arr = mm.get(key)
                if not isinstance(arr, list):
                    continue
                for i, x in enumerate(arr):
                    tv = _parse_temp_number(x)
                    if tv is None:
                        continue
                    while len(chip_temps) <= i:
                        chip_temps.append(None)
                    if key in ("MTmax", "Tmax", "TMax"):
                        chip_temps[i] = tv
                        all_chip.append(tv)
                    else:
                        if chip_temps[i] is None:
                            chip_temps[i] = tv
                        all_pcb.append(tv)
            for key in ("HBITemp", "HBOTemp"):
                tv = _parse_temp_number(mm.get(key))
                if tv is None:
                    continue
                if key == "HBITemp" and body.get("inlet") in (None, ""):
                    body["inlet"] = tv
                if key == "HBOTemp" and body.get("outlet") in (None, ""):
                    body["outlet"] = tv

        # fan0..fanN (Whatsminer/iPollo) and fan1.. (Bitmain)
        for i in range(0, 12):
            for key in (f"fan{i}", f"Fan{i}", f"fan_speed{i}"):
                if key in row and row.get(key) not in (None, "", 0, "0"):
                    try:
                        fv = int(float(row[key]))
                        if fv > 0:
                            fans.append(fv)
                    except (TypeError, ValueError):
                        pass

        # Structured Antminer chain temps (pyasic)
        parsed = _antminer_stats_temps(row)
        if parsed["temp_max"] is not None:
            temp_max_global = (
                max(temp_max_global, parsed["temp_max"])
                if temp_max_global is not None
                else parsed["temp_max"]
            )
        if parsed["pcb_by"] or parsed["chip_by"]:
            max_i = max(
                list(parsed["pcb_by"].keys()) + list(parsed["chip_by"].keys()) + [-1]
            )
            for i in range(max_i + 1):
                while len(pcb_temps) <= i:
                    pcb_temps.append(None)
                while len(chip_temps) <= i:
                    chip_temps.append(None)
                if i in parsed["pcb_by"]:
                    pcb_temps[i] = parsed["pcb_by"][i]
                    all_pcb.append(parsed["pcb_by"][i])
                if i in parsed["chip_by"]:
                    chip_temps[i] = parsed["chip_by"][i]
                    all_chip.append(parsed["chip_by"][i])
        else:
            # flat fallback (non-Bitmain) — only plausible temps
            for key, val in row.items():
                kl = str(key).lower()
                if not kl.startswith("temp") and "temp" not in kl:
                    continue
                if kl in ("temp_num", "temp_target"):
                    continue
                tv = _parse_temp_number(val)
                if tv is not None:
                    all_chip.append(tv)

        # Bitmain per-chain rate (GH/s like 5.27, or MH/s like 5670)
        for i in range(0, 9):
            found = False
            for key in (
                f"chain_rate{i}",
                f"chain_rateideal{i}",
                f"chain_hashrate{i}",
                f"chain_ghz{i}",
            ):
                if row.get(key) in (None, ""):
                    continue
                try:
                    raw = row[key]
                    if isinstance(raw, str):
                        raw = raw.replace(",", ".").split()[0]
                    v = float(raw)
                    if v <= 0:
                        continue
                    # ≥100 → MH/s (L9 ~5.6 GH/s per board often sent as 5600)
                    th = v / 1e6 if v >= 100 else v / 1000.0
                    board_ths.append(round(th, 6))
                    found = True
                except (TypeError, ValueError, IndexError):
                    continue
                break
            if found:
                continue
        if freq is None:
            for key in ("frequency", "Frequency", "freq", "freq1", "GHS 30m"):
                if row.get(key) not in (None, ""):
                    try:
                        freq = float(row[key])
                        # freq1=1300 is MHz, not GHS
                        if key.startswith("freq") and freq > 100:
                            body["freq_avg"] = freq
                        break
                    except (TypeError, ValueError):
                        pass
        # power if present (some stock FW)
        for key in ("power", "Power", "power_realtime", "chain_power"):
            if row.get(key) not in (None, "") and body.get("power") in (None, "", 0):
                try:
                    pw = float(row[key])
                    if pw > 10:
                        body["power"] = pw
                        body["power_source"] = "meter"
                        body["power_estimated"] = False
                except (TypeError, ValueError):
                    pass

    if fans and not body.get("fans"):
        seen: set[int] = set()
        uniq: list[int] = []
        for f in fans:
            if f not in seen:
                seen.add(f)
                uniq.append(f)
        body["fans"] = uniq[:8]
        body["fan"] = uniq[0]
        body["psu_fan"] = uniq[0]

    # Prefer chip sensors for chip_*; PCB for boards[]
    chip_vals = [t for t in all_chip if _temp_plausible(t)]
    pcb_vals = [t for t in all_pcb if _temp_plausible(t)]
    # treat 0.0 chip_avg as missing (Goldshell bug)
    cur_avg = body.get("chip_avg")
    try:
        cur_avg_f = float(cur_avg) if cur_avg not in (None, "") else None
    except (TypeError, ValueError):
        cur_avg_f = None
    need_chip = cur_avg_f is None or not _temp_plausible(cur_avg_f)

    if chip_vals and need_chip:
        body["chip_avg"] = round(sum(chip_vals) / len(chip_vals), 1)
        body["chip_max"] = round(
            max(chip_vals + ([temp_max_global] if temp_max_global else [])), 1
        )
        body["chip_min"] = round(min(chip_vals), 1)
    elif pcb_vals and need_chip:
        body["chip_avg"] = round(sum(pcb_vals) / len(pcb_vals), 1)
        body["chip_max"] = round(
            max(pcb_vals + ([temp_max_global] if temp_max_global else [])), 1
        )
        body["chip_min"] = round(min(pcb_vals), 1)
    elif temp_max_global is not None and need_chip:
        body["chip_avg"] = temp_max_global
        body["chip_max"] = temp_max_global
        body["chip_min"] = temp_max_global

    if temp_max_global is not None:
        try:
            cm = float(body.get("chip_max") or 0)
        except (TypeError, ValueError):
            cm = 0
        if temp_max_global > cm:
            body["chip_max"] = temp_max_global

    # Per-board arrays for UI (PCB as boards[], chip as board_chip_*)
    n_slots = max(len(pcb_temps), len(chip_temps), len(board_ths), 0)
    if n_slots > 0:
        while len(pcb_temps) < n_slots:
            pcb_temps.append(None)
        while len(chip_temps) < n_slots:
            chip_temps.append(None)
        # boards[] = PCB (or chip if no PCB)
        boards_out = []
        bca, bcmn, bcmx = [], [], []
        for i in range(n_slots):
            pcb = pcb_temps[i]
            chip = chip_temps[i]
            boards_out.append(round(pcb, 1) if pcb is not None else (
                round(chip, 1) if chip is not None else None
            ))
            if chip is not None:
                bca.append(round(chip, 1))
                bcmn.append(round(chip, 1))
                bcmx.append(round(chip, 1))
            elif pcb is not None:
                bca.append(round(pcb, 1))
                bcmn.append(round(pcb, 1))
                bcmx.append(round(pcb, 1))
            else:
                bca.append(None)
                bcmn.append(None)
                bcmx.append(None)
        if any(x is not None for x in boards_out):
            body["boards"] = boards_out
            body["board_count"] = len(boards_out)
        if any(x is not None for x in bca):
            body["board_chip_avg"] = bca
            body["board_chip_min"] = bcmn
            body["board_chip_max"] = bcmx

    if board_ths and not body.get("boards_th"):
        body["boards_th"] = board_ths
        if not body.get("board_count"):
            body["board_count"] = len(board_ths)
    if freq is not None and body.get("freq_avg") in (None, "", 0):
        body["freq_avg"] = freq
    if ant_type and not body.get("model_display"):
        body["model_name"] = ant_type
    return body


def _fetch_live_direct() -> dict:
    # summary/status: support both Msg-dict and classic SUMMARY/STATUS sections
    try:
        summary_raw = miner_cmd({"cmd": "summary"})
    except Exception as e:
        # Goldshell cloud-box often exposes live only via HTTP /mcb/*
        host_only = str(_asic_target()[0] or HOST_MINER or "").split(":")[0]
        gs = _fetch_live_goldshell_http(host_only, _asic_target()[1])
        if isinstance(gs, dict) and gs.get("ok"):
            print(f"[live] cgminer summary failed ({e}); goldshell HTTP ok", flush=True)
            _mark_miner_live_ok()
            return gs
        raise RuntimeError(f"summary: {e}") from e
    # CGMiner error payload → raise clearly
    if _asic_status_is_error(summary_raw):
        st = summary_raw.get("STATUS") if isinstance(summary_raw, dict) else None
        msg = ""
        if isinstance(st, list) and st and isinstance(st[0], dict):
            msg = str(st[0].get("Msg") or st[0].get("Description") or "")
        raise RuntimeError(f"summary: {msg or 'ASIC error'}")
    summary = _extract_miner_payload(summary_raw, "SUMMARY", "summary")
    if not summary and isinstance(summary_raw, dict):
        # still nothing usable
        summary = {}
    cg_ident = _cgminer_identity(summary_raw, summary)

    try:
        status_raw = miner_cmd({"cmd": "status"})
    except Exception as e:
        # status missing on some FW — non-fatal
        print(f"[live] status: {e}")
        status_raw = {}
    status = _extract_miner_payload(status_raw, "STATUS", "status")
    if not isinstance(status, dict):
        status = {}

    # classic SUMMARY uses "Temperature" instead of Chip Temp *
    if summary.get("Chip Temp Max") in (None, "") and summary.get("Temperature") not in (
        None,
        "",
    ):
        try:
            t = float(summary.get("Temperature"))
            summary.setdefault("Chip Temp Max", t)
            summary.setdefault("Chip Temp Avg", t)
            summary.setdefault("Chip Temp Min", t)
        except (TypeError, ValueError):
            pass

    # devs may return error object while miner is suspended — non-fatal
    devs: list = []
    try:
        devs_raw = miner_cmd({"cmd": "devs"})
        if isinstance(devs_raw, dict):
            d = devs_raw.get("DEVS") or devs_raw.get("devs")
            if isinstance(d, list):
                devs = d
            elif not d:
                # some FW nest under Msg
                msg = devs_raw.get("Msg")
                if isinstance(msg, dict):
                    d2 = msg.get("DEVS") or msg.get("devs")
                    if isinstance(d2, list):
                        devs = d2
    except Exception as e:
        print(f"[live] devs: {e}")
    # Classic CGMiner pools (iPollo / Avalon / …)
    pools_live: list = []
    try:
        pools_raw = miner_cmd({"cmd": "pools"}, timeout=4)
        if isinstance(pools_raw, dict):
            pr = pools_raw.get("POOLS") or pools_raw.get("pools")
            if isinstance(pr, list):
                for p0 in pr:
                    if not isinstance(p0, dict):
                        continue
                    pools_live.append(
                        {
                            "url": p0.get("URL") or p0.get("Stratum URL") or p0.get("url"),
                            "user": p0.get("User") or p0.get("user"),
                            "status": p0.get("Status") or p0.get("status"),
                            "accepted": p0.get("Accepted"),
                            "rejected": p0.get("Rejected"),
                            "stratum": p0.get("Stratum Active"),
                            "priority": p0.get("Priority"),
                        }
                    )
    except Exception as e:
        print(f"[live] pools: {e}")
    raw_errors = _fetch_miner_errors_raw()

    # PSU: temp0 (°C), fan_speed (rpm), Vin/Iin/Pin — never fail whole live poll
    psu_temp = None
    psu_fan = None
    psu_pin = None
    psu_vin = None  # PowerVin (input V) — Tools name
    psu_iin = None  # PowerIin (input A)
    psu_model = None
    psu: dict = {}
    try:
        psu_raw = miner_cmd({"cmd": "get_psu"}, timeout=3)
        psu = _extract_miner_payload(psu_raw, "PSU", "psu")
        if not psu and isinstance(psu_raw, dict):
            psu = psu_raw.get("Msg") if isinstance(psu_raw.get("Msg"), dict) else {}
        if isinstance(psu, dict) and psu:
            psu_temp = _f(psu.get("temp0"))
            psu_fan = _f(psu.get("fan_speed"))
            psu_pin = _f(psu.get("pin"))  # often watts as string
            psu_vin = _normalize_psu_vin(psu.get("vin") or psu.get("Vin"))
            psu_iin = _normalize_psu_iin(psu.get("iin") or psu.get("Iin"))
            psu_model = psu.get("model") or psu.get("name")
    except Exception as e:
        print(f"[psu] get_psu failed: {e}")

    # Liquid temp: status.liquid_temp missing on many liquid FW → API v3
    v3_msg = None
    liquid = _extract_liquid_temp(status, summary, psu)
    if liquid is None:
        v3_msg = _fetch_v3_device_msg()
        liquid = _extract_liquid_temp(status, summary, psu, v3_msg=v3_msg)

    # Fill Vin/Iin from v3 power{} if get_psu missing / odd units
    if psu_vin is None or psu_iin is None:
        try:
            if v3_msg is None:
                v3_msg = _fetch_v3_device_msg()
            pwr = (
                v3_msg.get("power")
                if isinstance(v3_msg, dict) and isinstance(v3_msg.get("power"), dict)
                else None
            )
            if isinstance(pwr, dict):
                if psu_vin is None:
                    psu_vin = _normalize_psu_vin(pwr.get("vin") or pwr.get("Vin"))
                if psu_iin is None:
                    psu_iin = _normalize_psu_iin(pwr.get("iin") or pwr.get("Iin"))
                if psu_pin is None:
                    psu_pin = _f(pwr.get("pin") or pwr.get("Pin"))
                if psu_temp is None:
                    psu_temp = _f(pwr.get("temp0"))
                if psu_fan is None:
                    psu_fan = _f(pwr.get("fanspeed") or pwr.get("fan_speed"))
        except Exception:
            pass

    # Hashboard count: live DEVS / v3 board-num / model map (M63=4, M60S=3, …)
    miner_type_s: str | None = None
    board_num_hint: int | None = None
    try:
        ident = get_miner_identity_cached(force=False)
        if isinstance(ident, dict):
            miner_type_s = (
                str(ident.get("miner_type") or "").strip() or None
            )
            try:
                bn = int(ident.get("board_num") or 0)
                if bn > 0:
                    board_num_hint = bn
            except (TypeError, ValueError):
                pass
    except Exception:
        pass
    # CGMiner / iPollo / Antminer: identity from Type / Device Code
    if isinstance(cg_ident, dict):
        if not miner_type_s and cg_ident.get("miner_type"):
            miner_type_s = str(cg_ident.get("miner_type")).strip() or None
        if not miner_type_s and cg_ident.get("vendor") == "ipollo":
            miner_type_s = "iPollo"
        elif not miner_type_s and cg_ident.get("device_code"):
            miner_type_s = str(cg_ident.get("device_code")).strip() or None
    if isinstance(devs, list) and devs and isinstance(devs[0], dict):
        dname = str(devs[0].get("Name") or "").strip()
        if dname and (
            not miner_type_s
            or miner_type_s in ("iPollo", "cgminer")
        ):
            # e.g. Name=VX → iPollo VX family
            if (cg_ident or {}).get("vendor") == "ipollo":
                miner_type_s = f"iPollo {dname}".strip()
            elif not miner_type_s:
                miner_type_s = dname
    n_devs_live = len(devs) if isinstance(devs, list) else 0
    hb_layout = resolve_hashboard_layout(
        miner_type_s,
        n_devs=n_devs_live,
        board_num=board_num_hint,
    )
    n_boards = int(hb_layout.get("boards") or 4)
    model_profile: dict | None = None
    if resolve_miner_model is not None:
        try:
            model_profile = resolve_miner_model(
                miner_type_s,
                n_devs=n_devs_live,
                board_num=board_num_hint,
            )
        except Exception:
            model_profile = hb_layout.get("profile") if isinstance(hb_layout, dict) else None
    elif isinstance(hb_layout, dict) and isinstance(hb_layout.get("profile"), dict):
        model_profile = hb_layout.get("profile")

    boards: list[float | None] = []
    board_chip_min: list[float | None] = []
    board_chip_max: list[float | None] = []
    board_chip_avg: list[float | None] = []
    upfreq: list[int] = []
    factory_parts: list[float] = []
    for i in range(n_boards):
        if i < len(devs) and isinstance(devs[i], dict):
            drow = devs[i]
            # pyasic-compatible: Goldshell tstemp-2, Whatsminer Temperature, …
            t_pcb, t_chip = _devs_row_temps(drow)
            if t_pcb is None:
                t_pcb = _parse_temp_number(drow.get("Temperature"))
            boards.append(round(t_pcb, 1) if t_pcb is not None else None)
            cmin = _f(drow.get("Chip Temp Min"))
            cmax = _f(drow.get("Chip Temp Max"))
            cavg = _f(drow.get("Chip Temp Avg"))
            if t_chip is not None:
                if cavg is None or not _temp_plausible(cavg):
                    cavg = t_chip
                if cmin is None or not _temp_plausible(cmin):
                    cmin = t_chip
                if cmax is None or not _temp_plausible(cmax):
                    cmax = t_chip
            board_chip_min.append(cmin if _temp_plausible(cmin) else None)
            board_chip_max.append(cmax if _temp_plausible(cmax) else None)
            board_chip_avg.append(cavg if _temp_plausible(cavg) else None)
            try:
                upfreq.append(int(drow.get("Upfreq Complete", 0) or 0))
            except (TypeError, ValueError):
                upfreq.append(0)
            try:
                fg = float(drow.get("Factory GHS") or 0)
                if fg > 0:
                    factory_parts.append(fg)
            except (TypeError, ValueError):
                pass
        else:
            # layout slot without DEVS row (suspend) — null, not fake 0 pad
            boards.append(None)
            board_chip_min.append(None)
            board_chip_max.append(None)
            board_chip_avg.append(None)
            upfreq.append(0)

    mode = summary.get("Power Mode") or status.get("power_mode")
    mode_norm = mode.strip().lower() if isinstance(mode, str) else str(mode)

    with _state_lock:
        pct_cmd = _state.get("power_pct_cmd")
        lim_cmd = _state.get("power_limit_cmd")
        mode_cmd = _state.get("mode_cmd")
        work_cmd = _state.get("work_cmd")
        work_cmd_ts = _state.get("work_cmd_ts")
        last_write = _state.get("last_write")

    hash_pct = status.get("hash_percent")
    try:
        hash_pct_num = float(hash_pct) if hash_pct not in (None, "") else None
    except (TypeError, ValueError):
        hash_pct_num = None

    hs = summary.get("Hash Stable")
    hs_int = 1 if str(hs).lower() in ("true", "1") else 0

    # Hashrate sources (priority):
    #  1) Bitmain "RT HASHRATE": "18.58 GH/s" / "AV HASHRATE"
    #  2) GHS 5s / GHS av  (Bitmain bare GH/s number)
    #  3) Whatsminer HS RT / MHS* (large raw MHS count or "240.2572M")
    rate_field = None
    mhs_raw = None
    for key in (
        "RT HASHRATE",
        "AV HASHRATE",
        "THEORY HASHRATE",
        "HS RT",
        "GHS 5s",
        "GHS 30m",
        "GHS av",
        "MHS 5s",
        "MHS 1m",
        "MHS 5m",
        "MHS av",
    ):
        if summary.get(key) not in (None, ""):
            rate_field = key
            mhs_raw = summary.get(key)
            break
    hashrate_hs = _parse_hashrate_to_hs(mhs_raw)
    hashrate_th = None
    is_bare = isinstance(mhs_raw, (int, float)) or (
        isinstance(mhs_raw, str)
        and re.match(r"^[+-]?\d+(\.\d+)?([eE][+-]?\d+)?$", str(mhs_raw).strip())
    )
    # Bitmain GHS* keys: bare number is GH/s (e.g. 18.57)
    is_ghs_field = bool(rate_field and str(rate_field).upper().startswith("GHS"))
    is_ant = str((cg_ident or {}).get("vendor") or "").lower() in (
        "antminer",
        "bitmain",
    )
    if hashrate_hs is not None:
        if is_bare and (is_ghs_field or (is_ant and hashrate_hs < 1e5)):
            # bare GH/s → H/s
            hashrate_hs = float(mhs_raw) * 1e9
            hashrate_th = hashrate_hs / 1e12
        elif is_bare:
            # Whatsminer-style MHS count → TH/s = n / 1e6
            if hashrate_hs >= 1e5:
                hashrate_th = hashrate_hs / 1e6
                hashrate_hs = hashrate_th * 1e12
            else:
                hashrate_th = (
                    hashrate_hs / 1e6 if hashrate_hs > 100 else _hs_to_th(hashrate_hs)
                )
        else:
            # unit suffix path ("18.58 GH/s", "240.2572M")
            hashrate_th = _hs_to_th(hashrate_hs)

    power_limit = _f(summary.get("Power Limit"))
    factory_ghs = None
    try:
        fg = summary.get("Factory GHS")
        if fg is not None and float(fg) > 0:
            factory_ghs = float(fg)
    except (TypeError, ValueError):
        factory_ghs = None
    if factory_ghs is None and factory_parts:
        factory_ghs = sum(factory_parts)

    # Only real get_error_code entries — no Hash Stable soft-alerts
    miner_errors = _resolve_miner_errors(
        raw_errors,
        hashrate_th=hashrate_th,
        power_limit=power_limit,
        factory_ghs=factory_ghs,
    )

    # ASIC Events table (LuCI status) — separate from get_error_code
    miner_events: list[dict] = []
    try:
        miner_events = _fetch_miner_events_luci(force=False)
    except Exception as e:
        print(f"[live] miner events: {e}")

    # Catalog of all temperature sensors available for this miner / model
    temps = _build_temp_sensors_catalog(
        summary=summary,
        status=status,
        liquid=liquid,
        liquid_source=(
            "v3"
            if liquid is not None
            and status.get("liquid_temp") in (None, "")
            and summary.get("Liquid Temp") in (None, "")
            else ("status" if status.get("liquid_temp") not in (None, "") else "summary")
        ),
        boards=boards,
        board_chip_min=board_chip_min,
        board_chip_max=board_chip_max,
        board_chip_avg=board_chip_avg,
        psu_temp=psu_temp,
        miner_type=miner_type_s,
        n_boards=n_boards,
    )

    body = {
        "ok": True,
        "ts": datetime.now().isoformat(timespec="seconds"),
        "host": f"{HOST_MINER}:{PORT_MINER}",
        "liquid": liquid,
        "liquid_source": (
            "v3"
            if liquid is not None
            and status.get("liquid_temp") in (None, "")
            and summary.get("Liquid Temp") in (None, "")
            else ("status" if status.get("liquid_temp") not in (None, "") else None)
        ),
        "env": summary.get("Env Temp"),
        "chip_min": summary.get("Chip Temp Min"),
        "chip_avg": summary.get("Chip Temp Avg"),
        "chip_max": summary.get("Chip Temp Max"),
        "boards": boards,
        "board_chip_min": board_chip_min,
        "board_chip_max": board_chip_max,
        "board_chip_avg": board_chip_avg,
        "temps": temps,
        "upfreq": upfreq,
        "board_count": n_boards,
        "board_chart_slots": list(hb_layout.get("chart") or [0, 2]),
        "board_layout_key": hb_layout.get("model_key"),
        "board_layout_note": hb_layout.get("note"),
        "miner_type": miner_type_s,
        "model": model_profile,
        "power": summary.get("Power"),
        "mode": mode,
        "mode_norm": mode_norm,
        "mineroff": status.get("mineroff"),
        "mineroff_reason": status.get("mineroff_reason"),
        "power_limit": summary.get("Power Limit"),
        "power_limit_set": status.get("power_limit_set"),
        "power_pct_reported": hash_pct_num,
        "power_pct_cmd": pct_cmd,
        "power_limit_cmd": lim_cmd,
        "mode_cmd": mode_cmd,
        "work_cmd": work_cmd,
        "work_cmd_ts": work_cmd_ts,
        # measured from miner API (for UI); work_cmd = last successful command
        "work_measured": (
            "suspend"
            if _measured_work_state(
                {
                    "mineroff": status.get("mineroff"),
                    "mode": mode,
                    "mode_norm": mode_norm,
                    "power": summary.get("Power"),
                    "hashrate_th": hashrate_th,
                }
            )
            == "sleep"
            else "resume"
        ),
        "mode_measured": mode_norm,
        "power_limit_measured": (
            _f(status.get("power_limit_set"))
            if _f(status.get("power_limit_set")) is not None
            else _f(summary.get("Power Limit"))
        ),
        "last_write": last_write,
        "freq_avg": summary.get("freq_avg"),
        "hashrate_th": hashrate_th,
        "hashrate_hs": hashrate_hs,
        "hashrate_unit": (
            "TH/s"
            if hashrate_th is not None and hashrate_th >= 0.1
            else (
                "GH/s"
                if hashrate_hs is not None and 1e8 <= hashrate_hs < 1e12
                else (
                    "MH/s"
                    if hashrate_hs is not None and hashrate_hs >= 1e5
                    else "H/s"
                )
            )
        ),
        "mhs_rt": (
            summary.get("RT HASHRATE")
            or summary.get("HS RT")
            or summary.get("MHS 5s")
            or summary.get("GHS 5s")
        ),
        "mhs_1m": summary.get("MHS 1m"),
        "mhs_av": summary.get("MHS av") or summary.get("GHS av"),
        "hash_stable": summary.get("Hash Stable"),
        "hash_stable_i": hs_int,
        "elapsed": summary.get("Elapsed"),
        "uptime": summary.get("Uptime"),
        "psu_temp": psu_temp,
        # optional hydro inlet/outlet when firmware exposes them
        "inlet": _f(
            summary.get("Inlet Temp")
            or summary.get("inlet_temp")
            or status.get("Inlet Temp")
            or status.get("inlet_temp")
        ),
        "outlet": _f(
            summary.get("Outlet Temp")
            or summary.get("outlet_temp")
            or status.get("Outlet Temp")
            or status.get("outlet_temp")
        ),
        "psu_fan": psu_fan,
        "psu_pin": psu_pin,
        "psu_vin": psu_vin,  # PowerVin V (input)
        "psu_iin": psu_iin,  # PowerIin A (input)
        "psu_model": psu_model,
        "miner_errors": miner_errors,
        "miner_events": miner_events,
        "pools": pools_live or None,
        "dry_run": bool(DRY_RUN),
        "policy": get_policy_status(),
    }
    # lifecycle status (starting / stopping / tuning / running / stopped)
    try:
        rs = mining_run_status(body)
        body["run_status"] = rs.get("key")
        body["run_status_ru"] = rs.get("label_ru")
        body["run_status_en"] = rs.get("label_en")
    except Exception:
        body["run_status"] = None
    # Vendor / API dialect
    if isinstance(cg_ident, dict):
        if cg_ident.get("vendor"):
            body["vendor"] = cg_ident.get("vendor")
        if cg_ident.get("api_vendor"):
            body["api_vendor"] = cg_ident.get("api_vendor")
        if cg_ident.get("device_code"):
            body["device_code"] = cg_ident.get("device_code")
    host_only = str(_asic_target()[0] or HOST_MINER or "").split(":")[0].strip()
    # stamp actual polled host on body (multi-fleet)
    try:
        th, tp = _asic_target()
        body["host"] = f"{th}:{tp}"
    except Exception:
        pass
    vendor_l = str(body.get("vendor") or body.get("api_vendor") or "").lower()
    type_l = str(miner_type_s or body.get("miner_type") or "").lower()
    # CGMiner stats → fans / freq (Goldshell, Avalon, …)
    try:
        if vendor_l in (
            "goldshell",
            "ipollo",
            "cgminer",
            "avalon",
            "antminer",
            "bitmain",
        ) or (
            isinstance(cg_ident, dict)
            and cg_ident.get("api_vendor")
            in ("cgminer", "goldshell", "ipollo", "antminer")
        ):
            body = _cgminer_apply_stats(body)
        # stamp antminer model from identity if stats didn't
        if isinstance(cg_ident, dict) and cg_ident.get("vendor") == "antminer":
            body["vendor"] = "antminer"
            body["api_vendor"] = "antminer"
            if cg_ident.get("miner_type"):
                body["miner_type"] = cg_ident.get("miner_type")
                body["model_name"] = cg_ident.get("model_name") or cg_ident.get(
                    "miner_type"
                )
            if cg_ident.get("fw_ver") and not body.get("fw_ver"):
                body["fw_ver"] = cg_ident.get("fw_ver")
    except Exception as e:
        print(f"[live] cgminer stats: {e}")
    # iPollo LuCI enrichment (model V1 mini, fans, precise temps)
    try:
        if vendor_l in ("ipollo",) or type_l.startswith("ipollo"):
            body = _enrich_live_ipollo(
                host_only,
                body,
                password=DEFAULT_API_PASSWORD,
            )
    except Exception as e:
        print(f"[live] ipollo enrich: {e}")
    # Goldshell cloud-box HTTP (/mcb/status|setting|pools)
    try:
        if (
            vendor_l in ("goldshell", "cgminer")
            or "goldshell" in type_l
            or "ckbox" in type_l
            or "ckb" in type_l
        ):
            body = _enrich_live_goldshell(host_only, body)
    except Exception as e:
        print(f"[live] goldshell enrich: {e}")
    # Vendor hashboard names (SM0 / CH1 / CPB0 / HB1) + Goldshell per-CPB temps
    try:
        body = _stamp_hashboard_meta(
            body, devs if isinstance(devs, list) else None
        )
    except Exception as e:
        print(f"[live] hashboard meta: {e}")
    # Model profile: trade name + power estimate when ASIC omits wall power
    try:
        if apply_model_profile_to_live is not None:
            body = apply_model_profile_to_live(
                body, vendor=body.get("vendor") or body.get("api_vendor")
            )
    except Exception as e:
        print(f"[live] model profile: {e}")
    # Antminer SearchFreqServer :6060 — real wall power / nonces (after profile
    # so measured power wins over J/TH estimate)
    try:
        if (
            vendor_l in ("antminer", "bitmain")
            or "antminer" in type_l
            or body.get("bmminer")
            or type_l.startswith("l9")
            or type_l.startswith("s19")
            or type_l.startswith("s21")
        ):
            body = _enrich_live_antminer_6060(host_only, body)
    except Exception as e:
        print(f"[live] antminer 6060: {e}")
    # refresh work_measured after enrichments
    try:
        body["work_measured"] = (
            "suspend" if _measured_work_state(body) == "sleep" else "resume"
        )
    except Exception:
        pass
    _mark_miner_live_ok()
    return body




def fetch_live() -> dict:
    """
    Live snapshot for HTTP serve: only from miner-poller live_cache.
    Direct ASIC TCP is used only when this process IS the python miner-poller
    (``--miner-poller`` / no Go binary) — never from the UI/HTTP process.
    """
    # Python poller child: we are the ASIC owner → direct poll.
    argv = " ".join(sys.argv)
    if "--miner-poller" in argv or "--asic-poller" in argv:
        return _fetch_live_direct()
    live = hydrate_live_from_disk(max_age_sec=LIVE_STALE_MAX_SEC)
    if isinstance(live, dict) and live.get("ok"):
        return live
    with _cache_lock:
        if isinstance(_cache, dict) and _cache.get("ok"):
            return dict(_cache)
    raise RuntimeError(
        "no live_cache from miner-poller (serve does not open ASIC TCP)"
    )


def _measured_work_state(live: dict) -> str:
    """
    Actual mining state from miner API (NOT last work_cmd).
    Primary signals: status.mineroff + hashrate.

    Important: ``mineroff=false`` means the miner claims ON (starting / tuning /
    running) — even at low residual watts. Never treat that as Suspend or the
    UI skips Suspend as «already suspend» and never shows «Останавливается».

    Residual board power after power_off with mineroff=true is Suspend.
    Returns sleep/suspend · resume/mining
    """
    mo = live.get("mineroff")
    mo_s = str(mo).strip().lower() if mo is not None else ""
    p = _f(live.get("power"))
    h = _f(live.get("hashrate_th"))
    hs = _f(live.get("hashrate_hs"))
    # BTC ASICs: ≥1 TH/s. ETH/ETC (iPollo V1 mini …): ≥10 MH/s in H/s.
    hashing = (h is not None and h >= 1.0) or (
        hs is not None and hs >= 1e7
    )  # 10 MH/s

    # API says miner off → Suspend, unless it is actually hashing
    if mo_s in ("true", "1", "yes"):
        return "resume" if hashing else "sleep"

    # mineroff false / 0 / no → miner claims ON (warmup, upfreq, mining)
    if mo_s in ("false", "0", "no"):
        return "resume"

    mode = str(live.get("mode_norm") or live.get("mode") or "").lower()
    if "sleep" in mode or mode in ("off", "power_off"):
        return "resume" if hashing else "sleep"

    # no mineroff field — fall back to hash / power
    if hashing:
        return "resume"
    if p is not None and p >= 200:
        return "resume"
    if p is not None and p < 50 and not hashing:
        return "sleep"
    return "resume" if hashing else "sleep"


def _infer_work_state(live: dict) -> str:
    """resume | sleep — measured state for history bands / UI badge."""
    return _measured_work_state(live)


def _fmt_last_share_time(v) -> str:
    """Whatsminer Last Share Time: 0 → Never; else unix or elapsed."""
    if v is None or v == "" or v == 0 or v == "0":
        return "Never"
    try:
        n = float(v)
    except (TypeError, ValueError):
        s = str(v).strip()
        return s if s else "Never"
    if n <= 0:
        return "Never"
    # absolute unix seconds
    if n > 1_000_000_000:
        try:
            return datetime.fromtimestamp(n).strftime("%d.%m.%Y %H:%M:%S")
        except Exception:
            return str(int(n))
    # relative seconds since last share
    sec = int(n)
    if sec < 60:
        return f"{sec}s ago"
    if sec < 3600:
        return f"{sec // 60}m ago"
    if sec < 86400:
        return f"{sec // 3600}h ago"
    return f"{sec // 86400}d ago"


def _normalize_pool_row(p: dict, idx: int = 0) -> dict:
    """Map Whatsminer POOLS[] entry → UI row (hash2cash-style columns)."""
    active = p.get("Stratum Active")
    if active is None:
        active = p.get("stratum_active")
    if isinstance(active, str):
        active = active.strip().lower() in ("true", "1", "yes")
    else:
        active = bool(active)

    lst_raw = p.get("Last Share Time", p.get("last_share_time"))
    diff = p.get("Stratum Difficulty", p.get("Difficulty", p.get("difficulty")))
    try:
        diff_f = float(diff) if diff not in (None, "") else None
    except (TypeError, ValueError):
        diff_f = None

    def _i(key_a, key_b=None, default=0):
        v = p.get(key_a)
        if v is None and key_b:
            v = p.get(key_b)
        try:
            return int(float(v)) if v not in (None, "") else default
        except (TypeError, ValueError):
            return default

    pool_n = p.get("POOL", p.get("pool", idx + 1))
    try:
        pool_n = int(pool_n)
    except (TypeError, ValueError):
        pool_n = idx + 1

    return {
        "pool": pool_n,
        "url": p.get("URL") or p.get("url") or "—",
        "active": active,
        "user": p.get("User") or p.get("user") or "—",
        "status": p.get("Status") or p.get("status") or "—",
        "difficulty": diff_f,
        "getworks": _i("Getworks", "getworks"),
        "accepted": _i("Accepted", "accepted"),
        "rejected": _i("Rejected", "rejected"),
        "stale": _i("Stale", "stale"),
        "discarded": _i("Discarded", "discarded"),
        "lst": lst_raw,
        "lst_label": _fmt_last_share_time(lst_raw),
        "priority": _i("Priority", "priority", default=idx),
        "rejected_pct": _f(
            p["Pool Rejected%"]
            if "Pool Rejected%" in p
            else p.get("rejected_pct")
        ),
        "stale_pct": _f(
            p["Pool Stale%"] if "Pool Stale%" in p else p.get("stale_pct")
        ),
    }


_pools_cache_lock = threading.Lock()
_pools_cache: dict | None = None
_pools_cache_ts = 0.0
_POOLS_CACHE_TTL = 15.0


def fetch_mining_pools(*, force: bool = False) -> dict:
    """
    Mining pool list + share stats from Whatsminer `pools` command.

    Always via miner-poller IPC (miner_read_req). Cached briefly.
    """
    global _pools_cache, _pools_cache_ts
    now = time.time()
    with _pools_cache_lock:
        if (
            not force
            and _pools_cache is not None
            and (now - _pools_cache_ts) < _POOLS_CACHE_TTL
        ):
            out = dict(_pools_cache)
            out["cached"] = True
            return out

    try:
        # miner_cmd → poller read IPC when poller alive
        raw = miner_cmd({"cmd": "pools"}, timeout=12)
    except Exception as e:
        return {
            "ok": False,
            "error": str(e),
            "pools": [],
            "host": f"{HOST_MINER}:{PORT_MINER}",
            "ts": datetime.now().isoformat(timespec="seconds"),
            "transport": (
                "go-miner-poller" if miner_poller_process_alive() else "direct"
            ),
        }

    pools_raw = None
    if isinstance(raw, dict):
        pools_raw = raw.get("POOLS") or raw.get("pools")
        if pools_raw is None:
            msg = raw.get("Msg")
            if isinstance(msg, list):
                pools_raw = msg
            elif isinstance(msg, dict) and isinstance(msg.get("POOLS"), list):
                pools_raw = msg["POOLS"]
    if not isinstance(pools_raw, list):
        pools_raw = []

    pools = []
    for i, p in enumerate(pools_raw):
        if isinstance(p, dict):
            pools.append(_normalize_pool_row(p, i))

    # active first, then pool number
    pools.sort(key=lambda r: (0 if r.get("active") else 1, r.get("pool") or 99))

    coin_type = ""
    try:
        # LuCI form field — not available on TCP `pools` status
        coin_type = fetch_miner_coin_type()
    except Exception:
        coin_type = ""

    body = {
        "ok": True,
        "pools": pools,
        "count": len(pools),
        "coin_type": coin_type,
        "host": f"{HOST_MINER}:{PORT_MINER}",
        "ts": datetime.now().isoformat(timespec="seconds"),
        "cached": False,
    }
    with _pools_cache_lock:
        _pools_cache = dict(body)
        _pools_cache_ts = now
    return body


def _infer_upfreq_ok(live: dict) -> int | None:
    """1 = all boards Upfreq Complete, 0 = tuning (any board still 0)."""
    up = live.get("upfreq")
    if not isinstance(up, (list, tuple)) or not up:
        return None
    try:
        vals = [int(x) for x in up]
    except (TypeError, ValueError):
        return None
    # any board not complete → still tuning
    return 1 if all(v == 1 for v in vals) else 0


def _sample_outdoor_c() -> float | None:
    """Outdoor °C from Open-Meteo cache (refresh if TTL expired)."""
    try:
        w = fetch_weather_current(force=False)
        if not w or w.get("enabled") is False:
            return None
        if w.get("ok") or w.get("stale"):
            return _f(w.get("temp_c"))
    except Exception:
        pass
    return None


def _sample_eff_jt(power, hashrate_th) -> float | None:
    """
    J/TH = W / (TH/s).
    Undefined (no hash, div-by-zero, offline ramp) → 0 for clean charts.
    """
    p = _f(power)
    h = _f(hashrate_th)
    if p is None and h is None:
        return 0.0
    if p is None:
        p = 0.0
    if h is None or h <= 0.05:
        return 0.0
    if p <= 0:
        return 0.0
    try:
        return round(p / h, 3)
    except Exception:
        return 0.0


def _temp_fields_from_live(live: dict) -> dict:
    """
    All temperatures that can be charted (settings gear list).
    PCB boards, chip global + per-slot, PSU, inlet/outlet, outdoor.
    """
    boards = live.get("boards") or []
    bcm = live.get("board_chip_min") or []
    bca = live.get("board_chip_avg") or []
    bcx = live.get("board_chip_max") or []
    out: dict = {
        "liquid": _f(live.get("liquid")),
        "env": _f(live.get("env")),
        "outdoor_c": _sample_outdoor_c(),
        "chip_min": _f(live.get("chip_min")),
        "chip_avg": _f(live.get("chip_avg")),
        "chip_max": _f(live.get("chip_max")),
        "psu_temp": _f(live.get("psu_temp")),
        "inlet": _f(live.get("inlet")),
        "outlet": _f(live.get("outlet")),
    }
    # inlet/outlet may only appear in temps catalog
    for trow in live.get("temps") or []:
        if not isinstance(trow, dict):
            continue
        tid = str(trow.get("id") or "")
        if tid in ("inlet", "outlet") and out.get(tid) is None:
            out[tid] = _f(trow.get("value"))
    pcb_vals: list[float] = []
    for i in range(4):
        bv = _f(boards[i] if i < len(boards) else None)
        out[f"board{i}"] = bv
        if bv is not None and bv > 0.05:
            pcb_vals.append(bv)
        out[f"sm{i}_chip_min"] = _f(bcm[i] if i < len(bcm) else None)
        out[f"sm{i}_chip_avg"] = _f(bca[i] if i < len(bca) else None)
        out[f"sm{i}_chip_max"] = _f(bcx[i] if i < len(bcx) else None)
    out["board_max"] = max(pcb_vals) if pcb_vals else None
    return out


def live_to_sample(live: dict) -> dict:
    lim_set = live.get("power_limit_set")
    try:
        lim_set_f = float(lim_set) if lim_set not in (None, "") else None
    except (TypeError, ValueError):
        lim_set_f = None
    now = time.time()
    online = 1 if live.get("ok") is not False else 0
    power = _f(live.get("power"))
    hashrate_th = _f(live.get("hashrate_th"))
    row = {
        "ts": now,
        "ts_iso": datetime.now().isoformat(timespec="seconds"),
        **_temp_fields_from_live(live),
        "power": power,
        "power_limit": _f(live.get("power_limit")),
        "power_limit_set": lim_set_f,
        "power_pct_cmd": _f(live.get("power_pct_cmd")),
        "freq": _f(live.get("freq_avg")),
        "hashrate_th": hashrate_th,
        "mode": live.get("mode"),
        "hash_stable": live.get("hash_stable_i", 0),
        "online": online,
        "work_state": _infer_work_state(live) if online else None,
        "upfreq_ok": _infer_upfreq_ok(live) if online else None,
        # always store a number for chart (0 = undefined / no hash)
        "eff_jt": _sample_eff_jt(power, hashrate_th) if online else 0.0,
    }
    return row


def offline_sample(err: str | None = None) -> dict:
    """Marker sample when miner is unreachable from monitor."""
    now = time.time()
    temps = {c: None for c in HISTORY_TEMP_COLUMNS}
    # weather is independent of miner link
    temps["outdoor_c"] = _sample_outdoor_c()
    return {
        "ts": now,
        "ts_iso": datetime.now().isoformat(timespec="seconds"),
        **temps,
        "power": None,
        "power_limit": None,
        "power_limit_set": None,
        "power_pct_cmd": None,
        "freq": None,
        "hashrate_th": None,
        "mode": None,
        "hash_stable": None,
        "online": 0,
        "work_state": None,
        "upfreq_ok": None,
        "eff_jt": None,
    }


def _f(v):
    if v is None or v == "":
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def _miner_cmd_result(resp) -> tuple[bool, str]:
    """Parse Whatsminer write response → (ok, message)."""
    if resp is None:
        return False, "empty response from miner"
    if not isinstance(resp, dict):
        return True, str(resp)

    # Encrypted / opaque blob without STATUS — treat as ok (can't decode further)
    if "STATUS" not in resp and "status" not in resp and "Msg" not in resp and "msg" not in resp:
        if "enc" in resp or "data" in resp:
            return True, ""
        return True, ""

    status = resp.get("STATUS", resp.get("status"))
    msg = resp.get("Msg", resp.get("msg", ""))
    desc = resp.get("Description", resp.get("description", ""))

    # STATUS can be list of dicts: [{"STATUS":"E","Msg":"..."}]
    if isinstance(status, list) and status:
        first = status[0]
        if isinstance(first, dict):
            s = str(first.get("STATUS") or first.get("status") or "").upper()
            msg = first.get("Msg") or first.get("msg") or msg
            desc = first.get("Description") or first.get("description") or desc
            status = s
        else:
            status = str(status[0]).upper()
    elif status is not None:
        status = str(status).upper()

    if isinstance(msg, dict):
        # rare: Msg is payload object on read cmds
        msg_s = json.dumps(msg, ensure_ascii=False)[:200]
    else:
        msg_s = str(msg or "").strip()

    desc_s = str(desc or "").strip()
    text = msg_s or desc_s or ""

    if status in ("E", "F", "N", "ERROR", "FAIL", "FAILED"):
        return False, text or f"miner STATUS={status}"

    # Some firmwares put errors only in Msg while STATUS is S
    low = text.lower()
    err_tokens = (
        "error",
        "fail",
        "invalid",
        "denied",
        "reject",
        "low_hash",
        "low hash",
        "not support",
        "permission",
        "over max",
    )
    if any(t in low for t in err_tokens) and low not in ("ok", "success"):
        return False, text

    return True, text if text.lower() not in ("ok", "success") else ""


def _record_write(action: str, value, resp, *, warning: str | None = None) -> dict:
    """Persist last write + raise if miner rejected command."""
    ok, msg = _miner_cmd_result(resp)
    entry = {
        "ts": datetime.now().isoformat(timespec="seconds"),
        "action": action,
        "value": value,
        "ok": ok,
        "error": None if ok else (msg or "miner rejected command"),
        "msg": msg or None,
    }
    with _state_lock:
        _state["last_write"] = entry
        _state["last_write_result"] = resp
        # Only sticky-cmd on successful writes — failed Suspend must not leave
        # UI stuck on «Останавливается» forever.
        if ok:
            if action == "mode":
                _state["mode_cmd"] = value
            elif action == "working":
                _state["work_cmd"] = value
                _state["work_cmd_ts"] = time.time()
            elif action == "power_pct":
                _state["power_pct_cmd"] = value
            elif action == "power_limit":
                _state["power_limit_cmd"] = value
        _save_state()
    # Soft invalidate: keep last-good for instant TG /status; also patch
    # commanded fields so miner card reflects the write before next poll.
    with _cache_lock:
        if isinstance(_cache, dict) and _cache.get("ok") and ok:
            if action == "mode" and value is not None:
                _cache["mode"] = value
                _cache["mode_norm"] = str(value).strip().lower()
                _cache["mode_measured"] = _cache["mode_norm"]
                _cache["mode_cmd"] = value
            elif action == "working" and value is not None:
                v = str(value).strip().lower()
                # Do NOT overwrite measured mineroff/work — wait for next live poll.
                # Only stamp commanded work_cmd for lifecycle "starting/stopping".
                _cache["work_cmd"] = value
                _cache["work_cmd_ts"] = time.time()
            elif action == "power_pct" and value is not None:
                _cache["power_pct_cmd"] = value
            elif action == "power_limit" and value is not None:
                try:
                    w = float(value)
                    _cache["power_limit_cmd"] = value
                    _cache["power_limit_set"] = w
                    _cache["power_limit_measured"] = w
                except (TypeError, ValueError):
                    pass
            _cache["last_write"] = entry
        elif isinstance(_cache, dict):
            _cache["last_write"] = entry
    _invalidate_cache(hard=False)
    if not ok:
        # Expand laconic Whatsminer msgs so UI/TG get actionable text
        err = entry["error"] or "miner rejected command"
        low = str(err).lower()
        if "can't access write" in low or "cant access write" in low:
            err = (
                "can't access write cmd — API записи закрыт. "
                "WhatsMinerTool/web могут работать, а TCP :4028 write — нет, "
                "пока не смените API-пароль в WhatsMinerTool (можно вернуть admin) "
                "и укажете тот же пароль в poolheat Settings → Miner."
            )
        elif "enc json load" in low:
            err = (
                "enc json load err — неверный API-пароль "
                "(майнер не расшифровал privileged-команду)."
            )
        entry["error"] = err
        with _state_lock:
            _state["last_write"] = entry
            _save_state()
        raise RuntimeError(err)
    out = {
        "ok": True,
        "action": action,
        "value": value,
        "response": resp,
        "msg": msg or None,
    }
    if warning:
        out["warning"] = warning
    return out


def _live_power_limit_w(live: dict | None = None) -> float | None:
    """Configured power limit (prefer power_limit_set; summary Power Limit is 0 in Suspend)."""
    try:
        live = live if isinstance(live, dict) else fetch_live()
    except Exception:
        return None
    lim = _f(live.get("power_limit_measured"))
    if lim is None:
        lim = _f(live.get("power_limit_set"))
    if lim is None:
        lim = _f(live.get("power_limit"))
    return lim


def apply_set(action: str, value, password: str) -> dict:
    global _cache, _cache_ts
    action = (action or "").strip().lower()
    password = password or DEFAULT_API_PASSWORD

    # Optional multi-miner target (fleet context menu): value={host,vendor,port,…}
    target_host = None
    if isinstance(value, dict):
        target_host = str(value.get("host") or value.get("ip") or "").strip() or None

    # No write if active ASIC is offline — except targeted reboot/restart by host
    # (iPollo/Goldshell may still accept LuCI/HTTP reboot when :4028 is down).
    _skip_online_gate = bool(
        target_host
        and action
        in (
            "reboot",
            "reboot_asic",
            "system_reboot",
            "restart",
            "restart_miner",
            "restart_btminer",
            "btminer_restart",
            "restart_cgminer",
        )
    )
    if not _skip_online_gate:
        if not miner_is_online(max_age_sec=_MINER_ONLINE_MAX_AGE_SEC, probe=True):
            raise RuntimeError(
                "ASIC offline · write skipped (read недоступен — команда не отправлялась)"
            )

    if action == "mode":
        v = str(value).strip().lower()
        # Power Mode only: low / normal / high
        cmd_map = {
            "low": "set_low_power",
            "normal": "set_normal_power",
            "high": "set_high_power",
        }
        if v not in cmd_map:
            raise ValueError("Power Mode must be low|normal|high (use action=working for suspend|resume)")
        # skip if already on this mode (mode change restarts mining)
        try:
            live = live_snapshot(max_age_sec=LIVE_STALE_MAX_SEC)
            cur = str(live.get("mode_norm") or live.get("mode") or "").strip().lower()
            if cur == v:
                return {
                    "ok": True,
                    "skipped": True,
                    "action": "mode",
                    "value": v,
                    "msg": f"mode already {v}",
                }
        except Exception:
            pass
        resp = miner_write_cmd({"cmd": cmd_map[v]}, password)
        out = _record_write("mode", v, resp)
        out["cmd"] = cmd_map[v]
        if isinstance(resp, dict) and resp.get("transport"):
            out["transport"] = resp.get("transport")
        return out

    if action in ("working", "working_mode", "work", "mining"):
        v = str(value).strip().lower().replace(" ", "_")
        # Mining Control: Suspend Mining / Resume Mining (Whatsminer power_off / power_on)
        aliases = {
            "sleep": "sleep",
            "suspend": "sleep",
            "suspend_mining": "sleep",
            "power_off": "sleep",
            "resume": "resume",
            "resume_mining": "resume",
            "power_on": "resume",
        }
        if v not in aliases:
            raise ValueError("Mining Control must be sleep|suspend|resume")
        stored = aliases[v]
        cmd_map = {
            "sleep": "power_off",
            "resume": "power_on",
        }
        miner_cmd_name = cmd_map[stored]
        # skip only when solidly already in target state (not mid-transition)
        try:
            live = live_snapshot(max_age_sec=LIVE_STALE_MAX_SEC)
            have = str(live.get("work_measured") or _live_work(live) or "").lower()
            want = "suspend" if stored == "sleep" else "resume"
            mo = str(live.get("mineroff") or "").strip().lower()
            h = _f(live.get("hashrate_th"))
            hashing = h is not None and h >= 1.0
            # sticky command: if user commanded the opposite recently, do not skip
            cmd = str(live.get("work_cmd") or "").strip().lower()
            cmd_side = (
                "suspend"
                if cmd in ("sleep", "suspend", "power_off", "off")
                else (
                    "resume"
                    if cmd in ("resume", "mining", "power_on", "on")
                    else None
                )
            )
            if want == "suspend":
                # solid stop: API says off and no hash (not just measured label)
                solid_off = mo in ("true", "1", "yes") and not hashing
                # if commanded resume (starting) — always allow Suspend to cancel
                if solid_off and cmd_side != "resume" and have in (
                    "sleep",
                    "suspend",
                ):
                    return {
                        "ok": True,
                        "skipped": True,
                        "action": "working",
                        "value": stored,
                        "msg": "already suspend",
                    }
            elif want == "resume":
                solid_on = hashing or mo in ("false", "0", "no")
                if solid_on and cmd_side != "suspend" and have in (
                    "resume",
                    "mining",
                ):
                    return {
                        "ok": True,
                        "skipped": True,
                        "action": "working",
                        "value": stored,
                        "msg": "already resume",
                    }
        except Exception:
            pass
        resp = miner_write_cmd({"cmd": miner_cmd_name}, password)
        out = _record_write("working", stored, resp)
        out["cmd"] = miner_cmd_name
        if isinstance(resp, dict) and resp.get("transport"):
            out["transport"] = resp.get("transport")
        return out

    if action == "power_pct":
        pct = int(value)
        if not 0 <= pct <= 100:
            raise ValueError("power_pct must be 0..100")
        # skip if already at this pct — set_power_pct can disturb / restart hashing
        try:
            live = live_snapshot(max_age_sec=LIVE_STALE_MAX_SEC)
            have_cmd = _f(live.get("power_pct_cmd"))
            if have_cmd is None:
                have_cmd = _f(_state.get("power_pct_cmd"))
            same = False
            if have_cmd is not None and abs(float(have_cmd) - float(pct)) < 0.5:
                same = True
            if not same:
                # estimate from power / limit (ASIC may not read back pct)
                pw = _f(live.get("power"))
                lim = _live_power_limit_w(live)
                if pw is not None and lim is not None and lim > 0 and float(pw) > 0:
                    est = 100.0 * float(pw) / float(lim)
                    if abs(est - float(pct)) <= 3.0:
                        same = True
            if same:
                return {
                    "ok": True,
                    "skipped": True,
                    "action": "power_pct",
                    "value": pct,
                    "msg": f"power_pct already {pct}%",
                }
        except Exception:
            pass
        resp = miner_write_cmd(
            {"cmd": "set_power_pct", "percent": str(pct)}, password
        )
        return _record_write("power_pct", pct, resp)

    if action in ("power_limit", "set_power_limit", "adjust_power_limit"):
        watts = int(value)
        if watts < 0 or watts > 20000:
            raise ValueError("power_limit out of range")
        # skip if ASIC already reports this limit (prefer power_limit_set, not
        # summary Power Limit which is often 0 in Suspend)
        try:
            live = live_snapshot(max_age_sec=LIVE_STALE_MAX_SEC)
            cur = _live_power_limit_w(live)
            # do NOT skip based only on power_limit_cmd — user may re-apply after
            # miner reset; only skip when live ASIC readback matches
            if cur is not None and abs(int(round(float(cur))) - int(watts)) <= 1:
                # still stamp cmd so UI form stays in sync
                with _state_lock:
                    _state["power_limit_cmd"] = watts
                    _save_state()
                return {
                    "ok": True,
                    "skipped": True,
                    "action": "power_limit",
                    "value": watts,
                    "msg": f"power_limit already {watts} W",
                }
        except Exception:
            pass
        # Prefer WMT NetPacket first (PoolheatMiner); if netpacket acks but
        # readback stays wrong, UniversalMiner still tried fallbacks.
        resp = miner_write_cmd(
            {"cmd": "adjust_power_limit", "power_limit": str(watts)}, password
        )
        out = _record_write(
            "power_limit",
            watts,
            resp,
            warning="adjust_power_limit may reboot / restart mining",
        )
        # Best-effort verify / refresh limit into cache after write
        try:
            live2 = live_snapshot(max_age_sec=LIVE_STALE_MAX_SEC)
            got = _live_power_limit_w(live2 if isinstance(live2, dict) else None)
            if got is not None:
                out["power_limit_set"] = got
                with _cache_lock:
                    if isinstance(_cache, dict):
                        _cache["power_limit_set"] = got
                        _cache["power_limit_measured"] = got
                        _cache["power_limit_cmd"] = watts
            else:
                # status may lag; still surface commanded watts in UI
                out["power_limit_set"] = float(watts)
        except Exception:
            out["power_limit_set"] = float(watts)
        return out

    # Full device reboot (Whatsminer / iPollo LuCI / Goldshell HTTP / CGMiner)
    if action in ("reboot", "reboot_asic", "system_reboot"):
        cmd: dict = {"cmd": "reboot"}
        pw = password
        if isinstance(value, dict):
            for k in ("host", "ip", "vendor", "api_vendor", "port", "id"):
                if value.get(k) not in (None, ""):
                    cmd[k if k != "api_vendor" else "vendor"] = value.get(k)
            # Resolve inventory password / vendor for targeted host
            th = str(value.get("host") or value.get("ip") or "").strip()
            if th:
                try:
                    for m in get_miners_managed().get("miners") or []:
                        if not isinstance(m, dict):
                            continue
                        mh = str(m.get("host") or "").strip()
                        if mh != th:
                            continue
                        if m.get("password") not in (None, ""):
                            pw = str(m.get("password"))
                            cmd["password"] = pw
                        if not cmd.get("vendor") and m.get("vendor"):
                            cmd["vendor"] = m.get("vendor")
                        if cmd.get("port") in (None, "") and m.get("port"):
                            cmd["port"] = m.get("port")
                        break
                except Exception:
                    pass
            if value.get("password") not in (None, ""):
                pw = str(value.get("password"))
                cmd["password"] = pw
        resp = miner_write_cmd(cmd, pw)
        out = _record_write(
            "reboot",
            cmd.get("host") or "asic",
            resp,
            warning="ASIC rebooting — offline for several minutes",
        )
        if isinstance(resp, dict) and resp.get("transport"):
            out["transport"] = resp.get("transport")
        return out

    # Restart mining process only (btminer / cgminer), not full OS reboot
    if action in ("restart", "restart_miner", "restart_btminer", "btminer_restart"):
        cmd = {"cmd": "restart_btminer"}
        pw = password
        if isinstance(value, dict):
            for k in ("host", "ip", "vendor", "port", "id"):
                if value.get(k) not in (None, ""):
                    cmd[k] = value.get(k)
            th = str(value.get("host") or value.get("ip") or "").strip()
            if th:
                try:
                    for m in get_miners_managed().get("miners") or []:
                        if not isinstance(m, dict):
                            continue
                        if str(m.get("host") or "").strip() != th:
                            continue
                        if m.get("password") not in (None, ""):
                            pw = str(m.get("password"))
                            cmd["password"] = pw
                        if not cmd.get("vendor") and m.get("vendor"):
                            cmd["vendor"] = m.get("vendor")
                        break
                except Exception:
                    pass
        resp = miner_write_cmd(cmd, pw)
        out = _record_write(
            "restart_miner",
            cmd.get("host") or "btminer",
            resp,
            warning="btminer restarting — hash rate rebuilds after upfreq",
        )
        if isinstance(resp, dict) and resp.get("transport"):
            out["transport"] = resp.get("transport")
        return out

    # Set mining pools via LuCI (btccom/libbtctools WhatsMinerHttpsLuci path)
    # value: list of {url,user,pass} or {"pools":[...]} — up to 3
    if action in ("pools", "set_pools", "update_pools"):
        pools_in = value
        if isinstance(pools_in, dict) and "pools" in pools_in:
            pools_in = pools_in.get("pools")
        if isinstance(pools_in, str):
            try:
                pools_in = json.loads(pools_in)
            except Exception as e:
                raise ValueError(f"pools JSON: {e}") from e
        if not isinstance(pools_in, list) or not pools_in:
            raise ValueError(
                "pools requires list [{url,user,pass},…] (1–3 entries)"
            )
        norm: list[dict] = []
        for p in pools_in[:3]:
            if not isinstance(p, dict):
                raise ValueError("each pool must be an object")
            norm.append(
                {
                    "url": str(p.get("url") or p.get("URL") or "").strip(),
                    "user": str(
                        p.get("user") or p.get("User") or p.get("worker") or ""
                    ).strip(),
                    "pass": str(
                        p.get("pass") or p.get("password") or p.get("Pass") or "x"
                    ),
                }
            )
        if not any(x.get("url") for x in norm):
            raise ValueError("at least one pool url required")
        resp = miner_write_cmd({"cmd": "update_pools", "pools": norm}, password)
        out = _record_write(
            "pools",
            norm,
            resp,
            warning="pools updated · btminer restart may follow",
        )
        if isinstance(resp, dict) and resp.get("transport"):
            out["transport"] = resp.get("transport")
        # invalidate pools cache
        try:
            global _pools_cache, _pools_cache_ts
            with _pools_cache_lock:
                _pools_cache = None
                _pools_cache_ts = 0.0
        except Exception:
            pass
        return out

    # Factory reset — Go miner-poller (NetPacket cmd 10, then V2).
    if action in (
        "factory_reset",
        "factory",
        "restore_factory",
        "reset_factory",
    ):
        conf = str(value or "").strip().lower()
        if conf not in ("yes", "confirm", "factory", "1", "go"):
            raise ValueError(
                "factory_reset requires value=yes (double confirm in UI)"
            )
        try:
            _policy_log("warn", "FACTORY_RESET via miner-poller · settings → defaults")
        except Exception:
            pass
        resp = miner_write_cmd({"cmd": "factory_reset"}, password)
        # Enrich response so UI WRITE log shows transport + status (not bare OK).
        if isinstance(resp, dict):
            tr = str(resp.get("transport") or "go-miner-poller")
            detail = str(
                resp.get("Msg")
                or resp.get("msg")
                or resp.get("status_text")
                or "accepted"
            )
            acc = resp.get("account")
            msg = f"{detail} · {tr}"
            if acc:
                msg += f" · {acc}"
            resp = dict(resp)
            resp.setdefault("STATUS", "S")
            resp["Msg"] = msg
            resp["transport"] = tr
        try:
            _policy_log(
                "ok",
                "FACTORY_RESET "
                + (
                    str((resp or {}).get("Msg") or "poller")
                    if isinstance(resp, dict)
                    else "poller"
                )
                + " · ASIC should reboot / defaults; IP may change",
            )
        except Exception:
            pass
        try:
            _token_cache_clear()
        except Exception:
            pass
        with _cache_lock:
            _cache = None
            _cache_ts = 0.0
        out = _record_write(
            "factory_reset",
            "asic",
            resp if isinstance(resp, dict) else {"result": resp},
            warning=(
                "Factory reset via miner-poller NetPacket cmd 10 · ASIC must reboot. "
                "If it stays online, factory mode may be blocked or password wrong — "
                "check miner-poller log."
            ),
        )
        if isinstance(resp, dict) and resp.get("transport"):
            out["transport"] = resp.get("transport")
        elif isinstance(out, dict):
            out["transport"] = "go-miner-poller"
        return out

    # Customer SN (EEPROM custom_data) — NetPacket cmd 30 / V2 set_customer_msg
    if action in (
        "customer_sn",
        "set_customer_sn",
        "set_customersn",
        "customersn",
        "set_customer_msg",
    ):
        sn = str(value if value is not None else "").strip()
        if len(sn) > 64:
            raise ValueError("CustomerSn max 64 characters")
        # empty allowed = erase
        resp = miner_write_cmd(
            {
                "cmd": "set_customer_sn",
                "sn": sn,
                "key": "CustomerSn",
                "val": sn,
            },
            password,
        )
        # stamp cache immediately so UI / identity show new SN without waiting
        try:
            _set_customer_sn_cache(sn or None)
        except Exception:
            pass
        # patch identity mem/disk so Miner Info updates even if re-collect is slow
        try:
            sn_n = _normalize_sn(sn) if sn else None
            patch = {
                "customer_sn": sn_n,
                "display_sn": sn_n,  # may be overridden if minersn present
                "sn_source": "customer_sn" if sn_n else None,
            }
            mem = _IDENT_CACHE.get("data") if isinstance(_IDENT_CACHE, dict) else None
            if isinstance(mem, dict):
                msn = _normalize_sn(mem.get("minersn"))
                if msn:
                    patch["display_sn"] = msn
                    patch["sn_source"] = "minersn"
                elif sn_n:
                    patch["display_sn"] = sn_n
                    patch["sn_source"] = "customer_sn"
                else:
                    patch["display_sn"] = None
                    patch["sn_source"] = None
                mem = dict(mem)
                mem.update(patch)
                _IDENT_CACHE["data"] = mem
                _IDENT_CACHE["ts"] = time.time()
                _save_miner_id_disk(mem)
            else:
                disk = _load_miner_id_disk() or {}
                if isinstance(disk, dict):
                    msn = _normalize_sn(disk.get("minersn"))
                    if msn:
                        patch["display_sn"] = msn
                        patch["sn_source"] = "minersn"
                    disk = dict(disk)
                    disk.update(patch)
                    _IDENT_CACHE["data"] = disk
                    _IDENT_CACHE["ts"] = time.time()
                    _save_miner_id_disk(disk)
        except Exception as e:
            print(f"[ident] customer_sn patch: {e}", flush=True)
        # full re-collect in background-ish (best-effort)
        try:
            get_miner_identity_cached(force=True)
        except Exception:
            pass
        try:
            _policy_log(
                "device" if sn else "info",
                (
                    f"CustomerSn set · {sn}"
                    if sn
                    else "CustomerSn cleared"
                ),
            )
        except Exception:
            pass
        out = _record_write(
            "customer_sn",
            sn or "(cleared)",
            resp if isinstance(resp, dict) else {"result": resp},
        )
        if isinstance(resp, dict) and resp.get("transport"):
            out["transport"] = resp.get("transport")
        if isinstance(out, dict):
            out["customer_sn"] = sn or None
            out["ok"] = True
            if sn:
                out["sn_source"] = "customer_sn"
                out["display_sn"] = sn
        return out

    raise ValueError(f"unknown action: {action}")


def _invalidate_cache(*, hard: bool = False) -> None:
    """
    Soft (default): drop freshness so /api/live re-polls, but keep last-good
    snapshot for Telegram (status/miner cards stay instant).
    hard=True: wipe snapshot (host change, etc.).
    """
    global _cache, _cache_ts
    with _cache_lock:
        if hard:
            _cache = None
            _cache_ts = 0.0
        else:
            # keep _cache body; force next HTTP live to refresh
            _cache_ts = 0.0


# ─── Telegram bot (getUpdates long-poll) ──────────────────────────────────────

# Default prefs for each chat_id (copied when chat is first seen)
# Notifications OFF by default — user enables in Profile.
DEFAULT_CHAT_PREFS = {
    "lang": "ru",  # ru | en
    "notify_events": False,
    "notify_offline": False,
    "notify_safety": False,
    "notify_zone": False,
    "commands_en": True,
    # confirm main-menu Force Stop / Continue (avoid accidental taps)
    "confirm_force_stop": True,
    # main reply-keyboard sections (Status + Profile always shown)
    "show_miner": True,
    "show_policy": True,  # Events section visibility
    "show_force_stop": True,
    "show_settings": True,
    "show_help": True,
}

# bool prefs stored per chat (besides lang)
_TG_BOOL_PREF_KEYS = (
    "notify_events",
    "notify_offline",
    "notify_safety",
    "notify_zone",
    "commands_en",
    "confirm_force_stop",
    "show_miner",
    "show_policy",
    "show_force_stop",
    "show_settings",
    "show_help",
)

# callback id → pref key for menu section visibility
_TG_SECTION_TOG = {
    "miner": "show_miner",
    "policy": "show_policy",
    "force_stop": "show_force_stop",
    "settings": "show_settings",
    "help": "show_help",
}

DEFAULT_TELEGRAM_CFG = {
    "enabled": False,
    "bot_token": "",
    # chat ids allowed for commands + receive notifications (ints or str digits)
    "chat_ids": [],
    # per-chat prefs: { "123456": { lang, notify_* , commands_en } }
    "chats": {},
    # global defaults for NEW chats (and fallback) — all notify OFF until user opts in
    "notify_events": False,  # zone/policy event log · APPLY
    "notify_offline": False,  # ASIC offline (after N consecutive poll fails)
    "notify_offline_streak": 3,  # in a row timeouts before TG (reset on any ok poll)
    "notify_safety": False,  # Safety Critical
    "notify_zone": False,  # zone change apply
    "commands_en": True,  # /status /suspend …
    "default_lang": "ru",
    "offset": 0,  # last processed update_id + 1
    # seen chats from bot traffic: [{id, username, first_name, last_name, title, type, nick, seen_ts}]
    "chat_history": [],
}
_TG_HISTORY_MAX = 40

_tg_cfg_lock = threading.Lock()
_tg_cfg: dict = dict(DEFAULT_TELEGRAM_CFG)
_tg_stop = threading.Event()
_tg_state_lock = threading.Lock()
_tg_state: dict = {
    "ok": False,
    "last_error": None,
    "last_update_ts": None,
    "last_send_ts": None,
    "me": None,  # bot username
    "polls": 0,
}
_tg_notify_lock = threading.Lock()
_tg_last_msg_sig: dict[str, float] = {}  # debounce identical messages
# Throttle telegram_config.json writes (Entware flash is slow; was on every msg)
_tg_save_ts = 0.0
_tg_save_dirty = False
_TG_SAVE_MIN_INTERVAL_SEC = 3.0
# Per-command latency: receive → first reply / handler end (ring buffer)
_TG_TIMING_MAX = 100
_TG_TIMING_SLOW_MS = 1500.0  # print [tg] slow when first/total exceeds
_tg_timing_lock = threading.Lock()
_tg_timing_log: list[dict] = []  # newest last; max _TG_TIMING_MAX
_tg_req = threading.local()  # active handler timing context
# ASIC offline streak: only TG after N consecutive fails; reset on success
_tg_offline_streak = 0
_tg_offline_notified = False
# Hidden tool: /emoji — wait for custom emoji and print custom_emoji_id
_tg_emoji_wait_lock = threading.Lock()
_tg_emoji_wait: set[str] = set()  # chat id keys in capture mode

# Custom emoji for miner host line (🖥 → pack glyph)
# HTML: <tg-emoji emoji-id="5399965542633200318">📦</tg-emoji>
_TG_MINER_HOST_EMOJI_ID = "5399965542633200318"
_TG_MINER_HOST_EMOJI_FB = "📦"  # unicode fallback inside custom_emoji entity
# Control / write FAIL in Miner + Status
# <tg-emoji emoji-id="5278578973595427038">🚫</tg-emoji>
# Fallback inside <tg-emoji> must NOT be 🚫 — some clients render custom+alt = two 🚫.
_TG_CTRL_ERR_EMOJI_ID = "5278578973595427038"
_TG_CTRL_ERR_EMOJI_FB = "⛔"
# Inline button «Пулы» — icon_custom_emoji_id (Bot API)
# <tg-emoji emoji-id="5267040075803274242">💲</tg-emoji>
_TG_POOLS_BTN_EMOJI_ID = "5267040075803274242"


def _load_telegram_cfg() -> None:
    global _tg_cfg
    with _tg_cfg_lock:
        raw = _load_json(TELEGRAM_CFG_FILE, DEFAULT_TELEGRAM_CFG)
        cfg = dict(DEFAULT_TELEGRAM_CFG)
        cfg.update(raw if isinstance(raw, dict) else {})
        cfg["enabled"] = bool(cfg.get("enabled", False))
        cfg["bot_token"] = str(cfg.get("bot_token") or "").strip()
        ids = cfg.get("chat_ids") or []
        if isinstance(ids, str):
            ids = [x.strip() for x in ids.replace(";", ",").split(",") if x.strip()]
        out_ids: list = []
        for x in ids if isinstance(ids, list) else []:
            try:
                out_ids.append(int(str(x).strip()))
            except (TypeError, ValueError):
                s = str(x).strip()
                if s:
                    out_ids.append(s)
        cfg["chat_ids"] = out_ids
        # legacy global key notify_policy → notify_events
        if isinstance(raw, dict) and "notify_policy" in raw and "notify_events" not in raw:
            cfg["notify_events"] = bool(raw.get("notify_policy"))
        cfg.pop("notify_policy", None)
        # legacy rudiment (filtration menu removed)
        cfg.pop("show_filtration", None)
        if isinstance(raw, dict):
            raw.pop("notify_policy", None)  # no-op on file; keep cfg clean
        for k in _TG_BOOL_PREF_KEYS:
            if k.startswith("show_"):
                cfg[k] = bool(cfg.get(k, True))
            else:
                # notify_* default OFF; commands_en default ON (DEFAULT_TELEGRAM_CFG)
                cfg[k] = bool(cfg.get(k, DEFAULT_TELEGRAM_CFG.get(k, False)))
        lang0 = str(cfg.get("default_lang") or "ru").lower()
        cfg["default_lang"] = "en" if lang0.startswith("en") else "ru"
        # per-chat map
        chats_in = cfg.get("chats") if isinstance(cfg.get("chats"), dict) else {}
        chats_out: dict = {}
        for cid in out_ids:
            key = str(cid)
            base = dict(DEFAULT_CHAT_PREFS)
            base["lang"] = cfg["default_lang"]
            for nk in _TG_BOOL_PREF_KEYS:
                # global defaults for notify_*/commands_en; show_* always default True
                if nk.startswith("show_"):
                    base[nk] = True
                else:
                    base[nk] = bool(
                        cfg.get(nk, DEFAULT_CHAT_PREFS.get(nk, False))
                    )
            prev = chats_in.get(key) if isinstance(chats_in.get(key), dict) else {}
            # also try int key as string already
            merged = dict(base)
            for pk, pv in prev.items():
                if pk == "lang":
                    merged["lang"] = "en" if str(pv).lower().startswith("en") else "ru"
                elif pk == "notify_policy":
                    # legacy → notify_events
                    merged["notify_events"] = bool(pv)
                elif pk in _TG_BOOL_PREF_KEYS or str(pk).startswith("show_"):
                    merged[pk] = bool(pv)
            merged.pop("notify_policy", None)
            chats_out[key] = merged
        # One-shot: silence all notifies (user opts in via Profile). Existing
        # chats had True from old defaults — reset once then set flag.
        notify_migrated = False
        if not cfg.get("notify_opt_in_v1"):
            for k in (
                "notify_events",
                "notify_offline",
                "notify_safety",
                "notify_zone",
            ):
                cfg[k] = False
            for ch in chats_out.values():
                if isinstance(ch, dict):
                    for k in (
                        "notify_events",
                        "notify_offline",
                        "notify_safety",
                        "notify_zone",
                    ):
                        ch[k] = False
            cfg["notify_opt_in_v1"] = True
            notify_migrated = True
        # keep orphan prefs? drop — only allowlisted chats
        cfg["chats"] = chats_out
        try:
            cfg["offset"] = max(0, int(cfg.get("offset") or 0))
        except (TypeError, ValueError):
            cfg["offset"] = 0
        try:
            cfg["notify_offline_streak"] = max(
                1, min(30, int(cfg.get("notify_offline_streak") or 3))
            )
        except (TypeError, ValueError):
            cfg["notify_offline_streak"] = 3
        # chat history (id + nick) for UI helper
        hist_in = cfg.get("chat_history") if isinstance(cfg.get("chat_history"), list) else []
        hist_out: list = []
        seen_h: set = set()
        for h in hist_in:
            if not isinstance(h, dict):
                continue
            try:
                hid = int(h.get("id"))
            except (TypeError, ValueError):
                continue
            if hid in seen_h:
                continue
            seen_h.add(hid)
            nick = str(h.get("nick") or "").strip()
            uname = str(h.get("username") or "").strip().lstrip("@")
            fn = str(h.get("first_name") or "").strip()
            ln = str(h.get("last_name") or "").strip()
            title = str(h.get("title") or "").strip()
            if not nick:
                if uname:
                    nick = "@" + uname
                elif title:
                    nick = title
                elif fn or ln:
                    nick = (fn + " " + ln).strip()
                else:
                    nick = str(hid)
            hist_out.append(
                {
                    "id": hid,
                    "username": uname,
                    "first_name": fn,
                    "last_name": ln,
                    "title": title,
                    "type": str(h.get("type") or "private"),
                    "nick": nick,
                    "seen_ts": str(h.get("seen_ts") or ""),
                }
            )
        # also seed from allowlisted chat_ids if not in history
        for cid in out_ids:
            try:
                hid = int(cid)
            except (TypeError, ValueError):
                continue
            if hid in seen_h:
                continue
            seen_h.add(hid)
            hist_out.append(
                {
                    "id": hid,
                    "username": "",
                    "first_name": "",
                    "last_name": "",
                    "title": "",
                    "type": "private",
                    "nick": str(hid),
                    "seen_ts": "",
                }
            )
        cfg["chat_history"] = hist_out[:_TG_HISTORY_MAX]
        _tg_cfg = cfg
        if notify_migrated:
            # hold lock; write directly (avoid re-entrant _save_telegram_cfg)
            try:
                _save_json(TELEGRAM_CFG_FILE, _tg_cfg)
            except Exception as e:
                print(f"[tg] notify_opt_in_v1 save: {e}")


def _save_telegram_cfg(*, force: bool = False) -> None:
    """
    Persist telegram_config.json. Throttled by default — every inbound message
    used to rewrite flash and delay getUpdates handlers on Peak.
    force=True for explicit API / offset-critical paths when needed.
    """
    global _tg_save_ts, _tg_save_dirty
    now = time.time()
    with _tg_cfg_lock:
        if (
            not force
            and _tg_save_ts
            and (now - float(_tg_save_ts)) < _TG_SAVE_MIN_INTERVAL_SEC
        ):
            _tg_save_dirty = True
            return
        _save_json(TELEGRAM_CFG_FILE, _tg_cfg)
        _tg_save_ts = now
        _tg_save_dirty = False


def get_telegram_cfg(*, redact: bool = True) -> dict:
    with _tg_cfg_lock:
        cfg = dict(_tg_cfg)
        # deep-ish copy chats
        if isinstance(cfg.get("chats"), dict):
            cfg["chats"] = {
                k: dict(v) if isinstance(v, dict) else v
                for k, v in cfg["chats"].items()
            }
    if redact and cfg.get("bot_token"):
        t = str(cfg["bot_token"])
        cfg["bot_token_set"] = True
        cfg["bot_token"] = (t[:6] + "…" + t[-4:]) if len(t) > 12 else "••••"
    else:
        cfg["bot_token_set"] = bool(cfg.get("bot_token"))
    with _tg_state_lock:
        cfg["status"] = dict(_tg_state)
    return cfg


def _tg_remember_chat(chat: dict | None, user: dict | None = None) -> None:
    """
    Record chat id + nick into chat_history (for UI picker).
    Called on every inbound message / callback.
    """
    if not isinstance(chat, dict):
        return
    try:
        hid = int(chat.get("id"))
    except (TypeError, ValueError):
        return
    ctype = str(chat.get("type") or "private")
    uname = ""
    fn = ""
    ln = ""
    title = str(chat.get("title") or "").strip()
    # prefer user for private chats
    src = user if isinstance(user, dict) else None
    if ctype == "private" and src:
        uname = str(src.get("username") or "").strip().lstrip("@")
        fn = str(src.get("first_name") or "").strip()
        ln = str(src.get("last_name") or "").strip()
    elif src:
        uname = str(src.get("username") or chat.get("username") or "").strip().lstrip("@")
        fn = str(src.get("first_name") or "").strip()
        ln = str(src.get("last_name") or "").strip()
    else:
        uname = str(chat.get("username") or "").strip().lstrip("@")
    if uname:
        nick = "@" + uname
    elif title:
        nick = title
    elif fn or ln:
        nick = (fn + " " + ln).strip()
    else:
        nick = str(hid)
    entry = {
        "id": hid,
        "username": uname,
        "first_name": fn,
        "last_name": ln,
        "title": title,
        "type": ctype,
        "nick": nick,
        "seen_ts": datetime.now().isoformat(timespec="seconds"),
    }
    with _tg_cfg_lock:
        hist = _tg_cfg.get("chat_history")
        if not isinstance(hist, list):
            hist = []
        # move to front / update
        hist = [h for h in hist if not (isinstance(h, dict) and h.get("id") == hid)]
        hist.insert(0, entry)
        _tg_cfg["chat_history"] = hist[:_TG_HISTORY_MAX]
    # persist lightly (ok to write often — small file)
    try:
        _save_telegram_cfg()
    except Exception:
        pass


def _tg_cid_key(chat_id) -> str:
    try:
        return str(int(chat_id))
    except (TypeError, ValueError):
        return str(chat_id)


def _tg_ensure_chat_prefs(chat_id) -> dict:
    """Create default prefs for chat_id if missing. Caller holds no lock required."""
    key = _tg_cid_key(chat_id)
    with _tg_cfg_lock:
        chats = _tg_cfg.setdefault("chats", {})
        if not isinstance(chats, dict):
            chats = {}
            _tg_cfg["chats"] = chats
        if key not in chats or not isinstance(chats.get(key), dict):
            prefs = dict(DEFAULT_CHAT_PREFS)
            prefs["lang"] = str(_tg_cfg.get("default_lang") or "ru")
            for nk in _TG_BOOL_PREF_KEYS:
                if nk.startswith("show_"):
                    prefs[nk] = True
                else:
                    prefs[nk] = bool(_tg_cfg.get(nk, True))
            chats[key] = prefs
        # ensure chat_id in allowlist when we have prefs from active user
        ids = list(_tg_cfg.get("chat_ids") or [])
        try:
            cid_i = int(key)
        except ValueError:
            cid_i = key
        if cid_i not in ids and key not in {str(x) for x in ids}:
            # do not auto-allow; only ensure structure for allowed chats
            pass
        return dict(chats[key])


def _tg_get_chat_prefs(chat_id) -> dict:
    key = _tg_cid_key(chat_id)
    with _tg_cfg_lock:
        chats = _tg_cfg.get("chats") if isinstance(_tg_cfg.get("chats"), dict) else {}
        p = chats.get(key)
        if isinstance(p, dict):
            out = dict(DEFAULT_CHAT_PREFS)
            out.update(p)
            # legacy cleanup for callers
            if "notify_policy" in out:
                if "notify_events" not in p:
                    out["notify_events"] = bool(out.get("notify_policy"))
                out.pop("notify_policy", None)
            return out
        # fallback global defaults
        out = dict(DEFAULT_CHAT_PREFS)
        out["lang"] = str(_tg_cfg.get("default_lang") or "ru")
        for nk in _TG_BOOL_PREF_KEYS:
            if nk.startswith("show_"):
                out[nk] = True
            else:
                out[nk] = bool(_tg_cfg.get(nk, True))
        return out


def _tg_remove_chat(chat_id, *, history: bool = False) -> dict:
    """
    Remove chat from allowlist + per-chat prefs.
    history=True also drops entry from chat_history picker.
    """
    key = _tg_cid_key(chat_id)
    with _tg_cfg_lock:
        ids = list(_tg_cfg.get("chat_ids") or [])
        _tg_cfg["chat_ids"] = [
            x
            for x in ids
            if str(x) != key and str(x) != str(chat_id)
        ]
        chats = _tg_cfg.get("chats")
        if isinstance(chats, dict):
            chats.pop(key, None)
            chats.pop(str(chat_id), None)
        if history:
            hist = _tg_cfg.get("chat_history")
            if isinstance(hist, list):
                try:
                    hid = int(key)
                except ValueError:
                    hid = None
                _tg_cfg["chat_history"] = [
                    h
                    for h in hist
                    if not (
                        isinstance(h, dict)
                        and (
                            str(h.get("id")) == key
                            or (hid is not None and h.get("id") == hid)
                        )
                    )
                ]
    try:
        _save_telegram_cfg()
    except Exception:
        pass
    _load_telegram_cfg()
    return get_telegram_cfg(redact=True)


def _tg_set_chat_prefs(chat_id, **updates) -> dict:
    key = _tg_cid_key(chat_id)
    with _tg_cfg_lock:
        chats = _tg_cfg.setdefault("chats", {})
        if not isinstance(chats, dict):
            chats = {}
            _tg_cfg["chats"] = chats
        cur = dict(DEFAULT_CHAT_PREFS)
        if isinstance(chats.get(key), dict):
            cur.update(chats[key])
        for k, v in updates.items():
            if k == "lang":
                cur["lang"] = "en" if str(v).lower().startswith("en") else "ru"
            elif k == "notify_policy":
                cur["notify_events"] = bool(v)
            elif k in _TG_BOOL_PREF_KEYS or str(k).startswith("show_"):
                cur[k] = bool(v)
        cur.pop("notify_policy", None)
        chats[key] = cur
        # ensure allowlisted
        ids = list(_tg_cfg.get("chat_ids") or [])
        try:
            cid_i = int(key)
        except ValueError:
            cid_i = key
        if cid_i not in ids and str(cid_i) not in {str(x) for x in ids}:
            ids.append(cid_i)
            _tg_cfg["chat_ids"] = ids
        out = dict(cur)
    try:
        _save_telegram_cfg()
    except Exception:
        pass
    return out


def _tg_chat_wants(chat_id, notify_kind: str) -> bool:
    """notify_kind: events | offline | safety | zone"""
    prefs = _tg_get_chat_prefs(chat_id)
    key = {
        "events": "notify_events",
        "offline": "notify_offline",
        "safety": "notify_safety",
        "zone": "notify_zone",
    }.get(str(notify_kind or "").strip().lower())
    if not key:
        return True
    return bool(prefs.get(key, True))


def _tg_api(method: str, payload: dict | None = None, *, timeout: float = 35.0) -> dict:
    with _tg_cfg_lock:
        token = str(_tg_cfg.get("bot_token") or "").strip()
    if not token:
        raise RuntimeError("bot_token empty")
    url = f"https://api.telegram.org/bot{token}/{method}"
    data = None
    headers = {"User-Agent": f"poolheat/{get_app_version()} telegram"}
    if payload is not None:
        raw = json.dumps(payload).encode("utf-8")
        data = raw
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, headers=headers, method="POST" if data else "GET")
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        body = json.loads(resp.read().decode("utf-8", errors="replace"))
    if not isinstance(body, dict):
        raise RuntimeError("bad telegram response")
    if not body.get("ok"):
        raise RuntimeError(body.get("description") or "telegram api error")
    return body


def _tg_chat_allowed(chat_id) -> bool:
    with _tg_cfg_lock:
        ids = list(_tg_cfg.get("chat_ids") or [])
    if not ids:
        return False
    try:
        cid = int(chat_id)
    except (TypeError, ValueError):
        cid = str(chat_id)
    return cid in ids or str(cid) in {str(x) for x in ids}


def _tg_target_chats() -> list:
    with _tg_cfg_lock:
        return list(_tg_cfg.get("chat_ids") or [])


def _tg_utf16_len(s: str) -> int:
    """Length in UTF-16 code units (Telegram entity offsets)."""
    return len((s or "").encode("utf-16-le")) // 2


def _tg_miner_host_prefix() -> str:
    """📦  — fallback glyph for custom miner-host emoji."""
    return f"{_TG_MINER_HOST_EMOJI_FB}  "


def _tg_html_esc(s) -> str:
    """Escape for Telegram parse_mode=HTML."""
    return (
        str(s if s is not None else "")
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def _tg_miner_host_line_html(host: str) -> str:
    """Host line with custom emoji via HTML (works with parse_mode=HTML)."""
    return (
        f'<tg-emoji emoji-id="{_TG_MINER_HOST_EMOJI_ID}">'
        f"{_TG_MINER_HOST_EMOJI_FB}</tg-emoji>  {_tg_html_esc(host)}"
    )


def _tg_attach_miner_host_emoji(text: str) -> tuple[str, list[dict]]:
    """
    Replace 🖥 with pack emoji 📦 and attach custom_emoji entities.
    Returns (text, entities) for sendMessage/editMessageText.
    """
    t = text or ""
    # normalize any computer emoji to our fallback box
    t = t.replace("🖥  ", _tg_miner_host_prefix()).replace("🖥 ", _tg_miner_host_prefix())
    t = t.replace("🖥", _TG_MINER_HOST_EMOJI_FB)
    entities: list[dict] = []
    fb = _TG_MINER_HOST_EMOJI_FB
    fb_u16 = _tg_utf16_len(fb)
    # scan codepoints; track UTF-16 offset
    u16 = 0
    i = 0
    while i < len(t):
        if t.startswith(fb, i):
            prev = t[i - 1] if i > 0 else "\n"
            # only host lines: start of message or after newline, then "  "
            nxt = t[i + len(fb) : i + len(fb) + 2]
            if (i == 0 or prev == "\n") and nxt == "  ":
                entities.append(
                    {
                        "type": "custom_emoji",
                        "offset": u16,
                        "length": fb_u16,
                        "custom_emoji_id": _TG_MINER_HOST_EMOJI_ID,
                    }
                )
            u16 += fb_u16
            i += len(fb)
            continue
        # advance one unicode char
        ch = t[i]
        u16 += _tg_utf16_len(ch)
        i += 1
    return t, entities


def _tg_req_begin(
    *,
    kind: str,
    cmd: str,
    chat_id=None,
    update_id=None,
) -> None:
    """Start timing for one inbound update (command or callback)."""
    _tg_req.active = True
    _tg_req.t0 = time.monotonic()
    _tg_req.kind = str(kind or "msg")[:24]
    _tg_req.cmd = str(cmd or "")[:100]
    _tg_req.chat_id = chat_id
    _tg_req.update_id = update_id
    _tg_req.n_out = 0
    _tg_req.first_ms = None  # any outbound (answer/send/edit)
    _tg_req.reply_ms = None  # first sendMessage / editMessageText
    _tg_req.answer_ms = None
    _tg_req.last_via = None
    _tg_req.outs = []


def _tg_req_note_out(via: str) -> None:
    """Mark one Telegram outbound API call after success."""
    if not getattr(_tg_req, "active", False):
        return
    t0 = getattr(_tg_req, "t0", None)
    if t0 is None:
        return
    ms = round((time.monotonic() - float(t0)) * 1000.0, 1)
    via_s = str(via or "out")[:24]
    _tg_req.n_out = int(getattr(_tg_req, "n_out", 0) or 0) + 1
    if _tg_req.first_ms is None:
        _tg_req.first_ms = ms
    if via_s == "answer":
        if _tg_req.answer_ms is None:
            _tg_req.answer_ms = ms
    elif via_s in ("send", "edit", "edit_markup") and _tg_req.reply_ms is None:
        _tg_req.reply_ms = ms
    _tg_req.last_via = via_s
    outs = getattr(_tg_req, "outs", None)
    if not isinstance(outs, list):
        outs = []
        _tg_req.outs = outs
    outs.append({"via": via_s, "ms": ms})
    if len(outs) > 8:
        del outs[:-8]


def _tg_req_end(*, error: str | None = None) -> None:
    """Close timing context and append ring-buffer entry."""
    if not getattr(_tg_req, "active", False):
        return
    t0 = getattr(_tg_req, "t0", None)
    total_ms = (
        round((time.monotonic() - float(t0)) * 1000.0, 1) if t0 is not None else None
    )
    first_ms = getattr(_tg_req, "first_ms", None)
    reply_ms = getattr(_tg_req, "reply_ms", None)
    answer_ms = getattr(_tg_req, "answer_ms", None)
    entry = {
        "ts": datetime.now().isoformat(timespec="seconds"),
        "kind": getattr(_tg_req, "kind", None),
        "cmd": getattr(_tg_req, "cmd", None),
        "chat_id": getattr(_tg_req, "chat_id", None),
        "update_id": getattr(_tg_req, "update_id", None),
        "first_ms": first_ms,
        "answer_ms": answer_ms,
        "reply_ms": reply_ms,
        "total_ms": total_ms,
        "n_out": int(getattr(_tg_req, "n_out", 0) or 0),
        "last_via": getattr(_tg_req, "last_via", None),
        "outs": list(getattr(_tg_req, "outs", None) or []),
        "error": (str(error)[:160] if error else None),
    }
    with _tg_timing_lock:
        _tg_timing_log.append(entry)
        overflow = len(_tg_timing_log) - _TG_TIMING_MAX
        if overflow > 0:
            del _tg_timing_log[:overflow]
    # console hint for slow handlers
    slow_ref = reply_ms if reply_ms is not None else first_ms
    try:
        slow = (
            (slow_ref is not None and float(slow_ref) >= _TG_TIMING_SLOW_MS)
            or (total_ms is not None and float(total_ms) >= _TG_TIMING_SLOW_MS)
        )
    except (TypeError, ValueError):
        slow = False
    if slow or error:
        print(
            f"[tg] timing {'SLOW ' if slow else ''}"
            f"cmd={entry.get('cmd')!r} first={first_ms} "
            f"reply={reply_ms} total={total_ms} ms n_out={entry.get('n_out')}"
            + (f" err={error}" if error else "")
        )
    _tg_req.active = False


def get_tg_timing(*, limit: int = 100, newest_first: bool = True) -> dict:
    """Ring buffer of recent command→reply latencies (in-memory)."""
    lim = max(1, min(int(limit or _TG_TIMING_MAX), _TG_TIMING_MAX))
    with _tg_timing_lock:
        items = list(_tg_timing_log[-lim:])
    if newest_first:
        items.reverse()
    return {
        "ok": True,
        "max": _TG_TIMING_MAX,
        "count": len(items),
        "slow_ms": _TG_TIMING_SLOW_MS,
        "items": items,
    }


def tg_send_message(
    chat_id,
    text: str,
    *,
    silent: bool = False,
    reply_markup: dict | None = None,
    parse_mode: str | None = None,
    entities: list | None = None,
    miner_host_emoji: bool = False,
) -> bool:
    text = (text or "")[:3900]
    if not text:
        return False
    try:
        ent = list(entities) if entities else None
        if miner_host_emoji and not parse_mode:
            # custom emoji entities conflict with parse_mode HTML
            text, ent2 = _tg_attach_miner_host_emoji(text)
            ent = (ent or []) + ent2
        payload: dict = {
            "chat_id": chat_id,
            "text": text,
            "disable_notification": bool(silent),
        }
        if reply_markup is not None:
            payload["reply_markup"] = reply_markup
        if parse_mode:
            payload["parse_mode"] = parse_mode
        elif ent:
            payload["entities"] = ent
        _tg_api("sendMessage", payload, timeout=20)
        _tg_req_note_out("send")
        with _tg_state_lock:
            _tg_state["last_send_ts"] = datetime.now().isoformat(timespec="seconds")
            _tg_state["ok"] = True
            _tg_state["last_error"] = None
        return True
    except Exception as e:
        with _tg_state_lock:
            _tg_state["ok"] = False
            _tg_state["last_error"] = str(e)
        print(f"[tg] send fail chat={chat_id}: {e}")
        return False


def tg_edit_message(
    chat_id,
    message_id: int,
    text: str,
    *,
    reply_markup: dict | None = None,
    parse_mode: str | None = None,
    entities: list | None = None,
    miner_host_emoji: bool = False,
) -> bool:
    text = (text or "")[:3900]
    try:
        ent = list(entities) if entities else None
        if miner_host_emoji and not parse_mode:
            text, ent2 = _tg_attach_miner_host_emoji(text)
            ent = (ent or []) + ent2
        payload: dict = {
            "chat_id": chat_id,
            "message_id": int(message_id),
            "text": text,
        }
        if reply_markup is not None:
            payload["reply_markup"] = reply_markup
        if parse_mode:
            payload["parse_mode"] = parse_mode
        elif ent:
            payload["entities"] = ent
        _tg_api("editMessageText", payload, timeout=15)
        _tg_req_note_out("edit")
        return True
    except Exception as e:
        err = str(e).lower()
        # text identical — still try to swap keyboard only
        if "not modified" in err and reply_markup is not None:
            return tg_edit_reply_markup(chat_id, message_id, reply_markup)
        if "not modified" in err:
            _tg_req_note_out("edit")
            return True
        print(f"[tg] edit fail: {e}")
        # last resort: keyboard-only edit
        if reply_markup is not None:
            return tg_edit_reply_markup(chat_id, message_id, reply_markup)
        return False


def tg_edit_reply_markup(
    chat_id, message_id: int, reply_markup: dict | None
) -> bool:
    """Update inline keyboard without changing message text."""
    try:
        payload: dict = {
            "chat_id": chat_id,
            "message_id": int(message_id),
        }
        if reply_markup is not None:
            payload["reply_markup"] = reply_markup
        else:
            payload["reply_markup"] = {"inline_keyboard": []}
        _tg_api("editMessageReplyMarkup", payload, timeout=15)
        _tg_req_note_out("edit_markup")
        return True
    except Exception as e:
        if "not modified" in str(e).lower():
            _tg_req_note_out("edit_markup")
            return True
        print(f"[tg] edit markup fail: {e}")
        return False


def tg_answer_callback(callback_query_id: str, text: str = "", *, alert: bool = False) -> None:
    try:
        _tg_api(
            "answerCallbackQuery",
            {
                "callback_query_id": callback_query_id,
                "text": (text or "")[:180],
                "show_alert": bool(alert),
            },
            timeout=10,
        )
        _tg_req_note_out("answer")
    except Exception:
        pass


def _tg_dry_run_on() -> bool:
    try:
        return bool(get_miner_settings().get("dry_run"))
    except Exception:
        return bool(DRY_RUN)


def _tg_who(from_user: dict | None, chat_id=None) -> str:
    """
    Laconic actor for action log (kind already shows [tg]):
      @username   if Telegram login is set
      chat 123    otherwise (no first-name noise)
    """
    cid = chat_id if chat_id is not None else "?"
    uname = ""
    if isinstance(from_user, dict):
        uname = str(from_user.get("username") or "").strip().lstrip("@")
    if uname:
        return f"@{uname}"
    return f"chat {cid}"


def _rewrite_tg_event_msg(msg: str) -> str:
    """
    Normalize legacy TG action log lines:
      chat 843750212 · @chogdekogo · Filtration ON  →  @chogdekogo · Filtration ON
      chat 843750212 · John · Filtration ON         →  chat 843750212 · Filtration ON
    """
    m = str(msg or "").strip()
    if not m.lower().startswith("chat "):
        return m
    # chat ID · @user · action
    mm = re.match(
        r"^chat\s+(\S+)\s+·\s+(@[A-Za-z0-9_]{1,64})\s+·\s+(.+)$",
        m,
    )
    if mm:
        return f"{mm.group(2)} · {mm.group(3).strip()}"
    # chat ID · something · action  (no @login → keep chat id only)
    mm = re.match(r"^chat\s+(\S+)\s+·\s+([^·]+?)\s+·\s+(.+)$", m)
    if mm:
        return f"chat {mm.group(1)} · {mm.group(3).strip()}"
    # chat ID · @user   (no action tail)
    mm = re.match(r"^chat\s+(\S+)\s+·\s+(@[A-Za-z0-9_]{1,64})\s*$", m)
    if mm:
        return mm.group(2)
    return m


def _tg_log_control(
    chat_id,
    from_user: dict | None,
    action: str,
) -> None:
    """
    Action log after a real control change only (not confirm dialogs).
    Format: @user · Force Stop OFF   or   chat 123 · Force Stop OFF
    (kind [tg] is added by the Events / Action log UI)
    """
    who = _tg_who(from_user, chat_id)
    act = str(action or "?").strip()
    msg = f"{who} · {act}" if act else who
    try:
        _policy_log(
            "tg",
            msg,
            source="telegram",
            chat_id=str(chat_id),
        )
    except Exception as e:
        print(f"[tg] action log fail: {e}")


def _tg_apply_force_stop_result(
    chat_id,
    onoff: bool,
    lang: str = "ru",
    *,
    from_user: dict | None = None,
    log: bool = True,
) -> None:
    """Apply Force Stop and send result + main keyboard."""
    en = str(lang or "ru").lower().startswith("en")
    if log:
        _tg_log_control(
            chat_id,
            from_user,
            "Force Stop ON" if onoff else "Force Stop OFF")
    try:
        set_force_stop(bool(onoff), apply_now=True)
        if onoff:
            msg = (
                "🛑 Force Stop ON · mining suspended\n"
                "Zones & Dry Run ignored until Continue mining"
                if en
                else "🛑 Force Stop ВКЛ · майнинг остановлен\n"
                "Зоны и Dry Run игнорируются до «Продолжить майнинг»"
            )
        else:
            msg = (
                "▶️ Force Stop OFF · Continue mining\n"
                "Zone auto / Dry Run rules apply again"
                if en
                else "▶️ Force Stop ВЫКЛ · Продолжить майнинг\n"
                "Снова действуют зоны / Dry Run"
            )
        tg_send_message(chat_id, msg, reply_markup=_tg_main_keyboard(lang, chat_id))
    except Exception as e:
        tg_send_message(
            chat_id,
            f"❌ Force Stop: {e}",
            reply_markup=_tg_main_keyboard(lang, chat_id),
        )


def _tg_offer_force_stop_confirm(chat_id, want: bool, lang: str = "ru") -> None:
    """Inline Yes/No before Force Stop ON/OFF (profile confirm_force_stop)."""
    en = str(lang or "ru").lower().startswith("en")
    if want:
        text = (
            "⚠️ Confirm <b>Force Stop ON</b>?\n"
            "Mining will suspend · zones & Dry Run ignored until Continue."
            if en
            else "⚠️ Подтвердите <b>Force Stop ВКЛ</b>?\n"
            "Майнинг остановится · зоны и Dry Run игнорируются до «Продолжить»."
        )
    else:
        text = (
            "⚠️ Confirm <b>Force Stop OFF</b>?\n"
            "Zone auto / Dry Run rules apply again."
            if en
            else "⚠️ Подтвердите <b>Force Stop ВЫКЛ</b>?\n"
            "Снова действуют зоны / Dry Run."
        )
    markup = {
        "inline_keyboard": [
            [
                {
                    "text": "✅ Yes" if en else "✅ Да",
                    "callback_data": f"fs:yes:{1 if want else 0}",
                },
                {
                    "text": "❌ No" if en else "❌ Нет",
                    "callback_data": "fs:no",
                },
            ]
        ]
    }
    tg_send_message(
        chat_id,
        text,
        reply_markup=markup,
        parse_mode="HTML",
    )


def _tg_force_stop_btn_label(lang: str = "ru") -> str:
    """Main-menu toggle: Stop when off, Continue when Force Stop is active."""
    en = str(lang or "ru").lower().startswith("en")
    on = get_force_stop()
    # ▶️ continue · ⏹ stop (same “transport” style)
    if en:
        return "▶️ Continue mining" if on else "⏹ Stop mining"
    return "▶️ Продолжить майнинг" if on else "⏹ Остановить майнинг"


def _tg_main_keyboard(lang: str = "ru", chat_id=None) -> dict:
    """
    Persistent reply keyboard — main navigation.
    Per-chat show_* prefs hide optional sections (Status + Profile always on).
    Pump / outlets: only via Peripherals → Devices bot buttons.
    """
    prefs: dict = {}
    if chat_id is not None:
        try:
            prefs = _tg_get_chat_prefs(chat_id)
            if not lang:
                lang = str(prefs.get("lang") or "ru")
        except Exception:
            prefs = {}
    en = str(lang or "ru").lower().startswith("en")

    def _show(key: str) -> bool:
        # default visible if pref missing
        return bool(prefs.get(key, True)) if prefs else True

    # Info + Pools live under Miner (inline), not on the main keyboard.
    fs_btn = _tg_force_stop_btn_label(lang)

    # Row 1: Status always · Miner optional
    row1 = [{"text": "📊 Status" if en else "📊 Статус"}]
    if _show("show_miner"):
        row1.append({"text": "⛏ Miner" if en else "⛏ Майнер"})

    # Row 2: Profile always · Events (policy log) optional
    row2 = [{"text": "👤 Profile" if en else "👤 Профайл"}]
    if _show("show_policy"):
        row2.append({"text": "📋 Events" if en else "📋 События"})

    rows: list[list[dict]] = [row1, row2]
    if _show("show_force_stop"):
        rows.append([{"text": fs_btn}])

    # Peripherals devices with «show button in bot»
    try:
        bot_devs = list_devices_bot_buttons(lang="en" if en else "ru")
    except Exception:
        bot_devs = []
    if bot_devs:
        # up to 2 buttons per row
        row_dev: list[dict] = []
        for bd in bot_devs[:12]:
            icon = str(bd.get("icon") or "🔌")
            name = str(bd.get("name") or bd.get("alias") or "device")[:24]
            st = bd.get("on")
            if st is True:
                mark = "●" if en else "●"
            elif st is False:
                mark = "○"
            else:
                mark = "·"
            label = f"{icon} {name} [{mark}]"
            if len(label) > 40:
                label = f"{icon} {name[:18]} [{mark}]"
            row_dev.append({"text": label})
            if len(row_dev) >= 2:
                rows.append(row_dev)
                row_dev = []
        if row_dev:
            rows.append(row_dev)

    # Settings / Help
    tail: list[dict] = []
    if _show("show_settings"):
        tail.append({"text": "⚙️ Settings" if en else "⚙️ Настройки"})
    if _show("show_help"):
        tail.append({"text": "❓ Help" if en else "❓ Справка"})
    if tail:
        rows.append(tail)

    return {
        "keyboard": rows,
        "resize_keyboard": True,
        "is_persistent": True,
    }


def _tg_on_mark(v: bool, en: bool) -> str:
    if en:
        return "✅ ON" if v else "⬜ OFF"
    return "✅ ВКЛ" if v else "⬜ ВЫКЛ"


def _tg_settings_inline(
    chat_id, prefs: dict | None = None, *, view: str = "root"
) -> dict:
    """
    Inline keyboard for personal settings.
    view:
      root     — language · Notifications · Menu sections · Control · nav
      notify   — expand notification toggles + Back
      sections — expand main-menu section visibility + Back
    """
    p = prefs or _tg_get_chat_prefs(chat_id)
    en = str(p.get("lang") or "ru").lower().startswith("en")
    v = str(view or "root").lower()
    if v.startswith("notif"):
        view = "notify"
    elif v.startswith("sec") or v in ("menu", "sections", "menu_sec"):
        view = "sections"
    else:
        view = "root"

    def on_mark(key: str, default: bool = True) -> str:
        return _tg_on_mark(bool(p.get(key, default)), en)

    if view == "notify":
        # Expanded: each notification toggle + back to profile root
        rows = [
            [
                {
                    "text": (
                        f"Zone {on_mark('notify_zone')}"
                        if en
                        else f"Зоны {on_mark('notify_zone')}"
                    ),
                    "callback_data": "s:tog:zone",
                }
            ],
            [
                {
                    "text": f"Safety {on_mark('notify_safety')}",
                    "callback_data": "s:tog:safety",
                }
            ],
            [
                {
                    "text": f"Offline {on_mark('notify_offline')}",
                    "callback_data": "s:tog:offline",
                }
            ],
            [
                {
                    "text": (
                        f"Events {on_mark('notify_events')}"
                        if en
                        else f"События {on_mark('notify_events')}"
                    ),
                    "callback_data": "s:tog:events",
                }
            ],
            [
                {
                    "text": "◀️ " + ("Back" if en else "Назад"),
                    "callback_data": "s:notify:back",
                }
            ],
        ]
        return {"inline_keyboard": rows}

    if view == "sections":
        # Which main-menu buttons to show (Status + Profile always on)
        def sec_btn(sid: str, label_en: str, label_ru: str) -> dict:
            key = _TG_SECTION_TOG[sid]
            return {
                "text": f"{label_en if en else label_ru} {on_mark(key)}",
                "callback_data": f"s:togsec:{sid}",
            }

        rows = [
            [sec_btn("miner", "⛏ Miner", "⛏ Майнер")],
            [sec_btn("policy", "📋 Events", "📋 События")],
            [sec_btn("force_stop", "⏹ Force Stop", "⏹ Force Stop")],
            [sec_btn("settings", "⚙️ Settings", "⚙️ Настройки")],
            [sec_btn("help", "❓ Help", "❓ Справка")],
            [
                {
                    "text": "◀️ " + ("Back" if en else "Назад"),
                    "callback_data": "s:sections:back",
                }
            ],
        ]
        return {"inline_keyboard": rows}

    # Root profile keyboard
    lang_ru = "● RU" if not en else "RU"
    lang_en = "● EN" if en else "EN"
    # compact status of all notify flags on the folder button
    n_on = sum(
        1
        for k in (
            "notify_zone",
            "notify_safety",
            "notify_offline",
            "notify_events",
        )
        if bool(p.get(k, True))
    )
    notify_btn = (
        f"🔔 Notifications · {n_on}/4"
        if en
        else f"🔔 Уведомления · {n_on}/4"
    )
    sec_keys = list(_TG_SECTION_TOG.values())
    s_on = sum(1 for k in sec_keys if bool(p.get(k, True)))
    s_tot = len(sec_keys)
    sections_btn = (
        f"📱 Menu sections · {s_on}/{s_tot}"
        if en
        else f"📱 Разделы меню · {s_on}/{s_tot}"
    )
    rows = [
        [
            {"text": f"🌐 {lang_ru}", "callback_data": "s:lang:ru"},
            {"text": f"🌐 {lang_en}", "callback_data": "s:lang:en"},
        ],
        [
            {
                "text": notify_btn,
                "callback_data": "s:notify",
            }
        ],
        [
            {
                "text": sections_btn,
                "callback_data": "s:sections",
            }
        ],
        [
            {
                "text": (
                    f"Control {on_mark('commands_en')}"
                    if en
                    else f"Управление {on_mark('commands_en')}"
                ),
                "callback_data": "s:tog:commands",
            }
        ],
        [
            {
                "text": (
                    f"Force Stop confirm {on_mark('confirm_force_stop')}"
                    if en
                    else f"Подтверждение Force Stop {on_mark('confirm_force_stop')}"
                ),
                "callback_data": "s:tog:confirm_fs",
            }
        ],
        [
            {
                "text": "🔄 " + ("Refresh" if en else "Обновить"),
                "callback_data": "s:refresh",
            },
            {
                "text": "◀️ " + ("Settings" if en else "Настройки"),
                "callback_data": "cfg:home",
            },
            {
                "text": "🏠 " + ("Menu" if en else "Меню"),
                "callback_data": "s:menu",
            },
        ],
    ]
    return {"inline_keyboard": rows}


def _tg_normalize_incoming_text(text: str) -> str:
    """
    Button label → /command; leave real commands as-is.
    Match by keyword (emoji variants differ across clients).
    """
    t = (text or "").strip()
    if not t:
        return t
    if t.startswith("/"):
        return t
    low = t.lower()
    # strip common emoji / symbols for matching
    bare = low
    for ch in (
        "📊", "⚙️", "⚙", "⏸", "⏸️", "▶️", "▶", "⏹", "⏹️", "🛑",
        "📋", "🏊", "ℹ️", "ℹ", "🏠", "⛏", "⛏️", "❓", "🧪", "🔴", "🟢",
        "💧", "🔒",
    ):
        bare = bare.replace(ch, " ")
    bare = " ".join(bare.split())
    if "status" in bare or bare in ("статус",):
        return "/status"
    if "miner" in bare or "майнер" in bare:
        return "/miner"
    if "dry" in bare or "dry_run" in bare or "dryrun" in bare:
        return "/dry_run"
    if bare in ("info", "инфо", "информ", "information") or "инфо" in bare:
        return "/info"
    if "профайл" in bare or "profile" in bare or bare == "prefs":
        return "/profile"
    if "setting" in bare or "настрой" in bare:
        return "/settings"
    if "update" in bare or "обновл" in bare:
        return "/update"
    if (
        "stop mining" in bare
        or "stop work" in bare
        or "остановить майнинг" in bare
        or "остановить работу" in bare
        or bare in ("остановить", "stop", "force stop", "forcestop")
        or "force_stop" in bare
        or "останов" in bare
    ):
        return "/force_stop"
    if (
        "continue mining" in bare
        or "continue work" in bare
        or "продолжить майнинг" in bare
        or "продолжить работу" in bare
        or bare in ("продолжить", "continue")
        or "продолж" in bare
    ):
        # Continue mining = clear Force Stop (not plain resume)
        return "/force_stop"
    if "suspend" in bare or "sleep" in bare or "приостанов" in bare:
        return "/force_stop"
    if "resume" in bare or bare in ("mining", "майнинг"):
        return "/force_stop"
    if "events" in bare or "событ" in bare or bare in ("event", "policy"):
        return "/events"
    if "pool" in bare or "пул" in bare:
        return "/pools"
    if "help" in bare or "справк" in bare or "помощ" in bare:
        return "/help"
    if "menu" in bare or "меню" in bare:
        return "/start"
    # Peripheral device buttons: "🔌 Name [●]" → /alias
    try:
        bot_devs = list_devices_bot_buttons(lang="ru")
    except Exception:
        bot_devs = []
    if bot_devs:
        # strip trailing state marker [●]/○ ·]
        name_part = re.sub(r"\s*\[[^\]]*\]\s*$", "", t).strip()
        name_low = name_part.lower()
        bare_name = re.sub(
            r"[^\w\s\-а-яё]+",
            " ",
            name_low,
            flags=re.I,
        )
        bare_name = " ".join(bare_name.split())
        for bd in bot_devs:
            alias = str(bd.get("alias") or "").strip().lower()
            names = {
                str(bd.get("name") or "").strip().lower(),
                str(bd.get("name_en") or "").strip().lower(),
                str(bd.get("name_ru") or "").strip().lower(),
            }
            names.discard("")
            if not alias:
                continue
            if bare_name == alias or bare.endswith(alias) or bare.startswith(alias + " "):
                return f"/{alias}"
            for dname in names:
                if (
                    bare_name == dname
                    or bare_name.endswith(dname)
                    or dname in bare_name
                    or bare_name in dname
                ):
                    return f"/{alias}"
                icon = str(bd.get("icon") or "")
                if icon and icon in t and dname in low:
                    return f"/{alias}"
    return t


def tg_broadcast(
    text: str,
    *,
    silent: bool = False,
    debounce_key: str | None = None,
    notify_kind: str | None = None,
    text_by_lang: dict | None = None,
) -> int:
    """
    Send to configured chat_ids.
    notify_kind: policy|offline|safety|zone — filtered by per-chat prefs.
    text_by_lang: optional { "ru": "...", "en": "..." } overrides text per lang.
    """
    if debounce_key:
        now = time.time()
        with _tg_notify_lock:
            last = float(_tg_last_msg_sig.get(debounce_key) or 0)
            if now - last < 45.0:
                return 0
            _tg_last_msg_sig[debounce_key] = now
    n = 0
    for cid in _tg_target_chats():
        if notify_kind and not _tg_chat_wants(cid, notify_kind):
            continue
        prefs = _tg_get_chat_prefs(cid)
        lang = prefs.get("lang") or "ru"
        msg = text
        if text_by_lang and isinstance(text_by_lang, dict):
            msg = text_by_lang.get(lang) or text_by_lang.get("ru") or text_by_lang.get("en") or text
        # HTML status cards (<b>, <tg-emoji>) vs entity-based host emoji
        use_html = ("<b>" in msg) or ("<tg-emoji" in msg)
        use_icon = (not use_html) and (("📦  " in msg) or ("🖥" in msg))
        if tg_send_message(
            cid,
            msg,
            silent=silent,
            miner_host_emoji=use_icon,
            parse_mode="HTML" if use_html else None,
        ):
            n += 1
    return n


def _fmt_asic_offline_msg(err, lang: str = "ru") -> str:
    """Laconic ASIC offline line for Telegram."""
    s = str(err or "").strip()
    low = s.lower()
    en = str(lang or "ru").lower().startswith("en")
    if "timed out" in low or "timeout" in low or "incomplete json" in low:
        return "⚠️ ASIC offline · timeout" if en else "⚠️ ASIC offline · timeout"
    if "refused" in low or "reset" in low:
        return (
            "⚠️ ASIC offline · connection refused"
            if en
            else "⚠️ ASIC offline · нет соединения"
        )
    if "unreachable" in low or "no route" in low:
        return (
            "⚠️ ASIC offline · unreachable"
            if en
            else "⚠️ ASIC offline · недоступен"
        )
    if "name or service" in low or "nodename" in low or "resolve" in low:
        return (
            "⚠️ ASIC offline · host unresolved"
            if en
            else "⚠️ ASIC offline · хост не найден"
        )
    # JSON parse bugs / firmware quirks — not a true offline event
    if (
        "bad json" in low
        or "expecting" in low
        or "delimiter" in low
        or "json" in low
        and ("parse" in low or "decode" in low or "column" in low)
    ):
        return (
            "⚠️ ASIC response error · retry"
            if en
            else "⚠️ ASIC · ошибка ответа API (повтор)"
        )
    if s:
        brief = s.replace("live poll fail:", "").strip()
        if len(brief) > 60:
            brief = brief[:57] + "…"
        return f"⚠️ ASIC offline · {brief}"
    return "⚠️ ASIC offline"


def tg_note_live_poll_ok() -> None:
    """Any successful miner poll resets offline streak (no spam after blips)."""
    global _tg_offline_streak, _tg_offline_notified
    with _tg_notify_lock:
        _tg_offline_streak = 0
        _tg_offline_notified = False


def tg_note_live_poll_fail(err) -> None:
    """
    Count consecutive ASIC poll failures.
    Telegram only after notify_offline_streak in a row (default 3).
    One message per outage; resets when poll succeeds again.
    Per-chat notify_offline is applied in tg_broadcast.
    """
    global _tg_offline_streak, _tg_offline_notified
    with _tg_cfg_lock:
        if not _tg_cfg.get("enabled") or not _tg_cfg.get("bot_token"):
            return
        if not _tg_cfg.get("chat_ids"):
            return
        try:
            need = max(1, min(30, int(_tg_cfg.get("notify_offline_streak") or 3)))
        except (TypeError, ValueError):
            need = 3

    with _tg_notify_lock:
        _tg_offline_streak += 1
        streak = _tg_offline_streak
        already = _tg_offline_notified
        if streak < need or already:
            return
        _tg_offline_notified = True

    def _msg(lang: str) -> str:
        t = _fmt_asic_offline_msg(err, lang=lang)
        if need > 1:
            t = f"{t} ({streak}×)"
        return t

    tg_broadcast(
        _msg("ru"),
        debounce_key=None,
        notify_kind="offline",
        text_by_lang={"ru": _msg("ru"), "en": _msg("en")},
    )


def tg_on_policy_event(kind: str, msg: str, extra: dict | None = None) -> None:
    with _tg_cfg_lock:
        if not _tg_cfg.get("enabled") or not _tg_cfg.get("bot_token"):
            return
        if not _tg_cfg.get("chat_ids"):
            return

    msg_l = (msg or "").lower()
    kind = (kind or "info").lower()
    extra = extra or {}

    # ASIC offline handled by tg_note_live_poll_fail (streak) — skip here
    if "live poll fail" in msg_l:
        return

    if "safety" in msg_l or str(extra.get("source") or "").startswith("safety"):
        icon = "🛑" if kind in ("ok", "err", "warn") else "ℹ️"
        tg_broadcast(
            f"{icon} Safety\n{msg}",
            debounce_key="safety:" + msg[:40],
            notify_kind="safety",
            text_by_lang={
                "ru": f"{icon} Safety\n{msg}",
                "en": f"{icon} Safety\n{msg}",
            },
        )
        return

    if kind == "err" or "fail" in msg_l or str(msg or "").upper().startswith("FAIL "):
        # Humanize: FAIL working=suspend: can't access write cmd
        # → 🚫 Ошибка установки режима Suspend (custom emoji)
        emoji = _tg_ctrl_err_emoji_html()
        text_ru = f"{emoji} {_tg_fail_human_text(msg, 'ru')}"
        text_en = f"{emoji} {_tg_fail_human_text(msg, 'en')}"
        tg_broadcast(
            text_ru,
            debounce_key="err:" + (msg or "")[:50],
            notify_kind="events",
            text_by_lang={"ru": text_ru, "en": text_en},
        )
        return

    if kind == "ok" and (
        msg.startswith("AUTO ") or msg.startswith("APPLY ") or "fix working" in msg_l
    ):
        if "working=suspend" in msg_l or "enforce:suspend" in msg_l:
            tg_broadcast(
                f"⏸ Suspend\n{msg}",
                debounce_key="susp:" + msg[:40],
                notify_kind="zone",
                text_by_lang={
                    "ru": f"⏸ Suspend\n{msg}",
                    "en": f"⏸ Suspend\n{msg}",
                },
            )
            return
        if "working=resume" in msg_l:
            tg_broadcast(
                f"▶️ Resume\n{msg}",
                debounce_key="res:" + msg[:40],
                notify_kind="zone",
            )
            return
        src = str(extra.get("source") or "")
        if src in ("z0", "z1", "z2", "z3") or any(
            f" {z}" in msg or msg.startswith(f"AUTO {z}") for z in ("z0", "z1", "z2", "z3")
        ):
            tg_broadcast(
                f"📐 Zone\n{msg}",
                debounce_key="zone:" + msg[:50],
                notify_kind="zone",
            )
        else:
            tg_broadcast(
                f"✅ {msg}",
                debounce_key="pol:" + msg[:50],
                notify_kind="events",
            )


# Human titles for heat zones (UI header + Telegram)
ZONE_TITLES = {
    "z0": "Z0 · High Heat",
    "z1": "Z1 · Normal heat",
    "z2": "Z2 · Reduced heat",
    "z3": "Z3 · No heat",
    "critical": "Safety · Critical",
    "safety": "Safety · Critical",
}


def zone_title(zone_id) -> str:
    """z3 → 'Z3 · No heat'; safety sticky → full Safety title."""
    if zone_id is None or zone_id == "":
        return "—"
    k = str(zone_id).strip().lower()
    if k in ZONE_TITLES:
        return ZONE_TITLES[k]
    # allow already-pretty strings
    if "·" in str(zone_id) or " " in str(zone_id):
        return str(zone_id)
    return str(zone_id).upper()


def _tg_fmt_num(v, digits: int = 1, empty: str = "—") -> str:
    try:
        if v is None or v == "":
            return empty
        n = float(v)
        if not (n == n):  # NaN
            return empty
        if digits == 0:
            return str(int(round(n)))
        s = f"{n:.{digits}f}".rstrip("0").rstrip(".")
        return s if s else "0"
    except (TypeError, ValueError):
        return empty


def _tg_zone_emoji(zone_id, *, safety: bool = False) -> str:
    if safety:
        return "🛑"
    k = str(zone_id or "").strip().lower()
    return {
        "z0": "🔥",
        "z1": "🟢",
        "z2": "🔵",
        "z3": "🧊",
        "critical": "🛑",
    }.get(k, "📍")


def _tg_fmt_ts_eu(ts) -> str:
    """
    Policy event timestamps for Telegram:
      04.08.2026 11:32:27
    Accepts ISO (2026-08-04T11:32:27[.fff][Z]) or already-formatted strings.
    """
    if ts is None:
        return "—"
    s = str(ts).strip()
    if not s:
        return "—"
    # already DD.MM.YYYY …
    if re.match(r"^\d{2}\.\d{2}\.\d{4}\s+\d{2}:\d{2}", s):
        return s[:19] if len(s) >= 19 else s
    try:
        raw = s.replace("Z", "+00:00")
        # datetime.fromisoformat handles "2026-08-04T11:32:27" and with micros
        dt = datetime.fromisoformat(raw)
        # drop tz for display (local wall time as stored)
        if dt.tzinfo is not None:
            dt = dt.replace(tzinfo=None)
        return dt.strftime("%d.%m.%Y %H:%M:%S")
    except Exception:
        pass
    # fallback: 2026-08-04 11:32:27 or T-separated
    m = re.match(
        r"^(\d{4})-(\d{2})-(\d{2})[T\s](\d{2}):(\d{2}):(\d{2})", s
    )
    if m:
        y, mo, d, hh, mm, ss = m.groups()
        return f"{d}.{mo}.{y} {hh}:{mm}:{ss}"
    return s


def _tg_pretty_last_event(msg: str | None) -> str | None:
    if not msg:
        return None
    m = str(msg).strip()
    low = m.lower()
    if "live poll fail" in low or "timed out" in low or "timeout" in low:
        return "⚠️ ASIC offline · timeout"
    if "connection refused" in low:
        return "⚠️ ASIC offline · no connection"
    # Dry Run preview — keep short (full cmd list is noisy)
    if low.startswith("dry_run would"):
        # "DRY_RUN would z3: working=suspend, … · no write (Dry Run)"
        try:
            rest = m.split("would", 1)[1].strip()
            z = rest.split(":", 1)[0].strip().upper()
            body = rest.split(":", 1)[1] if ":" in rest else rest
            body = body.split("·")[0].strip()
            # first action only
            first = body.split(",")[0].strip()
            if "working=suspend" in first.lower() or "working=sleep" in first.lower():
                act = "Suspend"
            elif "working=resume" in first.lower():
                act = "Mining"
            else:
                act = first.replace("working=", "").replace("mode=", "mode ")
            return f"Dry Run · {z} → {act} (без записи)"
        except Exception:
            return "Dry Run · preview (без записи)"
    # APPLY / AUTO — not for Status card (noise); Action log keeps them
    if m.startswith("AUTO ") or m.startswith("APPLY "):
        return None
    if m.upper().startswith("FORCE_STOP"):
        return None
    # TG action log: "chat 123 · @user · Filtration ON" — Action log only
    if low.startswith("chat ") or " · chat " in low:
        return None
    if "filtration" in low or "фильтрац" in low or "насос" in low:
        return None
    # FAIL action=value: err — multi-line block via _tg_status_fail_lines
    if m.upper().startswith("FAIL "):
        return m
    return m


def _tg_ctrl_err_emoji_html() -> str:
    return (
        f'<tg-emoji emoji-id="{_TG_CTRL_ERR_EMOJI_ID}">'
        f"{_TG_CTRL_ERR_EMOJI_FB}</tg-emoji>"
    )


def _tg_fail_human_text(
    msg: str = "",
    lang: str = "ru",
    *,
    cmd: str | None = None,
    reply: str | None = None,
) -> str:
    """
    Map FAIL working=suspend: … → laconic human message.
    e.g. «Ошибка установки режима Suspend»
    """
    en = str(lang or "ru").lower().startswith("en")
    c = (cmd or "").strip()
    r = (reply or "").strip()
    if not c:
        m = str(msg or "").strip()
        if m.upper().startswith("FAIL "):
            m = m[5:].strip()
        if ":" in m:
            left, right = m.split(":", 1)
            c = left.strip()
            r = right.strip()
        else:
            c = m
    # Full blob for reply heuristics (raw API Msg)
    blob = f"{msg} {r} {c}".lower()
    # Whatsminer Code 45: write API locked (Tools/web may still work)
    if "can't access write" in blob or "cant access write" in blob:
        return (
            "Write API locked · cycle API password in WhatsMinerTool, set same in poolheat"
            if en
            else "API записи закрыт · смените API-пароль в WhatsMinerTool и укажите его в poolheat"
        )
    if "enc json load" in blob:
        return (
            "Wrong API password (miner cannot decrypt write)"
            if en
            else "Неверный API-пароль (майнер не расшифровал write)"
        )
    if "over max connect" in blob:
        return (
            "API token limit (over max connect) · wait ~30 min or reboot ASIC"
            if en
            else "Лимит токенов API (over max connect) · ждите ~30 мин или reboot ASIC"
        )
    action = ""
    value = ""
    if "=" in c:
        action, value = c.split("=", 1)
        action = action.strip().lower()
        value = value.strip().lower()
    else:
        action = c.lower()

    # working / Mining Control
    if action in ("working", "work", "mining", "working_mode"):
        if value in ("sleep", "suspend", "power_off", "off"):
            return (
                "Suspend mode set failed"
                if en
                else "Ошибка установки режима Suspend"
            )
        if value in ("resume", "power_on", "on", "mining"):
            return (
                "Resume mode set failed"
                if en
                else "Ошибка установки режима Resume"
            )
        return (
            f"Mining Control set failed ({value or '—'})"
            if en
            else f"Ошибка Mining Control ({value or '—'})"
        )
    if action == "mode":
        return (
            f"Power Mode set failed ({value or '—'})"
            if en
            else f"Ошибка Power Mode ({value or '—'})"
        )
    if action in ("power_limit", "set_power_limit", "adjust_power_limit"):
        return "Power Limit set failed" if en else "Ошибка Power Limit"
    if action == "power_pct":
        return "Power pct set failed" if en else "Ошибка Power pct"
    if action in ("reboot", "reboot_asic", "system_reboot"):
        return "Reboot command failed" if en else "Ошибка reboot"
    if action in ("restart", "restart_miner", "restart_btminer"):
        return "Restart miner failed" if en else "Ошибка restart miner"
    # fallback: short original without raw API dump
    if c:
        return f"Ошибка: {c}" if not en else f"Error: {c}"
    return "Ошибка управления" if not en else "Control error"


def _tg_status_fail_lines(
    msg: str,
    lang: str = "ru",
    *,
    cmd: str | None = None,
    reply: str | None = None,
) -> list[str]:
    """
    One line for Status / Miner:
      🚫 Ошибка установки режима Suspend
    """
    text = _tg_fail_human_text(msg, lang, cmd=cmd, reply=reply)
    return [f"{_tg_ctrl_err_emoji_html()} {text}"]


