    def _api_config_restore_post(self) -> None:
        """POST /api/config/restore — upload backup JSON and apply."""
        try:
            req = self._read_json_body()
            if not isinstance(req, dict):
                raise ValueError("JSON object required")
            # allow { backup: {...}, sections: [...] } or raw backup
            payload = req.get("backup") if isinstance(req.get("backup"), dict) else req
            sections = req.get("sections") if isinstance(req.get("sections"), list) else None
            if sections is not None:
                sections = [str(s) for s in sections]
            out = restore_config_backup(payload, sections=sections)
            self._json_response(200, out)
        except Exception as e:
            self._json_response(400, {"ok": False, "error": str(e)})

    def _api_live(self) -> None:
        """
        Live snapshot for the UI.

        Critical: never hold ``_cache_lock`` across ``fetch_live()`` (miner I/O
        can take many seconds). Concurrent clients share a single in-flight
        poll; if it is slow, return last-good cache quickly so the UI does not
        look like the service is down.
        """
        global _cache, _cache_ts, _live_fetch_future
        now = time.time()
        body: dict | None = None
        stale: dict | None = None
        stale_age = 0.0

        # Prefer disk snapshot from miner-poller process (keeps UI off :4028)
        disk_live = hydrate_live_from_disk(max_age_sec=LIVE_DISK_MAX_AGE_SEC)
        if isinstance(disk_live, dict) and disk_live.get("ok"):
            body = dict(disk_live)

        with _cache_lock:
            if body is None and (
                _cache is not None
                and (now - _cache_ts) < CACHE_TTL
                and _cache.get("ok")
            ):
                body = dict(_cache)
            elif body is None and _cache is not None:
                stale = dict(_cache)
                stale_age = max(0.0, now - float(_cache_ts or 0))

        if body is None:
            # Miner-poller owns ASIC polls when running — do not double-hit :4028
            if miner_poller_process_alive():
                disk2 = hydrate_live_from_disk(max_age_sec=LIVE_STALE_MAX_SEC)
                if isinstance(disk2, dict) and disk2.get("ok"):
                    body = dict(disk2)
                    body["stale"] = True
                    body["error"] = "waiting for miner-poller snapshot"
                elif stale and stale.get("ok") and stale_age <= LIVE_STALE_MAX_SEC:
                    body = dict(stale)
                    body["stale"] = True
                    body["stale_age_sec"] = round(stale_age, 1)
                else:
                    body = {
                        "ok": False,
                        "error": "miner-poller has no live snapshot yet",
                        "ts": datetime.now().isoformat(timespec="seconds"),
                        "host": f"{HOST_MINER}:{PORT_MINER}",
                    }
            else:
                # Poller not running — serve does not open ASIC TCP.
                if stale and stale.get("ok") and stale_age <= LIVE_STALE_MAX_SEC:
                    body = dict(stale)
                    body["stale"] = True
                    body["error"] = "miner-poller not running · last good snapshot"
                    body["stale_age_sec"] = round(stale_age, 1)
                else:
                    body = {
                        "ok": False,
                        "error": (
                            "miner-poller not running — start poolheat-miner-poller "
                            "(serve does not open ASIC TCP)"
                        ),
                        "ts": datetime.now().isoformat(timespec="seconds"),
                        "host": f"{HOST_MINER}:{PORT_MINER}",
                    }

        if not isinstance(body, dict):
            body = {
                "ok": False,
                "error": "no live data",
                "ts": datetime.now().isoformat(timespec="seconds"),
                "host": f"{HOST_MINER}:{PORT_MINER}",
            }

        # ASIC I/O (incl. liquid V3) is miner-poller only — serve never hits :4028/:4433 for live.
        with _state_lock:
            body["power_pct_cmd"] = _state.get("power_pct_cmd")
            body["power_limit_cmd"] = _state.get("power_limit_cmd")
            body["mode_cmd"] = _state.get("mode_cmd")
            body["work_cmd"] = _state.get("work_cmd")
            body["last_write"] = _state.get("last_write")
            # compact last miner response for UI error panel
            lwr = _state.get("last_write_result")
            if isinstance(lwr, dict):
                body["last_write_result"] = {
                    k: lwr.get(k)
                    for k in ("STATUS", "status", "Msg", "msg", "Code", "Description")
                    if k in lwr
                } or {"raw_keys": list(lwr.keys())[:12]}
            else:
                body["last_write_result"] = lwr
        # Resolved zone-map T_ctrl (supports Peripherals → Sensors aliases)
        try:
            t_val, t_sens = resolve_t_ctrl(body if isinstance(body, dict) else {})
            body["t_ctrl"] = t_val
            body["t_ctrl_sensor"] = t_sens
        except Exception:
            pass
        self._json_response(200 if body.get("ok") else 502, body)

    def _api_set(self) -> None:
        try:
            req = self._read_json_body()
            action = req.get("action") or req.get("cmd")
            value = req.get("value")
            password = req.get("password") or DEFAULT_API_PASSWORD
            result = apply_set(action, value, password)
            self._json_response(200, result)
        except Exception as e:
            # still expose last_write if recorded before raise
            with _state_lock:
                lw = _state.get("last_write")
            self._json_response(
                400,
                {
                    "ok": False,
                    "error": str(e),
                    "last_write": lw,
                },
            )

    def _api_history(self) -> None:
        """
        GET /api/history[?hours&max&chart&fmt]
        chart=dash|power|temps|all  ·  fmt=cols|objects
        Aliases: /api/history/power · /api/history/temps
        """
        parsed = urlparse(self.path)
        qs = parse_qs(parsed.query)
        path = parsed.path.rstrip("/") or "/"

        def one(key, default=None):
            v = qs.get(key, [default])[0]
            return v

        try:
            hours = one("hours")
            hours_f = float(hours) if hours not in (None, "") else None
            max_points = int(one("max", "2000") or 2000)
            since = one("since")
            until = one("until")
            chart = str(one("chart", "all") or "all").strip().lower()
            # path aliases
            if path.endswith("/history/power"):
                chart = "power"
            elif path.endswith("/history/temps"):
                chart = "temps"
            elif path.endswith("/history/dash"):
                chart = "dash"
            fmt = str(one("fmt", "objects") or "objects").strip().lower()
            if fmt in ("col", "column", "columnar", "columns"):
                fmt = "cols"
            if fmt not in ("cols", "objects"):
                fmt = "objects"

            now = time.time()
            max_points = max(10, min(20000, int(max_points)))
            q_since = float(since) if since not in (None, "") else None
            q_until = float(until) if until not in (None, "") else None
            if q_since is None and q_until is None:
                h_key = 24.0 if hours_f is None else float(hours_f)
                http_key = (
                    "h",
                    round(h_key, 3),
                    int(max_points),
                    chart,
                    fmt,
                )
            else:
                http_key = (
                    "r",
                    int((q_since or 0) // 60) * 60,
                    int((q_until or now) // 60) * 60,
                    int(max_points),
                    chart,
                    fmt,
                )
            # Warm path: pre-serialized JSON (skip dumps on ARM)
            with _history_http_cache_lock:
                hit = _history_http_cache.get(http_key)
                if (
                    hit
                    and (now - float(hit.get("ts") or 0)) < _HISTORY_HTTP_TTL_SEC
                    and isinstance(hit.get("data"), (bytes, bytearray))
                ):
                    data = hit["data"]
                    try:
                        self.send_response(200)
                        self.send_header(
                            "Content-Type", "application/json; charset=utf-8"
                        )
                        self.send_header("Content-Length", str(len(data)))
                        self.send_header("X-Poolheat-History-Cache", "HIT")
                        self.send_header("X-Poolheat-History-Chart", chart)
                        self.send_header("X-Poolheat-History-Fmt", fmt)
                        self.end_headers()
                        view = memoryview(data)
                        step = 65536
                        for off in range(0, len(data), step):
                            self.wfile.write(view[off : off + step])
                    except (
                        BrokenPipeError,
                        ConnectionResetError,
                        ConnectionAbortedError,
                    ):
                        pass
                    return

            points = query_history(
                hours=hours_f if q_since is None else None,
                since=q_since,
                until=q_until,
                max_points=max_points,
                chart=chart,
                use_cache=True,
            )
            with _hist_cfg_lock:
                cfg = dict(_hist_cfg)
            sensor_series: list = []
            if _history_want_sensors(chart):
                try:
                    sensor_series = history_sensor_series_meta(use_cache=True)
                except Exception:
                    sensor_series = []
            try:
                stats = history_stats(use_cache=True)
            except Exception:
                stats = {}
            body: dict = {
                "ok": True,
                "count": len(points),
                "chart": chart,
                "fmt": fmt,
                "config": cfg,
                "stats": stats,
                "sensor_series": sensor_series,
            }
            if fmt == "cols":
                keys, cols = _points_to_columnar(points)
                body["keys"] = keys
                body["cols"] = cols
                body["points"] = []  # keep key for old clients; empty when cols
            else:
                body["points"] = points
            data = json.dumps(body, ensure_ascii=False, default=str).encode(
                "utf-8"
            )
            with _history_http_cache_lock:
                if len(_history_http_cache) > 24:
                    _history_http_cache.clear()
                _history_http_cache[http_key] = {
                    "ts": time.time(),
                    "data": data,
                }
            try:
                self.send_response(200)
                self.send_header(
                    "Content-Type", "application/json; charset=utf-8"
                )
                self.send_header("Content-Length", str(len(data)))
                self.send_header("X-Poolheat-History-Cache", "MISS")
                self.send_header("X-Poolheat-History-Chart", chart)
                self.send_header("X-Poolheat-History-Fmt", fmt)
                self.end_headers()
                view = memoryview(data)
                step = 65536
                for off in range(0, len(data), step):
                    self.wfile.write(view[off : off + step])
            except (
                BrokenPipeError,
                ConnectionResetError,
                ConnectionAbortedError,
            ):
                pass
        except Exception as e:
            self._json_response(400, {"ok": False, "error": str(e)})

