    def _api_ewelink_devices_login(self) -> None:
        """
        POST {email, password, country_code?, region?, device_id?}
        → auto-matched eWeLink device + devicekey (no full inventory in UI).
        Optionally binds key onto poolheat device store id.
        """
        try:
            req = self._read_json_body() or {}
            if not isinstance(req, dict):
                raise ValueError("expected object")
            email = str(req.get("email") or "").strip()
            password = str(req.get("password") or "")
            store_id = str(req.get("device_id") or req.get("id") or "").strip()
            if (not password or password in ("••••", "****")) and store_id:
                cfg = _device_cfg_snapshot(store_id)
                if cfg and cfg.get("password"):
                    password = str(cfg.get("password"))
                if cfg and not email:
                    email = str(cfg.get("email") or "")
            if not email or not password:
                raise ValueError("email and password required")
            cc = str(req.get("country_code") or req.get("ewelink_country") or "+7")
            region = str(req.get("region") or req.get("ewelink_region") or "") or None
            want_did = str(req.get("ewelink_deviceid") or req.get("target_deviceid") or "").strip()
            want_ip = str(req.get("ip") or "").strip()
            try:
                from ewelink_lan import login_and_find_device  # type: ignore
            except ImportError:
                from .ewelink_lan import login_and_find_device  # type: ignore
            out = login_and_find_device(
                email,
                password,
                deviceid=want_did or None,
                ip=want_ip or None,
                country_code=cc,
                region=region,
            )
            # strip access token from response
            out.pop("at", None)
            n_dev = int(out.get("device_count") or len(out.get("devices") or []))
            # UI only needs the auto-matched device (no full inventory dump)
            match_raw = out.get("match") if isinstance(out.get("match"), dict) else None
            match = None
            if match_raw:
                match = {
                    "deviceid": match_raw.get("deviceid"),
                    "devicekey": match_raw.get("devicekey"),
                    "name": match_raw.get("name"),
                    "online": match_raw.get("online"),
                    "productModel": match_raw.get("productModel"),
                    "brandName": match_raw.get("brandName"),
                    "uiid": match_raw.get("uiid"),
                    "ip": match_raw.get("ip"),
                    "params": match_raw.get("params")
                    if isinstance(match_raw.get("params"), dict)
                    else None,
                }
            out = {
                "ok": True,
                "region": out.get("region"),
                "apikey": out.get("apikey"),
                "device_count": n_dev,
                "match": match,
            }
            # Always remember eWeLink cloud login for this country
            try:
                if email and password:
                    upsert_cloud_credential(
                        ecosystem="ewelink",
                        email=email,
                        password=password,
                        country=cc,
                        region=str(out.get("region") or ""),
                    )
            except Exception as ce:
                print(f"[ewelink] cred vault: {ce}", flush=True)
            if store_id and match and match.get("devicekey"):
                key = str(match.get("devicekey"))
                did_cloud = str(match.get("deviceid") or "")
                user_apikey = str(out.get("apikey") or "").strip()

                def _mut(d):
                    d["ewelink_devicekey"] = key
                    d["ewelink_mode"] = d.get("ewelink_mode") or "lan"
                    if did_cloud:
                        d["device_id"] = did_cloud  # cloud id is authoritative
                    if user_apikey:
                        d["ewelink_apikey"] = user_apikey
                    if email:
                        d["email"] = email
                    if password:
                        d["password"] = password
                    d["ewelink_region"] = out.get("region") or d.get("ewelink_region")
                    d["ewelink_country"] = cc
                    # optional: adopt cloud-reported LAN IP when form empty
                    if match.get("ip") and not str(d.get("ip") or "").strip():
                        d["ip"] = str(match.get("ip"))

                with _devices_cfg_lock:
                    devices = list(_devices_cfg.get("devices") or [])
                    for i, d in enumerate(devices):
                        if str(d.get("id") or "") == store_id:
                            nd = dict(d)
                            _mut(nd)
                            devices[i] = _strip_device_runtime(
                                _normalize_device(nd) or nd
                            )
                            _devices_cfg["devices"] = devices
                            break
                try:
                    _save_devices_cfg()
                except Exception as se:
                    print(f"[ewelink] save devicekey: {se}", flush=True)
                out["bound_device_id"] = store_id
                out["bound_devicekey"] = True
            self._json_response(200, out)
        except Exception as e:
            self._json_response(400, {"ok": False, "error": str(e)})

    def _api_tuya_devices_login(self) -> None:
        """
        POST {email, password, country?, region?, ecosystem?, device_id?,
              tuya_device_id?, ip?, slim?}

        Default slim=true (eWeLink-style): auto-match one cloud device by
        device_id / IP / single-device account — no full inventory in UI.
        Persists local_key into devices_config for Go poller.
        """
        try:
            req = self._read_json_body() or {}
            if not isinstance(req, dict):
                raise ValueError("expected object")
            email = str(req.get("email") or "").strip()
            password = str(req.get("password") or "")
            # allow empty password if device already has one stored
            store_id = str(req.get("device_id") or req.get("id") or "").strip()
            if (not password or password in ("••••", "****")) and store_id:
                cfg = _device_cfg_snapshot(store_id)
                if cfg and cfg.get("password"):
                    password = str(cfg.get("password"))
                if cfg and not email:
                    email = str(cfg.get("email") or "")
            if not email or not password:
                raise ValueError("email and password required")
            slim = req.get("slim")
            if slim is None:
                slim = True
            out = tuya_refresh_device_keys(
                email=email,
                password=password,
                country=str(req.get("country") or req.get("tuya_country") or "7"),
                region=str(req.get("region") or req.get("tuya_region") or "eu"),
                ecosystem=str(
                    req.get("ecosystem") or req.get("tuya_ecosystem") or "smartlife"
                ),
                device_store_id=store_id or None,
                target_device_id=str(
                    req.get("tuya_device_id")
                    or req.get("target_device_id")
                    or req.get("cloud_device_id")
                    or ""
                ).strip()
                or None,
                target_ip=str(req.get("ip") or req.get("tuya_ip") or "").strip() or None,
                slim=bool(slim),
            )
            # Remember cloud login like eWeLink
            try:
                if email and password:
                    upsert_cloud_credential(
                        ecosystem=str(
                            req.get("ecosystem")
                            or req.get("tuya_ecosystem")
                            or "smartlife"
                        ),
                        email=email,
                        password=password,
                        country=str(
                            req.get("country") or req.get("tuya_country") or "7"
                        ),
                        region=str(req.get("region") or req.get("tuya_region") or "eu"),
                    )
            except Exception as ce:
                print(f"[tuya] cred vault: {ce}", flush=True)
            self._json_response(200, out)
        except Exception as e:
            self._json_response(400, {"ok": False, "error": str(e)})

